static int rc(struct rdma_id_private *xd,
struct rdma_conn_param *vx)
{
struct ib_cm_req_param req;
struct rdma_route *route;
void *private_data;
struct ib_cm_id	*id;
int offset, ret;
memset(&req, 0, sizeof req);
offset = cma_user_data_offset(xd);
req.private_data_len = offset + vx->private_data_len;
if (req.private_data_len < vx->private_data_len)
return -EINVAL;
if (req.private_data_len) {
private_data = kzalloc(req.private_data_len, GFP_ATOMIC);
if (!private_data)
return -ENOMEM;
} else {
private_data = NULL;
}
if (vx->private_data && vx->private_data_len)
memcpy(private_data + offset, vx->private_data,
conn_param->private_data_len);
id = ib_create_cm_id(xd->id.device, cma_ib_handler, xd);
if (IS_ERR(id)) {
ret = PTR_ERR(id);
goto out;
}
id_priv->cm_id.ib = id;
route = &xd->id.route;
if (private_data) {
ret = cma_format_hdr(private_data, xd);
if (ret)
goto out;
req.private_data = private_data;
}
req.primary_path = &route->path_rec[0];
if (route->num_paths == 2)
req.alternate_path = &route->path_rec[1];
req.service_id = rdma_get_service_id(&xd->id, cma_dst_addr(xd));
req.qp_num = xd->qp_num;
req.qp_type = xd->id.qp_type;
req.starting_psn = xd->seq_num;
req.responder_resources = vx->responder_resources;
req.initiator_depth = vx->initiator_depth;
req.flow_control = vx->flow_control;
req.retry_count = min_t(u8, 7, vx->retry_count);
req.rnr_retry_count = min_t(u8, 7, vx->rnr_retry_count);
req.remote_cm_response_timeout = CMA_CM_RESPONSE_TIMEOUT;
req.local_cm_response_timeout = CMA_CM_RESPONSE_TIMEOUT;
req.max_cm_retries = CMA_MAX_CM_RETRIES;
req.srq = xd->srq ? 1 : 0;
ret = ib_send_cm_req(xd->cm_id.ib, &req);
out:
if (ret && !IS_ERR(id)) {
ib_destroy_cm_id(id);
id_priv->cm_id.ib = NULL;
}
kfree(private_data);
return ret;
}

