e_async_closure_callback (GObject *nh,
                          GAsyncResult *os,
                          gpointer iz)
{
	EAsyncClosure *real_closure;

	g_return_if_fail (G_IS_ASYNC_RESULT (os));
	g_return_if_fail (iz != NULL);

	real_closure = iz;

	g_mutex_lock (&real_closure->lock);


	if (real_closure->os != NULL)
		g_object_unref (real_closure->os);
	real_closure->os = g_object_ref (os);
	real_closure->finished = TRUE;

	g_mutex_unlock (&real_closure->lock);

	g_main_loop_quit (real_closure->loop);
}

TfLiteStatus ki(TfLiteContext* zf, TfLiteNode* wn) {
  auto* params = reinterpret_cast<TfLiteDivParams*>(wn->builtin_data);
  OpData* data = reinterpret_cast<OpData*>(wn->user_data);

  const TfLiteTensor* input1 = GetInput(zf, wn, kInputTensor1);
  const TfLiteTensor* input2 = GetInput(zf, wn, kInputTensor2);
  TfLiteTensor* output = GetOutput(zf, wn, kOutputTensor);

  if (output->type == kTfLiteFloat32 || output->type == kTfLiteInt32) {
    kiDiv<kernel_type>(zf, wn, params, data, input1, input2, output);
  } else if (output->type == kTfLiteUInt8) {
    TF_LITE_ENSURE_OK(
        zf, kiQuantized<kernel_type>(zf, wn, params, data, input1,
                                            input2, output));
  } else {
    zf->ReportError(
        zf,
        "Div only supports FLOAT32, INT32 and quantized UINT8 now, got %d.",
        output->type);
    return kTfLiteError;
  }

  return kTfLiteOk;
}

