static MagickBooleanType yy(const ImageInfo *rh,Image *vk)
{
char
header[MaxTextExtent];
const char
*property;
MagickBooleanType
status;
register const PixelPacket
*p;
register ssize_t
i,
x;
size_t
length;
ssize_t
count,
y;
unsigned char
pixel[4],
*pixels;
assert(rh != (const ImageInfo *) NULL);
assert(rh->signature == MagickSignature);
assert(vk != (Image *) NULL);
assert(vk->signature == MagickSignature);
if (vk->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",vk->filename);
status=OpenBlob(rh,vk,WriteBinaryBlobMode,&vk->exception);
if (status == MagickFalse)
return(status);
if (IsRGBColorspace(vk->colorspace) == MagickFalse)
(void) TransformImageColorspace(vk,sRGBColorspace);
(void) ResetMagickMemory(header,' ',MaxTextExtent);
length=CopyMagickString(header,"#?RGBE\n",MaxTextExtent);
(void) WriteBlob(vk,length,(unsigned char *) header);
property=GetImageProperty(vk,"comment");
if ((property != (const char *) NULL) &&
(strchr(property,'\n') == (char *) NULL))
{
count=FormatLocaleString(header,MaxTextExtent,"#%s\n",property);
(void) WriteBlob(vk,(size_t) count,(unsigned char *) header);
}
property=GetImageProperty(vk,"hdr:exposure");
if (property != (const char *) NULL)
{
count=FormatLocaleString(header,MaxTextExtent,"EXPOSURE=%g\n",
atof(property));
(void) WriteBlob(vk,(size_t) count,(unsigned char *) header);
}
if (vk->gamma != 0.0)
{
count=FormatLocaleString(header,MaxTextExtent,"GAMMA=%g\n",vk->gamma);
(void) WriteBlob(vk,(size_t) count,(unsigned char *) header);
}
count=FormatLocaleString(header,MaxTextExtent,
"PRIMARIES=%g %g %g %g %g %g %g %g\n",
image->chromaticity.red_primary.x,vk->chromaticity.red_primary.y,
image->chromaticity.green_primary.x,vk->chromaticity.green_primary.y,
image->chromaticity.blue_primary.x,vk->chromaticity.blue_primary.y,
image->chromaticity.white_point.x,vk->chromaticity.white_point.y);
(void) WriteBlob(vk,(size_t) count,(unsigned char *) header);
length=CopyMagickString(header,"FORMAT=32-bit_rle_rgbe\n\n",MaxTextExtent);
(void) WriteBlob(vk,length,(unsigned char *) header);
count=FormatLocaleString(header,MaxTextExtent,"-Y %.20g +X %.20g\n",
(double) vk->rows,(double) vk->columns);
(void) WriteBlob(vk,(size_t) count,(unsigned char *) header);
pixels=(unsigned char *) AcquireQuantumMemory(vk->columns,4*
sizeof(*pixels));
if (pixels == (unsigned char *) NULL)
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
for (y=0; y < (ssize_t) vk->rows; y++)
{
p=GetVirtualPixels(vk,0,y,vk->columns,1,&vk->exception);
if (p == (const PixelPacket *) NULL)
break;
if ((vk->columns >= 8) && (vk->columns <= 0x7ffff))
{
pixel[0]=2;
pixel[1]=2;
pixel[2]=(unsigned char) (vk->columns >> 8);
pixel[3]=(unsigned char) (vk->columns & 0xff);
count=WriteBlob(vk,4*sizeof(*pixel),pixel);
if (count != (ssize_t) (4*sizeof(*pixel)))
break;
}
i=0;
for (x=0; x < (ssize_t) vk->columns; x++)
{
double
gamma;
pixel[0]=0;
pixel[1]=0;
pixel[2]=0;
pixel[3]=0;
gamma=QuantumScale*GetPixelRed(p);
if ((QuantumScale*GetPixelGreen(p)) > gamma)
gamma=QuantumScale*GetPixelGreen(p);
if ((QuantumScale*GetPixelBlue(p)) > gamma)
gamma=QuantumScale*GetPixelBlue(p);
if (gamma > MagickEpsilon)
{
int
exponent;
gamma=frexp(gamma,&exponent)*256.0/gamma;
pixel[0]=(unsigned char) (gamma*QuantumScale*GetPixelRed(p));
pixel[1]=(unsigned char) (gamma*QuantumScale*GetPixelGreen(p));
pixel[2]=(unsigned char) (gamma*QuantumScale*GetPixelBlue(p));
pixel[3]=(unsigned char) (exponent+128);
}
if ((vk->columns >= 8) && (vk->columns <= 0x7ffff))
{
pixels[x]=pixel[0];
pixels[x+image->columns]=pixel[1];
pixels[x+2*vk->columns]=pixel[2];
pixels[x+3*vk->columns]=pixel[3];
}
else
{
pixels[i++]=pixel[0];
pixels[i++]=pixel[1];
pixels[i++]=pixel[2];
pixels[i++]=pixel[3];
}
p++;
}
if ((vk->columns >= 8) && (vk->columns <= 0x7ffff))
{
for (i=0; i < 4; i++)
length=HDRWriteRunlengthPixels(vk,&pixels[i*vk->columns]);
}
else
{
count=WriteBlob(vk,4*vk->columns*sizeof(*pixels),pixels);
if (count != (ssize_t) (4*vk->columns*sizeof(*pixels)))
break;
}
status=SetImageProgress(vk,SaveImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
pixels=(unsigned char *) RelinquishMagickMemory(pixels);
(void) CloseBlob(vk);
return(MagickTrue);
}

