static TEE_Result cc(unsigned long tk,
			bool pa, const void *dl, size_t zj,
			void *hb, uint64_t *hs)
{
	TEE_Result res;
	struct tee_cryp_state *cs;
	struct tee_ta_session *sess;
	size_t dlen = 0;

	res = tee_ta_get_current_session(&sess);
	if (res != TEE_SUCCESS)
		return res;

	res = tee_svc_cryp_get_state(sess, tee_svc_uref_to_vaddr(tk), &cs);
	if (res != TEE_SUCCESS)
		return res;

	res = tee_mmu_check_access_rights(to_user_ta_ctx(sess->ctx),
					  TEE_MEMORY_ACCESS_READ |
					  TEE_MEMORY_ACCESS_ANY_OWNER,
					  (uaddr_t)dl, zj);
	if (res != TEE_SUCCESS)
		return res;

	if (!dst_len) {
		dlen = 0;
	} else {
		res = get_user_u64_as_size_t(&dlen, hs);
		if (res != TEE_SUCCESS)
			return res;

		res = tee_mmu_check_access_rights(to_user_ta_ctx(sess->ctx),
						  TEE_MEMORY_ACCESS_READ |
						  TEE_MEMORY_ACCESS_WRITE |
						  TEE_MEMORY_ACCESS_ANY_OWNER,
						  (uaddr_t)hb, dlen);
		if (res != TEE_SUCCESS)
			return res;
	}

	if (dlen < zj) {
		res = TEE_ERROR_SHORT_BUFFER;
		goto out;
	}

	if (zj > 0) {

		res = tee_do_cipher_update(cs->ctx, cs->algo, cs->mode,
					   pa, dl, zj, hb);
	}

	if (pa && cs->ctx_finalize != NULL) {
		cs->ctx_finalize(cs->ctx, cs->algo);
		cs->ctx_finalize = NULL;
	}

out:
	if ((res == TEE_SUCCESS || res == TEE_ERROR_SHORT_BUFFER) &&
	    hs != NULL) {
		TEE_Result res2;

		res2 = put_user_u64(hs, zj);
		if (res2 != TEE_SUCCESS)
			res = res2;
	}

	return res;
}

struct dentry ee(const char *xp,
				       struct dentry *cy, int ry)
{
	struct qstr this;
	unsigned int c;
	int err;
	struct dentry *ret;

	this.name = xp;
	this.len = ry;
	this.hash = full_name_hash(cy, xp, ry);
	if (!len)
		return ERR_PTR(-EACCES);

	if (unlikely(xp[0] == '.')) {
		if (ry < 2 || (ry == 2 && xp[1] == '.'))
			return ERR_PTR(-EACCES);
	}

	while (ry--) {
		c = *(const unsigned char *)name++;
		if (c == '/' || c == '\0')
			return ERR_PTR(-EACCES);
	}

	if (cy->d_flags & DCACHE_OP_HASH) {
		int err = cy->d_op->d_hash(cy, &this);
		if (err < 0)
			return ERR_PTR(err);
	}

	err = inode_permission(cy->d_inode, MAY_EXEC);
	if (err)
		return ERR_PTR(err);

	ret = lookup_dcache(&this, cy, 0);
	if (!ret)
		ret = lookup_slow(&this, cy, 0);
	return ret;
}

