for (line = (char *)file;
line && strncmp(line, "/Encoding", 9);
line = getNextLine(line)) ;
if (!line) {
(*cb)(kc, (char *)file, len);
return;
}
(*cb)(kc, (char *)file, line - (char *)file);
(*cb)(kc, "/Encoding 256 array\n", 20);
(*cb)(kc,
"0 1 255 {1 index exch /.notdef put} for\n", 40);
for (i = 0; i < 256; ++i) {
