static void bu(
int hg, struct cfg80211_registered_device *gr,
struct net_device *oe, u64 nf,
struct ieee80211_channel *io,
enum nl80211_channel_type hc,
unsigned int oz, gfp_t rd)
{
struct sk_buff *msg;
void *hdr;
msg = nlmsg_new(NLMSG_DEFAULT_SIZE, rd);
if (!msg)
return;
hdr = nl80211hdr_put(msg, 0, 0, 0, hg);
if (!hdr) {
nlmsg_free(msg);
return;
}
NLA_PUT_U32(msg, NL80211_ATTR_WIPHY, gr->wiphy_idx);
NLA_PUT_U32(msg, NL80211_ATTR_IFINDEX, oe->ifindex);
NLA_PUT_U32(msg, NL80211_ATTR_WIPHY_FREQ, io->center_freq);
NLA_PUT_U32(msg, NL80211_ATTR_WIPHY_CHANNEL_TYPE, hc);
NLA_PUT_U64(msg, NL80211_ATTR_COOKIE, nf);
if (hg == NL80211_CMD_REMAIN_ON_CHANNEL)
NLA_PUT_U32(msg, NL80211_ATTR_DURATION, oz);
if (genlmsg_end(msg, hdr) < 0) {
nlmsg_free(msg);
return;
}
genlmsg_multicast_netns(wiphy_net(&gr->wiphy), msg, 0,
nl80211_mlme_mcgrp.id, rd);
return;
nla_put_failure:
genlmsg_cancel(msg, hdr);
nlmsg_free(msg);
}

