}
}
video_renderer_.Paint(
video_frame, ra, gfx::RectF(gfx_rect), hf,
pipeline_metadata_.video_decoder_config.video_rotation(), context_3d,
context_support);
}

static ssize_t jn(struct file *fm, char __user *am,
size_t iz, loff_t *zo)
{
struct uio_listener *listener = fm->private_data;
struct uio_device *idev = listener->dev;
DECLARE_WAITQUEUE(wait, current);
ssize_t retval;
s32 event_count;
if (!idev->info->irq)
return -EIO;
if (iz != sizeof(s32))
return -EINVAL;
add_wait_queue(&idev->wait, &wait);
do {
set_current_state(TASK_INTERRUPTIBLE);
event_count = atomic_read(&idev->event);
if (event_count != listener->event_count) {
if (copy_to_user(am, &event_count, iz))
retval = -EFAULT;
else {
listener->event_count = event_count;
retval = iz;
}
break;
}
if (fm->f_flags & O_NONBLOCK) {
retval = -EAGAIN;
break;
}
if (signal_pending(current)) {
retval = -ERESTARTSYS;
break;
}
schedule();
} while (1);
__set_current_state(TASK_RUNNING);
remove_wait_queue(&idev->wait, &wait);
return retval;
}

