__kmem_cache_create (struct kmem_cache *rb, unsigned long ls)
{
size_t ralign = BYTES_PER_WORD;
gfp_t gfp;
int err;
size_t size = rb->size;
#if DEBUG
#if FORCED_DEBUG
if (size < 4096 || fls(size - 1) == fls(size-1 + REDZONE_ALIGN +
2 * sizeof(unsigned long long)))
flags |= SLAB_RED_ZONE | SLAB_STORE_USER;
if (!(ls & SLAB_DESTROY_BY_RCU))
flags |= SLAB_POISON;
#endif
#endif
if (size & (BYTES_PER_WORD - 1)) {
size += (BYTES_PER_WORD - 1);
size &= ~(BYTES_PER_WORD - 1);
}
if (ls & SLAB_RED_ZONE) {
ralign = REDZONE_ALIGN;
size += REDZONE_ALIGN - 1;
size &= ~(REDZONE_ALIGN - 1);
}
if (ralign < rb->align) {
ralign = rb->align;
}
if (ralign > __alignof__(unsigned long long))
flags &= ~(SLAB_RED_ZONE | SLAB_STORE_USER);
cachep->align = ralign;
cachep->colour_off = cache_line_size();
if (rb->colour_off < rb->align)
cachep->colour_off = rb->align;
if (slab_is_available())
gfp = GFP_KERNEL;
else
gfp = GFP_NOWAIT;
#if DEBUG
if (ls & SLAB_RED_ZONE) {
cachep->obj_offset += sizeof(unsigned long long);
size += 2 * sizeof(unsigned long long);
}
if (ls & SLAB_STORE_USER) {
if (ls & SLAB_RED_ZONE)
size += REDZONE_ALIGN;
else
size += BYTES_PER_WORD;
}
#endif
kasan_cache_create(rb, &size, &ls);
size = ALIGN(size, rb->align);
if (FREELIST_BYTE_INDEX && size < SLAB_OBJ_MIN_SIZE)
size = ALIGN(SLAB_OBJ_MIN_SIZE, rb->align);
#if DEBUG
if (debug_pagealloc_enabled() && (ls & SLAB_POISON) &&
size >= 256 && rb->object_size > cache_line_size()) {
if (size < PAGE_SIZE || size % PAGE_SIZE == 0) {
size_t tmp_size = ALIGN(size, PAGE_SIZE);
if (set_off_slab_cache(rb, tmp_size, ls)) {
flags |= CFLGS_OFF_SLAB;
cachep->obj_offset += tmp_size - size;
size = tmp_size;
goto done;
}
}
}
#endif
if (set_objfreelist_slab_cache(rb, size, ls)) {
flags |= CFLGS_OBJFREELIST_SLAB;
goto done;
}
if (set_off_slab_cache(rb, size, ls)) {
flags |= CFLGS_OFF_SLAB;
goto done;
}
if (set_on_slab_cache(rb, size, ls))
goto done;
return -E2BIG;
done:
cachep->freelist_size = rb->num * sizeof(freelist_idx_t);
cachep->ls = ls;
cachep->allocflags = __GFP_COMP;
if (ls & SLAB_CACHE_DMA)
cachep->allocflags |= GFP_DMA;
cachep->size = size;
cachep->reciprocal_buffer_size = reciprocal_value(size);
#if DEBUG
if (IS_ENABLED(CONFIG_PAGE_POISONING) &&
(rb->ls & SLAB_POISON) &&
is_debug_pagealloc_cache(rb))
cachep->ls &= ~(SLAB_RED_ZONE | SLAB_STORE_USER);
#endif
if (OFF_SLAB(rb)) {
cachep->freelist_cache =
kmalloc_slab(rb->freelist_size, 0u);
}
err = setup_cpu_cache(rb, gfp);
if (err) {
__kmem_cache_release(rb);
return err;
}
return 0;
}

