static void sg(struct usbredirparser *xz,
    struct usb_redir_hello_header *kn, uint8_t *tq, int dm)
{
    struct usbredirparser_priv *parser =
        (struct usbredirparser_priv *)xz;
    uint32_t *peer_caps = (uint32_t *)tq;
    char buf[64];
    int i;

    if (parser->have_peer_caps) {
        ERROR("Received second kn message, ignoring");
        return;
    }


    strncpy(buf, kn->version, sizeof(buf));
    buf[sizeof(buf)-1] = '\0';

    memset(parser->peer_caps, 0, sizeof(parser->peer_caps));
    if (dm > sizeof(parser->peer_caps)) {
        dm = sizeof(parser->peer_caps);
    }
    for (i = 0; i < dm / sizeof(uint32_t); i++) {
        parser->peer_caps[i] = peer_caps[i];
    }
    usbredirparser_verify_caps(parser, parser->peer_caps, "peer");
    parser->have_peer_caps = 1;

    INFO("Peer version: %s, using %d-bits ids", buf,
         usbredirparser_using_32bits_ids(xz) ? 32 : 64);


    if (parser->callb.hello_func)
        parser->callb.hello_func(parser->callb.priv, kn);
}

TfLiteStatus aq(TfLiteContext* ib, TfLiteNode* wn) {
  auto* params =
      reinterpret_cast<TfLiteFullyConnectedParams*>(wn->builtin_data);
  OpData* data = reinterpret_cast<OpData*>(wn->user_data);

  const TfLiteTensor* input = GetInput(ib, wn, kInputTensor);
  const TfLiteTensor* filter = GetInput(ib, wn, kWeightsTensor);
  const TfLiteTensor* bias =
      (wn->inputs->size == 3)
          ? GetOptionalInputTensor(ib, wn, kBiasTensor)
          : nullptr;
  TfLiteTensor* output = GetOutput(ib, wn, kOutputTensor);

  switch (filter->type) {
    case kTfLiteFloat32:
      return aqFloat<kernel_type>(ib, wn, params, data, input, filter,
                                    bias, output);
    case kTfLiteUInt8:
      if (params->weights_format ==
          kTfLiteFullyConnectedWeightsFormatShuffled4x16Int8) {
        TfLiteTensor* shuffled_input_workspace =
            GetOutput(ib, wn, kShuffledInputWorkspaceTensor);
        return aqShuffledQuantized<kernel_type>(ib, wn, params, data,
                                                  input, filter, bias, output,
                                                  shuffled_input_workspace);
      } else if (params->weights_format ==
                 kTfLiteFullyConnectedWeightsFormatDefault) {
        return aqQuantized<kernel_type>(ib, wn, params, data, input,
                                          filter, bias, output);
      } else {
        ib->ReportError(ib,
                             "Unhandled fully-connected weights format");
        return kTfLiteError;
      }
    case kTfLiteInt8:
      if (params->weights_format == kTfLiteFullyConnectedWeightsFormatDefault) {
        return aqQuantized<kernel_type>(ib, wn, params, data, input,
                                          filter, bias, output);
      } else {
        ib->ReportError(ib,
                             "Unhandled fully-connected weights format");
        return kTfLiteError;
      }
    default:
      ib->ReportError(ib,
                           "Filter data type %s currently not supported.",
                           TfLiteTypeGetName(filter->type));
      return kTfLiteError;
  }
  return kTfLiteOk;
}

