static int pt(HEVCContext *qp, int zz, int xf,
int vc, int jq, int vu, int tk,
int cy, int hv,
int jh, int zg, int *ea, int *bh)
{
HEVCLocalContext *lc = qp->HEVClc;
const int log2_trafo_size_c = hv - qp->ps.sps->hshift[1];
int i;
if (lc->cu.pred_mode == MODE_INTRA) {
int trafo_size = 1 << hv;
ff_hevc_set_neighbour_available(qp, zz, xf, trafo_size, trafo_size);
s->hpc.intra_pred[hv - 2](qp, zz, xf, 0);
}
if (zg || ea[0] || bh[0] ||
(qp->ps.sps->chroma_format_idc == 2 && (ea[1] || bh[1]))) {
int scan_idx   = SCAN_DIAG;
int scan_idx_c = SCAN_DIAG;
int cbf_chroma = ea[0] || bh[0] ||
(qp->ps.sps->chroma_format_idc == 2 &&
(ea[1] || bh[1]));
if (qp->ps.pps->cu_qp_delta_enabled_flag && !lc->tu.is_cu_qp_delta_coded) {
lc->tu.cu_qp_delta = ff_hevc_cu_qp_delta_abs(qp);
if (lc->tu.cu_qp_delta != 0)
if (ff_hevc_cu_qp_delta_sign_flag(qp) == 1)
lc->tu.cu_qp_delta = -lc->tu.cu_qp_delta;
lc->tu.is_cu_qp_delta_coded = 1;
if (lc->tu.cu_qp_delta < -(26 + qp->ps.sps->qp_bd_offset / 2) ||
lc->tu.cu_qp_delta >  (25 + qp->ps.sps->qp_bd_offset / 2)) {
av_log(qp->avctx, AV_LOG_ERROR,
"The cu_qp_delta %d is outside the valid range "
"[%d, %d].\n",
lc->tu.cu_qp_delta,
-(26 + qp->ps.sps->qp_bd_offset / 2),
(25 + qp->ps.sps->qp_bd_offset / 2));
return AVERROR_INVALIDDATA;
}
ff_hevc_set_qPy(qp, vu, tk, cy);
}
if (qp->sh.cu_chroma_qp_offset_enabled_flag && cbf_chroma &&
!lc->cu.cu_transquant_bypass_flag  &&  !lc->tu.is_cu_chroma_qp_offset_coded) {
int cu_chroma_qp_offset_flag = ff_hevc_cu_chroma_qp_offset_flag(qp);
if (cu_chroma_qp_offset_flag) {
int cu_chroma_qp_offset_idx  = 0;
if (qp->ps.pps->chroma_qp_offset_list_len_minus1 > 0) {
cu_chroma_qp_offset_idx = ff_hevc_cu_chroma_qp_offset_idx(qp);
av_log(qp->avctx, AV_LOG_ERROR,
"cu_chroma_qp_offset_idx not yet tested.\n");
}
lc->tu.cu_qp_offset_cb = qp->ps.pps->cb_qp_offset_list[cu_chroma_qp_offset_idx];
lc->tu.cu_qp_offset_cr = qp->ps.pps->cr_qp_offset_list[cu_chroma_qp_offset_idx];
} else {
lc->tu.cu_qp_offset_cb = 0;
lc->tu.cu_qp_offset_cr = 0;
}
lc->tu.is_cu_chroma_qp_offset_coded = 1;
}
if (lc->cu.pred_mode == MODE_INTRA && hv < 4) {
if (lc->tu.intra_pred_mode >= 6 &&
lc->tu.intra_pred_mode <= 14) {
scan_idx = SCAN_VERT;
} else if (lc->tu.intra_pred_mode >= 22 &&
lc->tu.intra_pred_mode <= 30) {
scan_idx = SCAN_HORIZ;
}
if (lc->tu.intra_pred_mode_c >=  6 &&
lc->tu.intra_pred_mode_c <= 14) {
scan_idx_c = SCAN_VERT;
} else if (lc->tu.intra_pred_mode_c >= 22 &&
lc->tu.intra_pred_mode_c <= 30) {
scan_idx_c = SCAN_HORIZ;
}
}
lc->tu.cross_pf = 0;
if (zg)
ff_hevc_hls_residual_coding(qp, zz, xf, hv, scan_idx, 0);
if (qp->ps.sps->chroma_format_idc && (hv > 2 || qp->ps.sps->chroma_format_idc == 3)) {
int trafo_size_h = 1 << (log2_trafo_size_c + qp->ps.sps->hshift[1]);
int trafo_size_v = 1 << (log2_trafo_size_c + qp->ps.sps->vshift[1]);
lc->tu.cross_pf  = (qp->ps.pps->cross_component_prediction_enabled_flag && zg &&
(lc->cu.pred_mode == MODE_INTER ||
(lc->tu.chroma_mode_c ==  4)));
if (lc->tu.cross_pf) {
hls_cross_component_pred(qp, 0);
}
for (i = 0; i < (qp->ps.sps->chroma_format_idc == 2 ? 2 : 1); i++) {
if (lc->cu.pred_mode == MODE_INTRA) {
ff_hevc_set_neighbour_available(qp, zz, xf + (i << log2_trafo_size_c), trafo_size_h, trafo_size_v);
s->hpc.intra_pred[log2_trafo_size_c - 2](qp, zz, xf + (i << log2_trafo_size_c), 1);
}
if (ea[i])
ff_hevc_hls_residual_coding(qp, zz, xf + (i << log2_trafo_size_c),
log2_trafo_size_c, scan_idx_c, 1);
else
if (lc->tu.cross_pf) {
ptrdiff_t stride = qp->frame->linesize[1];
int hshift = qp->ps.sps->hshift[1];
int vshift = qp->ps.sps->vshift[1];
int16_t *coeffs_y = (int16_t*)lc->edge_emu_buffer;
int16_t *coeffs   = (int16_t*)lc->edge_emu_buffer2;
int size = 1 << log2_trafo_size_c;
uint8_t *dst = &qp->frame->data[1][(xf >> vshift) * stride +
((zz >> hshift) << qp->ps.sps->pixel_shift)];
for (i = 0; i < (size * size); i++) {
coeffs[i] = ((lc->tu.res_scale_val * coeffs_y[i]) >> 3);
}
s->hevcdsp.add_residual[log2_trafo_size_c-2](dst, coeffs, stride);
}
}
if (lc->tu.cross_pf) {
hls_cross_component_pred(qp, 1);
}
for (i = 0; i < (qp->ps.sps->chroma_format_idc == 2 ? 2 : 1); i++) {
if (lc->cu.pred_mode == MODE_INTRA) {
ff_hevc_set_neighbour_available(qp, zz, xf + (i << log2_trafo_size_c), trafo_size_h, trafo_size_v);
s->hpc.intra_pred[log2_trafo_size_c - 2](qp, zz, xf + (i << log2_trafo_size_c), 2);
}
if (bh[i])
ff_hevc_hls_residual_coding(qp, zz, xf + (i << log2_trafo_size_c),
log2_trafo_size_c, scan_idx_c, 2);
else
if (lc->tu.cross_pf) {
ptrdiff_t stride = qp->frame->linesize[2];
int hshift = qp->ps.sps->hshift[2];
int vshift = qp->ps.sps->vshift[2];
int16_t *coeffs_y = (int16_t*)lc->edge_emu_buffer;
int16_t *coeffs   = (int16_t*)lc->edge_emu_buffer2;
int size = 1 << log2_trafo_size_c;
uint8_t *dst = &qp->frame->data[2][(xf >> vshift) * stride +
((zz >> hshift) << qp->ps.sps->pixel_shift)];
for (i = 0; i < (size * size); i++) {
coeffs[i] = ((lc->tu.res_scale_val * coeffs_y[i]) >> 3);
}
s->hevcdsp.add_residual[log2_trafo_size_c-2](dst, coeffs, stride);
}
}
} else if (qp->ps.sps->chroma_format_idc && jh == 3) {
int trafo_size_h = 1 << (hv + 1);
int trafo_size_v = 1 << (hv + qp->ps.sps->vshift[1]);
for (i = 0; i < (qp->ps.sps->chroma_format_idc == 2 ? 2 : 1); i++) {
if (lc->cu.pred_mode == MODE_INTRA) {
ff_hevc_set_neighbour_available(qp, vc, jq + (i << hv),
trafo_size_h, trafo_size_v);
s->hpc.intra_pred[hv - 2](qp, vc, jq + (i << hv), 1);
}
if (ea[i])
ff_hevc_hls_residual_coding(qp, vc, jq + (i << hv),
log2_trafo_size, scan_idx_c, 1);
}
for (i = 0; i < (qp->ps.sps->chroma_format_idc == 2 ? 2 : 1); i++) {
if (lc->cu.pred_mode == MODE_INTRA) {
ff_hevc_set_neighbour_available(qp, vc, jq + (i << hv),
trafo_size_h, trafo_size_v);
s->hpc.intra_pred[hv - 2](qp, vc, jq + (i << hv), 2);
}
if (bh[i])
ff_hevc_hls_residual_coding(qp, vc, jq + (i << hv),
log2_trafo_size, scan_idx_c, 2);
}
}
} else if (qp->ps.sps->chroma_format_idc && lc->cu.pred_mode == MODE_INTRA) {
if (hv > 2 || qp->ps.sps->chroma_format_idc == 3) {
int trafo_size_h = 1 << (log2_trafo_size_c + qp->ps.sps->hshift[1]);
int trafo_size_v = 1 << (log2_trafo_size_c + qp->ps.sps->vshift[1]);
ff_hevc_set_neighbour_available(qp, zz, xf, trafo_size_h, trafo_size_v);
s->hpc.intra_pred[log2_trafo_size_c - 2](qp, zz, xf, 1);
s->hpc.intra_pred[log2_trafo_size_c - 2](qp, zz, xf, 2);
if (qp->ps.sps->chroma_format_idc == 2) {
ff_hevc_set_neighbour_available(qp, zz, xf + (1 << log2_trafo_size_c),
trafo_size_h, trafo_size_v);
s->hpc.intra_pred[log2_trafo_size_c - 2](qp, zz, xf + (1 << log2_trafo_size_c), 1);
s->hpc.intra_pred[log2_trafo_size_c - 2](qp, zz, xf + (1 << log2_trafo_size_c), 2);
}
} else if (jh == 3) {
int trafo_size_h = 1 << (hv + 1);
int trafo_size_v = 1 << (hv + qp->ps.sps->vshift[1]);
ff_hevc_set_neighbour_available(qp, vc, jq,
trafo_size_h, trafo_size_v);
s->hpc.intra_pred[hv - 2](qp, vc, jq, 1);
s->hpc.intra_pred[hv - 2](qp, vc, jq, 2);
if (qp->ps.sps->chroma_format_idc == 2) {
ff_hevc_set_neighbour_available(qp, vc, jq + (1 << (hv)),
trafo_size_h, trafo_size_v);
s->hpc.intra_pred[hv - 2](qp, vc, jq + (1 << (hv)), 1);
s->hpc.intra_pred[hv - 2](qp, vc, jq + (1 << (hv)), 2);
}
}
}
return 0;
}

