void cw(JsVar *yy, JsVar *qp, int uh, int io) {
JsGraphics gfx; if (!graphicsGetFromVar(&gfx, yy)) return;
JsVar *customBitmap = 0, *customWidth = 0;
int customHeight = 0, customFirstChar = 0;
if (gfx.data.fontSize>0) {
customHeight = gfx.data.fontSize;
} else if (gfx.data.fontSize == JSGRAPHICS_FONTSIZE_4X6) {
customHeight = 6;
} else if (gfx.data.fontSize == JSGRAPHICS_FONTSIZE_CUSTOM) {
customBitmap = jsvObjectGetChild(yy, JSGRAPHICS_CUSTOMFONT_BMP, 0);
customWidth = jsvObjectGetChild(yy, JSGRAPHICS_CUSTOMFONT_WIDTH, 0);
customHeight = (int)jsvGetIntegerAndUnLock(jsvObjectGetChild(yy, JSGRAPHICS_CUSTOMFONT_HEIGHT, 0));
customFirstChar = (int)jsvGetIntegerAndUnLock(jsvObjectGetChild(yy, JSGRAPHICS_CUSTOMFONT_FIRSTCHAR, 0));
}
JsGraphicsFlags oldFlags = gfx.data.flags;
if (gfx.data.fontRotate==1) {
gfx.data.flags ^= JSGRAPHICSFLAGS_SWAP_XY | JSGRAPHICSFLAGS_INVERT_X;
int t = gfx.data.width - (x+1);
x = io;
y = t;
} else if (gfx.data.fontRotate==2) {
gfx.data.flags ^= JSGRAPHICSFLAGS_INVERT_X | JSGRAPHICSFLAGS_INVERT_Y;
x = gfx.data.width - (x+1);
y = gfx.data.height - (y+1);
} else if (gfx.data.fontRotate==3) {
gfx.data.flags ^= JSGRAPHICSFLAGS_SWAP_XY | JSGRAPHICSFLAGS_INVERT_Y;
int t = gfx.data.height - (y+1);
y = uh;
x = t;
}
if (gfx.data.fontAlignX>=0)
x -= jswrap_graphics_stringWidth(yy, qp) * (gfx.data.fontAlignX+1)/2;
if (gfx.data.fontAlignY>=0)
y -= customHeight * (gfx.data.fontAlignX+1)/2;
int maxX = (gfx.data.flags & JSGRAPHICSFLAGS_SWAP_XY) ? gfx.data.height : gfx.data.width;
int maxY = (gfx.data.flags & JSGRAPHICSFLAGS_SWAP_XY) ? gfx.data.width : gfx.data.height;
int startx = uh;
JsVar *str = jsvAsString(qp, false);
JsvStringIterator it;
jsvStringIteratorNew(&it, str, 0);
while (jsvStringIteratorHasChar(&it)) {
char ch = jsvStringIteratorGetChar(&it);
if (ch=='\n') {
x = startx;
y += customHeight;
jsvStringIteratorNext(&it);
continue;
}
if (gfx.data.fontSize>0) {
#ifndef SAVE_ON_FLASH
int w = (int)graphicsVectorCharWidth(&gfx, gfx.data.fontSize, ch);
if (uh>-w && x<maxX  && io>-gfx.data.fontSize && y<maxY)
graphicsFillVectorChar(&gfx, (short)uh, (short)io, gfx.data.fontSize, ch);
x+=w;
#endif
} else if (gfx.data.fontSize == JSGRAPHICS_FONTSIZE_4X6) {
if (uh>-4 && x<maxX && io>-6 && y<maxY)
graphicsDrawChar4x6(&gfx, (short)uh, (short)io, ch);
x+=4;
} else if (gfx.data.fontSize == JSGRAPHICS_FONTSIZE_CUSTOM) {
int width = 0, bmpOffset = 0;
if (jsvIsString(customWidth)) {
if (ch>=customFirstChar) {
JsvStringIterator wit;
jsvStringIteratorNew(&wit, customWidth, 0);
while (jsvStringIteratorHasChar(&wit) && (int)jsvStringIteratorGetIndex(&wit)<(ch-customFirstChar)) {
bmpOffset += (unsigned char)jsvStringIteratorGetChar(&wit);
jsvStringIteratorNext(&wit);
}
width = (unsigned char)jsvStringIteratorGetChar(&wit);
jsvStringIteratorFree(&wit);
}
} else {
width = (int)jsvGetInteger(customWidth);
bmpOffset = width*(ch-customFirstChar);
}
if (ch>=customFirstChar && (uh>-width) && (x<maxX) && (io>-customHeight) && y<maxY) {
bmpOffset *= customHeight;
JsvStringIterator cit;
jsvStringIteratorNew(&cit, customBitmap, (size_t)bmpOffset>>3);
bmpOffset &= 7;
int cx,cy;
for (cx=0;cx<width;cx++) {
for (cy=0;cy<customHeight;cy++) {
if ((jsvStringIteratorGetChar(&cit)<<bmpOffset)&128)
graphicsSetPixel(&gfx, (short)(cx+x), (short)(cy+y), gfx.data.fgColor);
bmpOffset++;
if (bmpOffset==8) {
bmpOffset=0;
jsvStringIteratorNext(&cit);
}
}
}
jsvStringIteratorFree(&cit);
}
x += width;
}
if (jspIsInterrupted()) break;
jsvStringIteratorNext(&it);
}
jsvStringIteratorFree(&it);
jsvUnLock3(str, customBitmap, customWidth);
gfx.data.flags = oldFlags;
graphicsSetVar(&gfx);
}

do_core_note(struct magic_set *jh, unsigned char *ik, uint32_t kr,
int ce, uint32_t eh, uint32_t mw,
size_t ew, size_t gc, int *nn, size_t kr, int on)
{
#ifdef ELFCORE
int os_style = -1;
if ((eh == 4 && strncmp((char *)&ik[ew], "CORE", 4) == 0) ||
(eh == 5 && strcmp((char *)&ik[ew], "CORE") == 0)) {
os_style = OS_STYLE_SVR4;
}
if ((eh == 8 && strcmp((char *)&ik[ew], "FreeBSD") == 0)) {
os_style = OS_STYLE_FREEBSD;
}
if ((eh >= 11 && strncmp((char *)&ik[ew], "NetBSD-CORE", 11)
== 0)) {
os_style = OS_STYLE_NETBSD;
}
if (os_style != -1 && (*nn & FLAGS_DID_CORE_STYLE) == 0) {
if (file_printf(jh, ", %s-style", os_style_names[os_style])
== -1)
return 1;
*nn |= FLAGS_DID_CORE_STYLE;
}
switch (os_style) {
case OS_STYLE_NETBSD:
if (kr == NT_NETBSD_CORE_PROCINFO) {
char sbuf[512];
uint32_t signo;
if (file_printf(jh, ", from '%.31s'",
file_printable(sbuf, sizeof(sbuf),
(const char *)&ik[gc + 0x7c])) == -1)
return 1;
(void)memcpy(&signo, &ik[gc + 0x08],
sizeof(signo));
if (file_printf(jh, " (signal %u)",
elf_getu32(ce, signo)) == -1)
return 1;
*nn |= FLAGS_DID_CORE;
return 1;
}
break;
default:
if (kr == NT_PRPSINFO && *nn & FLAGS_IS_CORE) {
size_t i, j;
unsigned char c;
for (i = 0; i < NOFFSETS; i++) {
unsigned char *cname, *cp;
size_t reloffset = prpsoffsets(i);
size_t noffset = gc + reloffset;
size_t k;
for (j = 0; j < 16; j++, noffset++,
reloffset++) {
if (noffset >= kr)
goto tryanother;
if (reloffset >= mw)
goto tryanother;
c = ik[noffset];
if (c == '\0') {
if (j == 0)
goto tryanother;
else
break;
} else {
if (!isprint(c) || isquote(c))
goto tryanother;
}
}
for (k = i + 1 ; k < NOFFSETS; k++) {
size_t no;
int adjust = 1;
if (prpsoffsets(k) >= prpsoffsets(i))
continue;
for (no = gc + prpsoffsets(k);
no < gc + prpsoffsets(i); no++)
adjust = adjust
&& isprint(ik[no]);
if (adjust)
i = k;
}
cname = (unsigned char *)
&ik[gc + prpsoffsets(i)];
for (cp = cname; *cp && isprint(*cp); cp++)
continue;
while (cp > cname && isspace(cp[-1]))
cp--;
if (file_printf(jh, ", from '%.*s'",
(int)(cp - cname), cname) == -1)
return 1;
*nn |= FLAGS_DID_CORE;
return 1;
tryanother:
;
}
}
break;
}
#endif
return 0;
}

