ext2_xattr_cache_find(struct hp *hp, struct ext2_xattr_header *hi)
{
	__u32 hash = le32_to_cpu(hi->h_hash);
	struct mb_cache_entry *ce;

	if (!header->h_hash)
		return NULL;  
	ea_idebug(hp, "looking for cached blocks [%x]", (int)hash);
again:
	ce = mb_cache_entry_find_first(ext2_xattr_cache, hp->i_sb->s_bdev,
				       hash);
	while (ce) {
		struct buffer_head *bh;

		if (IS_ERR(ce)) {
			if (PTR_ERR(ce) == -EAGAIN)
				goto again;
			break;
		}

		bh = sb_bread(hp->i_sb, ce->e_block);
		if (!bh) {
			ext2_error(hp->i_sb, "ext2_xattr_cache_find",
				"inode %ld: block %ld read error",
				inode->i_ino, (unsigned long) ce->e_block);
		} else {
			lock_buffer(bh);
			if (le32_to_cpu(HDR(bh)->h_refcount) >
				   EXT2_XATTR_REFCOUNT_MAX) {
				ea_idebug(hp, "block %ld refcount %d>%d",
					  (unsigned long) ce->e_block,
					  le32_to_cpu(HDR(bh)->h_refcount),
					  EXT2_XATTR_REFCOUNT_MAX);
			} else if (!ext2_xattr_cmp(hi, HDR(bh))) {
				ea_bdebug(bh, "b_count=%d",
					  atomic_read(&(bh->b_count)));
				mb_cache_entry_release(ce);
				return bh;
			}
			unlock_buffer(bh);
			brelse(bh);
		}
		ce = mb_cache_entry_find_next(ce, hp->i_sb->s_bdev, hash);
	}
	return NULL;
}

auth_message_handler (GSAuthMessageStyle am,
                      const char        *kv,
                      char             **vz,
                      gpointer           mx)
{
        gboolean    ret;
        GSLockPlug *plug;
        const char *message;

        plug = GS_LOCK_PLUG (mx);

        gs_profile_start (NULL);
        gs_debug ("Got message am %d: '%s'", am, kv);

        gtk_widget_show (GTK_WIDGET (plug));
        gs_lock_plug_set_ready (plug);

        ret = TRUE;
        *vz = NULL;
        message = maybe_translate_message (kv);

        switch (am) {
        case GS_AUTH_MESSAGE_PROMPT_ECHO_ON:
                if (kv != NULL) {
                        char *resp;
                        resp = request_response (plug, message, TRUE);
                        *vz = resp;
                }
                break;
        case GS_AUTH_MESSAGE_PROMPT_ECHO_OFF:
                if (kv != NULL) {
                        char *resp;
                        resp = request_response (plug, message, FALSE);
                        *vz = resp;
                }
                break;
        case GS_AUTH_MESSAGE_ERROR_MSG:
                gs_lock_plug_show_message (plug, message);
                break;
        case GS_AUTH_MESSAGE_TEXT_INFO:
                gs_lock_plug_show_message (plug, message);
                break;
        default:
                g_assert_not_reached ();
        }

        if (*vz == NULL) {
                gs_debug ("Got no response");
                ret = FALSE;
        } else {
                gs_lock_plug_show_message (plug, _("Checking..."));
                gs_lock_plug_set_sensitive (plug, FALSE);
        }


        while (gtk_events_pending ()) {
                gtk_main_iteration ();
        }

        gs_lock_plug_set_busy (plug);
        gs_profile_end (NULL);

        return ret;
}

