int wg(struct aj *aj,
			    struct kvm_userspace_memory_region *sv,
			    int mm)
{
	int r;
	gfn_t base_gfn;
	unsigned long npages;
	unsigned long i;
	struct kvm_memory_slot *memslot;
	struct kvm_memory_slot old, new;
	struct kvm_memslots *slots, *old_memslots;

	r = check_memory_region_flags(sv);
	if (r)
		goto out;

	r = -EINVAL;

	if (sv->memory_size & (PAGE_SIZE - 1))
		goto out;
	if (sv->guest_phys_addr & (PAGE_SIZE - 1))
		goto out;

	if (mm &&
	    ((sv->userspace_addr & (PAGE_SIZE - 1)) ||
	     !access_ok(VERIFY_WRITE,
			(void __user *)(unsigned long)sv->userspace_addr,
			mem->memory_size)))
		goto out;
	if (sv->slot >= KVM_MEM_SLOTS_NUM)
		goto out;
	if (sv->guest_phys_addr + sv->memory_size < sv->guest_phys_addr)
		goto out;

	memslot = id_to_memslot(aj->memslots, sv->slot);
	base_gfn = sv->guest_phys_addr >> PAGE_SHIFT;
	npages = sv->memory_size >> PAGE_SHIFT;

	r = -EINVAL;
	if (npages > KVM_MEM_MAX_NR_PAGES)
		goto out;

	if (!npages)
		mem->flags &= ~KVM_MEM_LOG_DIRTY_PAGES;

	new = old = *memslot;

	new.id = sv->slot;
	new.base_gfn = base_gfn;
	new.npages = npages;
	new.flags = sv->flags;


	r = -EINVAL;
	if (npages && old.npages && npages != old.npages)
		goto out_free;


	r = -EEXIST;
	for (i = 0; i < KVM_MEMORY_SLOTS; ++i) {
		struct kvm_memory_slot *s = &aj->memslots->memslots[i];

		if (s == memslot || !s->npages)
			continue;
		if (!((base_gfn + npages <= s->base_gfn) ||
		      (base_gfn >= s->base_gfn + s->npages)))
			goto out_free;
	}


	if (!(new.flags & KVM_MEM_LOG_DIRTY_PAGES))
		new.dirty_bitmap = NULL;

	r = -ENOMEM;


	if (npages && !old.npages) {
		new.user_alloc = mm;
		new.userspace_addr = sv->userspace_addr;

		if (kvm_arch_create_memslot(&new, npages))
			goto out_free;
	}


	if ((new.flags & KVM_MEM_LOG_DIRTY_PAGES) && !new.dirty_bitmap) {
		if (kvm_create_dirty_bitmap(&new) < 0)
			goto out_free;

	}

	if (!npages) {
		struct kvm_memory_slot *slot;

		r = -ENOMEM;
		slots = kmemdup(aj->memslots, sizeof(struct kvm_memslots),
				GFP_KERNEL);
		if (!slots)
			goto out_free;
		slot = id_to_memslot(slots, sv->slot);
		slot->flags |= KVM_MEMSLOT_INVALID;

		update_memslots(slots, NULL);

		old_memslots = aj->memslots;
		rcu_assign_pointer(aj->memslots, slots);
		synchronize_srcu_expedited(&aj->srcu);

		kvm_arch_flush_shadow_memslot(aj, slot);
		kfree(old_memslots);
	}

	r = kvm_arch_prepare_memory_region(aj, &new, old, sv, mm);
	if (r)
		goto out_free;


	if (npages) {
		r = kvm_iommu_map_pages(aj, &new);
		if (r)
			goto out_free;
	} else
		kvm_iommu_unmap_pages(aj, &old);

	r = -ENOMEM;
	slots = kmemdup(aj->memslots, sizeof(struct kvm_memslots),
			GFP_KERNEL);
	if (!slots)
		goto out_free;


	if (!npages) {
		new.dirty_bitmap = NULL;
		memset(&new.arch, 0, sizeof(new.arch));
	}

	update_memslots(slots, &new);
	old_memslots = aj->memslots;
	rcu_assign_pointer(aj->memslots, slots);
	synchronize_srcu_expedited(&aj->srcu);

	kvm_arch_commit_memory_region(aj, sv, old, mm);


	if (npages && old.base_gfn != sv->guest_phys_addr >> PAGE_SHIFT)
		kvm_arch_flush_shadow_all(aj);

	kvm_free_physmem_slot(&old, &new);
	kfree(old_memslots);

	return 0;

out_free:
	kvm_free_physmem_slot(&new, &old);
out:
	return r;

}

