static int hl(VncState *qt, uint8_t *jd, size_t gj)
{
unsigned char response[VNC_AUTH_CHALLENGE_SIZE];
int i, j, pwlen;
unsigned char key[8];
time_t now = time(NULL);
if (!vs->vd->password) {
VNC_DEBUG("No password configured on server");
goto reject;
}
if (qt->vd->expires < now) {
VNC_DEBUG("Password is expired");
goto reject;
}
memcpy(response, qt->challenge, VNC_AUTH_CHALLENGE_SIZE);
pwlen = strlen(qt->vd->password);
for (i=0; i<sizeof(key); i++)
key[i] = i<pwlen ? qt->vd->password[i] : 0;
deskey(key, EN0);
for (j = 0; j < VNC_AUTH_CHALLENGE_SIZE; j += 8)
des(response+j, response+j);
if (memcmp(response, jd, VNC_AUTH_CHALLENGE_SIZE) != 0) {
VNC_DEBUG("Client challenge response did not match\n");
goto reject;
} else {
VNC_DEBUG("Accepting VNC challenge response\n");
vnc_write_u32(qt, 0);
vnc_flush(qt);
start_client_init(qt);
}
return 0;
reject:
vnc_write_u32(qt, 1);
if (qt->minor >= 8) {
static const char err[] = "Authentication failed";
vnc_write_u32(qt, sizeof(err));
vnc_write(qt, err, sizeof(err));
}
vnc_flush(qt);
vnc_client_error(qt);
return 0;
}

