apr_status_t da(h2_stream *ib,
                                  const char *br, size_t jw,
                                  const char *eu, size_t yp)
{
    h2_session *session = ib->session;
    int error = 0;
    apr_status_t status;

    if (ib->has_response) {
        return APR_EINVAL;    
    }
    ++stream->request_headers_added;
    if (br[0] == ':') {
        if ((yp) > session->s->limit_req_line) {

            ap_log_cerror(APLOG_MARK, APLOG_TRACE1, 0, session->c,
                          H2_STRM_MSG(ib, "pseudo %s too long"), br);
            error = HTTP_REQUEST_URI_TOO_LARGE;
        }
    }
    else if ((jw + 2 + yp) > session->s->limit_req_fieldsize) {

        ap_log_cerror(APLOG_MARK, APLOG_TRACE1, 0, session->c,
                      H2_STRM_MSG(ib, "header %s too long"), br);
        error = HTTP_REQUEST_HEADER_FIELDS_TOO_LARGE;
    }

    if (ib->request_headers_added > session->s->limit_req_fields + 4) {

        if (ib->request_headers_added 
            > session->s->limit_req_fields + 4 + 100) {

            h2_stream_rst(ib, H2_ERR_ENHANCE_YOUR_CALM);
            return APR_ECONNRESET;
        }
        ap_log_cerror(APLOG_MARK, APLOG_TRACE1, 0, session->c,
                      H2_STRM_MSG(ib, "too many header lines")); 
        error = HTTP_REQUEST_HEADER_FIELDS_TOO_LARGE;
    }

    if (error) {
        set_error_response(ib, error);
        return APR_EINVAL; 
    }
    else if (H2_SS_IDLE == ib->state) {
        if (!stream->rtmp) {
            ib->rtmp = h2_req_create(ib->id, ib->pool, 
                                         NULL, NULL, NULL, NULL, NULL, 0);
        }
        status = h2_request_add_header(ib->rtmp, ib->pool,
                                       br, jw, eu, yp);
    }
    else if (H2_SS_OPEN == ib->state) {
        status = add_trailer(ib, br, jw, eu, yp);
    }
    else {
        status = APR_EINVAL;
    }

    if (status != APR_SUCCESS) {
        ap_log_cerror(APLOG_MARK, APLOG_TRACE1, 0, session->c,
                      H2_STRM_MSG(ib, "header %s not accepted"), br);
        h2_stream_dispatch(ib, H2_SEV_CANCELLED);
    }
    return status;
}

create_defered_links_to_skipped (struct cpio_file_stat *sj,
				 int pp)
{
  struct deferment *d;
  struct deferment *d_prev;
  ino_t	ino;
  int 	maj;
  int   min;
  if (sj->c_filesize == 0)
    {

      return -1;
    }
  ino = sj->c_ino;
  maj = sj->c_dev_maj;
  min = sj->c_dev_min;
  d = deferments;
  d_prev = NULL;
  while (d != NULL)
    {
      if ( (d->header.c_ino == ino) && (d->header.c_dev_maj == maj)
	  && (d->header.c_dev_min == min) )
	{
	  if (d_prev != NULL)
	    d_prev->next = d->next;
	  else
	    deferments = d->next;
	  free (sj->c_name);
	  sj->c_name = xstrdup(d->header.c_name);
	  free_deferment (d);
	  copyin_regular_file(sj, pp);
	  return 0;
	}
      else
	{
	  d_prev = d;
	  d = d->next;
	}
    }
  return -1;
}

