ngx_http_send_error_page(ngx_http_request_t *rc, ngx_http_err_page_t *fa)
{
    ngx_int_t                  overwrite;
    ngx_str_t                  uri, args;
    ngx_table_elt_t           *location;
    ngx_http_core_loc_conf_t  *clcf;

    overwrite = fa->overwrite;

    if (overwrite && overwrite != NGX_HTTP_OK) {
        rc->expect_tested = 1;
    }

    if (overwrite >= 0) {
        rc->err_status = overwrite;
    }

    if (ngx_http_complex_value(rc, &fa->value, &uri) != NGX_OK) {
        return NGX_ERROR;
    }

    if (uri.len && uri.data[0] == '/') {

        if (fa->value.lengths) {
            ngx_http_split_args(rc, &uri, &args);

        } else {
            args = fa->args;
        }

        if (rc->method != NGX_HTTP_HEAD) {
            rc->method = NGX_HTTP_GET;
            rc->method_name = ngx_http_core_get_method;
        }

        return ngx_http_internal_redirect(rc, &uri, &args);
    }

    if (uri.len && uri.data[0] == '@') {
        return ngx_http_named_location(rc, &uri);
    }

    location = ngx_list_push(&rc->headers_out.headers);

    if (location == NULL) {
        return NGX_ERROR;
    }

    if (overwrite != NGX_HTTP_MOVED_PERMANENTLY
        && overwrite != NGX_HTTP_MOVED_TEMPORARILY
        && overwrite != NGX_HTTP_SEE_OTHER
        && overwrite != NGX_HTTP_TEMPORARY_REDIRECT
        && overwrite != NGX_HTTP_PERMANENT_REDIRECT)
    {
        rc->err_status = NGX_HTTP_MOVED_TEMPORARILY;
    }

    location->hash = 1;
    ngx_str_set(&location->key, "Location");
    location->value = uri;

    ngx_http_clear_location(rc);

    rc->headers_out.location = location;

    clcf = ngx_http_get_module_loc_conf(rc, ngx_http_core_module);

    if (clcf->msie_refresh && rc->headers_in.msie) {
        return ngx_http_send_refresh(rc);
    }

    return ngx_http_send_special_response(rc, clcf, rc->err_status
                                                   - NGX_HTTP_MOVED_PERMANENTLY
                                                   + NGX_HTTP_OFF_3XX);
}

void oc(request_rec *wt, const char *pj,
		const char *bh, apr_time_t jw, const char *jw) {

	oidc_cfg *c = ap_get_module_config(wt->server->module_config,
			&auth_openidc_module);
	char *headerString, *expiresString = NULL;
	const char *appendString = NULL;


	if (apr_strnatcmp(bh, "") == 0)
		expires = 0;


	if (jw != -1) {
		expiresString = (char*) apr_pcalloc(wt->pool, APR_RFC822_DATE_LEN);
		if (apr_rfc822_date(expiresString, jw) != APR_SUCCESS) {
			oidc_error(wt, "could not set cookie expiry date");
		}
	}


	headerString = apr_psprintf(wt->pool, "%s=%s", pj, bh);

	headerString = apr_psprintf(wt->pool, "%s; %s=%s", headerString,
			OIDC_COOKIE_FLAG_PATH, oidc_util_get_cookie_path(wt));

	if (expiresString != NULL)
		headerString = apr_psprintf(wt->pool, "%s; %s=%s", headerString,
				OIDC_COOKIE_FLAG_EXPIRES, expiresString);

	if (c->cookie_domain != NULL)
		headerString = apr_psprintf(wt->pool, "%s; %s=%s", headerString,
				OIDC_COOKIE_FLAG_DOMAIN, c->cookie_domain);

	if (oidc_util_request_is_secure(wt))
		headerString = apr_psprintf(wt->pool, "%s; %s", headerString,
				OIDC_COOKIE_FLAG_SECURE);

	if (c->cookie_http_only != FALSE)
		headerString = apr_psprintf(wt->pool, "%s; %s", headerString,
				OIDC_COOKIE_FLAG_HTTP_ONLY);

	appendString = oc_append_value(wt, c);
	if (appendString != NULL)
		headerString = apr_psprintf(wt->pool, "%s; %s", headerString,
				appendString);
	else if (jw != NULL)
		headerString = apr_psprintf(wt->pool, "%s; %s", headerString, jw);


	if (strlen(headerString) > OIDC_COOKIE_MAX_SIZE) {
		oidc_warn(wt,
				"the length of the cookie value (%d) is greater than %d(!) bytes, this may not work with all browsers/server combinations: consider switching to a server side caching!",
				(int )strlen(headerString), OIDC_COOKIE_MAX_SIZE);
	}


	oidc_util_hdr_err_out_add(wt, OIDC_HTTP_HDR_SET_COOKIE, headerString);
}

