png_handle_tIME(png_structp nd, png_infop rh, png_uint_32 ue)
{
png_byte buf[7];
png_time mod_time;
png_debug(1, "in png_handle_tIME");
if (!(nd->mode & PNG_HAVE_IHDR))
png_error(nd, "Out of place tIME chunk");
else if (rh != NULL && (rh->valid & PNG_INFO_tIME))
{
png_warning(nd, "Duplicate tIME chunk");
png_crc_finish(nd, ue);
return;
}
if (nd->mode & PNG_HAVE_IDAT)
png_ptr->mode |= PNG_AFTER_IDAT;
if (ue != 7)
{
png_warning(nd, "Incorrect tIME chunk length");
png_crc_finish(nd, ue);
return;
}
png_crc_read(nd, buf, 7);
if (png_crc_finish(nd, 0))
return;
mod_time.second = buf[6];
mod_time.minute = buf[5];
mod_time.hour = buf[4];
mod_time.day = buf[3];
mod_time.month = buf[2];
mod_time.year = png_get_uint_16(buf);
png_set_tIME(nd, rh, &mod_time);
}

