static CACHE_BITMAP_V3_ORDER* yv(rdpUpdate* ch, wStream* vs,
                                                                UINT16 sa)
{
	BYTE bitsPerPixelId;
	BITMAP_DATA_EX* bitmapData;
	UINT32 new_len;
	BYTE* new_data;
	CACHE_BITMAP_V3_ORDER* cache_bitmap_v3;

	if (!update || !s)
		return NULL;

	cache_bitmap_v3 = calloc(1, sizeof(CACHE_BITMAP_V3_ORDER));

	if (!cache_bitmap_v3)
		goto fail;

	cache_bitmap_v3->cacheId = sa & 0x00000003;
	cache_bitmap_v3->sa = (sa & 0x0000FF80) >> 7;
	bitsPerPixelId = (sa & 0x00000078) >> 3;
	cache_bitmap_v3->bpp = CBR23_BPP[bitsPerPixelId];

	if (Stream_GetRemainingLength(vs) < 21)
		goto fail;

	Stream_Read_UINT16(vs, cache_bitmap_v3->cacheIndex); 
	Stream_Read_UINT32(vs, cache_bitmap_v3->key1);       
	Stream_Read_UINT32(vs, cache_bitmap_v3->key2);       
	bitmapData = &cache_bitmap_v3->bitmapData;
	Stream_Read_UINT8(vs, bitmapData->bpp);

	if ((bitmapData->bpp < 1) || (bitmapData->bpp > 32))
	{
		WLog_Print(ch->log, WLOG_ERROR, "invalid bpp value %" PRIu32 "", bitmapData->bpp);
		goto fail;
	}

	Stream_Seek_UINT8(vs);                      
	Stream_Seek_UINT8(vs);                      
	Stream_Read_UINT8(vs, bitmapData->codecID); 
	Stream_Read_UINT16(vs, bitmapData->width);  
	Stream_Read_UINT16(vs, bitmapData->height); 
	Stream_Read_UINT32(vs, new_len);            

	if ((new_len == 0) || (Stream_GetRemainingLength(vs) < new_len))
		goto fail;

	new_data = (BYTE*)realloc(bitmapData->data, new_len);

	if (!new_data)
		goto fail;

	bitmapData->data = new_data;
	bitmapData->length = new_len;
	Stream_Read(vs, bitmapData->data, bitmapData->length);
	return cache_bitmap_v3;
fail:
	free_cache_bitmap_v3_order(ch->context, cache_bitmap_v3);
	return NULL;
}

