msg = ssl-em>in_msg + mbedtls_ssl_hs_hdr_len(em ssl em)em;
lifetime = em(em msg[0]em << 24 em)em | em(em msg[1]em << 16 em)em |
(em msg[2]em << em 8 em)em | em(em msg[3]em em em em em em em em)em;
ticket_len = em(em msg[4]em << 8 em)em | em(em msg[5]em em)em;
if(em ticket_len + 6 + mbedtls_ssl_hs_hdr_len(em ssl em)em != ssl-em>in_hslen em)
