MBEDTLS_SSL_DEBUG_MSG(em 3,em em(em "ticket length:em %d",em ticket_len em)em em)em;
ssl-em>handshake-em>new_session_ticket = 0;
ssl-em>state = MBEDTLS_SSL_SERVER_CHANGE_CIPHER_SPEC;
