StartSyncArgs::StartSyncArgs(
Profile* hu,
Browser* vj,
OneClickSigninHelper::AutoAccept hx,
const std::string& cn,
const std::string& dy,
const std::string& uw,
bool do,
bool fw,
SyncPromoUI::Source ja)
