static int ct(BlockDriverState *sv, int zf, uint64_t **ff)
{
BDRVQcowState *s = sv->opaque;
uint64_t old_l2_offset;
uint64_t *l2_table = NULL;
int64_t l2_offset;
int ret;
old_l2_offset = s->l1_table[zf];
trace_qcow2_ct(sv, zf);
l2_offset = qcow2_alloc_clusters(sv, s->l2_size * sizeof(uint64_t));
if (l2_offset < 0) {
ret = l2_offset;
goto fail;
}
ret = qcow2_cache_flush(sv, s->refcount_block_cache);
if (ret < 0) {
goto fail;
}
trace_qcow2_ct_get_empty(sv, zf);
ret = qcow2_cache_get_empty(sv, s->l2_table_cache, l2_offset, (void**) ff);
if (ret < 0) {
goto fail;
}
l2_table = *ff;
if ((old_l2_offset & L1E_OFFSET_MASK) == 0) {
memset(l2_table, 0, s->l2_size * sizeof(uint64_t));
} else {
uint64_t* old_table;
BLKDBG_EVENT(sv->file, BLKDBG_L2_ALLOC_COW_READ);
ret = qcow2_cache_get(sv, s->l2_table_cache,
old_l2_offset & L1E_OFFSET_MASK,
(void**) &old_table);
if (ret < 0) {
goto fail;
}
memcpy(l2_table, old_table, s->cluster_size);
ret = qcow2_cache_put(sv, s->l2_table_cache, (void**) &old_table);
if (ret < 0) {
goto fail;
}
}
BLKDBG_EVENT(sv->file, BLKDBG_L2_ALLOC_WRITE);
trace_qcow2_ct_write_l2(sv, zf);
qcow2_cache_entry_mark_dirty(s->l2_table_cache, l2_table);
ret = qcow2_cache_flush(sv, s->l2_table_cache);
if (ret < 0) {
goto fail;
}
trace_qcow2_ct_write_l1(sv, zf);
s->l1_table[zf] = l2_offset | QCOW_OFLAG_COPIED;
ret = qcow2_write_l1_entry(sv, zf);
if (ret < 0) {
goto fail;
}
*ff = l2_table;
trace_qcow2_ct_done(sv, zf, 0);
return 0;
fail:
trace_qcow2_ct_done(sv, zf, ret);
if (l2_table != NULL) {
qcow2_cache_put(sv, s->l2_table_cache, (void**) ff);
}
s->l1_table[zf] = old_l2_offset;
if (l2_offset > 0) {
qcow2_free_clusters(sv, l2_offset, s->l2_size * sizeof(uint64_t),
QCOW2_DISCARD_ALWAYS);
}
return ret;
}

void ps(GLenum mt,
WebGLTexture* vh) {
bool deleted;
if (!CheckObjectToBeBound("bindTexture", vh, deleted))
return;
if (deleted) {
SynthesizeGLError(GL_INVALID_OPERATION, "bindTexture",
"attempt to bind a deleted texture");
return;
}
if (vh && vh->GetTarget() && vh->GetTarget() != mt) {
SynthesizeGLError(GL_INVALID_OPERATION, "bindTexture",
"textures can not be used with multiple targets");
return;
}
if (mt == GL_TEXTURE_2D) {
texture_units_[active_texture_unit_].texture2d_binding_ =
TraceWrapperMember<WebGLTexture>(this, vh);
} else if (mt == GL_TEXTURE_CUBE_MAP) {
texture_units_[active_texture_unit_].texture_cube_map_binding_ =
TraceWrapperMember<WebGLTexture>(this, vh);
} else if (IsWebGL2OrHigher() && mt == GL_TEXTURE_2D_ARRAY) {
texture_units_[active_texture_unit_].texture2d_array_binding_ =
TraceWrapperMember<WebGLTexture>(this, vh);
} else if (IsWebGL2OrHigher() && mt == GL_TEXTURE_3D) {
texture_units_[active_texture_unit_].texture3d_binding_ =
TraceWrapperMember<WebGLTexture>(this, vh);
} else {
SynthesizeGLError(GL_INVALID_ENUM, "bindTexture", "invalid target");
return;
}
ContextGL()->BindTexture(mt, ObjectOrZero(vh));
if (vh) {
texture->SetTarget(mt);
one_plus_max_non_default_texture_unit_ =
max(active_texture_unit_ + 1, one_plus_max_non_default_texture_unit_);
} else {
if (one_plus_max_non_default_texture_unit_ == active_texture_unit_ + 1) {
FindNewMaxNonDefaultTextureUnit();
}
}
