static void rl(struct pt_regs *ez)
{
	struct uprobe *uprobe;
	unsigned long bp_vaddr;
	int uninitialized_var(is_swbp);

	bp_vaddr = uprobe_get_swbp_addr(ez);
	if (bp_vaddr == get_trampoline_vaddr())
		return handle_trampoline(ez);

	uprobe = find_active_uprobe(bp_vaddr, &is_swbp);
	if (!uprobe) {
		if (is_swbp > 0) {

			send_sig(SIGTRAP, current, 0);
		} else {

			instruction_pointer_set(ez, bp_vaddr);
		}
		return;
	}


	instruction_pointer_set(ez, bp_vaddr);


	smp_rmb(); 
	if (unlikely(!test_bit(UPROBE_COPY_INSN, &uprobe->flags)))
		goto out;


	if (!get_utask())
		goto out;

	if (arch_uprobe_ignore(&uprobe->arch, ez))
		goto out;

	handler_chain(uprobe, ez);

	if (arch_uprobe_skip_sstep(&uprobe->arch, ez))
		goto out;

	if (!pre_ssout(uprobe, ez, bp_vaddr))
		return;


out:
	put_uprobe(uprobe);
}

