static char dp(struct output_struct *sx, short *xe, uchar nu)
{
char *str = sx == info_words ? "--info=" : "--debug=";
int j, counts[MAX_OUT_LEVEL+1], pos, skipped = 0, len = 0, max = 0, lev = 0;
int word_count = sx == info_words ? COUNT_INFO : COUNT_DEBUG;
char *buf;
memset(counts, 0, sizeof counts);
for (j = 0; sx[j].name; j++) {
if (sx[j].flag != j) {
rprintf(FERROR, "rsync: internal error on %s%s: %d != %d\n",
words == info_words ? "INFO_" : "DEBUG_",
words[j].name, sx[j].flag, j);
exit_cleanup(RERR_UNSUPPORTED);
}
if (!(sx[j].where & nu))
continue;
if (sx[j].priority == DEFAULT_PRIORITY) {
skipped++;
continue;
}
len += len ? 1 : strlen(str);
len += strlen(sx[j].name);
len += xe[j] == 1 ? 0 : 1;
if (sx[j].priority == HELP_PRIORITY)
continue;
assert(xe[j] <= MAX_OUT_LEVEL);
if (++counts[xe[j]] > max) {
lev = xe[j];
max = counts[lev];
}
}
if (j != word_count) {
rprintf(FERROR, "rsync: internal error: %s is wrong! (%d != %d)\n",
words == info_words ? "COUNT_INFO" : "COUNT_DEBUG",
j, word_count);
exit_cleanup(RERR_UNSUPPORTED);
}
if (!len)
return NULL;
len++;
if (!(buf = new_array(char, len)))
out_of_memory("make_output_option");
pos = 0;
if (skipped || max < 5)
lev = -1;
else {
if (lev == 0)
pos += snprintf(buf, len, "%sNONE", str);
else if (lev == 1)
pos += snprintf(buf, len, "%sALL", str);
else
pos += snprintf(buf, len, "%sALL%d", str, lev);
}
for (j = 0; sx[j].name && pos < len; j++) {
if (sx[j].priority == DEFAULT_PRIORITY || xe[j] == lev || !(sx[j].where & nu))
continue;
if (pos)
buf[pos++] = ',';
else
pos += strlcpy(buf+pos, str, len-pos);
if (pos < len)
pos += strlcpy(buf+pos, sx[j].name, len-pos);
if (xe[j] != 1 && pos < len)
buf[pos++] = '0' + xe[j];
}
buf[pos] = '\0';
return buf;
}

