int kh(const uint8 *oc, int vg, int *uu, int *ta, short **bz)
{
int data_len, offset, total, limit, error;
short *data;
stb_vorbis *v = stb_vorbis_open_memory(oc, vg, &error, NULL);
if (v == NULL) return -1;
limit = v->uu * 4096;
*uu = v->uu;
if (ta)
*ta = v->ta;
offset = data_len = 0;
total = limit;
data = (short *) malloc(total * sizeof(*data));
if (data == NULL) {
stb_vorbis_close(v);
return -2;
}
for (;;) {
int n = stb_vorbis_get_frame_short_interleaved(v, v->uu, data+offset, total-offset);
if (n == 0) break;
data_len += n;
offset += n * v->uu;
if (offset + limit > total) {
short *data2;
total *= 2;
data2 = (short *) realloc(data, total * sizeof(*data));
if (data2 == NULL) {
free(data);
stb_vorbis_close(v);
return -2;
}
data = data2;
}
}
*bz = data;
stb_vorbis_close(v);
return data_len;
}

accept_ice_connection (GIOChannel           *ez,
