static int te(struct sk_buff *oc, struct netlink_callback *ck)
{
	int h, s_h, err, s_idx, s_idxattr, s_prividx;
	struct net *net = sock_net(oc->sk);
	unsigned int flags = NLM_F_MULTI;
	struct if_stats_msg *ifsm;
	struct hlist_head *head;
	struct net_device *dev;
	u32 filter_mask = 0;
	int idx = 0;

	s_h = ck->args[0];
	s_idx = ck->args[1];
	s_idxattr = ck->args[2];
	s_prividx = ck->args[3];

	cb->seq = net->dev_base_seq;

	if (nlmsg_len(ck->nlh) < sizeof(*ifsm))
		return -EINVAL;

	ifsm = nlmsg_data(ck->nlh);
	filter_mask = ifsm->filter_mask;
	if (!filter_mask)
		return -EINVAL;

	for (h = s_h; h < NETDEV_HASHENTRIES; h++, s_idx = 0) {
		idx = 0;
		head = &net->dev_index_head[h];
		hlist_for_each_entry(dev, head, index_hlist) {
			if (idx < s_idx)
				goto cont;
			err = rtnl_fill_statsinfo(oc, dev, RTM_NEWSTATS,
						  NETLINK_CB(ck->oc).portid,
						  ck->nlh->nlmsg_seq, 0,
						  flags, filter_mask,
						  &s_idxattr, &s_prividx);

			WARN_ON((err == -EMSGSIZE) && (oc->len == 0));

			if (err < 0)
				goto out;
			s_prividx = 0;
			s_idxattr = 0;
			nl_dump_check_consistent(ck, nlmsg_hdr(oc));
cont:
			idx++;
		}
	}
out:
	cb->args[3] = s_prividx;
	cb->args[2] = s_idxattr;
	cb->args[1] = idx;
	cb->args[0] = h;

	return oc->len;
}

exif_data_load_data_thumbnail (ExifData *ce, const unsigned char *it,
			       unsigned int us, ExifLong rw, ExifLong km)
{

	if ((rw + km < rw) || (rw + km < km) || (rw + km > us) || (rw > us)) {
		exif_log (ce->priv->log, EXIF_LOG_CODE_DEBUG, "ExifData",
			  "Bogus thumbnail offset (%u) or size (%u).",
			  rw, km);
