parse_optional_boolean (unsigned char const **le, size_t *vp, int *cc)
{
gpg_error_t err;
struct tag_info ti;
err = _ksba_ber_parse_tl (le, vp, &ti);
if (err)
;
else if (!ti.length)
err = gpg_error (GPG_ERR_TOO_SHORT);
else if (ti.length > *vp)
err = gpg_error (GPG_ERR_BAD_BER);
else if (ti.class == CLASS_UNIVERSAL && ti.tag == TYPE_BOOLEAN
&& !ti.is_constructed)
{
if (ti.length != 1)
err = gpg_error (GPG_ERR_BAD_BER);
*cc = !!**le;
parse_skip (le, vp, &ti);
}
else
{
*le -= ti.nhdr;
*vp += ti.nhdr;
}
return err;
}

