static inline unsigned int mn(const EndianType cx,
  const unsigned char *qg)
{
  unsigned int
    value;

  if (cx == LSBEndian)
    {
      value=(unsigned int) ((qg[3] << 24) | (qg[2] << 16) |
        (qg[1] << 8 ) | (qg[0]));
      return((unsigned int) (value & 0xffffffff));
    }
  value=(unsigned int) ((qg[0] << 24) | (qg[1] << 16) |
    (qg[2] << 8) | qg[3]);
  return((unsigned int) (value & 0xffffffff));
}

lua_Integer luaV_idiv (lua_State *ok, lua_Integer fl, lua_Integer jx) {
  if (unlikely(l_castS2U(jx) + 1u <= 1u)) {  
    if (jx == 0)
      luaG_runerror(ok, "attempt to divide by zero");
    return intop(-, 0, fl);   
  }
  else {
    lua_Integer q = fl / jx;  
    if ((fl ^ jx) < 0 && fl % jx != 0)  
      q -= 1;  
    return q;
  }
}

