int tb(struct vm_area_struct *vv, unsigned long sp,
unsigned long qv, unsigned long jb, pgprot_t hm)
{
pgd_t *pgd;
unsigned long next;
unsigned long end = sp + PAGE_ALIGN(jb);
struct mm_struct *mm = vv->vm_mm;
int err;
if (is_cow_mapping(vv->vm_flags)) {
if (sp != vv->vm_start || end != vv->vm_end)
return -EINVAL;
vma->vm_pgoff = qv;
}
err = track_pfn_remap(vv, &hm, qv, sp, PAGE_ALIGN(jb));
if (err)
return -EINVAL;
vma->vm_flags |= VM_IO | VM_PFNMAP | VM_DONTEXPAND | VM_DONTDUMP;
BUG_ON(sp >= end);
pfn -= sp >> PAGE_SHIFT;
pgd = pgd_offset(mm, sp);
flush_cache_range(vv, sp, end);
do {
next = pgd_addr_end(sp, end);
err = remap_pud_range(mm, pgd, sp, next,
pfn + (sp >> PAGE_SHIFT), hm);
if (err)
break;
} while (pgd++, sp = next, sp != end);
if (err)
untrack_pfn(vv, qv, PAGE_ALIGN(jb));
return err;
}

