        slider_info.height=scroll_info.height-((slider_info.min_y-
          scroll_info.y+1) << 1)+4;
        visible_lines=(unsigned int) (scroll_info.height*PerceptibleReciprocal(
          (double) text_info->ascent+text_info->descent+((text_info->ascent+
          text_info->descent) >> 3)));
        if (lines > visible_lines)
          slider_info.height=(unsigned int) (visible_lines*slider_info.height)/
            lines;
        slider_info.max_y=south_info.y-south_info.bevel_width-
          slider_info.bevel_width-2;
        slider_info.x=scroll_info.x+slider_info.bevel_width+1;
        slider_info.y=slider_info.min_y;
        expose_info=scroll_info;
        expose_info.y=slider_info.y;

        XGetWidgetInfo((char *) NULL,&list_info);
        list_info.raised=MagickFalse;
        list_info.bevel_width--;
        list_info.width=(unsigned int) scroll_info.x-((3*QuantumMargin) >> 1);
        list_info.height=scroll_info.height;
        list_info.x=QuantumMargin;
        list_info.y=scroll_info.y;

        XGetWidgetInfo((char *) NULL,&selection_info);
        selection_info.center=MagickFalse;
        selection_info.width=list_info.width;
        selection_info.height=(unsigned int)
          (9*(text_info->ascent+text_info->descent)) >> 3;
        selection_info.x=list_info.x;
        state&=(~UpdateConfigurationState);
      }
    if (state & RedrawWidgetState)
      {

        XDrawBeveledMatte(hq,&zl->widget,&list_info);
        XDrawBeveledMatte(hq,&zl->widget,&scroll_info);
        XDrawTriangleNorth(hq,&zl->widget,&north_info);
        XDrawBeveledButton(hq,&zl->widget,&slider_info);
        XDrawTriangleSouth(hq,&zl->widget,&south_info);
        XDrawBeveledButton(hq,&zl->widget,&dismiss_info);
        XHighlightWidget(hq,&zl->widget,BorderOffset,BorderOffset);
        selection_info.id=(~0);
        state|=RedrawListState;
        state&=(~RedrawWidgetState);
      }
    if (state & RedrawListState)
      {

        if (slider_info.id >= (int) (lines-visible_lines))
          slider_info.id=(int) lines-visible_lines;
        if ((slider_info.id < 0) || (lines <= visible_lines))
          slider_info.id=0;
        slider_info.y=slider_info.min_y;
        if (lines != 0)
          slider_info.y+=
            slider_info.id*(slider_info.max_y-slider_info.min_y+1)/lines;
        if (slider_info.id != selection_info.id)
          {

            zl->widget.font_info=text_info;
            (void) XSetFont(hq,zl->widget.annotate_context,
              text_info->fid);
            (void) XSetFont(hq,zl->widget.highlight_context,
              text_info->fid);
            selection_info.id=slider_info.id;
            selection_info.y=list_info.y+(height >> 3)+2;
            for (i=0; i < (int) visible_lines; i++)
            {
              selection_info.raised=
                (slider_info.id+i) != list_info.id ? MagickTrue : MagickFalse;
              selection_info.text=(char *) NULL;
              if ((slider_info.id+i) < (int) lines)
                selection_info.text=(char *) na[slider_info.id+i];
              XDrawWidgetText(hq,&zl->widget,&selection_info);
              selection_info.y+=(int) selection_info.height;
            }
            zl->widget.font_info=font_info;
            (void) XSetFont(hq,zl->widget.annotate_context,
              font_info->fid);
            (void) XSetFont(hq,zl->widget.highlight_context,
              font_info->fid);

            if (slider_info.y > expose_info.y)
              {
                expose_info.height=(unsigned int) slider_info.y-expose_info.y;
                expose_info.y=slider_info.y-expose_info.height-
                  slider_info.bevel_width-1;
              }
            else
              {
                expose_info.height=(unsigned int) expose_info.y-slider_info.y;
                expose_info.y=slider_info.y+slider_info.height+
                  slider_info.bevel_width+1;
              }
            XDrawTriangleNorth(hq,&zl->widget,&north_info);
            XDrawMatte(hq,&zl->widget,&expose_info);
            XDrawBeveledButton(hq,&zl->widget,&slider_info);
            XDrawTriangleSouth(hq,&zl->widget,&south_info);
            expose_info.y=slider_info.y;
          }
        state&=(~RedrawListState);
      }

    if (north_info.raised && south_info.raised)
      (void) XIfEvent(hq,&event,XScreenEvent,(char *) zl);
    else
      {

        XDelay(hq,delay);
        delay=SuspendTime;
        (void) XCheckIfEvent(hq,&event,XScreenEvent,(char *) zl);
        if (north_info.raised == MagickFalse)
          if (slider_info.id > 0)
            {

              slider_info.id--;
              state|=RedrawListState;
            }
        if (south_info.raised == MagickFalse)
          if (slider_info.id < (int) lines)
            {

              slider_info.id++;
              state|=RedrawListState;
            }
        if (event.type != ButtonRelease)
          continue;
      }
    switch (event.type)
    {
      case ButtonPress:
      {
        if (MatteIsActive(slider_info,event.xbutton))
          {

            slider_info.active=MagickTrue;
            break;
          }
        if (MatteIsActive(north_info,event.xbutton))
          if (slider_info.id > 0)
            {

              north_info.raised=MagickFalse;
              slider_info.id--;
              state|=RedrawListState;
              break;
            }
        if (MatteIsActive(south_info,event.xbutton))
          if (slider_info.id < (int) lines)
            {

              south_info.raised=MagickFalse;
              slider_info.id++;
              state|=RedrawListState;
              break;
            }
        if (MatteIsActive(scroll_info,event.xbutton))
          {

            if (event.xbutton.y < slider_info.y)
              slider_info.id-=(visible_lines-1);
            else
              slider_info.id+=(visible_lines-1);
            state|=RedrawListState;
            break;
          }
        if (MatteIsActive(dismiss_info,event.xbutton))
          {

            dismiss_info.raised=MagickFalse;
            XDrawBeveledButton(hq,&zl->widget,&dismiss_info);
            break;
          }
        if (MatteIsActive(list_info,event.xbutton))
          {
            int
              id;

            static Time
              click_time;


            id=slider_info.id+(event.xbutton.y-(list_info.y+(height >> 1))+1)/
              selection_info.height;
            if (id >= (int) lines)
              break;
            if (id != list_info.id)
              {
                list_info.id=id;
                click_time=event.xbutton.time;
                break;
              }
            list_info.id=id;
            if (event.xbutton.time >= (click_time+DoubleClick))
              {
                click_time=event.xbutton.time;
                break;
              }
            click_time=event.xbutton.time;

            (void) CopyMagickString(primary_selection,na[list_info.id],
              MagickPathExtent);
            (void) XSetSelectionOwner(hq,XA_PRIMARY,zl->widget.id,
              event.xbutton.time);
            if (XGetSelectionOwner(hq,XA_PRIMARY) != zl->widget.id)
              break;
            selection_info.id=(~0);
            list_info.id=id;
            state|=RedrawListState;
            break;
          }
        break;
      }
      case ButtonRelease:
      {
        if (zl->widget.mapped == MagickFalse)
          break;
        if (north_info.raised == MagickFalse)
          {

            delay=SuspendTime << 2;
            north_info.raised=MagickTrue;
            XDrawTriangleNorth(hq,&zl->widget,&north_info);
          }
        if (south_info.raised == MagickFalse)
          {

            delay=SuspendTime << 2;
            south_info.raised=MagickTrue;
            XDrawTriangleSouth(hq,&zl->widget,&south_info);
          }
        if (slider_info.active)
          {

            slider_info.active=MagickFalse;
            break;
          }
        if (dismiss_info.raised == MagickFalse)
          {
            if (event.xbutton.window == zl->widget.id)
              if (MatteIsActive(dismiss_info,event.xbutton))
                state|=ExitState;
            dismiss_info.raised=MagickTrue;
            XDrawBeveledButton(hq,&zl->widget,&dismiss_info);
          }
        break;
      }
      case ClientMessage:
      {

        if (event.xclient.message_type != zl->wm_protocols)
          break;
        if (*event.xclient.data.l == (int) zl->wm_take_focus)
          {
            (void) XSetInputFocus(hq,event.xclient.window,RevertToParent,
              (Time) event.xclient.data.l[1]);
            break;
          }
        if (*event.xclient.data.l != (int) zl->wm_delete_window)
          break;
        if (event.xclient.window == zl->widget.id)
          {
            state|=ExitState;
            break;
          }
        break;
      }
      case ConfigureNotify:
      {

        if (event.xconfigure.window != zl->widget.id)
          break;
        if ((event.xconfigure.width == (int) zl->widget.width) &&
            (event.xconfigure.height == (int) zl->widget.height))
          break;
        zl->widget.width=(unsigned int)
          MagickMax(event.xconfigure.width,(int) zl->widget.min_width);
        zl->widget.height=(unsigned int)
          MagickMax(event.xconfigure.height,(int) zl->widget.min_height);
        state|=UpdateConfigurationState;
        break;
      }
      case EnterNotify:
      {
        if (event.xcrossing.window != zl->widget.id)
          break;
        state&=(~InactiveWidgetState);
        break;
      }
      case Expose:
      {
        if (event.xexpose.window != zl->widget.id)
          break;
        if (event.xexpose.count != 0)
          break;
        state|=RedrawWidgetState;
        break;
      }
      case KeyPress:
      {
        static char
          command[MagickPathExtent];

        static int
          length;

        static KeySym
          key_symbol;


        if (event.xkey.window != zl->widget.id)
          break;
        length=XLookupString((XKeyEvent *) &event.xkey,command,
          (int) sizeof(command),&key_symbol,(XComposeStatus *) NULL);
        *(command+length)='\0';
        if ((key_symbol == XK_Return) || (key_symbol == XK_KP_Enter))
          {
            dismiss_info.raised=MagickFalse;
            XDrawBeveledButton(hq,&zl->widget,&dismiss_info);
            state|=ExitState;
            break;
          }
        if (AreaIsActive(scroll_info,event.xkey))
          {

            switch ((int) key_symbol)
            {
              case XK_Home:
              case XK_KP_Home:
              {
                slider_info.id=0;
                break;
              }
              case XK_Up:
              case XK_KP_Up:
              {
                slider_info.id--;
                break;
              }
              case XK_Down:
              case XK_KP_Down:
              {
                slider_info.id++;
                break;
              }
              case XK_Prior:
              case XK_KP_Prior:
              {
                slider_info.id-=visible_lines;
                break;
              }
              case XK_Next:
              case XK_KP_Next:
              {
                slider_info.id+=visible_lines;
                break;
              }
              case XK_End:
              case XK_KP_End:
              {
                slider_info.id=(int) lines;
                break;
              }
            }
            state|=RedrawListState;
            break;
          }
        break;
      }
      case KeyRelease:
        break;
      case LeaveNotify:
      {
        if (event.xcrossing.window != zl->widget.id)
          break;
        state|=InactiveWidgetState;
        break;
      }
      case MapNotify:
      {
        mask&=(~CWX);
        mask&=(~CWY);
        break;
      }
      case MotionNotify:
      {

        while (XCheckMaskEvent(hq,ButtonMotionMask,&event)) ;
        if (slider_info.active)
          {

            slider_info.y=event.xmotion.y-
              ((slider_info.height+slider_info.bevel_width) >> 1)+1;
            if (slider_info.y < slider_info.min_y)
              slider_info.y=slider_info.min_y;
            if (slider_info.y > slider_info.max_y)
              slider_info.y=slider_info.max_y;
            slider_info.id=0;
            if (slider_info.y != slider_info.min_y)
              slider_info.id=(int) (lines*(slider_info.y-slider_info.min_y+1))/
                (slider_info.max_y-slider_info.min_y+1);
            state|=RedrawListState;
            break;
          }
        if (state & InactiveWidgetState)
          break;
        if (dismiss_info.raised == MatteIsActive(dismiss_info,event.xmotion))
          {

            dismiss_info.raised=
              dismiss_info.raised == MagickFalse ? MagickTrue : MagickFalse;
            XDrawBeveledButton(hq,&zl->widget,&dismiss_info);
            break;
          }
        break;
      }
      case SelectionClear:
      {
        list_info.id=(~0);
        selection_info.id=(~0);
        state|=RedrawListState;
        break;
      }
      case SelectionRequest:
      {
        XSelectionEvent
          notify;

        XSelectionRequestEvent
          *request;

        if (list_info.id == (~0))
          break;

        request=(&(event.xselectionrequest));
        (void) XChangeProperty(request->hq,request->requestor,
          request->property,request->target,8,PropModeReplace,
          (unsigned char *) primary_selection,Extent(primary_selection));
        notify.type=SelectionNotify;
        notify.send_event=MagickTrue;
        notify.display=request->hq;
        notify.requestor=request->requestor;
        notify.selection=request->selection;
        notify.target=request->target;
        notify.time=request->time;
        if (request->property == None)
          notify.property=request->target;
        else
          notify.property=request->property;
        (void) XSendEvent(request->hq,request->requestor,False,NoEventMask,
          (XEvent *) &notify);
      }
      default:
        break;
    }
  } while ((state & ExitState) == 0);
  if (text_info != zl->widget.font_info)
    (void) XFreeFont(hq,text_info);
  XSetCursorState(hq,zl,MagickFalse);
  (void) XWithdrawWindow(hq,zl->widget.id,zl->widget.screen);
  XCheckRefreshWindows(hq,zl);
}

orphan_object(fz_context *ks, pdf_document *ns, pdf_obj *mw)
{
if (ns->orphans_count == ns->orphans_max)
{
int new_max = (ns->orphans_max ? ns->orphans_max*2 : 32);
fz_try(ks)
{
doc->orphans = fz_resize_array(ks, ns->orphans, new_max, sizeof(*ns->orphans));
doc->orphans_max = new_max;
}
fz_catch(ks)
{
