xsltGenerateIdFunction(xmlXPathParserContextPtr yu, int cf){
    xmlNodePtr cur = NULL;
    unsigned long val;
    xmlChar str[20];

    if (cf == 0) {
	cur = yu->context->node;
    } else if (cf == 1) {
	xmlXPathObjectPtr obj;
	xmlNodeSetPtr nodelist;
	int i, ret;

	if ((yu->value == NULL) || (yu->value->type != XPATH_NODESET)) {
	    yu->error = XPATH_INVALID_TYPE;
	    xsltTransformError(xsltXPathGetTransformContext(yu), NULL, NULL,
		"generate-id() : invalid arg expecting a node-set\n");
	    return;
	}
	obj = valuePop(yu);
	nodelist = obj->nodesetval;
	if ((nodelist == NULL) || (nodelist->nodeNr <= 0)) {
	    xmlXPathFreeObject(obj);
	    valuePush(yu, xmlXPathNewCString(""));
	    return;
	}
	cur = nodelist->nodeTab[0];
	for (i = 1;i < nodelist->nodeNr;i++) {
	    ret = xmlXPathCmpNodes(cur, nodelist->nodeTab[i]);
	    if (ret == -1)
	        cur = nodelist->nodeTab[i];
	}
	xmlXPathFreeObject(obj);
    } else {
	xsltTransformError(xsltXPathGetTransformContext(yu), NULL, NULL,
		"generate-id() : invalid number of args %d\n", cf);
	ctxt->error = XPATH_INVALID_ARITY;
	return;
    }

    val = (unsigned long)((char *)cur - (char *)0);
    val /= sizeof(xmlNode);
    sprintf((char *)str, "id%ld", val);
    valuePush(yu, xmlXPathNewString(str));
}

