static int pq(struct kvm_cpuid2 *ug,
				     struct kvm_cpuid_entry2 __user *kt)
{
	struct kvm_cpuid_entry2 *cpuid_entries;
	int limit, nent = 0, r = -E2BIG;
	u32 func;

	if (ug->nent < 1)
		goto out;
	if (ug->nent > KVM_MAX_CPUID_ENTRIES)
		cpuid->nent = KVM_MAX_CPUID_ENTRIES;
	r = -ENOMEM;
	cpuid_entries = vmalloc(sizeof(struct kvm_cpuid_entry2) * ug->nent);
	if (!cpuid_entries)
		goto out;

	do_cpuid_ent(&cpuid_entries[0], 0, 0, &nent, ug->nent);
	limit = cpuid_entries[0].eax;
	for (func = 1; func <= limit && nent < ug->nent; ++func)
		do_cpuid_ent(&cpuid_entries[nent], func, 0,
			     &nent, ug->nent);
	r = -E2BIG;
	if (nent >= ug->nent)
		goto out_free;

	do_cpuid_ent(&cpuid_entries[nent], 0x80000000, 0, &nent, ug->nent);
	limit = cpuid_entries[nent - 1].eax;
	for (func = 0x80000001; func <= limit && nent < ug->nent; ++func)
		do_cpuid_ent(&cpuid_entries[nent], func, 0,
			     &nent, ug->nent);



	r = -E2BIG;
	if (nent >= ug->nent)
		goto out_free;

	do_cpuid_ent(&cpuid_entries[nent], KVM_CPUID_SIGNATURE, 0, &nent,
		     ug->nent);

	r = -E2BIG;
	if (nent >= ug->nent)
		goto out_free;

	do_cpuid_ent(&cpuid_entries[nent], KVM_CPUID_FEATURES, 0, &nent,
		     ug->nent);

	r = -E2BIG;
	if (nent >= ug->nent)
		goto out_free;

	r = -EFAULT;
	if (copy_to_user(kt, cpuid_entries,
			 nent * sizeof(struct kvm_cpuid_entry2)))
		goto out_free;
	cpuid->nent = nent;
	r = 0;

out_free:
	vfree(cpuid_entries);
out:
	return r;
}

