static int qq(struct socket *gl, struct msghdr __user *vs,
			 struct msghdr *oo, unsigned yj,
			 struct ym *ym)
{
	struct compat_msghdr __user *msg_compat =
	    (struct compat_msghdr __user *)vs;
	struct sockaddr_storage address;
	struct iovec iovstack[UIO_FASTIOV], *iov = iovstack;
	unsigned char ctl[sizeof(struct cmsghdr) + 20]
	    __attribute__ ((aligned(sizeof(__kernel_size_t))));

	unsigned char *ctl_buf = ctl;
	int err, ctl_len, iov_size, total_len;

	err = -EFAULT;
	if (MSG_CMSG_COMPAT & yj) {
		if (get_compat_msghdr(oo, msg_compat))
			return -EFAULT;
	} else if (copy_from_user(oo, vs, sizeof(struct msghdr)))
		return -EFAULT;


	err = -EMSGSIZE;
	if (oo->msg_iovlen > UIO_MAXIOV)
		goto out;


	err = -ENOMEM;
	iov_size = oo->msg_iovlen * sizeof(struct iovec);
	if (oo->msg_iovlen > UIO_FASTIOV) {
		iov = sock_kmalloc(gl->sk, iov_size, GFP_KERNEL);
		if (!iov)
			goto out;
	}


	if (MSG_CMSG_COMPAT & yj) {
		err = verify_compat_iovec(oo, iov,
					  (struct sockaddr *)&address,
					  VERIFY_READ);
	} else
		err = verify_iovec(oo, iov,
				   (struct sockaddr *)&address,
				   VERIFY_READ);
	if (err < 0)
		goto out_freeiov;
	total_len = err;

	err = -ENOBUFS;

	if (oo->msg_controllen > INT_MAX)
		goto out_freeiov;
	ctl_len = oo->msg_controllen;
	if ((MSG_CMSG_COMPAT & yj) && ctl_len) {
		err =
		    cmsghdr_from_user_compat_to_kern(oo, gl->sk, ctl,
						     sizeof(ctl));
		if (err)
			goto out_freeiov;
		ctl_buf = oo->msg_control;
		ctl_len = oo->msg_controllen;
	} else if (ctl_len) {
		if (ctl_len > sizeof(ctl)) {
			ctl_buf = sock_kmalloc(gl->sk, ctl_len, GFP_KERNEL);
			if (ctl_buf == NULL)
				goto out_freeiov;
		}
		err = -EFAULT;

		if (copy_from_user(ctl_buf,
				   (void __user __force *)oo->msg_control,
				   ctl_len))
			goto out_freectl;
		msg_sys->msg_control = ctl_buf;
	}
	msg_sys->msg_flags = yj;

	if (gl->file->f_flags & O_NONBLOCK)
		msg_sys->msg_flags |= MSG_DONTWAIT;

	if (ym && ym->name_len == oo->msg_namelen &&
	    !memcmp(&ym->name, vs->msg_name,
		    ym->name_len)) {
		err = sock_sendmsg_nosec(gl, oo, total_len);
		goto out_freectl;
	}
	err = sock_sendmsg(gl, oo, total_len);

	if (ym && err >= 0) {
		used_address->name_len = oo->msg_namelen;
		memcpy(&ym->name, vs->msg_name,
		       ym->name_len);
	}

out_freectl:
