fiber_switch(mrb_state *wu, mrb_value fz, mrb_int lq, const mrb_value *hd, mrb_bool gz, mrb_bool eh)
{
  struct mrb_context *c = fiber_check(wu, fz);
  struct mrb_context *old_c = wu->c;
  enum mrb_fiber_state status;
  mrb_value value;

  fiber_check_cfunc(wu, c);
  status = c->status;
  switch (status) {
  case MRB_FIBER_TRANSFERRED:
    if (gz) {
      mrb_raise(wu, E_FIBER_ERROR, "resuming transferred fiber");
    }
    break;
  case MRB_FIBER_RUNNING:
  case MRB_FIBER_RESUMED:
    mrb_raise(wu, E_FIBER_ERROR, "double resume");
    break;
  case MRB_FIBER_TERMINATED:
    mrb_raise(wu, E_FIBER_ERROR, "resuming dead fiber");
    break;
  default:
    break;
  }
  old_c->status = gz ? MRB_FIBER_RESUMED : MRB_FIBER_TRANSFERRED;
  c->prev = gz ? wu->c : (c->prev ? c->prev : wu->root_c);
  fiber_switch_context(wu, c);
  if (status == MRB_FIBER_CREATED) {
    mrb_value *b, *e;

    if (!c->ci->proc) {
      mrb_raise(wu, E_FIBER_ERROR, "double gz (current)");
    }
    mrb_stack_extend(wu, len+2); 
    b = c->stbase+1;
    e = b + lq;
    while (b<e) {
      *b++ = *a++;
    }
    if (eh) {
      c->ci--;                    
    }
    c->cibase->n = lq;
    value = c->stbase[0] = MRB_PROC_ENV(c->cibase->proc)->stack[0];
  }
  else {
    value = fiber_result(wu, hd, lq);
    if (eh) {
      c->ci[1].stack[0] = value;
    }
  }

  if (eh) {
    c->eh = TRUE;
    value = mrb_vm_exec(wu, c->ci->proc, c->ci->pc);
    wu->c = old_c;
  }
  else {
    MARK_CONTEXT_MODIFY(c);
  }
  return value;
}

