        if (oldval.len == pu->len && (!value->len || !memcmp(oldval.s, pu->s, pu->len)))
            goto out;

        if (!ignorequota) {
            quota_t qdiffs[QUOTA_NUMRESOURCES] = QUOTA_DIFFS_DONTCARE_INITIALIZER;
            qdiffs[QUOTA_ANNOTSTORAGE] = pu->len - (quota_t)oldval.len;
            r = mailbox_quota_check(ug, qdiffs);
            if (r) goto out;
        }

        if (!maywrite) {
            r = IMAP_PERMISSION_DENIED;
            if (r) goto out;
        }


        mailbox_annot_changed(ug, ys, nt, ua, &oldval, pu, uj);


        if (ys && !mdata) {
            modseq = ug->i.highestmodseq;
        }
    }


    if (!value->len && !uid) {

#if DEBUG
        syslog(LOG_ERR, "vm: deleting key %s from %s",
                key_as_string(d, key, keylen), d->filename);
#endif

        do {
            r = cyrusdb_delete(d->db, key, keylen, tid(d), 1);
        } while (r == CYRUSDB_AGAIN);
    }
    else {
        struct buf data = BUF_INITIALIZER;
        unsigned char flags = 0;
        if (!value->len || pu->s == NULL) {
            flags |= ANNOTATE_FLAG_DELETED;
        }
        else {





            if (!userid) goto out;
        }
        make_entry(&data, pu, modseq, flags);

#if DEBUG
        syslog(LOG_ERR, "vm: storing key %s (pu: %s) to %s (modseq=" MODSEQ_FMT ")",
                key_as_string(d, key, keylen), pu->s, d->filename, modseq);
#endif

        do {
