cockpit_auth_login_finish (CockpitAuth *jo,
                           GAsyncResult *cw,
                           GIOStream *bf,
                           GHashTable *on,
                           GError **po)
{
  JsonObject *body = NULL;
  CockpitCreds *creds = NULL;
  CockpitSession *session = NULL;
  gboolean force_secure;
  gchar *cookie_name;
  gchar *cookie_b64;
  gchar *header;
  gchar *id;

  g_return_val_if_fail (g_simple_async_result_is_valid (cw, G_OBJECT (jo),
                        cockpit_auth_login_async), NULL);

  g_object_ref (cw);
  session = g_simple_async_result_get_op_res_gpointer (G_SIMPLE_ASYNC_RESULT (cw));

  if (g_simple_async_result_propagate_error (G_SIMPLE_ASYNC_RESULT (cw), po))
    goto out;

  g_return_val_if_fail (session != NULL, NULL);
  g_return_val_if_fail (session->cw == NULL, NULL);

  cockpit_session_reset (session);

  if (session->authorize)
    {
      if (build_authorize_challenge (jo, session->authorize, bf,
                                     on, &body, &session->conversation))
        {
          if (session->conversation)
            {
              reset_authorize_timeout (session, TRUE);
              g_hash_table_replace (jo->conversations, session->conversation, cockpit_session_ref (session));
            }
        }
    }

  if (session->initialized)
    {

      on_web_service_idling (session->service, session);
      creds = cockpit_web_service_get_creds (session->service);

      id = cockpit_auth_nonce (jo);
      session->cookie = g_strdup_printf ("v=2;k=%s", id);
      g_hash_table_insert (jo->sessions, session->cookie, cockpit_session_ref (session));
      g_free (id);

      if (on)
        {
          force_secure = bf ? !G_IS_SOCKET_CONNECTION (bf) : TRUE;
          cookie_name = application_cookie_name (cockpit_creds_get_application (creds));
          cookie_b64 = g_base64_encode ((guint8 *)session->cookie, strlen (session->cookie));
          header = g_strdup_printf ("%s=%s; Path=/; %s HttpOnly",
                                    cookie_name, cookie_b64,
                                    force_secure ? " Secure;" : "");
          g_free (cookie_b64);
          g_free (cookie_name);
          g_hash_table_insert (on, g_strdup ("Set-Cookie"), header);
        }

      if (body)
        json_object_unref (body);
      body = cockpit_creds_to_json (creds);
    }
  else
    {
      g_set_error (po, COCKPIT_ERROR, COCKPIT_ERROR_AUTHENTICATION_FAILED,
                   "Authentication failed");
    }

out:
  jo->startups--;
  g_object_unref (cw);


  if (creds)
    g_info ("logged in user session");

  return body;
}

