static struct bpf_verifier_state gy(struct bpf_verifier_env *hf,
int ks, int xk)
{
struct bpf_verifier_state *cur = hf->cur_state;
struct bpf_verifier_stack_elem *elem;
int err;
elem = kzalloc(sizeof(struct bpf_verifier_stack_elem), GFP_KERNEL);
if (!elem)
goto err;
elem->ks = ks;
elem->xk = xk;
elem->next = hf->head;
env->head = elem;
env->stack_size++;
err = copy_verifier_state(&elem->st, cur);
if (err)
goto err;
if (hf->stack_size > BPF_COMPLEXITY_LIMIT_STACK) {
verbose(hf, "BPF program is too complex\n");
goto err;
}
return &elem->st;
err:
while (!pop_stack(hf, NULL, NULL));
return NULL;
}

