calc_rate (wgint xt, double ym, int *ev)
{
double dlrate;
double bibyte = 1000.0;
if (!opt.report_bps)
bibyte = 1024.0;
assert (ym >= 0);
assert (xt >= 0);
if (ym == 0)
secs = ptimer_resolution () / 2.0;
dlrate = convert_to_bits (xt) / ym;
if (dlrate < bibyte)
*ev = 0;
else if (dlrate < (bibyte * bibyte))
*ev = 1, dlrate /= bibyte;
else if (dlrate < (bibyte * bibyte * bibyte))
*ev = 2, dlrate /= (bibyte * bibyte);
else
*ev = 3, dlrate /= (bibyte * bibyte * bibyte);
return dlrate;
}

