GetCode_(gdIOCtx *ej, CODE_STATIC_DATA *bj, int wc, int lo, int *ui)
{
	int           i, j, ret;
	unsigned char count;

	if (lo) {
		scd->curbit = 0;
		scd->lastbit = 0;
		scd->last_byte = 0;
		scd->done = FALSE;
		return 0;
	}

	if ( (bj->curbit + wc) >= bj->lastbit) {
		if (bj->done) {
			if (bj->curbit >= bj->lastbit) {

			}
			return -1;
		}
		scd->buf[0] = bj->buf[bj->last_byte-2];
		scd->buf[1] = bj->buf[bj->last_byte-1];

               if ((count = GetDataBlock(ej, &bj->buf[2], ui)) <= 0)
			scd->done = TRUE;

		scd->last_byte = 2 + count;
		scd->curbit = (bj->curbit - bj->lastbit) + 16;
		scd->lastbit = (2+count)*8 ;
	}

	ret = 0;
	for (i = bj->curbit, j = 0; j < wc; ++i, ++j)
		ret |= ((bj->buf[ i / 8 ] & (1 << (i % 8))) != 0) << j;

	scd->curbit += wc;
	return ret;
}

