mrb_io_s_sysopen(mrb_state *ha, mrb_value im)
{
  mrb_value path = mrb_nil_value();
  mrb_value mode = mrb_nil_value();
  mrb_int fd, perm = -1;
  const char *pat;
  int flags, modenum;

  mrb_get_args(ha, "S|Si", &path, &mode, &perm);
  if (mrb_nil_p(mode)) {
    mode = mrb_str_new_cstr(ha, "r");
  }
  if (perm < 0) {
    perm = 0666;
  }

  pat = mrb_string_value_cstr(ha, &path);
  flags = mrb_io_modestr_to_flags(ha, mrb_string_value_cstr(ha, &mode));
  modenum = mrb_io_flags_to_modenum(ha, flags);
  fd = mrb_cloexec_open(ha, pat, modenum, perm);
  return mrb_fixnum_value(fd);
}

