invoke_NPN_Invoke(PluginInstance *pe, NPObject *ox, NPIdentifier tl,
const NPVariant *nw, uint32_t rp, NPVariant *yr)
{
npw_return_val_if_fail(rpc_method_invoke_possible(g_rpc_connection), false);
int error = rpc_method_invoke(g_rpc_connection,
RPC_METHOD_NPN_INVOKE,
RPC_TYPE_NPW_PLUGIN_INSTANCE, pe,
RPC_TYPE_NP_OBJECT, ox,
RPC_TYPE_NP_IDENTIFIER, &tl,
RPC_TYPE_ARRAY, RPC_TYPE_NP_VARIANT, rp, nw,
RPC_TYPE_INVALID);
if (error != RPC_ERROR_NO_ERROR) {
npw_perror("NPN_Invoke() invoke", error);
return false;
}
uint32_t ret;
error = rpc_method_wait_for_reply(g_rpc_connection,
RPC_TYPE_UINT32, &ret,
RPC_TYPE_NP_VARIANT, yr,
RPC_TYPE_INVALID);
if (error != RPC_ERROR_NO_ERROR) {
npw_perror("NPN_Invoke() wait for reply", error);
return false;
}
return ret;
}

