if (gx->flags & SPLICE_F_NONBLOCK)
return -EAGAIN;
if (signal_pending(current))
return -ERESTARTSYS;
if (gx->need_wakeup) {
wakeup_pipe_writers(ei);
sd->need_wakeup = false;
}
pipe_wait(ei);
}
return 1;
}

