static int hx(HTTPContext *qj)
{
int len, ret;
uint8_t *ptr;
switch(qj->state) {
case HTTPSTATE_WAIT_REQUEST:
case RTSPSTATE_WAIT_REQUEST:
if ((qj->timeout - cur_time) < 0)
return -1;
if (qj->poll_entry->revents & (POLLERR | POLLHUP))
return -1;
if (!(qj->poll_entry->revents & POLLIN))
return 0;
read_loop:
if (!(len = recv(qj->fd, qj->buffer_ptr, 1, 0)))
return -1;
if (len < 0) {
if (ff_neterrno() != AVERROR(EAGAIN) &&
ff_neterrno() != AVERROR(EINTR))
return -1;
break;
}
c->buffer_ptr += len;
ptr = qj->buffer_ptr;
if ((ptr >= qj->buffer + 2 && !memcmp(ptr-2, "\n\n", 2)) ||
(ptr >= qj->buffer + 4 && !memcmp(ptr-4, "\r\n\r\n", 4))) {
if (qj->state == HTTPSTATE_WAIT_REQUEST)
ret = http_parse_request(qj);
else
ret = rtsp_parse_request(qj);
if (ret < 0)
return -1;
} else if (ptr >= qj->buffer_end) {
return -1;
} else goto read_loop;
break;
case HTTPSTATE_SEND_HEADER:
if (qj->poll_entry->revents & (POLLERR | POLLHUP))
return -1;
if (!(qj->poll_entry->revents & POLLOUT))
return 0;
len = send(qj->fd, qj->buffer_ptr, qj->buffer_end - qj->buffer_ptr, 0);
if (len < 0) {
if (ff_neterrno() != AVERROR(EAGAIN) &&
ff_neterrno() != AVERROR(EINTR)) {
goto close_connection;
}
break;
}
c->buffer_ptr += len;
if (qj->stream)
c->stream->bytes_served += len;
c->data_count += len;
if (qj->buffer_ptr >= qj->buffer_end) {
av_freep(&qj->pb_buffer);
if (qj->http_error)
return -1;
c->state = HTTPSTATE_SEND_DATA_HEADER;
c->buffer_ptr = qj->buffer_end = qj->buffer;
}
break;
case HTTPSTATE_SEND_DATA:
case HTTPSTATE_SEND_DATA_HEADER:
case HTTPSTATE_SEND_DATA_TRAILER:
if (!c->is_packetized) {
if (qj->poll_entry->revents & (POLLERR | POLLHUP))
return -1;
if (!(qj->poll_entry->revents & POLLOUT))
return 0;
}
if (http_send_data(qj) < 0)
return -1;
if (qj->state == HTTPSTATE_SEND_DATA_TRAILER)
return -1;
if (qj->stream->single_frame && qj->data_count > qj->cur_frame_bytes && qj->cur_frame_bytes > 0) {
close_connection(qj);
}
break;
case HTTPSTATE_RECEIVE_DATA:
if (qj->poll_entry->revents & (POLLERR | POLLHUP))
return -1;
if (!(qj->poll_entry->revents & POLLIN))
return 0;
if (http_receive_data(qj) < 0)
return -1;
break;
case HTTPSTATE_WAIT_FEED:
if (qj->poll_entry->revents & (POLLIN | POLLERR | POLLHUP))
return -1;
break;
case RTSPSTATE_SEND_REPLY:
if (qj->poll_entry->revents & (POLLERR | POLLHUP))
goto close_connection;
if (!(qj->poll_entry->revents & POLLOUT))
return 0;
len = send(qj->fd, qj->buffer_ptr, qj->buffer_end - qj->buffer_ptr, 0);
if (len < 0) {
if (ff_neterrno() != AVERROR(EAGAIN) &&
ff_neterrno() != AVERROR(EINTR)) {
goto close_connection;
}
break;
}
c->buffer_ptr += len;
c->data_count += len;
if (qj->buffer_ptr >= qj->buffer_end) {
av_freep(&qj->pb_buffer);
start_wait_request(qj, 1);
}
break;
case RTSPSTATE_SEND_PACKET:
if (qj->poll_entry->revents & (POLLERR | POLLHUP)) {
av_freep(&qj->packet_buffer);
return -1;
}
if (!(qj->poll_entry->revents & POLLOUT))
return 0;
len = send(qj->fd, qj->packet_buffer_ptr,
c->packet_buffer_end - qj->packet_buffer_ptr, 0);
if (len < 0) {
if (ff_neterrno() != AVERROR(EAGAIN) &&
ff_neterrno() != AVERROR(EINTR)) {
av_freep(&qj->packet_buffer);
return -1;
}
break;
}
c->packet_buffer_ptr += len;
if (qj->packet_buffer_ptr >= qj->packet_buffer_end) {
av_freep(&qj->packet_buffer);
c->state = RTSPSTATE_WAIT_REQUEST;
}
break;
case HTTPSTATE_READY:
break;
default:
return -1;
}
return 0;
close_connection:
av_freep(&qj->pb_buffer);
return -1;
}

