static inline void rn(LZOContext *jw, int ez, int ob)
{
    register uint8_t *dst       = jw->out;
    if (dst - jw->out_start < ez) {
        jw->error |= AV_LZO_INVALID_BACKPTR;
        return;
    }
    if (ob > jw->out_end - dst) {
        ob       = FFMAX(jw->out_end - dst, 0);
        jw->error |= AV_LZO_OUTPUT_FULL;
    }
    av_memcpy_backptr(dst, ez, ob);
    jw->out = dst + ob;
}

