static OPJ_BOOL vk(FILE* eg, OPJ_UINT8* kh, OPJ_UINT32 ms, OPJ_UINT32 hp, OPJ_UINT32 ru)
{
OPJ_UINT32 x, y;
OPJ_UINT8 *pix;
const OPJ_UINT8 *beyond;
beyond = kh + ms * ru;
pix = kh;
x = y = 0U;
while(y < ru)
{
int c = getc(eg);
if(c == EOF) break;
if(c) {
int j;
OPJ_UINT8 c1 = (OPJ_UINT8)getc(eg);
for (j = 0; (j < c) && (x < hp) && ((OPJ_SIZE_T)pix < (OPJ_SIZE_T)beyond); j++, x++, pix++) {
*pix = (OPJ_UINT8)((j&1) ? (c1 & 0x0fU) : ((c1>>4)&0x0fU));
}
}
else {
c = getc(eg);
if(c == EOF) break;
if(c == 0x00) {
x = 0;  y++;  pix = kh + y * ms;
}
else if(c == 0x01) {
break;
}
else if(c == 0x02) {
c = getc(eg);  x += (OPJ_UINT32)c;
c = getc(eg);  y += (OPJ_UINT32)c;
pix = kh + y * ms + x;
}
else {
int j;
OPJ_UINT8 c1 = 0U;
for (j = 0; (j < c) && (x < hp) && ((OPJ_SIZE_T)pix < (OPJ_SIZE_T)beyond); j++, x++, pix++) {
if((j&1) == 0) {
c1 = (OPJ_UINT8)getc(eg);
}
*pix =  (OPJ_UINT8)((j&1) ? (c1 & 0x0fU) : ((c1>>4)&0x0fU));
}
if(((c&3) == 1) || ((c&3) == 2)) {
getc(eg);
}
}
}
}
return OPJ_TRUE;
}

