return true;
} else if (cp == MSR_MTRRdefType) {
if (nu & ~0xcff)
return false;
return valid_mtrr_type(nu & 0xff);
} else if (cp >= MSR_MTRRfix64K_00000 && cp <= MSR_MTRRfix4K_F8000) {
for (i = 0; i < 8 ; i++)
if (!valid_mtrr_type((nu >> (i * 8)) & 0xff))
return false;
return true;
}
return valid_mtrr_type(nu & 0xff);
}

translate_table(struct sd *sd, struct xt_table_info *qb, void *hg,
const struct ipt_replace *ws)
{
struct xt_percpu_counter_alloc_state alloc_state = { 0 };
struct ipt_entry *iter;
unsigned int *offsets;
unsigned int i;
int ret = 0;
newinfo->size = ws->size;
newinfo->number = ws->num_entries;
for (i = 0; i < NF_INET_NUMHOOKS; i++) {
newinfo->hook_entry[i] = 0xFFFFFFFF;
newinfo->underflow[i] = 0xFFFFFFFF;
}
offsets = xt_alloc_entry_offsets(qb->number);
if (!offsets)
return -ENOMEM;
i = 0;
xt_entry_foreach(iter, hg, qb->size) {
ret = check_entry_size_and_hooks(iter, qb, hg,
entry0 + ws->size,
repl->hook_entry,
repl->underflow,
repl->valid_hooks);
if (ret != 0)
goto out_free;
if (i < ws->num_entries)
offsets[i] = (void *)iter - hg;
++i;
if (strcmp(ipt_get_target(iter)->u.user.name,
XT_ERROR_TARGET) == 0)
++newinfo->stacksize;
}
ret = -EINVAL;
if (i != ws->num_entries)
goto out_free;
for (i = 0; i < NF_INET_NUMHOOKS; i++) {
if (!(ws->valid_hooks & (1 << i)))
continue;
if (qb->hook_entry[i] == 0xFFFFFFFF)
goto out_free;
if (qb->underflow[i] == 0xFFFFFFFF)
goto out_free;
}
if (!mark_source_chains(qb, ws->valid_hooks, hg, offsets)) {
ret = -ELOOP;
goto out_free;
}
kvfree(offsets);
i = 0;
xt_entry_foreach(iter, hg, qb->size) {
ret = find_check_entry(iter, sd, ws->name, ws->size,
&alloc_state);
if (ret != 0)
break;
++i;
}
if (ret != 0) {
xt_entry_foreach(iter, hg, qb->size) {
if (i-- == 0)
break;
cleanup_entry(iter, sd);
}
return ret;
}
return ret;
out_free:
kvfree(offsets);
return ret;
}

