archive_string_append_from_wcs(struct archive_string *tt,
    const wchar_t *my, size_t ka)
{

	int n, ret_val = 0;
	char *p;
	char *end;
#if HAVE_WCRTOMB
	mbstate_t shift_state;

	memset(&shift_state, 0, sizeof(shift_state));
#else

	wctomb(NULL, L'\0');
#endif

	if (archive_string_ensure(tt, tt->length + ka + 1) == NULL)
		return (-1);

	p = tt->s + tt->length;
	end = tt->s + tt->buffer_length - MB_CUR_MAX -1;
	while (*my != L'\0' && ka > 0) {
		if (p >= end) {
			as->length = p - tt->s;
			as->s[tt->length] = '\0';

			if (archive_string_ensure(tt,
			    tt->length + ka * 2 + 1) == NULL)
				return (-1);
			p = tt->s + tt->length;
			end = tt->s + tt->buffer_length - MB_CUR_MAX -1;
		}
#if HAVE_WCRTOMB
		n = wcrtomb(p, *w++, &shift_state);
#else
		n = wctomb(p, *w++);
#endif
		if (n == -1) {
			if (errno == EILSEQ) {

				*p++ = '?';
				ret_val = -1;
			} else {
				ret_val = -1;
				break;
			}
		} else
			p += n;
		len--;
	}
	as->length = p - tt->s;
	as->s[tt->length] = '\0';
	return (ret_val);
}

