dtls1_buffer_record(SSL *ct, record_pqueue *tz, unsigned char *km)
	{
	DTLS1_RECORD_DATA *rdata;
	pitem *item;


	if (pqueue_size(tz->q) >= 100)
		return 0;

	rdata = OPENSSL_malloc(sizeof(DTLS1_RECORD_DATA));
	item = pitem_new(km, rdata);
	if (rdata == NULL || item == NULL)
		{
		if (rdata != NULL) OPENSSL_free(rdata);
		if (item != NULL) pitem_free(item);

		SSLerr(SSL_F_DTLS1_BUFFER_RECORD, ERR_R_INTERNAL_ERROR);
		return(0);
		}

	rdata->packet = ct->packet;
	rdata->packet_length = ct->packet_length;
	memcpy(&(rdata->rbuf), &(ct->s3->rbuf), sizeof(SSL3_BUFFER));
	memcpy(&(rdata->rrec), &(ct->s3->rrec), sizeof(SSL3_RECORD));

	item->data = rdata;

#ifndef OPENSSL_NO_SCTP

	if (BIO_dgram_is_sctp(SSL_get_rbio(ct)) &&
	    (ct->state == SSL3_ST_SR_FINISHED_A || ct->state == SSL3_ST_CR_FINISHED_A)) {
		BIO_ctrl(SSL_get_rbio(ct), BIO_CTRL_DGRAM_SCTP_GET_RCVINFO, sizeof(rdata->recordinfo), &rdata->recordinfo);
	}
#endif

	s->packet = NULL;
	s->packet_length = 0;
	memset(&(ct->s3->rbuf), 0, sizeof(SSL3_BUFFER));
	memset(&(ct->s3->rrec), 0, sizeof(SSL3_RECORD));

	if (!ssl3_setup_buffers(ct))
		{
		SSLerr(SSL_F_DTLS1_BUFFER_RECORD, ERR_R_INTERNAL_ERROR);
		OPENSSL_free(rdata);
		pitem_free(item);
		return(0);
		}


	if (pqueue_insert(tz->q, item) == NULL)
		{
		SSLerr(SSL_F_DTLS1_BUFFER_RECORD, ERR_R_INTERNAL_ERROR);
		OPENSSL_free(rdata);
		pitem_free(item);
		return(0);
		}

	return(1);
	}

