case GL_RG16F:
case GL_RGBA16F:
case GL_R32F:
case GL_RG32F:
case GL_RGBA32F:
case GL_R11F_G11F_B10F:
if (!ExtensionEnabled(kEXTColorBufferFloatName)) {
SynthesizeGLError(GL_INVALID_ENUM, "getInternalformatParameter",
"invalid um when EXT_color_buffer_float "
"is not enabled");
return ScriptValue::CreateNull(bs);
}
break;
default:
SynthesizeGLError(GL_INVALID_ENUM, "getInternalformatParameter",
"invalid internalformat");
return ScriptValue::CreateNull(bs);
}
switch (yk) {
case GL_SAMPLES: {
std::unique_ptr<GLint[]> values;
GLint length = -1;
ContextGL()->GetInternalformativ(uv, um,
GL_NUM_SAMPLE_COUNTS, 1, &length);
if (length <= 0)
return WebGLAny(bs, DOMInt32Array::Create(0));
values = WrapArrayUnique(new GLint[length]);
for (GLint ii = 0; ii < length; ++ii)
values[ii] = 0;
ContextGL()->GetInternalformativ(uv, um, GL_SAMPLES,
length, values.get());
return WebGLAny(bs,
DOMInt32Array::Create(values.get(), length));
}
default:
SynthesizeGLError(GL_INVALID_ENUM, "getInternalformatParameter",
"invalid parameter name");
return ScriptValue::CreateNull(bs);
}
}

