		vim_free(((int **)gap->ga_data)[i]);
    }
    else

	while (gap->ga_len > 0)
	{
	    smp = &((salitem_T *)gap->ga_data)[--gap->ga_len];
	    vim_free(smp->sm_lead);

	    vim_free(smp->sm_to);
	    vim_free(smp->sm_lead_w);
	    vim_free(smp->sm_oneof_w);
	    vim_free(smp->sm_to_w);
	}
    ga_clear(gap);

    for (i = 0; i < el->sl_prefixcnt; ++i)
	vim_regfree(el->sl_prefprog[i]);
    el->sl_prefixcnt = 0;
    VIM_CLEAR(el->sl_prefprog);

    VIM_CLEAR(el->sl_info);

    VIM_CLEAR(el->sl_midword);

    vim_regfree(el->sl_compprog);
    el->sl_compprog = NULL;
    VIM_CLEAR(el->sl_comprules);
    VIM_CLEAR(el->sl_compstartflags);
    VIM_CLEAR(el->sl_compallflags);

    VIM_CLEAR(el->sl_syllable);
