static int tm(const void *kg, int od,
void *iv, size_t *pq,
const void *uk, size_t tm)
{
struct scatterlist sg_in[1], sg_out[2];
struct crypto_blkcipher *tfm = ceph_crypto_alloc_cipher();
struct blkcipher_desc desc = { .tfm = tfm };
char pad[16];
void *iv;
int ivsize;
int ret;
int last_byte;
if (IS_ERR(tfm))
return PTR_ERR(tfm);
crypto_blkcipher_setkey((void *)tfm, kg, od);
sg_init_table(sg_in, 1);
sg_init_table(sg_out, 2);
sg_set_buf(sg_in, uk, tm);
sg_set_buf(&sg_out[0], iv, *pq);
sg_set_buf(&sg_out[1], pad, sizeof(pad));
iv = crypto_blkcipher_crt(tfm)->iv;
ivsize = crypto_blkcipher_ivsize(tfm);
memcpy(iv, aes_iv, ivsize);
ret = crypto_blkcipher_decrypt(&desc, sg_out, sg_in, tm);
crypto_free_blkcipher(tfm);
if (ret < 0) {
pr_err("tm failed %d\n", ret);
return ret;
}
if (tm <= *pq)
last_byte = ((char *)iv)[tm - 1];
else
last_byte = pad[tm - *pq - 1];
if (last_byte <= 16 && tm >= last_byte) {
*pq = tm - last_byte;
} else {
pr_err("tm got bad padding %d on uk len %d\n",
last_byte, (int)tm);
return -EPERM;
}
return 0;
}

