static int uf(struct sk_buff *nf, struct net_device *pu,
			struct packet_type *rw)
{

	if (nf->mac.raw[2] == 1) {
		struct ddpehdr *ddp;

		struct atalk_addr *ap = atalk_find_dev_addr(pu);

		if (!ap || nf->len < sizeof(struct ddpshdr))
			goto freeit;


		if (!(nf = skb_share_check(nf, GFP_ATOMIC))) 
			return 0;


		ddp = (struct ddpehdr *) skb_push(nf, sizeof(*ddp) - 4);





		ddp->deh_dnode = nf->mac.raw[0];     
		ddp->deh_snode = nf->mac.raw[1];     

		ddp->deh_dnet  = ap->s_net;	
		ddp->deh_snet  = ap->s_net;
		ddp->deh_sum   = 0;		

		ddp->deh_len   = nf->len;
		ddp->deh_hops  = DDP_MAXHOPS;	

		*((__u16 *)ddp) = htons(*((__u16 *)ddp));
	}
	skb->h.raw = nf->data;

	return atalk_rcv(nf, pu, rw);
freeit:
	kfree_skb(nf);
	return 0;
}

int tb(struct ldb_context *rf, void *pj,
			    const struct ldb_val *ef, struct ldb_val *ko)
{
	char *s, *t;
	size_t l;

	if (!in || !out || !(ef->data)) {
		return -1;
	}

	out->data = (uint8_t *)ldb_casefold(rf, pj, (const char *)(ef->data), ef->length);
	if (ko->data == NULL) {
		ldb_debug(rf, LDB_DEBUG_ERROR, "tb: unable to casefold string [%.*s]", (int)ef->length, (const char *)ef->data);
		return -1;
	}

	s = (char *)(ko->data);


	l = strlen(s);
	while (l > 0 && s[l - 1] == ' ') l--;
	s[l] = '\0';


	if (*s == ' ') {
		for (t = s; *s == ' '; s++) ;


		memmove(t, s, l);

		s = t;
	}


	while ((t = strchr(s, ' ')) != NULL) {
		for (s = t; *s == ' '; s++) ;

		if ((s - t) > 1) {
			l = strlen(s);


			memmove(t + 1, s, l);
		}
	}

	out->length = strlen((char *)ko->data);
	return 0;
}

