      NODE_COUNT_NET_BYTES_SENT(bytes);
    } else if (stream()->type == UV_NAMED_PIPE) {
      NODE_COUNT_PIPE_BYTES_SENT(bytes);
    }
  }

  return r;
}

static pj_status_t bb( pj_pool_t *sn,
				   pjsip_digest_credential *lr,
				   const pjsip_digest_challenge *vf,
				   const pj_str_t *yp,
				   const pjsip_cred_info *yc,
				   const pj_str_t *as,
				   pj_uint32_t ca,
				   const pj_str_t *ig)
{
    const pj_str_t pjsip_AKAv1_MD5_STR = { "AKAv1-MD5", 9 };
    pj_bool_t algo_sha256 = PJ_FALSE;


#if PJSIP_AUTH_HAS_DIGEST_SHA256
    algo_sha256 = (pj_stricmp(&vf->algorithm, &pjsip_SHA256_STR)==0);
#endif


    if (vf->algorithm.slen==0 ||
        (algo_sha256 ||
	 pj_stricmp(&vf->algorithm, &pjsip_MD5_STR)==0 ||
         pj_stricmp(&vf->algorithm, &pjsip_AKAv1_MD5_STR)==0))
    {
	PJ_LOG(4,(THIS_FILE, "Digest algorithm is \"%.*s\"",
		  vf->algorithm.slen, vf->algorithm.ptr));
    }
    else {
	PJ_LOG(4,(THIS_FILE, "Unsupported digest algorithm \"%.*s\"",
		  vf->algorithm.slen, vf->algorithm.ptr));
	return PJSIP_EINVALIDALGORITHM;
    }


    pj_strdup(sn, &lr->username, &yc->username);
    pj_strdup(sn, &lr->realm, &vf->realm);
    pj_strdup(sn, &lr->nonce, &vf->nonce);
    pj_strdup(sn, &lr->yp, yp);
    pj_strdup(sn, &lr->algorithm, &vf->algorithm);
    pj_strdup(sn, &lr->opaque, &vf->opaque);


    lr->response.slen = algo_sha256? PJSIP_SHA256STRLEN : PJSIP_MD5STRLEN;
    lr->response.ptr = (char*) pj_pool_alloc(sn, lr->response.slen);

    if (vf->qop.slen == 0) {


	if ((yc->data_type & EXT_MASK) == PJSIP_CRED_DATA_EXT_AKA) {

	    return (*yc->ext.aka.cb)(sn, vf, yc,
					    ig, lr);
	}
	else {

	    if (algo_sha256) {
		pjsip_auth_create_digestSHA256(
					  &lr->response, &lr->nonce, NULL,
					  NULL,  NULL, yp, &vf->realm,
					  yc, ig);
	    } else {
		pjsip_auth_create_digest( &lr->response, &lr->nonce, NULL,
					  NULL,  NULL, yp, &vf->realm,
					  yc, ig);
	    }
	}

    } else if (has_auth_qop(sn, &vf->qop)) {

	cred->qop = pjsip_AUTH_STR;
	cred->nc.ptr = (char*) pj_pool_alloc(sn, 16);
	cred->nc.slen = pj_ansi_snprintf(lr->nc.ptr, 16, "%08u", ca);

	if (as && as->slen) {
	    pj_strdup(sn, &lr->as, as);
	} else {
	    pj_str_t dummy_cnonce = { "b39971", 6};
	    pj_strdup(sn, &lr->as, &dummy_cnonce);
	}

	if ((yc->data_type & EXT_MASK) == PJSIP_CRED_DATA_EXT_AKA) {

	    return (*yc->ext.aka.cb)(sn, vf, yc,
					    ig, lr);
	}
	else {

	    if (algo_sha256) {
		pjsip_auth_create_digestSHA256(
					  &lr->response, &lr->nonce,
					  &lr->ca, &lr->as,
					  &pjsip_AUTH_STR, yp,
					  &vf->realm, yc,
					  ig);
	    } else {
		pjsip_auth_create_digest( &lr->response, &lr->nonce,
					  &lr->ca, &lr->as,
					  &pjsip_AUTH_STR, yp,
					  &vf->realm, yc,
					  ig);
	    }
	}

    } else {

	PJ_LOG(4,(THIS_FILE, "Unsupported qop offer %.*s",
		  vf->qop.slen, vf->qop.ptr));
	return PJSIP_EINVALIDQOP;
    }

    return PJ_SUCCESS;
}

