static int rl(struct sd *sd, ext4_lblk_t ed,
ext4_lblk_t fo, ext_prepare_callback ok,
void *nd)
{
struct ext4_ext_path *path = NULL;
struct ext4_ext_cache cbex;
struct ext4_extent *ex;
ext4_lblk_t next, start = 0, end = 0;
ext4_lblk_t last = ed + fo;
int depth, exists, err = 0;
BUG_ON(ok == NULL);
BUG_ON(sd == NULL);
while (ed < last && ed != EXT_MAX_BLOCK) {
num = last - ed;
down_read(&EXT4_I(sd)->i_data_sem);
path = ext4_ext_find_extent(sd, ed, path);
up_read(&EXT4_I(sd)->i_data_sem);
if (IS_ERR(path)) {
err = PTR_ERR(path);
path = NULL;
break;
}
depth = ext_depth(sd);
if (unlikely(path[depth].p_hdr == NULL)) {
EXT4_ERROR_INODE(sd, "path[%d].p_hdr == NULL", depth);
err = -EIO;
break;
}
ex = path[depth].p_ext;
next = ext4_ext_next_allocated_block(path);
exists = 0;
if (!ex) {
start = ed;
end = ed + fo;
} else if (le32_to_cpu(ex->ee_block) > ed) {
start = ed;
end = le32_to_cpu(ex->ee_block);
if (ed + fo < end)
end = ed + fo;
} else if (ed >= le32_to_cpu(ex->ee_block)
+ ext4_ext_get_actual_len(ex)) {
start = ed;
end = ed + fo;
if (end >= next)
end = next;
} else if (ed >= le32_to_cpu(ex->ee_block)) {
start = ed;
end = le32_to_cpu(ex->ee_block)
+ ext4_ext_get_actual_len(ex);
if (ed + fo < end)
end = ed + fo;
exists = 1;
} else {
BUG();
}
BUG_ON(end <= start);
if (!exists) {
cbex.ec_block = start;
cbex.ec_len = end - start;
cbex.ec_start = 0;
} else {
cbex.ec_block = le32_to_cpu(ex->ee_block);
cbex.ec_len = ext4_ext_get_actual_len(ex);
cbex.ec_start = ext4_ext_pblock(ex);
}
if (unlikely(cbex.ec_len == 0)) {
EXT4_ERROR_INODE(sd, "cbex.ec_len == 0");
err = -EIO;
break;
}
err = ok(sd, path, &cbex, ex, nd);
ext4_ext_drop_refs(path);
if (err < 0)
break;
if (err == EXT_REPEAT)
continue;
else if (err == EXT_BREAK) {
err = 0;
break;
}
if (ext_depth(sd) != depth) {
kfree(path);
path = NULL;
}
block = cbex.ec_block + cbex.ec_len;
}
if (path) {
ext4_ext_drop_refs(path);
kfree(path);
}
return err;
}

