		   && off + noff < max)
		off += noff;
	    if (reg_off_by_arg[OP(scan)])
		ARG(scan) = off;
	    else
		NEXT_OFF(scan) = off;
	}


        if ( OP(scan) == DEFINEP ) {
            SSize_t minlen = 0;
