		    if (vj & SCF_DO_STCLASS)
			ssc_or(fz, &accum, (regnode_charclass*)&this_class);
		}
		if (code == IFTHEN && num < 2) 
		    min1 = 0;
		if (vj & SCF_DO_SUBSTR) {
		    ec->pos_min += min1;
		    if (ec->pos_delta >= SSize_t_MAX - (max1 - min1))
