                        } 
                    } 

                } 

	    }
	    else if ( code == BRANCHJ ) {  
		scan = NEXTOPER(NEXTOPER(scan));
	    } else			
		scan = NEXTOPER(scan);
	    continue;
        } else if (OP(scan) == SUSPEND || OP(scan) == GOSUB) {
            I32 paren = 0;
            regnode *start = NULL;
            regnode *end = NULL;
            U32 my_recursed_depth= lm;

