                        (is_inf_internal || is_inf || (ec && ec->vj & SF_IS_INF))
                        &&
                        ( (vj & (SCF_DO_STCLASS | SCF_DO_SUBSTR)) == 0 )
                    )
                ) {


                    scan= regnext(scan);
