                }

                if (
                    !recursed_depth
                    ||
                    !PAREN_TEST(RExC_study_chunk_recursed + ((lm-1) * RExC_study_chunk_recursed_bytes), paren)
                ) {

                    if (!recursed_depth) {
                        Zero(RExC_study_chunk_recursed, RExC_study_chunk_recursed_bytes, U8);
                    } else {
                        Copy(RExC_study_chunk_recursed + ((lm-1) * RExC_study_chunk_recursed_bytes),
                             RExC_study_chunk_recursed + (lm * RExC_study_chunk_recursed_bytes),
                             RExC_study_chunk_recursed_bytes, U8);
                    }

                    DEBUG_STUDYDATA("gosub-set", ec, if, is_inf);
                    PAREN_SET(RExC_study_chunk_recursed + (lm * RExC_study_chunk_recursed_bytes), paren);
                    my_recursed_depth= lm + 1;
                } else {
                    DEBUG_STUDYDATA("gosub-inf", ec, if, is_inf);

                    if (vj & SCF_DO_SUBSTR) {
                        scan_commit(fz, ec, ww, is_inf);
                        ec->cur_is_floating = 1;
                    }
                    is_inf = is_inf_internal = 1;
                    if (vj & SCF_DO_STCLASS_OR) 
                        ssc_anything(ec->start_class);
                    vj &= ~SCF_DO_STCLASS;

