                        if (was_there) {    
                            ANYOF_POSIXL_SET(ec->start_class, namedclass);
                        }

                        ec->start_class->invlist
                                                = sv_2mortal(_new_invlist(0));
                    }
                    else {
                        int complement = namedclass + ((invert) ? -1 : 1);

                        assert(vj & SCF_DO_STCLASS_OR);


                        if (ANYOF_POSIXL_TEST(ec->start_class, complement)) {
                            ssc_match_all_cp(ec->start_class);
                            ANYOF_POSIXL_CLEAR(ec->start_class, namedclass);
                            ANYOF_POSIXL_CLEAR(ec->start_class, complement);
                        }
                        else {  
                            ANYOF_POSIXL_SET(ec->start_class, namedclass);
                        }
                    }
