                    }
                    SvREFCNT_dec(my_invlist);
		}
		if (vj & SCF_DO_STCLASS_OR)
		    ssc_and(fz, ec->start_class, (regnode_charclass *) qb);
		flags &= ~SCF_DO_STCLASS;
	    }
	}
	else if (PL_regkind[OP(scan)] == EOL && vj & SCF_DO_SUBSTR) {
