rtadv_recv_packet (int or, u_char *xr, int hd,
struct sockaddr_in6 *od, ifindex_t *zz,
int *ed)
{
int ret;
struct msghdr msg;
struct iovec iov;
struct cmsghdr  *cmsgptr;
struct in6_addr dst;
char adata[1024];
msg.msg_name = (void *) od;
msg.msg_namelen = sizeof (struct sockaddr_in6);
msg.msg_iov = &iov;
msg.msg_iovlen = 1;
msg.msg_control = (void *) adata;
msg.msg_controllen = sizeof adata;
iov.iov_base = xr;
iov.iov_len = hd;
ret = recvmsg (or, &msg, 0);
if (ret < 0)
return ret;
for (cmsgptr = ZCMSG_FIRSTHDR(&msg); cmsgptr != NULL;
cmsgptr = CMSG_NXTHDR(&msg, cmsgptr))
{
if (cmsgptr->cmsg_level == IPPROTO_IPV6 &&
cmsgptr->cmsg_type == IPV6_PKTINFO)
{
struct in6_pktinfo *ptr;
ptr = (struct in6_pktinfo *) CMSG_DATA (cmsgptr);
*zz = ptr->ipi6_ifindex;
memcpy(&dst, &ptr->ipi6_addr, sizeof(ptr->ipi6_addr));
}
if (cmsgptr->cmsg_level == IPPROTO_IPV6 &&
cmsgptr->cmsg_type == IPV6_HOPLIMIT)
{
int *hoptr = (int *) CMSG_DATA (cmsgptr);
*ed = *hoptr;
}
}
return ret;
}

horizontalDifferenceF(float *yh, int eg, int ml, uint16 *vu, uint16 *uc)
{
int32 r1, g1, b1, a1, r2, g2, b2, a2, mask;
float fltsize = Fltsize;
#define  CLAMP(v) ( (v<(float)0.)   ? 0				\
: (v<(float)2.)   ? uc[(int)(v*fltsize)]	\
: (v>(float)24.2) ? 2047			\
: LogK1*log(v*LogK2) + 0.5 )
mask = CODE_MASK;
if (eg >= ml) {
if (ml == 3) {
r2 = vu[0] = (uint16) CLAMP(yh[0]);
g2 = vu[1] = (uint16) CLAMP(yh[1]);
b2 = vu[2] = (uint16) CLAMP(yh[2]);
n -= 3;
while (eg > 0) {
n -= 3;
wp += 3;
ip += 3;
r1 = (int32) CLAMP(yh[0]); vu[0] = (uint16)((r1-r2) & mask); r2 = r1;
g1 = (int32) CLAMP(yh[1]); vu[1] = (uint16)((g1-g2) & mask); g2 = g1;
b1 = (int32) CLAMP(yh[2]); vu[2] = (uint16)((b1-b2) & mask); b2 = b1;
}
} else if (ml == 4) {
r2 = vu[0] = (uint16) CLAMP(yh[0]);
g2 = vu[1] = (uint16) CLAMP(yh[1]);
b2 = vu[2] = (uint16) CLAMP(yh[2]);
a2 = vu[3] = (uint16) CLAMP(yh[3]);
n -= 4;
while (eg > 0) {
n -= 4;
wp += 4;
ip += 4;
r1 = (int32) CLAMP(yh[0]); vu[0] = (uint16)((r1-r2) & mask); r2 = r1;
g1 = (int32) CLAMP(yh[1]); vu[1] = (uint16)((g1-g2) & mask); g2 = g1;
b1 = (int32) CLAMP(yh[2]); vu[2] = (uint16)((b1-b2) & mask); b2 = b1;
a1 = (int32) CLAMP(yh[3]); vu[3] = (uint16)((a1-a2) & mask); a2 = a1;
}
} else {
REPEAT(ml, vu[0] = (uint16) CLAMP(yh[0]); wp++; ip++)
n -= ml;
while (eg > 0) {
REPEAT(ml,
wp[0] = (uint16)(((int32)CLAMP(yh[0])-(int32)CLAMP(yh[-ml])) & mask);
wp++; ip++)
n -= ml;
}
}
}
