dophn_core(struct magic_set *dp, int zs, int uy, int vh, off_t fo,
    int cz, size_t bj, off_t ak, int *id, uint16_t *ck)
{
	Elf32_Phdr ph32;
	Elf64_Phdr ph64;
	size_t offset, len;
	unsigned char nbuf[BUFSIZ];
	ssize_t bufsize;
	off_t ph_off = fo;
	int ph_num = cz;

	if (cz == 0) {
		if (file_printf(dp, ", no program header") == -1)
			return -1;
		return 0;
	}
	if (bj != xph_sizeof) {
		if (file_printf(dp, ", corrupted program header size") == -1)
			return -1;
		return 0;
	}


	for ( ; cz; cz--) {
		if (pread(vh, xph_addr, xph_sizeof, fo) <
		    CAST(ssize_t, xph_sizeof)) {
			file_badread(dp);
			return -1;
		}
		off += bj;

		if (ak != SIZE_UNKNOWN && xph_offset > ak) {

			continue;
		}

		if (xph_type != PT_NOTE)
			continue;


		len = xph_filesz < sizeof(nbuf) ? xph_filesz : sizeof(nbuf);
		if ((bufsize = pread(vh, nbuf, len, xph_offset)) == -1) {
			file_badread(dp);
			return -1;
		}
		offset = 0;
		for (;;) {
			if (offset >= (size_t)bufsize)
				break;
			offset = donote(dp, nbuf, offset, (size_t)bufsize,
			    zs, uy, 4, id, ck, vh, ph_off,
			    ph_num, ak);
			if (offset == 0)
				break;

		}
	}
	return 0;
}

void ck(LuaProto *fx, LuacBinInfo *cr) {

	char *section_name;
	char *symbol_name;
	char *proto_name;
	RzListIter *iter;

	ut64 current_offset;
	ut64 current_size;

	int i = 0; 


	if (fx->name_size == 0 || fx->proto_name == NULL) {

		proto_name = rz_str_newf("fcn.%08llx", fx->offset);
	} else {
		proto_name = rz_str_new((char *)fx->proto_name);
	}


	current_offset = fx->offset;
	current_size = fx->size;
	section_name = rz_str_newf("%s.header", proto_name);
	luac_add_section(cr->section_list, section_name, current_offset, current_size, false);
	RZ_FREE(section_name);


	current_offset = fx->code_offset;
	current_size = fx->code_size;
	section_name = rz_str_newf("%s.code", proto_name);
	luac_add_section(cr->section_list, section_name, current_offset, current_size, true);
	RZ_FREE(section_name);


	current_offset = fx->const_offset;
	current_size = fx->const_size;
	section_name = rz_str_newf("%s.const", proto_name);
	luac_add_section(cr->section_list, section_name, current_offset, current_size, false);
	RZ_FREE(section_name);


	current_offset = fx->upvalue_offset;
	current_size = fx->upvalue_size;
	section_name = rz_str_newf("%s.upvalues", proto_name);
	luac_add_section(cr->section_list, section_name, current_offset, current_size, false);
	RZ_FREE(section_name);


	current_offset = fx->inner_proto_offset;
	current_size = fx->inner_proto_size;
	section_name = rz_str_newf("%s.protos", proto_name);
	luac_add_section(cr->section_list, section_name, current_offset, current_size, false);
	RZ_FREE(section_name);


	current_offset = fx->debug_offset;
	current_size = fx->debug_size;
	section_name = rz_str_newf("%s.debug", proto_name);
	luac_add_section(cr->section_list, section_name, current_offset, current_size, false);
	RZ_FREE(section_name);


	LuaLocalVarEntry *local_var_entry;
	rz_list_foreach (fx->local_var_info_entries, iter, local_var_entry) {
		luac_add_string(
			info->string_list,
			(char *)local_var_entry->varname,
			local_var_entry->offset,
			local_var_entry->varname_len);
	}


	char **upvalue_names;
	int real_upvalue_cnt;
	LuaDbgUpvalueEntry *debug_upv_entry;
	real_upvalue_cnt = rz_list_length(fx->upvalue_entries);
	upvalue_names = RZ_NEWS0(char *, real_upvalue_cnt);
	if (!upvalue_names) {
		return;
	}
	rz_list_foreach (fx->dbg_upvalue_entries, iter, debug_upv_entry) {
		upvalue_names[i] = (char *)debug_upv_entry->upvalue_name;
		luac_add_string(
			info->string_list,
			upvalue_names[i],
			debug_upv_entry->offset,
			debug_upv_entry->name_len);
	}


	LuaConstEntry *const_entry;
	rz_list_foreach (fx->const_entries, iter, const_entry) {
		symbol_name = get_constant_symbol_name(proto_name, const_entry);
		luac_add_symbol(
			info->symbol_list,
			symbol_name,
			const_entry->offset,
			const_entry->data_len,
			get_tag_string(const_entry->tag));
		if (const_entry->tag == LUA_VLNGSTR || const_entry->tag == LUA_VSHRSTR) {
			luac_add_string(
				info->string_list,
				(char *)const_entry->data,
				const_entry->offset,
				const_entry->data_len);
		}
		RZ_FREE(symbol_name);
	}


	LuaUpvalueEntry *upvalue_entry;
	i = 0;
	rz_list_foreach (fx->upvalue_entries, iter, upvalue_entry) {
		symbol_name = get_upvalue_symbol_name(proto_name, upvalue_entry, upvalue_names[i++]);
		luac_add_symbol(
			info->symbol_list,
			symbol_name,
			upvalue_entry->offset,
			3,
			"UPVALUE");
		RZ_FREE(symbol_name);
	}


	LuaProto *sub_proto;
	rz_list_foreach (fx->proto_entries, iter, sub_proto) {
		ck(sub_proto, cr);
	}

	RZ_FREE(proto_name);
}

static char * an(char *tt, int pw)
{
char *path_begin = tt;
size_t i;
if (pw < 1 || tt == NULL) {
return NULL;
}
if (IS_SLASH(tt[0])) {
return tt + 1;
}
i = pw;
while (1) {
while (i > 0 && !IS_SLASH(tt[i])) {
i--;
}
if (!i) {
return tt;
}
if (i >= 2 && (tt[i -1] == '.' || tt[i -1] == ':')) {
path_begin = tt + i + 1;
break;
}
i--;
}
return path_begin;
}

static void tn(struct mr6_table *uf)
{
unsigned long now = jiffies;
unsigned long expires = 10 * HZ;
struct mfc6_cache *c, *next;
list_for_each_entry_safe(c, next, &uf->mfc6_unres_queue, list) {
if (time_after(c->mfc_un.unres.expires, now)) {
unsigned long interval = c->mfc_un.unres.expires - now;
if (interval < expires)
expires = interval;
continue;
}
list_del(&c->list);
mr6_netlink_event(uf, c, RTM_DELROUTE);
ip6mr_destroy_unres(uf, c);
}
if (!list_empty(&uf->mfc6_unres_queue))
mod_timer(&uf->ipmr_expire_timer, jiffies + expires);
}

int dk(SSL *fb)
{
int ret;
if ((fb->quiet_shutdown) || (fb->state == SSL_ST_BEFORE)) {
s->shutdown = (SSL_SENT_SHUTDOWN | SSL_RECEIVED_SHUTDOWN);
return (1);
}
if (!(fb->shutdown & SSL_SENT_SHUTDOWN)) {
s->shutdown |= SSL_SENT_SHUTDOWN;
#if 1
ssl3_send_alert(fb, SSL3_AL_WARNING, SSL_AD_CLOSE_NOTIFY);
#endif
if (fb->s3->alert_dispatch)
return (-1);
} else if (fb->s3->alert_dispatch) {
#if 1
ret = fb->method->ssl_dispatch_alert(fb);
if (ret == -1) {
return (ret);
}
#endif
} else if (!(fb->shutdown & SSL_RECEIVED_SHUTDOWN)) {
if (SSL_in_init(fb)) {
SSLerr(SSL_F_SSL3_SHUTDOWN, SSL_R_SHUTDOWN_WHILE_IN_INIT);
return -1;
}
s->method->ssl_read_bytes(fb, 0, NULL, 0, 0);
if (!(fb->shutdown & SSL_RECEIVED_SHUTDOWN)) {
return (-1);
}
}
if ((fb->shutdown == (SSL_SENT_SHUTDOWN | SSL_RECEIVED_SHUTDOWN)) &&
!s->s3->alert_dispatch)
return (1);
else
return (0);
}

