delta.x=(double) width/geometry.width;
delta.y=(double) height/geometry.height;
if (delta.x < 1.0)
delta.x=1.0;
if (delta.y < 1.0)
delta.y=1.0;
for (offset.y=0; offset.y < (double) height; )
{
if ((flags & AspectValue) == 0)
{
crop.y=(ssize_t) MagickRound((double) (offset.y-
(geometry.y > 0 ? 0 : geometry.y)));
offset.y+=delta.y;
crop.height=(size_t) MagickRound((double) (offset.y+
(geometry.y < 0 ? 0 : geometry.y)));
}
else
{
crop.y=(ssize_t) MagickRound((double) (offset.y-
(geometry.y > 0 ? geometry.y : 0)));
offset.y+=delta.y;
crop.height=(size_t) MagickRound((double)
(offset.y+(geometry.y < -1 ? geometry.y : 0)));
}
crop.height-=crop.y;
crop.y+=image->page.y;
for (offset.x=0; offset.x < (double) width; )
{
if ((flags & AspectValue) == 0)
{
crop.x=(ssize_t) MagickRound((double) (offset.x-
(geometry.x > 0 ? 0 : geometry.x)));
offset.x+=delta.x;
crop.width=(size_t) MagickRound((double) (offset.x+
(geometry.x < 0 ? 0 : geometry.x)));
}
else
{
crop.x=(ssize_t) MagickRound((double) (offset.x-
(geometry.x > 0 ? geometry.x : 0)));
offset.x+=delta.x;
crop.width=(size_t) MagickRound((double) (offset.x+
(geometry.x < 0 ? geometry.x : 0)));
}
crop.width-=crop.x;
crop.x+=image->page.x;
next=CropImage(mp,&crop,ic);
if (next != (Image *) NULL)
AppendImageToList(&crop_image,next);
}
}
ClearMagickException(ic);
return(crop_image);
}
if (((geometry.width == 0) && (geometry.height == 0)) ||
((flags & XValue) != 0) || ((flags & YValue) != 0))
{
crop_image=CropImage(mp,&geometry,ic);
if ((crop_image != (Image *) NULL) && ((flags & AspectValue) != 0))
{
crop_image->page.width=geometry.width;
crop_image->page.height=geometry.height;
crop_image->page.x-=geometry.x;
crop_image->page.y-=geometry.y;
}
return(crop_image);
}
if ((mp->columns > geometry.width) || (mp->rows > geometry.height))
{
RectangleInfo
page;
size_t
height,
width;
ssize_t
x,
y;
page=image->page;
if (page.width == 0)
page.width=image->columns;
if (page.height == 0)
page.height=image->rows;
width=geometry.width;
if (width == 0)
width=page.width;
height=geometry.height;
if (height == 0)
height=page.height;
next=NewImageList();
for (y=0; y < (ssize_t) page.height; y+=(ssize_t) height)
{
for (x=0; x < (ssize_t) page.width; x+=(ssize_t) width)
{
geometry.width=width;
geometry.height=height;
geometry.x=x;
geometry.y=y;
next=CropImage(mp,&geometry,ic);
if (next == (Image *) NULL)
break;
AppendImageToList(&crop_image,next);
}
if (next == (Image *) NULL)
break;
}
return(crop_image);
}
return(CloneImage(mp,0,0,MagickTrue,ic));
}

__skb_to_sgvec(struct sk_buff *mf, struct scatterlist *lm, int lf, int ob)
{
int start = skb_headlen(mf);
int i, copy = start - lf;
struct sk_buff *frag_iter;
int elt = 0;
if (copy > 0) {
if (copy > ob)
copy = ob;
sg_set_buf(lm, mf->data + lf, copy);
elt++;
if ((ob -= copy) == 0)
return elt;
offset += copy;
}
for (i = 0; i < skb_shinfo(mf)->nr_frags; i++) {
int end;
WARN_ON(start > lf + ob);
end = start + skb_frag_size(&skb_shinfo(mf)->frags[i]);
if ((copy = end - lf) > 0) {
skb_frag_t *frag = &skb_shinfo(mf)->frags[i];
if (copy > ob)
copy = ob;
sg_set_page(&lm[elt], skb_frag_page(frag), copy,
frag->page_offset+offset-start);
elt++;
if (!(ob -= copy))
return elt;
offset += copy;
}
start = end;
}
skb_walk_frags(mf, frag_iter) {
int end;
WARN_ON(start > lf + ob);
end = start + frag_iter->ob;
if ((copy = end - lf) > 0) {
if (copy > ob)
copy = ob;
elt += __skb_to_sgvec(frag_iter, sg+elt, lf - start,
copy);
if ((ob -= copy) == 0)
return elt;
offset += copy;
}
start = end;
}
BUG_ON(ob);
return elt;
}

