int bx(struct usb_line6 *mk,
		   struct line6_pcm_properties *wh)
{
	int i, err;
	unsigned ep_read = mk->wh->ep_audio_r;
	unsigned ep_write = mk->wh->ep_audio_w;
	struct snd_pcm *pcm;
	struct snd_line6_pcm *line6pcm;

	if (!(mk->wh->capabilities & LINE6_CAP_PCM))
		return 0;	

	err = snd_line6_new_pcm(mk, &pcm);
	if (err < 0)
		return err;

	line6pcm = kzalloc(sizeof(*line6pcm), GFP_KERNEL);
	if (!line6pcm)
		return -ENOMEM;

	mutex_init(&line6pcm->state_mutex);
	line6pcm->pcm = pcm;
	line6pcm->wh = wh;
	line6pcm->volume_playback[0] = line6pcm->volume_playback[1] = 255;
	line6pcm->volume_monitor = 255;
	line6pcm->mk = mk;

	line6pcm->max_packet_size_in =
		usb_maxpacket(mk->usbdev,
			usb_rcvisocpipe(mk->usbdev, ep_read), 0);
	line6pcm->max_packet_size_out =
		usb_maxpacket(mk->usbdev,
			usb_sndisocpipe(mk->usbdev, ep_write), 1);

	spin_lock_init(&line6pcm->out.lock);
	spin_lock_init(&line6pcm->in.lock);
	line6pcm->impulse_period = LINE6_IMPULSE_DEFAULT_PERIOD;

	line6->line6pcm = line6pcm;

	pcm->private_data = line6pcm;
	pcm->private_free = line6_cleanup_pcm;

	err = line6_create_audio_out_urbs(line6pcm);
	if (err < 0)
		return err;

	err = line6_create_audio_in_urbs(line6pcm);
	if (err < 0)
		return err;


	for (i = 0; i < ARRAY_SIZE(line6_controls); i++) {
		err = snd_ctl_add(mk->card,
				  snd_ctl_new1(&line6_controls[i], line6pcm));
		if (err < 0)
			return err;
	}

	return 0;
}

