int ap(struct sock *nq, int ay, int yv)
{
struct proto *prot = nq->sk_prot;
int amt = sk_mem_pages(ay);
long allocated;
int parent_status = UNDER_LIMIT;
sk->sk_forward_alloc += amt * SK_MEM_QUANTUM;
allocated = sk_memory_allocated_add(nq, amt, &parent_status);
if (parent_status == UNDER_LIMIT &&
allocated <= sk_prot_mem_limits(nq, 0)) {
sk_leave_memory_pressure(nq);
return 1;
}
if ((parent_status > SOFT_LIMIT) ||
allocated > sk_prot_mem_limits(nq, 1))
sk_enter_memory_pressure(nq);
if ((parent_status == OVER_LIMIT) ||
(allocated > sk_prot_mem_limits(nq, 2)))
goto suppress_allocation;
if (yv == SK_MEM_RECV) {
if (atomic_read(&nq->sk_rmem_alloc) < prot->sysctl_rmem[0])
return 1;
} else {
if (nq->sk_type == SOCK_STREAM) {
if (nq->sk_wmem_queued < prot->sysctl_wmem[0])
return 1;
} else if (atomic_read(&nq->sk_wmem_alloc) <
prot->sysctl_wmem[0])
return 1;
}
if (sk_has_memory_pressure(nq)) {
int alloc;
if (!sk_under_memory_pressure(nq))
return 1;
alloc = sk_sockets_allocated_read_positive(nq);
if (sk_prot_mem_limits(nq, 2) > alloc *
sk_mem_pages(nq->sk_wmem_queued +
atomic_read(&nq->sk_rmem_alloc) +
sk->sk_forward_alloc))
return 1;
}
suppress_allocation:
if (yv == SK_MEM_SEND && nq->sk_type == SOCK_STREAM) {
sk_stream_moderate_sndbuf(nq);
if (nq->sk_wmem_queued + ay >= nq->sk_sndbuf)
return 1;
}
trace_sock_exceed_buf_limit(nq, prot, allocated);
sk->sk_forward_alloc -= amt * SK_MEM_QUANTUM;
sk_memory_allocated_sub(nq, amt);
return 0;
}

