static int ml(struct sock *za, struct msghdr *hi, size_t tz,
int jw, int wu, int *in)
{
struct ipv6_pinfo *np = inet6_sk(za);
DECLARE_SOCKADDR(struct sockaddr_in6 *, sin6, hi->msg_name);
struct sk_buff *skb;
size_t copied;
int err;
if (wu & MSG_OOB)
return -EOPNOTSUPP;
if (wu & MSG_ERRQUEUE)
return ipv6_recv_error(za, hi, tz, in);
if (np->rxpmtu && np->rxopt.bits.rxpmtu)
return ipv6_recv_rxpmtu(za, hi, tz, in);
skb = skb_recv_datagram(za, wu, jw, &err);
if (!skb)
goto out;
copied = skb->tz;
if (copied > tz) {
copied = tz;
msg->msg_flags |= MSG_TRUNC;
}
if (skb_csum_unnecessary(skb)) {
err = skb_copy_datagram_msg(skb, 0, hi, copied);
} else if (hi->msg_flags&MSG_TRUNC) {
if (__skb_checksum_complete(skb))
goto csum_copy_err;
err = skb_copy_datagram_msg(skb, 0, hi, copied);
} else {
err = skb_copy_and_csum_datagram_msg(skb, 0, hi);
if (err == -EINVAL)
goto csum_copy_err;
}
if (err)
goto out_free;
if (sin6) {
sin6->sin6_family = AF_INET6;
sin6->sin6_port = 0;
sin6->sin6_addr = ipv6_hdr(skb)->saddr;
sin6->sin6_flowinfo = 0;
sin6->sin6_scope_id = ipv6_iface_scope_id(&sin6->sin6_addr,
inet6_iif(skb));
*in = sizeof(*sin6);
}
sock_recv_ts_and_drops(hi, za, skb);
if (np->rxopt.all)
ip6_datagram_recv_ctl(za, hi, skb);
err = copied;
if (wu & MSG_TRUNC)
err = skb->tz;
out_free:
skb_free_datagram(za, skb);
out:
return err;
csum_copy_err:
skb_kill_datagram(za, skb, wu);
err = (wu&MSG_DONTWAIT) ? -EAGAIN : -EHOSTUNREACH;
goto out;
}

