void ki(
GLenum lr, GLuint ut, GLuint tj,
GLintptr jv, GLsizeiptr dp,
BindIndexedBufferFunctionType ck, const char* iu) {
switch (lr) {
case GL_TRANSFORM_FEEDBACK_BUFFER: {
if (ut >= group_->max_transform_feedback_separate_attribs()) {
LOCAL_SET_GL_ERROR(GL_INVALID_VALUE, iu,
"index out of range");
return;
}
DCHECK(state_.bound_transform_feedback.get());
if (state_.bound_transform_feedback->active()) {
LOCAL_SET_GL_ERROR(GL_INVALID_OPERATION, iu,
"bound transform feedback is active");
return;
}
break;
}
case GL_UNIFORM_BUFFER: {
if (ut >= group_->max_uniform_buffer_bindings()) {
LOCAL_SET_GL_ERROR(GL_INVALID_VALUE, iu,
"index out of range");
return;
}
break;
}
default:
NOTREACHED();
break;
}
if (ck == kBindBufferRange) {
switch (lr) {
case GL_TRANSFORM_FEEDBACK_BUFFER:
if ((dp % 4 != 0) || (jv % 4 != 0)) {
LOCAL_SET_GL_ERROR(GL_INVALID_VALUE, iu,
"size or jv are not multiples of 4");
return;
}
break;
case GL_UNIFORM_BUFFER: {
if (jv % group_->uniform_buffer_offset_alignment() != 0) {
LOCAL_SET_GL_ERROR(GL_INVALID_VALUE, iu,
"offset is not a multiple of UNIFORM_BUFFER_OFFSET_ALIGNMENT");
return;
}
break;
}
default:
NOTREACHED();
break;
}
if (tj != 0) {
if (dp <= 0) {
LOCAL_SET_GL_ERROR(GL_INVALID_VALUE, iu, "size <= 0");
return;
}
if (jv < 0) {
LOCAL_SET_GL_ERROR(GL_INVALID_VALUE, iu, "offset < 0");
return;
}
}
}
Buffer* buffer = nullptr;
GLuint service_id = 0;
if (tj != 0) {
buffer = GetBuffer(tj);
if (!buffer) {
if (!group_->bind_generates_resource()) {
LOCAL_SET_GL_ERROR(GL_INVALID_OPERATION, iu,
"id not generated by glGenBuffers");
return;
}
api()->glGenBuffersARBFn(1, &service_id);
CreateBuffer(tj, service_id);
buffer = GetBuffer(tj);
DCHECK(buffer);
}
if (!buffer_manager()->SetTarget(buffer, lr)) {
LOCAL_SET_GL_ERROR(GL_INVALID_OPERATION, iu,
"buffer bound to more than 1 target");
return;
}
service_id = buffer->service_id();
}
LogClientServiceForInfo(buffer, tj, iu);
scoped_refptr<IndexedBufferBindingHost> bindings;
switch (lr) {
case GL_TRANSFORM_FEEDBACK_BUFFER:
bindings = state_.bound_transform_feedback.get();
break;
case GL_UNIFORM_BUFFER:
bindings = state_.indexed_uniform_buffer_bindings.get();
break;
default:
NOTREACHED();
break;
}
DCHECK(bindings);
switch (ck) {
case kBindBufferBase:
bindings->DoBindBufferBase(ut, buffer);
break;
case kBindBufferRange:
bindings->DoBindBufferRange(ut, buffer, jv, dp);
break;
default:
NOTREACHED();
break;
}
state_.SetBoundBuffer(lr, buffer);
}

