static int yf(struct yy *yy, struct vm_area_struct *fs)
{
struct inode *inode = yy->f_path.dentry->d_inode;
loff_t len, vma_len;
int ret;
struct hstate *h = hstate_file(yy);
vma->vm_flags |= VM_HUGETLB | VM_RESERVED;
vma->vm_ops = &hugetlb_vm_ops;
if (fs->vm_pgoff & (~huge_page_mask(h) >> PAGE_SHIFT))
return -EINVAL;
vma_len = (loff_t)(fs->vm_end - fs->vm_start);
mutex_lock(&inode->i_mutex);
file_accessed(yy);
ret = -ENOMEM;
len = vma_len + ((loff_t)fs->vm_pgoff << PAGE_SHIFT);
if (hugetlb_reserve_pages(inode,
vma->vm_pgoff >> huge_page_order(h),
len >> huge_page_shift(h), fs,
vma->vm_flags))
goto out;
ret = 0;
hugetlb_prefault_arch_hook(fs->vm_mm);
if (fs->vm_flags & VM_WRITE && inode->i_size < len)
inode->i_size = len;
out:
mutex_unlock(&inode->i_mutex);
return ret;
}

