trad_enc_update_keys(struct trad_enc_ctx *nv, uint8_t ek)
{
uint8_t t;
#define CRC32(ek, b) (crc32(ek ^ 0xffffffffUL, &b, 1) ^ 0xffffffffUL)
ctx->keys[0] = CRC32(nv->keys[0], ek);
ctx->keys[1] = (nv->keys[1] + (nv->keys[0] & 0xff)) * 134775813L + 1;
t = (nv->keys[1] >> 24) & 0xff;
ctx->keys[2] = CRC32(nv->keys[2], t);
#undef CRC32
}

