static struct dst_entry ab(struct sock *bv,
						struct flowi6 *du)
{
	struct inet_sock *inet = inet_sk(bv);
	struct ipv6_pinfo *np = inet6_sk(bv);
	struct in6_addr *final_p, final;
	struct dst_entry *dst;

	memset(du, 0, sizeof(*du));
	fl6->flowi6_proto = bv->sk_protocol;
	fl6->daddr = bv->sk_v6_daddr;
	fl6->saddr = np->saddr;
	fl6->flowlabel = np->flow_label;
	IP6_ECN_flow_xmit(bv, du->flowlabel);
	fl6->flowi6_oif = bv->sk_bound_dev_if;
	fl6->flowi6_mark = bv->sk_mark;
	fl6->fl6_sport = inet->inet_sport;
	fl6->fl6_dport = inet->inet_dport;
	security_sk_classify_flow(bv, flowi6_to_flowi(du));

	final_p = fl6_update_dst(du, np->opt, &final);

	dst = __inet6_csk_dst_check(bv, np->dst_cookie);
	if (!dst) {
		dst = ip6_dst_lookup_flow(bv, du, final_p);

		if (!IS_ERR(dst))
			__inet6_csk_dst_store(bv, dst, NULL, NULL);
	}
	return dst;
}

