static int pw(jpc_bitstream_t *ri)
{
int n;
if ((n = jpc_bitstream_getbit(ri)) > 0) {
if ((n = jpc_bitstream_getbit(ri)) > 0) {
if ((n = jpc_bitstream_getbits(ri, 2)) == 3) {
if ((n = jpc_bitstream_getbits(ri, 5)) == 31) {
if ((n = jpc_bitstream_getbits(ri, 7)) >= 0) {
n += 36 + 1;
}
} else if (n >= 0) {
n += 5 + 1;
}
} else if (n >= 0) {
n += 2 + 1;
}
} else if (!n) {
n += 2;
}
} else if (!n) {
++n;
}
return n;
}

size_t wv(const char *eg) {
size_t len = 0;
uint32_t *s = (uint32_t *)eg;
while (1) {
uint32_t w = *s++;
if ((w & 0xff) == 0) break;
len++; w >>= 8;
if ((w & 0xff) == 0) break;
len++; w >>= 8;
if ((w & 0xff) == 0) break;
len++; w >>= 8;
if ((w & 0xff) == 0) break;
len++;
}
return len;
}

