static int wn(struct ip_vs_dest_user_kern *gy,
struct nlattr *iq, int gl)
{
struct nlattr *attrs[IPVS_DEST_ATTR_MAX + 1];
struct nlattr *nla_addr, *nla_port;
if (iq == NULL ||
nla_parse_nested(attrs, IPVS_DEST_ATTR_MAX, iq, ip_vs_dest_policy))
return -EINVAL;
nla_addr	= attrs[IPVS_DEST_ATTR_ADDR];
nla_port	= attrs[IPVS_DEST_ATTR_PORT];
if (!(nla_addr && nla_port))
return -EINVAL;
memset(gy, 0, sizeof(*gy));
nla_memcpy(&gy->addr, nla_addr, sizeof(gy->addr));
udest->port = nla_get_u16(nla_port);
if (gl) {
struct nlattr *nla_fwd, *nla_weight, *nla_u_thresh,
*nla_l_thresh;
nla_fwd		= attrs[IPVS_DEST_ATTR_FWD_METHOD];
nla_weight	= attrs[IPVS_DEST_ATTR_WEIGHT];
nla_u_thresh	= attrs[IPVS_DEST_ATTR_U_THRESH];
nla_l_thresh	= attrs[IPVS_DEST_ATTR_L_THRESH];
if (!(nla_fwd && nla_weight && nla_u_thresh && nla_l_thresh))
return -EINVAL;
udest->conn_flags = nla_get_u32(nla_fwd)
& IP_VS_CONN_F_FWD_MASK;
udest->weight = nla_get_u32(nla_weight);
udest->u_threshold = nla_get_u32(nla_u_thresh);
udest->l_threshold = nla_get_u32(nla_l_thresh);
}
return 0;
}

int br(struct hns_roce_dev *jf)
{
int ret;
struct device *dev = jf->dev;
if (jf->hw->reset) {
ret = jf->hw->reset(jf, true);
if (ret) {
dev_err(dev, "Reset RoCE engine failed!\n");
return ret;
}
}
if (jf->hw->cmq_init) {
ret = jf->hw->cmq_init(jf);
if (ret) {
dev_err(dev, "Init RoCE Command Queue failed!\n");
goto error_failed_cmq_init;
}
}
ret = jf->hw->hw_profile(jf);
if (ret) {
dev_err(dev, "Get RoCE engine profile failed!\n");
goto error_failed_cmd_init;
}
ret = hns_roce_cmd_init(jf);
if (ret) {
dev_err(dev, "cmd init failed!\n");
goto error_failed_cmd_init;
}
ret = jf->hw->init_eq(jf);
if (ret) {
dev_err(dev, "eq init failed!\n");
goto error_failed_eq_table;
}
if (jf->cmd_mod) {
ret = hns_roce_cmd_use_events(jf);
if (ret) {
dev_err(dev, "Switch to event-driven cmd failed!\n");
goto error_failed_use_event;
}
}
ret = br_hem(jf);
if (ret) {
dev_err(dev, "init HEM(Hardware Entry Memory) failed!\n");
goto error_failed_init_hem;
}
ret = hns_roce_setup_hca(jf);
if (ret) {
dev_err(dev, "setup hca failed!\n");
goto error_failed_setup_hca;
}
if (jf->hw->hw_init) {
ret = jf->hw->hw_init(jf);
if (ret) {
dev_err(dev, "hw_init failed!\n");
goto error_failed_engine_init;
}
}
ret = hns_roce_register_device(jf);
if (ret)
goto error_failed_register_device;
return 0;
error_failed_register_device:
if (jf->hw->hw_exit)
hr_dev->hw->hw_exit(jf);
error_failed_engine_init:
hns_roce_cleanup_bitmap(jf);
error_failed_setup_hca:
hns_roce_cleanup_hem(jf);
error_failed_init_hem:
if (jf->cmd_mod)
hns_roce_cmd_use_polling(jf);
error_failed_use_event:
hr_dev->hw->cleanup_eq(jf);
error_failed_eq_table:
hns_roce_cmd_cleanup(jf);
error_failed_cmd_init:
if (jf->hw->cmq_exit)
hr_dev->hw->cmq_exit(jf);
error_failed_cmq_init:
if (jf->hw->reset) {
ret = jf->hw->reset(jf, false);
if (ret)
dev_err(dev, "Dereset RoCE engine failed!\n");
}
return ret;
}

