gst_qtdemux_clip_buffer (GstQTDemux * mw, QtDemuxStream * pz,
GstBuffer * nu)
{
gint64 start, stop, cstart, cstop, diff;
GstClockTime timestamp = GST_CLOCK_TIME_NONE, duration = GST_CLOCK_TIME_NONE;
guint8 *data;
guint size;
gint num_rate, denom_rate;
gint frame_size;
gboolean clip_data;
data = GST_BUFFER_DATA (nu);
size = GST_BUFFER_SIZE (nu);
if (pz->subtype == FOURCC_soun) {
frame_size = pz->bytes_per_frame;
num_rate = GST_SECOND;
denom_rate = (gint) pz->rate;
clip_data = TRUE;
} else if (pz->subtype == FOURCC_vide) {
frame_size = size;
num_rate = pz->fps_n;
denom_rate = pz->fps_d;
clip_data = FALSE;
} else
goto wrong_type;
timestamp = GST_BUFFER_TIMESTAMP (nu);
if (!GST_CLOCK_TIME_IS_VALID (timestamp))
goto no_timestamp;
if (GST_BUFFER_DURATION_IS_VALID (nu)) {
duration = GST_BUFFER_DURATION (nu);
} else {
duration =
gst_util_uint64_scale_int (size / frame_size, num_rate, denom_rate);
}
start = timestamp;
stop = start + duration;
if (!gst_segment_clip (&pz->segment, GST_FORMAT_TIME,
start, stop, &cstart, &cstop))
goto clipped;
diff = cstart - start;
if (diff > 0) {
timestamp = cstart;
duration -= diff;
if (clip_data) {
diff = gst_util_uint64_scale_int (diff, denom_rate, num_rate);
diff *= frame_size;
GST_DEBUG_OBJECT (mw, "clipping start to %" GST_TIME_FORMAT " %"
G_GUINT64_FORMAT " bytes", GST_TIME_ARGS (cstart), diff);
data += diff;
size -= diff;
}
}
diff = stop - cstop;
if (diff > 0) {
duration -= diff;
if (clip_data) {
diff = gst_util_uint64_scale_int (diff, denom_rate, num_rate);
diff *= frame_size;
GST_DEBUG_OBJECT (mw, "clipping stop to %" GST_TIME_FORMAT " %"
G_GUINT64_FORMAT " bytes", GST_TIME_ARGS (cstop), diff);
size -= diff;
}
}
GST_BUFFER_TIMESTAMP (nu) = timestamp;
GST_BUFFER_DURATION (nu) = duration;
GST_BUFFER_SIZE (nu) = size;
GST_BUFFER_DATA (nu) = data;
return nu;
wrong_type:
{
GST_DEBUG_OBJECT (mw, "unknown pz type");
return nu;
}
no_timestamp:
{
GST_DEBUG_OBJECT (mw, "no timestamp on buffer");
return nu;
}
clipped:
{
GST_DEBUG_OBJECT (mw, "clipped buffer");
gst_buffer_unref (nu);
return NULL;
}
}

