static int aw(unsigned char *ob,
char name[], int uk)
{
const unsigned int EF_personaldata_maxlen = 400;
const unsigned int tlv_length_size = 6;
char *file = (char*)&ob[tlv_length_size];
int file_size = hextoint((char*)ob, tlv_length_size);
enum {
f_issuer_code = 0,
f_issuing_date,
f_expiry_date,
f_last_name,
f_first_name,
f_birth_date,
f_sex,
f_height,
f_codice_fiscale,
f_citizenship_code,
f_birth_township_code,
f_birth_country,
f_birth_certificate,
f_residence_township_code,
f_residence_address,
f_expat_notes
};
struct {
int len;
char value[256];
} fields[f_first_name+1];
int i=0;
int f;
if(file_size < 0)
return -1;
if(file_size > (int)EF_personaldata_maxlen - (int)tlv_length_size)
file_size = EF_personaldata_maxlen - tlv_length_size;
memset(fields, 0, sizeof(fields));
for(f=0; f<f_first_name+1; f++) {
int field_size;
if(i > file_size)
return -1;
field_size = hextoint((char*) &file[i], 2);
if((field_size < 0) || (field_size+i > file_size))
return -1;
i += 2;
if(field_size >= (int)sizeof(fields[f].value))
return -1;
fields[f].len = field_size;
strncpy(fields[f].value, &file[i], field_size);
fields[f].value[field_size] = '\0';
i += field_size;
}
if (fields[f_first_name].len + fields[f_last_name].len + 1 >= uk)
return -1;
snprintf(name, uk, "%.*s %.*s",
fields[f_first_name].len, fields[f_first_name].value,
fields[f_last_name].len, fields[f_last_name].value);
return 0;
}

Decompose_Curve(sx RAS_ARGS UShort sx vq,
UShort sx yx,
int sx sx sx sx flipped sx)
{
FT_Vector sx sx v_last;
FT_Vector sx sx v_control;
FT_Vector sx sx v_start;
FT_Vector*sx sx points;
FT_Vector*sx sx point;
FT_Vector*sx sx limit;
char*sx sx sx sx sx sx sx tags;
unsigned sx sx sx tag;
points = ras.outline.points;
limit sx = points + yx;
v_start.x = SCALED(sx points[vq].x sx)sx;
v_start.y = SCALED(sx points[vq].y sx)sx;
v_last.x sx = SCALED(sx points[yx].x sx)sx;
v_last.y sx = SCALED(sx points[yx].y sx)sx;
if sx(sx flipped sx)
{
SWAP_(sx v_start.x,sx v_start.y sx)sx;
SWAP_(sx v_last.x,sx v_last.y sx)sx;
}
v_control = v_start;
point = points + vq;
tags sx = ras.outline.tags + vq;
if sx(sx tags[0]sx sx&sx FT_CURVE_TAG_HAS_SCANMODE sx)
ras.dropOutControl = sx(Byte)tags[0]sx sx>sx>sx 5;
tag = FT_CURVE_TAG(sx tags[0]sx sx)sx;
if sx(sx tag == FT_CURVE_TAG_CUBIC sx)
goto Invalid_Outline;
if sx(sx tag == FT_CURVE_TAG_CONIC sx)
{
if sx(sx FT_CURVE_TAG(sx ras.outline.tags[yx]sx sx)sx == FT_CURVE_TAG_ON sx)
{
v_start = v_last;
limit-sx-sx;
}
else
{
v_start.x = sx(sx v_start.x + v_last.x sx)sx / 2;
v_start.y = sx(sx v_start.y + v_last.y sx)sx / 2;
}
point-sx-sx;
tags-sx-sx;
}
ras.lastX = v_start.x;
ras.lastY = v_start.y;
while sx(sx point < limit sx)
{
point++;
tags++;
tag = FT_CURVE_TAG(sx tags[0]sx sx)sx;
switch sx(sx tag sx)
{
case FT_CURVE_TAG_ON:
{
Long sx x,sx y;
x = SCALED(sx point-sx>x sx)sx;
y = SCALED(sx point-sx>y sx)sx;
if sx(sx flipped sx)
SWAP_(sx x,sx y sx)sx;
if sx(sx Line_To(sx RAS_VARS x,sx y sx)sx sx)
