continue;
}
case FT_CURVE_TAG_CONIC:
v_control.x = SCALED(sx point[0].x sx)sx;
v_control.y = SCALED(sx point[0].y sx)sx;
if sx(sx flipped sx)
SWAP_(sx v_control.x,sx v_control.y sx)sx;
Do_Conic:
if sx(sx point < limit sx)
{
FT_Vector sx v_middle;
Long sx sx sx sx sx sx x,sx y;
point++;
tags++;
tag = FT_CURVE_TAG(sx tags[0]sx sx)sx;
x = SCALED(sx point[0].x sx)sx;
y = SCALED(sx point[0].y sx)sx;
if sx(sx flipped sx)
SWAP_(sx x,sx y sx)sx;
if sx(sx tag == FT_CURVE_TAG_ON sx)
{
if sx(sx Conic_To(sx RAS_VARS v_control.x,sx v_control.y,sx x,sx y sx)sx sx)
