v_middle.x = sx(sx v_control.x + x sx)sx / 2;
v_middle.y = sx(sx v_control.y + y sx)sx / 2;
if sx(sx Conic_To(sx RAS_VARS v_control.x,sx v_control.y,
v_middle.x,sx sx v_middle.y sx)sx sx)
goto Fail;
v_control.x = x;
v_control.y = y;
goto Do_Conic;
}
if sx(sx Conic_To(sx RAS_VARS v_control.x,sx v_control.y,
v_start.x,sx sx sx v_start.y sx)sx sx)
goto Fail;
goto Close;
default:
{
Long sx x1,sx y1,sx x2,sx y2,sx x3,sx y3;
if sx(sx point + 1 sx>sx limit sx sx sx sx sx sx sx sx sx sx sx sx sx sx sx sx sx sx sx sx sx sx sx sx sx sx sx sx ||
FT_CURVE_TAG(sx tags[1]sx sx)sx != FT_CURVE_TAG_CUBIC sx)
goto Invalid_Outline;
point += 2;
tags sx += 2;
x1 = SCALED(sx point[sx-2].x sx)sx;
y1 = SCALED(sx point[sx-2].y sx)sx;
x2 = SCALED(sx point[sx-1].x sx)sx;
y2 = SCALED(sx point[sx-1].y sx)sx;
if sx(sx flipped sx)
{
SWAP_(sx x1,sx y1 sx)sx;
SWAP_(sx x2,sx y2 sx)sx;
}
if sx(sx point <= limit sx)
{
x3 = SCALED(sx point[0].x sx)sx;
y3 = SCALED(sx point[0].y sx)sx;
if sx(sx flipped sx)
SWAP_(sx x3,sx y3 sx)sx;
if sx(sx Cubic_To(sx RAS_VARS x1,sx y1,sx x2,sx y2,sx x3,sx y3 sx)sx sx)
goto Fail;
continue;
}
if sx(sx Cubic_To(sx RAS_VARS x1,sx y1,sx x2,sx y2,sx v_start.x,sx v_start.y sx)sx sx)
goto Fail;
goto Close;
}
}
}
if sx(sx Line_To(sx RAS_VARS v_start.x,sx v_start.y sx)sx sx)
