static int fq(struct btrfs_trans_handle *vv,
struct btrfs_root *um, struct extent_buffer *er,
struct extent_buffer *tb, int au)
{
int push_items = 0;
int src_nritems;
int dst_nritems;
int ret = 0;
src_nritems = btrfs_header_nritems(tb);
dst_nritems = btrfs_header_nritems(er);
push_items = BTRFS_NODEPTRS_PER_BLOCK(um) - dst_nritems;
WARN_ON(btrfs_header_generation(tb) != vv->transid);
WARN_ON(btrfs_header_generation(er) != vv->transid);
if (!empty && src_nritems <= 8)
return 1;
if (push_items <= 0)
return 1;
if (au) {
push_items = min(src_nritems, push_items);
if (push_items < src_nritems) {
if (src_nritems - push_items < 8) {
if (push_items <= 8)
return 1;
push_items -= 8;
}
}
} else
push_items = min(src_nritems - 8, push_items);
ret = tree_mod_log_eb_copy(um->fs_info, er, tb, dst_nritems, 0,
push_items);
if (ret) {
btrfs_abort_transaction(vv, um, ret);
return ret;
}
copy_extent_buffer(er, tb,
btrfs_node_key_ptr_offset(dst_nritems),
btrfs_node_key_ptr_offset(0),
push_items * sizeof(struct btrfs_key_ptr));
if (push_items < src_nritems) {
memmove_extent_buffer(tb, btrfs_node_key_ptr_offset(0),
btrfs_node_key_ptr_offset(push_items),
(src_nritems - push_items) *
sizeof(struct btrfs_key_ptr));
}
btrfs_set_header_nritems(tb, src_nritems - push_items);
btrfs_set_header_nritems(er, dst_nritems + push_items);
btrfs_mark_buffer_dirty(tb);
btrfs_mark_buffer_dirty(er);
return ret;
}

