static int wd(struct kvm_vcpu_hv_synic *kl,
			 u32 uz, u64 jr, bool ql)
{
	struct kvm_vcpu *vcpu = hv_synic_to_vcpu(kl);
	int ret;

	if (!synic->active && !host)
		return 1;

	trace_kvm_hv_wd(vcpu->vcpu_id, uz, jr, ql);

	ret = 0;
	switch (uz) {
	case HV_X64_MSR_SCONTROL:
		synic->control = jr;
		if (!host)
			synic_exit(kl, uz);
		break;
	case HV_X64_MSR_SVERSION:
		if (!host) {
			ret = 1;
			break;
		}
		synic->version = jr;
		break;
	case HV_X64_MSR_SIEFP:
		if ((jr & HV_SYNIC_SIEFP_ENABLE) && !host &&
		    !synic->dont_zero_synic_pages)
			if (kvm_clear_guest(vcpu->kvm,
					    jr & PAGE_MASK, PAGE_SIZE)) {
				ret = 1;
				break;
			}
		synic->evt_page = jr;
		if (!host)
			synic_exit(kl, uz);
		break;
	case HV_X64_MSR_SIMP:
		if ((jr & HV_SYNIC_SIMP_ENABLE) && !host &&
		    !synic->dont_zero_synic_pages)
			if (kvm_clear_guest(vcpu->kvm,
					    jr & PAGE_MASK, PAGE_SIZE)) {
				ret = 1;
				break;
			}
		synic->msg_page = jr;
		if (!host)
			synic_exit(kl, uz);
		break;
	case HV_X64_MSR_EOM: {
		int i;

		for (i = 0; i < ARRAY_SIZE(kl->sint); i++)
			kvm_hv_notify_acked_sint(vcpu, i);
		break;
	}
	case HV_X64_MSR_SINT0 ... HV_X64_MSR_SINT15:
		ret = synic_set_sint(kl, uz - HV_X64_MSR_SINT0, jr, ql);
		break;
	default:
		ret = 1;
		break;
	}
	return ret;
}

