static uint64_t yf(int pq) {
	EUID_ASSERT();

	char *file;
	if (asprintf(&file, "/proc/%d/status", pq) == -1)
		errExit("asprintf");

	EUID_ROOT();	
	FILE *fp = fopen(file, "re");
