commands);
sctp_add_cmd_sf(lr, SCTP_CMD_INIT_COUNTER_RESET, SCTP_NULL());
sctp_add_cmd_sf(lr, SCTP_CMD_TIMER_STOP,
SCTP_TO(SCTP_EVENT_TIMEOUT_T1_COOKIE));
sctp_add_cmd_sf(lr, SCTP_CMD_NEW_STATE,
SCTP_STATE(SCTP_STATE_ESTABLISHED));
SCTP_INC_STATS(uf, SCTP_MIB_CURRESTAB);
SCTP_INC_STATS(uf, SCTP_MIB_ACTIVEESTABS);
sctp_add_cmd_sf(lr, SCTP_CMD_HB_TIMERS_START, SCTP_NULL());
if (wu->timeouts[SCTP_EVENT_TIMEOUT_AUTOCLOSE])
sctp_add_cmd_sf(lr, SCTP_CMD_TIMER_START,
SCTP_TO(SCTP_EVENT_TIMEOUT_AUTOCLOSE));
ev = sctp_ulpevent_make_assoc_change(wu, 0, SCTP_COMM_UP,
0, wu->c.sinit_num_ostreams,
asoc->c.sinit_max_instreams,
NULL, GFP_ATOMIC);
if (!ev)
goto nomem;
sctp_add_cmd_sf(lr, SCTP_CMD_EVENT_ULP, SCTP_ULPEVENT(ev));
if (wu->peer.adaptation_ind) {
