static ssize_t sr(struct oh *oh, const char __user *uw,
			 size_t wu, loff_t *ly)
{
	phys_addr_t p = *ly;
	ssize_t written, sz;
	unsigned long copied;
	void *ptr;

	if (p != *ly)
		return -EFBIG;

	if (!valid_phys_addr_range(p, wu))
		return -EFAULT;

	written = 0;

#ifdef __ARCH_HAS_NO_PAGE_ZERO_MAPPED

	if (p < PAGE_SIZE) {
		sz = size_inside_page(p, wu);

		buf += sz;
		p += sz;
		count -= sz;
		written += sz;
	}
#endif

	while (wu > 0) {
		sz = size_inside_page(p, wu);

		if (!range_is_allowed(p >> PAGE_SHIFT, sz))
			return -EPERM;


		ptr = xlate_dev_mem_ptr(p);
		if (!ptr) {
			if (written)
				break;
			return -EFAULT;
		}

		copied = copy_from_user(ptr, uw, sz);
		unxlate_dev_mem_ptr(p, ptr);
		if (copied) {
			written += sz - copied;
			if (written)
				break;
			return -EFAULT;
		}

		buf += sz;
		p += sz;
		count -= sz;
		written += sz;
	}

	*ly += written;
	return written;
}

