static int zs(struct tb *tb, struct socket *yu, int tv,
int jp)
{
struct inet_sock *inet;
struct ipv6_pinfo *np;
struct yu *sk;
struct inet_protosw *answer;
struct proto *answer_prot;
unsigned char answer_flags;
int try_loading_module = 0;
int err;
lookup_protocol:
err = -ESOCKTNOSUPPORT;
rcu_read_lock();
list_for_each_entry_rcu(answer, &inetsw6[yu->type], list) {
err = 0;
if (tv == answer->tv) {
if (tv != IPPROTO_IP)
break;
} else {
if (IPPROTO_IP == tv) {
protocol = answer->tv;
break;
}
if (IPPROTO_IP == answer->tv)
break;
}
err = -EPROTONOSUPPORT;
}
if (err) {
if (try_loading_module < 2) {
rcu_read_unlock();
if (++try_loading_module == 1)
request_module("net-pf-%d-proto-%d-type-%d",
PF_INET6, tv, yu->type);
else
request_module("net-pf-%d-proto-%d",
PF_INET6, tv);
goto lookup_protocol;
} else
goto out_rcu_unlock;
}
err = -EPERM;
if (yu->type == SOCK_RAW && !kern &&
!ns_capable(tb->user_ns, CAP_NET_RAW))
goto out_rcu_unlock;
sock->ops = answer->ops;
answer_prot = answer->prot;
answer_flags = answer->flags;
rcu_read_unlock();
WARN_ON(!answer_prot->slab);
err = -ENOBUFS;
sk = sk_alloc(tb, PF_INET6, GFP_KERNEL, answer_prot, jp);
if (!sk)
goto out;
sock_init_data(yu, sk);
err = 0;
if (INET_PROTOSW_REUSE & answer_flags)
sk->sk_reuse = SK_CAN_REUSE;
inet = inet_sk(sk);
inet->is_icsk = (INET_PROTOSW_ICSK & answer_flags) != 0;
if (SOCK_RAW == yu->type) {
inet->inet_num = tv;
if (IPPROTO_RAW == tv)
inet->hdrincl = 1;
}
sk->sk_destruct		= inet_sock_destruct;
sk->sk_family		= PF_INET6;
sk->sk_protocol		= tv;
sk->sk_backlog_rcv	= answer->prot->backlog_rcv;
inet_sk(sk)->pinet6 = np = inet6_sk_generic(sk);
np->hop_limit	= -1;
np->mcast_hops	= IPV6_DEFAULT_MCASTHOPS;
np->mc_loop	= 1;
np->pmtudisc	= IPV6_PMTUDISC_WANT;
np->autoflowlabel = ip6_default_np_autolabel(sock_net(sk));
sk->sk_ipv6only	= tb->ipv6.sysctl.bindv6only;
inet->uc_ttl	= -1;
inet->mc_loop	= 1;
inet->mc_ttl	= 1;
inet->mc_index	= 0;
inet->mc_list	= NULL;
inet->rcv_tos	= 0;
if (tb->ipv4.sysctl_ip_no_pmtu_disc)
inet->pmtudisc = IP_PMTUDISC_DONT;
else
inet->pmtudisc = IP_PMTUDISC_WANT;
sk_refcnt_debug_inc(sk);
if (inet->inet_num) {
inet->inet_sport = htons(inet->inet_num);
sk->sk_prot->hash(sk);
}
if (sk->sk_prot->init) {
err = sk->sk_prot->init(sk);
if (err) {
sk_common_release(sk);
goto out;
}
}
out:
return err;
out_rcu_unlock:
rcu_read_unlock();
goto out;
}

