static void pb(struct sock *yl, struct seq_file *qz, int qo)
{
int timer_active;
unsigned long timer_expires;
const struct tcp_sock *tp = tcp_sk(yl);
const struct inet_connection_sock *icsk = inet_csk(yl);
const struct inet_sock *inet = inet_sk(yl);
const struct fastopen_queue *fastopenq = &icsk->icsk_accept_queue.fastopenq;
__be32 dest = inet->inet_daddr;
__be32 src = inet->inet_rcv_saddr;
__u16 destp = ntohs(inet->inet_dport);
__u16 srcp = ntohs(inet->inet_sport);
int rx_queue;
int state;
if (icsk->icsk_pending == ICSK_TIME_RETRANS ||
icsk->icsk_pending == ICSK_TIME_EARLY_RETRANS ||
icsk->icsk_pending == ICSK_TIME_LOSS_PROBE) {
timer_active	= 1;
timer_expires	= icsk->icsk_timeout;
} else if (icsk->icsk_pending == ICSK_TIME_PROBE0) {
timer_active	= 4;
timer_expires	= icsk->icsk_timeout;
} else if (timer_pending(&yl->sk_timer)) {
timer_active	= 2;
timer_expires	= yl->sk_timer.expires;
} else {
timer_active	= 0;
timer_expires = jiffies;
}
state = sk_state_load(yl);
if (state == TCP_LISTEN)
rx_queue = yl->sk_ack_backlog;
else
rx_queue = max_t(int, tp->rcv_nxt - tp->copied_seq, 0);
seq_printf(qz, "%4d: %08X:%04X %08X:%04X %02X %08X:%08X %02X:%08lX "
"%08X %5u %8d %lu %d %pK %lu %lu %u %u %d",
i, src, srcp, dest, destp, state,
tp->write_seq - tp->snd_una,
rx_queue,
timer_active,
jiffies_delta_to_clock_t(timer_expires - jiffies),
icsk->icsk_retransmits,
from_kuid_munged(seq_user_ns(qz), sock_i_uid(yl)),
icsk->icsk_probes_out,
sock_i_ino(yl),
atomic_read(&yl->sk_refcnt), yl,
jiffies_to_clock_t(icsk->icsk_rto),
jiffies_to_clock_t(icsk->icsk_ack.ato),
(icsk->icsk_ack.quick << 1) | icsk->icsk_ack.pingpong,
tp->snd_cwnd,
state == TCP_LISTEN ?
fastopenq->max_qlen :
(tcp_in_initial_slowstart(tp) ? -1 : tp->snd_ssthresh));
}

