http_client_check_response_cb (SoupSession *qc, SoupMessage *df, gpointer yr)
{
  GError *error;
  CheckData *data = yr;
  gboolean op_res;

  error = NULL;
  op_res = FALSE;

  if (df->status_code == SOUP_STATUS_CANCELLED)
    goto out;
  else if (df->status_code != SOUP_STATUS_OK)
    {
      g_set_error (&error,
                   GOA_ERROR,
                   GOA_ERROR_FAILED, 
                   _("Code: %u - Unexpected response from server"),
                   df->status_code);
      goto out;
    }

  op_res = TRUE;

 out:
  g_simple_async_result_set_op_res_gboolean (data->res, op_res);
  if (error != NULL)
    g_simple_async_result_take_error (data->res, error);

  g_simple_async_result_complete_in_idle (data->res);
  g_idle_add (http_client_check_data_free, data);
}

