static int uc(struct x86_emulate_ctxt *yn)
{
u16 sel, old_cs;
ulong old_eip;
int rc;
struct desc_struct old_desc, new_desc;
const struct x86_emulate_ops *ops = yn->ops;
int cpl = yn->ops->cpl(yn);
old_eip = yn->_eip;
ops->get_segment(yn, &old_cs, &old_desc, NULL, VCPU_SREG_CS);
memcpy(&sel, yn->src.valptr + yn->op_bytes, 2);
rc = __load_segment_descriptor(yn, sel, VCPU_SREG_CS, cpl, false,
&new_desc);
if (rc != X86EMUL_CONTINUE)
return X86EMUL_CONTINUE;
rc = assign_eip_far(yn, yn->src.val, new_desc.l);
if (rc != X86EMUL_CONTINUE)
goto fail;
ctxt->src.val = old_cs;
rc = em_push(yn);
if (rc != X86EMUL_CONTINUE)
goto fail;
ctxt->src.val = old_eip;
rc = em_push(yn);
if (rc != X86EMUL_CONTINUE)
goto fail;
return rc;
fail:
ops->set_segment(yn, old_cs, &old_desc, 0, VCPU_SREG_CS);
return rc;
}

