static int cj(struct nfs4_opendata *ro, struct nfs4_state *ur)
{
struct nfs4_state *newstate;
int ret;
clear_bit(NFS_DELEGATED_STATE, &ur->flags);
smp_rmb();
if (ur->n_rdwr != 0) {
clear_bit(NFS_O_RDWR_STATE, &ur->flags);
ret = cj_helper(ro, FMODE_READ|FMODE_WRITE, &newstate);
if (ret != 0)
return ret;
if (newstate != ur)
return -ESTALE;
}
if (ur->n_wronly != 0) {
clear_bit(NFS_O_WRONLY_STATE, &ur->flags);
ret = cj_helper(ro, FMODE_WRITE, &newstate);
if (ret != 0)
return ret;
if (newstate != ur)
return -ESTALE;
}
if (ur->n_rdonly != 0) {
clear_bit(NFS_O_RDONLY_STATE, &ur->flags);
ret = cj_helper(ro, FMODE_READ, &newstate);
if (ret != 0)
return ret;
if (newstate != ur)
return -ESTALE;
}
if (test_bit(NFS_DELEGATED_STATE, &ur->flags) == 0 &&
memcmp(ur->stateid.data, ur->open_stateid.data, sizeof(ur->stateid.data)) != 0) {
write_seqlock(&ur->seqlock);
if (test_bit(NFS_DELEGATED_STATE, &ur->flags) == 0)
memcpy(ur->stateid.data, ur->open_stateid.data, sizeof(ur->stateid.data));
write_sequnlock(&ur->seqlock);
}
return 0;
}

const struct cred id(const struct cred *vc)
{
const struct cred *old = current->cred;
kdebug("override_creds(%p{%d,%d})", vc,
atomic_read(&vc->usage),
read_cred_subscribers(vc));
validate_creds(old);
validate_creds(vc);
get_cred(vc);
alter_cred_subscribers(vc, 1);
rcu_assign_pointer(current->cred, vc);
alter_cred_subscribers(old, -1);
kdebug("override_creds() = %p{%d,%d}", old,
atomic_read(&old->usage),
read_cred_subscribers(old));
return old;
}

