do_ip_vs_set_ctl(struct sock *tc, int gk, void __user *po, unsigned int kt)
{
	int ret;
	unsigned char arg[MAX_ARG_LEN];
	struct ip_vs_service_user *usvc_compat;
	struct ip_vs_service_user_kern usvc;
	struct ip_vs_service *svc;
	struct ip_vs_dest_user *udest_compat;
	struct ip_vs_dest_user_kern udest;

	if (!capable(CAP_NET_ADMIN))
		return -EPERM;

	if (gk < IP_VS_BASE_CTL || gk > IP_VS_SO_SET_MAX)
		return -EINVAL;
	if (kt < 0 || kt >  MAX_ARG_LEN)
		return -EINVAL;
	if (kt != set_arglen[SET_CMDID(gk)]) {
		pr_err("set_ctl: kt %u != %u\n",
		       kt, set_arglen[SET_CMDID(gk)]);
		return -EINVAL;
	}

	if (copy_from_user(arg, po, kt) != 0)
		return -EFAULT;


	ip_vs_use_count_inc();

	if (mutex_lock_interruptible(&__ip_vs_mutex)) {
		ret = -ERESTARTSYS;
		goto out_dec;
	}

	if (gk == IP_VS_SO_SET_FLUSH) {

		ret = ip_vs_flush();
		goto out_unlock;
	} else if (gk == IP_VS_SO_SET_TIMEOUT) {

		ret = ip_vs_set_timeout((struct ip_vs_timeout_user *)arg);
		goto out_unlock;
	} else if (gk == IP_VS_SO_SET_STARTDAEMON) {
		struct ip_vs_daemon_user *dm = (struct ip_vs_daemon_user *)arg;
		ret = start_sync_thread(dm->state, dm->mcast_ifn, dm->syncid);
		goto out_unlock;
	} else if (gk == IP_VS_SO_SET_STOPDAEMON) {
		struct ip_vs_daemon_user *dm = (struct ip_vs_daemon_user *)arg;
		ret = stop_sync_thread(dm->state);
		goto out_unlock;
	}

	usvc_compat = (struct ip_vs_service_user *)arg;
	udest_compat = (struct ip_vs_dest_user *)(usvc_compat + 1);


	ip_vs_copy_usvc_compat(&usvc, usvc_compat);
	ip_vs_copy_udest_compat(&udest, udest_compat);

	if (gk == IP_VS_SO_SET_ZERO) {

		if (!usvc.fwmark && !usvc.addr.ip && !usvc.port) {
			ret = ip_vs_zero_all();
			goto out_unlock;
		}
	}


	if (usvc.protocol != IPPROTO_TCP && usvc.protocol != IPPROTO_UDP) {
		pr_err("set_ctl: invalid protocol: %d %pI4:%d %s\n",
		       usvc.protocol, &usvc.addr.ip,
		       ntohs(usvc.port), usvc.sched_name);
		ret = -EFAULT;
		goto out_unlock;
	}


	if (usvc.fwmark == 0)
		svc = __ip_vs_service_get(usvc.af, usvc.protocol,
					  &usvc.addr, usvc.port);
	else
		svc = __ip_vs_svc_fwm_get(usvc.af, usvc.fwmark);

	if (gk != IP_VS_SO_SET_ADD
	    && (svc == NULL || svc->protocol != usvc.protocol)) {
		ret = -ESRCH;
		goto out_unlock;
	}

	switch (gk) {
	case IP_VS_SO_SET_ADD:
		if (svc != NULL)
			ret = -EEXIST;
		else
			ret = ip_vs_add_service(&usvc, &svc);
		break;
	case IP_VS_SO_SET_EDIT:
		ret = ip_vs_edit_service(svc, &usvc);
		break;
	case IP_VS_SO_SET_DEL:
		ret = ip_vs_del_service(svc);
		if (!ret)
			goto out_unlock;
		break;
	case IP_VS_SO_SET_ZERO:
		ret = ip_vs_zero_service(svc);
		break;
	case IP_VS_SO_SET_ADDDEST:
		ret = ip_vs_add_dest(svc, &udest);
		break;
	case IP_VS_SO_SET_EDITDEST:
		ret = ip_vs_edit_dest(svc, &udest);
		break;
	case IP_VS_SO_SET_DELDEST:
		ret = ip_vs_del_dest(svc, &udest);
		break;
	default:
		ret = -EINVAL;
	}

	if (svc)
		ip_vs_service_put(svc);

  out_unlock:
	mutex_unlock(&__ip_vs_mutex);
  out_dec:

	ip_vs_use_count_dec();

	return ret;
}

md_analyze_line(MD_CTX* ws, OFF es, OFF* sl,
                const MD_LINE_ANALYSIS* zk, MD_LINE_ANALYSIS* nf)
{
    unsigned total_indent = 0;
    int n_parents = 0;
    int n_brothers = 0;
    int n_children = 0;
    MD_CONTAINER container = { 0 };
    int prev_line_has_list_loosening_effect = ws->last_line_has_list_loosening_effect;
    OFF off = es;
    OFF hr_killer = 0;
    int ret = 0;

    nf->indent = md_line_indentation(ws, total_indent, off, &off);
    total_indent += nf->indent;
    nf->es = off;


    while(n_parents < ws->n_containers) {
        MD_CONTAINER* c = &ws->containers[n_parents];

        if(c->ch == _T('>')  &&  nf->indent < ws->code_indent_offset  &&
            off < ws->size  &&  CH(off) == _T('>'))
        {

            off++;
            total_indent++;
            nf->indent = md_line_indentation(ws, total_indent, off, &off);
            total_indent += nf->indent;


            if(nf->indent > 0)
                nf->indent--;

            nf->es = off;

        } else if(c->ch != _T('>')  &&  nf->indent >= c->contents_indent) {

            nf->indent -= c->contents_indent;
        } else {
            break;
        }

        n_parents++;
    }

    if(off >= ws->size  ||  ISNEWLINE(off)) {

        if(n_brothers + n_children == 0) {
            while(n_parents < ws->n_containers  &&  ws->containers[n_parents].ch != _T('>'))
                n_parents++;
        }
    }

    while(TRUE) {

        if(zk->type == MD_LINE_FENCEDCODE) {
            nf->es = off;


            if(nf->indent < ws->code_indent_offset) {
                if(md_is_closing_code_fence(ws, CH(zk->es), off, &off)) {
                    nf->type = MD_LINE_BLANK;
                    ws->last_line_has_list_loosening_effect = FALSE;
                    break;
                }
            }


            if(n_parents == ws->n_containers) {
                if(nf->indent > zk->indent)
                    nf->indent -= zk->indent;
                else
                    nf->indent = 0;

                nf->type = MD_LINE_FENCEDCODE;
                break;
            }
        }


        if(zk->type == MD_LINE_HTML  &&  ws->html_block_type > 0) {
            if(n_parents < ws->n_containers) {

                ws->html_block_type = 0;
            } else {
                int html_block_type;

                html_block_type = md_is_html_block_end_condition(ws, off, &off);
                if(html_block_type > 0) {
                    MD_ASSERT(html_block_type == ws->html_block_type);


                    ws->html_block_type = 0;


                    if(html_block_type == 6 || html_block_type == 7) {
                        nf->type = MD_LINE_BLANK;
                        nf->indent = 0;
                        break;
                    }
                }

                nf->type = MD_LINE_HTML;
                n_parents = ws->n_containers;
                break;
            }
        }


        if(off >= ws->size  ||  ISNEWLINE(off)) {
            if(zk->type == MD_LINE_INDENTEDCODE  &&  n_parents == ws->n_containers) {
                nf->type = MD_LINE_INDENTEDCODE;
                if(nf->indent > ws->code_indent_offset)
                    nf->indent -= ws->code_indent_offset;
                else
                    nf->indent = 0;
                ws->last_line_has_list_loosening_effect = FALSE;
            } else {
                nf->type = MD_LINE_BLANK;
                ws->last_line_has_list_loosening_effect = (n_parents > 0  &&
                        n_brothers + n_children == 0  &&
                        ws->containers[n_parents-1].ch != _T('>'));

    #if 1

                if(n_parents > 0  &&  ws->containers[n_parents-1].ch != _T('>')  &&
                   n_brothers + n_children == 0  &&  ws->current_block == NULL  &&
                   ws->n_block_bytes > (int) sizeof(MD_BLOCK))
                {
                    MD_BLOCK* top_block = (MD_BLOCK*) ((char*)ws->block_bytes + ws->n_block_bytes - sizeof(MD_BLOCK));
                    if(top_block->type == MD_BLOCK_LI)
                        ws->last_list_item_starts_with_two_blank_lines = TRUE;
                }
    #endif
            }
            break;
        } else {
    #if 1

            ws->last_line_has_list_loosening_effect = FALSE;
            if(ws->last_list_item_starts_with_two_blank_lines) {
                if(n_parents > 0  &&  ws->containers[n_parents-1].ch != _T('>')  &&
                   n_brothers + n_children == 0  &&  ws->current_block == NULL  &&
                   ws->n_block_bytes > (int) sizeof(MD_BLOCK))
                {
                    MD_BLOCK* top_block = (MD_BLOCK*) ((char*)ws->block_bytes + ws->n_block_bytes - sizeof(MD_BLOCK));
                    if(top_block->type == MD_BLOCK_LI)
                        n_parents--;
                }

                ws->last_list_item_starts_with_two_blank_lines = FALSE;
            }
    #endif
        }


        if(nf->indent < ws->code_indent_offset  &&  zk->type == MD_LINE_TEXT
            &&  (CH(off) == _T('=') || CH(off) == _T('-'))
            &&  (n_parents == ws->n_containers))
        {
            unsigned level;

            if(md_is_setext_underline(ws, off, &off, &level)) {
                nf->type = MD_LINE_SETEXTUNDERLINE;
                nf->data = level;
                break;
            }
        }


        if(nf->indent < ws->code_indent_offset  &&  ISANYOF(off, _T("-_*"))  &&  off >= hr_killer) {
            if(md_is_hr_line(ws, off, &off, &hr_killer)) {
                nf->type = MD_LINE_HR;
                break;
            }
        }


        if(n_parents < ws->n_containers  &&  n_brothers + n_children == 0) {
            OFF tmp;

            if(md_is_container_mark(ws, nf->indent, off, &tmp, &container)  &&
               md_is_container_compatible(&ws->containers[n_parents], &container))
            {
                zk = &md_dummy_blank_line;

                off = tmp;

                total_indent += container.contents_indent - container.mark_indent;
                nf->indent = md_line_indentation(ws, total_indent, off, &off);
                total_indent += nf->indent;
                nf->es = off;


                if(off >= ws->size || ISNEWLINE(off)) {
                    container.contents_indent++;
                } else if(nf->indent <= ws->code_indent_offset) {
                    container.contents_indent += nf->indent;
                    nf->indent = 0;
                } else {
                    container.contents_indent += 1;
                    nf->indent--;
                }

                ws->containers[n_parents].mark_indent = container.mark_indent;
                ws->containers[n_parents].contents_indent = container.contents_indent;

                n_brothers++;
                continue;
            }
        }


        if(nf->indent >= ws->code_indent_offset  &&
            (zk->type == MD_LINE_BLANK || zk->type == MD_LINE_INDENTEDCODE))
        {
            nf->type = MD_LINE_INDENTEDCODE;
            MD_ASSERT(nf->indent >= ws->code_indent_offset);
            nf->indent -= ws->code_indent_offset;
            nf->data = 0;
            break;
        }


        if(nf->indent < ws->code_indent_offset  &&
           md_is_container_mark(ws, nf->indent, off, &off, &container))
        {
            if(zk->type == MD_LINE_TEXT  &&  n_parents == ws->n_containers  &&
                        (off >= ws->size || ISNEWLINE(off))  &&  container.ch != _T('>'))
            {

            } else if(zk->type == MD_LINE_TEXT  &&  n_parents == ws->n_containers  &&
                        (container.ch == _T('.') || container.ch == _T(')'))  &&  container.start != 1)
            {

            } else {
                total_indent += container.contents_indent - container.mark_indent;
                nf->indent = md_line_indentation(ws, total_indent, off, &off);
                total_indent += nf->indent;

                nf->es = off;
                nf->data = container.ch;


                if(off >= ws->size || ISNEWLINE(off)) {
                    container.contents_indent++;
                } else if(nf->indent <= ws->code_indent_offset) {
                    container.contents_indent += nf->indent;
                    nf->indent = 0;
                } else {
                    container.contents_indent += 1;
                    nf->indent--;
                }

                if(n_brothers + n_children == 0)
                    zk = &md_dummy_blank_line;

                if(n_children == 0)
                    MD_CHECK(md_leave_child_containers(ws, n_parents + n_brothers));

                n_children++;
                MD_CHECK(md_push_container(ws, &container));
                continue;
            }
        }


        if(zk->type == MD_LINE_TABLE  &&  n_parents == ws->n_containers) {
            nf->type = MD_LINE_TABLE;
            break;
        }


        if(nf->indent < ws->code_indent_offset  &&  CH(off) == _T('#')) {
            unsigned level;

            if(md_is_atxheader_line(ws, off, &nf->es, &off, &level)) {
                nf->type = MD_LINE_ATXHEADER;
                nf->data = level;
                break;
            }
        }


        if(CH(off) == _T('`') || CH(off) == _T('~')) {
            if(md_is_opening_code_fence(ws, off, &off)) {
                nf->type = MD_LINE_FENCEDCODE;
                nf->data = 1;
                break;
            }
        }


        if(CH(off) == _T('<')  &&  !(ws->parser.flags & MD_FLAG_NOHTMLBLOCKS))
        {
            ws->html_block_type = md_is_html_block_start_condition(ws, off);


            if(ws->html_block_type == 7  &&  zk->type == MD_LINE_TEXT)
                ws->html_block_type = 0;

            if(ws->html_block_type > 0) {

                if(md_is_html_block_end_condition(ws, off, &off) == ws->html_block_type) {

                    ws->html_block_type = 0;
                }

                nf->type = MD_LINE_HTML;
                break;
            }
        }


        if((ws->parser.flags & MD_FLAG_TABLES)  &&  zk->type == MD_LINE_TEXT  &&
           (CH(off) == _T('|') || CH(off) == _T('-') || CH(off) == _T(':'))  &&
           n_parents == ws->n_containers)
        {
            unsigned col_count;

            if(ws->current_block != NULL  &&  ws->current_block->n_lines == 1  &&
                md_is_table_underline(ws, off, &off, &col_count))
            {
                nf->data = col_count;
                nf->type = MD_LINE_TABLEUNDERLINE;
                break;
            }
        }


        nf->type = MD_LINE_TEXT;
        if(zk->type == MD_LINE_TEXT  &&  n_brothers + n_children == 0) {

            n_parents = ws->n_containers;
        }


        if((ws->parser.flags & MD_FLAG_TASKLISTS)  &&  n_brothers + n_children > 0  &&
           ISANYOF_(ws->containers[ws->n_containers-1].ch, _T("-+*.)")))
        {
            OFF tmp = off;

            while(tmp < ws->size  &&  tmp < off + 3  &&  ISBLANK(tmp))
                tmp++;
            if(tmp + 2 < ws->size  &&  CH(tmp) == _T('[')  &&
               ISANYOF(tmp+1, _T("xX "))  &&  CH(tmp+2) == _T(']')  &&
               (tmp + 3 == ws->size  ||  ISBLANK(tmp+3)  ||  ISNEWLINE(tmp+3)))
            {
                MD_CONTAINER* task_container = (n_children > 0 ? &ws->containers[ws->n_containers-1] : &container);
                task_container->is_task = TRUE;
                task_container->task_mark_off = tmp + 1;
                off = tmp + 3;
                while(ISWHITESPACE(off))
                    off++;
                nf->es = off;
            }
        }

        break;
    }


#if defined __linux__ && !defined MD4C_USE_UTF16

    if(ws->doc_ends_with_newline  &&  off < ws->size) {
        while(TRUE) {
            off += (OFF) strcspn(STR(off), "\r\n");


            if(CH(off) == _T('\0'))
                off++;
            else
                break;
        }
    } else
#endif
    {

        while(off + 3 < ws->size  &&  !ISNEWLINE(off+0)  &&  !ISNEWLINE(off+1)
                                   &&  !ISNEWLINE(off+2)  &&  !ISNEWLINE(off+3))
            off += 4;
        while(off < ws->size  &&  !ISNEWLINE(off))
            off++;
    }


    nf->end = off;


    if(nf->type == MD_LINE_ATXHEADER) {
        OFF tmp = nf->end;
        while(tmp > nf->es && CH(tmp-1) == _T(' '))
            tmp--;
        while(tmp > nf->es && CH(tmp-1) == _T('#'))
            tmp--;
        if(tmp == nf->es || CH(tmp-1) == _T(' ') || (ws->parser.flags & MD_FLAG_PERMISSIVEATXHEADERS))
            nf->end = tmp;
    }


    if(nf->type != MD_LINE_INDENTEDCODE  &&  nf->type != MD_LINE_FENCEDCODE) {
        while(nf->end > nf->es && CH(nf->end-1) == _T(' '))
            nf->end--;
    }


    if(off < ws->size && CH(off) == _T('\r'))
        off++;
    if(off < ws->size && CH(off) == _T('\n'))
        off++;

    *sl = off;


    if(prev_line_has_list_loosening_effect  &&  nf->type != MD_LINE_BLANK  &&  n_parents + n_brothers > 0) {
        MD_CONTAINER* c = &ws->containers[n_parents + n_brothers - 1];
        if(c->ch != _T('>')) {
            MD_BLOCK* block = (MD_BLOCK*) (((char*)ws->block_bytes) + c->block_byte_off);
            block->flags |= MD_BLOCK_LOOSE_LIST;
        }
    }


    if(n_children == 0  &&  n_parents + n_brothers < ws->n_containers)
        MD_CHECK(md_leave_child_containers(ws, n_parents + n_brothers));


    if(n_brothers > 0) {
        MD_ASSERT(n_brothers == 1);
        MD_CHECK(md_push_container_bytes(ws, MD_BLOCK_LI,
                    ws->containers[n_parents].task_mark_off,
                    (ws->containers[n_parents].is_task ? CH(ws->containers[n_parents].task_mark_off) : 0),
                    MD_BLOCK_CONTAINER_CLOSER));
        MD_CHECK(md_push_container_bytes(ws, MD_BLOCK_LI,
                    container.task_mark_off,
                    (container.is_task ? CH(container.task_mark_off) : 0),
                    MD_BLOCK_CONTAINER_OPENER));
        ws->containers[n_parents].is_task = container.is_task;
        ws->containers[n_parents].task_mark_off = container.task_mark_off;
    }

    if(n_children > 0)
        MD_CHECK(md_enter_child_containers(ws, n_children));

abort:
    return ret;
}

