xmlXPathCompareNodeSets(int ui, int xi,
xmlXPathObjectPtr sr, xmlXPathObjectPtr sf) {
int i, j, init = 0;
double val1;
double *values2;
int ret = 0;
xmlNodeSetPtr ns1;
xmlNodeSetPtr ns2;
if ((sr == NULL) ||
((sr->type != XPATH_NODESET) && (sr->type != XPATH_XSLT_TREE))) {
xmlXPathFreeObject(sf);
return(0);
}
if ((sf == NULL) ||
((sf->type != XPATH_NODESET) && (sf->type != XPATH_XSLT_TREE))) {
xmlXPathFreeObject(sr);
xmlXPathFreeObject(sf);
return(0);
}
ns1 = sr->nodesetval;
ns2 = sf->nodesetval;
if ((ns1 == NULL) || (ns1->nodeNr <= 0)) {
xmlXPathFreeObject(sr);
xmlXPathFreeObject(sf);
return(0);
}
if ((ns2 == NULL) || (ns2->nodeNr <= 0)) {
xmlXPathFreeObject(sr);
xmlXPathFreeObject(sf);
return(0);
}
values2 = (double *) xmlMalloc(ns2->nodeNr * sizeof(double));
if (values2 == NULL) {
xmlXPathErrMemory(NULL, "comparing nodesets\n");
xmlXPathFreeObject(sr);
xmlXPathFreeObject(sf);
return(0);
}
for (i = 0;i < ns1->nodeNr;i++) {
val1 = xmlXPathCastNodeToNumber(ns1->nodeTab[i]);
if (xmlXPathIsNaN(val1))
continue;
for (j = 0;j < ns2->nodeNr;j++) {
if (init == 0) {
values2[j] = xmlXPathCastNodeToNumber(ns2->nodeTab[j]);
}
if (xmlXPathIsNaN(values2[j]))
continue;
if (ui && xi)
ret = (val1 < values2[j]);
else if (ui && !strict)
ret = (val1 <= values2[j]);
else if (!inf && xi)
ret = (val1 > values2[j]);
else if (!inf && !strict)
ret = (val1 >= values2[j]);
if (ret)
break;
}
if (ret)
break;
init = 1;
}
xmlFree(values2);
xmlXPathFreeObject(sr);
xmlXPathFreeObject(sf);
return(ret);
}

