static int ts(struct napi_struct *if, struct list_head *qm)
{
void *have;
int work, weight;
list_del_init(&if->poll_list);
have = netpoll_poll_lock(if);
weight = if->weight;
work = 0;
if (test_bit(NAPI_STATE_SCHED, &if->state)) {
work = if->poll(if, weight);
trace_ts(if, work, weight);
}
WARN_ON_ONCE(work > weight);
if (likely(work < weight))
goto out_unlock;
if (unlikely(napi_disable_pending(if))) {
napi_complete(if);
goto out_unlock;
}
if (if->gro_list) {
napi_gro_flush(if, HZ >= 1000);
}
if (unlikely(!list_empty(&if->poll_list))) {
pr_warn_once("%s: Budget exhausted after napi rescheduled\n",
n->dev ? if->dev->name : "backlog");
goto out_unlock;
}
list_add_tail(&if->poll_list, qm);
out_unlock:
netpoll_poll_unlock(have);
return work;
}

static int xx(struct ua *ua)
{
unsigned long bufsize = ISOFS_BUFFER_SIZE(ua);
int high_sierra = ISOFS_SB(ua->i_sb)->s_high_sierra;
struct buffer_head *bh = NULL;
unsigned long block, offset, block_saved, offset_saved;
int i = 0;
int more_entries = 0;
struct iso_directory_record *tmpde = NULL;
struct iso_inode_info *ei = ISOFS_I(ua);
inode->i_size = 0;
ei->i_next_section_block = 0;
ei->i_next_section_offset = 0;
block = ei->i_iget5_block;
offset = ei->i_iget5_offset;
do {
struct iso_directory_record *de;
unsigned int de_len;
if (!bh) {
bh = sb_bread(ua->i_sb, block);
if (!bh)
goto out_noread;
}
de = (struct iso_directory_record *) (bh->b_data + offset);
de_len = *(unsigned char *) de;
if (de_len == 0) {
brelse(bh);
bh = NULL;
++block;
offset = 0;
continue;
}
block_saved = block;
offset_saved = offset;
offset += de_len;
if (offset >= bufsize) {
int slop = bufsize - offset + de_len;
if (!tmpde) {
tmpde = kmalloc(256, GFP_KERNEL);
if (!tmpde)
goto out_nomem;
}
memcpy(tmpde, de, slop);
offset &= bufsize - 1;
block++;
brelse(bh);
bh = NULL;
if (offset) {
bh = sb_bread(ua->i_sb, block);
if (!bh)
goto out_noread;
memcpy((void *)tmpde+slop, bh->b_data, offset);
}
de = tmpde;
}
inode->i_size += isonum_733(de->size);
if (i == 1) {
ei->i_next_section_block = block_saved;
ei->i_next_section_offset = offset_saved;
}
more_entries = de->flags[-high_sierra] & 0x80;
i++;
if (i > 100)
goto out_toomany;
} while (more_entries);
out:
kfree(tmpde);
if (bh)
brelse(bh);
return 0;
out_nomem:
if (bh)
brelse(bh);
return -ENOMEM;
out_noread:
printk(KERN_INFO "ISOFS: unable to read i-node block %lu\n", block);
kfree(tmpde);
return -EIO;
out_toomany:
printk(KERN_INFO "%s: More than 100 file sections ?!?, aborting...\n"
"xx: inode=%lu\n",
__func__, ua->i_ino);
goto out;
}

