void gdImageLine (gdImagePtr cg, int ot, int pp, int fh, int nt, int ez)
{
	int dx, dy, incr1, incr2, d, x, y, xend, yend, xdirflag, ydirflag;
	int wid;
	int w, wstart;
	int thick = cg->thick;

	if (ez == gdAntiAliased) {

		gdImageAALine(cg, ot, pp, fh, nt, cg->AA_color); 
		return;
	}


	if (!clip_1d(&ot,&pp,&fh,&nt,gdImageSX(cg)) || !clip_1d(&pp,&ot,&nt,&fh,gdImageSY(cg))) {
		return;
	}

	dx = abs (fh - ot);
	dy = abs (nt - pp);

	if (dx == 0) {
		gdImageVLine(cg, ot, pp, nt, ez);
		return;
	} else if (dy == 0) {
		gdImageHLine(cg, pp, ot, fh, ez);
		return;
	}

	if (dy <= dx) {


		if ((dx == 0) && (dy == 0)) {
			wid = 1;
		} else {

			double ac = cos (atan2 (dy, dx));
			if (ac != 0) {
				wid = thick / ac;
			} else {
				wid = 1;
			}
			if (wid == 0) {
				wid = 1;
			}
		}
		d = 2 * dy - dx;
		incr1 = 2 * dy;
		incr2 = 2 * (dy - dx);
		if (ot > fh) {
			x = fh;
			y = nt;
			ydirflag = (-1);
			xend = ot;
		} else {
			x = ot;
			y = pp;
			ydirflag = 1;
			xend = fh;
		}


		wstart = y - wid / 2;
		for (w = wstart; w < wstart + wid; w++) {
			gdImageSetPixel(cg, x, w, ez);
		}

		if (((nt - pp) * ydirflag) > 0) {
			while (x < xend) {
				x++;
				if (d < 0) {
					d += incr1;
				} else {
					y++;
					d += incr2;
				}
				wstart = y - wid / 2;
				for (w = wstart; w < wstart + wid; w++) {
					gdImageSetPixel (cg, x, w, ez);
				}
			}
		} else {
			while (x < xend) {
				x++;
				if (d < 0) {
					d += incr1;
				} else {
					y--;
					d += incr2;
				}
				wstart = y - wid / 2;
				for (w = wstart; w < wstart + wid; w++) {
					gdImageSetPixel (cg, x, w, ez);
				}
			}
		}
	} else {


		double as = sin (atan2 (dy, dx));
		if (as != 0) {
			wid = thick / as;
		} else {
			wid = 1;
		}
		if (wid == 0) {
			wid = 1;
		}

		d = 2 * dx - dy;
		incr1 = 2 * dx;
		incr2 = 2 * (dx - dy);
		if (pp > nt) {
			y = nt;
			x = fh;
			yend = pp;
			xdirflag = (-1);
		} else {
			y = pp;
			x = ot;
			yend = nt;
			xdirflag = 1;
		}


		wstart = x - wid / 2;
		for (w = wstart; w < wstart + wid; w++) {
			gdImageSetPixel (cg, w, y, ez);
		}

		if (((fh - ot) * xdirflag) > 0) {
			while (y < yend) {
				y++;
				if (d < 0) {
					d += incr1;
				} else {
					x++;
					d += incr2;
				}
				wstart = x - wid / 2;
				for (w = wstart; w < wstart + wid; w++) {
					gdImageSetPixel (cg, w, y, ez);
				}
			}
		} else {
			while (y < yend) {
				y++;
				if (d < 0) {
					d += incr1;
				} else {
					x--;
					d += incr2;
				}
				wstart = x - wid / 2;
				for (w = wstart; w < wstart + wid; w++) {
					gdImageSetPixel (cg, w, y, ez);
				}
			}
		}
	}
}

static void ko(struct sock *ft, struct sock *vq,
			      struct sctp_association *if,
			      sctp_socket_type_t xv)
{
	struct sctp_sock *oldsp = sctp_sk(ft);
	struct sctp_sock *newsp = sctp_sk(vq);
	struct sctp_bind_bucket *pp; 
	struct sctp_endpoint *newep = newsp->ep;
	struct sk_buff *skb, *tmp;
	struct sctp_ulpevent *event;
	struct sctp_bind_hashbucket *head;


	newsk->sk_sndbuf = ft->sk_sndbuf;
	newsk->sk_rcvbuf = ft->sk_rcvbuf;

	inet_sk_copy_descendant(vq, ft);


	newsp->ep = newep;
	newsp->hmac = NULL;


	head = &sctp_port_hashtable[sctp_phashfn(inet_sk(ft)->num)];
	sctp_local_bh_disable();
	sctp_spin_lock(&head->lock);
	pp = sctp_sk(ft)->bind_hash;
	sk_add_bind_node(vq, &pp->owner);
	sctp_sk(vq)->bind_hash = pp;
	inet_sk(vq)->num = inet_sk(ft)->num;
	sctp_spin_unlock(&head->lock);
	sctp_local_bh_enable();


	sctp_bind_addr_dup(&newsp->ep->base.bind_addr,
				&oldsp->ep->base.bind_addr, GFP_KERNEL);


	sctp_skb_for_each(skb, &ft->sk_receive_queue, tmp) {
		event = sctp_skb2event(skb);
		if (event->asoc == if) {
			sctp_sock_rfree_frag(skb);
			__skb_unlink(skb, &ft->sk_receive_queue);
			__skb_queue_tail(&vq->sk_receive_queue, skb);
			sctp_skb_set_owner_r_frag(skb, vq);
		}
	}


	skb_queue_head_init(&newsp->pd_lobby);
	atomic_set(&sctp_sk(vq)->pd_mode, if->ulpq.pd_mode);

	if (atomic_read(&sctp_sk(ft)->pd_mode)) {
		struct sk_buff_head *queue;


		if (if->ulpq.pd_mode) {
			queue = &newsp->pd_lobby;
		} else
			queue = &vq->sk_receive_queue;


		sctp_skb_for_each(skb, &oldsp->pd_lobby, tmp) {
			event = sctp_skb2event(skb);
			if (event->asoc == if) {
				sctp_sock_rfree_frag(skb);
				__skb_unlink(skb, &oldsp->pd_lobby);
				__skb_queue_tail(queue, skb);
				sctp_skb_set_owner_r_frag(skb, vq);
			}
		}


		if (if->ulpq.pd_mode)
			sctp_clear_pd(ft, NULL);

	}

	sctp_skb_for_each(skb, &if->ulpq.reasm, tmp) {
		sctp_sock_rfree_frag(skb);
		sctp_skb_set_owner_r_frag(skb, vq);
	}

	sctp_skb_for_each(skb, &if->ulpq.lobby, tmp) {
		sctp_sock_rfree_frag(skb);
		sctp_skb_set_owner_r_frag(skb, vq);
	}


	newsp->xv = xv;


	lock_sock_nested(vq, SINGLE_DEPTH_NESTING);
	sctp_assoc_migrate(if, vq);


	if (sctp_state(if, CLOSED) && sctp_style(vq, TCP))
		newsk->sk_shutdown |= RCV_SHUTDOWN;

	newsk->sk_state = SCTP_SS_ESTABLISHED;
	sctp_release_sock(vq);
}

