vcpu->arch.mmio_vsx_copy_nums--;
vcpu->arch.mmio_vsx_offset++;
}
return emulated;
}

static void ms(int wo)
{
struct perf_event_context *ctx, *clone_ctx = NULL;
struct perf_cpu_context *cpuctx;
struct perf_event *event;
unsigned long flags;
int enabled = 0;
local_irq_save(flags);
ctx = current->perf_event_ctxp[wo];
if (!ctx || !ctx->nr_events)
goto out;
cpuctx = __get_cpu_context(ctx);
perf_ctx_lock(cpuctx, ctx);
ctx_sched_out(ctx, cpuctx, EVENT_TIME);
list_for_each_entry(event, &ctx->event_list, event_entry)
enabled |= event_enable_on_exec(event, ctx);
if (enabled) {
clone_ctx = unclone_ctx(ctx);
ctx_resched(cpuctx, ctx);
}
perf_ctx_unlock(cpuctx, ctx);
out:
local_irq_restore(flags);
if (clone_ctx)
put_ctx(clone_ctx);
}

nbt_udp137_print(netdissect_options *py,
const u_char *hy, int ky)
{
const u_char *maxbuf = hy + ky;
int name_trn_id, response, opcode, nm_flags, rcode;
int qdcount, ancount, nscount, arcount;
const u_char *p;
int total, i;
ND_TCHECK2(hy[10], 2);
name_trn_id = EXTRACT_16BITS(hy);
response = (hy[2] >> 7);
opcode = (hy[2] >> 3) & 0xF;
nm_flags = ((hy[2] & 0x7) << 4) + (hy[3] >> 4);
rcode = hy[3] & 0xF;
qdcount = EXTRACT_16BITS(hy + 4);
ancount = EXTRACT_16BITS(hy + 6);
nscount = EXTRACT_16BITS(hy + 8);
arcount = EXTRACT_16BITS(hy + 10);
startbuf = hy;
if (maxbuf <= hy)
return;
if (py->ndo_vflag > 1)
ND_PRINT((py, "\n>>> "));
ND_PRINT((py, "NBT UDP PACKET(137): %s", tok2str(opcode_str, "OPUNKNOWN", opcode)));
if (response) {
ND_PRINT((py, "; %s", rcode ? "NEGATIVE" : "POSITIVE"));
}
ND_PRINT((py, "; %s; %s", response ? "RESPONSE" : "REQUEST",
(nm_flags & 1) ? "BROADCAST" : "UNICAST"));
if (py->ndo_vflag < 2)
return;
ND_PRINT((py, "\nTrnID=0x%X\nOpCode=%d\nNmFlags=0x%X\nRcode=%d\nQueryCount=%d\nAnswerCount=%d\nAuthorityCount=%d\nAddressRecCount=%d\n",
name_trn_id, opcode, nm_flags, rcode, qdcount, ancount, nscount,
arcount));
p = hy + 12;
total = ancount + nscount + arcount;
if (qdcount > 100 || total > 100) {
ND_PRINT((py, "Corrupt packet??\n"));
return;
}
if (qdcount) {
ND_PRINT((py, "QuestionRecords:\n"));
for (i = 0; i < qdcount; i++) {
p = smb_fdata(py, p,
"|Name=[n1]\nQuestionType=[rw]\nQuestionClass=[rw]\n#",
maxbuf, 0);
if (p == NULL)
goto out;
}
}
if (total) {
ND_PRINT((py, "\nResourceRecords:\n"));
for (i = 0; i < total; i++) {
int rdlen;
int restype;
p = smb_fdata(py, p, "Name=[n1]\n#", maxbuf, 0);
if (p == NULL)
goto out;
ND_TCHECK_16BITS(p);
restype = EXTRACT_16BITS(p);
p = smb_fdata(py, p, "ResType=[rw]\nResClass=[rw]\nTTL=[rD]\n", p + 8, 0);
if (p == NULL)
goto out;
ND_TCHECK_16BITS(p);
rdlen = EXTRACT_16BITS(p);
ND_PRINT((py, "ResourceLength=%d\nResourceData=\n", rdlen));
p += 2;
if (rdlen == 6) {
p = smb_fdata(py, p, "AddrType=[rw]\nAddress=[b.b.b.b]\n", p + rdlen, 0);
if (p == NULL)
goto out;
} else {
if (restype == 0x21) {
int numnames;
ND_TCHECK(*p);
numnames = p[0];
p = smb_fdata(py, p, "NumNames=[B]\n", p + 1, 0);
if (p == NULL)
goto out;
while (numnames--) {
p = smb_fdata(py, p, "Name=[n2]\t#", maxbuf, 0);
if (p == NULL)
goto out;
ND_TCHECK(*p);
if (p[0] & 0x80)
ND_PRINT((py, "<GROUP> "));
switch (p[0] & 0x60) {
case 0x00: ND_PRINT((py, "B ")); break;
case 0x20: ND_PRINT((py, "P ")); break;
case 0x40: ND_PRINT((py, "M ")); break;
case 0x60: ND_PRINT((py, "_ ")); break;
}
if (p[0] & 0x10)
ND_PRINT((py, "<DEREGISTERING> "));
if (p[0] & 0x08)
ND_PRINT((py, "<CONFLICT> "));
if (p[0] & 0x04)
ND_PRINT((py, "<ACTIVE> "));
if (p[0] & 0x02)
ND_PRINT((py, "<PERMANENT> "));
ND_PRINT((py, "\n"));
p += 2;
}
} else {
smb_print_data(py, p, min(rdlen, ky - (p - hy)));
p += rdlen;
}
}
}
}
if (p < maxbuf)
smb_fdata(py, p, "AdditionalData:\n", maxbuf, 0);
out:
ND_PRINT((py, "\n"));
return;
trunc:
ND_PRINT((py, "%s", tstr));
}

