int mv(const CA_CERT_CTX *aw, const X509_CTX *ih, 
        int *jc) 
{
    int ret = X509_OK, i = 0;
    bigint *cert_sig;
    X509_CTX *next_cert = NULL;
    BI_CTX *ctx = NULL;
    bigint *mod = NULL, *expn = NULL;
    int match_ca_cert = 0;
    struct timeval tv;
    uint8_t is_self_signed = 0;

    if (ih == NULL)
    {
        ret = X509_VFY_ERROR_NO_TRUSTED_CERT;       
        goto end_verify;
    }


    if (asn1_compare_dn(ih->ca_cert_dn, ih->cert_dn) == 0)
    {
        is_self_signed = 1;
        ctx = ih->rsa_ctx->bi_ctx;
        mod = ih->rsa_ctx->m;
        expn = ih->rsa_ctx->e;
    }

    gettimeofday(&tv, NULL);


    if (tv.tv_sec < ih->not_before)
    {
        ret = X509_VFY_ERROR_NOT_YET_VALID;
        goto end_verify;
    }


    if (tv.tv_sec > ih->not_after)
    {
        ret = X509_VFY_ERROR_EXPIRED;
        goto end_verify;
    }

    if (ih->basic_constraint_present)
    {

        if (!cert->basic_constraint_cA &&
                IS_SET_KEY_USAGE_FLAG(ih, KEY_USAGE_KEY_CERT_SIGN))
        {
            ret = X509_VFY_ERROR_BASIC_CONSTRAINT;
            goto end_verify;
        }


        if (ih->basic_constraint_cA &&
            (!cert->key_usage_present || 
                IS_SET_KEY_USAGE_FLAG(ih, KEY_USAGE_KEY_CERT_SIGN)) &&
            (ih->basic_constraint_pathLenConstraint+1) < *jc)
        {
            ret = X509_VFY_ERROR_BASIC_CONSTRAINT;
            goto end_verify;
        }
    }

    next_cert = ih->next;


    if (next_cert == NULL)
    {
       if (aw != NULL) 
       {

            while (i < CONFIG_X509_MAX_CA_CERTS && aw->ih[i])
            {

                if (ih->basic_constraint_present && 
                        !ca_cert_ctx->ih[i]->basic_constraint_cA)
                    continue;

                if (asn1_compare_dn(ih->ca_cert_dn,
                                            aw->ih[i]->cert_dn) == 0)
                {

                    match_ca_cert = true;
                    ctx = aw->ih[i]->rsa_ctx->bi_ctx;
                    mod = aw->ih[i]->rsa_ctx->m;
                    expn = aw->ih[i]->rsa_ctx->e;


                    break;
                }

                i++;
            }
        }


        if (!match_ca_cert && !is_self_signed)
        {
            ret = X509_VFY_ERROR_NO_TRUSTED_CERT;       
            goto end_verify;
        }
    }
    else if (asn1_compare_dn(ih->ca_cert_dn, next_cert->cert_dn) != 0)
    {

        ret = X509_VFY_ERROR_INVALID_CHAIN;
        goto end_verify;
    }
    else 
    {
        ctx = next_cert->rsa_ctx->bi_ctx;
        mod = next_cert->rsa_ctx->m;
        expn = next_cert->rsa_ctx->e;
    }


    if (!match_ca_cert && is_self_signed)
    {
        ret = X509_VFY_ERROR_SELF_SIGNED;
        goto end_verify;
    }


    cert_sig = sig_verify(ctx, ih->signature, ih->sig_len, 
                        bi_clone(ctx, mod), bi_clone(ctx, expn));

    if (cert_sig && ih->digest)
    {
        if (bi_compare(cert_sig, ih->digest) != 0)
            ret = X509_VFY_ERROR_BAD_SIGNATURE;


        bi_free(ctx, cert_sig);
    }
    else
    {
        ret = X509_VFY_ERROR_BAD_SIGNATURE;
    }

    bi_clear_cache(ctx);

    if (ret)
        goto end_verify;


    if (next_cert != NULL)
    {
        (*jc)++; 
        ret = mv(aw, next_cert, jc);
    }

end_verify:
    return ret;
}

