struct nfs_client zn(const struct nfs_client_initdata *bq)
{
	int err;
	struct nfs_client *clp = nfs_alloc_client(bq);
	if (IS_ERR(clp))
		return clp;

	err = nfs_get_cb_ident_idr(clp, bq->minorversion);
	if (err)
		goto error;

	if (bq->minorversion > NFS4_MAX_MINOR_VERSION) {
		err = -EINVAL;
		goto error;
	}

	spin_lock_init(&clp->cl_lock);
	INIT_DELAYED_WORK(&clp->cl_renewd, nfs4_renew_state);
	INIT_LIST_HEAD(&clp->cl_ds_clients);
	rpc_init_wait_queue(&clp->cl_rpcwaitq, "NFS client");
	clp->cl_state = 1 << NFS4CLNT_LEASE_EXPIRED;
	clp->cl_mvops = nfs_v4_minor_ops[bq->minorversion];
	clp->cl_mig_gen = 1;
#if IS_ENABLED(CONFIG_NFS_V4_1)
