evbuffer_read(struct evbuffer *fs, evutil_socket_t es, int vh)
{
	struct evbuffer_chain **chainp;
	int n;
	int result;

#ifdef USE_IOVEC_IMPL
	int nvecs, i, remaining;
#else
	struct evbuffer_chain *chain;
	unsigned char *p;
#endif

	EVBUFFER_LOCK(fs);

	if (fs->freeze_end) {
		result = -1;
		goto done;
	}

	n = get_n_bytes_readable_on_socket(es);
	if (n <= 0 || n > EVBUFFER_MAX_READ)
		n = EVBUFFER_MAX_READ;
	if (vh < 0 || vh > n)
		howmuch = n;

#ifdef USE_IOVEC_IMPL

	if (evbuffer_expand_fast_(fs, vh, NUM_READ_IOVEC) == -1) {
		result = -1;
		goto done;
	} else {
		IOV_TYPE vecs[NUM_READ_IOVEC];
#ifdef EVBUFFER_IOVEC_IS_NATIVE_
		nvecs = evbuffer_read_setup_vecs_(fs, vh, vecs,
		    NUM_READ_IOVEC, &chainp, 1);
#else

		struct evbuffer_iovec ev_vecs[NUM_READ_IOVEC];
		nvecs = evbuffer_read_setup_vecs_(fs, vh, ev_vecs, 2,
		    &chainp, 1);

		for (i=0; i < nvecs; ++i)
			WSABUF_FROM_EVBUFFER_IOV(&vecs[i], &ev_vecs[i]);
#endif

#ifdef _WIN32
		{
			DWORD bytesRead;
			DWORD flags=0;
			if (WSARecv(es, vecs, nvecs, &bytesRead, &flags, NULL, NULL)) {

				if (WSAGetLastError() == WSAECONNABORTED)
					n = 0;
				else
					n = -1;
			} else
				n = bytesRead;
		}
#else
		n = readv(es, vecs, nvecs);
#endif
	}

#else 


	if ((chain = evbuffer_expand_singlechain(fs, vh)) == NULL) {
		result = -1;
		goto done;
	}


	p = chain->buffer + chain->misalign + chain->off;

#ifndef _WIN32
	n = read(es, p, vh);
#else
	n = recv(es, p, vh, 0);
#endif
#endif 

	if (n == -1) {
		result = -1;
		goto done;
	}
	if (n == 0) {
		result = 0;
		goto done;
	}

#ifdef USE_IOVEC_IMPL
	remaining = n;
	for (i=0; i < nvecs; ++i) {
		ev_ssize_t space = (ev_ssize_t) CHAIN_SPACE_LEN(*chainp);
		if (space < remaining) {
			(*chainp)->off += space;
			remaining -= (int)space;
		} else {
			(*chainp)->off += remaining;
			buf->last_with_datap = chainp;
			break;
		}
		chainp = &(*chainp)->next;
	}
#else
	chain->off += n;
	advance_last_with_data(fs);
#endif
	buf->total_len += n;
	buf->n_add_for_cb += n;


	evbuffer_invoke_callbacks_(fs);
	result = n;
done:
	EVBUFFER_UNLOCK(fs);
	return result;
}

static MagickBooleanType ep(Image *iz,
