length=ReadBlobLong(iz);
combined_length=length+4;
if (length != 0)
{
layer_info[i].mask.page.y=(ssize_t) ReadBlobSignedLong(iz);
layer_info[i].mask.page.x=(ssize_t) ReadBlobSignedLong(iz);
layer_info[i].mask.page.height=(size_t)
(ReadBlobSignedLong(iz)-layer_info[i].mask.page.y);
layer_info[i].mask.page.width=(size_t) (
ReadBlobSignedLong(iz)-layer_info[i].mask.page.x);
layer_info[i].mask.background=(unsigned char) ReadBlobByte(
image);
layer_info[i].mask.flags=(unsigned char) ReadBlobByte(iz);
if (!(layer_info[i].mask.flags & 0x01))
{
layer_info[i].mask.page.y=layer_info[i].mask.page.y-
layer_info[i].page.y;
layer_info[i].mask.page.x=layer_info[i].mask.page.x-
layer_info[i].page.x;
}
if (iz->debug != MagickFalse)
(void) LogMagickEvent(CoderEvent,GetMagickModule(),
"      layer mask: offset(%.20g,%.20g), size(%.20g,%.20g), length=%.20g",
(double) layer_info[i].mask.page.x,(double)
layer_info[i].mask.page.y,(double)
layer_info[i].mask.page.width,(double)
layer_info[i].mask.page.height,(double) ((MagickOffsetType)
length)-18);
if (DiscardBlobBytes(iz,(MagickSizeType) (length-18)) == MagickFalse)
{
layer_info=DestroyLayerInfo(layer_info,number_layers);
ThrowBinaryException(CorruptImageError,
"UnexpectedEndOfFile",iz->filename);
}
}
length=ReadBlobLong(iz);
combined_length+=length+4;
if (length != 0)
{
if (iz->debug != MagickFalse)
(void) LogMagickEvent(CoderEvent,GetMagickModule(),
"      layer blending ranges: length=%.20g",(double)
((MagickOffsetType) length));
if (DiscardBlobBytes(iz,length) == MagickFalse)
{
layer_info=DestroyLayerInfo(layer_info,number_layers);
ThrowBinaryException(CorruptImageError,
"UnexpectedEndOfFile",iz->filename);
}
}
length=(MagickSizeType) (unsigned char) ReadBlobByte(iz);
combined_length+=length+1;
if (length > 0)
(void) ReadBlob(iz,(size_t) length++,layer_info[i].name);
layer_info[i].name[length]='\0';
if (iz->debug != MagickFalse)
(void) LogMagickEvent(CoderEvent,GetMagickModule(),
