if (tg3_flag(ut, PCI_EXPRESS)) {
strcpy(sm, "PCI Express");
return sm;
} else if (tg3_flag(ut, PCIX_MODE)) {
u32 clock_ctrl = tr32(TG3PCI_CLOCK_CTRL) & 0x1f;
strcpy(sm, "PCIX:");
if ((clock_ctrl == 7) ||
((tr32(GRC_MISC_CFG) & GRC_MISC_CFG_BOARD_ID_MASK) ==
GRC_MISC_CFG_BOARD_ID_5704CIOBE))
strcat(sm, "133MHz");
else if (clock_ctrl == 0)
strcat(sm, "33MHz");
else if (clock_ctrl == 2)
strcat(sm, "50MHz");
else if (clock_ctrl == 4)
strcat(sm, "66MHz");
else if (clock_ctrl == 6)
strcat(sm, "100MHz");
} else {
strcpy(sm, "PCI:");
if (tg3_flag(ut, PCI_HIGH_SPEED))
strcat(sm, "66MHz");
else
strcat(sm, "33MHz");
}
if (tg3_flag(ut, PCI_32BIT))
strcat(sm, ":32-bit");
else
strcat(sm, ":64-bit");
return sm;
}

