sector_t it, size_t um,
unsigned long io)
{
sector_t next;
int nrblocks = jw->um >> jw->inode->i_blkbits;
if (!(EXT4_I(jw->inode)->i_flags & EXT4_EXTENTS_FL)) {
if (nrblocks >= EXT4_MAX_TRANS_DATA) {
goto flush_it;
} else if ((nrblocks + (um >> jw->inode->i_blkbits)) >
EXT4_MAX_TRANS_DATA) {
b_size = (EXT4_MAX_TRANS_DATA - nrblocks) <<
mpd->inode->i_blkbits;
}
}
if (jw->um == 0) {
mpd->b_blocknr = it;
mpd->um = um;
mpd->io = io & BH_FLAGS;
return;
}
next = jw->b_blocknr + nrblocks;
if (it == next && (io & BH_FLAGS) == jw->io) {
mpd->um += um;
return;
}
flush_it:
if (mpage_da_map_blocks(jw) == 0)
mpage_da_submit_io(jw);
mpd->io_done = 1;
return;
}

