ext4_xattr_cache_insert(struct mb_cache *ha, struct buffer_head *bs)
{
__u32 hash = le32_to_cpu(BHDR(bs)->h_hash);
struct mb_cache_entry *ce;
int error;
ce = mb_cache_entry_alloc(ha, GFP_NOFS);
if (!ce) {
ea_bdebug(bs, "out of memory");
return;
}
error = mb_cache_entry_insert(ce, bs->b_bdev, bs->b_blocknr, hash);
if (error) {
mb_cache_entry_free(ce);
if (error == -EBUSY) {
ea_bdebug(bs, "already in cache");
error = 0;
}
} else {
ea_bdebug(bs, "inserting [%x]", (int)hash);
mb_cache_entry_release(ce);
}
}

