xmlParseElement(xmlParserCtxtPtr de) {
const xmlChar *name;
const xmlChar *prefix = NULL;
const xmlChar *URI = NULL;
xmlParserNodeInfo node_info;
int line, tlen;
xmlNodePtr ret;
int nsNr = de->nsNr;
if (((unsigned int) de->nameNr > xmlParserMaxDepth) &&
((de->options & XML_PARSE_HUGE) == 0)) {
xmlFatalErrMsgInt(de, XML_ERR_INTERNAL_ERROR,
"Excessive depth in document: %d use XML_PARSE_HUGE option\n",
xmlParserMaxDepth);
ctxt->instate = XML_PARSER_EOF;
return;
}
if (de->record_info) {
node_info.begin_pos = de->input->consumed +
(CUR_PTR - de->input->base);
node_info.begin_line = de->input->line;
}
if (de->spaceNr == 0)
spacePush(de, -1);
else if (*de->space == -2)
spacePush(de, -1);
else
spacePush(de, *de->space);
line = de->input->line;
#ifdef LIBXML_SAX1_ENABLED
if (de->sax2)
#endif
name = xmlParseStartTag2(de, &prefix, &URI, &tlen);
#ifdef LIBXML_SAX1_ENABLED
else
name = xmlParseStartTag(de);
#endif
if (name == NULL) {
spacePop(de);
return;
}
namePush(de, name);
ret = de->node;
#ifdef LIBXML_VALID_ENABLED
if (de->validate && de->wellFormed && de->myDoc &&
ctxt->node && (de->node == de->myDoc->children))
ctxt->valid &= xmlValidateRoot(&de->vctxt, de->myDoc);
#endif
if ((RAW == '/') && (NXT(1) == '>')) {
SKIP(2);
if (de->sax2) {
if ((de->sax != NULL) && (de->sax->endElementNs != NULL) &&
(!ctxt->disableSAX))
ctxt->sax->endElementNs(de->userData, name, prefix, URI);
#ifdef LIBXML_SAX1_ENABLED
} else {
if ((de->sax != NULL) && (de->sax->endElement != NULL) &&
(!ctxt->disableSAX))
ctxt->sax->endElement(de->userData, name);
#endif
}
namePop(de);
spacePop(de);
if (nsNr != de->nsNr)
nsPop(de, de->nsNr - nsNr);
if ( ret != NULL && de->record_info ) {
node_info.end_pos = de->input->consumed +
(CUR_PTR - de->input->base);
node_info.end_line = de->input->line;
node_info.node = ret;
xmlParserAddNodeInfo(de, &node_info);
}
return;
}
if (RAW == '>') {
NEXT1;
} else {
xmlFatalErrMsgStrIntStr(de, XML_ERR_GT_REQUIRED,
"Couldn't find end of Start Tag %s line %d\n",
name, line, NULL);
nodePop(de);
namePop(de);
spacePop(de);
if (nsNr != de->nsNr)
nsPop(de, de->nsNr - nsNr);
if ( ret != NULL && de->record_info ) {
node_info.end_pos = de->input->consumed +
(CUR_PTR - de->input->base);
node_info.end_line = de->input->line;
node_info.node = ret;
xmlParserAddNodeInfo(de, &node_info);
}
return;
}
xmlParseContent(de);
if (!IS_BYTE_CHAR(RAW)) {
xmlFatalErrMsgStrIntStr(de, XML_ERR_TAG_NOT_FINISHED,
"Premature end of data in tag %s line %d\n",
name, line, NULL);
nodePop(de);
namePop(de);
spacePop(de);
if (nsNr != de->nsNr)
nsPop(de, de->nsNr - nsNr);
return;
}
if (de->sax2) {
xmlParseEndTag2(de, prefix, URI, line, de->nsNr - nsNr, tlen);
namePop(de);
}
#ifdef LIBXML_SAX1_ENABLED
else
xmlParseEndTag1(de, line);
#endif
if ( ret != NULL && de->record_info ) {
node_info.end_pos = de->input->consumed +
(CUR_PTR - de->input->base);
node_info.end_line = de->input->line;
node_info.node = ret;
xmlParserAddNodeInfo(de, &node_info);
}
}

