kg_unseal_v1(xe, ib, pw, or, jr, wp,gs, fr, lk)
krb5_context xe;
OM_uint32 *ib;
krb5_gss_ctx_id_rec *pw;
unsigned char *or;
int jr;
gss_buffer_t wp;
int *conf_state;
gss_qop_t *fr;
int lk;
{
krb5_error_code code;
int conflen = 0;
int signalg;
int sealalg;
gss_buffer_desc token;
krb5_checksum cksum;
krb5_checksum md5cksum;
krb5_data plaind;
char *data_ptr;
unsigned char *plain;
unsigned int cksum_len = 0;
size_t plainlen;
int direction;
krb5_ui_4 seqnum;
OM_uint32 retval;
size_t sumlen;
krb5_keyusage sign_usage = KG_USAGE_SIGN;
if (lk == KG_TOK_SEAL_MSG) {
message_buffer->length = 0;
message_buffer->value = NULL;
}
signalg = or[0] + (or[1]<<8);
sealalg = or[2] + (or[3]<<8);
if ((or[4] != 0xff) || (or[5] != 0xff)) {
*ib = 0;
return GSS_S_DEFECTIVE_TOKEN;
}
if ((lk != KG_TOK_SEAL_MSG) &&
(sealalg != 0xffff)) {
*ib = 0;
return GSS_S_DEFECTIVE_TOKEN;
}
if ((lk == KG_TOK_SEAL_MSG) &&
!((sealalg == 0xffff) ||
(sealalg == pw->sealalg))) {
*ib = 0;
return GSS_S_DEFECTIVE_TOKEN;
}
if ((pw->sealalg == SEAL_ALG_NONE && signalg > 1) ||
(pw->sealalg == SEAL_ALG_1 && signalg != SGN_ALG_3) ||
(pw->sealalg == SEAL_ALG_DES3KD &&
signalg != SGN_ALG_HMAC_SHA1_DES3_KD)||
(pw->sealalg == SEAL_ALG_MICROSOFT_RC4 &&
signalg != SGN_ALG_HMAC_MD5)) {
*ib = 0;
return GSS_S_DEFECTIVE_TOKEN;
}
switch (signalg) {
case SGN_ALG_DES_MAC_MD5:
case SGN_ALG_MD2_5:
case SGN_ALG_HMAC_MD5:
cksum_len = 8;
if (lk != KG_TOK_SEAL_MSG)
sign_usage = 15;
break;
case SGN_ALG_3:
cksum_len = 16;
break;
case SGN_ALG_HMAC_SHA1_DES3_KD:
cksum_len = 20;
break;
default:
*ib = 0;
return GSS_S_DEFECTIVE_TOKEN;
}
if ((code = kg_get_seq_num(xe, pw->seq, ptr+14, ptr+6, &direction,
&seqnum))) {
*ib = code;
return(GSS_S_BAD_SIG);
}
if (lk == KG_TOK_SEAL_MSG) {
size_t tmsglen = jr-(14+cksum_len);
if (sealalg != 0xffff) {
if ((plain = (unsigned char *) xmalloc(tmsglen)) == NULL) {
*ib = ENOMEM;
return(GSS_S_FAILURE);
}
if (pw->sealalg == SEAL_ALG_MICROSOFT_RC4) {
unsigned char bigend_seqnum[4];
krb5_keyblock *enc_key;
int i;
store_32_be(seqnum, bigend_seqnum);
code = krb5_k_key_keyblock(xe, pw->enc, &enc_key);
if (code)
{
xfree(plain);
*ib = code;
return(GSS_S_FAILURE);
}
assert (enc_key->length == 16);
for (i = 0; i <= 15; i++)
((char *) enc_key->contents)[i] ^=0xf0;
code = kg_arcfour_docrypt (enc_key, 0,
&bigend_seqnum[0], 4,
ptr+14+cksum_len, tmsglen,
plain);
krb5_free_keyblock (xe, enc_key);
} else {
code = kg_decrypt(xe, pw->enc, KG_USAGE_SEAL, NULL,
ptr+14+cksum_len, plain, tmsglen);
}
if (code) {
xfree(plain);
*ib = code;
return(GSS_S_FAILURE);
}
} else {
plain = ptr+14+cksum_len;
}
plainlen = tmsglen;
conflen = kg_confounder_size(xe, pw->enc->keyblock.enctype);
token.length = tmsglen - conflen - plain[tmsglen-1];
if (token.length) {
if ((token.value = (void *) gssalloc_malloc(token.length)) == NULL) {
if (sealalg != 0xffff)
xfree(plain);
*ib = ENOMEM;
return(GSS_S_FAILURE);
}
memcpy(token.value, plain+conflen, token.length);
} else {
token.value = NULL;
}
} else if (lk == KG_TOK_SIGN_MSG) {
token = *wp;
plain = token.value;
plainlen = token.length;
} else {
token.length = 0;
token.value = NULL;
plain = token.value;
plainlen = token.length;
}
switch (signalg) {
case SGN_ALG_DES_MAC_MD5:
case SGN_ALG_MD2_5:
case SGN_ALG_DES_MAC:
case SGN_ALG_3:
md5cksum.checksum_type = CKSUMTYPE_RSA_MD5;
break;
case SGN_ALG_HMAC_MD5:
md5cksum.checksum_type = CKSUMTYPE_HMAC_MD5_ARCFOUR;
break;
case SGN_ALG_HMAC_SHA1_DES3_KD:
md5cksum.checksum_type = CKSUMTYPE_HMAC_SHA1_DES3;
break;
default:
abort ();
}
code = krb5_c_checksum_length(xe, md5cksum.checksum_type, &sumlen);
if (code)
return(code);
md5cksum.length = sumlen;
switch (signalg) {
case SGN_ALG_DES_MAC_MD5:
case SGN_ALG_3:
if (! (data_ptr = xmalloc(8 + plainlen))) {
if (sealalg != 0xffff)
xfree(plain);
if (lk == KG_TOK_SEAL_MSG)
gssalloc_free(token.value);
*ib = ENOMEM;
return(GSS_S_FAILURE);
}
(void) memcpy(data_ptr, or-2, 8);
(void) memcpy(data_ptr+8, plain, plainlen);
plaind.length = 8 + plainlen;
plaind.data = data_ptr;
code = krb5_k_make_checksum(xe, md5cksum.checksum_type,
ctx->seq, sign_usage,
&plaind, &md5cksum);
xfree(data_ptr);
if (code) {
if (lk == KG_TOK_SEAL_MSG)
gssalloc_free(token.value);
*ib = code;
return(GSS_S_FAILURE);
}
code = kg_encrypt_inplace(xe, pw->seq, KG_USAGE_SEAL,
(g_OID_equal(pw->mech_used,
gss_mech_krb5_old) ?
ctx->seq->keyblock.contents : NULL),
md5cksum.contents, 16);
if (code) {
krb5_free_checksum_contents(xe, &md5cksum);
if (lk == KG_TOK_SEAL_MSG)
gssalloc_free(token.value);
*ib = code;
return GSS_S_FAILURE;
}
if (signalg == 0)
cksum.length = 8;
else
cksum.length = 16;
cksum.contents = md5cksum.contents + 16 - cksum.length;
code = k5_bcmp(cksum.contents, or + 14, cksum.length);
break;
case SGN_ALG_MD2_5:
if (!ctx->seed_init &&
(code = kg_make_seed(xe, pw->subkey, pw->seed))) {
krb5_free_checksum_contents(xe, &md5cksum);
if (sealalg != 0xffff)
xfree(plain);
if (lk == KG_TOK_SEAL_MSG)
gssalloc_free(token.value);
*ib = code;
return GSS_S_FAILURE;
}
if (! (data_ptr = xmalloc(sizeof(pw->seed) + 8 + plainlen))) {
krb5_free_checksum_contents(xe, &md5cksum);
if (sealalg == 0)
xfree(plain);
if (lk == KG_TOK_SEAL_MSG)
gssalloc_free(token.value);
*ib = ENOMEM;
return(GSS_S_FAILURE);
}
(void) memcpy(data_ptr, or-2, 8);
(void) memcpy(data_ptr+8, pw->seed, sizeof(pw->seed));
(void) memcpy(data_ptr+8+sizeof(pw->seed), plain, plainlen);
plaind.length = 8 + sizeof(pw->seed) + plainlen;
plaind.data = data_ptr;
krb5_free_checksum_contents(xe, &md5cksum);
code = krb5_k_make_checksum(xe, md5cksum.checksum_type,
ctx->seq, sign_usage,
&plaind, &md5cksum);
xfree(data_ptr);
if (code) {
if (sealalg == 0)
xfree(plain);
if (lk == KG_TOK_SEAL_MSG)
gssalloc_free(token.value);
*ib = code;
return(GSS_S_FAILURE);
}
code = k5_bcmp(md5cksum.contents, or + 14, 8);
default:
*ib = 0;
return(GSS_S_DEFECTIVE_TOKEN);
case SGN_ALG_HMAC_SHA1_DES3_KD:
case SGN_ALG_HMAC_MD5:
if (! (data_ptr = xmalloc(8 + plainlen))) {
if (sealalg != 0xffff)
xfree(plain);
if (lk == KG_TOK_SEAL_MSG)
gssalloc_free(token.value);
*ib = ENOMEM;
return(GSS_S_FAILURE);
}
(void) memcpy(data_ptr, or-2, 8);
(void) memcpy(data_ptr+8, plain, plainlen);
plaind.length = 8 + plainlen;
plaind.data = data_ptr;
code = krb5_k_make_checksum(xe, md5cksum.checksum_type,
ctx->seq, sign_usage,
&plaind, &md5cksum);
xfree(data_ptr);
if (code) {
if (lk == KG_TOK_SEAL_MSG)
gssalloc_free(token.value);
*ib = code;
return(GSS_S_FAILURE);
}
code = k5_bcmp(md5cksum.contents, or + 14, cksum_len);
break;
}
krb5_free_checksum_contents(xe, &md5cksum);
if (sealalg != 0xffff)
xfree(plain);
if (code) {
if (lk == KG_TOK_SEAL_MSG)
gssalloc_free(token.value);
*ib = 0;
return(GSS_S_BAD_SIG);
}
if (lk == KG_TOK_SEAL_MSG)
*wp = token;
if (conf_state)
*conf_state = (sealalg != 0xffff);
if (fr)
*fr = GSS_C_QOP_DEFAULT;
if ((pw->initiate && direction != 0xff) ||
(!ctx->initiate && direction != 0)) {
if (lk == KG_TOK_SEAL_MSG) {
gssalloc_free(token.value);
message_buffer->value = NULL;
message_buffer->length = 0;
}
*ib = (OM_uint32)G_BAD_DIRECTION;
return(GSS_S_BAD_SIG);
}
retval = g_order_check(&(pw->seqstate), (gssint_uint64)seqnum);
*ib = 0;
return(retval);
}

