TfLiteStatus mg(TfLiteContext* bx,
                                        TfLiteNode* cj, int cg,
                                        int qd, int dx,
                                        bool hr) {
  const auto* params = reinterpret_cast<TfLiteLSTMParams*>(cj->builtin_data);




  TF_LITE_ENSURE(bx, params->cell_clip >= 0);
  TF_LITE_ENSURE(bx, params->proj_clip >= 0);

  const TfLiteTensor* input_to_input_weights = GetOptionalInputTensor(
      bx, cj, lstm::full::kInputToInputWeightsTensor);
  if (input_to_input_weights != nullptr) {
    TF_LITE_ENSURE_EQ(bx, input_to_input_weights->dims->size, 2);
    TF_LITE_ENSURE_EQ(bx, input_to_input_weights->dims->data[0], dx);
    TF_LITE_ENSURE_EQ(bx, input_to_input_weights->dims->data[1], cg);
  }

  const TfLiteTensor* input_to_forget_weights =
      GetInput(bx, cj, lstm::full::kInputToForgetWeightsTensor);
  TF_LITE_ENSURE_EQ(bx, input_to_forget_weights->dims->size, 2);
  TF_LITE_ENSURE_EQ(bx, input_to_forget_weights->dims->data[0], dx);
  TF_LITE_ENSURE_EQ(bx, input_to_forget_weights->dims->data[1], cg);

  const TfLiteTensor* input_to_cell_weights =
      GetInput(bx, cj, lstm::full::kInputToCellWeightsTensor);
  TF_LITE_ENSURE_EQ(bx, input_to_cell_weights->dims->size, 2);
  TF_LITE_ENSURE_EQ(bx, input_to_cell_weights->dims->data[0], dx);
  TF_LITE_ENSURE_EQ(bx, input_to_cell_weights->dims->data[1], cg);

  const TfLiteTensor* recurrent_to_input_weights = GetOptionalInputTensor(
      bx, cj, lstm::full::kRecurrentToInputWeightsTensor);
  if (recurrent_to_input_weights != nullptr) {
    TF_LITE_ENSURE_EQ(bx, recurrent_to_input_weights->dims->size, 2);
    TF_LITE_ENSURE_EQ(bx, recurrent_to_input_weights->dims->data[0],
                      dx);
    TF_LITE_ENSURE_EQ(bx, recurrent_to_input_weights->dims->data[1],
                      qd);
  }

  const TfLiteTensor* recurrent_to_forget_weights =
      GetInput(bx, cj, lstm::full::kRecurrentToForgetWeightsTensor);
  TF_LITE_ENSURE_EQ(bx, recurrent_to_forget_weights->dims->size, 2);
  TF_LITE_ENSURE_EQ(bx, recurrent_to_forget_weights->dims->data[0],
                    dx);
  TF_LITE_ENSURE_EQ(bx, recurrent_to_forget_weights->dims->data[1],
                    qd);

  const TfLiteTensor* recurrent_to_cell_weights =
      GetInput(bx, cj, lstm::full::kRecurrentToCellWeightsTensor);
  TF_LITE_ENSURE_EQ(bx, recurrent_to_cell_weights->dims->size, 2);
  TF_LITE_ENSURE_EQ(bx, recurrent_to_cell_weights->dims->data[0], dx);
  TF_LITE_ENSURE_EQ(bx, recurrent_to_cell_weights->dims->data[1],
                    qd);



  const bool cifg_weights_all_or_none =
      ((input_to_input_weights != nullptr) &&
       (recurrent_to_input_weights != nullptr)) ||
      ((input_to_input_weights == nullptr) &&
       (recurrent_to_input_weights == nullptr));
  TF_LITE_ENSURE(bx, cifg_weights_all_or_none == true);

  const TfLiteTensor* cell_to_input_weights = GetOptionalInputTensor(
      bx, cj, lstm::full::kCellToInputWeightsTensor);
  if (cell_to_input_weights != nullptr) {
    TF_LITE_ENSURE_EQ(bx, cell_to_input_weights->dims->size, 1);
    TF_LITE_ENSURE_EQ(bx, cell_to_input_weights->dims->data[0], dx);
  }

  const TfLiteTensor* cell_to_forget_weights = GetOptionalInputTensor(
      bx, cj, lstm::full::kCellToForgetWeightsTensor);
  if (cell_to_forget_weights != nullptr) {
    TF_LITE_ENSURE_EQ(bx, cell_to_forget_weights->dims->size, 1);
    TF_LITE_ENSURE_EQ(bx, cell_to_forget_weights->dims->data[0], dx);
  }

  const TfLiteTensor* cell_to_output_weights = GetOptionalInputTensor(
      bx, cj, lstm::full::kCellToOutputWeightsTensor);
  if (cell_to_output_weights != nullptr) {
    TF_LITE_ENSURE_EQ(bx, cell_to_output_weights->dims->size, 1);
    TF_LITE_ENSURE_EQ(bx, cell_to_output_weights->dims->data[0], dx);
  }


  const bool use_cifg = (input_to_input_weights == nullptr);
  const bool peephole_weights_all_or_none =
      ((cell_to_input_weights != nullptr || use_cifg) &&
       (cell_to_forget_weights != nullptr) &&
       (cell_to_output_weights != nullptr)) ||
      ((cell_to_input_weights == nullptr) &&
       (cell_to_forget_weights == nullptr) &&
       (cell_to_output_weights == nullptr));
  TF_LITE_ENSURE(bx, peephole_weights_all_or_none == true);


  const TfLiteTensor* input_gate_bias =
      GetOptionalInputTensor(bx, cj, lstm::full::kInputGateBiasTensor);
  if (use_cifg) {
    TF_LITE_ENSURE_EQ(bx, input_gate_bias, nullptr);
  } else {
    TF_LITE_ENSURE_EQ(bx, input_gate_bias->dims->size, 1);
    TF_LITE_ENSURE_EQ(bx, input_gate_bias->dims->data[0], dx);
  }

  const TfLiteTensor* forget_gate_bias =
      GetInput(bx, cj, lstm::full::kForgetGateBiasTensor);
  TF_LITE_ENSURE_EQ(bx, forget_gate_bias->dims->size, 1);
  TF_LITE_ENSURE_EQ(bx, forget_gate_bias->dims->data[0], dx);

  const TfLiteTensor* cell_gate_bias =
      GetInput(bx, cj, lstm::full::kCellGateBiasTensor);
  TF_LITE_ENSURE_EQ(bx, cell_gate_bias->dims->size, 1);
  TF_LITE_ENSURE_EQ(bx, cell_gate_bias->dims->data[0], dx);

  const TfLiteTensor* output_gate_bias =
      GetInput(bx, cj, lstm::full::kOutputGateBiasTensor);
  TF_LITE_ENSURE_EQ(bx, output_gate_bias->dims->size, 1);
  TF_LITE_ENSURE_EQ(bx, output_gate_bias->dims->data[0], dx);

  const TfLiteTensor* projection_weights = GetOptionalInputTensor(
      bx, cj, lstm::full::kProjectionWeightsTensor);
  if (projection_weights != nullptr) {
    TF_LITE_ENSURE_EQ(bx, projection_weights->dims->size, 2);
    TF_LITE_ENSURE_EQ(bx, projection_weights->dims->data[0], qd);
    TF_LITE_ENSURE_EQ(bx, projection_weights->dims->data[1], dx);
  }

  const TfLiteTensor* projection_bias =
      GetOptionalInputTensor(bx, cj, lstm::full::kProjectionBiasTensor);
  if (projection_bias != nullptr) {
    TF_LITE_ENSURE_EQ(bx, projection_bias->dims->size, 1);
    TF_LITE_ENSURE_EQ(bx, projection_bias->dims->data[0], qd);
  }






  const bool projecton_tensors_consistent =
      ((projection_weights != nullptr) || (projection_bias == nullptr));
  TF_LITE_ENSURE(bx, projecton_tensors_consistent == true);

  if (hr) {
    const TfLiteTensor* input_layer_norm_coefficients = GetOptionalInputTensor(
        bx, cj, lstm::full::kInputLayerNormCoefficientsTensor);
    if (use_cifg) {
      TF_LITE_ENSURE_EQ(bx, input_layer_norm_coefficients, nullptr);
    } else {
      TF_LITE_ENSURE(bx, input_layer_norm_coefficients != nullptr);
      TF_LITE_ENSURE_EQ(bx, input_layer_norm_coefficients->dims->size, 1);
      TF_LITE_ENSURE_EQ(bx, input_layer_norm_coefficients->dims->data[0],
                        dx);
      TF_LITE_ENSURE_TYPES_EQ(bx, input_layer_norm_coefficients->type,
                              kTfLiteFloat32);
    }

    const TfLiteTensor* forget_layer_norm_coefficients =
        GetInput(bx, cj, lstm::full::kForgetLayerNormCoefficientsTensor);
    TF_LITE_ENSURE(bx, forget_layer_norm_coefficients != nullptr);
    TF_LITE_ENSURE_EQ(bx, forget_layer_norm_coefficients->dims->size, 1);
    TF_LITE_ENSURE_EQ(bx, forget_layer_norm_coefficients->dims->data[0],
                      dx);
    TF_LITE_ENSURE_TYPES_EQ(bx, forget_layer_norm_coefficients->type,
                            kTfLiteFloat32);

    const TfLiteTensor* cell_layer_norm_coefficients =
        GetInput(bx, cj, lstm::full::kCellLayerNormCoefficientsTensor);
    TF_LITE_ENSURE(bx, cell_layer_norm_coefficients != nullptr);
    TF_LITE_ENSURE_EQ(bx, cell_layer_norm_coefficients->dims->size, 1);
    TF_LITE_ENSURE_EQ(bx, cell_layer_norm_coefficients->dims->data[0],
                      dx);
    TF_LITE_ENSURE_TYPES_EQ(bx, cell_layer_norm_coefficients->type,
                            kTfLiteFloat32);

    const TfLiteTensor* output_layer_norm_coefficients =
        GetInput(bx, cj, lstm::full::kOutputLayerNormCoefficientsTensor);
    TF_LITE_ENSURE(bx, output_layer_norm_coefficients != nullptr);
    TF_LITE_ENSURE_EQ(bx, output_layer_norm_coefficients->dims->size, 1);
    TF_LITE_ENSURE_EQ(bx, output_layer_norm_coefficients->dims->data[0],
                      dx);
    TF_LITE_ENSURE_TYPES_EQ(bx, output_layer_norm_coefficients->type,
                            kTfLiteFloat32);
  }

  return kTfLiteOk;
}

static noinline void vh(struct list_head *gq)
{
while (!list_empty(gq)) {
struct key *key =
list_entry(gq->next, struct key, graveyard_link);
list_del(&key->graveyard_link);
kdebug("- %u", key->serial);
key_check(key);
if (key->type->destroy)
key->type->destroy(key);
security_key_free(key);
if (test_bit(KEY_FLAG_IN_QUOTA, &key->flags)) {
spin_lock(&key->user->lock);
key->user->qnkeys--;
key->user->qnbytes -= key->quotalen;
spin_unlock(&key->user->lock);
}
atomic_dec(&key->user->nkeys);
if (test_bit(KEY_FLAG_INSTANTIATED, &key->flags))
atomic_dec(&key->user->nikeys);
key_user_put(key->user);
kfree(key->description);
#ifdef KEY_DEBUGGING
key->magic = KEY_DEBUG_MAGIC_X;
#endif
kmem_cache_free(key_jar, key);
}
}

