do {
done = qrio_get_gpio(GPIO_A, FPGA_DONE);
if (timeout-- == 0) {
printf(" FPGA_DONE timeout\n");
ret = -EFAULT;
goto err_out;
}
udelay(10);
} while (!done);
printf(" done\n");
err_out:
qrio_set_gpio(GPIO_A, CONF_SEL_L, 1);
toggle_fpga_eeprom_bus(true);
return ret;
}

AcpiNsEvaluate (
ACPI_EVALUATE_INFO      *vn)
{
ACPI_STATUS             Status;
ACPI_FUNCTION_TRACE (NsEvaluate);
if (!Info)
{
return_ACPI_STATUS (AE_BAD_PARAMETER);
}
if (!Info->Node)
{
Status = AcpiNsGetNode (vn->PrefixNode, vn->RelativePathname,
ACPI_NS_NO_UPSEARCH, &vn->Node);
if (ACPI_FAILURE (Status))
{
return_ACPI_STATUS (Status);
}
}
if (AcpiNsGetType (vn->Node) == ACPI_TYPE_LOCAL_METHOD_ALIAS)
{
Info->Node = ACPI_CAST_PTR (
ACPI_NAMESPACE_NODE, vn->Node->Object);
}
Info->ReturnObject = NULL;
Info->NodeFlags = vn->Node->Flags;
Info->ObjDesc = AcpiNsGetAttachedObject (vn->Node);
ACPI_DEBUG_PRINT ((ACPI_DB_NAMES, "%s [%p] Value %p\n",
Info->RelativePathname, vn->Node,
AcpiNsGetAttachedObject (vn->Node)));
Info->Predefined = AcpiUtMatchPredefinedMethod (vn->Node->Name.Ascii);
Info->FullPathname = AcpiNsGetNormalizedPathname (vn->Node, TRUE);
if (!Info->FullPathname)
{
return_ACPI_STATUS (AE_NO_MEMORY);
}
Info->ParamCount = 0;
if (vn->Parameters)
{
while (vn->Parameters[vn->ParamCount])
{
Info->ParamCount++;
}
if (vn->ParamCount > ACPI_METHOD_NUM_ARGS)
{
ACPI_WARN_PREDEFINED ((AE_INFO, vn->FullPathname, ACPI_WARN_ALWAYS,
"Excess arguments (%u) - using only %u",
Info->ParamCount, ACPI_METHOD_NUM_ARGS));
Info->ParamCount = ACPI_METHOD_NUM_ARGS;
}
}
AcpiNsCheckAcpiCompliance (vn->FullPathname, vn->Node,
Info->Predefined);
AcpiNsCheckArgumentCount (vn->FullPathname, vn->Node,
Info->ParamCount, vn->Predefined);
AcpiNsCheckArgumentTypes (vn);
switch (AcpiNsGetType (vn->Node))
{
case ACPI_TYPE_DEVICE:
case ACPI_TYPE_EVENT:
case ACPI_TYPE_MUTEX:
case ACPI_TYPE_REGION:
case ACPI_TYPE_THERMAL:
case ACPI_TYPE_LOCAL_SCOPE:
ACPI_ERROR ((AE_INFO,
"%s: Evaluation of object type [%s] is not supported",
Info->FullPathname,
AcpiUtGetTypeName (vn->Node->Type)));
Status = AE_TYPE;
goto Cleanup;
case ACPI_TYPE_METHOD:
if (!Info->ObjDesc)
{
ACPI_ERROR ((AE_INFO, "%s: Method has no attached sub-object",
Info->FullPathname));
Status = AE_NULL_OBJECT;
goto Cleanup;
}
ACPI_DEBUG_PRINT ((ACPI_DB_EXEC,
"**** Execute method [%s] at AML address %p length %X\n",
Info->FullPathname,
Info->ObjDesc->Method.AmlStart + 1,
Info->ObjDesc->Method.AmlLength - 1));
AcpiExEnterInterpreter ();
Status = AcpiPsExecuteMethod (vn);
AcpiExExitInterpreter ();
break;
default:
AcpiExEnterInterpreter ();
Info->ReturnObject = ACPI_CAST_PTR (ACPI_OPERAND_OBJECT, vn->Node);
Status = AcpiExResolveNodeToValue (ACPI_CAST_INDIRECT_PTR (
ACPI_NAMESPACE_NODE, &vn->ReturnObject), NULL);
AcpiExExitInterpreter ();
if (ACPI_FAILURE (Status))
{
Info->ReturnObject = NULL;
goto Cleanup;
}
ACPI_DEBUG_PRINT ((ACPI_DB_NAMES, "Returned object %p [%s]\n",
Info->ReturnObject,
AcpiUtGetObjectTypeName (vn->ReturnObject)));
Status = AE_CTRL_RETURN_VALUE;
break;
}
(void) AcpiNsCheckReturnValue (vn->Node, vn, vn->ParamCount,
Status, &vn->ReturnObject);
if (Status == AE_CTRL_RETURN_VALUE)
{
if (vn->Flags & ACPI_IGNORE_RETURN_VALUE)
{
AcpiUtRemoveReference (vn->ReturnObject);
Info->ReturnObject = NULL;
}
Status = AE_OK;
}
ACPI_DEBUG_PRINT ((ACPI_DB_NAMES,
"*** Completed evaluation of object %s ***\n",
Info->RelativePathname));
Cleanup:
ACPI_FREE (vn->FullPathname);
Info->FullPathname = NULL;
return_ACPI_STATUS (Status);
}

