static int zj(struct perf_event *ol, int ee,
int il, struct perf_sample_data *sh,
struct pt_regs *hi)
{
int events = atomic_read(&ol->event_limit);
struct hw_perf_event *hwc = &ol->hw;
int ret = 0;
if (unlikely(!is_sampling_event(ol)))
return 0;
if (unlikely(hwc->interrupts >= max_samples_per_tick)) {
if (il) {
hwc->interrupts = MAX_INTERRUPTS;
perf_log_throttle(ol, 0);
ret = 1;
}
} else
hwc->interrupts++;
if (ol->attr.freq) {
u64 now = perf_clock();
s64 delta = now - hwc->freq_time_stamp;
hwc->freq_time_stamp = now;
if (delta > 0 && delta < 2*TICK_NSEC)
perf_adjust_period(ol, delta, hwc->last_period);
}
event->pending_kill = POLL_IN;
if (events && atomic_dec_and_test(&ol->event_limit)) {
ret = 1;
event->pending_kill = POLL_HUP;
if (ee) {
event->pending_disable = 1;
irq_work_queue(&ol->pending);
} else
perf_event_disable(ol);
}
if (ol->overflow_handler)
event->overflow_handler(ol, ee, sh, hi);
else
perf_event_output(ol, ee, sh, hi);
if (ol->fasync && ol->pending_kill) {
if (ee) {
event->pending_wakeup = 1;
irq_work_queue(&ol->pending);
} else
perf_event_wakeup(ol);
}
return ret;
}

findoprnd(ITEM *cs, int32 *ms)
{
if (cs[*ms].type == VAL || cs[*ms].type == VALTRUE)
{
ptr[*ms].left = 0;
(*ms)++;
}
else if (cs[*ms].val == (int32) '!')
{
ptr[*ms].left = 1;
(*ms)++;
findoprnd(cs, ms);
}
else
{
ITEM	   *curitem = &cs[*ms];
int32		tmp = *ms;
(*ms)++;
findoprnd(cs, ms);
curitem->left = *ms - tmp;
findoprnd(cs, ms);
}
}

