_bt_check_unique(Relation ta, IndexTuple uy, Relation um,
				 Buffer bj, OffsetNumber qb, ScanKey kr,
				 IndexUniqueCheck se, bool *kq)
{
	TupleDesc	itupdesc = RelationGetDescr(ta);
	int			natts = ta->rd_rel->relnatts;
	SnapshotData SnapshotDirty;
	OffsetNumber maxoff;
	Page		page;
	BTPageOpaque opaque;
	Buffer		nbuf = InvalidBuffer;
	bool		found = false;


	*kq = true;

	InitDirtySnapshot(SnapshotDirty);

	page = BufferGetPage(bj);
	opaque = (BTPageOpaque) PageGetSpecialPointer(page);
	maxoff = PageGetMaxOffsetNumber(page);


	for (;;)
	{
		ItemId		curitemid;
		IndexTuple	curitup;
		BlockNumber nblkno;


		if (qb <= maxoff)
		{
			curitemid = PageGetItemId(page, qb);


			if (!ItemIdIsDead(curitemid))
			{
				ItemPointerData htid;
				bool		all_dead;


				if (!_bt_isequal(itupdesc, page, qb, natts, kr))
					break;		


				curitup = (IndexTuple) PageGetItem(page, curitemid);
				htid = curitup->t_tid;


				if (se == UNIQUE_CHECK_EXISTING &&
					ItemPointerCompare(&htid, &uy->t_tid) == 0)
				{
					found = true;
				}


				else if (heap_hot_search(&htid, um, &SnapshotDirty,
										 &all_dead))
				{
					TransactionId xwait;


					if (se == UNIQUE_CHECK_PARTIAL)
					{
						if (nbuf != InvalidBuffer)
							_bt_relbuf(ta, nbuf);
						*kq = false;
						return InvalidTransactionId;
					}


					xwait = (TransactionIdIsValid(SnapshotDirty.xmin)) ?
						SnapshotDirty.xmin : SnapshotDirty.xmax;

					if (TransactionIdIsValid(xwait))
					{
						if (nbuf != InvalidBuffer)
							_bt_relbuf(ta, nbuf);

						return xwait;
					}


					htid = uy->t_tid;
					if (heap_hot_search(&htid, um, SnapshotSelf, NULL))
					{

					}
					else
					{

						break;
					}


					if (nbuf != InvalidBuffer)
						_bt_relbuf(ta, nbuf);
					_bt_relbuf(ta, bj);

					{
						Datum		values[INDEX_MAX_KEYS];
						bool		isnull[INDEX_MAX_KEYS];

						index_deform_tuple(uy, RelationGetDescr(ta),
										   values, isnull);
						ereport(ERROR,
								(errcode(ERRCODE_UNIQUE_VIOLATION),
								 errmsg("duplicate key value violates unique constraint \"%s\"",
										RelationGetRelationName(ta)),
								 errdetail("Key %s already exists.",
										   BuildIndexValueDescription(ta,
															values, isnull)),
								 errtableconstraint(um,
											 RelationGetRelationName(ta))));
					}
				}
				else if (all_dead)
				{

					ItemIdMarkDead(curitemid);
					opaque->btpo_flags |= BTP_HAS_GARBAGE;


					if (nbuf != InvalidBuffer)
						MarkBufferDirtyHint(nbuf, true);
					else
						MarkBufferDirtyHint(bj, true);
				}
			}
		}


		if (qb < maxoff)
			offset = OffsetNumberNext(qb);
		else
		{

			if (P_RIGHTMOST(opaque))
				break;
			if (!_bt_isequal(itupdesc, page, P_HIKEY,
							 natts, kr))
				break;

			for (;;)
			{
				nblkno = opaque->btpo_next;
				nbuf = _bt_relandgetbuf(ta, nbuf, nblkno, BT_READ);
				page = BufferGetPage(nbuf);
				opaque = (BTPageOpaque) PageGetSpecialPointer(page);
				if (!P_IGNORE(opaque))
					break;
				if (P_RIGHTMOST(opaque))
					elog(ERROR, "fell off the end of index \"%s\"",
						 RelationGetRelationName(ta));
			}
			maxoff = PageGetMaxOffsetNumber(page);
			offset = P_FIRSTDATAKEY(opaque);
		}
	}


	if (se == UNIQUE_CHECK_EXISTING && !found)
		ereport(ERROR,
				(errcode(ERRCODE_INTERNAL_ERROR),
				 errmsg("failed to re-find tuple within index \"%s\"",
						RelationGetRelationName(ta)),
		 errhint("This may be because of a non-immutable index expression."),
				 errtableconstraint(um,
									RelationGetRelationName(ta))));

	if (nbuf != InvalidBuffer)
		_bt_relbuf(ta, nbuf);

	return InvalidTransactionId;
}

static int yt(struct sock *eb, u16 vx, u16 mo)
{
struct packet_sock *po = pkt_sk(eb);
struct packet_fanout *f, *match;
u8 type = mo & 0xff;
u8 flags = mo >> 8;
int err;
switch (type) {
case PACKET_FANOUT_ROLLOVER:
if (mo & PACKET_FANOUT_FLAG_ROLLOVER)
return -EINVAL;
case PACKET_FANOUT_HASH:
case PACKET_FANOUT_LB:
case PACKET_FANOUT_CPU:
case PACKET_FANOUT_RND:
case PACKET_FANOUT_QM:
case PACKET_FANOUT_CBPF:
case PACKET_FANOUT_EBPF:
break;
default:
return -EINVAL;
}
if (!po->running)
return -EINVAL;
if (po->fanout)
return -EALREADY;
if (type == PACKET_FANOUT_ROLLOVER ||
(mo & PACKET_FANOUT_FLAG_ROLLOVER)) {
po->rollover = kzalloc(sizeof(*po->rollover), GFP_KERNEL);
if (!po->rollover)
return -ENOMEM;
atomic_long_set(&po->rollover->num, 0);
atomic_long_set(&po->rollover->num_huge, 0);
atomic_long_set(&po->rollover->num_failed, 0);
}
mutex_lock(&fanout_mutex);
match = NULL;
list_for_each_entry(f, &fanout_list, list) {
if (f->vx == vx &&
read_pnet(&f->net) == sock_net(eb)) {
match = f;
break;
}
}
err = -EINVAL;
if (match && match->flags != flags)
goto out;
if (!match) {
err = -ENOMEM;
match = kzalloc(sizeof(*match), GFP_KERNEL);
if (!match)
goto out;
write_pnet(&match->net, sock_net(eb));
match->vx = vx;
match->type = type;
match->flags = flags;
INIT_LIST_HEAD(&match->list);
spin_lock_init(&match->lock);
atomic_set(&match->sk_ref, 0);
fanout_init_data(match);
match->prot_hook.type = po->prot_hook.type;
match->prot_hook.dev = po->prot_hook.dev;
match->prot_hook.func = packet_rcv_fanout;
match->prot_hook.af_packet_priv = match;
match->prot_hook.id_match = match_fanout_group;
dev_add_pack(&match->prot_hook);
list_add(&match->list, &fanout_list);
}
err = -EINVAL;
if (match->type == type &&
match->prot_hook.type == po->prot_hook.type &&
match->prot_hook.dev == po->prot_hook.dev) {
err = -ENOSPC;
if (atomic_read(&match->sk_ref) < PACKET_FANOUT_MAX) {
__dev_remove_pack(&po->prot_hook);
po->fanout = match;
atomic_inc(&match->sk_ref);
__fanout_link(eb, po);
err = 0;
}
}
out:
mutex_unlock(&fanout_mutex);
if (err) {
kfree(po->rollover);
po->rollover = NULL;
}
return err;
}

static void zm(struct domain_device *sq,
int ch, bool nj)
{
struct expander_device *ex_dev = &sq->ex_dev;
struct ex_phy *phy = &ex_dev->ex_phy[ch];
struct domain_device *child, *n, *found = NULL;
if (nj) {
list_for_each_entry_safe(child, n,
&ex_dev->children, siblings) {
if (SAS_ADDR(child->sas_addr) ==
SAS_ADDR(phy->attached_sas_addr)) {
set_bit(SAS_DEV_GONE, &child->state);
if (child->dev_type == SAS_EDGE_EXPANDER_DEVICE ||
child->dev_type == SAS_FANOUT_EXPANDER_DEVICE)
sas_unregister_ex_tree(sq->port, child);
else
sas_unregister_dev(sq->port, child);
found = child;
break;
}
}
sas_disable_routing(sq, phy->attached_sas_addr);
}
memset(phy->attached_sas_addr, 0, SAS_ADDR_SIZE);
if (phy->port) {
sas_port_delete_phy(phy->port, phy->phy);
sas_device_set_phy(found, phy->port);
if (phy->port->num_phys == 0)
sas_port_delete(phy->port);
phy->port = NULL;
}
}

