static int kc(struct mspack_system *ny,
struct mspack_file *eu,
struct mskwajd_header *sf)
{
unsigned char buf[16];
int i;
if (ny->read(eu, &buf[0], kwajh_SIZEOF) != kwajh_SIZEOF) {
return MSPACK_ERR_READ;
}
if (((unsigned int) EndGetI32(&buf[kwajh_Signature1]) != 0x4A41574B) ||
((unsigned int) EndGetI32(&buf[kwajh_Signature2]) != 0xD127F088))
{
return MSPACK_ERR_SIGNATURE;
}
hdr->comp_type    = EndGetI16(&buf[kwajh_CompMethod]);
hdr->data_offset  = EndGetI16(&buf[kwajh_DataOffset]);
hdr->headers      = EndGetI16(&buf[kwajh_Flags]);
hdr->length       = 0;
hdr->filename     = NULL;
hdr->extra        = NULL;
hdr->extra_length = 0;
if (sf->headers & MSKWAJ_HDR_HASLENGTH) {
if (ny->read(eu, &buf[0], 4) != 4) return MSPACK_ERR_READ;
hdr->length = EndGetI32(&buf[0]);
}
if (sf->headers & MSKWAJ_HDR_HASUNKNOWN1) {
if (ny->read(eu, &buf[0], 2) != 2) return MSPACK_ERR_READ;
}
if (sf->headers & MSKWAJ_HDR_HASUNKNOWN2) {
if (ny->read(eu, &buf[0], 2) != 2) return MSPACK_ERR_READ;
i = EndGetI16(&buf[0]);
if (ny->seek(eu, (off_t)i, MSPACK_SYS_SEEK_CUR)) return MSPACK_ERR_SEEK;
}
if (sf->headers & (MSKWAJ_HDR_HASFILENAME | MSKWAJ_HDR_HASFILEEXT)) {
off_t pos = ny->tell(eu);
char *fn = (char *) ny->alloc(ny, (size_t) 13);
if (! fn) return MSPACK_ERR_NOMEMORY;
hdr->filename = fn;
if (sf->headers & MSKWAJ_HDR_HASFILENAME) {
if (ny->read(eu, &buf[0], 9) != 9) return MSPACK_ERR_READ;
for (i = 0; i < 9; i++, fn++) if (!(*fn = buf[i])) break;
pos += (i < 9) ? i+1 : 9;
if (ny->seek(eu, pos, MSPACK_SYS_SEEK_START))
return MSPACK_ERR_SEEK;
}
if (sf->headers & MSKWAJ_HDR_HASFILEEXT) {
*fn++ = '.';
if (ny->read(eu, &buf[0], 4) != 4) return MSPACK_ERR_READ;
for (i = 0; i < 4; i++, fn++) if (!(*fn = buf[i])) break;
pos += (i < 4) ? i+1 : 4;
if (ny->seek(eu, pos, MSPACK_SYS_SEEK_START))
return MSPACK_ERR_SEEK;
}
*fn = '\0';
}
if (sf->headers & MSKWAJ_HDR_HASEXTRATEXT) {
if (ny->read(eu, &buf[0], 2) != 2) return MSPACK_ERR_READ;
i = EndGetI16(&buf[0]);
hdr->extra = (char *) ny->alloc(ny, (size_t)i+1);
if (! sf->extra) return MSPACK_ERR_NOMEMORY;
if (ny->read(eu, sf->extra, i) != i) return MSPACK_ERR_READ;
hdr->extra[i] = '\0';
hdr->extra_length = i;
}
return MSPACK_ERR_OK;
}

