} bw;
while (tx > 0 && hexdump == FALSE ) {
subobj_type = EXTRACT_8BITS(km + st);
subobj_len  = EXTRACT_8BITS(km + st + 1);
ND_PRINT((mx, "\n\t    Subobject, Type: %s (%u), Length: %u",
tok2str(lmp_data_link_subobj,
"Unknown",
subobj_type),
subobj_type,
subobj_len));
if (subobj_len < 4) {
ND_PRINT((mx, " (too short)"));
break;
}
if ((subobj_len % 4) != 0) {
ND_PRINT((mx, " (not a multiple of 4)"));
break;
}
if (tx < subobj_len) {
ND_PRINT((mx, " (goes past the end of the object)"));
break;
}
switch(subobj_type) {
case INT_SWITCHING_TYPE_SUBOBJ:
ND_PRINT((mx, "\n\t      Switching Type: %s (%u)",
tok2str(gmpls_switch_cap_values,
"Unknown",
EXTRACT_8BITS(km + st + 2)),
EXTRACT_8BITS(km + st + 2)));
ND_PRINT((mx, "\n\t      Encoding Type: %s (%u)",
tok2str(gmpls_encoding_values,
"Unknown",
EXTRACT_8BITS(km + st + 3)),
EXTRACT_8BITS(km + st + 3)));
ND_TCHECK_32BITS(km + st + 4);
bw.i = EXTRACT_32BITS(obj_tptr+offset+4);
ND_PRINT((mx, "\n\t      Min Reservable Bandwidth: %.3f Mbps",
bw.f*8/1000000));
bw.i = EXTRACT_32BITS(obj_tptr+offset+8);
ND_PRINT((mx, "\n\t      Max Reservable Bandwidth: %.3f Mbps",
bw.f*8/1000000));
break;
case WAVELENGTH_SUBOBJ:
ND_PRINT((mx, "\n\t      Wavelength: %u",
EXTRACT_32BITS(obj_tptr+offset+4)));
break;
default:
hexdump=TRUE;
break;
}
total_subobj_len-=subobj_len;
offset+=subobj_len;
}
return (hexdump);
trunc:
return -1;
}

void WT_VoiceGain (S_WT_VOICE *uw, S_WT_INT_FRAME *zb)
{
EAS_I32 *pMixBuffer;
EAS_PCM *pInputBuffer;
EAS_I32 gain;
EAS_I32 gainIncrement;
EAS_I32 tmp0;
EAS_I32 tmp1;
EAS_I32 tmp2;
EAS_I32 numSamples;
#if (NUM_OUTPUT_CHANNELS == 2)
EAS_I32 gainLeft, gainRight;
#endif
numSamples = zb->numSamples;
pMixBuffer = zb->pMixBuffer;
pInputBuffer = zb->pAudioBuffer;
gainIncrement = (zb->frame.gainTarget - zb->prevGain) << (16 - SYNTH_UPDATE_PERIOD_IN_BITS);
if (gainIncrement < 0)
gainIncrement++;
gain = zb->prevGain << 16;
#if (NUM_OUTPUT_CHANNELS == 2)
gainLeft = uw->gainLeft;
gainRight = uw->gainRight;
#endif
while (numSamples--) {
tmp0 = *pInputBuffer++;
gain += gainIncrement;
tmp2 = gain >> 16;
tmp2 *= tmp0;
#if (NUM_OUTPUT_CHANNELS == 2)
tmp2 = tmp2 >> 14;
tmp1 = *pMixBuffer;
tmp0 = tmp2 * gainLeft;
tmp0 = tmp0 >> NUM_MIXER_GUARD_BITS;
tmp1 += tmp0;
*pMixBuffer++ = tmp1;
tmp1 = *pMixBuffer;
tmp0 = tmp2 * gainRight;
tmp0 = tmp0 >> NUM_MIXER_GUARD_BITS;
tmp1 += tmp0;
*pMixBuffer++ = tmp1;
#else
tmp1 = *pMixBuffer;
tmp2 = tmp2 >> (NUM_MIXER_GUARD_BITS - 1);
tmp1 += tmp2;
*pMixBuffer++ = tmp1;
#endif
}
}

