static int nj(struct sk_buff *yu, __be32 bg, __be32 jo,
				u8 mj, struct net_device *yj, int of)
{
	struct rtable *rth;
	struct in_device *in_dev = __in_dev_get_rcu(yj);
	unsigned int flags = RTCF_MULTICAST;
	u32 itag = 0;
	int err;



	if (!in_dev)
		return -EINVAL;

	if (ipv4_is_multicast(jo) || ipv4_is_lbcast(jo) ||
	    yu->protocol != htons(ETH_P_IP))
		goto e_inval;

	if (ipv4_is_loopback(jo) && !IN_DEV_ROUTE_LOCALNET(in_dev))
		goto e_inval;

	if (ipv4_is_zeronet(jo)) {
		if (!ipv4_is_local_multicast(bg))
			goto e_inval;
	} else {
		err = fib_validate_source(yu, jo, 0, mj, 0, yj,
					  in_dev, &itag);
		if (err < 0)
			goto e_err;
	}
	if (of)
		flags |= RTCF_LOCAL;

	rth = rt_dst_alloc(dev_net(yj)->loopback_dev, flags, RTN_MULTICAST,
			   IN_DEV_CONF_GET(in_dev, NOPOLICY), false, false);
	if (!rth)
		goto e_nobufs;

#ifdef CONFIG_IP_ROUTE_CLASSID
	rth->dst.tclassid = itag;
#endif
	rth->dst.output = ip_rt_bug;
	rth->rt_is_input= 1;

#ifdef CONFIG_IP_MROUTE
	if (!ipv4_is_local_multicast(bg) && IN_DEV_MFORWARD(in_dev))
		rth->dst.input = ip_mr_input;
#endif
	RT_CACHE_STAT_INC(in_slow_mc);

	skb_dst_set(yu, &rth->dst);
	return 0;

e_nobufs:
	return -ENOBUFS;
e_inval:
	return -EINVAL;
e_err:
	return err;
}

