static size_t ko(const PSDInfo *uo,
const ImageInfo *cx,Image *qd,Image *fy,
MagickOffsetType sw,const MagickBooleanType re,
ExceptionInfo *mn)
{
Image
*mask;
MagickOffsetType
rows_offset;
size_t
channels,
count,
length,
offset_length;
unsigned char
*compact_pixels;
count=0;
offset_length=0;
rows_offset=0;
compact_pixels=(unsigned char *) NULL;
if (fy->compression == RLECompression)
{
compact_pixels=AcquireCompactPixels(qd,mn);
if (compact_pixels == (unsigned char *) NULL)
return(0);
}
channels=1;
if (re == MagickFalse)
{
if (fy->storage_class != PseudoClass)
{
if (IsImageGray(fy) == MagickFalse)
channels=next_image->colorspace == CMYKColorspace ? 4 : 3;
if (fy->alpha_trait != UndefinedPixelTrait)
channels++;
}
rows_offset=TellBlob(qd)+2;
count+=WriteCompressionStart(uo,qd,fy,channels);
offset_length=(fy->rows*(uo->version == 1 ? 2 : 4));
}
size_offset+=2;
if (fy->storage_class == PseudoClass)
{
length=WritePSDChannel(uo,cx,qd,fy,
IndexQuantum,compact_pixels,rows_offset,re,mn);
if (re != MagickFalse)
size_offset+=WritePSDSize(uo,qd,length,sw)+2;
else
rows_offset+=offset_length;
count+=length;
}
else
{
if (IsImageGray(fy) != MagickFalse)
{
length=WritePSDChannel(uo,cx,qd,fy,
GrayQuantum,compact_pixels,rows_offset,re,mn);
if (re != MagickFalse)
size_offset+=WritePSDSize(uo,qd,length,sw)+2;
else
rows_offset+=offset_length;
count+=length;
}
else
{
if (fy->colorspace == CMYKColorspace)
(void) NegateCMYK(fy,mn);
length=WritePSDChannel(uo,cx,qd,fy,
RedQuantum,compact_pixels,rows_offset,re,mn);
if (re != MagickFalse)
size_offset+=WritePSDSize(uo,qd,length,sw)+2;
else
rows_offset+=offset_length;
count+=length;
length=WritePSDChannel(uo,cx,qd,fy,
GreenQuantum,compact_pixels,rows_offset,re,mn);
if (re != MagickFalse)
size_offset+=WritePSDSize(uo,qd,length,sw)+2;
else
rows_offset+=offset_length;
count+=length;
length=WritePSDChannel(uo,cx,qd,fy,
BlueQuantum,compact_pixels,rows_offset,re,mn);
if (re != MagickFalse)
size_offset+=WritePSDSize(uo,qd,length,sw)+2;
else
rows_offset+=offset_length;
count+=length;
if (fy->colorspace == CMYKColorspace)
{
length=WritePSDChannel(uo,cx,qd,fy,
BlackQuantum,compact_pixels,rows_offset,re,mn);
if (re != MagickFalse)
size_offset+=WritePSDSize(uo,qd,length,sw)+2;
else
rows_offset+=offset_length;
count+=length;
}
}
if (fy->alpha_trait != UndefinedPixelTrait)
{
length=WritePSDChannel(uo,cx,qd,fy,
AlphaQuantum,compact_pixels,rows_offset,re,mn);
if (re != MagickFalse)
size_offset+=WritePSDSize(uo,qd,length,sw)+2;
else
rows_offset+=offset_length;
count+=length;
}
}
compact_pixels=(unsigned char *) RelinquishMagickMemory(compact_pixels);
if (fy->colorspace == CMYKColorspace)
(void) NegateCMYK(fy,mn);
if (re != MagickFalse)
{
const char
*property;
property=GetImageArtifact(fy,"psd:opacity-mask");
if (property != (const char *) NULL)
{
mask=(Image *) GetImageRegistry(ImageRegistryType,property,
exception);
if (mask != (Image *) NULL)
{
if (mask->compression == RLECompression)
{
compact_pixels=AcquireCompactPixels(mask,mn);
if (compact_pixels == (unsigned char *) NULL)
return(0);
}
length=WritePSDChannel(uo,cx,qd,mask,
RedQuantum,compact_pixels,rows_offset,MagickTrue,mn);
(void) WritePSDSize(uo,qd,length,sw);
count+=length;
compact_pixels=(unsigned char *) RelinquishMagickMemory(
compact_pixels);
}
}
}
return(count);
}

u32 oc(__be32 af, __be32 os, __be16 wg)
{
struct keydata *keyptr = get_keyptr();
u32 hash[4];
hash[0] = (__force u32)af;
hash[1] = (__force u32)os;
hash[2] = (__force u32)wg ^ keyptr->secret[10];
hash[3] = keyptr->secret[11];
return half_md4_transform(hash, keyptr->secret);
}

