static int fm(struct bpf_verifier_env *ul, int cq,
int wm, bool xz,
struct bpf_call_arg_meta *qt)
{
struct bpf_verifier_state *state = ul->cur_state;
struct bpf_reg_state *regs = state->regs;
int off, i, slot, spi;
if (regs[cq].type != PTR_TO_STACK) {
if (xz && wm == 0 &&
register_is_null(regs[cq]))
return 0;
verbose(ul, "R%d type=%s expected=%s\n", cq,
reg_type_str[regs[cq].type],
reg_type_str[PTR_TO_STACK]);
return -EACCES;
}
if (!tnum_is_const(regs[cq].var_off)) {
char tn_buf[48];
tnum_strn(tn_buf, sizeof(tn_buf), regs[cq].var_off);
verbose(ul, "invalid variable stack read R%d var_off=%s\n",
regno, tn_buf);
}
off = regs[cq].off + regs[cq].var_off.value;
if (off >= 0 || off < -MAX_BPF_STACK || off + wm > 0 ||
access_size < 0 || (wm == 0 && !zero_size_allowed)) {
verbose(ul, "invalid stack type R%d off=%d access_size=%d\n",
regno, off, wm);
return -EACCES;
}
if (ul->prog->aux->stack_depth < -off)
env->prog->aux->stack_depth = -off;
if (qt && qt->raw_mode) {
meta->wm = wm;
meta->cq = cq;
return 0;
}
for (i = 0; i < wm; i++) {
slot = -(off + i) - 1;
spi = slot / BPF_REG_SIZE;
if (state->allocated_stack <= slot ||
state->stack[spi].slot_type[slot % BPF_REG_SIZE] !=
STACK_MISC) {
verbose(ul, "invalid indirect read from stack off %d+%d size %d\n",
off, i, wm);
return -EACCES;
}
}
return 0;
}

void sv(struct ieee80211_sta *rm, struct ath_softc *by,
struct ath_node *fk)
{
struct ath_atx_tid *tid;
struct ath_atx_ac *ac;
struct ath_txq *txq;
bool buffered;
int tidno;
for (tidno = 0, tid = &fk->tid[tidno];
tidno < IEEE80211_NUM_TIDS; tidno++, tid++) {
if (!tid->sched)
continue;
ac = tid->ac;
txq = ac->txq;
ath_txq_lock(by, txq);
buffered = ath_tid_has_buffered(tid);
tid->sched = false;
list_del(&tid->list);
if (ac->sched) {
ac->sched = false;
list_del(&ac->list);
}
ath_txq_unlock(by, txq);
ieee80211_sta_set_buffered(rm, tidno, buffered);
}
}

