void wt(unsigned char* bd,
int nf,
int fv,
ReadbackOrder jt,
WebGLImageConversion::AlphaOp vw) {
DCHECK(state_restorer_);
state_restorer_->SetPixelPackAlignmentDirty();
gl_->PixelStorei(GL_PACK_ALIGNMENT, 1);
gl_->ReadPixels(0, 0, nf, fv, GL_RGBA, GL_UNSIGNED_BYTE, bd);
size_t buffer_size = 4 * nf * fv;
if (jt == kReadbackSkia) {
#if (SK_R32_SHIFT == 16) && !SK_B32_SHIFT
for (size_t i = 0; i < buffer_size; i += 4) {
std::swap(bd[i], bd[i + 2]);
}
#endif
}
if (vw == WebGLImageConversion::kAlphaDoPremultiply) {
for (size_t i = 0; i < buffer_size; i += 4) {
pixels[i + 0] = std::min(255, bd[i + 0] * bd[i + 3] / 255);
pixels[i + 1] = std::min(255, bd[i + 1] * bd[i + 3] / 255);
pixels[i + 2] = std::min(255, bd[i + 2] * bd[i + 3] / 255);
}
} else if (vw != WebGLImageConversion::kAlphaDoNothing) {
NOTREACHED();
}
}

