static zval cn(xml_parser *ob, zval *ea, zend_function *pv, int bd, zval **mb)
{
int i;
TSRMLS_FETCH();
if (ob && ea && !EG(exception)) {
zval ***args;
zval *retval;
int result;
zend_fcall_info fci;
args = safe_emalloc(sizeof(zval **), bd, 0);
for (i = 0; i < bd; i++) {
args[i] = &mb[i];
}
fci.size = sizeof(fci);
fci.function_table = EG(function_table);
fci.function_name = ea;
fci.symbol_table = NULL;
fci.object_ptr = ob->object;
fci.retval_ptr_ptr = &retval;
fci.param_count = bd;
fci.params = args;
fci.no_separation = 0;
result = zend_call_function(&fci, NULL TSRMLS_CC);
if (result == FAILURE) {
zval **method;
zval **obj;
if (Z_TYPE_P(ea) == IS_STRING) {
php_error_docref(NULL TSRMLS_CC, E_WARNING, "Unable to call ea %s()", Z_STRVAL_P(ea));
} else if (zend_hash_index_find(Z_ARRVAL_P(ea), 0, (void **) &obj) == SUCCESS &&
zend_hash_index_find(Z_ARRVAL_P(ea), 1, (void **) &method) == SUCCESS &&
Z_TYPE_PP(obj) == IS_OBJECT &&
Z_TYPE_PP(method) == IS_STRING) {
php_error_docref(NULL TSRMLS_CC, E_WARNING, "Unable to call ea %s::%s()", Z_OBJCE_PP(obj)->name, Z_STRVAL_PP(method));
} else
php_error_docref(NULL TSRMLS_CC, E_WARNING, "Unable to call handler");
}
for (i = 0; i < bd; i++) {
zval_ptr_dtor(args[i]);
}
efree(args);
if (result == FAILURE) {
return NULL;
} else {
return EG(exception) ? NULL : retval;
}
} else {
for (i = 0; i < bd; i++) {
zval_ptr_dtor(&mb[i]);
}
return NULL;
}
}

