break;
extent=ExportQuantumPixels(ht,(const CacheView *) NULL,
quantum_info,quantum_type,pixels,&ht->exception);
(void) WriteBlob(ht,extent,pixels);
if (ht->previous == (Image *) NULL)
{
status=SetImageProgress(ht,SaveImageTag,(MagickOffsetType) y,
image->rows);
