}
}
quantum_info=DestroyQuantumInfo(quantum_info);
break;
}
}
if (GetNextImageInList(ht) == (Image *) NULL)
break;
image=SyncNextImageInList(ht);
status=SetImageProgress(ht,SaveImagesTag,scene++,imageListLength);
if (status == MagickFalse)
break;
} while (sn->adjoin != MagickFalse);
(void) CloseBlob(ht);
return(MagickTrue);
