EncodedJSValue JSC_HOST_CALL mc(ExecState* fp)
{
if (fp->argumentCount() < 1)
return throwVMError(fp, createTypeError(fp, "Not enough arguments"));
JSObject* object = fp->argument(0).getObject();
if (!object) {
setDOMException(fp, TYPE_MISMATCH_ERR);
return JSValue::encode(jsUndefined());
}
JSWebKitMutationObserverConstructor* jsConstructor = jsCast<JSWebKitMutationObserverConstructor*>(fp->callee());
RefPtr<MutationCallback> callback = JSMutationCallback::create(object, jsConstructor->globalObject());
return JSValue::encode(asObject(toJS(fp, jsConstructor->globalObject(), WebKitMutationObserver::create(callback.release()))));
}

