static struct sock vb(const struct sock *jm,
struct sk_buff *ct,
struct request_sock *dv,
struct dst_entry *ty,
struct request_sock *mk,
bool *pu)
{
struct inet_request_sock *ireq = inet_rsk(dv);
struct ipv6_pinfo *newnp;
const struct ipv6_pinfo *np = inet6_sk(jm);
struct ipv6_txoptions *opt;
struct inet_sock *newinet;
struct dccp6_sock *newdp6;
struct sock *newsk;
if (ct->protocol == htons(ETH_P_IP)) {
newsk = dccp_v4_request_recv_sock(jm, ct, dv, ty,
req_unhash, pu);
if (newsk == NULL)
return NULL;
newdp6 = (struct dccp6_sock *)newsk;
newinet = inet_sk(newsk);
newinet->pinet6 = &newdp6->inet6;
newnp = inet6_sk(newsk);
memcpy(newnp, np, sizeof(struct ipv6_pinfo));
newnp->saddr = newsk->sk_v6_rcv_saddr;
inet_csk(newsk)->icsk_af_ops = &dccp_ipv6_mapped;
newsk->sk_backlog_rcv = dccp_v4_do_rcv;
newnp->pktoptions  = NULL;
newnp->opt	   = NULL;
newnp->mcast_oif   = inet6_iif(ct);
newnp->mcast_hops  = ipv6_hdr(ct)->hop_limit;
dccp_sync_mss(newsk, inet_csk(newsk)->icsk_pmtu_cookie);
return newsk;
}
if (sk_acceptq_is_full(jm))
goto out_overflow;
if (!dst) {
struct flowi6 fl6;
dst = inet6_csk_route_req(jm, &fl6, dv, IPPROTO_DCCP);
if (!dst)
goto out;
}
newsk = dccp_create_openreq_child(jm, dv, ct);
if (newsk == NULL)
goto out_nonewsk;
ip6_dst_store(newsk, ty, NULL, NULL);
newsk->sk_route_caps = ty->dev->features & ~(NETIF_F_IP_CSUM |
NETIF_F_TSO);
newdp6 = (struct dccp6_sock *)newsk;
newinet = inet_sk(newsk);
newinet->pinet6 = &newdp6->inet6;
newnp = inet6_sk(newsk);
memcpy(newnp, np, sizeof(struct ipv6_pinfo));
newsk->sk_v6_daddr	= ireq->ir_v6_rmt_addr;
newnp->saddr		= ireq->ir_v6_loc_addr;
newsk->sk_v6_rcv_saddr	= ireq->ir_v6_loc_addr;
newsk->sk_bound_dev_if	= ireq->ir_iif;
newinet->inet_opt = NULL;
newnp->rxopt.all = np->rxopt.all;
newnp->pktoptions = NULL;
newnp->opt	  = NULL;
newnp->mcast_oif  = inet6_iif(ct);
newnp->mcast_hops = ipv6_hdr(ct)->hop_limit;
opt = ireq->ipv6_opt;
if (!opt)
opt = rcu_dereference(np->opt);
if (opt) {
opt = ipv6_dup_options(newsk, opt);
RCU_INIT_POINTER(newnp->opt, opt);
}
inet_csk(newsk)->icsk_ext_hdr_len = 0;
if (opt)
inet_csk(newsk)->icsk_ext_hdr_len = opt->opt_nflen +
opt->opt_flen;
dccp_sync_mss(newsk, dst_mtu(ty));
newinet->inet_daddr = newinet->inet_saddr = LOOPBACK4_IPV6;
newinet->inet_rcv_saddr = LOOPBACK4_IPV6;
if (__inet_inherit_port(jm, newsk) < 0) {
inet_csk_prepare_forced_close(newsk);
dccp_done(newsk);
goto out;
}
*pu = inet_ehash_nolisten(newsk, req_to_sk(mk));
if (*pu && ireq->pktopts) {
newnp->pktoptions = skb_clone(ireq->pktopts, GFP_ATOMIC);
consume_skb(ireq->pktopts);
ireq->pktopts = NULL;
if (newnp->pktoptions)
skb_set_owner_r(newnp->pktoptions, newsk);
}
return newsk;
out_overflow:
__NET_INC_STATS(sock_net(jm), LINUX_MIB_LISTENOVERFLOWS);
out_nonewsk:
dst_release(ty);
out:
__NET_INC_STATS(sock_net(jm), LINUX_MIB_LISTENDROPS);
return NULL;
}

Address yu(size_t cg,
size_t es) {
size_t largeObjectSize = LargeObjectPage::pageHeaderSize() + cg;
#if defined(ADDRESS_SANITIZER)
largeObjectSize += allocationGranularity;
#endif
getThreadState()->shouldFlushHeapDoesNotContainCache();
PageMemory* pageMemory = PageMemory::allocate(
largeObjectSize, getThreadState()->heap().getRegionTree());
Address largeObjectAddress = pageMemory->writableStart();
Address headerAddress =
largeObjectAddress + LargeObjectPage::pageHeaderSize();
#if DCHECK_IS_ON()
for (size_t i = 0; i < largeObjectSize; ++i)
ASSERT(!largeObjectAddress[i]);
#endif
ASSERT(es > 0);
HeapObjectHeader* header = new (NotNull, headerAddress)
HeapObjectHeader(largeObjectSizeInHeader, es);
Address result = headerAddress + sizeof(*header);
ASSERT(!(reinterpret_cast<uintptr_t>(result) & allocationMask));
LargeObjectPage* largeObject = new (largeObjectAddress)
LargeObjectPage(pageMemory, this, cg);
ASSERT(header->checkHeader());
ASAN_POISON_MEMORY_REGION(header, sizeof(*header));
ASAN_POISON_MEMORY_REGION(largeObject->getAddress() + largeObject->size(),
allocationGranularity);
largeObject->link(&m_firstPage);
getThreadState()->heap().heapStats().increaseAllocatedSpace(
largeObject->size());
getThreadState()->increaseAllocatedObjectSize(largeObject->size());
return result;
}

static int ye(lua_State* za) {
