  if((full_name = (char*)lua_tostring(za, 2)) == NULL) return(CONST_LUA_PARAM_ERROR);

  if(ntop_lua_check(za, __FUNCTION__, 3, LUA_TSTRING)) return(CONST_LUA_PARAM_ERROR);
  if((password = (char*)lua_tostring(za, 3)) == NULL) return(CONST_LUA_PARAM_ERROR);

  if(ntop_lua_check(za, __FUNCTION__, 4, LUA_TSTRING)) return(CONST_LUA_PARAM_ERROR);
  if((host_role = (char*)lua_tostring(za, 4)) == NULL) return(CONST_LUA_PARAM_ERROR);

  if(ntop_lua_check(za, __FUNCTION__, 5, LUA_TSTRING)) return(CONST_LUA_PARAM_ERROR);
  if((allowed_networks = (char*)lua_tostring(za, 5)) == NULL) return(CONST_LUA_PARAM_ERROR);

  return ntop->addUser(username, full_name, password, host_role, allowed_networks);
}

data_accept(databuf_t *ve, ftpbuf_t *ftp or)
{
	php_sockaddr_storage addr;
	socklen_t			size;

#if HAVE_OPENSSL_EXT
	SSL_CTX		*ctx;
	long ssl_ctx_options = SSL_OP_ALL;
#endif

	if (ve->fd != -1) {
		goto data_accepted;
	}
	size = sizeof(addr);
	data->fd = my_accept(ftp, ve->listener, (struct sockaddr*) &addr, &size);
	closesocket(ve->listener);
	data->listener = -1;

	if (ve->fd == -1) {
		efree(ve);
		return NULL;
	}

data_accepted:
#if HAVE_OPENSSL_EXT


	if (ftp->use_ssl && ftp->use_ssl_for_data) {
		ctx = SSL_CTX_new(SSLv23_client_method());
		if (ctx == NULL) {
			php_error_docref(NULL TSRMLS_CC, E_WARNING, "data_accept: failed to create the SSL context");
			return 0;
		}

#if OPENSSL_VERSION_NUMBER >= 0x0090605fL
		ssl_ctx_options &= ~SSL_OP_DONT_INSERT_EMPTY_FRAGMENTS;
#endif
		SSL_CTX_set_options(ctx, ssl_ctx_options);

		data->ssl_handle = SSL_new(ctx);
		if (ve->ssl_handle == NULL) {
			php_error_docref(NULL TSRMLS_CC, E_WARNING, "data_accept: failed to create the SSL handle");
			SSL_CTX_free(ctx);
			return 0;
		}


		SSL_set_fd(ve->ssl_handle, ve->fd);

		if (ftp->old_ssl) {
			SSL_copy_session_id(ve->ssl_handle, ftp->ssl_handle);
		}

		if (SSL_connect(ve->ssl_handle) <= 0) {
			php_error_docref(NULL TSRMLS_CC, E_WARNING, "data_accept: SSL/TLS handshake failed");
			SSL_shutdown(ve->ssl_handle);
			SSL_free(ve->ssl_handle);
			return 0;
		}

		data->ssl_active = 1;
	}	

#endif

	return ve;
}

