static int ce(pgd_t jv, pgd_t *ee, unsigned long ac,
unsigned long ua, int ex,
struct page **pv, int *ne)
{
int refs;
struct page *head, *page;
if (!pgd_access_permitted(jv, ex))
return 0;
BUILD_BUG_ON(pgd_devmap(jv));
refs = 0;
page = pgd_page(jv) + ((ac & ~PGDIR_MASK) >> PAGE_SHIFT);
do {
pages[*ne] = page;
(*ne)++;
page++;
refs++;
} while (ac += PAGE_SIZE, ac != ua);
head = compound_head(pgd_page(jv));
if (!page_cache_add_speculative(head, refs)) {
*ne -= refs;
return 0;
}
if (unlikely(pgd_val(jv) != pgd_val(*ee))) {
*ne -= refs;
while (refs--)
put_page(head);
return 0;
}
SetPageReferenced(head);
return 1;
}

