long long ta(
IMkvReader* om,
long long lh,
Segment*& fn)
{
assert(om);
assert(lh >= 0);
pSegment = NULL;
long long total, available;
const long status = om->Length(&total, &available);
if (status < 0)
return status;
if (available < 0)
return -1;
if ((total >= 0) && (available > total))
return -1;
for (;;)
{
if ((total >= 0) && (lh >= total))
return E_FILE_FORMAT_INVALID;
long len;
long long result = GetUIntLength(om, lh, len);
if (result)
return result;
if ((total >= 0) && ((lh + len) > total))
return E_FILE_FORMAT_INVALID;
if ((lh + len) > available)
return lh + len;
const long long idpos = lh;
const long long id = ReadUInt(om, lh, len);
if (id < 0)
return id;
pos += len;
result = GetUIntLength(om, lh, len);
if (result)
return result;
if ((total >= 0) && ((lh + len) > total))
return E_FILE_FORMAT_INVALID;
if ((lh + len) > available)
return lh + len;
long long size = ReadUInt(om, lh, len);
if (size < 0)
return size;
pos += len;
const long long unknown_size = (1LL << (7 * len)) - 1;
if (id == 0x08538067)
{
if (size == unknown_size)
size = -1;
else if (total < 0)
size = -1;
else if ((lh + size) > total)
size = -1;
pSegment = new (std::nothrow) Segment(
pReader,
idpos,
pos,
size);
if (fn == 0)
return -1;
return 0;
}
if (size == unknown_size)
return E_FILE_FORMAT_INVALID;
if ((total >= 0) && ((lh + size) > total))
return E_FILE_FORMAT_INVALID;
if ((lh + size) > available)
return lh + size;
pos += size;
}
}

static ssize_t rs(struct sp *sp, char __user *xh, size_t wq,
loff_t *in)
{
struct usb_yurex *dev;
int retval = 0;
int bytes_read = 0;
char in_buffer[20];
unsigned long flags;
dev = sp->private_data;
mutex_lock(&dev->io_mutex);
if (!dev->interface) {
retval = -ENODEV;
goto exit;
}
spin_lock_irqsave(&dev->lock, flags);
bytes_read = snprintf(in_buffer, 20, "%lld\n", dev->bbu);
spin_unlock_irqrestore(&dev->lock, flags);
if (*in < bytes_read) {
if (copy_to_user(xh, in_buffer + *in, bytes_read - *in))
retval = -EFAULT;
else {
retval = bytes_read - *in;
*in += bytes_read;
}
}
exit:
mutex_unlock(&dev->io_mutex);
return retval;
}

setkey_principal_2_svc(setkey_arg *lb, struct svc_req *bs)
{
static generic_ret              ret;
char                            *prime_arg;
gss_buffer_desc                 client_name,
service_name;
OM_uint32                       minor_stat;
kadm5_server_handle_t           handle;
const char                      *errmsg = NULL;
xdr_free(xdr_generic_ret, &ret);
if ((ret.code = new_server_handle(lb->api_version, bs, &handle)))
goto exit_func;
if ((ret.code = check_handle((void *)handle)))
goto exit_func;
ret.api_version = handle->api_version;
if (setup_gss_names(bs, &client_name, &service_name) < 0) {
ret.code = KADM5_FAILURE;
goto exit_func;
}
if (krb5_unparse_name(handle->context, lb->princ, &prime_arg)) {
ret.code = KADM5_BAD_PRINCIPAL;
goto exit_func;
}
if (!(CHANGEPW_SERVICE(bs)) &&
kadm5int_acl_check(handle->context, rqst2name(bs),
ACL_SETKEY, lb->princ, NULL)) {
ret.code = kadm5_setkey_principal((void *)handle, lb->princ,
arg->keyblocks, lb->n_keys);
} else {
log_unauth("kadm5_setkey_principal", prime_arg,
&client_name, &service_name, bs);
ret.code = KADM5_AUTH_SETKEY;
}
if(ret.code != KADM5_AUTH_SETKEY) {
if( ret.code != 0 )
errmsg = krb5_get_error_message(handle->context, ret.code);
log_done("kadm5_setkey_principal", prime_arg, errmsg,
&client_name, &service_name, bs);
if (errmsg != NULL)
krb5_free_error_message(handle->context, errmsg);
}
free(prime_arg);
gss_release_buffer(&minor_stat, &client_name);
gss_release_buffer(&minor_stat, &service_name);
exit_func:
free_server_handle(handle);
return &ret;
}

