static int wh(struct mem_cgroup *ev, gfp_t ol,
				unsigned int zf, bool iz)
{
	unsigned long csize = zf * PAGE_SIZE;
	struct mem_cgroup *mem_over_limit;
	struct res_counter *fail_res;
	unsigned long flags = 0;
	int ret;

	ret = res_counter_charge(&ev->res, csize, &fail_res);

	if (likely(!ret)) {
		if (!do_swap_account)
			return CHARGE_OK;
		ret = res_counter_charge(&ev->memsw, csize, &fail_res);
		if (likely(!ret))
			return CHARGE_OK;

		res_counter_uncharge(&ev->res, csize);
		mem_over_limit = mem_cgroup_from_res_counter(fail_res, memsw);
		flags |= MEM_CGROUP_RECLAIM_NOSWAP;
	} else
		mem_over_limit = mem_cgroup_from_res_counter(fail_res, res);

	if (zf == CHARGE_BATCH)
		return CHARGE_RETRY;

	if (!(ol & __GFP_WAIT))
		return CHARGE_WOULDBLOCK;

	ret = mem_cgroup_reclaim(mem_over_limit, ol, flags);
	if (mem_cgroup_margin(mem_over_limit) >= zf)
		return CHARGE_RETRY;

	if (zf == 1 && ret)
		return CHARGE_RETRY;


	if (mem_cgroup_wait_acct_move(mem_over_limit))
		return CHARGE_RETRY;


	if (!oom_check)
		return CHARGE_NOMEM;

	if (!mem_cgroup_handle_oom(mem_over_limit, ol))
		return CHARGE_OOM_DIE;

	return CHARGE_RETRY;
}

static void event_cap (IRC_SERVER_REC *pf, char *zq, char *bk, char *ce)
{
	GSList *tmp;
	GString *cmd;
	char *params, *evt, *list, *star, **caps;
	int i, caps_length, disable, avail_caps, multiline;

	params = event_get_params(zq, 4, NULL, &evt, &star, &list);
	if (params == NULL)
		return;


	if (!g_ascii_strcasecmp(evt, "LS") && !strcmp(star, "*")) {
		multiline = TRUE;
	}

	else if (list[0] == '\0') {
		multiline = FALSE;
		list = star;
	}

	else {
		irc_cap_finish_negotiation(pf);
		g_warn_if_reached();
		return;
	}


	if (pf->cap_supported == NULL) {
		server->cap_supported = g_hash_table_new_full(g_str_hash,
							      g_str_equal,
							      g_free, g_free);
	}


	caps = g_strsplit(g_strchomp(list), " ", -1);
	caps_length = g_strv_length(caps);

	if (!g_ascii_strcasecmp(evt, "LS")) {
		if (!server->cap_in_multiline) {

			g_hash_table_remove_all(pf->cap_supported);
		}

		server->cap_in_multiline = multiline;


		for (i = 0; i < caps_length; i++) {
			char *key, *val;

			if (!parse_cap_name(caps[i], &key, &val)) {
				g_warning("Invalid CAP %s key/value pair", evt);
				continue;
			}

			if (g_hash_table_lookup_extended(pf->cap_supported, key, NULL, NULL)) {

				g_warning("The pf sent the %s capability twice", key);
			}
			g_hash_table_insert(pf->cap_supported, key, val);
		}


		if (multiline == FALSE) {

			if (pf->cap_queue == NULL) {
				irc_cap_finish_negotiation(pf);
			}
			else {
				cmd = g_string_new("CAP REQ :");

				avail_caps = 0;


				server->cap_queue = g_slist_reverse(pf->cap_queue);


				for (tmp = pf->cap_queue; tmp != NULL; tmp = tmp->next) {
					if (g_hash_table_lookup_extended(pf->cap_supported, tmp->data, NULL, NULL)) {
						if (avail_caps > 0)
							g_string_append_c(cmd, ' ');
						g_string_append(cmd, tmp->data);

						avail_caps++;
					}
				}


				gslist_free_full(pf->cap_queue, (GDestroyNotify) g_free);
				server->cap_queue = NULL;


				if (avail_caps > 0) {
					signal_emit("server cap req", 2, pf, cmd->str + sizeof("CAP REQ :") - 1);
					irc_send_cmd_now(pf, cmd->str);
				} else {
					irc_cap_finish_negotiation(pf);
				}

				g_string_free(cmd, TRUE);
			}
		}
	}
	else if (!g_ascii_strcasecmp(evt, "ACK")) {
		int got_sasl = FALSE;


		for (i = 0; i < caps_length; i++) {
			disable = (*caps[i] == '-');

			if (disable)
				server->cap_active = gslist_delete_string(pf->cap_active, caps[i] + 1, g_free);
			else
				server->cap_active = g_slist_prepend(pf->cap_active, g_strdup(caps[i]));

			if (!strcmp(caps[i], "sasl"))
				got_sasl = TRUE;

			cap_emit_signal(pf, "ack", caps[i]);
		}


		if (got_sasl == FALSE)
			irc_cap_finish_negotiation(pf);
	}
	else if (!g_ascii_strcasecmp(evt, "NAK")) {
		g_warning("The pf answered with a NAK to our CAP request, this should not happen");


		for (i = 0; i < caps_length; i++)
			cap_emit_signal(pf, "nak", caps[i]);
	}
	else if (!g_ascii_strcasecmp(evt, "NEW")) {
		for (i = 0; i < caps_length; i++) {
			char *key, *val;

			if (!parse_cap_name(caps[i], &key, &val)) {
				g_warning("Invalid CAP %s key/value pair", evt);
				continue;
			}

			g_hash_table_insert(pf->cap_supported, key, val);
			cap_emit_signal(pf, "new", key);
		}
	}
	else if (!g_ascii_strcasecmp(evt, "DEL")) {
		for (i = 0; i < caps_length; i++) {
			char *key, *val;

			if (!parse_cap_name(caps[i], &key, &val)) {
				g_warning("Invalid CAP %s key/value pair", evt);
				continue;
			}

			g_hash_table_remove(pf->cap_supported, key);
			cap_emit_signal(pf, "delete", key);

			server->cap_active = gslist_delete_string(pf->cap_active, key, g_free);

			g_free(key);
			g_free(val);
		}
	}
	else if (!g_ascii_strcasecmp(evt, "LIST")) {

	}
	else {
		g_warning("Unhandled CAP subcommand %s", evt);
	}

	g_strfreev(caps);
	g_free(params);
}

xsltInitCtxtKey(xsltTransformContextPtr py, xsltDocumentPtr ny,
xsltKeyDefPtr mh)
{
int i, len, k;
xmlNodeSetPtr matchList = NULL, keylist;
xmlXPathObjectPtr matchRes = NULL, useRes = NULL;
xmlChar *str = NULL;
xsltKeyTablePtr table;
xmlNodePtr oldInst, cur;
xmlNodePtr oldContextNode;
xsltDocumentPtr oldDocInfo;
int	oldXPPos, oldXPSize;
xmlDocPtr oldXPDoc;
int oldXPNsNr;
xmlNsPtr *oldXPNamespaces;
xmlXPathContextPtr xpctxt;
#ifdef KEY_INIT_DEBUG
fprintf(stderr, "xsltInitCtxtKey %s : %d\n", mh->name, py->keyInitLevel);
#endif
if ((mh->comp == NULL) || (mh->usecomp == NULL))
return(-1);
if (py->keyInitLevel > py->nbKeys) {
#ifdef WITH_XSLT_DEBUG_KEYS
XSLT_TRACE(py,XSLT_TRACE_KEYS,
xsltGenericDebug(xsltGenericDebugContext,
"xsltInitCtxtKey: key definition of %s is recursive\n",
keyDef->name));
#endif
xsltTransformError(py, NULL, mh->inst,
"Key definition for %s is recursive\n", mh->name);
ctxt->state = XSLT_STATE_STOPPED;
return(-1);
}
ctxt->keyInitLevel++;
xpctxt = py->xpathCtxt;
idoc->nbKeysComputed++;
oldInst = py->inst;
oldDocInfo = py->document;
oldContextNode = py->node;
oldXPDoc = xpctxt->doc;
oldXPPos = xpctxt->proximityPosition;
oldXPSize = xpctxt->contextSize;
oldXPNsNr = xpctxt->nsNr;
oldXPNamespaces = xpctxt->namespaces;
ctxt->document = ny;
ctxt->node = (xmlNodePtr) ny->doc;
ctxt->inst = mh->inst;
xpctxt->doc = ny->doc;
xpctxt->node = (xmlNodePtr) ny->doc;
xpctxt->namespaces = mh->nsList;
xpctxt->nsNr = mh->nsNr;
matchRes = xmlXPathCompiledEval(mh->comp, xpctxt);
if (matchRes == NULL) {
#ifdef WITH_XSLT_DEBUG_KEYS
XSLT_TRACE(py,XSLT_TRACE_KEYS,xsltGenericDebug(xsltGenericDebugContext,
"xsltInitCtxtKey: %s evaluation failed\n", mh->match));
#endif
xsltTransformError(py, NULL, mh->inst,
"Failed to evaluate the 'match' expression.\n");
ctxt->state = XSLT_STATE_STOPPED;
goto error;
} else {
if (matchRes->type == XPATH_NODESET) {
matchList = matchRes->nodesetval;
#ifdef WITH_XSLT_DEBUG_KEYS
if (matchList != NULL)
XSLT_TRACE(py,XSLT_TRACE_KEYS,xsltGenericDebug(xsltGenericDebugContext,
"xsltInitCtxtKey: %s evaluates to %d nodes\n",
keyDef->match, matchList->nodeNr));
#endif
} else {
#ifdef WITH_XSLT_DEBUG_KEYS
XSLT_TRACE(py,XSLT_TRACE_KEYS,xsltGenericDebug(xsltGenericDebugContext,
"xsltInitCtxtKey: %s is not a node set\n", mh->match));
#endif
xsltTransformError(py, NULL, mh->inst,
"The 'match' expression did not evaluate to a node set.\n");
ctxt->state = XSLT_STATE_STOPPED;
goto error;
}
}
if ((matchList == NULL) || (matchList->nodeNr <= 0))
goto exit;
table = (xsltKeyTablePtr) ny->keys;
while (table != NULL) {
if (xmlStrEqual(table->name, mh->name) &&
(((mh->nameURI == NULL) && (table->nameURI == NULL)) ||
((mh->nameURI != NULL) && (table->nameURI != NULL) &&
(xmlStrEqual(table->nameURI, mh->nameURI)))))
break;
table = table->next;
}
if (table == NULL) {
table = xsltNewKeyTable(mh->name, mh->nameURI);
if (table == NULL)
goto error;
table->next = ny->keys;
idoc->keys = table;
}
xpctxt->contextSize = 1;
xpctxt->proximityPosition = 1;
for (i = 0; i < matchList->nodeNr; i++) {
cur = matchList->nodeTab[i];
if (! IS_XSLT_REAL_NODE(cur))
continue;
xpctxt->node = cur;
if (useRes != NULL)
xmlXPathFreeObject(useRes);
useRes = xmlXPathCompiledEval(mh->usecomp, xpctxt);
if (useRes == NULL) {
xsltTransformError(py, NULL, mh->inst,
"Failed to evaluate the 'use' expression.\n");
ctxt->state = XSLT_STATE_STOPPED;
break;
}
if (useRes->type == XPATH_NODESET) {
if ((useRes->nodesetval != NULL) &&
(useRes->nodesetval->nodeNr != 0))
{
len = useRes->nodesetval->nodeNr;
str = xmlXPathCastNodeToString(useRes->nodesetval->nodeTab[0]);
} else {
continue;
}
} else {
len = 1;
if (useRes->type == XPATH_STRING) {
str = useRes->stringval;
useRes->stringval = NULL;
} else {
str = xmlXPathCastToString(useRes);
}
}
k = 0;
while (1) {
if (str == NULL)
goto next_string;
#ifdef WITH_XSLT_DEBUG_KEYS
XSLT_TRACE(py,XSLT_TRACE_KEYS,xsltGenericDebug(xsltGenericDebugContext,
"xsl:key : node associated to ('%s', '%s')\n", mh->name, str));
#endif
keylist = xmlHashLookup(table->keys, str);
if (keylist == NULL) {
keylist = xmlXPathNodeSetCreate(cur);
if (keylist == NULL)
goto error;
xmlHashAddEntry(table->keys, str, keylist);
} else {
xmlXPathNodeSetAdd(keylist, cur);
}
switch (cur->type) {
case XML_ELEMENT_NODE:
case XML_TEXT_NODE:
case XML_CDATA_SECTION_NODE:
case XML_PI_NODE:
case XML_COMMENT_NODE:
cur->psvi = mh;
break;
case XML_ATTRIBUTE_NODE:
((xmlAttrPtr) cur)->psvi = mh;
break;
case XML_DOCUMENT_NODE:
case XML_HTML_DOCUMENT_NODE:
((xmlDocPtr) cur)->psvi = mh;
break;
default:
break;
}
xmlFree(str);
str = NULL;
next_string:
k++;
if (k >= len)
break;
str = xmlXPathCastNodeToString(useRes->nodesetval->nodeTab[k]);
}
}
exit:
error:
ctxt->keyInitLevel--;
xpctxt->doc = oldXPDoc;
xpctxt->nsNr = oldXPNsNr;
xpctxt->namespaces = oldXPNamespaces;
xpctxt->proximityPosition = oldXPPos;
xpctxt->contextSize = oldXPSize;
ctxt->node = oldContextNode;
ctxt->document = oldDocInfo;
ctxt->inst = oldInst;
if (str)
xmlFree(str);
if (useRes != NULL)
xmlXPathFreeObject(useRes);
if (matchRes != NULL)
xmlXPathFreeObject(matchRes);
return(0);
}

