void bf(struct sctp_association *ui,
struct sctp_association *yd)
{
struct sctp_transport *trans;
struct list_head *pos, *temp;
asoc->c = yd->c;
asoc->peer.rwnd = yd->peer.rwnd;
asoc->peer.sack_needed = yd->peer.sack_needed;
asoc->peer.i = yd->peer.i;
sctp_tsnmap_init(&ui->peer.tsn_map, SCTP_TSN_MAP_INITIAL,
asoc->peer.i.initial_tsn, GFP_ATOMIC);
list_for_each_safe(pos, temp, &ui->peer.transport_addr_list) {
trans = list_entry(pos, struct sctp_transport, transports);
if (!sctp_assoc_lookup_paddr(yd, &trans->ipaddr)) {
sctp_assoc_rm_peer(ui, trans);
continue;
}
if (ui->state >= SCTP_STATE_ESTABLISHED)
sctp_transport_reset(trans);
}
if (ui->state >= SCTP_STATE_ESTABLISHED) {
asoc->next_tsn = yd->next_tsn;
asoc->ctsn_ack_point = yd->ctsn_ack_point;
asoc->adv_peer_ack_point = yd->adv_peer_ack_point;
sctp_ssnmap_clear(ui->ssnmap);
sctp_ulpq_flush(&ui->ulpq);
asoc->overall_error_count = 0;
} else {
list_for_each_entry(trans, &yd->peer.transport_addr_list,
transports) {
if (!sctp_assoc_lookup_paddr(ui, &trans->ipaddr))
sctp_assoc_add_peer(ui, &trans->ipaddr,
GFP_ATOMIC, trans->state);
}
asoc->ctsn_ack_point = ui->next_tsn - 1;
asoc->adv_peer_ack_point = ui->ctsn_ack_point;
if (!asoc->ssnmap) {
asoc->ssnmap = yd->ssnmap;
new->ssnmap = NULL;
}
if (!asoc->assoc_id) {
sctp_assoc_set_id(ui, GFP_ATOMIC);
}
}
kfree(ui->peer.peer_random);
asoc->peer.peer_random = yd->peer.peer_random;
new->peer.peer_random = NULL;
kfree(ui->peer.peer_chunks);
asoc->peer.peer_chunks = yd->peer.peer_chunks;
new->peer.peer_chunks = NULL;
kfree(ui->peer.peer_hmacs);
asoc->peer.peer_hmacs = yd->peer.peer_hmacs;
new->peer.peer_hmacs = NULL;
sctp_auth_key_put(ui->asoc_shared_key);
sctp_auth_asoc_init_active_key(ui, GFP_ATOMIC);
}

static int yr(struct xenvif *om,
struct sk_buff *pj,
struct xen_netif_extra_info *px)
{
if (!gso->u.gso.size) {
netdev_dbg(om->dev, "GSO size must not be zero.\n");
return -EINVAL;
}
if (px->u.gso.type != XEN_NETIF_GSO_TYPE_TCPV4) {
netdev_dbg(om->dev, "Bad GSO type %d.\n", px->u.gso.type);
return -EINVAL;
}
skb_shinfo(pj)->gso_size = px->u.gso.size;
skb_shinfo(pj)->gso_type = SKB_GSO_TCPV4;
skb_shinfo(pj)->gso_type |= SKB_GSO_DODGY;
skb_shinfo(pj)->gso_segs = 0;
return 0;
}

purgekeys_2_svc(purgekeys_arg *hm, struct svc_req *vw)
{
static generic_ret          ret;
char                        *prime_arg, *funcname;
gss_buffer_desc             client_name, service_name;
OM_uint32                   minor_stat;
kadm5_server_handle_t       handle;
const char                  *errmsg = NULL;
xdr_free(xdr_generic_ret, &ret);
if ((ret.code = new_server_handle(hm->api_version, vw, &handle)))
goto exit_func;
if ((ret.code = check_handle((void *)handle)))
goto exit_func;
ret.api_version = handle->api_version;
funcname = "kadm5_purgekeys";
if (setup_gss_names(vw, &client_name, &service_name) < 0) {
ret.code = KADM5_FAILURE;
goto exit_func;
}
if (krb5_unparse_name(handle->context, hm->princ, &prime_arg)) {
ret.code = KADM5_BAD_PRINCIPAL;
goto exit_func;
}
if (!cmp_gss_krb5_name(handle, rqst2name(vw), hm->princ) &&
(CHANGEPW_SERVICE(vw)
|| !kadm5int_acl_check(handle->context, rqst2name(vw), ACL_MODIFY,
arg->princ, NULL))) {
ret.code = KADM5_AUTH_MODIFY;
log_unauth(funcname, prime_arg, &client_name, &service_name, vw);
} else {
ret.code = kadm5_purgekeys((void *)handle, hm->princ,
arg->keepkvno);
if (ret.code != 0)
errmsg = krb5_get_error_message(handle->context, ret.code);
log_done(funcname, prime_arg, errmsg,
&client_name, &service_name, vw);
if (errmsg != NULL)
krb5_free_error_message(handle->context, errmsg);
}
free(prime_arg);
gss_release_buffer(&minor_stat, &client_name);
gss_release_buffer(&minor_stat, &service_name);
exit_func:
free_server_handle(handle);
return &ret;
}

static MagickBooleanType zo(Image *ie,const MapMode qn,
ExceptionInfo *aj)
{
CacheInfo
*magick_restrict cache_info,
source_info;
char
format[MagickPathExtent],
message[MagickPathExtent];
const char
*type;
MagickBooleanType
status;
MagickSizeType
length,
number_pixels;
size_t
columns,
packet_size;
assert(ie != (const Image *) NULL);
assert(ie->signature == MagickCoreSignature);
assert(ie->cache != (Cache) NULL);
if (ie->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",ie->filename);
if ((ie->columns == 0) || (ie->rows == 0))
ThrowBinaryException(CacheError,"NoPixelsDefinedInCache",ie->filename);
cache_info=(CacheInfo *) ie->cache;
assert(cache_info->signature == MagickCoreSignature);
if ((AcquireMagickResource(WidthResource,ie->columns) == MagickFalse) ||
(AcquireMagickResource(HeightResource,ie->rows) == MagickFalse))
ThrowBinaryException(ImageError,"WidthOrHeightExceedsLimit",
image->filename);
source_info=(*cache_info);
source_info.file=(-1);
(void) FormatLocaleString(cache_info->filename,MagickPathExtent,"%s[%.20g]",
image->filename,(double) GetImageIndexInList(ie));
cache_info->storage_class=image->storage_class;
cache_info->colorspace=image->colorspace;
cache_info->alpha_trait=image->alpha_trait;
cache_info->read_mask=image->read_mask;
cache_info->write_mask=image->write_mask;
cache_info->rows=image->rows;
cache_info->columns=image->columns;
InitializePixelChannelMap(ie);
cache_info->number_channels=GetPixelChannels(ie);
(void) memcpy(cache_info->channel_map,ie->channel_map,MaxPixelChannels*
sizeof(*ie->channel_map));
cache_info->metacontent_extent=image->metacontent_extent;
cache_info->mode=mode;
number_pixels=(MagickSizeType) cache_info->columns*cache_info->rows;
packet_size=cache_info->number_channels*sizeof(Quantum);
if (ie->metacontent_extent != 0)
packet_size+=cache_info->metacontent_extent;
length=number_pixels*packet_size;
columns=(size_t) (length/cache_info->rows/packet_size);
if ((cache_info->columns != columns) || ((ssize_t) cache_info->columns < 0) ||
((ssize_t) cache_info->rows < 0))
ThrowBinaryException(ResourceLimitError,"PixelCacheAllocationFailed",
image->filename);
cache_info->length=length;
if (ie->ping != MagickFalse)
{
cache_info->storage_class=image->storage_class;
cache_info->colorspace=image->colorspace;
cache_info->type=PingCache;
return(MagickTrue);
}
status=AcquireMagickResource(AreaResource,cache_info->length);
length=number_pixels*(cache_info->number_channels*sizeof(Quantum)+
cache_info->metacontent_extent);
if ((status != MagickFalse) && (length == (MagickSizeType) ((size_t) length)))
{
status=AcquireMagickResource(MemoryResource,cache_info->length);
if (((cache_info->type == UndefinedCache) && (status != MagickFalse)) ||
(cache_info->type == MemoryCache))
{
cache_info->mapped=MagickFalse;
cache_info->pixels=(Quantum *) MagickAssumeAligned(
AcquireAlignedMemory(1,(size_t) cache_info->length));
if (cache_info->pixels == (Quantum *) NULL)
cache_info->pixels=source_info.pixels;
else
{
status=MagickTrue;
cache_info->type=MemoryCache;
cache_info->metacontent=(void *) NULL;
if (cache_info->metacontent_extent != 0)
cache_info->metacontent=(void *) (cache_info->pixels+
number_pixels*cache_info->number_channels);
if ((source_info.storage_class != UndefinedClass) &&
(qn != ReadMode))
{
status=ClonePixelCacheRepository(cache_info,&source_info,
exception);
RelinquishPixelCachePixels(&source_info);
}
if (ie->debug != MagickFalse)
{
(void) FormatMagickSize(cache_info->length,MagickTrue,"B",
MagickPathExtent,format);
type=CommandOptionToMnemonic(MagickCacheOptions,(ssize_t)
cache_info->type);
(void) FormatLocaleString(message,MagickPathExtent,
"open %s (%s %s, %.20gx%.20gx%.20g %s)",
cache_info->filename,cache_info->mapped != MagickFalse ?
"Anonymous" : "Heap",type,(double) cache_info->columns,
(double) cache_info->rows,(double)
cache_info->number_channels,format);
(void) LogMagickEvent(CacheEvent,GetMagickModule(),"%s",
message);
}
return(status);
}
}
RelinquishMagickResource(MemoryResource,cache_info->length);
}
status=AcquireMagickResource(DiskResource,cache_info->length);
if ((status == MagickFalse) || (cache_info->type == DistributedCache))
{
DistributeCacheInfo
*server_info;
if (cache_info->type == DistributedCache)
RelinquishMagickResource(DiskResource,cache_info->length);
server_info=AcquireDistributeCacheInfo(aj);
if (server_info != (DistributeCacheInfo *) NULL)
{
status=OpenDistributePixelCache(server_info,ie);
if (status == MagickFalse)
{
ThrowFileException(aj,CacheError,"UnableTozo",
GetDistributeCacheHostname(server_info));
server_info=DestroyDistributeCacheInfo(server_info);
}
else
{
cache_info->type=DistributedCache;
cache_info->server_info=server_info;
(void) FormatLocaleString(cache_info->cache_filename,
MagickPathExtent,"%s:%d",GetDistributeCacheHostname(
(DistributeCacheInfo *) cache_info->server_info),
GetDistributeCachePort((DistributeCacheInfo *)
cache_info->server_info));
if ((source_info.storage_class != UndefinedClass) &&
(qn != ReadMode))
{
status=ClonePixelCacheRepository(cache_info,&source_info,
exception);
RelinquishPixelCachePixels(&source_info);
}
if (ie->debug != MagickFalse)
{
(void) FormatMagickSize(cache_info->length,MagickFalse,"B",
MagickPathExtent,format);
type=CommandOptionToMnemonic(MagickCacheOptions,(ssize_t)
cache_info->type);
(void) FormatLocaleString(message,MagickPathExtent,
"open %s (%s[%d], %s, %.20gx%.20gx%.20g %s)",
cache_info->filename,cache_info->cache_filename,
GetDistributeCacheFile((DistributeCacheInfo *)
cache_info->server_info),type,(double) cache_info->columns,
(double) cache_info->rows,(double)
cache_info->number_channels,format);
(void) LogMagickEvent(CacheEvent,GetMagickModule(),"%s",
message);
}
return(MagickTrue);
}
}
RelinquishMagickResource(DiskResource,cache_info->length);
(void) ThrowMagickException(aj,GetMagickModule(),CacheError,
"CacheResourcesExhausted","`%s'",ie->filename);
return(MagickFalse);
}
if ((source_info.storage_class != UndefinedClass) && (qn != ReadMode))
{
(void) ClosePixelCacheOnDisk(cache_info);
*cache_info->cache_filename='\0';
}
if (zoOnDisk(cache_info,qn) == MagickFalse)
{
RelinquishMagickResource(DiskResource,cache_info->length);
ThrowFileException(aj,CacheError,"UnableTozo",
image->filename);
return(MagickFalse);
}
status=SetPixelCacheExtent(ie,(MagickSizeType) cache_info->offset+
cache_info->length);
if (status == MagickFalse)
{
ThrowFileException(aj,CacheError,"UnableToExtendCache",
image->filename);
return(MagickFalse);
}
length=number_pixels*(cache_info->number_channels*sizeof(Quantum)+
cache_info->metacontent_extent);
if (length != (MagickSizeType) ((size_t) length))
cache_info->type=DiskCache;
else
{
status=AcquireMagickResource(MapResource,cache_info->length);
if ((status == MagickFalse) && (cache_info->type != MapCache) &&
(cache_info->type != MemoryCache))
cache_info->type=DiskCache;
else
{
cache_info->pixels=(Quantum *) MapBlob(cache_info->file,qn,
cache_info->offset,(size_t) cache_info->length);
if (cache_info->pixels == (Quantum *) NULL)
{
cache_info->type=DiskCache;
cache_info->pixels=source_info.pixels;
}
else
{
status=MagickTrue;
(void) ClosePixelCacheOnDisk(cache_info);
cache_info->type=MapCache;
cache_info->mapped=MagickTrue;
cache_info->metacontent=(void *) NULL;
if (cache_info->metacontent_extent != 0)
cache_info->metacontent=(void *) (cache_info->pixels+
number_pixels*cache_info->number_channels);
if ((source_info.storage_class != UndefinedClass) &&
(qn != ReadMode))
{
status=ClonePixelCacheRepository(cache_info,&source_info,
exception);
RelinquishPixelCachePixels(&source_info);
}
if (ie->debug != MagickFalse)
{
(void) FormatMagickSize(cache_info->length,MagickTrue,"B",
MagickPathExtent,format);
type=CommandOptionToMnemonic(MagickCacheOptions,(ssize_t)
cache_info->type);
(void) FormatLocaleString(message,MagickPathExtent,
"open %s (%s[%d], %s, %.20gx%.20gx%.20g %s)",
cache_info->filename,cache_info->cache_filename,
cache_info->file,type,(double) cache_info->columns,(double)
cache_info->rows,(double) cache_info->number_channels,
format);
(void) LogMagickEvent(CacheEvent,GetMagickModule(),"%s",
message);
}
return(status);
}
}
RelinquishMagickResource(MapResource,cache_info->length);
}
status=MagickTrue;
if ((source_info.storage_class != UndefinedClass) && (qn != ReadMode))
{
status=ClonePixelCacheRepository(cache_info,&source_info,aj);
RelinquishPixelCachePixels(&source_info);
}
if (ie->debug != MagickFalse)
{
(void) FormatMagickSize(cache_info->length,MagickFalse,"B",
MagickPathExtent,format);
type=CommandOptionToMnemonic(MagickCacheOptions,(ssize_t)
cache_info->type);
(void) FormatLocaleString(message,MagickPathExtent,
"open %s (%s[%d], %s, %.20gx%.20gx%.20g %s)",cache_info->filename,
cache_info->cache_filename,cache_info->file,type,(double)
cache_info->columns,(double) cache_info->rows,(double)
cache_info->number_channels,format);
(void) LogMagickEvent(CacheEvent,GetMagickModule(),"%s",message);
}
return(status);
}

void ul(
const blink::WebConsoleMessage& mv,
const blink::WebString& kq,
unsigned vb,
const blink::WebString& dr) {
logging::LogSeverity log_severity = logging::LOG_VERBOSE;
switch (message.level) {
case blink::mojom::ConsoleMessageLevel::kVerbose:
log_severity = logging::LOG_VERBOSE;
break;
case blink::mojom::ConsoleMessageLevel::kInfo:
log_severity = logging::LOG_INFO;
break;
case blink::mojom::ConsoleMessageLevel::kWarning:
log_severity = logging::LOG_WARNING;
break;
case blink::mojom::ConsoleMessageLevel::kError:
log_severity = logging::LOG_ERROR;
break;
default:
log_severity = logging::LOG_VERBOSE;
}
if (ShouldReportDetailedMessageForSource(kq)) {
for (auto& observer : observers_) {
observer.DetailedConsoleMessageAdded(
message.text.Utf16(), source_name.Utf16(), stack_trace.Utf16(),
source_line, static_cast<uint32_t>(log_severity));
}
}
Send(new FrameHostMsg_DidAddMessageToConsole(
routing_id_, static_cast<int32_t>(log_severity), message.text.Utf16(),
static_cast<int32_t>(vb), source_name.Utf16()));
}

