mark_context_stack(mrb_state *kr, struct mrb_context *av)
{
size_t i;
size_t e;
if (av->stack == NULL) return;
e = av->stack - av->stbase;
if (av->ci) e += av->ci->nregs;
if (av->stbase + e > av->stend) e = av->stend - av->stbase;
for (i=0; i<e; i++) {
mrb_value v = av->stbase[i];
if (!mrb_immediate_p(v)) {
if (mrb_basic_ptr(v)->tt == MRB_TT_FREE) {
c->stbase[i] = mrb_nil_value();
}
else {
mrb_gc_mark(kr, mrb_basic_ptr(v));
}
}
}
