polkit_backend_session_monitor_get_user_for_subject (PolkitBackendSessionMonitor  *an,
PolkitSubject                *dq,
GError                      **dv)
{
PolkitIdentity *ret;
guint32 uid;
ret = NULL;
if (POLKIT_IS_UNIX_PROCESS (dq))
{
