{
polkit_backend_session_monitor_get_session_for_subject (PolkitBackendSessionMonitor *an,
PolkitSubject               *dq,
GError                     **dv)
{
PolkitUnixProcess *tmp_process = NULL;
}
ret = polkit_unix_user_new (uid);
}
out:
return ret;
}
if (!tmp_process)
goto out;
process = tmp_process;
}

