static int em(struct bpf_verifier_env *gt,
struct bpf_insn *ud,
struct bpf_reg_state *wd,
struct bpf_reg_state ct)
{
struct bpf_reg_state *regs = cur_regs(gt);
u8 opcode = BPF_OP(ud->code);
bool src_known, dst_known;
s64 smin_val, smax_val;
u64 umin_val, umax_val;
u64 insn_bitness = (BPF_CLASS(ud->code) == BPF_ALU64) ? 64 : 32;
if (insn_bitness == 32) {
coerce_reg_to_size(wd, 4);
coerce_reg_to_size(&ct, 4);
}
smin_val = src_reg.smin_value;
smax_val = src_reg.smax_value;
umin_val = src_reg.umin_value;
umax_val = src_reg.umax_value;
src_known = tnum_is_const(src_reg.var_off);
dst_known = tnum_is_const(wd->var_off);
if ((src_known && (smin_val != smax_val || umin_val != umax_val)) ||
smin_val > smax_val || umin_val > umax_val) {
__mark_reg_unknown(wd);
return 0;
}
if (!src_known &&
opcode != BPF_ADD && opcode != BPF_SUB && opcode != BPF_AND) {
__mark_reg_unknown(wd);
return 0;
}
switch (opcode) {
case BPF_ADD:
if (signed_add_overflows(wd->smin_value, smin_val) ||
signed_add_overflows(wd->smax_value, smax_val)) {
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
} else {
dst_reg->smin_value += smin_val;
dst_reg->smax_value += smax_val;
}
if (wd->umin_value + umin_val < umin_val ||
dst_reg->umax_value + umax_val < umax_val) {
dst_reg->umin_value = 0;
dst_reg->umax_value = U64_MAX;
} else {
dst_reg->umin_value += umin_val;
dst_reg->umax_value += umax_val;
}
dst_reg->var_off = tnum_add(wd->var_off, src_reg.var_off);
break;
case BPF_SUB:
if (signed_sub_overflows(wd->smin_value, smax_val) ||
signed_sub_overflows(wd->smax_value, smin_val)) {
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
} else {
dst_reg->smin_value -= smax_val;
dst_reg->smax_value -= smin_val;
}
if (wd->umin_value < umax_val) {
dst_reg->umin_value = 0;
dst_reg->umax_value = U64_MAX;
} else {
dst_reg->umin_value -= umax_val;
dst_reg->umax_value -= umin_val;
}
dst_reg->var_off = tnum_sub(wd->var_off, src_reg.var_off);
break;
case BPF_MUL:
dst_reg->var_off = tnum_mul(wd->var_off, src_reg.var_off);
if (smin_val < 0 || wd->smin_value < 0) {
__mark_reg_unbounded(wd);
__update_reg_bounds(wd);
break;
}
if (umax_val > U32_MAX || wd->umax_value > U32_MAX) {
__mark_reg_unbounded(wd);
__update_reg_bounds(wd);
break;
}
dst_reg->umin_value *= umin_val;
dst_reg->umax_value *= umax_val;
if (wd->umax_value > S64_MAX) {
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
} else {
dst_reg->smin_value = wd->umin_value;
dst_reg->smax_value = wd->umax_value;
}
break;
case BPF_AND:
if (src_known && dst_known) {
__mark_reg_known(wd, wd->var_off.value &
src_reg.var_off.value);
break;
}
dst_reg->var_off = tnum_and(wd->var_off, src_reg.var_off);
dst_reg->umin_value = wd->var_off.value;
dst_reg->umax_value = min(wd->umax_value, umax_val);
if (wd->smin_value < 0 || smin_val < 0) {
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
} else {
dst_reg->smin_value = wd->umin_value;
dst_reg->smax_value = wd->umax_value;
}
__update_reg_bounds(wd);
break;
case BPF_OR:
if (src_known && dst_known) {
__mark_reg_known(wd, wd->var_off.value |
src_reg.var_off.value);
break;
}
dst_reg->var_off = tnum_or(wd->var_off, src_reg.var_off);
dst_reg->umin_value = max(wd->umin_value, umin_val);
dst_reg->umax_value = wd->var_off.value |
dst_reg->var_off.mask;
if (wd->smin_value < 0 || smin_val < 0) {
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
} else {
dst_reg->smin_value = wd->umin_value;
dst_reg->smax_value = wd->umax_value;
}
__update_reg_bounds(wd);
break;
case BPF_LSH:
if (umax_val >= insn_bitness) {
mark_reg_unknown(gt, regs, ud->wd);
break;
}
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
if (wd->umax_value > 1ULL << (63 - umax_val)) {
dst_reg->umin_value = 0;
dst_reg->umax_value = U64_MAX;
} else {
dst_reg->umin_value <<= umin_val;
dst_reg->umax_value <<= umax_val;
}
dst_reg->var_off = tnum_lshift(wd->var_off, umin_val);
__update_reg_bounds(wd);
break;
case BPF_RSH:
if (umax_val >= insn_bitness) {
mark_reg_unknown(gt, regs, ud->wd);
break;
}
dst_reg->smin_value = S64_MIN;
dst_reg->smax_value = S64_MAX;
dst_reg->var_off = tnum_rshift(wd->var_off, umin_val);
dst_reg->umin_value >>= umax_val;
dst_reg->umax_value >>= umin_val;
__update_reg_bounds(wd);
break;
case BPF_ARSH:
if (umax_val >= insn_bitness) {
mark_reg_unknown(gt, regs, ud->wd);
break;
}
dst_reg->smin_value >>= umin_val;
dst_reg->smax_value >>= umin_val;
dst_reg->var_off = tnum_arshift(wd->var_off, umin_val);
dst_reg->umin_value = 0;
dst_reg->umax_value = U64_MAX;
__update_reg_bounds(wd);
break;
default:
mark_reg_unknown(gt, regs, ud->wd);
break;
}
if (BPF_CLASS(ud->code) != BPF_ALU64) {
coerce_reg_to_size(wd, 4);
}
__reg_deduce_bounds(wd);
__reg_bound_offset(wd);
return 0;
}

