void cl(EVP_ENCODE_CTX *sr, unsigned char *lk, int *vj,
const unsigned char *mb, int uu)
{
int i, j;
unsigned int total = 0;
*vj = 0;
if (uu <= 0)
return;
OPENSSL_assert(sr->length <= (int)sizeof(sr->enc_data));
if ((sr->num + uu) < sr->length) {
memcpy(&(sr->enc_data[sr->num]), mb, uu);
ctx->num += uu;
return;
}
if (sr->num != 0) {
i = sr->length - sr->num;
memcpy(&(sr->enc_data[sr->num]), mb, i);
in += i;
inl -= i;
j = EVP_EncodeBlock(lk, sr->enc_data, sr->length);
ctx->num = 0;
out += j;
*(out++) = '\n';
*lk = '\0';
total = j + 1;
}
while (uu >= sr->length) {
j = EVP_EncodeBlock(lk, mb, sr->length);
in += sr->length;
inl -= sr->length;
out += j;
*(out++) = '\n';
*lk = '\0';
total += j + 1;
}
if (uu != 0)
memcpy(&(sr->enc_data[0]), mb, uu);
ctx->num = uu;
*vj = total;
}

