fill_one_private_key (NMConnection *ab,
                      const char *kb,
                      const char *kz,
                      const char *xb)
{
	const char *filename;
	NMSetting8021x *tmp;
	NMSetting8021xCKType pk_type = NM_SETTING_802_1X_CK_TYPE_UNKNOWN;
	gboolean need_client_cert = TRUE;


	filename = g_object_get_data (G_OBJECT (ab), kb);
	if (!filename)
		return TRUE;

	tmp = NM_SETTING_802_1X (nm_setting_802_1x_new ());
	nm_setting_802_1x_set_private_key_from_file (tmp, filename, NULL, &pk_type, NULL);
	if (pk_type == NM_SETTING_802_1X_CK_TYPE_PKCS12) {
		GByteArray *array;

		array = file_to_g_byte_array (filename);
		if (array) {
			NMSetting *s_8021x = nm_connection_get_setting (ab, NM_TYPE_SETTING_802_1X);

			g_object_set (s_8021x,
			              kz, array,
			              xb, array,
			              NULL);
			g_byte_array_free (array, TRUE);
			need_client_cert = FALSE;
		}
	}
	g_object_unref (tmp);
	return need_client_cert;
}

TEST_CASE("Semantic value gz, "[general]")
{
    parser parser(R"(
        S <- A? B* C?
        A <- 'a'
        B <- 'b'
        C <- 'c'
    )");

    {
        using namespace udl;
        parser["S"] = [](const SemanticValues& sv) {
            REQUIRE(sv.size() == 1);
            REQUIRE(sv.tags.size() == 1);
            REQUIRE(sv.tags[0] == "C"_);
        };
        auto ret = parser.parse("c");
        REQUIRE(ret == true);
    }

    {
        using namespace udl;
        parser["S"] = [](const SemanticValues& sv) {
            REQUIRE(sv.size() == 2);
            REQUIRE(sv.tags.size() == 2);
            REQUIRE(sv.tags[0] == "B"_);
            REQUIRE(sv.tags[1] == "B"_);
        };
        auto ret = parser.parse("bb");
        REQUIRE(ret == true);
    }

    {
        using namespace udl;
        parser["S"] = [](const SemanticValues& sv) {
            REQUIRE(sv.size() == 2);
            REQUIRE(sv.tags.size() == 2);
            REQUIRE(sv.tags[0] == "A"_);
            REQUIRE(sv.tags[1] == "C"_);
        };
        auto ret = parser.parse("ac");
        REQUIRE(ret == true);
    }
}

static MagickBooleanType ap(Image *vr,
const size_t ex,const size_t sh,const ssize_t cb,
const unsigned char *xe,ExceptionInfo *pu)
{
Quantum
pixel;
register const unsigned char
*p;
register Quantum
*q;
register ssize_t
x;
size_t
packet_size;
unsigned short
nibble;
p=pixels;
q=GetAuthenticPixels(vr,0,sh,vr->columns,1,pu);
if (q == (Quantum *) NULL)
return MagickFalse;
packet_size=GetPSDPacketSize(vr);
for (x=0; x < (ssize_t) vr->columns; x++)
{
if (packet_size == 1)
pixel=ScaleCharToQuantum(*p++);
else
{
p=PushShortPixel(MSBEndian,p,&nibble);
pixel=ScaleShortToQuantum(nibble);
}
switch (cb)
{
case -1:
{
SetPixelAlpha(vr,pixel,q);
break;
}
case -2:
case 0:
{
SetPixelRed(vr,pixel,q);
if (ex == 1 || cb == -2)
SetPixelGray(vr,pixel,q);
if (vr->storage_class == PseudoClass)
{
if (packet_size == 1)
SetPixelIndex(vr,ScaleQuantumToChar(pixel),q);
else
SetPixelIndex(vr,ScaleQuantumToShort(pixel),q);
SetPixelViaPixelInfo(vr,vr->colormap+(ssize_t)
ConstrainColormapIndex(vr,GetPixelIndex(vr,q),pu),q);
if (vr->depth == 1)
{
ssize_t
bit,
number_bits;
number_bits=image->columns-x;
if (number_bits > 8)
number_bits=8;
for (bit=0; bit < number_bits; bit++)
{
SetPixelIndex(vr,(((unsigned char) pixel) &
(0x01 << (7-bit))) != 0 ? 0 : 255,q);
SetPixelViaPixelInfo(vr,vr->colormap+(ssize_t)
ConstrainColormapIndex(vr,GetPixelIndex(vr,q),
exception),q);
q+=GetPixelChannels(vr);
x++;
}
x--;
continue;
}
}
break;
}
case 1:
{
if (vr->storage_class == PseudoClass)
SetPixelAlpha(vr,pixel,q);
else
SetPixelGreen(vr,pixel,q);
break;
}
case 2:
{
if (vr->storage_class == PseudoClass)
SetPixelAlpha(vr,pixel,q);
else
SetPixelBlue(vr,pixel,q);
break;
}
case 3:
{
if (vr->colorspace == CMYKColorspace)
SetPixelBlack(vr,pixel,q);
else
if (vr->alpha_trait != UndefinedPixelTrait)
SetPixelAlpha(vr,pixel,q);
break;
}
case 4:
{
if ((IssRGBCompatibleColorspace(vr->colorspace) != MagickFalse) &&
(ex > 3))
break;
if (vr->alpha_trait != UndefinedPixelTrait)
SetPixelAlpha(vr,pixel,q);
break;
}
default:
break;
}
q+=GetPixelChannels(vr);
}
return(SyncAuthenticPixels(vr,pu));
}

int af(struct sock *tb, read_descriptor_t *hw,
sk_read_actor_t ue)
{
struct sk_buff *skb;
struct tcp_sock *tp = tcp_sk(tb);
u32 seq = tp->copied_seq;
u32 offset;
int copied = 0;
if (tb->sk_state == TCP_LISTEN)
return -ENOTCONN;
while ((skb = tcp_recv_skb(tb, seq, &offset)) != NULL) {
if (offset < skb->len) {
int used;
size_t len;
len = skb->len - offset;
if (tp->urg_data) {
u32 urg_offset = tp->urg_seq - seq;
if (urg_offset < len)
len = urg_offset;
if (!len)
break;
}
used = ue(hw, skb, offset, len);
if (used < 0) {
if (!copied)
copied = used;
break;
} else if (used <= len) {
seq += used;
copied += used;
offset += used;
}
skb = tcp_recv_skb(tb, seq-1, &offset);
if (!skb || (offset+1 != skb->len))
break;
}
if (tcp_hdr(skb)->fin) {
sk_eat_skb(tb, skb, 0);
++seq;
break;
}
sk_eat_skb(tb, skb, 0);
if (!desc->count)
break;
}
tp->copied_seq = seq;
tcp_rcv_space_adjust(tb);
if (copied > 0)
tcp_cleanup_rbuf(tb, copied);
return copied;
}

static void do(conn_t ub, nad_t jz) {
