attr = nad_find_attr(jz, 0, -1, "from", NULL);
if(attr < 0 || (from = jid_new(NAD_AVAL(jz, attr), NAD_AVAL_L(jz, attr))) == NULL) {
log_debug(ZONE, "missing or invalid from on db verify packet");
nad_free(jz);
return;
}
attr = nad_find_attr(jz, 0, -1, "to", NULL);
if(attr < 0 || (to = jid_new(NAD_AVAL(jz, attr), NAD_AVAL_L(jz, attr))) == NULL) {
log_debug(ZONE, "missing or invalid to on db verify packet");
jid_free(from);
nad_free(jz);
return;
}
attr = nad_find_attr(jz, 0, -1, "id", NULL);
if(attr < 0) {
log_debug(ZONE, "missing id on db verify packet");
jid_free(from);
jid_free(to);
nad_free(jz);
return;
}
in = xhash_getx(ub->s2s->in, NAD_AVAL(jz, attr), NAD_AVAL_L(jz, attr));
if(in == NULL) {
log_debug(ZONE, "got a verify for incoming conn %.*s, but it doesn't exist, dropping the packet", NAD_AVAL_L(jz, attr), NAD_AVAL(jz, attr));
jid_free(from);
jid_free(to);
nad_free(jz);
return;
}
rkey = s2s_route_key(NULL, to->domain, from->domain);
attr = nad_find_attr(jz, 0, -1, "type", "valid");
if(attr >= 0) {
xhash_put(in->states, pstrdup(xhash_pool(in->states), rkey), (void *) conn_VALID);
log_write(in->s2s->log, LOG_NOTICE, "[%d] [%s, port=%d] incoming route '%s' is now valid%s%s", in->fd->fd, in->ip, in->port, rkey, (in->s->flags & SX_SSL_WRAPPER) ? ", TLS negotiated" : "", in->s->compressed ? ", ZLIB compression enabled" : "");
valid = 1;
} else {
log_write(in->s2s->log, LOG_NOTICE, "[%d] [%s, port=%d] incoming route '%s' is now invalid", in->fd->fd, in->ip, in->port, rkey);
valid = 0;
}
free(rkey);
nad_free(jz);
--ub->verify;
nad = nad_new();
ns = nad_add_namespace(jz, uri_DIALBACK, "db");
nad_append_elem(jz, ns, "result", 0);
nad_append_attr(jz, -1, "to", from->domain);
nad_append_attr(jz, -1, "from", to->domain);
nad_append_attr(jz, -1, "type", valid ? "valid" : "invalid");
sx_nad_write(in->s, jz);
if (!valid) {
sx_error(in->s, stream_err_INVALID_ID, "dialback negotiation failed");
sx_close(in->s);
}
jid_free(from);
jid_free(to);
}

