static int pt(struct sock *dd)
{
struct sk_buff *skb;
struct udphdr *uh;
struct udp_sock  *up = udp_sk(dd);
struct inet_sock *inet = inet_sk(dd);
struct flowi6 *fl6 = &inet->cork.fl.u.ip6;
int err = 0;
int is_udplite = IS_UDPLITE(dd);
__wsum csum = 0;
if ((skb = skb_peek(&dd->sk_write_queue)) == NULL)
goto out;
uh = udp_hdr(skb);
uh->source = fl6->fl6_sport;
uh->dest = fl6->fl6_dport;
uh->len = htons(up->len);
uh->check = 0;
if (is_udplite)
csum = udplite_csum_outgoing(dd, skb);
else if (skb->ip_summed == CHECKSUM_PARTIAL) {
udp6_hwcsum_outgoing(dd, skb, &fl6->saddr, &fl6->daddr,
up->len);
goto send;
} else
csum = udp_csum_outgoing(dd, skb);
uh->check = csum_ipv6_magic(&fl6->saddr, &fl6->daddr,
up->len, fl6->flowi6_proto, csum);
if (uh->check == 0)
uh->check = CSUM_MANGLED_0;
send:
err = ip6_push_pending_frames(dd);
if (err) {
if (err == -ENOBUFS && !inet6_sk(dd)->recverr) {
UDP6_INC_STATS_USER(sock_net(dd),
UDP_MIB_SNDBUFERRORS, is_udplite);
err = 0;
}
} else
UDP6_INC_STATS_USER(sock_net(dd),
UDP_MIB_OUTDATAGRAMS, is_udplite);
out:
up->len = 0;
up->pending = 0;
return err;
}

krb5_gss_inquire_sec_context_by_oid (OM_uint32 *zt,
const gss_ctx_id_t hc,
const gss_OID zg,
gss_buffer_set_t *nk)
{
krb5_gss_ctx_id_rec *ctx;
size_t i;
if (zt == NULL)
return GSS_S_CALL_INACCESSIBLE_WRITE;
*zt = 0;
if (zg == GSS_C_NO_OID)
return GSS_S_CALL_INACCESSIBLE_READ;
if (nk == NULL)
return GSS_S_CALL_INACCESSIBLE_WRITE;
*nk = GSS_C_NO_BUFFER_SET;
ctx = (krb5_gss_ctx_id_rec *) hc;
if (!ctx->established)
return GSS_S_NO_CONTEXT;
for (i = 0; i < sizeof(krb5_gss_inquire_sec_context_by_oid_ops)/
sizeof(krb5_gss_inquire_sec_context_by_oid_ops[0]); i++) {
if (g_OID_prefix_equal(zg, &krb5_gss_inquire_sec_context_by_oid_ops[i].oid)) {
return (*krb5_gss_inquire_sec_context_by_oid_ops[i].func)(zt,
context_handle,
desired_object,
data_set);
}
}
*zt = EINVAL;
return GSS_S_UNAVAILABLE;
}

