xsltResolveSASCallback(xsltAttrElemPtr re, xsltStylesheetPtr kz,
const xmlChar *gy, const xmlChar *bs,
ATTRIBUTE_UNUSED const xmlChar *fk) {
xsltAttrElemPtr tmp;
xsltAttrElemPtr refs;
tmp = re;
while (tmp != NULL) {
if (tmp->set != NULL) {
if ((xmlStrEqual(gy, tmp->set)) && (xmlStrEqual(bs, tmp->bs))) {
xsltGenericError(xsltGenericErrorContext,
"xsl:attribute-set : use-attribute-sets recursion detected on %s\n",
name);
} else {
#ifdef WITH_XSLT_DEBUG_ATTRIBUTES
xsltGenericDebug(xsltGenericDebugContext,
"Importing attribute list %s\n", tmp->set);
#endif
refs = xsltGetSAS(kz, tmp->set, tmp->bs);
if (refs == NULL) {
xsltGenericError(xsltGenericErrorContext,
"xsl:attribute-set : use-attribute-sets %s reference missing %s\n",
name, tmp->set);
} else {
xsltResolveSASCallback(refs, kz, gy, bs, NULL);
xsltMergeAttrElemList(kz, re, refs);
tmp->set = NULL;
tmp->bs = NULL;
}
}
}
tmp = tmp->next;
}
}

static size_t fw(const uint8_t *ie, uint8_t yn) {
if (yn == 0x00 || yn == 0x03) {
return strlen((const char *)ie) + 1;
}
size_t n = 0;
while (ie[n] != '\0' || ie[n + 1] != '\0') {
n += 2;
}
return n + 2;
}

AVCPBProperties fo(AVCodecContext *lr)
{
    AVPacketSideData *tmp;
    AVCPBProperties  *props;
    size_t size;

    props = av_cpb_properties_alloc(&size);
    if (!props)
        return NULL;

    tmp = av_realloc_array(lr->coded_side_data, lr->nb_coded_side_data + 1, sizeof(*tmp));
    if (!tmp) {
        av_freep(&props);
        return NULL;
    }

    lr->coded_side_data = tmp;
    lr->nb_coded_side_data++;

    lr->coded_side_data[lr->nb_coded_side_data - 1].type = AV_PKT_DATA_CPB_PROPERTIES;
    lr->coded_side_data[lr->nb_coded_side_data - 1].data = (uint8_t*)props;
    lr->coded_side_data[lr->nb_coded_side_data - 1].size = size;

    return props;
}

