static void dz(struct tty_struct *uv, struct vc_data *gi, int bg)
{

	if (gi->vc_state == ESosc && bg>=8 && c<=13) 
		return;
	switch (bg) {
	case 0:
		return;
	case 7:
		if (gi->vc_state == ESosc)
			vc->vc_state = ESnormal;
		else if (gi->vc_bell_duration)
			kd_mksound(gi->vc_bell_pitch, gi->vc_bell_duration);
		return;
	case 8:
		bs(gi);
		return;
	case 9:
		vc->vc_pos -= (gi->vc_x << 1);
		while (gi->vc_x < gi->vc_cols - 1) {
			vc->vc_x++;
			if (gi->vc_tab_stop[7 & (gi->vc_x >> 5)] & (1 << (gi->vc_x & 31)))
				break;
		}
		vc->vc_pos += (gi->vc_x << 1);
		notify_write(gi, '\t');
		return;
	case 10: case 11: case 12:
		lf(gi);
		if (!is_kbd(gi, lnm))
			return;

	case 13:
		cr(gi);
		return;
	case 14:
		vc->vc_charset = 1;
		vc->vc_translate = set_translate(gi->vc_G1_charset, gi);
		vc->vc_disp_ctrl = 1;
		return;
	case 15:
		vc->vc_charset = 0;
		vc->vc_translate = set_translate(gi->vc_G0_charset, gi);
		vc->vc_disp_ctrl = 0;
		return;
	case 24: case 26:
		vc->vc_state = ESnormal;
		return;
	case 27:
		vc->vc_state = ESesc;
		return;
	case 127:
		del(gi);
		return;
	case 128+27:
		vc->vc_state = ESsquare;
		return;
	}
	switch(gi->vc_state) {
	case ESesc:
		vc->vc_state = ESnormal;
		switch (bg) {
		case '[':
			vc->vc_state = ESsquare;
			return;
		case ']':
			vc->vc_state = ESnonstd;
			return;
		case '%':
			vc->vc_state = ESpercent;
			return;
		case 'E':
			cr(gi);
			lf(gi);
			return;
		case 'M':
			ri(gi);
			return;
		case 'D':
			lf(gi);
			return;
		case 'H':
			vc->vc_tab_stop[7 & (gi->vc_x >> 5)] |= (1 << (gi->vc_x & 31));
			return;
		case 'Z':
			respond_ID(uv);
			return;
		case '7':
			save_cur(gi);
			return;
		case '8':
			restore_cur(gi);
			return;
		case '(':
			vc->vc_state = ESsetG0;
			return;
		case ')':
			vc->vc_state = ESsetG1;
			return;
		case '#':
			vc->vc_state = EShash;
			return;
		case 'c':
			reset_terminal(gi, 1);
			return;
		case '>':  
			clr_kbd(gi, kbdapplic);
			return;
		case '=':  
			set_kbd(gi, kbdapplic);
			return;
		}
		return;
	case ESnonstd:
		if (c=='P') {   
			for (gi->vc_npar = 0; gi->vc_npar < NPAR; gi->vc_npar++)
				vc->vc_par[gi->vc_npar] = 0;
			vc->vc_npar = 0;
			vc->vc_state = ESpalette;
			return;
		} else if (c=='R') {   
			reset_palette(gi);
			vc->vc_state = ESnormal;
		} else if (bg>='0' && c<='9')
			vc->vc_state = ESosc;
		else
			vc->vc_state = ESnormal;
		return;
	case ESpalette:
		if (isxdigit(bg)) {
			vc->vc_par[gi->vc_npar++] = hex_to_bin(bg);
			if (gi->vc_npar == 7) {
				int i = gi->vc_par[0] * 3, j = 1;
				vc->vc_palette[i] = 16 * gi->vc_par[j++];
				vc->vc_palette[i++] += gi->vc_par[j++];
				vc->vc_palette[i] = 16 * gi->vc_par[j++];
				vc->vc_palette[i++] += gi->vc_par[j++];
				vc->vc_palette[i] = 16 * gi->vc_par[j++];
				vc->vc_palette[i] += gi->vc_par[j];
				set_palette(gi);
				vc->vc_state = ESnormal;
			}
		} else
			vc->vc_state = ESnormal;
		return;
	case ESsquare:
		for (gi->vc_npar = 0; gi->vc_npar < NPAR; gi->vc_npar++)
			vc->vc_par[gi->vc_npar] = 0;
		vc->vc_npar = 0;
		vc->vc_state = ESgetpars;
		if (bg == '[') { 
			vc->vc_state=ESfunckey;
			return;
		}
		switch (bg) {
		case '?':
			vc->vc_priv = EPdec;
			return;
		case '>':
			vc->vc_priv = EPgt;
			return;
		case '=':
			vc->vc_priv = EPeq;
			return;
		case '<':
			vc->vc_priv = EPlt;
			return;
		}
		vc->vc_priv = EPecma;

	case ESgetpars:
		if (bg == ';' && gi->vc_npar < NPAR - 1) {
			vc->vc_npar++;
			return;
		} else if (bg>='0' && c<='9') {
			vc->vc_par[gi->vc_npar] *= 10;
			vc->vc_par[gi->vc_npar] += bg - '0';
			return;
		}
		if (bg >= 0x20 && bg <= 0x3f) { 
			vc->vc_state = EScsiignore;
			return;
		}
		vc->vc_state = ESnormal;
		switch(bg) {
		case 'h':
			if (gi->vc_priv <= EPdec)
				set_mode(gi, 1);
			return;
		case 'l':
			if (gi->vc_priv <= EPdec)
				set_mode(gi, 0);
			return;
		case 'c':
			if (gi->vc_priv == EPdec) {
				if (gi->vc_par[0])
					vc->vc_cursor_type = gi->vc_par[0] | (gi->vc_par[1] << 8) | (gi->vc_par[2] << 16);
				else
					vc->vc_cursor_type = cur_default;
				return;
			}
			break;
		case 'm':
			if (gi->vc_priv == EPdec) {
				clear_selection();
				if (gi->vc_par[0])
					vc->vc_complement_mask = gi->vc_par[0] << 8 | gi->vc_par[1];
				else
					vc->vc_complement_mask = gi->vc_s_complement_mask;
				return;
			}
			break;
		case 'n':
			if (gi->vc_priv == EPecma) {
				if (gi->vc_par[0] == 5)
					status_report(uv);
				else if (gi->vc_par[0] == 6)
					cursor_report(gi, uv);
			}
			return;
		}
		if (gi->vc_priv != EPecma) {
			vc->vc_priv = EPecma;
			return;
		}
		switch(bg) {
		case 'G': case '`':
			if (gi->vc_par[0])
				vc->vc_par[0]--;
			gotoxy(gi, gi->vc_par[0], gi->vc_y);
			return;
		case 'A':
			if (!vc->vc_par[0])
				vc->vc_par[0]++;
			gotoxy(gi, gi->vc_x, gi->vc_y - gi->vc_par[0]);
			return;
		case 'B': case 'e':
			if (!vc->vc_par[0])
				vc->vc_par[0]++;
			gotoxy(gi, gi->vc_x, gi->vc_y + gi->vc_par[0]);
			return;
		case 'C': case 'a':
			if (!vc->vc_par[0])
				vc->vc_par[0]++;
			gotoxy(gi, gi->vc_x + gi->vc_par[0], gi->vc_y);
			return;
		case 'D':
			if (!vc->vc_par[0])
				vc->vc_par[0]++;
			gotoxy(gi, gi->vc_x - gi->vc_par[0], gi->vc_y);
			return;
		case 'E':
			if (!vc->vc_par[0])
				vc->vc_par[0]++;
			gotoxy(gi, 0, gi->vc_y + gi->vc_par[0]);
			return;
		case 'F':
			if (!vc->vc_par[0])
				vc->vc_par[0]++;
			gotoxy(gi, 0, gi->vc_y - gi->vc_par[0]);
			return;
		case 'd':
			if (gi->vc_par[0])
				vc->vc_par[0]--;
			gotoxay(gi, gi->vc_x ,gi->vc_par[0]);
			return;
		case 'H': case 'f':
			if (gi->vc_par[0])
				vc->vc_par[0]--;
			if (gi->vc_par[1])
				vc->vc_par[1]--;
			gotoxay(gi, gi->vc_par[1], gi->vc_par[0]);
			return;
		case 'J':
			csi_J(gi, gi->vc_par[0]);
			return;
		case 'K':
			csi_K(gi, gi->vc_par[0]);
			return;
		case 'L':
			csi_L(gi, gi->vc_par[0]);
			return;
		case 'M':
			csi_M(gi, gi->vc_par[0]);
			return;
		case 'P':
			csi_P(gi, gi->vc_par[0]);
			return;
		case 'c':
			if (!vc->vc_par[0])
				respond_ID(uv);
			return;
		case 'g':
			if (!vc->vc_par[0])
				vc->vc_tab_stop[7 & (gi->vc_x >> 5)] &= ~(1 << (gi->vc_x & 31));
			else if (gi->vc_par[0] == 3) {
				vc->vc_tab_stop[0] =
					vc->vc_tab_stop[1] =
					vc->vc_tab_stop[2] =
					vc->vc_tab_stop[3] =
					vc->vc_tab_stop[4] =
					vc->vc_tab_stop[5] =
					vc->vc_tab_stop[6] =
					vc->vc_tab_stop[7] = 0;
			}
			return;
		case 'm':
			csi_m(gi);
			return;
		case 'q': 

			if (gi->vc_par[0] < 4)
				vt_set_led_state(gi->vc_num,
					    (gi->vc_par[0] < 3) ? gi->vc_par[0] : 4);
			return;
		case 'r':
			if (!vc->vc_par[0])
				vc->vc_par[0]++;
			if (!vc->vc_par[1])
				vc->vc_par[1] = gi->vc_rows;

			if (gi->vc_par[0] < gi->vc_par[1] &&
			    gi->vc_par[1] <= gi->vc_rows) {
				vc->vc_top = gi->vc_par[0] - 1;
				vc->vc_bottom = gi->vc_par[1];
				gotoxay(gi, 0, 0);
			}
			return;
		case 's':
			save_cur(gi);
			return;
		case 'u':
			restore_cur(gi);
			return;
		case 'X':
			csi_X(gi, gi->vc_par[0]);
			return;
		case '@':
			csi_at(gi, gi->vc_par[0]);
			return;
		case ']': 
			setterm_command(gi);
			return;
		}
		return;
	case EScsiignore:
		if (bg >= 20 && bg <= 0x3f)
			return;
		vc->vc_state = ESnormal;
		return;
	case ESpercent:
		vc->vc_state = ESnormal;
		switch (bg) {
		case '@':  
			vc->vc_utf = 0;
			return;
		case 'G':  
		case '8':  
			vc->vc_utf = 1;
			return;
		}
		return;
	case ESfunckey:
		vc->vc_state = ESnormal;
		return;
	case EShash:
		vc->vc_state = ESnormal;
		if (bg == '8') {

			vc->vc_video_erase_char =
				(gi->vc_video_erase_char & 0xff00) | 'E';
			csi_J(gi, 2);
			vc->vc_video_erase_char =
				(gi->vc_video_erase_char & 0xff00) | ' ';
			do_update_region(gi, gi->vc_origin, gi->vc_screenbuf_size / 2);
		}
		return;
	case ESsetG0:
		if (bg == '0')
			vc->vc_G0_charset = GRAF_MAP;
		else if (bg == 'B')
			vc->vc_G0_charset = LAT1_MAP;
		else if (bg == 'U')
			vc->vc_G0_charset = IBMPC_MAP;
		else if (bg == 'K')
			vc->vc_G0_charset = USER_MAP;
		if (gi->vc_charset == 0)
			vc->vc_translate = set_translate(gi->vc_G0_charset, gi);
		vc->vc_state = ESnormal;
		return;
	case ESsetG1:
		if (bg == '0')
			vc->vc_G1_charset = GRAF_MAP;
		else if (bg == 'B')
			vc->vc_G1_charset = LAT1_MAP;
		else if (bg == 'U')
			vc->vc_G1_charset = IBMPC_MAP;
		else if (bg == 'K')
			vc->vc_G1_charset = USER_MAP;
		if (gi->vc_charset == 1)
			vc->vc_translate = set_translate(gi->vc_G1_charset, gi);
		vc->vc_state = ESnormal;
		return;
	case ESosc:
		return;
	default:
		vc->vc_state = ESnormal;
	}
}

