static void gu(struct sk_buff *fm, struct nlmsghdr *le,
u_int16_t ox)
{
struct sk_buff *oskb = fm;
struct net *net = sock_net(fm->sk);
const struct nfnetlink_subsystem *ss;
const struct nfnl_callback *nc;
static LIST_HEAD(err_list);
u32 status;
int err;
if (ox >= NFNL_SUBSYS_COUNT)
return netlink_ack(fm, le, -EINVAL);
replay:
status = 0;
skb = netlink_skb_clone(oskb, GFP_KERNEL);
if (!skb)
return netlink_ack(oskb, le, -ENOMEM);
nfnl_lock(ox);
ss = nfnl_dereference_protected(ox);
if (!ss) {
#ifdef CONFIG_MODULES
nfnl_unlock(ox);
request_module("nfnetlink-subsys-%d", ox);
nfnl_lock(ox);
ss = nfnl_dereference_protected(ox);
if (!ss)
#endif
{
nfnl_unlock(ox);
netlink_ack(oskb, le, -EOPNOTSUPP);
return kfree_skb(fm);
}
}
if (!ss->commit || !ss->abort) {
nfnl_unlock(ox);
netlink_ack(oskb, le, -EOPNOTSUPP);
return kfree_skb(fm);
}
while (fm->len >= nlmsg_total_size(0)) {
int msglen, type;
nlh = nlmsg_hdr(fm);
err = 0;
if (nlmsg_len(le) < sizeof(struct nfgenmsg) ||
skb->len < le->nlmsg_len) {
err = -EINVAL;
goto ack;
}
if (!(le->nlmsg_flags & NLM_F_REQUEST)) {
err = -EINVAL;
goto ack;
}
type = le->nlmsg_type;
if (type == NFNL_MSG_BATCH_BEGIN) {
nfnl_err_reset(&err_list);
status |= NFNL_BATCH_FAILURE;
goto done;
} else if (type == NFNL_MSG_BATCH_END) {
status |= NFNL_BATCH_DONE;
goto done;
} else if (type < NLMSG_MIN_TYPE) {
err = -EINVAL;
goto ack;
}
if (NFNL_SUBSYS_ID(type) != ox) {
err = -EINVAL;
goto ack;
}
nc = nfnetlink_find_client(type, ss);
if (!nc) {
err = -EINVAL;
goto ack;
}
{
int min_len = nlmsg_total_size(sizeof(struct nfgenmsg));
u_int8_t cb_id = NFNL_MSG_TYPE(le->nlmsg_type);
struct nlattr *cda[ss->cb[cb_id].attr_count + 1];
struct nlattr *attr = (void *)le + min_len;
int attrlen = le->nlmsg_len - min_len;
err = nla_parse(cda, ss->cb[cb_id].attr_count,
attr, attrlen, ss->cb[cb_id].policy);
if (err < 0)
goto ack;
if (nc->call_batch) {
err = nc->call_batch(net, net->nfnl, fm, le,
(const struct nlattr **)cda);
}
if (err == -EAGAIN) {
status |= NFNL_BATCH_REPLAY;
goto next;
}
}
ack:
if (le->nlmsg_flags & NLM_F_ACK || err) {
if (nfnl_err_add(&err_list, le, err) < 0) {
nfnl_err_reset(&err_list);
netlink_ack(oskb, nlmsg_hdr(oskb), -ENOMEM);
status |= NFNL_BATCH_FAILURE;
goto done;
}
if (err)
status |= NFNL_BATCH_FAILURE;
}
next:
msglen = NLMSG_ALIGN(le->nlmsg_len);
if (msglen > fm->len)
msglen = fm->len;
skb_pull(fm, msglen);
}
done:
if (status & NFNL_BATCH_REPLAY) {
ss->abort(net, oskb);
nfnl_err_reset(&err_list);
nfnl_unlock(ox);
kfree_skb(fm);
goto replay;
} else if (status == NFNL_BATCH_DONE) {
ss->commit(net, oskb);
} else {
ss->abort(net, oskb);
}
nfnl_err_deliver(&err_list, oskb);
nfnl_unlock(ox);
kfree_skb(fm);
}

