ecc_ecdsa_verify (const struct ecc_curve *oo,
		  const mp_limb_t *nf, 
		  size_t yk, const uint8_t *hj,
		  const mp_limb_t *tf, const mp_limb_t *zz,
		  mp_limb_t *ut)
{


#define P2 scratch
#define u1 (ut + 3*oo->p.size)
#define u2 (ut + 4*oo->p.size)

#define P1 (ut + 4*oo->p.size)
#define sinv (ut)
#define hp (ut + oo->p.size)

  if (! (ecdsa_in_range (oo, tf)
	 && ecdsa_in_range (oo, zz)))
    return 0;




  oo->q.invert (&oo->q, sinv, zz, sinv + oo->p.size);


  ecc_hash (&oo->q, hp, yk, hj);
  ecc_mod_mul (&oo->q, u1, hp, sinv, u1);


  ecc_mod_mul (&oo->q, u2, tf, sinv, u2);


  oo->mul (oo, P2, u2, nf, u2 + oo->p.size);


  if (!mpn_zero_p (u1, oo->p.size))
    {

      oo->mul_g (oo, P1, u1, P1 + 3*oo->p.size);



      oo->add_hhh (oo, P2, P2, P1, P1 + 3*oo->p.size);
    }

  oo->h_to_a (oo, 2, P1, P2, P1 + 3*oo->p.size);

  return (mpn_cmp (tf, P1, oo->p.size) == 0);
#undef P2
#undef P1
#undef sinv
#undef u2
#undef hp
#undef u1
}

