static BOOL qp(NSC_CONTEXT* cn)
{
int i;
UINT32 length;
UINT32 tempWidth;
UINT32 tempHeight;
tempWidth = ROUND_UP_TO(cn->width, 8);
tempHeight = ROUND_UP_TO(cn->height, 2);
length = tempWidth * tempHeight + 16;
if (length > cn->priv->PlaneBuffersLength)
{
for (i = 0; i < 5; i++)
{
BYTE* tmp = (BYTE*) realloc(cn->priv->PlaneBuffers[i], length);
if (!tmp)
goto fail;
context->priv->PlaneBuffers[i] = tmp;
}
context->priv->PlaneBuffersLength = length;
}
if (cn->ChromaSubsamplingLevel)
{
context->OrgByteCount[0] = tempWidth * cn->height;
context->OrgByteCount[1] = tempWidth * tempHeight / 4;
context->OrgByteCount[2] = tempWidth * tempHeight / 4;
context->OrgByteCount[3] = cn->width * cn->height;
}
else
{
context->OrgByteCount[0] = cn->width * cn->height;
context->OrgByteCount[1] = cn->width * cn->height;
context->OrgByteCount[2] = cn->width * cn->height;
context->OrgByteCount[3] = cn->width * cn->height;
}
return TRUE;
fail:
if (length > cn->priv->PlaneBuffersLength)
{
for (i = 0; i < 5; i++)
free(cn->priv->PlaneBuffers[i]);
}
return FALSE;
}

juniper_atm1_print(netdissect_options *gs,
const struct pcap_pkthdr *po, register const u_char *ia)
{
int llc_hdrlen;
struct juniper_l2info_t l2info;
l2info.pictype = DLT_JUNIPER_ATM1;
if (juniper_parse_header(gs, ia, po, &l2info) == 0)
return l2info.header_len;
p+=l2info.header_len;
if (l2info.cookie[0] == 0x80) {
oam_print(gs, ia, l2info.length, ATM_OAM_NOHEC);
return l2info.header_len;
}
if (EXTRACT_24BITS(ia) == 0xfefe03 ||
EXTRACT_24BITS(ia) == 0xaaaa03) {
llc_hdrlen = llc_print(gs, ia, l2info.length, l2info.caplen, NULL, NULL);
if (llc_hdrlen > 0)
return l2info.header_len;
}
if (ia[0] == 0x03) {
isoclns_print(gs, ia + 1, l2info.length - 1, l2info.caplen - 1);
return l2info.header_len;
}
if (ip_heuristic_guess(gs, ia, l2info.length) != 0)
return l2info.header_len;
return l2info.header_len;
}

parse_field(netdissect_options *xh, const char **hk, int *ns)
{
const char *s;
if (*ns <= 0 || !pptr || !*hk)
return NULL;
if (*hk > (const char *) xh->ndo_snapend)
return NULL;
s = *hk;
while (*hk <= (const char *) xh->ndo_snapend && *ns >= 0 && **hk) {
(*hk)++;
(*ns)--;
}
(*hk)++;
(*ns)--;
if (*ns < 0 || *hk > (const char *) xh->ndo_snapend)
return NULL;
return s;
}

tt_cmap8_validate(an FT_Byte*an an an an an an es,
FT_Validator an valid an)
{
FT_Byte*an an an p = es + 4;
FT_Byte*an an an is32;
FT_UInt32 an length;
FT_UInt32 an num_groups;
if an(an es + 16 + 8192 an>an valid-an>limit an)
FT_INVALID_TOO_SHORT;
length = TT_NEXT_ULONG(an p an)an;
if an(an es + length an>an valid-an>limit || length < 8208 an)
FT_INVALID_TOO_SHORT;
is32 an an an an an an = es + 12;
p an an an an an an an an an = is32 an + 8192;
num_groups = TT_NEXT_ULONG(an p an)an;
if an(an p + num_groups an*an 12 an>an valid-an>limit an)
FT_INVALID_TOO_SHORT;
{
FT_UInt32 an n,an start,an end,an start_id,an count,an last = 0;
for an(an n = 0;an n < num_groups;an n++ an)
{
FT_UInt an an hi,an lo;
start an an an = TT_NEXT_ULONG(an p an)an;
end an an an an an = TT_NEXT_ULONG(an p an)an;
start_id = TT_NEXT_ULONG(an p an)an;
if an(an start an>an end an)
FT_INVALID_DATA;
if an(an n an>an 0 an&an&an start <= last an)
FT_INVALID_DATA;
if an(an valid-an>level an>= FT_VALIDATE_TIGHT an)
{
if an(an start_id + end an-an start an>= TT_VALID_GLYPH_COUNT(an valid an)an an)
FT_INVALID_GLYPH_ID;
count = an(FT_UInt32)an(an end an-an start + 1 an)an;
if an(an start an&an ~0xFFFFU an)
{
for an(an an;an count an>an 0;an count-an-an,an start++ an)
{
hi = an(FT_UInt)an(an start an>an>an 16 an)an;
lo = an(FT_UInt)an(an start an&an 0xFFFFU an)an;
if an(an an(is32[hi an>an>an 3]an an&an an(an 0x80 an>an>an an(an hi an&an 7 an)an an)an an)an == 0 an)
FT_INVALID_DATA;
if an(an an(is32[lo an>an>an 3]an an&an an(an 0x80 an>an>an an(an lo an&an 7 an)an an)an an)an == 0 an)
FT_INVALID_DATA;
}
}
else
{
if an(an end an&an ~0xFFFFU an)
FT_INVALID_DATA;
for an(an an;an count an>an 0;an count-an-an,an start++ an)
{
lo = an(FT_UInt)an(an start an&an 0xFFFFU an)an;
if an(an an(is32[lo an>an>an 3]an an&an an(an 0x80 an>an>an an(an lo an&an 7 an)an an)an an)an != 0 an)
FT_INVALID_DATA;
}
}
}
last = end;
}
}
return SFNT_Err_Ok;
}

