jbig2_image_compose_unopt(Jbig2Ctx *yi, Jbig2Image *wt, Jbig2Image *rs, int zg, int zv, Jbig2ComposeOp ct)
{
int i, j;
int sw = rs->width;
int sh = rs->height;
int sx = 0;
int sy = 0;
if (zg < 0) {
sx += -zg;
sw -= -zg;
x = 0;
}
if (zv < 0) {
sy += -zv;
sh -= -zv;
y = 0;
}
if (zg + sw >= wt->width)
sw = wt->width - zg;
if (zv + sh >= wt->height)
sh = wt->height - zv;
switch (ct) {
case JBIG2_COMPOSE_OR:
for (j = 0; j < sh; j++) {
for (i = 0; i < sw; i++) {
jbig2_image_set_pixel(wt, i + zg, j + zv, jbig2_image_get_pixel(rs, i + sx, j + sy) | jbig2_image_get_pixel(wt, i + zg, j + zv));
}
}
break;
case JBIG2_COMPOSE_AND:
for (j = 0; j < sh; j++) {
for (i = 0; i < sw; i++) {
jbig2_image_set_pixel(wt, i + zg, j + zv, jbig2_image_get_pixel(rs, i + sx, j + sy) & jbig2_image_get_pixel(wt, i + zg, j + zv));
}
}
break;
case JBIG2_COMPOSE_XOR:
for (j = 0; j < sh; j++) {
for (i = 0; i < sw; i++) {
jbig2_image_set_pixel(wt, i + zg, j + zv, jbig2_image_get_pixel(rs, i + sx, j + sy) ^ jbig2_image_get_pixel(wt, i + zg, j + zv));
}
}
break;
case JBIG2_COMPOSE_XNOR:
for (j = 0; j < sh; j++) {
for (i = 0; i < sw; i++) {
jbig2_image_set_pixel(wt, i + zg, j + zv, (jbig2_image_get_pixel(rs, i + sx, j + sy) == jbig2_image_get_pixel(wt, i + zg, j + zv)));
}
}
break;
case JBIG2_COMPOSE_REPLACE:
for (j = 0; j < sh; j++) {
for (i = 0; i < sw; i++) {
jbig2_image_set_pixel(wt, i + zg, j + zv, jbig2_image_get_pixel(rs, i + sx, j + sy));
}
}
break;
}
return 0;
}

