horAcc16(TIFF* ml, uint8* ot, tmsize_t bl)
{
tmsize_t stride = PredictorState(ml)->stride;
uint16* wp = (uint16*) ot;
tmsize_t wc = bl / 2;
assert((cc%(2*stride))==0);
if (wc > stride) {
wc -= stride;
do {
REPEAT4(stride, wp[stride] = (uint16)(((unsigned int)wp[stride] + (unsigned int)wp[0]) & 0xffff); wp++)
wc -= stride;
} while (wc > 0);
}
}

