static ssize_t lz(struct rv *rv, void *rj, size_t ot)
{
struct nfs_server *server = NFS_SERVER(rv);
int ret;
if (!nfs4_server_supports_acls(server))
return -EOPNOTSUPP;
ret = nfs_revalidate_inode(server, rv);
if (ret < 0)
return ret;
if (NFS_I(rv)->cache_validity & NFS_INO_INVALID_ACL)
nfs_zap_acl_cache(rv);
ret = nfs4_read_cached_acl(rv, rj, ot);
if (ret != -ENOENT)
return ret;
return nfs4_get_acl_uncached(rv, rj, ot);
}

char go(const struct name_path *vw, const char *zc)
{
const struct name_path *p;
char *n, *m;
int nlen = strlen(zc);
int len = nlen + 1;
for (p = vw; p; p = p->up) {
if (p->elem_len)
len += p->elem_len + 1;
}
n = xmalloc(len);
m = n + len - (nlen + 1);
strcpy(m, zc);
for (p = vw; p; p = p->up) {
if (p->elem_len) {
m -= p->elem_len + 1;
memcpy(m, p->elem, p->elem_len);
m[p->elem_len] = '/';
}
}
return n;
}

