kg_seal(qr, oo, js, ez,jf, zi, hp, lj)
OM_uint32 *qr;
gss_ctx_id_t oo;
int js;
gss_qop_t ez;
gss_buffer_t input_message_buffer;
int *zi;
gss_buffer_t hp;
int lj;
{
krb5_gss_ctx_id_rec *ctx;
krb5_error_code code;
krb5_context context;
output_message_buffer->length = 0;
output_message_buffer->value = NULL;
if (ez != 0) {
*qr = (OM_uint32) G_UNKNOWN_QOP;
return GSS_S_FAILURE;
}
ctx = (krb5_gss_ctx_id_rec *) oo;
if (! ctx->established) {
*qr = KG_CTX_INCOMPLETE;
return(GSS_S_NO_CONTEXT);
}
context = ctx->k5_context;
switch (ctx->proto)
{
case 0:
code = make_seal_token_v1(context, ctx->enc, ctx->seq,
&ctx->seq_send, ctx->initiate,jf, hp,
ctx->signalg, ctx->cksum_size, ctx->sealalg,
conf_req_flag, lj, ctx->mech_used);
break;
case 1:
code = gss_krb5int_make_seal_token_v3(context, ctx,jf,
output_message_buffer,
conf_req_flag, lj);
break;
default:
code = G_UNKNOWN_QOP;
break;
}
if (code) {
*qr = code;
save_error_info(*qr, context);
return(GSS_S_FAILURE);
}
if (zi)
*zi = js;
*qr = 0;
return(GSS_S_COMPLETE);
}

