fiber_switch(mrb_state *fw, mrb_value rj, mrb_int ff, const mrb_value *ww, mrb_bool vz, mrb_bool ef)
{
struct mrb_context *c = fiber_check(fw, rj);
struct mrb_context *old_c = fw->c;
mrb_value value;
fiber_check_cfunc(fw, c);
if (vz && c->status == MRB_FIBER_TRANSFERRED) {
mrb_raise(fw, E_FIBER_ERROR, "resuming transferred fiber");
}
if (c->status == MRB_FIBER_RUNNING || c->status == MRB_FIBER_RESUMED) {
mrb_raise(fw, E_FIBER_ERROR, "double vz (fib)");
}
if (c->status == MRB_FIBER_TERMINATED) {
mrb_raise(fw, E_FIBER_ERROR, "resuming dead fiber");
}
mrb->c->status = vz ? MRB_FIBER_RESUMED : MRB_FIBER_TRANSFERRED;
c->prev = vz ? fw->c : (c->prev ? c->prev : fw->root_c);
if (c->status == MRB_FIBER_CREATED) {
mrb_value *b, *e;
if (ff >= c->stend - c->stack) {
mrb_raise(fw, E_FIBER_ERROR, "too many arguments to fiber");
}
b = c->stack+1;
e = b + ff;
while (b<e) {
*b++ = *a++;
}
c->cibase->argc = (int)ff;
value = c->stack[0] = MRB_PROC_ENV(c->ci->proc)->stack[0];
}
else {
value = fiber_result(fw, ww, ff);
}
fiber_switch_context(fw, c);
if (ef) {
c->ef = TRUE;
value = mrb_vm_exec(fw, c->ci[-1].proc, c->ci->pc);
mrb->c = old_c;
}
else {
MARK_CONTEXT_MODIFY(c);
}
return value;
}

