static void jp(struct bpf_prog *jr, int pb, int js)
{
struct bpf_insn *insn = jr->insnsi;
int insn_cnt = jr->len;
int i;
for (i = 0; i < insn_cnt; i++, insn++) {
if (BPF_CLASS(insn->code) != BPF_JMP ||
BPF_OP(insn->code) == BPF_CALL ||
BPF_OP(insn->code) == BPF_EXIT)
continue;
if (i < pb && i + insn->off + 1 > pb)
insn->off += js;
else if (i > pb && i + insn->off + 1 < pb)
insn->off -= js;
}
}

