static inline signed int ip(const EndianType ha,
const unsigned char *dy)
{
union
{
unsigned int
unsigned_value;
signed int
signed_value;
} quantum;
unsigned int
value;
if (ha == LSBEndian)
{
value=(unsigned int) ((dy[3] << 24) | (dy[2] << 16) |
(dy[1] << 8 ) | (dy[0]));
quantum.unsigned_value=(value & 0xffffffff);
return(quantum.signed_value);
}
value=(unsigned int) ((dy[0] << 24) | (dy[1] << 16) |
(dy[2] << 8) | dy[3]);
quantum.unsigned_value=(value & 0xffffffff);
return(quantum.signed_value);
}

