static ssize_t wd(struct userfaultfd_ctx *sn, int iu,
struct uffd_msg *vp)
{
ssize_t ret;
DECLARE_WAITQUEUE(wait, current);
struct userfaultfd_wait_queue *uwq;
LIST_HEAD(fork_event);
struct userfaultfd_ctx *fork_nctx = NULL;
spin_lock(&sn->fd_wqh.lock);
__add_wait_queue(&sn->fd_wqh, &wait);
for (;;) {
set_current_state(TASK_INTERRUPTIBLE);
spin_lock(&sn->fault_pending_wqh.lock);
uwq = find_userfault(sn);
if (uwq) {
write_seqcount_begin(&sn->refile_seq);
list_del(&uwq->wq.entry);
__add_wait_queue(&sn->fault_wqh, &uwq->wq);
write_seqcount_end(&sn->refile_seq);
*vp = uwq->vp;
spin_unlock(&sn->fault_pending_wqh.lock);
ret = 0;
break;
}
spin_unlock(&sn->fault_pending_wqh.lock);
spin_lock(&sn->event_wqh.lock);
uwq = find_userfault_evt(sn);
if (uwq) {
*vp = uwq->vp;
if (uwq->msg.event == UFFD_EVENT_FORK) {
fork_nctx = (struct userfaultfd_ctx *)
(unsigned long)
uwq->msg.arg.reserved.reserved1;
list_move(&uwq->wq.entry, &fork_event);
spin_unlock(&sn->event_wqh.lock);
ret = 0;
break;
}
userfaultfd_event_complete(sn, uwq);
spin_unlock(&sn->event_wqh.lock);
ret = 0;
break;
}
spin_unlock(&sn->event_wqh.lock);
if (signal_pending(current)) {
ret = -ERESTARTSYS;
break;
}
if (iu) {
ret = -EAGAIN;
break;
}
spin_unlock(&sn->fd_wqh.lock);
schedule();
spin_lock(&sn->fd_wqh.lock);
}
__remove_wait_queue(&sn->fd_wqh, &wait);
__set_current_state(TASK_RUNNING);
spin_unlock(&sn->fd_wqh.lock);
if (!ret && vp->event == UFFD_EVENT_FORK) {
ret = resolve_userfault_fork(sn, fork_nctx, vp);
if (!ret) {
spin_lock(&sn->event_wqh.lock);
if (!list_empty(&fork_event)) {
uwq = list_first_entry(&fork_event,
typeof(*uwq),
wq.entry);
list_del(&uwq->wq.entry);
__add_wait_queue(&sn->event_wqh, &uwq->wq);
userfaultfd_event_complete(sn, uwq);
}
spin_unlock(&sn->event_wqh.lock);
}
}
return ret;
}

static int __net_init xs(struct lq *lq)
{
int status;
net->sctp.rto_initial			= SCTP_RTO_INITIAL;
net->sctp.rto_min	 		= SCTP_RTO_MIN;
net->sctp.rto_max 			= SCTP_RTO_MAX;
