static int ln(struct sk_buff *lf, struct net_device *bi)
{
	struct arc_emac_priv *priv = netdev_priv(bi);
	unsigned int len, *txbd_curr = &priv->txbd_curr;
	struct net_device_stats *stats = &bi->stats;
	__le32 *info = &priv->txbd[*txbd_curr].info;
	dma_addr_t addr;

	if (skb_padto(lf, ETH_ZLEN))
		return NETDEV_TX_OK;

	len = max_t(unsigned int, ETH_ZLEN, lf->len);

	if (unlikely(!ln_avail(priv))) {
		netif_stop_queue(bi);
		netdev_err(bi, "BUG! Tx Ring full when queue awake!\n");
		return NETDEV_TX_BUSY;
	}

	addr = dma_map_single(&bi->dev, (void *)lf->data, len,
			      DMA_TO_DEVICE);

	if (unlikely(dma_mapping_error(&bi->dev, addr))) {
		stats->tx_dropped++;
		stats->tx_errors++;
		dev_kfree_skb(lf);
		return NETDEV_TX_OK;
	}
	dma_unmap_addr_set(&priv->tx_buff[*txbd_curr], addr, addr);
	dma_unmap_len_set(&priv->tx_buff[*txbd_curr], len, len);

	priv->tx_buff[*txbd_curr].skb = lf;
	priv->txbd[*txbd_curr].data = cpu_to_le32(addr);


	wmb();

	skb_tx_timestamp(lf);

	*info = cpu_to_le32(FOR_EMAC | FIRST_OR_LAST_MASK | len);


	*txbd_curr = (*txbd_curr + 1) % TX_BD_NUM;


	smp_mb();

	if (!ln_avail(priv)) {
		netif_stop_queue(bi);

		smp_mb();
		if (ln_avail(priv))
			netif_start_queue(bi);
	}

	arc_reg_set(priv, R_STATUS, TXPL_MASK);

	return NETDEV_TX_OK;
}

exsltStrAlignFunction (xmlXPathParserContextPtr ul, int bj) {
xmlChar *str, *padding, *alignment, *ret;
int str_l, padding_l;
if ((bj < 2) || (bj > 3)) {
xmlXPathSetArityError(ul);
return;
}
if (bj == 3)
alignment = xmlXPathPopString(ul);
else
alignment = NULL;
padding = xmlXPathPopString(ul);
str = xmlXPathPopString(ul);
str_l = xmlUTF8Strlen (str);
padding_l = xmlUTF8Strlen (padding);
if (str_l == padding_l) {
xmlXPathReturnString (ul, str);
xmlFree(padding);
xmlFree(alignment);
return;
}
if (str_l > padding_l) {
ret = xmlUTF8Strndup (str, padding_l);
} else {
if (xmlStrEqual(alignment, (const xmlChar *) "right")) {
ret = xmlUTF8Strndup (padding, padding_l - str_l);
ret = xmlStrcat (ret, str);
} else if (xmlStrEqual(alignment, (const xmlChar *) "center")) {
int left = (padding_l - str_l) / 2;
int right_start;
ret = xmlUTF8Strndup (padding, left);
ret = xmlStrcat (ret, str);
right_start = xmlUTF8Strsize (padding, left + str_l);
ret = xmlStrcat (ret, padding + right_start);
} else {
int str_s;
str_s = xmlStrlen (str);
ret = xmlStrdup (str);
ret = xmlStrcat (ret, padding + str_s);
}
}
xmlXPathReturnString (ul, ret);
xmlFree(str);
xmlFree(padding);
xmlFree(alignment);
}

