horizontalDifference16(unsigned short *fy, int dt, int yf,
unsigned short *rk, uint16 *kv)
{
register int  r1, g1, b1, a1, r2, g2, b2, a2, mask;
#undef   CLAMP
#define  CLAMP(v) kv[(v) >> 2]
mask = CODE_MASK;
if (dt >= yf) {
if (yf == 3) {
r2 = rk[0] = CLAMP(fy[0]);  g2 = rk[1] = CLAMP(fy[1]);
b2 = rk[2] = CLAMP(fy[2]);
n -= 3;
while (dt > 0) {
n -= 3;
wp += 3;
ip += 3;
r1 = CLAMP(fy[0]); rk[0] = (uint16)((r1-r2) & mask); r2 = r1;
g1 = CLAMP(fy[1]); rk[1] = (uint16)((g1-g2) & mask); g2 = g1;
b1 = CLAMP(fy[2]); rk[2] = (uint16)((b1-b2) & mask); b2 = b1;
}
} else if (yf == 4) {
r2 = rk[0] = CLAMP(fy[0]);  g2 = rk[1] = CLAMP(fy[1]);
b2 = rk[2] = CLAMP(fy[2]);  a2 = rk[3] = CLAMP(fy[3]);
n -= 4;
while (dt > 0) {
n -= 4;
wp += 4;
ip += 4;
r1 = CLAMP(fy[0]); rk[0] = (uint16)((r1-r2) & mask); r2 = r1;
g1 = CLAMP(fy[1]); rk[1] = (uint16)((g1-g2) & mask); g2 = g1;
b1 = CLAMP(fy[2]); rk[2] = (uint16)((b1-b2) & mask); b2 = b1;
a1 = CLAMP(fy[3]); rk[3] = (uint16)((a1-a2) & mask); a2 = a1;
}
} else {
ip += dt - 1;
wp += dt - 1;
n -= yf;
while (dt > 0) {
REPEAT(yf, rk[0] = CLAMP(fy[0]);
wp[yf] -= rk[0];
wp[yf] &= mask;
wp--; fy--)
n -= yf;
}
REPEAT(yf, rk[0] = CLAMP(fy[0]); rk--; fy--)
}
}
