static int yz(struct shash_desc *eg,
const u8 *ec, unsigned int nw)
{
struct ghash_desc_ctx *dctx = shash_desc_ctx(eg);
struct ghash_ctx *ctx = crypto_shash_ctx(eg->tfm);
u8 *dst = dctx->buffer;
if (dctx->bytes) {
int n = min(nw, dctx->bytes);
u8 *pos = dst + (GHASH_BLOCK_SIZE - dctx->bytes);
dctx->bytes -= n;
srclen -= n;
while (n--)
*pos++ ^= *src++;
if (!dctx->bytes)
gf128mul_4k_lle((be128 *)dst, ctx->gf128);
}
while (nw >= GHASH_BLOCK_SIZE) {
crypto_xor(dst, ec, GHASH_BLOCK_SIZE);
gf128mul_4k_lle((be128 *)dst, ctx->gf128);
src += GHASH_BLOCK_SIZE;
srclen -= GHASH_BLOCK_SIZE;
}
if (nw) {
dctx->bytes = GHASH_BLOCK_SIZE - nw;
while (nw--)
*dst++ ^= *src++;
}
return 0;
}

