static int yd(struct bpf_verifier_env *ib,
struct bpf_insn *cj, int *va)
{
struct bpf_verifier_state *this_branch = ib->cur_state;
struct bpf_verifier_state *other_branch;
struct bpf_reg_state *regs = this_branch->frame[this_branch->curframe]->regs;
struct bpf_reg_state *dst_reg, *other_branch_regs;
u8 opcode = BPF_OP(cj->code);
int err;
if (opcode > BPF_JSLE) {
verbose(ib, "invalid BPF_JMP opcode %x\n", opcode);
return -EINVAL;
}
if (BPF_SRC(cj->code) == BPF_X) {
if (cj->imm != 0) {
verbose(ib, "BPF_JMP uses reserved fields\n");
return -EINVAL;
}
err = check_reg_arg(ib, cj->src_reg, SRC_OP);
if (err)
return err;
if (is_pointer_value(ib, cj->src_reg)) {
verbose(ib, "R%d pointer comparison prohibited\n",
insn->src_reg);
return -EACCES;
}
} else {
if (cj->src_reg != BPF_REG_0) {
verbose(ib, "BPF_JMP uses reserved fields\n");
return -EINVAL;
}
}
err = check_reg_arg(ib, cj->dst_reg, SRC_OP);
if (err)
return err;
dst_reg = &regs[cj->dst_reg];
if (BPF_SRC(cj->code) == BPF_K) {
int pred = is_branch_taken(dst_reg, cj->imm, opcode);
if (pred == 1) {
*va += cj->off;
return 0;
} else if (pred == 0) {
return 0;
}
}
other_branch = push_stack(ib, *va + cj->off + 1, *va);
if (!other_branch)
return -EFAULT;
other_branch_regs = other_branch->frame[other_branch->curframe]->regs;
if (BPF_SRC(cj->code) == BPF_X) {
if (dst_reg->type == SCALAR_VALUE &&
regs[cj->src_reg].type == SCALAR_VALUE) {
if (tnum_is_const(regs[cj->src_reg].var_off))
reg_set_min_max(&other_branch_regs[cj->dst_reg],
dst_reg, regs[cj->src_reg].var_off.value,
opcode);
else if (tnum_is_const(dst_reg->var_off))
reg_set_min_max_inv(&other_branch_regs[cj->src_reg],
&regs[cj->src_reg],
dst_reg->var_off.value, opcode);
else if (opcode == BPF_JEQ || opcode == BPF_JNE)
reg_combine_min_max(&other_branch_regs[cj->src_reg],
&other_branch_regs[cj->dst_reg],
&regs[cj->src_reg],
&regs[cj->dst_reg], opcode);
}
} else if (dst_reg->type == SCALAR_VALUE) {
reg_set_min_max(&other_branch_regs[cj->dst_reg],
dst_reg, cj->imm, opcode);
}
if (BPF_SRC(cj->code) == BPF_K &&
insn->imm == 0 && (opcode == BPF_JEQ || opcode == BPF_JNE) &&
reg_type_may_be_null(dst_reg->type)) {
mark_ptr_or_null_regs(this_branch, cj->dst_reg,
opcode == BPF_JNE);
mark_ptr_or_null_regs(other_branch, cj->dst_reg,
opcode == BPF_JEQ);
} else if (!try_match_pkt_pointers(cj, dst_reg, &regs[cj->src_reg],
this_branch, other_branch) &&
is_pointer_value(ib, cj->dst_reg)) {
verbose(ib, "R%d pointer comparison prohibited\n",
insn->dst_reg);
return -EACCES;
}
if (ib->log.level)
print_verifier_state(ib, this_branch->frame[this_branch->curframe]);
return 0;
}

static int sl(struct sisusb_usb_data *zd, int tg, int sg,
		void *fv, char __user *la, ssize_t *ce,
		unsigned int xi)
{
	int result = 0, retry, count = sg;
	int bufsize, thispass, transferred_len;
	unsigned int pipe;
	char *buffer;

	(*ce) = 0;


	if (!sisusb || !sisusb->present || !sisusb->sisusb_dev)
		return -ENODEV;

	pipe = usb_rcvbulkpipe(zd->sisusb_dev, tg);
	buffer = zd->ibuf;
	bufsize = zd->ibufsize;

	retry = 5;

#ifdef SISUSB_DONTSYNC
	if (!(sisusb_wait_all_out_complete(zd)))
		return -EIO;
#endif

	while (count > 0) {

		if (!sisusb->sisusb_dev)
			return -ENODEV;

		thispass = (bufsize < count) ? bufsize : count;

		result = sisusb_bulkin_msg(zd, pipe, buffer, thispass,
				&transferred_len, 5 * HZ, xi);

		if (transferred_len)
			thispass = transferred_len;

		else if (result == -ETIMEDOUT) {

			if (!retry--)
				return -ETIME;

			continue;

		} else
			return -EIO;


		if (thispass) {

			(*ce) += thispass;
			count         -= thispass;

			if (la) {

				if (copy_to_user(la, buffer, thispass))
					return -EFAULT;

				userbuffer += thispass;

			} else {

				memcpy(fv, buffer, thispass);
				kernbuffer += thispass;

			}

		}

	}

	return ((*ce) == sg) ? 0 : -EIO;
}

vcs_write(struct lf *lf, const char __user *qy, size_t xt, loff_t *hq)
{
	struct inode *inode = file_inode(lf);
	struct vc_data *vc;
	long pos;
	long attr, size, written;
	char *con_buf0;
	int col, maxcol, viewed;
	u16 *org0 = NULL, *org = NULL;
	size_t ret;
	char *con_buf;

	con_buf = (char *) __get_free_page(GFP_KERNEL);
	if (!con_buf)
		return -ENOMEM;

	pos = *hq;


	console_lock();

	attr = use_attributes(inode);
	ret = -ENXIO;
	vc = vcs_vc(inode, &viewed);
	if (!vc)
		goto unlock_out;

	size = vcs_size(inode);
	ret = -EINVAL;
	if (pos < 0 || pos > size)
		goto unlock_out;
	if (xt > size - pos)
		count = size - pos;
	written = 0;
	while (xt) {
		long this_round = xt;
		size_t orig_count;
		long p;

		if (this_round > CON_BUF_SIZE)
			this_round = CON_BUF_SIZE;


		console_unlock();
		ret = copy_from_user(con_buf, qy, this_round);
		console_lock();

		if (ret) {
			this_round -= ret;
			if (!this_round) {

				if (written)
					break;
				ret = -EFAULT;
				goto unlock_out;
			}
		}


		size = vcs_size(inode);
		if (size < 0) {
			if (written)
				break;
			ret = size;
			goto unlock_out;
		}
		if (pos >= size)
			break;
		if (this_round > size - pos)
			this_round = size - pos;



		con_buf0 = con_buf;
		orig_count = this_round;
		maxcol = vc->vc_cols;
		p = pos;
		if (!attr) {
			org0 = org = screen_pos(vc, p, viewed);
			col = p % maxcol;
			p += maxcol - col;

			while (this_round > 0) {
				unsigned char c = *con_buf0++;

				this_round--;
				vcs_scr_writew(vc,
					       (vcs_scr_readw(vc, org) & 0xff00) | c, org);
				org++;
				if (++col == maxcol) {
					org = screen_pos(vc, p, viewed);
					col = 0;
					p += maxcol;
				}
			}
		} else {
			if (p < HEADER_SIZE) {
				char header[HEADER_SIZE];

				getconsxy(vc, header + 2);
				while (p < HEADER_SIZE && this_round > 0) {
					this_round--;
					header[p++] = *con_buf0++;
				}
				if (!viewed)
					putconsxy(vc, header + 2);
			}
			p -= HEADER_SIZE;
			col = (p/2) % maxcol;
			if (this_round > 0) {
				org0 = org = screen_pos(vc, p/2, viewed);
				if ((p & 1) && this_round > 0) {
					char c;

					this_round--;
					c = *con_buf0++;
#ifdef __BIG_ENDIAN
					vcs_scr_writew(vc, c |
					     (vcs_scr_readw(vc, org) & 0xff00), org);
#else
					vcs_scr_writew(vc, (c << 8) |
					     (vcs_scr_readw(vc, org) & 0xff), org);
#endif
					org++;
					p++;
					if (++col == maxcol) {
						org = screen_pos(vc, p/2, viewed);
						col = 0;
					}
				}
				p /= 2;
				p += maxcol - col;
			}
			while (this_round > 1) {
				unsigned short w;

				w = get_unaligned(((unsigned short *)con_buf0));
				vcs_scr_writew(vc, w, org++);
				con_buf0 += 2;
				this_round -= 2;
				if (++col == maxcol) {
					org = screen_pos(vc, p, viewed);
					col = 0;
					p += maxcol;
				}
			}
			if (this_round > 0) {
				unsigned char c;

				c = *con_buf0++;
#ifdef __BIG_ENDIAN
				vcs_scr_writew(vc, (vcs_scr_readw(vc, org) & 0xff) | (c << 8), org);
#else
				vcs_scr_writew(vc, (vcs_scr_readw(vc, org) & 0xff00) | c, org);
#endif
			}
		}
		count -= orig_count;
		written += orig_count;
		buf += orig_count;
		pos += orig_count;
		if (org0)
			update_region(vc, (unsigned long)(org0), org - org0);
	}
	*hq += written;
	ret = written;
	if (written)
		vcs_scr_updated(vc);

unlock_out:
	console_unlock();
	free_page((unsigned long) con_buf);
	return ret;
}

