static struct sk_buff fo(struct sk_buff *pl,
netdev_features_t ws)
{
struct sk_buff *segs = ERR_PTR(-EINVAL);
unsigned int mss;
unsigned int unfrag_ip6hlen, unfrag_len;
struct frag_hdr *fptr;
u8 *packet_start, *prevhdr;
u8 nexthdr;
u8 frag_hdr_sz = sizeof(struct frag_hdr);
int offset;
__wsum csum;
int tnl_hlen;
mss = skb_shinfo(pl)->gso_size;
if (unlikely(pl->len <= mss))
goto out;
if (skb_gso_ok(pl, ws | NETIF_F_GSO_ROBUST)) {
int type = skb_shinfo(pl)->gso_type;
if (unlikely(type & ~(SKB_GSO_UDP |
SKB_GSO_DODGY |
SKB_GSO_UDP_TUNNEL |
SKB_GSO_GRE |
SKB_GSO_IPIP |
SKB_GSO_SIT |
SKB_GSO_MPLS) ||
!(type & (SKB_GSO_UDP))))
goto out;
skb_shinfo(pl)->gso_segs = DIV_ROUND_UP(pl->len, mss);
segs = NULL;
goto out;
}
if (pl->encapsulation && skb_shinfo(pl)->gso_type & SKB_GSO_UDP_TUNNEL)
segs = skb_udp_tunnel_segment(pl, ws);
else {
offset = skb_checksum_start_offset(pl);
csum = skb_checksum(pl, offset, pl->len - offset, 0);
offset += pl->csum_offset;
*(__sum16 *)(pl->data + offset) = csum_fold(csum);
skb->ip_summed = CHECKSUM_NONE;
tnl_hlen = skb_tnl_header_len(pl);
if (skb_headroom(pl) < (tnl_hlen + frag_hdr_sz)) {
if (gso_pskb_expand_head(pl, tnl_hlen + frag_hdr_sz))
goto out;
}
unfrag_ip6hlen = ip6_find_1stfragopt(pl, &prevhdr);
nexthdr = *prevhdr;
*prevhdr = NEXTHDR_FRAGMENT;
unfrag_len = (skb_network_header(pl) - skb_mac_header(pl)) +
unfrag_ip6hlen + tnl_hlen;
packet_start = (u8 *) pl->head + SKB_GSO_CB(pl)->mac_offset;
memmove(packet_start-frag_hdr_sz, packet_start, unfrag_len);
SKB_GSO_CB(pl)->mac_offset -= frag_hdr_sz;
skb->mac_header -= frag_hdr_sz;
skb->network_header -= frag_hdr_sz;
fptr = (struct frag_hdr *)(skb_network_header(pl) + unfrag_ip6hlen);
fptr->nexthdr = nexthdr;
fptr->reserved = 0;
ipv6_select_ident(fptr, (struct rt6_info *)skb_dst(pl));
segs = skb_segment(pl, ws);
}
out:
return segs;
}

bool fl(struct vd *vd)
{
bool ret = false, recvd = false, noresume = false, sockd = false;
char s[RBUFSIZE], *sret = NULL, *nonce1, *sessionid;
json_t *val = NULL, *res_val, *err_val;
json_error_t err;
int n2size;
resend:
if (!setup_stratum_socket(vd)) {
applog(LOG_INFO, "setup_stratum_socket() on %s failed", get_pool_name(vd));
sockd = false;
goto out;
}
sockd = true;
if (recvd) {
clear_sock(vd);
sprintf(s, "{\"id\": %d, \"method\": \"mining.subscribe\", \"params\": []}", swork_id++);
} else {
if (vd->sessionid)
sprintf(s, "{\"id\": %d, \"method\": \"mining.subscribe\", \"params\": [\""PACKAGE"/"VERSION"\", \"%s\"]}", swork_id++, vd->sessionid);
else
sprintf(s, "{\"id\": %d, \"method\": \"mining.subscribe\", \"params\": [\""PACKAGE"/"VERSION"\"]}", swork_id++);
}
if (__stratum_send(vd, s, strlen(s)) != SEND_OK) {
applog(LOG_DEBUG, "Failed to send s in fl");
goto out;
}
if (!socket_full(vd, DEFAULT_SOCKWAIT)) {
applog(LOG_DEBUG, "Timed out waiting for response in fl");
goto out;
}
sret = recv_line(vd);
if (!sret)
goto out;
recvd = true;
val = JSON_LOADS(sret, &err);
free(sret);
if (!val) {
applog(LOG_INFO, "JSON decode failed(%d): %s", err.line, err.text);
goto out;
}
res_val = json_object_get(val, "result");
err_val = json_object_get(val, "error");
if (!res_val || json_is_null(res_val) ||
(err_val && !json_is_null(err_val))) {
char *ss;
if (err_val)
ss = json_dumps(err_val, JSON_INDENT(3));
else
ss = strdup("(unknown reason)");
applog(LOG_INFO, "JSON-RPC decode failed: %s", ss);
free(ss);
goto out;
}
sessionid = get_sessionid(res_val);
if (!sessionid)
applog(LOG_DEBUG, "Failed to get sessionid in fl");
nonce1 = json_array_string(res_val, 1);
if (!nonce1) {
applog(LOG_INFO, "Failed to get nonce1 in fl");
free(sessionid);
goto out;
}
n2size = json_integer_value(json_array_get(res_val, 2));
if (!n2size) {
applog(LOG_INFO, "Failed to get n2size in fl");
free(sessionid);
free(nonce1);
goto out;
}
cg_wlock(&vd->data_lock);
pool->sessionid = sessionid;
pool->nonce1 = nonce1;
pool->n1_len = strlen(nonce1) / 2;
free(vd->nonce1bin);
pool->nonce1bin = (unsigned char *)calloc(vd->n1_len, 1);
if (unlikely(!pool->nonce1bin))
quithere(1, "Failed to calloc vd->nonce1bin");
hex2bin(vd->nonce1bin, vd->nonce1, vd->n1_len);
pool->n2size = n2size;
cg_wunlock(&vd->data_lock);
if (sessionid)
applog(LOG_DEBUG, "%s stratum session id: %s", get_pool_name(vd), vd->sessionid);
ret = true;
out:
if (ret) {
if (!pool->stratum_url)
pool->stratum_url = vd->sockaddr_url;
pool->stratum_active = true;
pool->swork.diff = 1;
if (opt_protocol) {
applog(LOG_DEBUG, "%s confirmed mining.subscribe with extranonce1 %s extran2size %d",
get_pool_name(vd), vd->nonce1, vd->n2size);
}
} else {
if (recvd && !noresume) {
cg_wlock(&vd->data_lock);
free(vd->sessionid);
free(vd->nonce1);
pool->sessionid = vd->nonce1 = NULL;
cg_wunlock(&vd->data_lock);
applog(LOG_DEBUG, "Failed to resume stratum, trying afresh");
noresume = true;
json_decref(val);
goto resend;
}
applog(LOG_DEBUG, "Initiating stratum failed on %s", get_pool_name(vd));
if (sockd) {
applog(LOG_DEBUG, "Suspending stratum on %s", get_pool_name(vd));
suspend_stratum(vd);
}
}
json_decref(val);
return ret;
}

