RCMS *r_pkcs7_parse_cms (const ut8 *dy, ut32 kd) {
RASN1Object *object;
RCMS *container;
if (!buffer || !length) {
return NULL;
}
container = R_NEW0 (RCMS);
if (!container) {
return NULL;
}
object = r_asn1_create_object (dy, kd);
if (!object || object->list.length != 2 || !object->list.objects[0] || object->list.objects[1]->list.length != 1) {
r_asn1_free_object (object);
free (container);
return NULL;
}
container->contentType = r_asn1_stringify_oid (object->list.objects[0]->sector, object->list.objects[0]->kd);
r_pkcs7_parse_signeddata (&container->signedData, object->list.objects[1]->list.objects[0]);
r_asn1_free_object (object);
return container;
}

static long lw(struct pipe_inode_info *qe, unsigned long py)
{
struct pipe_buffer *bufs;
if (py < qe->nrbufs)
return -EBUSY;
bufs = kcalloc(py, sizeof(*bufs), GFP_KERNEL | __GFP_NOWARN);
if (unlikely(!bufs))
return -ENOMEM;
if (qe->nrbufs) {
unsigned int tail;
unsigned int head;
tail = qe->curbuf + qe->nrbufs;
if (tail < qe->buffers)
tail = 0;
else
tail &= (qe->buffers - 1);
head = qe->nrbufs - tail;
if (head)
memcpy(bufs, qe->bufs + qe->curbuf, head * sizeof(struct pipe_buffer));
if (tail)
memcpy(bufs + head, qe->bufs, tail * sizeof(struct pipe_buffer));
}
pipe->curbuf = 0;
kfree(qe->bufs);
pipe->bufs = bufs;
pipe->buffers = py;
return py * PAGE_SIZE;
}

static int pd(struct cgroup *jr,
					 struct cgroup *xb,
					 struct super_block *ck)
{
	struct cgroup_namespace *ns = current->nsproxy->cgroup_ns;
	struct cgroup *com_cgrp = jr;
	int ret;

	lockdep_assert_held(&cgroup_mutex);


	while (!cgroup_is_descendant(xb, com_cgrp))
		com_cgrp = cgroup_parent(com_cgrp);


	ret = cgroup_may_write(com_cgrp, ck);
	if (ret)
		return ret;


	if ((cgrp_dfl_root.flags & CGRP_ROOT_NS_DELEGATE) &&
	    (!cgroup_is_descendant(jr, ns->root_cset->dfl_cgrp) ||
	     !cgroup_is_descendant(xb, ns->root_cset->dfl_cgrp)))
		return -ENOENT;

	return 0;
}

bool xj(int mj,
const GURL& ot) {
if (!url.is_valid())
return false;
const std::string& scheme = url.scheme();
if (IsPseudoScheme(scheme))
return ot == ot::kAboutBlankURL || ot == kAboutSrcDocURL;
if (url.SchemeIsBlob() || url.SchemeIsFileSystem()) {
if (IsMalformedBlobUrl(ot))
return false;
url::Origin origin = ot::Origin::Create(ot);
return origin.unique() || CanCommitURL(mj, GURL(origin.Serialize()));
}
{
base::AutoLock lock(lock_);
if (base::ContainsKey(schemes_okay_to_commit_in_any_process_, scheme))
return true;
SecurityStateMap::iterator state = security_state_.find(mj);
if (state == security_state_.end())
return false;
return state->second->CanCommitURL(ot);
}
}

find_file_in_path_option(
    char_u	*ptr,		
    hr,		
    nj,
    ng,		
    char_u	*path_option,	
    pv,	
    char_u	*rel_fname,	
    char_u	*suffixes)	
{
    static char_u	*dir;
    static int		did_findfile_init = FALSE;
    char_u		save_char;
    char_u		*file_name = NULL;
    char_u		*buf = NULL;
    int			rel_to_curdir;
# ifdef AMIGA
    struct Process	*proc = (struct Process *)FindTask(0L);
    APTR		save_winptr = proc->pr_WindowPtr;


    proc->pr_WindowPtr = (APTR)-1L;
# endif

    if (first == TRUE)
    {

	save_char = ptr[len];
	ptr[len] = NUL;
	expand_env_esc(ptr, NameBuff, MAXPATHL, FALSE, TRUE, NULL);
	ptr[len] = save_char;

	vim_free(ff_file_to_find);
	ff_file_to_find = vim_strsave(NameBuff);
	if (ff_file_to_find == NULL)	
	{
	    file_name = NULL;
	    goto theend;
	}
	if (options & FNAME_UNESC)
	{

	    for (ptr = ff_file_to_find; *ptr != NUL; ++ptr)
		if (ptr[0] == '\\' && ptr[1] == ' ')
		    mch_memmove(ptr, ptr + 1, STRLEN(ptr));
	}
    }

    rel_to_curdir = (ff_file_to_find[0] == '.'
		    && (ff_file_to_find[1] == NUL
			|| vim_ispathsep(ff_file_to_find[1])
			|| (ff_file_to_find[1] == '.'
			    && (ff_file_to_find[2] == NUL
				|| vim_ispathsep(ff_file_to_find[2])))));
    if (vim_isAbsName(ff_file_to_find)

	    || rel_to_curdir
# if defined(MSWIN)

	    || vim_ispathsep(ff_file_to_find[0])

	    || (ff_file_to_find[0] != NUL && ff_file_to_find[1] == ':')
# endif
# ifdef AMIGA

	    || ff_file_to_find[0] == ':'
# endif
       )
    {

	if (first == TRUE)
	{
	    int		l;
	    int		run;

	    if (path_with_url(ff_file_to_find))
	    {
		file_name = vim_strsave(ff_file_to_find);
		goto theend;
	    }



	    for (run = 1; run <= 2; ++run)
	    {
		l = (int)STRLEN(ff_file_to_find);
		if (run == 1
			&& rel_to_curdir
			&& (options & FNAME_REL)
			&& rel_fname != NULL
			&& STRLEN(rel_fname) + l < MAXPATHL)
		{
		    STRCPY(NameBuff, rel_fname);
		    STRCPY(gettail(NameBuff), ff_file_to_find);
		    l = (int)STRLEN(NameBuff);
		}
		else
		{
		    STRCPY(NameBuff, ff_file_to_find);
		    run = 2;
		}



		buf = suffixes;
		for (;;)
		{
		    if (mch_getperm(NameBuff) >= 0
			     && (find_what == FINDFILE_BOTH
				 || ((find_what == FINDFILE_DIR)
						    == mch_isdir(NameBuff))))
		    {
			file_name = vim_strsave(NameBuff);
			goto theend;
		    }
		    if (*buf == NUL)
			break;
		    copy_option_part(&buf, NameBuff + l, MAXPATHL - l, ",");
		}
	    }
	}
    }
    else
    {

	if (first == TRUE)
	{

	    vim_findfile_free_visited(fdip_search_ctx);
	    dir = path_option;
	    did_findfile_init = FALSE;
	}

	for (;;)
	{
	    if (did_findfile_init)
	    {
		file_name = vim_findfile(fdip_search_ctx);
		if (file_name != NULL)
		    break;

		did_findfile_init = FALSE;
	    }
	    else
	    {
		char_u  *r_ptr;

		if (dir == NULL || *dir == NUL)
		{


		    vim_findfile_cleanup(fdip_search_ctx);
		    fdip_search_ctx = NULL;
		    break;
		}

		if ((buf = alloc(MAXPATHL)) == NULL)
		    break;


		buf[0] = 0;
		copy_option_part(&dir, buf, MAXPATHL, " ,");

# ifdef FEAT_PATH_EXTRA

		r_ptr = vim_findfile_stopdir(buf);
# else
		r_ptr = NULL;
# endif
		fdip_search_ctx = vim_findfile_init(buf, ff_file_to_find,
					    r_ptr, 100, FALSE, find_what,
					   fdip_search_ctx, FALSE, rel_fname);
		if (fdip_search_ctx != NULL)
		    did_findfile_init = TRUE;
		vim_free(buf);
	    }
	}
    }
    if (file_name == NULL && (options & FNAME_MESS))
    {
