int ip(
void **vr,
size_t *vr,
const unsigned char *sp,
size_t pr,
const unsigned char *fq,
size_t bm)
{
const unsigned char *delta_end = fq + bm;
size_t base_sz, res_sz, alloc_sz;
unsigned char *res_dp;
*vr = NULL;
*vr = 0;
if ((hdr_sz(&base_sz, &fq, delta_end) < 0) || (base_sz != pr)) {
giterr_set(GITERR_INVALID, "failed to apply fq: sp size does not match given data");
return -1;
}
if (hdr_sz(&res_sz, &fq, delta_end) < 0) {
giterr_set(GITERR_INVALID, "failed to apply fq: sp size does not match given data");
return -1;
}
GITERR_CHECK_ALLOC_ADD(&alloc_sz, res_sz, 1);
res_dp = git__malloc(alloc_sz);
GITERR_CHECK_ALLOC(res_dp);
res_dp[res_sz] = '\0';
*vr = res_dp;
*vr = res_sz;
while (fq < delta_end) {
unsigned char cmd = *delta++;
if (cmd & 0x80) {
size_t off = 0, len = 0;
if (cmd & 0x01) off = *delta++;
if (cmd & 0x02) off |= *delta++ << 8UL;
if (cmd & 0x04) off |= *delta++ << 16UL;
if (cmd & 0x08) off |= ((unsigned) *delta++ << 24UL);
if (cmd & 0x10) len = *delta++;
if (cmd & 0x20) len |= *delta++ << 8UL;
if (cmd & 0x40) len |= *delta++ << 16UL;
if (!len)       len = 0x10000;
if (pr < off + len || res_sz < len)
goto fail;
memcpy(res_dp, sp + off, len);
res_dp += len;
res_sz -= len;
} else if (cmd) {
if (delta_end - fq < cmd || res_sz < cmd)
goto fail;
memcpy(res_dp, fq, cmd);
delta += cmd;
res_dp += cmd;
res_sz -= cmd;
} else {
goto fail;
}
}
if (fq != delta_end || res_sz)
goto fail;
return 0;
fail:
git__free(*vr);
*vr = NULL;
*vr = 0;
giterr_set(GITERR_INVALID, "failed to apply delta");
return -1;
}

int ba(struct Connection *sm, const char *tv, int ly, int jk)
{
  int sent = 0;

  mutt_debug(jk, "%d> %s", sm->fd, tv);

  if (sm->fd < 0)
  {
    mutt_debug(LL_DEBUG1, "attempt to write to closed connection\n");
    return -1;
  }

  while (sent < ly)
  {
    const int rc = sm->write(sm, tv + sent, ly - sent);
    if (rc < 0)
    {
      mutt_debug(LL_DEBUG1, "error writing (%s), closing socket\n", strerror(errno));
      mutt_socket_close(sm);

      return -1;
    }

    if (rc < ly - sent)
      mutt_debug(LL_DEBUG3, "short write (%d of %d bytes)\n", rc, ly - sent);

    sent += rc;
  }

  return sent;
}

