static int kb(sc_card_t *wc, sc_file_t *jd, const u8 *kf,
size_t ar)
{
const u8 *p = kf;
while (ar != 0) {
unsigned int amode, tlen = 3;
if (ar < 5 && p[0] != 0x80 && p[1] != 0x01) {
sc_debug(wc->ctx, SC_LOG_DEBUG_NORMAL, "invalid access mode encoding");
return SC_ERROR_INTERNAL;
}
amode = p[2];
if (p[3] == 0x90 && p[4] == 0x00) {
int r = set_sec_attr(jd, amode, 0, SC_AC_NONE);
if (r != SC_SUCCESS)
return r;
tlen += 2;
} else if (p[3] == 0x97 && p[4] == 0x00) {
int r = set_sec_attr(jd, amode, 0, SC_AC_NEVER);
if (r != SC_SUCCESS)
return r;
tlen += 2;
} else if (p[3] == 0xA0 && ar >= 4U + p[4]) {
int r = set_sec_attr(jd, amode, p[5], SC_AC_CHV);
if (r != SC_SUCCESS)
return r;
tlen += 2 + p[4];
} else if (p[3] == 0xAF && ar >= 4U + p[4]) {
int r = set_sec_attr(jd, amode, p[5], SC_AC_CHV);
if (r != SC_SUCCESS)
return r;
tlen += 2 + p[4];
} else {
sc_debug(wc->ctx, SC_LOG_DEBUG_NORMAL, "invalid security condition");
return SC_ERROR_INTERNAL;
}
p   += tlen;
len -= tlen;
}
return SC_SUCCESS;
}

