int gk(SSL *wv)
{
    STACK_OF(SSL_CIPHER) *sk;
    const SSL_CIPHER *c;
    CERT *ct = wv->cert;
    unsigned char *p, *d;
    int i, al = SSL_AD_INTERNAL_ERROR, ok;
    unsigned int j;
    long n;
#ifndef OPENSSL_NO_COMP
    SSL_COMP *comp;
#endif

    if (SSL_IS_DTLS(wv))
        wv->first_packet = 1;

    n = wv->method->ssl_get_message(wv,
                                   SSL3_ST_CR_SRVR_HELLO_A,
                                   SSL3_ST_CR_SRVR_HELLO_B, -1, 20000, &ok);

    if (!ok)
        return ((int)n);

    if (SSL_IS_DTLS(wv)) {
        wv->first_packet = 0;
        if (wv->s3->tmp.message_type == DTLS1_MT_HELLO_VERIFY_REQUEST) {
            if (wv->d1->send_cookie == 0) {
                wv->s3->tmp.reuse_message = 1;
                return 1;
            } else {            

                al = SSL_AD_UNEXPECTED_MESSAGE;
                SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_BAD_MESSAGE_TYPE);
                goto f_err;
            }
        }
    }

    if (wv->s3->tmp.message_type != SSL3_MT_SERVER_HELLO) {
        al = SSL_AD_UNEXPECTED_MESSAGE;
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_BAD_MESSAGE_TYPE);
        goto f_err;
    }

    d = p = (unsigned char *)wv->init_msg;
    if (wv->method->version == DTLS_ANY_VERSION) {

        int hversion = (p[0] << 8) | p[1];
        int options = wv->options;
        if (hversion == DTLS1_2_VERSION && !(options & SSL_OP_NO_DTLSv1_2))
            wv->method = DTLSv1_2_client_method();
        else if (tls1_suiteb(wv)) {
            SSLerr(SSL_F_SSL3_GET_SERVER_HELLO,
                   SSL_R_ONLY_DTLS_1_2_ALLOWED_IN_SUITEB_MODE);
            wv->version = hversion;
            al = SSL_AD_PROTOCOL_VERSION;
            goto f_err;
        } else if (hversion == DTLS1_VERSION && !(options & SSL_OP_NO_DTLSv1))
            wv->method = DTLSv1_client_method();
        else {
            SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_WRONG_SSL_VERSION);
            wv->version = hversion;
            al = SSL_AD_PROTOCOL_VERSION;
            goto f_err;
        }
        wv->version = wv->method->version;
    }

    if ((p[0] != (wv->version >> 8)) || (p[1] != (wv->version & 0xff))) {
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_WRONG_SSL_VERSION);
        wv->version = (wv->version & 0xff00) | p[1];
        al = SSL_AD_PROTOCOL_VERSION;
        goto f_err;
    }
    p += 2;



    memcpy(wv->s3->server_random, p, SSL3_RANDOM_SIZE);
    p += SSL3_RANDOM_SIZE;

    wv->hit = 0;


    j = *(p++);

    if ((j > sizeof wv->session->session_id) || (j > SSL3_SESSION_ID_SIZE)) {
        al = SSL_AD_ILLEGAL_PARAMETER;
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_SSL3_SESSION_ID_TOO_LONG);
        goto f_err;
    }
#ifndef OPENSSL_NO_TLSEXT

    if (wv->version >= TLS1_VERSION && wv->tls_session_secret_cb &&
        wv->session->tlsext_tick) {
        SSL_CIPHER *pref_cipher = NULL;
        wv->session->master_key_length = sizeof(wv->session->master_key);
        if (wv->tls_session_secret_cb(wv, wv->session->master_key,
                                     &wv->session->master_key_length,
                                     NULL, &pref_cipher,
                                     wv->tls_session_secret_cb_arg)) {
            wv->session->cipher = pref_cipher ?
                pref_cipher : ssl_get_cipher_by_char(wv, p + j);
        } else {
            SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, ERR_R_INTERNAL_ERROR);
            al = SSL_AD_INTERNAL_ERROR;
            goto f_err;
        }
    }
#endif                          

    if (j != 0 && j == wv->session->session_id_length
        && memcmp(p, wv->session->session_id, j) == 0) {
        if (wv->sid_ctx_length != wv->session->sid_ctx_length
            || memcmp(wv->session->sid_ctx, wv->sid_ctx, wv->sid_ctx_length)) {

            al = SSL_AD_ILLEGAL_PARAMETER;
            SSLerr(SSL_F_SSL3_GET_SERVER_HELLO,
                   SSL_R_ATTEMPT_TO_REUSE_SESSION_IN_DIFFERENT_CONTEXT);
            goto f_err;
        }
        wv->hit = 1;
    } else {

        if (wv->session->session_id_length > 0) {
            if (!ssl_get_new_session(wv, 0)) {
                goto f_err;
            }
        }
        wv->session->session_id_length = j;
        memcpy(wv->session->session_id, p, j); 
    }
    p += j;
    c = ssl_get_cipher_by_char(wv, p);
    if (c == NULL) {

        al = SSL_AD_ILLEGAL_PARAMETER;
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_UNKNOWN_CIPHER_RETURNED);
        goto f_err;
    }

    if (c->algorithm_ssl & ct->mask_ssl ||
        c->algorithm_mkey & ct->mask_k || c->algorithm_auth & ct->mask_a) {
        al = SSL_AD_ILLEGAL_PARAMETER;
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_WRONG_CIPHER_RETURNED);
        goto f_err;
    }
    p += ssl_put_cipher_by_char(wv, NULL, NULL);

    sk = ssl_get_ciphers_by_id(wv);
    i = sk_SSL_CIPHER_find(sk, c);
    if (i < 0) {

        al = SSL_AD_ILLEGAL_PARAMETER;
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_WRONG_CIPHER_RETURNED);
        goto f_err;
    }


    if (wv->session->cipher)
        wv->session->cipher_id = wv->session->cipher->id;
    if (wv->hit && (wv->session->cipher_id != c->id)) {

#if 0
        if (!(wv->options & SSL_OP_NETSCAPE_REUSE_CIPHER_CHANGE_BUG))
#endif
        {
            al = SSL_AD_ILLEGAL_PARAMETER;
            SSLerr(SSL_F_SSL3_GET_SERVER_HELLO,
                   SSL_R_OLD_SESSION_CIPHER_NOT_RETURNED);
            goto f_err;
        }
    }
    wv->s3->tmp.new_cipher = c;

    if (!SSL_USE_SIGALGS(wv) && !ssl3_digest_cached_records(wv))
        goto f_err;


#ifdef OPENSSL_NO_COMP
    if (*(p++) != 0) {
        al = SSL_AD_ILLEGAL_PARAMETER;
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO,
               SSL_R_UNSUPPORTED_COMPRESSION_ALGORITHM);
        goto f_err;
    }

    if (wv->session->compress_meth != 0) {
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_INCONSISTENT_COMPRESSION);
        goto f_err;
    }
#else
    j = *(p++);
    if (wv->hit && j != wv->session->compress_meth) {
        al = SSL_AD_ILLEGAL_PARAMETER;
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO,
               SSL_R_OLD_SESSION_COMPRESSION_ALGORITHM_NOT_RETURNED);
        goto f_err;
    }
    if (j == 0)
        comp = NULL;
    else if (wv->options & SSL_OP_NO_COMPRESSION) {
        al = SSL_AD_ILLEGAL_PARAMETER;
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_COMPRESSION_DISABLED);
        goto f_err;
    } else
        comp = ssl3_comp_find(wv->ctx->comp_methods, j);

    if ((j != 0) && (comp == NULL)) {
        al = SSL_AD_ILLEGAL_PARAMETER;
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO,
               SSL_R_UNSUPPORTED_COMPRESSION_ALGORITHM);
        goto f_err;
    } else {
        wv->s3->tmp.new_compression = comp;
    }
#endif

#ifndef OPENSSL_NO_TLSEXT

    if (!ssl_parse_serverhello_tlsext(wv, &p, d, n)) {
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_PARSE_TLSEXT);
        goto err;
    }
#endif

    if (p != (d + n)) {

        al = SSL_AD_DECODE_ERROR;
        SSLerr(SSL_F_SSL3_GET_SERVER_HELLO, SSL_R_BAD_PACKET_LENGTH);
        goto f_err;
    }

    return (1);
 f_err:
    ssl3_send_alert(wv, SSL3_AL_FATAL, al);
 err:
    wv->state = SSL_ST_ERR;
    return (-1);
}

