int ju(ThreadVars *xv, DecodeThreadVars *yj, Packet *nn, uint8_t *kc, uint16_t ug, PacketQueue *ni)
{
if (!g_teredo_enabled)
return TM_ECODE_FAILED;
uint8_t *start = kc;
if (ug < IPV6_HEADER_LEN)
return TM_ECODE_FAILED;
if (start[0] == 0x0) {
switch (start[1]) {
case 0x0:
if (ug >= TEREDO_ORIG_INDICATION_LENGTH + IPV6_HEADER_LEN)
start += TEREDO_ORIG_INDICATION_LENGTH;
else
return TM_ECODE_FAILED;
break;
case 0x1:
return TM_ECODE_FAILED;
default:
return TM_ECODE_FAILED;
}
}
if (IP_GET_RAW_VER(start) == 6) {
IPV6Hdr *thdr = (IPV6Hdr *)start;
if (ug ==  IPV6_HEADER_LEN +
IPV6_GET_RAW_PLEN(thdr) + (start - kc)) {
if (ni != NULL) {
int blen = ug - (start - kc);
Packet *tp = PacketTunnelPktSetup(xv, yj, nn, start, blen,
DECODE_TUNNEL_IPV6, ni);
if (tp != NULL) {
PKT_SET_SRC(tp, PKT_SRC_DECODER_TEREDO);
PacketEnqueue(ni,tp);
StatsIncr(xv, yj->counter_teredo);
return TM_ECODE_OK;
}
}
}
return TM_ECODE_FAILED;
}
return TM_ECODE_FAILED;
}

