jbig2_text_region(Jbig2Ctx *fu, Jbig2Segment *bx, const byte *pz)
{
int offset = 0;
Jbig2RegionSegmentInfo region_info;
Jbig2TextRegionParams params;
Jbig2Image *image = NULL;
Jbig2SymbolDict **dicts = NULL;
int n_dicts = 0;
uint16_t flags = 0;
uint16_t huffman_flags = 0;
Jbig2ArithCx *GR_stats = NULL;
int code = 0;
Jbig2WordStream *ws = NULL;
Jbig2ArithState *as = NULL;
int table_index = 0;
const Jbig2HuffmanParams *huffman_params = NULL;
if (bx->data_length < 17)
goto too_short;
jbig2_get_region_segment_info(&region_info, pz);
offset += 17;
flags = jbig2_get_uint16(pz + offset);
offset += 2;
jbig2_error(fu, JBIG2_SEVERITY_DEBUG, bx->number, "text region header flags 0x%04x", flags);
memset(&params, 0, sizeof(Jbig2TextRegionParams));
params.SBHUFF = flags & 0x0001;
params.SBREFINE = flags & 0x0002;
params.LOGSBSTRIPS = (flags & 0x000c) >> 2;
params.SBSTRIPS = 1 << params.LOGSBSTRIPS;
params.REFCORNER = (Jbig2RefCorner)((flags & 0x0030) >> 4);
params.TRANSPOSED = flags & 0x0040;
params.SBCOMBOP = (Jbig2ComposeOp)((flags & 0x0180) >> 7);
params.SBDEFPIXEL = flags & 0x0200;
params.SBDSOFFSET = (flags & 0x7C00) >> 10;
if (params.SBDSOFFSET > 0x0f)
params.SBDSOFFSET -= 0x20;
params.SBRTEMPLATE = flags & 0x8000;
if (params.SBDSOFFSET) {
jbig2_error(fu, JBIG2_SEVERITY_DEBUG, bx->number, "text region has SBDSOFFSET %d", params.SBDSOFFSET);
}
if (params.SBHUFF) {
huffman_flags = jbig2_get_uint16(pz + offset);
offset += 2;
if (huffman_flags & 0x8000)
jbig2_error(fu, JBIG2_SEVERITY_WARNING, bx->number, "reserved bit 15 of text region huffman flags is not zero");
} else {
if ((params.SBREFINE) && !(params.SBRTEMPLATE)) {
params.sbrat[0] = pz[offset];
params.sbrat[1] = pz[offset + 1];
params.sbrat[2] = pz[offset + 2];
params.sbrat[3] = pz[offset + 3];
offset += 4;
}
}
params.SBNUMINSTANCES = jbig2_get_uint32(pz + offset);
offset += 4;
if (params.SBHUFF) {
switch (huffman_flags & 0x0003) {
case 0:
params.SBHUFFFS = jbig2_build_huffman_table(fu, &jbig2_huffman_params_F);
break;
case 1:
params.SBHUFFFS = jbig2_build_huffman_table(fu, &jbig2_huffman_params_G);
break;
case 3:
huffman_params = jbig2_find_table(fu, bx, table_index);
if (huffman_params == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "Custom FS huffman table not found (%d)", table_index);
goto cleanup1;
}
params.SBHUFFFS = jbig2_build_huffman_table(fu, huffman_params);
++table_index;
break;
case 2:
default:
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "text region specified invalid FS huffman table");
goto cleanup1;
break;
}
if (params.SBHUFFFS == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "failed to allocate text region specified FS huffman table");
goto cleanup1;
}
switch ((huffman_flags & 0x000c) >> 2) {
case 0:
params.SBHUFFDS = jbig2_build_huffman_table(fu, &jbig2_huffman_params_H);
break;
case 1:
params.SBHUFFDS = jbig2_build_huffman_table(fu, &jbig2_huffman_params_I);
break;
case 2:
params.SBHUFFDS = jbig2_build_huffman_table(fu, &jbig2_huffman_params_J);
break;
case 3:
huffman_params = jbig2_find_table(fu, bx, table_index);
if (huffman_params == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "Custom DS huffman table not found (%d)", table_index);
goto cleanup1;
}
params.SBHUFFDS = jbig2_build_huffman_table(fu, huffman_params);
++table_index;
break;
}
if (params.SBHUFFDS == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "failed to allocate text region specified DS huffman table");
goto cleanup1;
}
switch ((huffman_flags & 0x0030) >> 4) {
case 0:
params.SBHUFFDT = jbig2_build_huffman_table(fu, &jbig2_huffman_params_K);
break;
case 1:
params.SBHUFFDT = jbig2_build_huffman_table(fu, &jbig2_huffman_params_L);
break;
case 2:
params.SBHUFFDT = jbig2_build_huffman_table(fu, &jbig2_huffman_params_M);
break;
case 3:
huffman_params = jbig2_find_table(fu, bx, table_index);
if (huffman_params == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "Custom DT huffman table not found (%d)", table_index);
goto cleanup1;
}
params.SBHUFFDT = jbig2_build_huffman_table(fu, huffman_params);
++table_index;
break;
}
if (params.SBHUFFDT == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "failed to allocate text region specified DT huffman table");
goto cleanup1;
}
switch ((huffman_flags & 0x00c0) >> 6) {
case 0:
params.SBHUFFRDW = jbig2_build_huffman_table(fu, &jbig2_huffman_params_N);
break;
case 1:
params.SBHUFFRDW = jbig2_build_huffman_table(fu, &jbig2_huffman_params_O);
break;
case 3:
huffman_params = jbig2_find_table(fu, bx, table_index);
if (huffman_params == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "Custom RDW huffman table not found (%d)", table_index);
goto cleanup1;
}
params.SBHUFFRDW = jbig2_build_huffman_table(fu, huffman_params);
++table_index;
break;
case 2:
default:
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "text region specified invalid RDW huffman table");
goto cleanup1;
break;
}
if (params.SBHUFFRDW == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "failed to allocate text region specified RDW huffman table");
goto cleanup1;
}
switch ((huffman_flags & 0x0300) >> 8) {
case 0:
params.SBHUFFRDH = jbig2_build_huffman_table(fu, &jbig2_huffman_params_N);
break;
case 1:
params.SBHUFFRDH = jbig2_build_huffman_table(fu, &jbig2_huffman_params_O);
break;
case 3:
huffman_params = jbig2_find_table(fu, bx, table_index);
if (huffman_params == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "Custom RDH huffman table not found (%d)", table_index);
goto cleanup1;
}
params.SBHUFFRDH = jbig2_build_huffman_table(fu, huffman_params);
++table_index;
break;
case 2:
default:
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "text region specified invalid RDH huffman table");
goto cleanup1;
break;
}
if (params.SBHUFFRDH == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "failed to allocate text region specified RDH huffman table");
goto cleanup1;
}
switch ((huffman_flags & 0x0c00) >> 10) {
case 0:
params.SBHUFFRDX = jbig2_build_huffman_table(fu, &jbig2_huffman_params_N);
break;
case 1:
params.SBHUFFRDX = jbig2_build_huffman_table(fu, &jbig2_huffman_params_O);
break;
case 3:
huffman_params = jbig2_find_table(fu, bx, table_index);
if (huffman_params == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "Custom RDX huffman table not found (%d)", table_index);
goto cleanup1;
}
params.SBHUFFRDX = jbig2_build_huffman_table(fu, huffman_params);
++table_index;
break;
case 2:
default:
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "text region specified invalid RDX huffman table");
goto cleanup1;
break;
}
if (params.SBHUFFRDX == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "failed to allocate text region specified RDX huffman table");
goto cleanup1;
}
switch ((huffman_flags & 0x3000) >> 12) {
case 0:
params.SBHUFFRDY = jbig2_build_huffman_table(fu, &jbig2_huffman_params_N);
break;
case 1:
params.SBHUFFRDY = jbig2_build_huffman_table(fu, &jbig2_huffman_params_O);
break;
case 3:
huffman_params = jbig2_find_table(fu, bx, table_index);
if (huffman_params == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "Custom RDY huffman table not found (%d)", table_index);
goto cleanup1;
}
params.SBHUFFRDY = jbig2_build_huffman_table(fu, huffman_params);
++table_index;
break;
case 2:
default:
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "text region specified invalid RDY huffman table");
goto cleanup1;
break;
}
if (params.SBHUFFRDY == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "failed to allocate text region specified RDY huffman table");
goto cleanup1;
}
switch ((huffman_flags & 0x4000) >> 14) {
case 0:
params.SBHUFFRSIZE = jbig2_build_huffman_table(fu, &jbig2_huffman_params_A);
break;
case 1:
huffman_params = jbig2_find_table(fu, bx, table_index);
if (huffman_params == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "Custom RSIZE huffman table not found (%d)", table_index);
goto cleanup1;
}
params.SBHUFFRSIZE = jbig2_build_huffman_table(fu, huffman_params);
++table_index;
break;
}
if (params.SBHUFFRSIZE == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "failed to allocate text region specified RSIZE huffman table");
goto cleanup1;
}
if (huffman_flags & 0x8000) {
jbig2_error(fu, JBIG2_SEVERITY_WARNING, bx->number, "text region huffman flags bit 15 is set, contrary to spec");
}
}
jbig2_error(fu, JBIG2_SEVERITY_INFO, bx->number,
"text region: %d x %d @ (%d,%d) %d symbols", region_info.width, region_info.height, region_info.x, region_info.y, params.SBNUMINSTANCES);
n_dicts = jbig2_sd_count_referred(fu, bx);
if (n_dicts != 0) {
dicts = jbig2_sd_list_referred(fu, bx);
} else {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "text region refers to no symbol dictionaries!");
goto cleanup1;
}
if (dicts == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "unable to retrive symbol dictionaries! previous parsing error?");
goto cleanup1;
} else {
int index;
if (dicts[0] == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_WARNING, bx->number, "unable to find first referenced symbol dictionary!");
goto cleanup1;
}
for (index = 1; index < n_dicts; index++)
if (dicts[index] == NULL) {
jbig2_error(fu, JBIG2_SEVERITY_WARNING, bx->number, "unable to find all referenced symbol dictionaries!");
n_dicts = index;
}
}
{
int stats_size = params.SBRTEMPLATE ? 1 << 10 : 1 << 13;
GR_stats = jbig2_new(fu, Jbig2ArithCx, stats_size);
if (GR_stats == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "could not allocate GR_stats");
goto cleanup1;
}
memset(GR_stats, 0, stats_size);
}
image = jbig2_image_new(fu, region_info.width, region_info.height);
if (image == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "couldn't allocate text region image");
goto cleanup2;
}
ws = jbig2_word_stream_buf_new(fu, pz + offset, bx->data_length - offset);
if (ws == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "couldn't allocate ws in text region image");
goto cleanup2;
}
as = jbig2_arith_new(fu, ws);
if (as == NULL) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "couldn't allocate as in text region image");
goto cleanup2;
}
if (!params.SBHUFF) {
int SBSYMCODELEN, index;
int SBNUMSYMS = 0;
for (index = 0; index < n_dicts; index++) {
SBNUMSYMS += dicts[index]->n_symbols;
}
params.IADT = jbig2_arith_int_ctx_new(fu);
params.IAFS = jbig2_arith_int_ctx_new(fu);
params.IADS = jbig2_arith_int_ctx_new(fu);
params.IAIT = jbig2_arith_int_ctx_new(fu);
if ((params.IADT == NULL) || (params.IAFS == NULL) || (params.IADS == NULL) || (params.IAIT == NULL)) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "couldn't allocate text region image data");
goto cleanup3;
}
for (SBSYMCODELEN = 0; (1 << SBSYMCODELEN) < SBNUMSYMS; SBSYMCODELEN++) {
}
params.IAID = jbig2_arith_iaid_ctx_new(fu, SBSYMCODELEN);
params.IARI = jbig2_arith_int_ctx_new(fu);
params.IARDW = jbig2_arith_int_ctx_new(fu);
params.IARDH = jbig2_arith_int_ctx_new(fu);
params.IARDX = jbig2_arith_int_ctx_new(fu);
params.IARDY = jbig2_arith_int_ctx_new(fu);
if ((params.IAID == NULL) || (params.IARI == NULL) ||
(params.IARDW == NULL) || (params.IARDH == NULL) || (params.IARDX == NULL) || (params.IARDY == NULL)) {
code = jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "couldn't allocate text region image data");
goto cleanup4;
}
}
code = jbig2_decode_text_region(fu, bx, &params,
(const Jbig2SymbolDict * const *)dicts, n_dicts, image,
segment_data + offset, bx->data_length - offset, GR_stats, as, ws);
if (code < 0) {
jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "failed to decode text region image data");
goto cleanup4;
}
if ((bx->flags & 63) == 4) {
segment->result = jbig2_image_clone(fu, image);
} else {
jbig2_error(fu, JBIG2_SEVERITY_DEBUG, bx->number,
"composing %dx%d decoded text region onto page at (%d, %d)", region_info.width, region_info.height, region_info.x, region_info.y);
jbig2_page_add_result(fu, &fu->pages[fu->current_page], image, region_info.x, region_info.y, region_info.op);
}
cleanup4:
if (!params.SBHUFF) {
jbig2_arith_iaid_ctx_free(fu, params.IAID);
jbig2_arith_int_ctx_free(fu, params.IARI);
jbig2_arith_int_ctx_free(fu, params.IARDW);
jbig2_arith_int_ctx_free(fu, params.IARDH);
jbig2_arith_int_ctx_free(fu, params.IARDX);
jbig2_arith_int_ctx_free(fu, params.IARDY);
}
cleanup3:
if (!params.SBHUFF) {
jbig2_arith_int_ctx_free(fu, params.IADT);
jbig2_arith_int_ctx_free(fu, params.IAFS);
jbig2_arith_int_ctx_free(fu, params.IADS);
jbig2_arith_int_ctx_free(fu, params.IAIT);
}
jbig2_free(fu->allocator, as);
jbig2_word_stream_buf_free(fu, ws);
cleanup2:
jbig2_free(fu->allocator, GR_stats);
jbig2_image_release(fu, image);
cleanup1:
if (params.SBHUFF) {
jbig2_release_huffman_table(fu, params.SBHUFFFS);
jbig2_release_huffman_table(fu, params.SBHUFFDS);
jbig2_release_huffman_table(fu, params.SBHUFFDT);
jbig2_release_huffman_table(fu, params.SBHUFFRDX);
jbig2_release_huffman_table(fu, params.SBHUFFRDY);
jbig2_release_huffman_table(fu, params.SBHUFFRDW);
jbig2_release_huffman_table(fu, params.SBHUFFRDH);
jbig2_release_huffman_table(fu, params.SBHUFFRSIZE);
}
jbig2_free(fu->allocator, dicts);
return code;
too_short:
return jbig2_error(fu, JBIG2_SEVERITY_FATAL, bx->number, "Segment too short");
}

