Node* mx(Node* cn, const String& lv, ExceptionCode& vc)
{
if (cn->isDocumentNode() || (cn->parentNode() && cn->parentNode()->isDocumentNode())) {
patchDocument(lv);
return 0;
}
Node* previousSibling = cn->previousSibling();
RefPtr<DocumentFragment> fragment = DocumentFragment::create(m_document);
fragment->parseHTML(lv, cn->parentElement() ? cn->parentElement() : m_document->documentElement());
ContainerNode* parentNode = cn->parentNode();
Vector<OwnPtr<Digest> > oldList;
for (Node* child = parentNode->firstChild(); child; child = child->nextSibling())
oldList.append(createDigest(child, 0));
String markupCopy = lv;
markupCopy.makeLower();
Vector<OwnPtr<Digest> > newList;
for (Node* child = parentNode->firstChild(); child != cn; child = child->nextSibling())
newList.append(createDigest(child, 0));
for (Node* child = fragment->firstChild(); child; child = child->nextSibling()) {
if (child->hasTagName(headTag) && !child->firstChild() && markupCopy.find("</head>") == notFound)
continue;
if (child->hasTagName(bodyTag) && !child->firstChild() && markupCopy.find("</body>") == notFound)
continue;
newList.append(createDigest(child, &m_unusedNodesMap));
}
for (Node* child = cn->nextSibling(); child; child = child->nextSibling())
newList.append(createDigest(child, 0));
if (!innerPatchChildren(parentNode, oldList, newList, vc)) {
ec = 0;
if (!m_domEditor->replaceChild(parentNode, fragment.release(), cn, vc))
return 0;
}
return previousSibling ? previousSibling->nextSibling() : parentNode->firstChild();
}

static void xq(struct net_bridge *eh,
struct net_bridge_port_group *ds)
{
struct net_bridge_mdb_htable *mdb;
struct net_bridge_mdb_entry *mp;
struct net_bridge_port_group *p;
struct net_bridge_port_group __rcu **pp;
mdb = mlock_dereference(eh->mdb, eh);
mp = br_mdb_ip_get(mdb, &ds->addr);
if (WARN_ON(!mp))
return;
for (pp = &mp->ports;
(p = mlock_dereference(*pp, eh)) != NULL;
pp = &p->next) {
if (p != ds)
continue;
rcu_assign_pointer(*pp, p->next);
hlist_del_init(&p->mglist);
del_timer(&p->timer);
call_rcu_bh(&p->rcu, br_multicast_free_pg);
if (!mp->ports && !mp->mglist &&
netif_running(eh->dev))
mod_timer(&mp->timer, jiffies);
return;
}
WARN_ON(1);
}

