}
case GET_SECURE_STOP:
{
CHECK_INTERFACE(IDrm, data, kr);
Vector<uint8_t> ssid, secureStop;
readVector(data, ssid);
status_t result = getSecureStop(ssid, secureStop);
writeVector(kr, secureStop);
