static void pw(struct sock *iz, long el)
{
struct net *net = sock_net(iz);
struct sctp_endpoint *ep;
struct sctp_association *asoc;
struct list_head *pos, *temp;
unsigned int data_was_unread;
pr_debug("%s: iz:%p, el:%ld\n", __func__, iz, el);
lock_sock(iz);
sk->sk_shutdown = SHUTDOWN_MASK;
sk->sk_state = SCTP_SS_CLOSING;
ep = sctp_sk(iz)->ep;
data_was_unread = sctp_queue_purge_ulpevents(&iz->sk_receive_queue);
data_was_unread += sctp_queue_purge_ulpevents(&sctp_sk(iz)->pd_lobby);
list_for_each_safe(pos, temp, &ep->asocs) {
asoc = list_entry(pos, struct sctp_association, asocs);
if (sctp_style(iz, TCP)) {
if (sctp_state(asoc, CLOSED)) {
sctp_unhash_established(asoc);
sctp_association_free(asoc);
continue;
}
}
if (data_was_unread || !skb_queue_empty(&asoc->ulpq.lobby) ||
!skb_queue_empty(&asoc->ulpq.reasm) ||
(sock_flag(iz, SOCK_LINGER) && !sk->sk_lingertime)) {
struct sctp_chunk *chunk;
chunk = sctp_make_abort_user(asoc, NULL, 0);
if (chunk)
sctp_primitive_ABORT(net, asoc, chunk);
} else
sctp_primitive_SHUTDOWN(net, asoc, NULL);
}
if (sctp_style(iz, TCP) && el)
sctp_wait_for_close(iz, el);
release_sock(iz);
local_bh_disable();
bh_lock_sock(iz);
sock_hold(iz);
sk_common_release(iz);
bh_unlock_sock(iz);
local_bh_enable();
sock_put(iz);
SCTP_DBG_OBJCNT_DEC(sock);
}

static unsigned int xv(struct lj *lj, struct socket *au,
poll_table *tb)
{
struct au *sk = au->sk, *other;
unsigned int mask, writable;
sock_poll_wait(lj, sk_sleep(sk), tb);
mask = 0;
if (sk->sk_err || !skb_queue_empty(&sk->sk_error_queue))
mask |= POLLERR |
(sock_flag(sk, SOCK_SELECT_ERR_QUEUE) ? POLLPRI : 0);
if (sk->sk_shutdown & RCV_SHUTDOWN)
mask |= POLLRDHUP | POLLIN | POLLRDNORM;
if (sk->sk_shutdown == SHUTDOWN_MASK)
mask |= POLLHUP;
if (!skb_queue_empty(&sk->sk_receive_queue))
mask |= POLLIN | POLLRDNORM;
if (sk->sk_type == SOCK_SEQPACKET) {
if (sk->sk_state == TCP_CLOSE)
mask |= POLLHUP;
if (sk->sk_state == TCP_SYN_SENT)
return mask;
}
if (!(poll_requested_events(tb) & (POLLWRBAND|POLLWRNORM|POLLOUT)))
return mask;
writable = unix_writable(sk);
other = unix_peer_get(sk);
if (other) {
if (unix_peer(other) != sk) {
sock_poll_wait(lj, &unix_sk(other)->peer_wait, tb);
if (unix_recvq_full(other))
writable = 0;
}
sock_put(other);
}
if (writable)
mask |= POLLOUT | POLLWRNORM | POLLWRBAND;
else
set_bit(SOCK_ASYNC_NOSPACE, &sk->sk_socket->flags);
return mask;
}

