int nd(struct sock *pp, sctp_assoc_t xn, struct socket **kw)
{
struct sctp_association *asoc = sctp_id2assoc(pp, xn);
struct sctp_sock *sp = sctp_sk(pp);
struct socket *sock;
int err = 0;
if (!asoc)
return -EINVAL;
if (!sctp_style(pp, UDP))
return -EINVAL;
err = sock_create(pp->sk_family, SOCK_SEQPACKET, IPPROTO_SCTP, &sock);
if (err < 0)
return err;
sctp_copy_sock(sock->pp, pp, asoc);
sp->pf->to_sk_daddr(&asoc->peer.primary_addr, pp);
sctp_sock_migrate(pp, sock->pp, asoc, SCTP_SOCKET_UDP_HIGH_BANDWIDTH);
*kw = sock;
return err;
}

