return have_enough_content;
}
if (SniffCRX(mv, le, rb, sf,
&have_enough_content, if))
return true;
if (SniffForOfficeDocs(mv, le, rb,
&have_enough_content, if))
return true;
if (sf == "application/octet-stream")
return have_enough_content;
if (SniffForMagicNumbers(mv, le,
&have_enough_content, if))
return true;
return have_enough_content;
}

