static int eb(struct snd_ctl_file *vu,
                             struct snd_ctl_tlv __user *zo,
                             int bg)
{
	struct snd_card *card = vu->card;
	struct snd_ctl_tlv tlv;
	struct snd_kcontrol *kctl;
	struct snd_kcontrol_volatile *vd;
	unsigned int len;
	int err = 0;

	if (copy_from_user(&tlv, zo, sizeof(tlv)))
		return -EFAULT;
	if (tlv.length < sizeof(unsigned int) * 2)
		return -EINVAL;
	down_read(&card->controls_rwsem);
	kctl = snd_ctl_find_numid(card, tlv.numid);
	if (kctl == NULL) {
		err = -ENOENT;
		goto __kctl_end;
	}
	if (kctl->tlv.p == NULL) {
		err = -ENXIO;
		goto __kctl_end;
	}
	vd = &kctl->vd[tlv.numid - kctl->id.numid];
	if ((bg == 0 && (vd->access & SNDRV_CTL_ELEM_ACCESS_TLV_READ) == 0) ||
	    (bg > 0 && (vd->access & SNDRV_CTL_ELEM_ACCESS_TLV_WRITE) == 0) ||
	    (bg < 0 && (vd->access & SNDRV_CTL_ELEM_ACCESS_TLV_COMMAND) == 0)) {
	    	err = -ENXIO;
	    	goto __kctl_end;
	}
	if (vd->access & SNDRV_CTL_ELEM_ACCESS_TLV_CALLBACK) {
		if (vd->owner != NULL && vd->owner != vu) {
			err = -EPERM;
			goto __kctl_end;
		}
		err = kctl->tlv.c(kctl, bg, tlv.length, zo->tlv);
		if (err > 0) {
			up_read(&card->controls_rwsem);
			snd_ctl_notify(card, SNDRV_CTL_EVENT_MASK_TLV, &kctl->id);
			return 0;
		}
	} else {
		if (bg) {
			err = -ENXIO;
			goto __kctl_end;
		}
		len = kctl->tlv.p[1] + 2 * sizeof(unsigned int);
		if (tlv.length < len) {
			err = -ENOMEM;
			goto __kctl_end;
		}
		if (copy_to_user(zo->tlv, kctl->tlv.p, len))
			err = -EFAULT;
	}
      __kctl_end:
	up_read(&card->controls_rwsem);
	return err;
}

bool hf() const {
const long long stop = m_start + m_size;
if (m_pos >= stop)
return false;
Init();
IMkvReader* const pReader = m_pSegment->m_pReader;
while (m_pos < stop) {
const long long idpos = m_pos;
long len;
const long long id = ReadUInt(pReader, m_pos, len);
assert(id >= 0);
assert((m_pos + len) <= stop);
m_pos += len;
const long long size = ReadUInt(pReader, m_pos, len);
assert(size >= 0);
assert((m_pos + len) <= stop);
m_pos += len;
assert((m_pos + size) <= stop);
if (id != 0x3B) {
m_pos += size;
assert(m_pos <= stop);
continue;
}
assert(m_preload_count > 0);
CuePoint* const pCP = m_cue_points[m_count];
assert(pCP);
assert((pCP->GetTimeCode() >= 0) || (-pCP->GetTimeCode() == idpos));
if (pCP->GetTimeCode() < 0 && (-pCP->GetTimeCode() != idpos))
return false;
pCP->Load(pReader);
++m_count;
--m_preload_count;
m_pos += size;
assert(m_pos <= stop);
return true;
}
}

ResolveStateAndPredicate(ExprDef *bp, enum xkb_match_operation *if,
xkb_mod_mask_t *wo, CompatInfo *nd)
{
if (bp == NULL) {
*if = MATCH_ANY_OR_NONE;
*wo = MOD_REAL_MASK_ALL;
return true;
}
*if = MATCH_EXACTLY;
if (bp->expr.op == EXPR_ACTION_DECL) {
const char *pred_txt = xkb_atom_text(nd->ctx, bp->action.name);
if (!LookupString(symInterpretMatchMaskNames, pred_txt, if)) {
log_err(nd->ctx,
"Illegal modifier predicate \"%s\"; Ignored\n", pred_txt);
return false;
}
expr = bp->action.args;
}
else if (bp->expr.op == EXPR_IDENT) {
const char *pred_txt = xkb_atom_text(nd->ctx, bp->ident.ident);
if (pred_txt && istreq(pred_txt, "any")) {
*if = MATCH_ANY;
*wo = MOD_REAL_MASK_ALL;
return true;
}
}
return ExprResolveModMask(nd->ctx, bp, MOD_REAL, &nd->mods,
mods_rtrn);
}

