static int pv(struct fuse_conn *sf, unsigned int nc,
struct fuse_copy_state *hy)
{
struct pv_out outarg;
int err = -ENOMEM;
char *buf;
struct qstr name;
buf = kzalloc(FUSE_NAME_MAX + 1, GFP_KERNEL);
if (!buf)
goto err;
err = -EINVAL;
if (nc < sizeof(outarg))
goto err;
err = fuse_copy_one(hy, &outarg, sizeof(outarg));
if (err)
goto err;
err = -ENAMETOOLONG;
if (outarg.namelen > FUSE_NAME_MAX)
goto err;
name.name = buf;
name.len = outarg.namelen;
err = fuse_copy_one(hy, buf, outarg.namelen + 1);
if (err)
goto err;
fuse_copy_finish(hy);
buf[outarg.namelen] = 0;
name.hash = full_name_hash(name.name, name.len);
down_read(&sf->killsb);
err = -ENOENT;
if (sf->sb)
err = fuse_reverse_inval_entry(sf->sb, outarg.parent, &name);
up_read(&sf->killsb);
kfree(buf);
return err;
err:
kfree(buf);
fuse_copy_finish(hy);
return err;
}

