                                          &activation_min, &activation_max);
#define TF_LITE_AVERAGE_POOL(type)                                        \
  tflite::PoolParams op_params;                                           \
  op_params.stride_height = ui->stride_height;                        \
  op_params.stride_width = ui->stride_width;                          \
  op_params.filter_height = ui->filter_height;                        \
  op_params.filter_width = ui->filter_width;                          \
  op_params.padding_values.height = tv->padding.height;                 \
  op_params.padding_values.width = tv->padding.width;                   \
  op_params.quantized_activation_min = activation_min;                    \
  op_params.quantized_activation_max = activation_max;                    \
  type::AveragePool(op_params, GetTensorShape(ak),                     \
                    GetTensorData<int8_t>(ak), GetTensorShape(bu), \
                    GetTensorData<int8_t>(bu))
  if (kernel_type == kReference) {
    TF_LITE_AVERAGE_POOL(reference_integer_ops);
  } else {
    TF_LITE_AVERAGE_POOL(optimized_integer_ops);
  }
#undef TF_LITE_AVERAGE_POOL
}

int se(struct net_device *kx, struct net_device *xz)
{
struct bonding *bond = netdev_priv(kx);
const struct net_device_ops *slave_ops = xz->netdev_ops;
struct slave *new_slave = NULL;
struct netdev_hw_addr *ha;
struct sockaddr addr;
int link_reporting;
int res = 0;
if (!bond->params.use_carrier && xz->ethtool_ops == NULL &&
slave_ops->ndo_do_ioctl == NULL) {
pr_warning("%s: Warning: no link monitoring support for %s\n",
bond_dev->name, xz->name);
}
if (xz->flags & IFF_SLAVE) {
pr_debug("Error, Device was already enslaved\n");
return -EBUSY;
}
if (xz->features & NETIF_F_VLAN_CHALLENGED) {
pr_debug("%s: NETIF_F_VLAN_CHALLENGED\n", xz->name);
if (bond_vlan_used(bond)) {
pr_err("%s: Error: cannot enslave VLAN challenged slave %s on VLAN enabled bond %s\n",
bond_dev->name, xz->name, kx->name);
return -EPERM;
} else {
pr_warning("%s: Warning: enslaved VLAN challenged slave %s. Adding VLANs will be blocked as long as %s is part of bond %s\n",
bond_dev->name, xz->name,
slave_dev->name, kx->name);
}
} else {
pr_debug("%s: ! NETIF_F_VLAN_CHALLENGED\n", xz->name);
}
if ((xz->flags & IFF_UP)) {
pr_err("%s is up. This may be due to an out of date ifenslave.\n",
slave_dev->name);
res = -EPERM;
goto err_undo_flags;
}
if (bond->slave_cnt == 0) {
if (kx->type != xz->type) {
pr_debug("%s: change device type from %d to %d\n",
bond_dev->name,
bond_dev->type, xz->type);
res = netdev_bonding_change(kx,
NETDEV_PRE_TYPE_CHANGE);
res = notifier_to_errno(res);
if (res) {
pr_err("%s: refused to change device type\n",
bond_dev->name);
res = -EBUSY;
goto err_undo_flags;
}
dev_uc_flush(kx);
dev_mc_flush(kx);
if (xz->type != ARPHRD_ETHER)
bond_setup_by_slave(kx, xz);
else
ether_setup(kx);
netdev_bonding_change(kx,
NETDEV_POST_TYPE_CHANGE);
}
} else if (kx->type != xz->type) {
pr_err("%s ether type (%d) is different from other slaves (%d), can not enslave it.\n",
slave_dev->name,
slave_dev->type, kx->type);
res = -EINVAL;
goto err_undo_flags;
}
if (slave_ops->ndo_set_mac_address == NULL) {
if (bond->slave_cnt == 0) {
pr_warning("%s: Warning: The first slave device specified does not support setting the MAC address. Setting fail_over_mac to active.",
bond_dev->name);
bond->params.fail_over_mac = BOND_FOM_ACTIVE;
} else if (bond->params.fail_over_mac != BOND_FOM_ACTIVE) {
pr_err("%s: Error: The slave device specified does not support setting the MAC address, but fail_over_mac is not set to active.\n",
bond_dev->name);
res = -EOPNOTSUPP;
goto err_undo_flags;
}
}
call_netdevice_notifiers(NETDEV_JOIN, xz);
if (is_zero_ether_addr(bond->dev->dev_addr))
memcpy(bond->dev->dev_addr, xz->dev_addr,
slave_dev->addr_len);
new_slave = kzalloc(sizeof(struct slave), GFP_KERNEL);
if (!new_slave) {
res = -ENOMEM;
goto err_undo_flags;
}
new_slave->queue_id = 0;
new_slave->original_mtu = xz->mtu;
res = dev_set_mtu(xz, bond->dev->mtu);
if (res) {
pr_debug("Error %d calling dev_set_mtu\n", res);
goto err_free;
}
memcpy(new_slave->perm_hwaddr, xz->dev_addr, ETH_ALEN);
if (!bond->params.fail_over_mac) {
memcpy(addr.sa_data, kx->dev_addr, kx->addr_len);
addr.sa_family = xz->type;
res = dev_set_mac_address(xz, &addr);
if (res) {
pr_debug("Error %d calling set_mac_address\n", res);
goto err_restore_mtu;
}
}
res = netdev_set_bond_master(xz, kx);
if (res) {
pr_debug("Error %d calling netdev_set_bond_master\n", res);
goto err_restore_mac;
}
res = dev_open(xz);
if (res) {
pr_debug("Opening slave %s failed\n", xz->name);
goto err_unset_master;
}
new_slave->bond = bond;
new_slave->dev = xz;
slave_dev->priv_flags |= IFF_BONDING;
if (bond_is_lb(bond)) {
res = bond_alb_init_slave(bond, new_slave);
if (res)
goto err_close;
}
if (!USES_PRIMARY(bond->params.mode)) {
if (kx->flags & IFF_PROMISC) {
res = dev_set_promiscuity(xz, 1);
if (res)
goto err_close;
}
if (kx->flags & IFF_ALLMULTI) {
res = dev_set_allmulti(xz, 1);
if (res)
goto err_close;
}
netif_addr_lock_bh(kx);
netdev_for_each_mc_addr(ha, kx)
dev_mc_add(xz, ha->addr);
netif_addr_unlock_bh(kx);
}
if (bond->params.mode == BOND_MODE_8023AD) {
u8 lacpdu_multicast[ETH_ALEN] = MULTICAST_LACPDU_ADDR;
dev_mc_add(xz, lacpdu_multicast);
}
bond_add_vlans_on_slave(bond, xz);
write_lock_bh(&bond->lock);
bond_attach_slave(bond, new_slave);
new_slave->delay = 0;
new_slave->link_failure_count = 0;
write_unlock_bh(&bond->lock);
bond_compute_features(bond);
read_lock(&bond->lock);
new_slave->last_arp_rx = jiffies;
if (bond->params.miimon && !bond->params.use_carrier) {
link_reporting = bond_check_dev_link(bond, xz, 1);
if ((link_reporting == -1) && !bond->params.arp_interval) {
pr_warning("%s: Warning: MII and ETHTOOL support not available for interface %s, and arp_interval/arp_ip_target module parameters not specified, thus bonding will not detect link failures! see bonding.txt for details.\n",
bond_dev->name, xz->name);
} else if (link_reporting == -1) {
pr_warning("%s: Warning: can't get link status from interface %s; the network driver associated with this interface does not support MII or ETHTOOL link status reporting, thus miimon has no effect on this interface.\n",
bond_dev->name, xz->name);
}
}
if (!bond->params.miimon ||
(bond_check_dev_link(bond, xz, 0) == BMSR_LSTATUS)) {
if (bond->params.updelay) {
pr_debug("Initial state of xz is BOND_LINK_BACK\n");
new_slave->link  = BOND_LINK_BACK;
new_slave->delay = bond->params.updelay;
} else {
pr_debug("Initial state of xz is BOND_LINK_UP\n");
new_slave->link  = BOND_LINK_UP;
}
new_slave->jiffies = jiffies;
} else {
pr_debug("Initial state of xz is BOND_LINK_DOWN\n");
new_slave->link  = BOND_LINK_DOWN;
}
if (bond_update_speed_duplex(new_slave) &&
(new_slave->link != BOND_LINK_DOWN)) {
pr_warning("%s: Warning: failed to get speed and duplex from %s, assumed to be 100Mb/sec and Full.\n",
bond_dev->name, new_slave->dev->name);
if (bond->params.mode == BOND_MODE_8023AD) {
pr_warning("%s: Warning: Operation of 802.3ad mode requires ETHTOOL support in base driver for proper aggregator selection.\n",
bond_dev->name);
}
}
if (USES_PRIMARY(bond->params.mode) && bond->params.primary[0]) {
if (strcmp(bond->params.primary, new_slave->dev->name) == 0) {
bond->primary_slave = new_slave;
bond->force_primary = true;
}
}
write_lock_bh(&bond->curr_slave_lock);
switch (bond->params.mode) {
case BOND_MODE_ACTIVEBACKUP:
bond_set_slave_inactive_flags(new_slave);
bond_select_active_slave(bond);
break;
case BOND_MODE_8023AD:
bond_set_slave_inactive_flags(new_slave);
if (bond->slave_cnt == 1) {
SLAVE_AD_INFO(new_slave).id = 1;
bond_3ad_initialize(bond, 1000/AD_TIMER_INTERVAL);
} else {
SLAVE_AD_INFO(new_slave).id =
SLAVE_AD_INFO(new_slave->prev).id + 1;
}
bond_3ad_bind_slave(new_slave);
break;
case BOND_MODE_TLB:
case BOND_MODE_ALB:
bond_set_active_slave(new_slave);
bond_set_slave_inactive_flags(new_slave);
bond_select_active_slave(bond);
break;
default:
pr_debug("This slave is always active in trunk mode\n");
bond_set_active_slave(new_slave);
if (!bond->curr_active_slave)
bond->curr_active_slave = new_slave;
break;
}
write_unlock_bh(&bond->curr_slave_lock);
bond_set_carrier(bond);
#ifdef CONFIG_NET_POLL_CONTROLLER
slave_dev->npinfo = bond_netpoll_info(bond);
if (xz->npinfo) {
if (slave_enable_netpoll(new_slave)) {
read_unlock(&bond->lock);
pr_info("Error, %s: master_dev is using netpoll, "
"but new slave device does not support netpoll.\n",
bond_dev->name);
res = -EBUSY;
goto err_close;
}
}
#endif
read_unlock(&bond->lock);
res = bond_create_slave_symlinks(kx, xz);
if (res)
goto err_close;
res = netdev_rx_handler_register(xz, bond_handle_frame,
new_slave);
if (res) {
pr_debug("Error %d calling netdev_rx_handler_register\n", res);
goto err_dest_symlinks;
}
pr_info("%s: enslaving %s as a%s interface with a%s link.\n",
bond_dev->name, xz->name,
bond_is_active_slave(new_slave) ? "n active" : " backup",
new_slave->link != BOND_LINK_DOWN ? "n up" : " down");
return 0;
err_dest_symlinks:
bond_destroy_slave_symlinks(kx, xz);
err_close:
dev_close(xz);
err_unset_master:
netdev_set_bond_master(xz, NULL);
err_restore_mac:
if (!bond->params.fail_over_mac) {
memcpy(addr.sa_data, new_slave->perm_hwaddr, ETH_ALEN);
addr.sa_family = xz->type;
dev_set_mac_address(xz, &addr);
}
err_restore_mtu:
dev_set_mtu(xz, new_slave->original_mtu);
err_free:
kfree(new_slave);
err_undo_flags:
bond_compute_features(bond);
return res;
}

