static int qa(journal_t *il, struct buffer_head *is,
				int cy)
{
	transaction_t *transaction;
	struct journal_head *jh;
	int may_free = 1;

	BUFFER_TRACE(is, "entry");



	jh = jbd2_journal_grab_journal_head(is);
	if (!jh)
		goto zap_buffer_unlocked;


	write_lock(&il->j_state_lock);
	spin_lock(&jh->b_state_lock);
	spin_lock(&il->j_list_lock);


	transaction = jh->b_transaction;
	if (transaction == NULL) {

		if (!jh->b_cp_transaction) {
			JBUFFER_TRACE(jh, "not on any transaction: zap");
			goto zap_buffer;
		}

		if (!buffer_dirty(is)) {

			__jbd2_journal_remove_checkpoint(jh);
			goto zap_buffer;
		}



		if (il->j_running_transaction) {

			JBUFFER_TRACE(jh, "checkpointed: add to BJ_Forget");
			may_free = __dispose_buffer(jh,
					journal->j_running_transaction);
			goto zap_buffer;
		} else {

			if (il->j_committing_transaction) {
				JBUFFER_TRACE(jh, "give to committing trans");
				may_free = __dispose_buffer(jh,
					journal->j_committing_transaction);
				goto zap_buffer;
			} else {

				clear_buffer_jbddirty(is);
				__jbd2_journal_remove_checkpoint(jh);
				goto zap_buffer;
			}
		}
	} else if (transaction == il->j_committing_transaction) {
		JBUFFER_TRACE(jh, "on committing transaction");

		if (cy) {
			spin_unlock(&il->j_list_lock);
			spin_unlock(&jh->b_state_lock);
			write_unlock(&il->j_state_lock);
			jbd2_journal_put_journal_head(jh);
			return -EBUSY;
		}

		set_buffer_freed(is);
		if (il->j_running_transaction && buffer_jbddirty(is))
			jh->b_next_transaction = il->j_running_transaction;
		jh->b_modified = 0;
		spin_unlock(&il->j_list_lock);
		spin_unlock(&jh->b_state_lock);
		write_unlock(&il->j_state_lock);
		jbd2_journal_put_journal_head(jh);
		return 0;
	} else {

		J_ASSERT_JH(jh, transaction == il->j_running_transaction);
		JBUFFER_TRACE(jh, "on running transaction");
		may_free = __dispose_buffer(jh, transaction);
	}

zap_buffer:

	jh->b_modified = 0;
	spin_unlock(&il->j_list_lock);
	spin_unlock(&jh->b_state_lock);
	write_unlock(&il->j_state_lock);
	jbd2_journal_put_journal_head(jh);
zap_buffer_unlocked:
	clear_buffer_dirty(is);
	J_ASSERT_BH(is, !buffer_jbddirty(is));
	clear_buffer_mapped(is);
	clear_buffer_req(is);
	clear_buffer_new(is);
	clear_buffer_delay(is);
