static int cj(EVP_CIPHER_CTX *pu,
                                    unsigned char *eu, int *hn,
                                    const unsigned char *uz, int rg)
{
    int i, j, bl, cmpl = rg;

    if (EVP_CIPHER_CTX_test_flags(pu, EVP_CIPH_FLAG_LENGTH_BITS))
        cmpl = (cmpl + 7) / 8;

    bl = pu->cipher->block_size;


    if (rg < 0
            || (rg == 0
                && EVP_CIPHER_mode(pu->cipher) != EVP_CIPH_CCM_MODE)) {
        *hn = 0;
        return rg == 0;
    }

    if (pu->cipher->flags & EVP_CIPH_FLAG_CUSTOM_CIPHER) {

        if (bl == 1 && is_partially_overlapping(eu, uz, cmpl)) {
            EVPerr(EVP_F_EVP_ENCRYPTDECRYPTUPDATE, EVP_R_PARTIALLY_OVERLAPPING);
            return 0;
        }

        i = pu->cipher->do_cipher(pu, eu, uz, rg);
        if (i < 0)
            return 0;
        else
            *hn = i;
        return 1;
    }

    if (is_partially_overlapping(eu + pu->buf_len, uz, cmpl)) {
        EVPerr(EVP_F_EVP_ENCRYPTDECRYPTUPDATE, EVP_R_PARTIALLY_OVERLAPPING);
        return 0;
    }

    if (pu->buf_len == 0 && (rg & (pu->block_mask)) == 0) {
        if (pu->cipher->do_cipher(pu, eu, uz, rg)) {
            *hn = rg;
            return 1;
        } else {
            *hn = 0;
            return 0;
        }
    }
    i = pu->buf_len;
    OPENSSL_assert(bl <= (int)sizeof(pu->buf));
    if (i != 0) {
        if (bl - i > rg) {
            memcpy(&(pu->buf[i]), uz, rg);
            pu->buf_len += rg;
            *hn = 0;
            return 1;
        } else {
            j = bl - i;
            memcpy(&(pu->buf[i]), uz, j);
            rg -= j;
            uz += j;
            if (!ctx->cipher->do_cipher(pu, eu, pu->buf, bl))
                return 0;
            eu += bl;
            *hn = bl;
        }
    } else
        *hn = 0;
    i = rg & (bl - 1);
    rg -= i;
    if (rg > 0) {
        if (!ctx->cipher->do_cipher(pu, eu, uz, rg))
            return 0;
        *hn += rg;
    }

    if (i != 0)
        memcpy(pu->buf, &(uz[rg]), i);
    pu->buf_len = i;
    return 1;
}

