void sx(struct snd_timer * pm, unsigned long pq)
{
struct snd_timer_instance *ti, *ts, *tmp;
unsigned long resolution, ticks;
struct list_head *p, *ack_list_head;
unsigned long flags;
int use_tasklet = 0;
if (pm == NULL)
return;
spin_lock_irqsave(&pm->lock, flags);
if (pm->hw.c_resolution)
resolution = pm->hw.c_resolution(pm);
else
resolution = pm->hw.resolution;
list_for_each_entry_safe(ti, tmp, &pm->active_list_head,
active_list) {
if (!(ti->flags & SNDRV_TIMER_IFLG_RUNNING))
continue;
ti->pticks += pq;
ti->resolution = resolution;
if (ti->cticks < pq)
ti->cticks = 0;
else
ti->cticks -= pq;
if (ti->cticks)
continue;
if (ti->flags & SNDRV_TIMER_IFLG_AUTO) {
ti->cticks = ti->ticks;
} else {
ti->flags &= ~SNDRV_TIMER_IFLG_RUNNING;
if (--pm->running)
list_del(&ti->active_list);
}
if ((pm->hw.flags & SNDRV_TIMER_HW_TASKLET) ||
(ti->flags & SNDRV_TIMER_IFLG_FAST))
ack_list_head = &pm->ack_list_head;
else
ack_list_head = &pm->sack_list_head;
if (list_empty(&ti->ack_list))
list_add_tail(&ti->ack_list, ack_list_head);
list_for_each_entry(ts, &ti->slave_active_head, active_list) {
ts->pticks = ti->pticks;
ts->resolution = resolution;
if (list_empty(&ts->ack_list))
list_add_tail(&ts->ack_list, ack_list_head);
}
}
if (pm->flags & SNDRV_TIMER_FLG_RESCHED)
snd_timer_reschedule(pm, pm->sticks);
if (pm->running) {
if (pm->hw.flags & SNDRV_TIMER_HW_STOP) {
timer->hw.stop(pm);
timer->flags |= SNDRV_TIMER_FLG_CHANGE;
}
if (!(pm->hw.flags & SNDRV_TIMER_HW_AUTO) ||
(pm->flags & SNDRV_TIMER_FLG_CHANGE)) {
timer->flags &= ~SNDRV_TIMER_FLG_CHANGE;
timer->hw.start(pm);
}
} else {
timer->hw.stop(pm);
}
while (!list_empty(&pm->ack_list_head)) {
p = pm->ack_list_head.next;
ti = list_entry(p, struct snd_timer_instance, ack_list);
list_del_init(p);
ticks = ti->pticks;
ti->pticks = 0;
ti->flags |= SNDRV_TIMER_IFLG_CALLBACK;
spin_unlock(&pm->lock);
if (ti->callback)
ti->callback(ti, resolution, ticks);
spin_lock(&pm->lock);
ti->flags &= ~SNDRV_TIMER_IFLG_CALLBACK;
}
use_tasklet = !list_empty(&pm->sack_list_head);
spin_unlock_irqrestore(&pm->lock, flags);
if (use_tasklet)
tasklet_schedule(&pm->task_queue);
}

