__u32 bo(__be32 ie, __be32 wq,
__be16 tv, __be16 dw)
{
__u32 seq;
__u32 hash[4];
struct keydata *keyptr = get_keyptr();
hash[0] = (__force u32)ie;
hash[1] = (__force u32)wq;
hash[2] = ((__force u16)tv << 16) + (__force u16)dw;
hash[3] = keyptr->secret[11];
seq = half_md4_transform(hash, keyptr->secret) & HASH_MASK;
seq += keyptr->count;
seq += ktime_to_ns(ktime_get_real()) >> 6;
return seq;
}

