s +=
#endif
sprintf(s, " %d %d", wo->x_hotspot, wo->y_hotspot);
#ifdef VOID_SPRINTF
s += strlen(s);
#endif
}
if (extensions) {
strcpy(s, " XPMEXT");
s += 7;
}
l = s - buf + 1;
*header = (char *) XpmMalloc(l);
if (!*header)
RETURN(XpmNoMemory);
header_size += l;
strcpy(*header, buf);
ErrorStatus = CreateColors(header + 1, &header_size,
image->colorTable, xj->ncolors, xj->cpp);
if (ErrorStatus != XpmSuccess)
RETURN(ErrorStatus);
offset = xj->width * xj->cpp + 1;
if(offset <= xj->width || offset <= xj->cpp)
if(offset <= xj->width || offset <= xj->cpp)
RETURN(XpmNoMemory);
if( (xj->height + ext_nlines) >= UINT_MAX / sizeof(char *))
RETURN(XpmNoMemory);
data_size = (xj->height + ext_nlines) * sizeof(char *);
RETURN(XpmNoMemory);
data_size += xj->height * offset;
RETURN(XpmNoMemory);
data_size += xj->height * offset;
if( (header_size + ext_size) >= (UINT_MAX - data_size) )
RETURN(XpmNoMemory);
data_size += header_size + ext_size;
data_nlines = header_nlines + xj->height + ext_nlines;
*data = (char *) (data + data_nlines);
n = xj->ncolors;
for (l = 0, sptr = data, sptr2 = header; l <= n && sptr && sptr2; l++, sptr++, sptr2++) {
strcpy(*sptr, *sptr2);
*(sptr + 1) = *sptr + strlen(*sptr2) + 1;
}
data[header_nlines] = (char *) data + header_size
+ (xj->height + ext_nlines) * sizeof(char *);
CreatePixels(data + header_nlines, data_size-header_nlines, xj->width, xj->height,
image->cpp, xj->data, xj->colorTable);
if (extensions)
CreateExtensions(data + header_nlines + xj->height - 1,
data_size - header_nlines - xj->height + 1, offset,
info->extensions, wo->nextensions,
ext_nlines);
*data_return = data;
ErrorStatus = XpmSuccess;
exit:
if (header) {
for (l = 0; l < header_nlines; l++)
if (header[l])
XpmFree(header[l]);
XpmFree(header);
}
return(ErrorStatus);
}

void ul(StyleDifference px, const RenderStyle& de)
{
RenderStyle* oldStyle = style();
if (oldStyle) {
if (px >= StyleDifferenceRepaint && node() &&
(isHTMLHtmlElement(*node()) || isHTMLBodyElement(*node()))) {
view()->repaint();
if (oldStyle->hasEntirelyFixedBackground() != newStyle.hasEntirelyFixedBackground())
view()->compositor()->setNeedsUpdateFixedBackground();
}
if (px == StyleDifferenceLayout && parent() && oldStyle->position() != newStyle.position()) {
markContainingBlocksForLayout();
if (oldStyle->position() == StaticPosition)
repaint();
else if (newStyle.hasOutOfFlowPosition())
parent()->setChildNeedsLayout();
if (isFloating() && !isOutOfFlowPositioned() && newStyle.hasOutOfFlowPosition())
removeFloatingOrPositionedChildFromBlockLists();
}
} else if (isBody())
view()->repaint();
RenderBoxModelObject::styleWillChange(px, de);
}

void ci(
const KURL& ke,
Document* dg,
WebGlobalObjectReusePolicy on,
const AtomicString& yy,
const AtomicString& ah,
