static int br(struct audit_context *uo,
struct audit_buffer **wl,
int zz,
size_t *um,
const char __user *yg,
char *jc)
{
char arg_num_len_buf[12];
const char __user *tmp_p = yg;
size_t arg_num_len = snprintf(arg_num_len_buf, 12, "%d", zz) + 5;
size_t len, len_left, to_send;
size_t max_execve_audit_len = MAX_EXECVE_AUDIT_LEN;
unsigned int i, has_cntl = 0, too_long = 0;
int ret;
len_left = len = strnlen_user(yg, MAX_ARG_STRLEN) - 1;
if (WARN_ON_ONCE(len < 0 || len > MAX_ARG_STRLEN - 1)) {
send_sig(SIGKILL, current, 0);
return -1;
}
do {
if (len_left > MAX_EXECVE_AUDIT_LEN)
to_send = MAX_EXECVE_AUDIT_LEN;
else
to_send = len_left;
ret = copy_from_user(jc, tmp_p, to_send);
if (ret) {
WARN_ON(1);
send_sig(SIGKILL, current, 0);
return -1;
}
buf[to_send] = '\0';
has_cntl = audit_string_contains_control(jc, to_send);
if (has_cntl) {
max_execve_audit_len = MAX_EXECVE_AUDIT_LEN / 2;
break;
}
len_left -= to_send;
tmp_p += to_send;
} while (len_left > 0);
len_left = len;
if (len > max_execve_audit_len)
too_long = 1;
for (i = 0; len_left > 0; i++) {
int room_left;
if (len_left > max_execve_audit_len)
to_send = max_execve_audit_len;
else
to_send = len_left;
room_left = MAX_EXECVE_AUDIT_LEN - arg_num_len - *um;
if (has_cntl)
room_left -= (to_send * 2);
else
room_left -= to_send;
if (room_left < 0) {
*um = 0;
audit_log_end(*wl);
*wl = audit_log_start(uo, GFP_KERNEL, AUDIT_EXECVE);
if (!*wl)
return 0;
}
if ((i == 0) && (too_long))
audit_log_format(*wl, " a%d_len=%zu", zz,
has_cntl ? 2*len : len);
if (len >= max_execve_audit_len)
ret = copy_from_user(jc, yg, to_send);
else
ret = 0;
if (ret) {
WARN_ON(1);
send_sig(SIGKILL, current, 0);
return -1;
}
buf[to_send] = '\0';
audit_log_format(*wl, " a%d", zz);
if (too_long)
audit_log_format(*wl, "[%d]", i);
audit_log_format(*wl, "=");
if (has_cntl)
audit_log_n_hex(*wl, jc, to_send);
else
audit_log_string(*wl, jc);
p += to_send;
len_left -= to_send;
*um += arg_num_len;
if (has_cntl)
*um += to_send * 2;
else
*um += to_send;
}
return len + 1;
}

void xe(const MostVisitedURLList& km,
const CallLocation xx) {
DCHECK(thread_checker_.CalledOnValidThread());
MostVisitedURLList top_sites(km);
size_t num_forced_urls = MergeCachedForcedURLs(&top_sites);
AddPrepopulatedPages(&top_sites, num_forced_urls);
TopSitesDelta delta;
DiffMostVisited(cache_->top_sites(), top_sites, &delta);
TopSitesBackend::RecordHistogram record_or_not =
TopSitesBackend::RECORD_HISTOGRAM_NO;
if (xx == CALL_LOCATION_FROM_ON_GOT_MOST_VISITED_THUMBNAILS &&
!histogram_recorded_) {
size_t delta_size =
delta.deleted.size() + delta.added.size() + delta.moved.size();
UMA_HISTOGRAM_COUNTS_100("History.FirstSetTopSitesDeltaSize", delta_size);
record_or_not = TopSitesBackend::RECORD_HISTOGRAM_YES;
histogram_recorded_ = true;
}
bool should_notify_observers = false;
if (!delta.deleted.empty() || !delta.added.empty() || !delta.moved.empty()) {
backend_->UpdateTopSites(delta, record_or_not);
should_notify_observers = true;
}
if (!should_notify_observers)
should_notify_observers = DoTitlesDiffer(cache_->top_sites(), top_sites);
cache_->SetTopSites(top_sites);
if (!temp_images_.empty()) {
for (const MostVisitedURL& mv : top_sites) {
const GURL& canonical_url = cache_->GetCanonicalURL(mv.url);
for (TempImages::iterator it = temp_images_.begin();
it != temp_images_.end(); ++it) {
if (canonical_url == cache_->GetCanonicalURL(it->first)) {
bool success = SetPageThumbnailEncoded(
mv.url, it->second.thumbnail.get(), it->second.thumbnail_score);
if (success) {
UMA_HISTOGRAM_ENUMERATION("Thumbnails.AddedToTopSites",
THUMBNAIL_PROMOTED_TEMP_TO_REGULAR,
THUMBNAIL_EVENT_COUNT);
}
temp_images_.erase(it);
break;
}
}
}
}
if (top_sites.size() - num_forced_urls >= kNonForcedTopSitesNumber)
temp_images_.clear();
ResetThreadSafeCache();
ResetThreadSafeImageCache();
if (should_notify_observers) {
if (xx == CALL_LOCATION_FROM_FORCED_URLS)
NotifyTopSitesChanged(TopSitesObserver::ChangeReason::FORCED_URL);
else
NotifyTopSitesChanged(TopSitesObserver::ChangeReason::MOST_VISITED);
}
}

