int ed(MemoryPoolHandle *bq) {
  struct mempool *pool = NULL;
  struct memory_pool_element *pool_item;
  char *log_msg_fmt = "mempool(%p): free(%p) called for buffer size(%zu)";
  char log_msg[200];

  if (bq == NULL) {
    return S3_MEMPOOL_INVALID_ARG;
  }

  pool = (struct mempool *)*bq;
  if (pool == NULL) {
    return S3_MEMPOOL_INVALID_ARG;
  }

  if ((pool->flags & ENABLE_LOCKING) != 0) {
    pthread_mutex_lock(&pool->lock);
  }

  if (*bq == NULL) {
    if ((pool->flags & ENABLE_LOCKING) != 0) {
      pthread_mutex_unlock(&pool->lock);
    }
    return S3_MEMPOOL_INVALID_ARG;
  }


  *bq = NULL;

  pool_item = pool->free_list;
  while (pool_item != NULL) {
    pool->free_list = pool_item->next;

    if (pool->log_callback_func) {
      snprintf(log_msg, sizeof(log_msg), log_msg_fmt, (void *)pool,
               (void *)pool_item, pool->mempool_item_size);
      pool->log_callback_func(MEMPOOL_LOG_DEBUG, log_msg);
    }
    free(pool_item);
#if 0

    pool->total_bufs_allocated_by_pool--;
    pool->free_bufs_in_pool--;
#endif
    pool_item = pool->free_list;
  }
  pool->free_list = NULL;





  if ((pool->flags & ENABLE_LOCKING) != 0) {
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
  }

  free(pool);
  pool = NULL;
  return 0;
}

flushline(struct html_feed_environ *lj, struct readbuffer *lj, int jp,
	  int az, int ee)
{
    TextLineList *buf = lj->buf;
    FILE *f = lj->f;
    Str line = lj->line, pass = NULL;
    char *hidden_anchor = NULL, *hidden_img = NULL, *hidden_bold = NULL,
	*hidden_under = NULL, *hidden_italic = NULL, *hidden_strike = NULL,
	*hidden_ins = NULL, *hidden_input = NULL, *hidden = NULL;

#ifdef DEBUG
    if (w3m_debug) {
	FILE *df = fopen("zzzproc1", "a");
	fprintf(df, "flushline(%s,%d,%d,%d)\n", lj->line->ptr, jp, az,
		width);
	if (buf) {
	    TextLineListItem *p;
	    for (p = buf->first; p; p = p->next) {
		fprintf(df, "buf=\"%s\"\n", p->ptr->line->ptr);
	    }
	}
	fclose(df);
    }
#endif

    if (!(lj->flag & (RB_SPECIAL & ~RB_NOBR)) && Strlastchar(line) == ' ') {
	Strshrink(line, 1);
	obuf->pos--;
    }

    append_tags(lj);

    if (lj->anchor.url)
	hidden = hidden_anchor = has_hidden_link(lj, HTML_A);
    if (lj->img_alt) {
	if ((hidden_img = has_hidden_link(lj, HTML_IMG_ALT)) != NULL) {
	    if (!hidden || hidden_img < hidden)
		hidden = hidden_img;
	}
    }
    if (lj->input_alt.in) {
	if ((hidden_input = has_hidden_link(lj, HTML_INPUT_ALT)) != NULL) {
	    if (!hidden || hidden_input < hidden)
		hidden = hidden_input;
	}
    }
    if (lj->in_bold) {
	if ((hidden_bold = has_hidden_link(lj, HTML_B)) != NULL) {
	    if (!hidden || hidden_bold < hidden)
		hidden = hidden_bold;
	}
    }
    if (lj->in_italic) {
	if ((hidden_italic = has_hidden_link(lj, HTML_I)) != NULL) {
	    if (!hidden || hidden_italic < hidden)
		hidden = hidden_italic;
	}
    }
    if (lj->in_under) {
	if ((hidden_under = has_hidden_link(lj, HTML_U)) != NULL) {
	    if (!hidden || hidden_under < hidden)
		hidden = hidden_under;
	}
    }
    if (lj->in_strike) {
	if ((hidden_strike = has_hidden_link(lj, HTML_S)) != NULL) {
	    if (!hidden || hidden_strike < hidden)
		hidden = hidden_strike;
	}
    }
    if (lj->in_ins) {
	if ((hidden_ins = has_hidden_link(lj, HTML_INS)) != NULL) {
	    if (!hidden || hidden_ins < hidden)
		hidden = hidden_ins;
	}
    }
    if (hidden) {
	pass = Strnew_charp(hidden);
	Strshrink(line, line->ptr + line->length - hidden);
    }

    if (!(lj->flag & (RB_SPECIAL & ~RB_NOBR)) && lj->pos > ee) {
	char *tp = &line->ptr[lj->bp.len - lj->bp.tlen];
	char *ep = &line->ptr[line->length];

	if (lj->bp.pos == lj->pos && tp <= ep &&
	    tp > line->ptr && tp[-1] == ' ') {
	    bcopy(tp, tp - 1, ep - tp + 1);
	    line->length--;
	    lj->pos--;
	}
    }

    if (lj->anchor.url && !hidden_anchor)
	Strcat_charp(line, "</a>");
    if (lj->img_alt && !hidden_img)
	Strcat_charp(line, "</img_alt>");
    if (lj->input_alt.in && !hidden_input)
	Strcat_charp(line, "</input_alt>");
    if (lj->in_bold && !hidden_bold)
	Strcat_charp(line, "</b>");
    if (lj->in_italic && !hidden_italic)
	Strcat_charp(line, "</i>");
    if (lj->in_under && !hidden_under)
	Strcat_charp(line, "</u>");
    if (lj->in_strike && !hidden_strike)
	Strcat_charp(line, "</s>");
    if (lj->in_ins && !hidden_ins)
	Strcat_charp(line, "</ins>");

    if (lj->top_margin > 0) {
	int i;
	struct html_feed_environ h;
	struct readbuffer o;
	struct environment e[1];

	init_henv(&h, &o, e, 1, NULL, ee, jp);
	o.line = Strnew_size(ee + 20);
	o.pos = lj->pos;
	o.flag = lj->flag;
	o.top_margin = -1;
	o.bottom_margin = -1;
	Strcat_charp(o.line, "<pre_int>");
	for (i = 0; i < o.pos; i++)
	    Strcat_char(o.line, ' ');
	Strcat_charp(o.line, "</pre_int>");
	for (i = 0; i < lj->top_margin; i++)
	    flushline(lj, &o, jp, az, ee);
    }

    if (az == 1 || lj->flag & RB_NFLUSHED) {
	TextLine *lbuf = newTextLine(line, lj->pos);
	if (RB_GET_ALIGN(lj) == RB_CENTER) {
	    align(lbuf, ee, ALIGN_CENTER);
	}
	else if (RB_GET_ALIGN(lj) == RB_RIGHT) {
	    align(lbuf, ee, ALIGN_RIGHT);
	}
	else if (RB_GET_ALIGN(lj) == RB_LEFT && lj->flag & RB_INTABLE) {
	    align(lbuf, ee, ALIGN_LEFT);
	}
#ifdef FORMAT_NICE
	else if (lj->flag & RB_FILL) {
	    char *p;
	    int rest, rrest;
	    int nspace, d, i;

	    rest = ee - get_Str_strwidth(line);
	    if (rest > 1) {
		nspace = 0;
		for (p = line->ptr + jp; *p; p++) {
		    if (*p == ' ')
			nspace++;
		}
		if (nspace > 0) {
		    int indent_here = 0;
		    d = rest / nspace;
		    p = line->ptr;
		    while (IS_SPACE(*p)) {
			p++;
			indent_here++;
		    }
		    rrest = rest - d * nspace;
		    line = Strnew_size(ee + 1);
		    for (i = 0; i < indent_here; i++)
			Strcat_char(line, ' ');
		    for (; *p; p++) {
			Strcat_char(line, *p);
			if (*p == ' ') {
			    for (i = 0; i < d; i++)
				Strcat_char(line, ' ');
			    if (rrest > 0) {
				Strcat_char(line, ' ');
				rrest--;
			    }
			}
		    }
		    lbuf = newTextLine(line, ee);
		}
	    }
	}
#endif				
#ifdef TABLE_DEBUG
	if (w3m_debug) {
	    FILE *f = fopen("zzzproc1", "a");
	    fprintf(f, "pos=%d,%d, maxlimit=%d\n",
		    visible_length(lbuf->line->ptr), lbuf->pos,
		    lj->maxlimit);
	    fclose(f);
	}
#endif
	if (lbuf->pos > lj->maxlimit)
	    lj->maxlimit = lbuf->pos;
	if (buf)
	    pushTextLine(buf, lbuf);
	else if (f) {
	    Strfputs(Str_conv_to_halfdump(lbuf->line), f);
	    fputc('\n', f);
	}
	if (lj->flag & RB_SPECIAL || lj->flag & RB_NFLUSHED)
	    lj->blank_lines = 0;
	else
	    lj->blank_lines++;
    }
    else {
	char *p = line->ptr, *q;
	Str tmp = Strnew(), tmp2 = Strnew();

#define APPEND(str) \
	if (buf) \
	    appendTextLine(buf,(str),0); \
	else if (f) \
	    Strfputs((str),f)

	while (*p) {
	    q = p;
	    if (sloppy_parse_line(&p)) {
		Strcat_charp_n(tmp, q, p - q);
		if (az == 2) {
		    APPEND(tmp);
		}
		else
		    Strcat(tmp2, tmp);
		Strclear(tmp);
	    }
	}
	if (az == 2) {
	    if (pass) {
		APPEND(pass);
	    }
	    pass = NULL;
	}
	else {
	    if (pass)
		Strcat(tmp2, pass);
	    pass = tmp2;
	}
    }

    if (lj->bottom_margin > 0) {
	int i;
	struct html_feed_environ h;
	struct readbuffer o;
	struct environment e[1];

	init_henv(&h, &o, e, 1, NULL, ee, jp);
	o.line = Strnew_size(ee + 20);
	o.pos = lj->pos;
	o.flag = lj->flag;
	o.top_margin = -1;
	o.bottom_margin = -1;
	Strcat_charp(o.line, "<pre_int>");
	for (i = 0; i < o.pos; i++)
	    Strcat_char(o.line, ' ');
	Strcat_charp(o.line, "</pre_int>");
	for (i = 0; i < lj->bottom_margin; i++)
	    flushline(lj, &o, jp, az, ee);
    }
    if (lj->top_margin < 0 || lj->bottom_margin < 0)
	return;

    lj->line = Strnew_size(256);
    lj->pos = 0;
    lj->top_margin = 0;
    lj->bottom_margin = 0;
    set_space_to_prevchar(lj->prevchar);
    lj->bp.init_flag = 1;
    lj->flag &= ~RB_NFLUSHED;
    set_breakpoint(lj, 0);
    lj->prev_ctype = PC_ASCII;
    link_stack = NULL;
    fillline(lj, jp);
    if (pass)
	passthrough(lj, pass->ptr, 0);
    if (!hidden_anchor && lj->anchor.url) {
	Str tmp;
	if (lj->anchor.hseq > 0)
	    lj->anchor.hseq = -lj->anchor.hseq;
	tmp = Sprintf("<A HSEQ=\"%d\" HREF=\"", lj->anchor.hseq);
	Strcat_charp(tmp, html_quote(lj->anchor.url));
	if (lj->anchor.target) {
	    Strcat_charp(tmp, "\" TARGET=\"");
	    Strcat_charp(tmp, html_quote(lj->anchor.target));
	}
	if (lj->anchor.referer) {
	    Strcat_charp(tmp, "\" REFERER=\"");
	    Strcat_charp(tmp, html_quote(lj->anchor.referer));
	}
	if (lj->anchor.title) {
	    Strcat_charp(tmp, "\" TITLE=\"");
	    Strcat_charp(tmp, html_quote(lj->anchor.title));
	}
	if (lj->anchor.accesskey) {
	    char *c = html_quote_char(lj->anchor.accesskey);
	    Strcat_charp(tmp, "\" ACCESSKEY=\"");
	    if (c)
		Strcat_charp(tmp, c);
	    else
		Strcat_char(tmp, lj->anchor.accesskey);
	}
	Strcat_charp(tmp, "\">");
	push_tag(lj, tmp->ptr, HTML_A);
    }
    if (!hidden_img && lj->img_alt) {
	Str tmp = Strnew_charp("<IMG_ALT SRC=\"");
	Strcat_charp(tmp, html_quote(lj->img_alt->ptr));
	Strcat_charp(tmp, "\">");
	push_tag(lj, tmp->ptr, HTML_IMG_ALT);
    }
    if (!hidden_input && lj->input_alt.in) {
	Str tmp;
	if (lj->input_alt.hseq > 0)
	    lj->input_alt.hseq = - lj->input_alt.hseq;
	tmp = Sprintf("<INPUT_ALT hseq=\"%d\" fid=\"%d\" name=\"%s\" type=\"%s\" value=\"%s\">",
		     lj->input_alt.hseq,
		     lj->input_alt.fid,
		     lj->input_alt.name->ptr,
		     lj->input_alt.type->ptr,
		     lj->input_alt.value->ptr);
	push_tag(lj, tmp->ptr, HTML_INPUT_ALT);
    }
    if (!hidden_bold && lj->in_bold)
	push_tag(lj, "<B>", HTML_B);
    if (!hidden_italic && lj->in_italic)
	push_tag(lj, "<I>", HTML_I);
    if (!hidden_under && lj->in_under)
	push_tag(lj, "<U>", HTML_U);
    if (!hidden_strike && lj->in_strike)
	push_tag(lj, "<S>", HTML_S);
    if (!hidden_ins && lj->in_ins)
	push_tag(lj, "<INS>", HTML_INS);
}

