    if(phase!=PROTOCOL_EARLY)
        return NULL;
    s_read(wj, wj->local_rfd.fd, buffer, 4) ;
    len=(uint16_t)(((uint16_t)(buffer[2])<<8)|buffer[3]);
    if(len>sizeof buffer-4) {
        s_log(LOG_ERR, "Received block too long");
        throw_exception(wj, 1);
    }
    s_read(wj, wj->local_rfd.fd, buffer+4, len);
    if(buffer[0]!=0x81) { 
        s_log(LOG_ERR, "Client did not send session setup");
        s_write(wj, wj->local_wfd.fd, response_access_denied, 5);
        throw_exception(wj, 1);
    }
    s_write(wj, wj->local_wfd.fd, response_use_ssl, 5);
    return NULL;
}

