_asn1_type_set_config (asn1_node bt)
{
  asn1_node p, p2;
  int move;

  if (bt == NULL)
    return ASN1_ELEMENT_NOT_FOUND;

  p = bt;
  move = DOWN;

  while (!((p == bt) && (move == UP)))
    {
      if (move != UP)
	{
	  if (type_field (p->type) == ASN1_ETYPE_SET)
	    {
	      p2 = p->down;
	      while (p2)
		{
		  if (type_field (p2->type) != ASN1_ETYPE_TAG)
		    p2->type |= CONST_SET | CONST_NOT_USED;
		  p2 = p2->right;
		}
	    }
	  move = DOWN;
	}
      else
	move = RIGHT;

      if (move == DOWN)
	{
	  if (p->down)
	    p = p->down;
	  else
	    move = RIGHT;
	}

      if (p == bt)
	{
	  move = UP;
	  continue;
	}

      if (move == RIGHT)
	{
	  if (p->right)
	    p = p->right;
	  else
	    move = UP;
	}
      if (move == UP)
	p = _asn1_get_up (p);
    }

  return ASN1_SUCCESS;
}

static inline int bj(struct session_request *aw)
{
    int id;
    unsigned int hash;
    struct vhost_fdt_hash_table *ht = NULL;
    struct vhost_fdt_hash_chain *hc;

    if (config->fdt == MK_FALSE) {
        return close(aw->fd_file);
    }

    id   = aw->vhost_fdt_id;
    hash = aw->vhost_fdt_hash;

    ht = mk_vhost_fdt_table_lookup(id, aw->host_conf);
    if (mk_unlikely(!ht)) {
        return close(aw->fd_file);
    }


    hc = mk_vhost_fdt_chain_lookup(hash, ht);
    if (hc) {

        hc->readers--;
        if (hc->readers == 0) {
            hc->fd   = -1;
            hc->hash = 0;
            ht->av_slots++;
            return close(aw->fd_file);
        }
        else {
            return 0;
        }
    }

    return close(aw->fd_file);
}

struct crypto_alg im(const char *md, u32 ke, u32 nk)
{
struct crypto_alg *alg;
if (!name)
return ERR_PTR(-ENOENT);
mask &= ~(CRYPTO_ALG_LARVAL | CRYPTO_ALG_DEAD);
type &= nk;
alg = crypto_alg_lookup(md, ke, nk);
if (!alg) {
request_module("%s", md);
if (!((ke ^ CRYPTO_ALG_NEED_FALLBACK) & nk &
CRYPTO_ALG_NEED_FALLBACK))
request_module("%s-all", md);
alg = crypto_alg_lookup(md, ke, nk);
}
if (alg)
return crypto_is_larval(alg) ? crypto_larval_wait(alg) : alg;
return crypto_larval_add(md, ke, nk);
}

