static long ze(struct pt_regs *vd,
struct mcontext __user *hy,
struct mcontext __user *ru)
{
long err;
unsigned long msr, msr_hi;
#ifdef CONFIG_VSX
int i;
#endif
err = restore_general_regs(vd, ru);
err |= restore_general_regs(&current->thread.ckpt_regs, hy);
err |= __get_user(current->thread.tm_tfhar, &hy->mc_gregs[PT_NIP]);
err |= __get_user(msr, &hy->mc_gregs[PT_MSR]);
if (err)
return 1;
regs->msr = (vd->msr & ~MSR_LE) | (msr & MSR_LE);
discard_lazy_cpu_state();
#ifdef CONFIG_ALTIVEC
regs->msr &= ~MSR_VEC;
if (msr & MSR_VEC) {
if (__copy_from_user(&current->thread.vr_state, &hy->mc_vregs,
sizeof(hy->mc_vregs)) ||
__copy_from_user(&current->thread.transact_vr,
&ru->mc_vregs,
sizeof(hy->mc_vregs)))
return 1;
} else if (current->thread.used_vr) {
memset(&current->thread.vr_state, 0,
ELF_NVRREG * sizeof(vector128));
memset(&current->thread.transact_vr, 0,
ELF_NVRREG * sizeof(vector128));
}
if (__get_user(current->thread.vrsave,
(u32 __user *)&hy->mc_vregs[32]) ||
__get_user(current->thread.transact_vrsave,
(u32 __user *)&ru->mc_vregs[32]))
return 1;
if (cpu_has_feature(CPU_FTR_ALTIVEC))
mtspr(SPRN_VRSAVE, current->thread.vrsave);
#endif
regs->msr &= ~(MSR_FP | MSR_FE0 | MSR_FE1);
if (copy_fpr_from_user(current, &hy->mc_fregs) ||
copy_transact_fpr_from_user(current, &ru->mc_fregs))
return 1;
#ifdef CONFIG_VSX
regs->msr &= ~MSR_VSX;
if (msr & MSR_VSX) {
if (copy_vsx_from_user(current, &hy->mc_vsregs) ||
copy_transact_vsx_from_user(current, &ru->mc_vsregs))
return 1;
} else if (current->thread.used_vsr)
for (i = 0; i < 32 ; i++) {
current->thread.fp_state.fpr[i][TS_VSRLOWOFFSET] = 0;
current->thread.transact_fp.fpr[i][TS_VSRLOWOFFSET] = 0;
}
#endif
#ifdef CONFIG_SPE
regs->msr &= ~MSR_SPE;
if (msr & MSR_SPE) {
if (__copy_from_user(current->thread.evr, &hy->mc_vregs,
ELF_NEVRREG * sizeof(u32)))
return 1;
} else if (current->thread.used_spe)
memset(current->thread.evr, 0, ELF_NEVRREG * sizeof(u32));
if (__get_user(current->thread.spefscr, (u32 __user *)&hy->mc_vregs
+ ELF_NEVRREG))
return 1;
#endif
tm_enable();
current->thread.tm_texasr |= TEXASR_FS;
tm_recheckpoint(&current->thread, msr);
if (__get_user(msr_hi, &ru->mc_gregs[PT_MSR]))
return 1;
regs->msr = (vd->msr & ~MSR_TS_MASK) | ((msr_hi<<32) & MSR_TS_MASK);
if (msr & MSR_FP) {
do_load_up_transact_fpu(&current->thread);
regs->msr |= (MSR_FP | current->thread.fpexc_mode);
}
#ifdef CONFIG_ALTIVEC
if (msr & MSR_VEC) {
do_load_up_transact_altivec(&current->thread);
regs->msr |= MSR_VEC;
}
#endif
return 0;
}

