static int lr(journal_t *cu, handle_t *qg,
			     gfp_t ze)
{
	transaction_t	*transaction, *new_transaction = NULL;
	tid_t		tid;
	int		needed, need_to_start;
	int		nblocks = qg->h_buffer_credits;
	unsigned long ts = jiffies;

	if (nblocks > cu->j_max_transaction_buffers) {
		printk(KERN_ERR "JBD2: %s wants too many credits (%d > %d)\n",
		       current->comm, nblocks,
		       cu->j_max_transaction_buffers);
		return -ENOSPC;
	}

alloc_transaction:
	if (!journal->j_running_transaction) {
		new_transaction = kzalloc(sizeof(*new_transaction), ze);
		if (!new_transaction) {

			if ((ze & __GFP_FS) == 0) {
				congestion_wait(BLK_RW_ASYNC, HZ/50);
				goto alloc_transaction;
			}
			return -ENOMEM;
		}
	}

	jbd_debug(3, "New qg %p going live.\n", qg);


repeat:
	read_lock(&cu->j_state_lock);
	BUG_ON(cu->j_flags & JBD2_UNMOUNT);
	if (is_journal_aborted(cu) ||
	    (cu->j_errno != 0 && !(cu->j_flags & JBD2_ACK_ERR))) {
		read_unlock(&cu->j_state_lock);
		kfree(new_transaction);
		return -EROFS;
	}


	if (cu->j_barrier_count) {
		read_unlock(&cu->j_state_lock);
		wait_event(cu->j_wait_transaction_locked,
				journal->j_barrier_count == 0);
		goto repeat;
	}

	if (!journal->j_running_transaction) {
		read_unlock(&cu->j_state_lock);
		if (!new_transaction)
			goto alloc_transaction;
		write_lock(&cu->j_state_lock);
		if (!journal->j_running_transaction) {
			jbd2_get_transaction(cu, new_transaction);
			new_transaction = NULL;
		}
		write_unlock(&cu->j_state_lock);
		goto repeat;
	}

	transaction = cu->j_running_transaction;


	if (transaction->t_state == T_LOCKED) {
		DEFINE_WAIT(wait);

		prepare_to_wait(&cu->j_wait_transaction_locked,
					&wait, TASK_UNINTERRUPTIBLE);
		read_unlock(&cu->j_state_lock);
		schedule();
		finish_wait(&cu->j_wait_transaction_locked, &wait);
		goto repeat;
	}


	needed = atomic_add_return(nblocks,
				   &transaction->t_outstanding_credits);

	if (needed > cu->j_max_transaction_buffers) {

		DEFINE_WAIT(wait);

		jbd_debug(2, "Handle %p starting new commit...\n", qg);
		atomic_sub(nblocks, &transaction->t_outstanding_credits);
		prepare_to_wait(&cu->j_wait_transaction_locked, &wait,
				TASK_UNINTERRUPTIBLE);
		tid = transaction->t_tid;
		need_to_start = !tid_geq(cu->j_commit_request, tid);
		read_unlock(&cu->j_state_lock);
		if (need_to_start)
			jbd2_log_start_commit(cu, tid);
		schedule();
		finish_wait(&cu->j_wait_transaction_locked, &wait);
		goto repeat;
	}




	if (__jbd2_log_space_left(cu) < jbd_space_needed(cu)) {
		jbd_debug(2, "Handle %p waiting for checkpoint...\n", qg);
		atomic_sub(nblocks, &transaction->t_outstanding_credits);
		read_unlock(&cu->j_state_lock);
		write_lock(&cu->j_state_lock);
		if (__jbd2_log_space_left(cu) < jbd_space_needed(cu))
			__jbd2_log_wait_for_space(cu);
		write_unlock(&cu->j_state_lock);
		goto repeat;
	}


	update_t_max_wait(transaction, ts);
	handle->h_transaction = transaction;
	atomic_inc(&transaction->t_updates);
	atomic_inc(&transaction->t_handle_count);
	jbd_debug(4, "Handle %p given %d credits (total %d, free %d)\n",
		  qg, nblocks,
		  atomic_read(&transaction->t_outstanding_credits),
		  __jbd2_log_space_left(cu));
	read_unlock(&cu->j_state_lock);

	lock_map_acquire(&qg->h_lockdep_map);
	kfree(new_transaction);
	return 0;
}

static php_mb_regex_t tj(const char *fz, int hr, OnigOptionType nr, OnigEncoding ob, OnigSyntaxType *syntax ao)
{
