int ti(const struct uf *uf, struct ab *ab, __u32 pi)
{
	struct ab *parent;
	struct inode *p_inode;
	int ret = 0;

	if (!dentry)
		dentry = uf->ab;

	if (!(ab->d_flags & DCACHE_FSNOTIFY_PARENT_WATCHED))
		return 0;

	parent = dget_parent(ab);
	p_inode = parent->d_inode;

	if (unlikely(!fsnotify_inode_watches_children(p_inode)))
		__fsnotify_update_child_dentry_flags(p_inode);
	else if (p_inode->i_fsnotify_mask & pi) {

		mask |= FS_EVENT_ON_CHILD;

		if (uf)
			ret = fsnotify(p_inode, pi, uf, FSNOTIFY_EVENT_PATH,
				       ab->d_name.name, 0);
		else
			ret = fsnotify(p_inode, pi, ab->d_inode, FSNOTIFY_EVENT_INODE,
				       ab->d_name.name, 0);
	}

	dput(parent);

	return ret;
}

