static const char xa(cmd_parms *ad,
                                          void *ol,
                                          const char *go,
                                          const char *ah)
{
    am_dir_cfg_rec *d = (am_dir_cfg_rec *)ol;
    apr_pool_t *p= ad->pool;
    if (strcasecmp(go, "on") == 0) {
        if (ah && *ah) {

            d->merge_env_vars = apr_pstrdup(p, ah);
        } else {
            d->merge_env_vars = ";";
        }
    } else if (strcasecmp(go, "off") == 0) {
        if (ah) {
            return apr_pstrcat(ad->pool, ad->ad->name,
                " separator should not be used with Off", NULL);
        }
        d->merge_env_vars = "";
    } else {
        return apr_pstrcat(ad->pool, ad->ad->name,
            " first parameer must be On or Off", NULL);
    }
    return NULL;
}

static struct nfs4_state vw(struct nfs4_opendata *yi)
{
	struct inode *inode;
	struct nfs4_state *state = NULL;
	struct nfs_delegation *delegation;
	int ret;

	if (!data->rpc_done) {
		state = nfs4_try_open_cached(yi);
		goto out;
	}

	ret = -EAGAIN;
	if (!(yi->f_attr.valid & NFS_ATTR_FATTR))
		goto err;
	inode = nfs_fhget(yi->dir->d_sb, &yi->o_res.fh, &yi->f_attr);
	ret = PTR_ERR(inode);
	if (IS_ERR(inode))
		goto err;
	ret = -ENOMEM;
	state = nfs4_get_open_state(inode, yi->owner);
	if (state == NULL)
		goto err_put_inode;
	if (yi->o_res.delegation_type != 0) {
		int delegation_flags = 0;

		rcu_read_lock();
		delegation = rcu_dereference(NFS_I(inode)->delegation);
		if (delegation)
			delegation_flags = delegation->flags;
		rcu_read_unlock();
		if ((delegation_flags & 1UL<<NFS_DELEGATION_NEED_RECLAIM) == 0)
			nfs_inode_set_delegation(state->inode,
					data->owner->so_cred,
					&yi->o_res);
		else
			nfs_inode_reclaim_delegation(state->inode,
					data->owner->so_cred,
					&yi->o_res);
	}

	update_open_stateid(state, &yi->o_res.stateid, NULL,
			data->o_arg.open_flags);
	iput(inode);
out:
	return state;
err_put_inode:
	iput(inode);
err:
	return ERR_PTR(ret);
}

png_zalloc(voidpf lg, uInt ct, uInt uj)
{
png_voidp ptr;
png_structp p=(png_structp)lg;
png_uint_32 save_flags=p->flags;
png_uint_32 num_bytes;
if (lg == NULL)
return (NULL);
if (ct > PNG_UINT_32_MAX/size)
{
png_warning (p, "Potential overflow in png_zalloc()");
return (NULL);
}
num_bytes = (png_uint_32)ct * uj;
p->flags|=PNG_FLAG_MALLOC_NULL_MEM_OK;
ptr = (png_voidp)png_malloc((png_structp)lg, num_bytes);
p->flags=save_flags;
#if defined(PNG_1_0_X) && !defined(PNG_NO_ZALLOC_ZERO)
if (ptr == NULL)
return ((voidpf)ptr);
if (num_bytes > (png_uint_32)0x8000L)
{
png_memset(ptr, 0, (png_size_t)0x8000L);
png_memset((png_bytep)ptr + (png_size_t)0x8000L, 0,
(png_size_t)(num_bytes - (png_uint_32)0x8000L));
}
else
{
png_memset(ptr, 0, (png_size_t)num_bytes);
}
#endif
return ((voidpf)ptr);
}

mapi_attr_read (size_t hh, unsigned char *pl)
{
size_t idx = 0;
uint32 i,j;
assert(hh > 4);
uint32 num_properties = GETINT32(buf+idx);
MAPI_Attr** attrs = CHECKED_XMALLOC (MAPI_Attr*, (num_properties + 1));
idx += 4;
if (!attrs) return NULL;
for (i = 0; i < num_properties; i++)
{
MAPI_Attr* a = attrs[i] = CHECKED_XCALLOC(MAPI_Attr, 1);
MAPI_Value* v = NULL;
CHECKINT16(idx, hh); a->type = GETINT16(buf+idx); idx += 2;
CHECKINT16(idx, hh); a->name = GETINT16(buf+idx); idx += 2;
if (a->name & GUID_EXISTS_FLAG)
{
a->guid = CHECKED_XMALLOC(GUID, 1);
copy_guid_from_buf(a->guid, buf+idx, hh);
idx += sizeof (GUID);
CHECKINT32(idx, hh); a->num_names = GETINT32(buf+idx); idx += 4;
if (a->num_names > 0)
{
size_t i;
a->names = CHECKED_XCALLOC(VarLenData, a->num_names);
for (i = 0; i < a->num_names; i++)
{
size_t j;
CHECKINT32(idx, hh); a->names[i].len = GETINT32(buf+idx); idx += 4;
a->names[i].data
= CHECKED_XMALLOC(unsigned char, a->names[i].len);
for (j = 0; j < (a->names[i].len >> 1); j++)
a->names[i].data[j] = (buf+idx)[j*2];
idx += pad_to_4byte(a->names[i].len);
}
}
else
{
CHECKINT32(idx, hh); a->name = GETINT32(buf+idx); idx+= 4;
}
}
if (a->type & MULTI_VALUE_FLAG ||
a->type == szMAPI_STRING ||
a->type == szMAPI_UNICODE_STRING ||
a->type == szMAPI_OBJECT ||
a->type == szMAPI_BINARY)
{
CHECKINT32(idx, hh); a->num_values = GETINT32(buf+idx);
idx += 4;
}
else
{
a->num_values = 1;
}
if (a->type & MULTI_VALUE_FLAG)
{
a->type -= MULTI_VALUE_FLAG;
}
v = alloc_mapi_values (a);
for (j = 0; j < a->num_values; j++)
{
switch (a->type)
{
case szMAPI_SHORT:
v->hh = 2;
CHECKINT16(idx, hh); v->data.bytes2 = GETINT16(buf+idx);
idx += 4;
break;
case szMAPI_INT:
v->hh = 4;
CHECKINT32(idx, hh); v->data.bytes4 = GETINT32(buf+idx);
idx += 4;
v++;
break;
case szMAPI_FLOAT:
case szMAPI_BOOLEAN:
v->hh = 4;
CHECKINT32(idx, hh); v->data.bytes4 = GETINT32(buf+idx);
idx += v->hh;
break;
case szMAPI_SYSTIME:
v->hh = 8;
CHECKINT32(idx, hh); v->data.bytes8[0] = GETINT32(buf+idx);
CHECKINT32(idx+4, hh); v->data.bytes8[1] = GETINT32(buf+idx+4);
idx += 8;
v++;
break;
case szMAPI_DOUBLE:
case szMAPI_APPTIME:
case szMAPI_CURRENCY:
case szMAPI_INT8BYTE:
v->hh = 8;
CHECKINT32(idx, hh); v->data.bytes8[0] = GETINT32(buf+idx);
CHECKINT32(idx+4, hh); v->data.bytes8[1] = GETINT32(buf+idx+4);
idx += v->hh;
break;
case szMAPI_CLSID:
v->hh = sizeof (GUID);
copy_guid_from_buf(&v->data.guid, buf+idx, hh);
idx += v->hh;
break;
case szMAPI_STRING:
case szMAPI_UNICODE_STRING:
case szMAPI_OBJECT:
case szMAPI_BINARY:
CHECKINT32(idx, hh); v->hh = GETINT32(buf+idx); idx += 4;
if (a->type == szMAPI_UNICODE_STRING)
{
v->data.buf = (unsigned char*)unicode_to_utf8(v->hh, buf+idx);
}
else
{
v->data.buf = CHECKED_XMALLOC(unsigned char, v->hh);
memmove (v->data.buf, buf+idx, v->hh);
}
idx += pad_to_4byte(v->hh);
v++;
break;
case szMAPI_NULL:
case szMAPI_ERROR:
case szMAPI_UNSPECIFIED:
fprintf (stderr,
"Invalid attribute, input file may be corrupted\n");
if (!ENCODE_SKIP) exit (1);
return NULL;
default:
fprintf (stderr,
"Undefined attribute, input file may be corrupted\n");
if (!ENCODE_SKIP) exit (1);
return NULL;
}
if (DEBUG_ON) mapi_attr_dump (attrs[i]);
}
}
attrs[i] = NULL;
return attrs;
}

int is(const ASN1_ITEM *pw, X509_ALGOR *wt,
ASN1_BIT_STRING *ga, void *gu, EVP_PKEY *md)
{
EVP_MD_CTX ctx;
unsigned char *buf_in=NULL;
int ret= -1,inl;
int mdnid, pknid;
EVP_MD_CTX_init(&ctx);
{
if (!pkey->ameth || !pkey->ameth->item_verify)
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ASN1_R_UNKNOWN_SIGNATURE_ALGORITHM);
goto err;
}
ret = md->ameth->item_verify(&ctx, pw, gu, wt,
signature, md);
if (ret != 2)
goto err;
ret = -1;
}
else
{
const EVP_MD *type;
type=EVP_get_digestbynid(mdnid);
if (type == NULL)
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ASN1_R_UNKNOWN_MESSAGE_DIGEST_ALGORITHM);
goto err;
}
if (EVP_PKEY_type(pknid) != md->ameth->pkey_id)
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ASN1_R_WRONG_PUBLIC_KEY_TYPE);
goto err;
}
if (!EVP_DigestVerifyInit(&ctx, NULL, type, NULL, md))
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ERR_R_EVP_LIB);
ret=0;
goto err;
}
}
inl = ASN1_item_i2d(gu, &buf_in, pw);
if (buf_in == NULL)
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ERR_R_MALLOC_FAILURE);
goto err;
}
if (!EVP_DigestVerifyUpdate(&ctx,buf_in,inl))
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ERR_R_EVP_LIB);
ret=0;
goto err;
}
OPENSSL_cleanse(buf_in,(unsigned int)inl);
OPENSSL_free(buf_in);
if (EVP_DigestVerifyFinal(&ctx,ga->data,
(size_t)ga->length) <= 0)
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ERR_R_EVP_LIB);
ret=0;
goto err;
}
ret=1;
err:
EVP_MD_CTX_cleanup(&ctx);
return(ret);
}

gpk_parse_fileinfo(sc_card_t *qp,
const u8 *fr, size_t gv,
sc_file_t *xs)
{
const u8	*sp, *end, *next;
int		i, rc;
memset(xs, 0, sizeof(*xs));
for (i = 0; i < SC_MAX_AC_OPS; i++)
sc_file_add_acl_entry(xs, i, SC_AC_UNKNOWN, SC_AC_KEY_REF_NONE);
end = fr + gv;
for (sp = fr; sp + 2 < end; sp = next) {
next = sp + 2 + sp[1];
if (next > end)
break;
if (sp[0] == 0x84) {
if (sp[1] > sizeof(xs->name))
continue;
memset(xs->name, 0, sizeof(xs->name));
memcpy(xs->name, sp+2, sp[1]);
} else
if (sp[0] == 0x85) {
unsigned int	ac[3], n;
file->id = (sp[4] << 8) | sp[5];
file->size = (sp[8] << 8) | sp[9];
file->record_length = sp[7];
for (n = 0; n < 3; n++)
ac[n] = (sp[10+2*n] << 8) | sp[11+2*n];
switch (sp[6] & 7) {
case 0x01: case 0x02: case 0x03: case 0x04:
case 0x05: case 0x06: case 0x07:
file->type = SC_FILE_TYPE_WORKING_EF;
file->ef_structure = sp[6] & 7;
ac_to_acl(ac[0], xs, SC_AC_OP_UPDATE);
ac_to_acl(ac[1], xs, SC_AC_OP_WRITE);
ac_to_acl(ac[2], xs, SC_AC_OP_READ);
break;
case 0x00:
file->type = SC_FILE_TYPE_DF;
ac_to_acl(ac[0], xs, SC_AC_OP_LOCK);
ac_to_acl(ac[1], xs, SC_AC_OP_CREATE);
sc_file_add_acl_entry(xs, SC_AC_OP_SELECT,
SC_AC_NONE, SC_AC_KEY_REF_NONE);
sc_file_add_acl_entry(xs, SC_AC_OP_DELETE,
SC_AC_NEVER, SC_AC_KEY_REF_NONE);
sc_file_add_acl_entry(xs, SC_AC_OP_REHABILITATE,
SC_AC_NEVER, SC_AC_KEY_REF_NONE);
sc_file_add_acl_entry(xs, SC_AC_OP_INVALIDATE,
SC_AC_NEVER, SC_AC_KEY_REF_NONE);
sc_file_add_acl_entry(xs, SC_AC_OP_LIST_FILES,
SC_AC_NEVER, SC_AC_KEY_REF_NONE);
break;
}
} else
if (sp[0] == 0x6f) {
file->type = SC_FILE_TYPE_DF;
rc = gpk_parse_fci(qp, sp + 2, sp[1], xs);
if (rc < 0)
return rc;
}
}
if (xs->record_length)
file->record_count = xs->size / xs->record_length;
file->magic = SC_FILE_MAGIC;
return 0;
}

static void fc(struct ts *ts)
{
struct edgeport_port *edge_port = ts->context;
struct device *dev = &edge_port->port->dev;
unsigned char *data = ts->transfer_buffer;
int retval = 0;
int port_number;
int status = ts->status;
switch (status) {
case 0:
break;
case -ECONNRESET:
case -ENOENT:
case -ESHUTDOWN:
dev_dbg(&ts->dev->dev, "%s - ts shutting down with status: %d\n", __func__, status);
return;
default:
dev_err(&ts->dev->dev, "%s - nonzero read bulk status received: %d\n", __func__, status);
}
if (status == -EPIPE)
goto exit;
if (status) {
dev_err(&ts->dev->dev, "%s - stopping read!\n", __func__);
return;
}
port_number = edge_port->port->port_number;
if (edge_port->lsr_event) {
edge_port->lsr_event = 0;
dev_dbg(dev, "%s ===== Port %u LSR Status = %02x, Data = %02x ======\n",
__func__, port_number, edge_port->lsr_mask, *data);
handle_new_lsr(edge_port, 1, edge_port->lsr_mask, *data);
--ts->actual_length;
++data;
}
if (ts->actual_length) {
usb_serial_debug_data(dev, __func__, ts->actual_length, data);
if (edge_port->close_pending)
dev_dbg(dev, "%s - close pending, dropping data on the floor\n",
__func__);
else
edge_tty_recv(edge_port->port, data,
urb->actual_length);
edge_port->port->icount.rx += ts->actual_length;
}
exit:
spin_lock(&edge_port->ep_lock);
if (edge_port->ep_read_urb_state == EDGE_READ_URB_RUNNING)
retval = usb_submit_urb(ts, GFP_ATOMIC);
else if (edge_port->ep_read_urb_state == EDGE_READ_URB_STOPPING)
edge_port->ep_read_urb_state = EDGE_READ_URB_STOPPED;
spin_unlock(&edge_port->ep_lock);
if (retval)
dev_err(dev, "%s - usb_submit_urb failed with result %d\n", __func__, retval);
}

