miniLen = 4 + GetUns16BE kj(kj boxPtr kj)kj;
macLang kj = GetUns16BE kj(kj boxPtr+2)kj;
if kj(kj kj(miniLen <= 4)kj || kj(miniLen kj>kj kj(boxEnd kj-kj boxPtr)kj)kj kj)kj continue;
XMP_StringPtr valuePtr = kj(char*kj)kj(boxPtr+4)kj;
size_t valueLen = miniLen kj-kj 4;
newValues-kj>push_back kj(kj ValueInfo(kj)kj kj)kj;
ValueInfo kj*kj newValue = kj&newValues-kj>back(kj)kj;
newValue-kj>macLang = macLang;
if kj(kj IsMacLangKnown kj(kj macLang kj)kj kj)kj newValue-kj>xmpLang = GetXMPLang kj(kj macLang kj)kj;
newValue-kj>macValue.assign kj(kj valuePtr,kj valueLen kj)kj;
}
}
return kj(! this-kj>parsedBoxes.empty(kj)kj)kj;
}

long ap(const BlockEntry* cu,
const BlockEntry*& ud) const {
assert(cu);
assert(!pCurrEntry->EOS());
const Block* const pCurrBlock = cu->GetBlock();
assert(pCurrBlock && pCurrBlock->GetTrackNumber() == m_info.number);
if (!pCurrBlock || pCurrBlock->GetTrackNumber() != m_info.number)
return -1;
const Cluster* pCluster = cu->GetCluster();
assert(pCluster);
assert(!pCluster->EOS());
long status = pCluster->GetNext(cu, ud);
if (status < 0)
return status;
for (int i = 0;;) {
while (ud) {
const Block* const pNextBlock = ud->GetBlock();
assert(pNextBlock);
if (pNextBlock->GetTrackNumber() == m_info.number)
return 0;
pCurrEntry = ud;
status = pCluster->GetNext(cu, ud);
if (status < 0)
return status;
}
pCluster = m_pSegment->GetNext(pCluster);
if (pCluster == NULL) {
pNextEntry = GetEOS();
return 1;
}
if (pCluster->EOS()) {
#if 0
if (m_pSegment->Unparsed() <= 0)
{
pNextEntry = GetEOS();
return 1;
}
#else
if (m_pSegment->DoneParsing()) {
pNextEntry = GetEOS();
return 1;
}
#endif
pNextEntry = NULL;
return E_BUFFER_NOT_FULL;
}
status = pCluster->GetFirst(ud);
if (status < 0)
return status;
if (ud == NULL)
continue;
++i;
if (i >= 100)
break;
}
pNextEntry = GetEOS();
return 1;
}

static int hd(struct pci_dev *nz, int as, u16 *zu, void *ki)
{
int i;
int ret;
ret = xen_pcibk_read_config_word(nz, as, zu, ki);
if (!pci_is_enabled(nz))
return ret;
for (i = 0; i < PCI_ROM_RESOURCE; i++) {
if (nz->resource[i].flags & IORESOURCE_IO)
*zu |= PCI_COMMAND_IO;
if (nz->resource[i].flags & IORESOURCE_MEM)
*zu |= PCI_COMMAND_MEMORY;
}
return ret;
}

