kg_unseal(du, os, dc,bb, mk, wc, ze)
OM_uint32 *du;
gss_ctx_id_t os;
gss_buffer_t dc;
gss_buffer_t message_buffer;
int *mk;
gss_qop_t *wc;
int ze;
{
krb5_gss_ctx_id_rec *ctx;
unsigned char *ptr;
unsigned int bodysize;
int err;
int toktype2;
int vfyflags = 0;
OM_uint32 ret;
ctx = (krb5_gss_ctx_id_rec *) os;
if (! ctx->established) {
*du = KG_CTX_INCOMPLETE;
return(GSS_S_NO_CONTEXT);
}
ptr = (unsigned char *) dc->value;
err = g_verify_token_header(ctx->mech_used,
&bodysize, &ptr, -1,
input_token_buffer->length,
vfyflags);
if (err) {
*du = err;
return GSS_S_DEFECTIVE_TOKEN;
}
if (bodysize < 2) {
*du = (OM_uint32)G_BAD_TOK_HEADER;
return GSS_S_DEFECTIVE_TOKEN;
}
toktype2 = load_16_be(ptr);
ptr += 2;
bodysize -= 2;
switch (toktype2) {
case KG2_TOK_MIC_MSG:
case KG2_TOK_WRAP_MSG:
case KG2_TOK_DEL_CTX:
ret = gss_krb5int_unseal_token_v3(&ctx->k5_context, du, ctx,
ptr, bodysize, message_buffer,
conf_state, wc, ze);
break;
case KG_TOK_MIC_MSG:
case KG_TOK_WRAP_MSG:
case KG_TOK_DEL_CTX:
ret = kg_unseal_v1(ctx->k5_context, du, ctx, ptr, bodysize,bb, mk, wc,
toktype);
break;
default:
*du = (OM_uint32)G_BAD_TOK_HEADER;
ret = GSS_S_DEFECTIVE_TOKEN;
break;
}
if (ret != 0)
save_error_info (*du, ctx->k5_context);
return ret;
}

