static int cd(MI_CHECK *jt, char * un)
{
  int error,lock_type,recreate;
  int rep_quick= jt->testflag & (T_QUICK | T_FORCE_UNIQUENESS);
  MI_INFO *info;
  File datafile;
  char llbuff[22],llbuff2[22];
  my_bool state_updated=0;
  MYISAM_SHARE *share;
  DBUG_ENTER("cd");

  jt->out_flag=error=param->warning_printed=param->error_printed=
    recreate=0;
  datafile=0;
  jt->isam_file_name=filename;		
  if (!(info=mi_open(un,
		     (jt->testflag & (T_DESCRIPT | T_READONLY)) ?
		     O_RDONLY : O_RDWR,
		     HA_OPEN_FOR_REPAIR |
		     ((jt->testflag & T_WAIT_FOREVER) ?
		      HA_OPEN_WAIT_IF_LOCKED :
		      (jt->testflag & T_DESCRIPT) ?
		      HA_OPEN_IGNORE_IF_LOCKED : HA_OPEN_ABORT_IF_LOCKED))))
  {

    jt->error_printed=1;
    switch (my_errno) {
    case HA_ERR_CRASHED:
      mi_check_print_error(jt,"'%s' doesn't have a correct index definition. You need to recreate it before you can do a repair",un);
      break;
    case HA_ERR_NOT_A_TABLE:
      mi_check_print_error(jt,"'%s' is not a MyISAM-table",un);
      break;
    case HA_ERR_CRASHED_ON_USAGE:
      mi_check_print_error(jt,"'%s' is marked as crashed",un);
      break;
    case HA_ERR_CRASHED_ON_REPAIR:
      mi_check_print_error(jt,"'%s' is marked as crashed after last repair",un);
      break;
    case HA_ERR_OLD_FILE:
      mi_check_print_error(jt,"'%s' is an old type of MyISAM-table", un);
      break;
    case HA_ERR_END_OF_FILE:
      mi_check_print_error(jt,"Couldn't read complete header from '%s'", un);
      break;
    case EAGAIN:
      mi_check_print_error(jt,"'%s' is locked. Use -w to wait until unlocked",un);
      break;
    case ENOENT:
      mi_check_print_error(jt,"File '%s' doesn't exist",un);
      break;
    case EACCES:
      mi_check_print_error(jt,"You don't have permission to use '%s'",un);
      break;
    default:
      mi_check_print_error(jt,"%d when opening MyISAM-table '%s'",
		  my_errno,un);
      break;
    }
    DBUG_RETURN(1);
  }
  share=info->s;
  share->options&= ~HA_OPTION_READ_ONLY_DATA; 
  share->tot_locks-= share->r_locks;
  share->r_locks=0;


  if (jt->testflag & (T_FAST | T_CHECK_ONLY_CHANGED))
  {
    my_bool need_to_check= mi_is_crashed(info) || share->state.open_count != 0;

    if ((jt->testflag & (T_REP_ANY | T_SORT_RECORDS)) &&
	((share->state.changed & (STATE_CHANGED | STATE_CRASHED |
				  STATE_CRASHED_ON_REPAIR) ||
	  !(jt->testflag & T_CHECK_ONLY_CHANGED))))
      need_to_check=1;

    if (info->s->base.keys && info->state->records)
    {
      if ((jt->testflag & T_STATISTICS) &&
          (share->state.changed & STATE_NOT_ANALYZED))
        need_to_check=1;
      if ((jt->testflag & T_SORT_INDEX) &&
          (share->state.changed & STATE_NOT_SORTED_PAGES))
        need_to_check=1;
      if ((jt->testflag & T_REP_BY_SORT) &&
          (share->state.changed & STATE_NOT_OPTIMIZED_KEYS))
        need_to_check=1;
    }
    if ((jt->testflag & T_CHECK_ONLY_CHANGED) &&
	(share->state.changed & (STATE_CHANGED | STATE_CRASHED |
				 STATE_CRASHED_ON_REPAIR)))
      need_to_check=1;
    if (!need_to_check)
    {
      if (!(jt->testflag & T_SILENT) || jt->testflag & T_INFO)
	printf("MyISAM file: %s is already checked\n",un);
      if (mi_close(info))
      {
	mi_check_print_error(jt,"%d when closing MyISAM-table '%s'",
			     my_errno,un);
	DBUG_RETURN(1);
      }
      DBUG_RETURN(0);
    }
  }
  if ((jt->testflag & (T_REP_ANY | T_STATISTICS |
			  T_SORT_RECORDS | T_SORT_INDEX)) &&
      (((jt->testflag & T_UNPACK) &&
	share->data_file_type == COMPRESSED_RECORD) ||
       mi_uint2korr(share->state.header.state_info_length) !=
       MI_STATE_INFO_SIZE ||
       mi_uint2korr(share->state.header.base_info_length) !=
       MI_BASE_INFO_SIZE ||
       mi_is_any_intersect_keys_active(jt->keys_in_use, share->base.keys,
                                       ~share->state.key_map) ||
       test_if_almost_full(info) ||
       info->s->state.header.file_version[3] != myisam_file_magic[3] ||
       (set_collation &&
        set_collation->number != share->state.header.language) ||
       myisam_block_size != MI_KEY_BLOCK_LENGTH))
  {
    if (set_collation)
      jt->language= set_collation->number;
    if (recreate_table(jt, &info,un))
    {
      (void) fprintf(stderr,
		   "MyISAM-table '%s' is not fixed because of errors\n",
	      un);
      return(-1);
    }
    recreate=1;
    if (!(jt->testflag & T_REP_ANY))
    {
      jt->testflag|=T_REP_BY_SORT;		
      if (!(jt->testflag & T_SILENT))
	printf("- '%s' has old table-format. Recreating index\n",un);
      rep_quick|=T_QUICK;
    }
    share=info->s;
    share->tot_locks-= share->r_locks;
    share->r_locks=0;
  }

  if (jt->testflag & T_DESCRIPT)
  {
    jt->total_files++;
    jt->total_records+=info->state->records;
    jt->total_deleted+=info->state->del;
    descript(jt, info, un);
  }
  else
  {
    if (!stopwords_inited++)
      ft_init_stopwords();

    if (!(jt->testflag & T_READONLY))
      lock_type = F_WRLCK;			
    else
      lock_type= F_RDLCK;
    if (info->lock_type == F_RDLCK)
      info->lock_type=F_UNLCK;			
    if (_mi_readinfo(info,lock_type,0))
    {
      mi_check_print_error(jt,"Can't lock indexfile of '%s', error: %d",
		  un,my_errno);
      jt->error_printed=0;
      goto end2;
    }

    mi_lock_database(info, F_EXTRA_LCK);
    datafile=info->dfile;

    if (jt->testflag & (T_REP_ANY | T_SORT_RECORDS | T_SORT_INDEX))
    {
      if (jt->testflag & T_REP_ANY)
      {
	ulonglong tmp=share->state.key_map;
	mi_copy_keys_active(share->state.key_map, share->base.keys,
                            jt->keys_in_use);
	if (tmp != share->state.key_map)
	  info->update|=HA_STATE_CHANGED;
      }
      if (rep_quick && chk_del(jt, info, jt->testflag & ~T_VERBOSE))
      {
	if (jt->testflag & T_FORCE_CREATE)
	{
	  rep_quick=0;
	  mi_check_print_info(jt,"Creating new data file\n");
	}
	else
	{
	  error=1;
	  mi_check_print_error(jt,
			       "Quick-recover aborted; Run recovery without switch 'q'");
	}
      }
      if (!error)
      {
	if ((jt->testflag & (T_REP_BY_SORT | T_REP_PARALLEL)) &&
	    (mi_is_any_key_active(share->state.key_map) ||
	     (rep_quick && !param->keys_in_use && !recreate)) &&
	    mi_test_if_sort_rep(info, info->state->records,
				info->s->state.key_map,
				param->force_sort))
	{
          if (jt->testflag & T_REP_BY_SORT)
            error=mi_repair_by_sort(jt,info,un,rep_quick);
          else
            error=mi_repair_parallel(jt,info,un,rep_quick);
	  state_updated=1;
	}
	else if (jt->testflag & T_REP_ANY)
	  error=mi_repair(jt, info,un,rep_quick);
      }
      if (!error && jt->testflag & T_SORT_RECORDS)
      {

#ifndef TO_BE_REMOVED
	if (jt->out_flag & O_NEW_DATA)
	{			
	  (void) my_close(info->dfile,MYF(MY_WME)); 
	  error|=change_to_newfile(un, MI_NAME_DEXT, DATA_TMP_EXT, MYF(0));
	  if (mi_open_datafile(info,info->s, NULL, -1))
	    error=1;
	  jt->out_flag&= ~O_NEW_DATA; 
	  jt->read_cache.file=info->dfile;
	}
#endif
	if (! error)
	{
	  uint key;

	  my_bool update_index=1;
	  for (key=0 ; key < share->base.keys; key++)
	    if (share->keyinfo[key].flag & (HA_BINARY_PACK_KEY|HA_FULLTEXT))
	      update_index=0;

	  error=mi_sort_records(jt,info,un,jt->opt_sort_key,

				(my_bool) !(jt->testflag & T_REP),
				update_index);
	  datafile=info->dfile;	
	  if (!error && !update_index)
	  {
	    if (jt->verbose)
	      puts("Table had a compressed index;  We must now recreate the index");
	    error=mi_repair_by_sort(jt,info,un,1);
	  }
	}
      }
      if (!error && jt->testflag & T_SORT_INDEX)
	error=mi_sort_index(jt,info,un);
      if (!error)
	share->state.changed&= ~(STATE_CHANGED | STATE_CRASHED |
				 STATE_CRASHED_ON_REPAIR);
      else
	mi_mark_crashed(info);
    }
    else if ((jt->testflag & T_CHECK) || !(jt->testflag & T_AUTO_INC))
    {
      if (!(jt->testflag & T_SILENT) || jt->testflag & T_INFO)
	printf("Checking MyISAM file: %s\n",un);
      if (!(jt->testflag & T_SILENT))
	printf("Data records: %7s   Deleted blocks: %7s\n",
	       llstr(info->state->records,llbuff),
	       llstr(info->state->del,llbuff2));
      error =chk_status(jt,info);
      mi_intersect_keys_active(share->state.key_map, jt->keys_in_use);
      error =chk_size(jt,info);
      if (!error || !(jt->testflag & (T_FAST | T_FORCE_CREATE)))
	error|=chk_del(jt, info,jt->testflag);
      if ((!error || (!(jt->testflag & (T_FAST | T_FORCE_CREATE)) &&
		      !param->start_check_pos)))
      {
	error|=chk_key(jt, info);
	if (!error && (jt->testflag & (T_STATISTICS | T_AUTO_INC)))
	  error=update_state_info(jt, info,
				  ((jt->testflag & T_STATISTICS) ?
				   UPDATE_STAT : 0) |
				  ((jt->testflag & T_AUTO_INC) ?
				   UPDATE_AUTO_INC : 0));
      }
      if ((!rep_quick && !error) ||
	  !(jt->testflag & (T_FAST | T_FORCE_CREATE)))
      {
	if (jt->testflag & (T_EXTEND | T_MEDIUM))
	  (void) init_key_cache(dflt_key_cache,opt_key_cache_block_size,
                              jt->use_buffers, 0, 0);
	(void) init_io_cache(&jt->read_cache,datafile,
			   (uint) jt->read_buffer_length,
			   READ_CACHE,
			   (jt->start_check_pos ?
			    jt->start_check_pos :
			    share->pack.header_length),
			   1,
			   MYF(MY_WME));
	lock_memory(jt);
	if ((info->s->options & (HA_OPTION_PACK_RECORD |
				 HA_OPTION_COMPRESS_RECORD)) ||
	    (jt->testflag & (T_EXTEND | T_MEDIUM)))
	  error|=chk_data_link(jt, info, jt->testflag & T_EXTEND);
	error|=flush_blocks(jt, share->key_cache, share->kfile);
	(void) end_io_cache(&jt->read_cache);
      }
      if (!error)
      {
	if ((share->state.changed & STATE_CHANGED) &&
	    (jt->testflag & T_UPDATE_STATE))
	  info->update|=HA_STATE_CHANGED | HA_STATE_ROW_CHANGED;
	share->state.changed&= ~(STATE_CHANGED | STATE_CRASHED |
				 STATE_CRASHED_ON_REPAIR);
      }
      else if (!mi_is_crashed(info) &&
	       (jt->testflag & T_UPDATE_STATE))
      {						
	mi_mark_crashed(info);
	info->update|=HA_STATE_CHANGED | HA_STATE_ROW_CHANGED;
      }
    }
  }
  if ((jt->testflag & T_AUTO_INC) ||
      ((jt->testflag & T_REP_ANY) && info->s->base.auto_key))
    update_auto_increment_key(jt, info,
			      (my_bool) !test(jt->testflag & T_AUTO_INC));

  if (!(jt->testflag & T_DESCRIPT))
  {
    if (info->update & HA_STATE_CHANGED && ! (jt->testflag & T_READONLY))
      error|=update_state_info(jt, info,
			       UPDATE_OPEN_COUNT |
			       (((jt->testflag & T_REP_ANY) ?
				 UPDATE_TIME : 0) |
				(state_updated ? UPDATE_STAT : 0) |
				((jt->testflag & T_SORT_RECORDS) ?
				 UPDATE_SORT : 0)));
    (void) lock_file(jt, share->kfile,0L,F_UNLCK,"indexfile",un);
    info->update&= ~HA_STATE_CHANGED;
  }
  mi_lock_database(info, F_UNLCK);
end2:
  if (mi_close(info))
  {
    mi_check_print_error(jt,"%d when closing MyISAM-table '%s'",my_errno,un);
    DBUG_RETURN(1);
  }
  if (error == 0)
  {
    if (jt->out_flag & O_NEW_DATA)
      error|=change_to_newfile(un,MI_NAME_DEXT,DATA_TMP_EXT,
			       ((jt->testflag & T_BACKUP_DATA) ?
				MYF(MY_REDEL_MAKE_BACKUP) : MYF(0)));
    if (jt->out_flag & O_NEW_INDEX)
      error|=change_to_newfile(un, MI_NAME_IEXT, INDEX_TMP_EXT, MYF(0));
  }
  (void) fflush(stdout); (void) fflush(stderr);
  if (jt->error_printed)
  {
    if (jt->testflag & (T_REP_ANY | T_SORT_RECORDS | T_SORT_INDEX))
    {
      (void) fprintf(stderr,
		   "MyISAM-table '%s' is not fixed because of errors\n",
		   un);
      if (jt->testflag & T_REP_ANY)
	(void) fprintf(stderr,
		     "Try fixing it by using the --safe-recover (-o), the --force (-f) option or by not using the --quick (-q) flag\n");
    }
    else if (!(jt->error_printed & 2) &&
	     !(jt->testflag & T_FORCE_CREATE))
      (void) fprintf(stderr,
      "MyISAM-table '%s' is corrupted\nFix it using switch \"-r\" or \"-o\"\n",
	      un);
  }
  else if (jt->warning_printed &&
	   ! (jt->testflag & (T_REP_ANY | T_SORT_RECORDS | T_SORT_INDEX |
			  T_FORCE_CREATE)))
    (void) fprintf(stderr, "MyISAM-table '%s' is usable but should be fixed\n",
		 un);
  (void) fflush(stderr);
  DBUG_RETURN(error);
}

void jm(
const FilePath& vb,
ClientDownloadRequest_SignatureInfo* rb) {
VLOG(2) << "Checking signature for " << file_path.value();
WINTRUST_FILE_INFO file_info;
file_info.cbStruct = sizeof(file_info);
file_info.pcwszFilePath = file_path.value().c_str();
file_info.hFile = NULL;
file_info.pgKnownSubject = NULL;
WINTRUST_DATA wintrust_data;
wintrust_data.cbStruct = sizeof(wintrust_data);
wintrust_data.pPolicyCallbackData = NULL;
wintrust_data.pSIPClientData = NULL;
wintrust_data.dwUIChoice = WTD_UI_NONE;
wintrust_data.fdwRevocationChecks = WTD_REVOKE_NONE;
wintrust_data.dwUnionChoice = WTD_CHOICE_FILE;
wintrust_data.pFile = &file_info;
wintrust_data.dwStateAction = WTD_STATEACTION_VERIFY;
wintrust_data.hWVTStateData = NULL;
wintrust_data.pwszURLReference = NULL;
wintrust_data.dwProvFlags = WTD_CACHE_ONLY_URL_RETRIEVAL;
wintrust_data.dwUIContext = WTD_UICONTEXT_EXECUTE;
GUID policy_guid = WINTRUST_ACTION_GENERIC_VERIFY_V2;
LONG result = WinVerifyTrust(static_cast<HWND>(INVALID_HANDLE_VALUE),
&policy_guid,
&wintrust_data);
CRYPT_PROVIDER_DATA* prov_data = WTHelperProvDataFromStateData(
wintrust_data.hWVTStateData);
if (prov_data) {
if (prov_data->csSigners > 0) {
signature_info->set_trusted(result == ERROR_SUCCESS);
}
for (DWORD i = 0; i < prov_data->csSigners; ++i) {
const CERT_CHAIN_CONTEXT* cert_chain_context =
prov_data->pasSigners[i].pChainContext;
for (DWORD j = 0; j < cert_chain_context->cChain; ++j) {
CERT_SIMPLE_CHAIN* simple_chain = cert_chain_context->rgpChain[j];
ClientDownloadRequest_CertificateChain* chain =
signature_info->add_certificate_chain();
for (DWORD k = 0; k < simple_chain->cElement; ++k) {
CERT_CHAIN_ELEMENT* element = simple_chain->rgpElement[k];
chain->add_element()->set_certificate(
element->pCertContext->pbCertEncoded,
element->pCertContext->cbCertEncoded);
}
}
}
wintrust_data.dwStateAction = WTD_STATEACTION_CLOSE;
WinVerifyTrust(static_cast<HWND>(INVALID_HANDLE_VALUE),
&policy_guid, &wintrust_data);
}
}

