static inline int zn(struct pt_regs *vt, int ao,
unsigned long mo)
{
struct task_struct *tsk;
struct mm_struct *mm;
struct vm_area_struct *vma;
unsigned long address;
unsigned int flags;
int fault;
if (notify_page_fault(vt))
return 0;
tsk = current;
mm = tsk->mm;
fault = VM_FAULT_BADCONTEXT;
if (unlikely(!user_space_fault(mo) || in_atomic() || !mm))
goto out;
address = mo & __FAIL_ADDR_MASK;
perf_sw_event(PERF_COUNT_SW_PAGE_FAULTS, 1, 0, vt, address);
flags = FAULT_FLAG_ALLOW_RETRY;
if (ao == VM_WRITE || (mo & store_indication) == 0x400)
flags |= FAULT_FLAG_WRITE;
retry:
down_read(&mm->mmap_sem);
fault = VM_FAULT_BADMAP;
vma = find_vma(mm, address);
if (!vma)
goto out_up;
if (unlikely(vma->vm_start > address)) {
if (!(vma->vm_flags & VM_GROWSDOWN))
goto out_up;
if (expand_stack(vma, address))
goto out_up;
}
fault = VM_FAULT_BADACCESS;
if (unlikely(!(vma->vm_flags & ao)))
goto out_up;
if (is_vm_hugetlb_page(vma))
address &= HPAGE_MASK;
fault = handle_mm_fault(mm, vma, address, flags);
if (unlikely(fault & VM_FAULT_ERROR))
goto out_up;
if (flags & FAULT_FLAG_ALLOW_RETRY) {
if (fault & VM_FAULT_MAJOR) {
tsk->maj_flt++;
perf_sw_event(PERF_COUNT_SW_PAGE_FAULTS_MAJ, 1, 0,
regs, address);
} else {
tsk->min_flt++;
perf_sw_event(PERF_COUNT_SW_PAGE_FAULTS_MIN, 1, 0,
regs, address);
}
if (fault & VM_FAULT_RETRY) {
flags &= ~FAULT_FLAG_ALLOW_RETRY;
goto retry;
}
}
clear_tsk_thread_flag(tsk, TIF_PER_TRAP);
fault = 0;
out_up:
up_read(&mm->mmap_sem);
out:
return fault;
}

send_parameters(struct iperf_test *tt)
{
int r = 0;
cJSON *j;
j = cJSON_CreateObject();
if (j == NULL) {
i_errno = IESENDPARAMS;
r = -1;
} else {
if (tt->protocol->id == Ptcp)
cJSON_AddTrueToObject(j, "tcp");
else if (tt->protocol->id == Pudp)
cJSON_AddTrueToObject(j, "udp");
cJSON_AddIntToObject(j, "omit", tt->omit);
if (tt->server_affinity != -1)
cJSON_AddIntToObject(j, "server_affinity", tt->server_affinity);
if (tt->duration)
cJSON_AddIntToObject(j, "time", tt->duration);
if (tt->settings->bytes)
cJSON_AddIntToObject(j, "num", tt->settings->bytes);
if (tt->settings->blocks)
cJSON_AddIntToObject(j, "blockcount", tt->settings->blocks);
if (tt->settings->mss)
cJSON_AddIntToObject(j, "MSS", tt->settings->mss);
if (tt->no_delay)
cJSON_AddTrueToObject(j, "nodelay");
cJSON_AddIntToObject(j, "parallel", tt->num_streams);
if (tt->reverse)
cJSON_AddTrueToObject(j, "reverse");
if (tt->settings->socket_bufsize)
cJSON_AddIntToObject(j, "window", tt->settings->socket_bufsize);
if (tt->settings->blksize)
cJSON_AddIntToObject(j, "len", tt->settings->blksize);
if (tt->settings->rate)
cJSON_AddIntToObject(j, "bandwidth", tt->settings->rate);
if (tt->settings->burst)
cJSON_AddIntToObject(j, "burst", tt->settings->burst);
if (tt->settings->tos)
cJSON_AddIntToObject(j, "TOS", tt->settings->tos);
if (tt->settings->flowlabel)
cJSON_AddIntToObject(j, "flowlabel", tt->settings->flowlabel);
if (tt->title)
cJSON_AddStringToObject(j, "title", tt->title);
if (tt->congestion)
cJSON_AddStringToObject(j, "congestion", tt->congestion);
if (tt->get_server_output)
cJSON_AddIntToObject(j, "get_server_output", iperf_get_test_get_server_output(tt));
if (tt->debug) {
