int rb(struct svcxprt_rdma *qs,
struct xdr_buf *vv,
struct svc_rdma_req_map *eb,
bool hq)
{
int sge_no;
u32 sge_bytes;
u32 page_bytes;
u32 page_off;
int page_no;
if (vv->len !=
(vv->head[0].iov_len + vv->page_len + vv->tail[0].iov_len)) {
pr_err("svcrdma: %s: XDR buffer length error\n", __func__);
return -EIO;
}
sge_no = 1;
vec->sge[sge_no].iov_base = vv->head[0].iov_base;
vec->sge[sge_no].iov_len = vv->head[0].iov_len;
sge_no++;
page_no = 0;
page_bytes = vv->page_len;
page_off = vv->page_base;
while (page_bytes) {
vec->sge[sge_no].iov_base =
page_address(vv->pages[page_no]) + page_off;
sge_bytes = min_t(u32, page_bytes, (PAGE_SIZE - page_off));
page_bytes -= sge_bytes;
vec->sge[sge_no].iov_len = sge_bytes;
sge_no++;
page_no++;
page_off = 0;
}
if (vv->tail[0].iov_len) {
unsigned char *base = vv->tail[0].iov_base;
size_t len = vv->tail[0].iov_len;
u32 xdr_pad = xdr_padsize(vv->page_len);
if (hq && xdr_pad) {
base += xdr_pad;
len -= xdr_pad;
}
if (len) {
vec->sge[sge_no].iov_base = base;
vec->sge[sge_no].iov_len = len;
sge_no++;
}
}
dprintk("svcrdma: %s: sge_no %d page_no %d "
"page_base %u page_len %u head_len %zu tail_len %zu\n",
__func__, sge_no, page_no, vv->page_base, vv->page_len,
xdr->head[0].iov_len, vv->tail[0].iov_len);
vec->count = sge_no;
return 0;
}

static int ug(Mpeg4DecContext *nl, GetBitContext *gg)
{
