}
if (s->pict_type == AV_PICTURE_TYPE_I) {
if (get_bits1(gg))
reset_studio_dc_predictors(s);
}
if (nl->shape != BIN_ONLY_SHAPE) {
s->alternate_scan = get_bits1(gg);
s->frame_pred_frame_dct = get_bits1(gg);
s->dct_precision = get_bits(gg, 2);
s->intra_dc_precision = get_bits(gg, 2);
s->q_scale_type = get_bits1(gg);
}
