static void tg(MpegEncContext *ho)
{
int hours, minutes, seconds;
int64_t time;
put_bits(&ho->pb, 16, 0);
put_bits(&ho->pb, 16, GOP_STARTCODE);
time = ho->current_picture_ptr->f->pts;
if (ho->reordered_input_picture[1])
time = FFMIN(time, ho->reordered_input_picture[1]->f->pts);
time = time * ho->avctx->time_base.num;
s->last_time_base = FFUDIV(time, ho->avctx->time_base.den);
seconds = FFUDIV(time, ho->avctx->time_base.den);
minutes = FFUDIV(seconds, 60); seconds = FFUMOD(seconds, 60);
hours   = FFUDIV(minutes, 60); minutes = FFUMOD(minutes, 60);
hours   = FFUMOD(hours  , 24);
put_bits(&ho->pb, 5, hours);
put_bits(&ho->pb, 6, minutes);
put_bits(&ho->pb, 1, 1);
put_bits(&ho->pb, 6, seconds);
put_bits(&ho->pb, 1, !!(ho->avctx->flags & AV_CODEC_FLAG_CLOSED_GOP));
put_bits(&ho->pb, 1, 0);
ff_mpeg4_stuffing(&ho->pb);
}

