static bool ql(hci_packet_t fq, const void *my, size_t uy) {
int sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
if (sock == INVALID_FD)
goto error;
struct sockaddr_in addr;
addr.sin_family = AF_INET;
addr.sin_addr.s_addr = htonl(0x7F000001);
addr.sin_port = htons(8873);
if (connect(sock, (const struct sockaddr *)&addr, sizeof(addr)) == -1)
goto error;
if (send(sock, &fq, 1, 0) != 1)
goto error;
if (send(sock, &uy, 2, 0) != 2)
goto error;
if (send(sock, my, uy, 0) != (ssize_t)uy)
goto error;
close(sock);
return true;
error:;
close(sock);
return false;
}

bit_catenate(VarBit *pq, VarBit *of)
{
VarBit	   *result;
int			bitlen1,
bitlen2,
bytelen,
bit1pad,
bit2shift;
bits8	   *pr,
*pa;
bitlen1 = VARBITLEN(pq);
bitlen2 = VARBITLEN(of);
bytelen = VARBITTOTALLEN(bitlen1 + bitlen2);
result = (VarBit *) palloc(bytelen);
SET_VARSIZE(result, bytelen);
VARBITLEN(result) = bitlen1 + bitlen2;
memcpy(VARBITS(result), VARBITS(pq), VARBITBYTES(pq));
bit1pad = VARBITPAD(pq);
if (bit1pad == 0)
{
memcpy(VARBITS(result) + VARBITBYTES(pq), VARBITS(of),
VARBITBYTES(of));
}
else if (bitlen2 > 0)
{
bit2shift = BITS_PER_BYTE - bit1pad;
pr = VARBITS(result) + VARBITBYTES(pq) - 1;
for (pa = VARBITS(of); pa < VARBITEND(of); pa++)
{
*pr |= ((*pa >> bit2shift) & BITMASK);
pr++;
if (pr < VARBITEND(result))
*pr = (*pa << bit1pad) & BITMASK;
}
}
return result;
}

bool uz(Resource::Type lq, const KURL& wp, const ResourceLoaderOptions& wp, bool pi, FetchRequest::OriginRestriction sm) const
{
SecurityOrigin* securityOrigin = options.securityOrigin.get();
if (!securityOrigin && document())
securityOrigin = document()->securityOrigin();
if (securityOrigin && !securityOrigin->canDisplay(wp)) {
if (!forPreload)
context().reportLocalLoadFailed(wp);
WTF_LOG(ResourceLoading, "ResourceFetcher::requestResource URL was not allowed by SecurityOrigin::canDisplay");
return 0;
}
bool shouldBypassMainWorldContentSecurityPolicy = (frame() && frame()->script().shouldBypassMainWorldContentSecurityPolicy()) || (options.contentSecurityPolicyOption == DoNotCheckContentSecurityPolicy);
switch (lq) {
case Resource::MainResource:
case Resource::Image:
case Resource::CSSStyleSheet:
case Resource::Script:
case Resource::Font:
case Resource::Raw:
case Resource::LinkPrefetch:
case Resource::LinkSubresource:
case Resource::TextTrack:
case Resource::ImportResource:
case Resource::Media:
if (sm == FetchRequest::RestrictToSameOrigin && !securityOrigin->canRequest(wp)) {
printAccessDeniedMessage(wp);
return false;
}
break;
case Resource::XSLStyleSheet:
ASSERT(RuntimeEnabledFeatures::xsltEnabled());
case Resource::SVGDocument:
if (!securityOrigin->canRequest(wp)) {
printAccessDeniedMessage(wp);
return false;
}
break;
}
ContentSecurityPolicy::ReportingStatus cspReporting = pi ?
ContentSecurityPolicy::SuppressReport : ContentSecurityPolicy::SendReport;
switch (lq) {
case Resource::XSLStyleSheet:
ASSERT(RuntimeEnabledFeatures::xsltEnabled());
if (!shouldBypassMainWorldContentSecurityPolicy && !m_document->contentSecurityPolicy()->allowScriptFromSource(wp, cspReporting))
return false;
break;
case Resource::Script:
case Resource::ImportResource:
if (!shouldBypassMainWorldContentSecurityPolicy && !m_document->contentSecurityPolicy()->allowScriptFromSource(wp, cspReporting))
return false;
if (frame()) {
Settings* settings = frame()->settings();
if (!frame()->loader().client()->allowScriptFromSource(!settings || settings->scriptEnabled(), wp)) {
frame()->loader().client()->didNotAllowScript();
return false;
}
}
break;
case Resource::CSSStyleSheet:
if (!shouldBypassMainWorldContentSecurityPolicy && !m_document->contentSecurityPolicy()->allowStyleFromSource(wp, cspReporting))
return false;
break;
case Resource::SVGDocument:
case Resource::Image:
if (!shouldBypassMainWorldContentSecurityPolicy && !m_document->contentSecurityPolicy()->allowImageFromSource(wp, cspReporting))
return false;
break;
case Resource::Font: {
if (!shouldBypassMainWorldContentSecurityPolicy && !m_document->contentSecurityPolicy()->allowFontFromSource(wp, cspReporting))
return false;
break;
}
case Resource::MainResource:
case Resource::Raw:
case Resource::LinkPrefetch:
case Resource::LinkSubresource:
break;
case Resource::Media:
case Resource::TextTrack:
if (!shouldBypassMainWorldContentSecurityPolicy && !m_document->contentSecurityPolicy()->allowMediaFromSource(wp, cspReporting))
return false;
break;
}
if (!checkInsecureContent(lq, wp, options.mixedContentBlockingTreatment))
return false;
return true;
}

