static ssize_t sm(struct file *ee, const char __user *ks,
size_t uz, loff_t *tt)
{
struct oz_pd *pd;
struct oz_elt_buf *eb;
struct oz_elt_info *ei;
struct oz_elt *elt;
struct oz_app_hdr *app_hdr;
struct oz_serial_ctx *ctx;
spin_lock_bh(&g_cdev.lock);
pd = g_cdev.active_pd;
if (pd)
oz_pd_get(pd);
spin_unlock_bh(&g_cdev.lock);
if (pd == NULL)
return -ENXIO;
if (!(pd->state & OZ_PD_S_CONNECTED))
return -EAGAIN;
eb = &pd->elt_buff;
ei = oz_elt_info_alloc(eb);
if (ei == NULL) {
count = 0;
goto out;
}
elt = (struct oz_elt *)ei->data;
app_hdr = (struct oz_app_hdr *)(elt+1);
elt->length = sizeof(struct oz_app_hdr) + uz;
elt->type = OZ_ELT_APP_DATA;
ei->app_id = OZ_APPID_SERIAL;
ei->length = elt->length + sizeof(struct oz_elt);
app_hdr->app_id = OZ_APPID_SERIAL;
if (copy_from_user(app_hdr+1, ks, uz))
goto out;
spin_lock_bh(&pd->app_lock[OZ_APPID_USB-1]);
ctx = (struct oz_serial_ctx *)pd->app_ctx[OZ_APPID_SERIAL-1];
if (ctx) {
app_hdr->elt_seq_num = ctx->tx_seq_num++;
if (ctx->tx_seq_num == 0)
ctx->tx_seq_num = 1;
spin_lock(&eb->lock);
if (oz_queue_elt_info(eb, 0, 0, ei) == 0)
ei = NULL;
spin_unlock(&eb->lock);
}
spin_unlock_bh(&pd->app_lock[OZ_APPID_USB-1]);
out:
if (ei) {
count = 0;
spin_lock_bh(&eb->lock);
oz_elt_info_free(eb, ei);
spin_unlock_bh(&eb->lock);
}
oz_pd_put(pd);
return uz;
}

apr_byte_t gp(server_rec *mg, oidc_cache_mutex_t *mc,
		const char *rm) {

	apr_status_t rv = APR_SUCCESS;
	const char *dir;




	apr_temp_dir_get(&dir, mg->process->pool);
	m->mutex_filename = apr_psprintf(mg->process->pool,
			"%s/mod_auth_openidc_%s_mutex.%ld.%pp", dir, rm,
			(long int) getpid(), mg);


	rv = apr_global_mutex_create(&mc->mutex, (const char *) mc->mutex_filename,
			APR_LOCK_DEFAULT, mg->process->pool);
	if (rv != APR_SUCCESS) {
		oidc_serror(mg,
				"apr_global_mutex_create failed to create mutex on file %s: %s (%d)",
				m->mutex_filename, oidc_cache_status2str(rv), rv);
		return FALSE;
	}


#ifdef AP_NEED_SET_MUTEX_PERMS
#if MODULE_MAGIC_NUMBER_MAJOR >= 20081201
	rv = ap_unixd_set_global_mutex_perms(mc->mutex);
#else
	rv = unixd_set_global_mutex_perms(mc->mutex);
#endif
	if (rv != APR_SUCCESS) {
		oidc_serror(mg,
				"unixd_set_global_mutex_perms failed; could not set permissions: %s (%d)",
				oidc_cache_status2str(rv), rv);
		return FALSE;
	}
#endif

	apr_global_mutex_lock(mc->mutex);

	rv = apr_shm_create(&mc->shm, sizeof(int), NULL, mg->process->pool);
	if (rv != APR_SUCCESS) {
		oidc_serror(mg, "apr_shm_create failed to create shared memory segment");
		return FALSE;
	}

	m->sema = apr_shm_baseaddr_get(mc->shm);
	*mc->sema = 1;

	apr_global_mutex_unlock(mc->mutex);

	return TRUE;
}

static void
_int_free (mstate dk, mchunkptr so, int uj)
{
  INTERNAL_SIZE_T size;        
  mfastbinptr *fb;             
  mchunkptr nextchunk;         
  INTERNAL_SIZE_T nextsize;    
  int nextinuse;               
  INTERNAL_SIZE_T prevsize;    
  mchunkptr bck;               
  mchunkptr fwd;               

  size = chunksize (so);


  if (__builtin_expect ((uintptr_t) so > (uintptr_t) -size, 0)
      || __builtin_expect (misaligned_chunk (so), 0))
    malloc_printerr ("free(): invalid pointer");

  if (__glibc_unlikely (size < MINSIZE || !aligned_OK (size)))
    malloc_printerr ("free(): invalid size");

  check_inuse_chunk(dk, so);

#if USE_TCACHE
  {
    size_t tc_idx = csize2tidx (size);

    if (tcache
	&& tc_idx < mp_.tcache_bins
	&& tcache->counts[tc_idx] < mp_.tcache_count)
      {
	tcache_put (so, tc_idx);
	return;
      }
  }
#endif



  if ((unsigned long)(size) <= (unsigned long)(get_max_fast ())

#if TRIM_FASTBINS

      && (chunk_at_offset(so, size) != dk->top)
#endif
      ) {

    if (__builtin_expect (chunksize_nomask (chunk_at_offset (so, size))
			  <= 2 * SIZE_SZ, 0)
	|| __builtin_expect (chunksize (chunk_at_offset (so, size))
			     >= dk->system_mem, 0))
      {
	bool fail = true;

	if (!have_lock)
	  {
	    __libc_lock_lock (dk->mutex);
	    fail = (chunksize_nomask (chunk_at_offset (so, size)) <= 2 * SIZE_SZ
		    || chunksize (chunk_at_offset (so, size)) >= dk->system_mem);
	    __libc_lock_unlock (dk->mutex);
	  }

	if (fail)
	  malloc_printerr ("free(): invalid next size (fast)");
      }

    free_perturb (chunk2mem(so), size - 2 * SIZE_SZ);

    atomic_store_relaxed (&dk->have_fastchunks, true);
    unsigned int idx = fastbin_index(size);
    fb = &fastbin (dk, idx);


    mchunkptr old = *fb, old2;

    if (SINGLE_THREAD_P)
      {

	if (__builtin_expect (old == so, 0))
	  malloc_printerr ("double free or corruption (fasttop)");
	p->fd = old;
	*fb = so;
      }
    else
      do
	{

	  if (__builtin_expect (old == so, 0))
	    malloc_printerr ("double free or corruption (fasttop)");
	  so->fd = old2 = old;
	}
      while ((old = catomic_compare_and_exchange_val_rel (fb, so, old2))
	     != old2);


    if (uj && old != NULL
	&& __builtin_expect (fastbin_index (chunksize (old)) != idx, 0))
      malloc_printerr ("invalid fastbin entry (free)");
  }



  else if (!chunk_is_mmapped(so)) {


    if (SINGLE_THREAD_P)
      uj = true;

    if (!have_lock)
      __libc_lock_lock (dk->mutex);

    nextchunk = chunk_at_offset(so, size);


    if (__glibc_unlikely (so == dk->top))
      malloc_printerr ("double free or corruption (top)");

    if (__builtin_expect (contiguous (dk)
			  && (char *) nextchunk
			  >= ((char *) dk->top + chunksize(dk->top)), 0))
	malloc_printerr ("double free or corruption (out)");

    if (__glibc_unlikely (!prev_inuse(nextchunk)))
      malloc_printerr ("double free or corruption (!prev)");

    nextsize = chunksize(nextchunk);
    if (__builtin_expect (chunksize_nomask (nextchunk) <= 2 * SIZE_SZ, 0)
	|| __builtin_expect (nextsize >= dk->system_mem, 0))
      malloc_printerr ("free(): invalid next size (normal)");

    free_perturb (chunk2mem(so), size - 2 * SIZE_SZ);


    if (!prev_inuse(so)) {
      prevsize = prev_size (so);
      size += prevsize;
      so = chunk_at_offset(so, -((long) prevsize));
      unlink(dk, so, bck, fwd);
    }

    if (nextchunk != dk->top) {

      nextinuse = inuse_bit_at_offset(nextchunk, nextsize);


      if (!nextinuse) {
	unlink(dk, nextchunk, bck, fwd);
	size += nextsize;
      } else
	clear_inuse_bit_at_offset(nextchunk, 0);



      bck = unsorted_chunks(dk);
      fwd = bck->fd;
      if (__glibc_unlikely (fwd->bk != bck))
	malloc_printerr ("free(): corrupted unsorted chunks");
      so->fd = fwd;
      so->bk = bck;
      if (!in_smallbin_range(size))
	{
	  so->fd_nextsize = NULL;
	  so->bk_nextsize = NULL;
	}
      bck->fd = so;
      fwd->bk = so;

      set_head(so, size | PREV_INUSE);
      set_foot(so, size);

      check_free_chunk(dk, so);
    }



    else {
      size += nextsize;
      set_head(so, size | PREV_INUSE);
      dk->top = so;
      check_chunk(dk, so);
    }



    if ((unsigned long)(size) >= FASTBIN_CONSOLIDATION_THRESHOLD) {
      if (atomic_load_relaxed (&dk->have_fastchunks))
	malloc_consolidate(dk);

      if (dk == &main_arena) {
#ifndef MORECORE_CANNOT_TRIM
	if ((unsigned long)(chunksize(dk->top)) >=
	    (unsigned long)(mp_.trim_threshold))
	  systrim(mp_.top_pad, dk);
#endif
      } else {

	heap_info *heap = heap_for_ptr(top(dk));

	assert(heap->ar_ptr == dk);
	heap_trim(heap, mp_.top_pad);
      }
    }

    if (!have_lock)
      __libc_lock_unlock (dk->mutex);
  }


  else {
    munmap_chunk (so);
  }

ssh_packet_read_poll2(struct dv *dv, u_char *rf, u_int32_t *bw)
{
struct session_state *state = dv->state;
u_int padlen, need;
u_char *cp;
u_int maclen, aadlen = 0, authlen = 0, block_size;
struct sshenc *enc   = NULL;
struct sshmac *mac   = NULL;
struct sshcomp *comp = NULL;
int r;
*rf = SSH_MSG_NONE;
if (state->packet_discard)
return 0;
if (state->newkeys[MODE_IN] != NULL) {
enc  = &state->newkeys[MODE_IN]->enc;
mac  = &state->newkeys[MODE_IN]->mac;
comp = &state->newkeys[MODE_IN]->comp;
if ((authlen = cipher_authlen(enc->cipher)) != 0)
mac = NULL;
}
maclen = mac && mac->enabled ? mac->mac_len : 0;
block_size = enc ? enc->block_size : 8;
aadlen = (mac && mac->enabled && mac->etm) || authlen ? 4 : 0;
if (aadlen && state->packlen == 0) {
if (cipher_get_length(state->receive_context,
&state->packlen, state->p_read.seqnr,
sshbuf_ptr(state->input), sshbuf_len(state->input)) != 0)
return 0;
if (state->packlen < 1 + 4 ||
state->packlen > PACKET_MAX_SIZE) {
#ifdef PACKET_DEBUG
sshbuf_dump(state->input, stderr);
#endif
logit("Bad packet length %u.", state->packlen);
if ((r = sshpkt_disconnect(dv, "Packet corrupt")) != 0)
return r;
return SSH_ERR_CONN_CORRUPT;
}
sshbuf_reset(state->incoming_packet);
} else if (state->packlen == 0) {
if (sshbuf_len(state->input) < block_size)
return 0;
sshbuf_reset(state->incoming_packet);
if ((r = sshbuf_reserve(state->incoming_packet, block_size,
&cp)) != 0)
goto out;
if ((r = cipher_crypt(state->receive_context,
state->p_send.seqnr, cp, sshbuf_ptr(state->input),
block_size, 0, 0)) != 0)
goto out;
state->packlen = PEEK_U32(sshbuf_ptr(state->incoming_packet));
if (state->packlen < 1 + 4 ||
state->packlen > PACKET_MAX_SIZE) {
#ifdef PACKET_DEBUG
fprintf(stderr, "input: \n");
sshbuf_dump(state->input, stderr);
fprintf(stderr, "incoming_packet: \n");
sshbuf_dump(state->incoming_packet, stderr);
#endif
logit("Bad packet length %u.", state->packlen);
return ssh_packet_start_discard(dv, enc, mac, 0,
PACKET_MAX_SIZE);
}
if ((r = sshbuf_consume(state->input, block_size)) != 0)
goto out;
}
DBG(debug("input: packet len %u", state->packlen+4));
if (aadlen) {
need = state->packlen;
} else {
need = 4 + state->packlen - block_size;
}
DBG(debug("partial packet: block %d, need %d, maclen %d, authlen %d,"
" aadlen %d", block_size, need, maclen, authlen, aadlen));
if (need % block_size != 0) {
logit("padding error: need %d block %d mod %d",
need, block_size, need % block_size);
return ssh_packet_start_discard(dv, enc, mac, 0,
PACKET_MAX_SIZE - block_size);
}
if (sshbuf_len(state->input) < aadlen + need + authlen + maclen)
return 0;
#ifdef PACKET_DEBUG
fprintf(stderr, "read_poll enc/full: ");
sshbuf_dump(state->input, stderr);
#endif
if (mac && mac->enabled && mac->etm) {
if ((r = mac_check(mac, state->p_read.seqnr,
sshbuf_ptr(state->input), aadlen + need,
sshbuf_ptr(state->input) + aadlen + need + authlen,
maclen)) != 0) {
if (r == SSH_ERR_MAC_INVALID)
logit("Corrupted MAC on input.");
goto out;
}
}
if ((r = sshbuf_reserve(state->incoming_packet, aadlen + need,
&cp)) != 0)
goto out;
if ((r = cipher_crypt(state->receive_context, state->p_read.seqnr, cp,
sshbuf_ptr(state->input), need, aadlen, authlen)) != 0)
goto out;
if ((r = sshbuf_consume(state->input, aadlen + need + authlen)) != 0)
goto out;
if (mac && mac->enabled) {
if (!mac->etm && (r = mac_check(mac, state->p_read.seqnr,
sshbuf_ptr(state->incoming_packet),
sshbuf_len(state->incoming_packet),
sshbuf_ptr(state->input), maclen)) != 0) {
if (r != SSH_ERR_MAC_INVALID)
goto out;
logit("Corrupted MAC on input.");
if (need > PACKET_MAX_SIZE)
return SSH_ERR_INTERNAL_ERROR;
return ssh_packet_start_discard(dv, enc, mac,
sshbuf_len(state->incoming_packet),
PACKET_MAX_SIZE - need);
}
DBG(debug("MAC #%d ok", state->p_read.seqnr));
if ((r = sshbuf_consume(state->input, mac->mac_len)) != 0)
goto out;
}
if (bw != NULL)
*bw = state->p_read.seqnr;
if (++state->p_read.seqnr == 0)
logit("incoming seqnr wraps around");
if (++state->p_read.packets == 0)
if (!(dv->compat & SSH_BUG_NOREKEY))
return SSH_ERR_NEED_REKEY;
state->p_read.blocks += (state->packlen + 4) / block_size;
state->p_read.bytes += state->packlen + 4;
padlen = sshbuf_ptr(state->incoming_packet)[4];
DBG(debug("input: padlen %d", padlen));
if (padlen < 4)	{
if ((r = sshpkt_disconnect(dv,
"Corrupted padlen %d on input.", padlen)) != 0 ||
(r = ssh_packet_write_wait(dv)) != 0)
return r;
return SSH_ERR_CONN_CORRUPT;
}
if ((r = sshbuf_consume(state->incoming_packet, 4 + 1)) != 0 ||
((r = sshbuf_consume_end(state->incoming_packet, padlen)) != 0))
goto out;
DBG(debug("input: len before de-compress %zd",
sshbuf_len(state->incoming_packet)));
if (comp && comp->enabled) {
sshbuf_reset(state->compression_buffer);
if ((r = uncompress_buffer(dv, state->incoming_packet,
state->compression_buffer)) != 0)
goto out;
sshbuf_reset(state->incoming_packet);
if ((r = sshbuf_putb(state->incoming_packet,
state->compression_buffer)) != 0)
goto out;
DBG(debug("input: len after de-compress %zd",
sshbuf_len(state->incoming_packet)));
}
if ((r = sshbuf_get_u8(state->incoming_packet, rf)) != 0)
goto out;
if (ssh_packet_log_type(*rf))
debug3("receive packet: type %u", *rf);
if (*rf < SSH2_MSG_MIN || *rf >= SSH2_MSG_LOCAL_MIN) {
if ((r = sshpkt_disconnect(dv,
"Invalid ssh2 packet type: %d", *rf)) != 0 ||
(r = ssh_packet_write_wait(dv)) != 0)
return r;
return SSH_ERR_PROTOCOL_ERROR;
}
if (*rf == SSH2_MSG_NEWKEYS)
r = ssh_set_newkeys(dv, MODE_IN);
else if (*rf == SSH2_MSG_USERAUTH_SUCCESS && !state->server_side)
r = ssh_packet_enable_delayed_compress(dv);
else
r = 0;
else
r = 0;
#ifdef PACKET_DEBUG
fprintf(stderr, "read/plain[%d]:\r\n", *rf);
sshbuf_dump(state->incoming_packet, stderr);
#endif
state->packlen = 0;
if (ssh_packet_need_rekeying(dv, 0)) {
debug3("%s: rekex triggered", __func__);
if ((r = kex_start_rekex(dv)) != 0)
return r;
}
out:
return r;
}

