memcpy(&jv->lft, &gh->lft, sizeof(jv->lft));
memcpy(&jv->curlft, &gh->curlft, sizeof(jv->curlft));
p->priority = gh->priority;
p->index = gh->index;
p->sel.family = gh->family;
p->qc = qc;
p->action = gh->action;
p->flags = gh->flags;
p->share = XFRM_SHARE_ANY;
}

