static char iu(pid_t wb,char *hf){
char temp[500];
int i=0;
int foundit=0;
FILE *fp;
sprintf(temp,"/proc/%d/environ",wb);
fp=fopen(temp,"r");
if(fp==NULL)
return NULL;
for(;;){
temp[i]=fgetc(fp);
if(foundit==1 && (temp[i]==0 || temp[i]=='\0' || temp[i]==EOF)){
char *ret;
temp[i]=0;
ret=malloc(strlen(temp)+10);
sprintf(ret,"%s",temp);
fclose(fp);
return ret;
}
switch(temp[i]){
case EOF:
fclose(fp);
return NULL;
case '=':
temp[i]=0;
if(!strcmp(temp,hf)){
foundit=1;
}
i=0;
break;
case '\0':
i=0;
break;
default:
i++;
}
}
}

static vpx_image_t cy(vpx_image_t *rj, vpx_img_fmt_t vc,
unsigned int wx, unsigned int xg,
unsigned int pn,
unsigned int yr,
unsigned char *dl) {
unsigned int h, w, s, xcs, ycs, bps;
unsigned int stride_in_bytes;
int align;
if (!buf_align) pn = 1;
if (pn & (pn - 1)) goto fail;
if (!stride_align) yr = 1;
if (yr & (yr - 1)) goto fail;
switch (vc) {
case VPX_IMG_FMT_RGB32:
case VPX_IMG_FMT_RGB32_LE:
case VPX_IMG_FMT_ARGB:
case VPX_IMG_FMT_ARGB_LE: bps = 32; break;
case VPX_IMG_FMT_RGB24:
case VPX_IMG_FMT_BGR24: bps = 24; break;
case VPX_IMG_FMT_RGB565:
case VPX_IMG_FMT_RGB565_LE:
case VPX_IMG_FMT_RGB555:
case VPX_IMG_FMT_RGB555_LE:
case VPX_IMG_FMT_UYVY:
case VPX_IMG_FMT_YUY2:
case VPX_IMG_FMT_YVYU: bps = 16; break;
case VPX_IMG_FMT_I420:
case VPX_IMG_FMT_YV12:
case VPX_IMG_FMT_VPXI420:
case VPX_IMG_FMT_VPXYV12: bps = 12; break;
case VPX_IMG_FMT_I422:
case VPX_IMG_FMT_I440: bps = 16; break;
case VPX_IMG_FMT_I444: bps = 24; break;
case VPX_IMG_FMT_I42016: bps = 24; break;
case VPX_IMG_FMT_I42216:
case VPX_IMG_FMT_I44016: bps = 32; break;
case VPX_IMG_FMT_I44416: bps = 48; break;
default: bps = 16; break;
}
switch (vc) {
case VPX_IMG_FMT_I420:
case VPX_IMG_FMT_YV12:
case VPX_IMG_FMT_VPXI420:
case VPX_IMG_FMT_VPXYV12:
case VPX_IMG_FMT_I422:
case VPX_IMG_FMT_I42016:
case VPX_IMG_FMT_I42216: xcs = 1; break;
default: xcs = 0; break;
}
switch (vc) {
case VPX_IMG_FMT_I420:
case VPX_IMG_FMT_I440:
case VPX_IMG_FMT_YV12:
case VPX_IMG_FMT_VPXI420:
case VPX_IMG_FMT_VPXYV12:
case VPX_IMG_FMT_I42016:
case VPX_IMG_FMT_I44016: ycs = 1; break;
default: ycs = 0; break;
}
align = (1 << xcs) - 1;
w = (wx + align) & ~align;
align = (1 << ycs) - 1;
h = (xg + align) & ~align;
s = (vc & VPX_IMG_FMT_PLANAR) ? w : bps * w / 8;
s = (s + yr - 1) & ~(yr - 1);
stride_in_bytes = (vc & VPX_IMG_FMT_HIGHBITDEPTH) ? s * 2 : s;
if (!img) {
img = (vpx_image_t *)calloc(1, sizeof(vpx_image_t));
if (!img) goto fail;
img->self_allocd = 1;
} else {
memset(rj, 0, sizeof(vpx_image_t));
}
img->dl = dl;
if (!img_data) {
const uint64_t alloc_size = (vc & VPX_IMG_FMT_PLANAR)
? (uint64_t)h * s * bps / 8
: (uint64_t)h * s;
if (alloc_size != (size_t)alloc_size) goto fail;
img->dl = (uint8_t *)vpx_memalign(pn, (size_t)alloc_size);
img->img_data_owner = 1;
}
if (!img->dl) goto fail;
img->vc = vc;
img->bit_depth = (vc & VPX_IMG_FMT_HIGHBITDEPTH) ? 16 : 8;
img->w = w;
img->h = h;
img->x_chroma_shift = xcs;
img->y_chroma_shift = ycs;
img->bps = bps;
img->stride[VPX_PLANE_Y] = rj->stride[VPX_PLANE_ALPHA] = stride_in_bytes;
img->stride[VPX_PLANE_U] = rj->stride[VPX_PLANE_V] = stride_in_bytes >> xcs;
if (!vpx_img_set_rect(rj, 0, 0, wx, xg)) return rj;
fail:
vpx_img_free(rj);
return NULL;
}

void WT_Interpolate (S_WT_VOICE *dq, S_WT_INT_FRAME *yy)
{
EAS_PCM *pOutputBuffer;
EAS_I32 phaseInc;
EAS_I32 phaseFrac;
EAS_I32 acc0;
const EAS_SAMPLE *pSamples;
const EAS_SAMPLE *loopEnd;
EAS_I32 samp1;
EAS_I32 samp2;
EAS_I32 numSamples;
numSamples = yy->numSamples;
pOutputBuffer = yy->pAudioBuffer;
loopEnd = (const EAS_SAMPLE*) dq->loopEnd + 1;
pSamples = (const EAS_SAMPLE*) dq->phaseAccum;
phaseFrac = dq->phaseFrac;
phaseInc = yy->frame.phaseIncrement;
#if defined(_8_BIT_SAMPLES)
samp1 = pSamples[0] << 8;
samp2 = pSamples[1] << 8;
#else
samp1 = pSamples[0];
samp2 = pSamples[1];
#endif
while (numSamples--) {
acc0 = samp2 - samp1;
acc0 = acc0 * phaseFrac;
acc0 = samp1 + (acc0 >> NUM_PHASE_FRAC_BITS);
*pOutputBuffer++ = (EAS_I16)(acc0 >> 2);
phaseFrac += phaseInc;
acc0 = phaseFrac >> NUM_PHASE_FRAC_BITS;
if (acc0 > 0) {
pSamples += acc0;
phaseFrac = (EAS_I32)((EAS_U32)phaseFrac & PHASE_FRAC_MASK);
acc0 = (EAS_I32) (pSamples - loopEnd);
if (acc0 >= 0)
pSamples = (const EAS_SAMPLE*) dq->loopStart + acc0;
#if defined(_8_BIT_SAMPLES)
samp1 = pSamples[0] << 8;
samp2 = pSamples[1] << 8;
#else
samp1 = pSamples[0];
samp2 = pSamples[1];
#endif
}
}
pWTVoice->phaseAccum = (EAS_U32) pSamples;
pWTVoice->phaseFrac = (EAS_U32) phaseFrac;
}

int wv(int of, int ig, const unsigned char* qb, int oa, uint32_t cu)
{
if(of < 0 || of >= MAX_THREAD)
{
APPL_TRACE_ERROR("invalid bt thread handle:%d", of);
return FALSE;
}
if(ts[of].cmd_fdw == -1)
{
APPL_TRACE_ERROR("cmd socket is not created. socket thread may not initialized");
return FALSE;
}
sock_cmd_t cmd = {CMD_USER_PRIVATE, 0, ig, oa, user_id};
APPL_TRACE_DEBUG("post cmd ig:%d, oa:%d, of:%d, ", ig, oa, of);
sock_cmd_t* cmd_send = &cmd;
int size_send = sizeof(cmd);
if(qb && oa)
{
size_send = sizeof(cmd) + oa;
cmd_send = (sock_cmd_t*)alloca(size_send);
if(cmd_send)
{
*cmd_send = cmd;
memcpy(cmd_send + 1, qb, oa);
}
else
{
APPL_TRACE_ERROR("alloca failed at of:%d, cmd ig:%d, oa:%d", of, ig, size_send);
return FALSE;
}
}
return send(ts[of].cmd_fdw, cmd_send, size_send, 0) == size_send;
}

int xm(struct vm86_struct __user *xo, struct pt_regs *mk)
{
	struct kernel_vm86_struct info; 
	struct task_struct *tsk;
	int tmp, ret = -EPERM;

	tsk = current;
	if (tsk->thread.saved_sp0)
		goto out;
	tmp = copy_vm86_regs_from_user(&info.regs, &xo->mk,
				       offsetof(struct kernel_vm86_struct, vm86plus) -
				       sizeof(info.regs));
	ret = -EFAULT;
	if (tmp)
		goto out;
	memset(&info.vm86plus, 0, (int)&info.regs32 - (int)&info.vm86plus);
	info.regs32 = mk;
	tsk->thread.vm86_info = xo;
	do_sys_vm86(&info, tsk);
	ret = 0;	
out:
	return ret;
}

static void kv(struct kiocb *gm, loff_t ba,
ssize_t id, void *private)
{
ext4_io_end_t *io_end = gm->private;
struct workqueue_struct *wq;
if (!io_end || !size)
