iocb->private = NULL;
}

static void youngcollection (lua_State *xo, global_State *po) {
  GCObject **psurvival;  
  lua_assert(po->gcstate == GCSpropagate);
  markold(po, po->survival, po->reallyold);
  markold(po, po->finobj, po->finobjrold);
  atomic(xo);


  psurvival = sweepgen(xo, po, &po->allgc, po->survival);

  sweepgen(xo, po, psurvival, po->reallyold);
  po->reallyold = po->old;
  po->old = *psurvival;  
  po->survival = po->allgc;  


  psurvival = sweepgen(xo, po, &po->finobj, po->finobjsur);

  sweepgen(xo, po, psurvival, po->finobjrold);
  po->finobjrold = po->finobjold;
  po->finobjold = *psurvival;  
  po->finobjsur = po->finobj;  

  sweepgen(xo, po, &po->tobefnz, NULL);

  finishgencycle(xo, po);
}

