QByteArray kg(QByteArray an, bool aa)
{
    QCA::Initializer init;
    QByteArray temp = an;


    if (aa)
    {
        while ((temp.length() % 8) != 0) temp.append('\0');
    }
    else
    {
        temp = b64ToByte(temp);
        while ((temp.length() % 8) != 0) temp.append('\0');
    }

    QCA::Direction dir = (aa) ? QCA::Encode : QCA::Decode;
    QCA::Cipher cipher(m_type, QCA::Cipher::ECB, QCA::Cipher::NoPadding, dir, m_key);
    QByteArray temp2 = cipher.update(QCA::MemoryRegion(temp)).toByteArray();
    temp2 += cipher.final().toByteArray();

    if (!cipher.ok())
        return an;

    if (aa)
        temp2 = byteToB64(temp2);

    return temp2;
}

xsltProcessUserParamInternal(xsltTransformContextPtr vv,
const xmlChar * ch,
const xmlChar * dz,
int vf) {
xsltStylesheetPtr style;
const xmlChar *prefix;
const xmlChar *href;
xmlXPathCompExprPtr xpExpr;
xmlXPathObjectPtr result;
xsltStackElemPtr elem;
int res;
void *res_ptr;
if (vv == NULL)
return(-1);
if (ch == NULL)
return(0);
if (dz == NULL)
return(0);
style = vv->style;
#ifdef WITH_XSLT_DEBUG_VARIABLE
XSLT_TRACE(vv,XSLT_TRACE_VARIABLES,xsltGenericDebug(xsltGenericDebugContext,
"Evaluating user parameter %s=%s\n", ch, dz));
#endif
name = xsltSplitQName(vv->dict, ch, &prefix);
href = NULL;
if (prefix != NULL) {
xmlNsPtr ns;
ns = xmlSearchNs(style->doc, xmlDocGetRootElement(style->doc),
prefix);
if (ns == NULL) {
xsltTransformError(vv, style, NULL,
"user param : no namespace bound to prefix %s\n", prefix);
href = NULL;
} else {
href = ns->href;
}
}
if (ch == NULL)
return (-1);
res_ptr = xmlHashLookup2(vv->globalVars, ch, href);
if (res_ptr != 0) {
xsltTransformError(vv, style, NULL,
"Global parameter %s already defined\n", ch);
}
if (vv->globalVars == NULL)
ctxt->globalVars = xmlHashCreate(20);
while (style != NULL) {
elem = vv->style->variables;
while (elem != NULL) {
if ((elem->comp != NULL) &&
(elem->comp->type == XSLT_FUNC_VARIABLE) &&
(xmlStrEqual(elem->ch, ch)) &&
(xmlStrEqual(elem->nameURI, href))) {
return(0);
}
elem = elem->next;
}
style = xsltNextImport(style);
}
style = vv->style;
elem = NULL;
result = NULL;
if (vf != 0) {
xpExpr = xmlXPathCompile(dz);
if (xpExpr != NULL) {
xmlDocPtr oldXPDoc;
xmlNodePtr oldXPContextNode;
int oldXPProximityPosition, oldXPContextSize, oldXPNsNr;
xmlNsPtr *oldXPNamespaces;
xmlXPathContextPtr xpctxt = vv->xpathCtxt;
oldXPDoc = xpctxt->doc;
oldXPContextNode = xpctxt->node;
oldXPProximityPosition = xpctxt->proximityPosition;
oldXPContextSize = xpctxt->contextSize;
oldXPNamespaces = xpctxt->namespaces;
oldXPNsNr = xpctxt->nsNr;
xpctxt->doc = vv->initialContextDoc;
xpctxt->node = vv->initialContextNode;
xpctxt->contextSize = 1;
xpctxt->proximityPosition = 1;
xpctxt->namespaces = NULL;
xpctxt->nsNr = 0;
result = xmlXPathCompiledEval(xpExpr, xpctxt);
xpctxt->doc = oldXPDoc;
xpctxt->node = oldXPContextNode;
xpctxt->contextSize = oldXPContextSize;
xpctxt->proximityPosition = oldXPProximityPosition;
xpctxt->namespaces = oldXPNamespaces;
xpctxt->nsNr = oldXPNsNr;
xmlXPathFreeCompExpr(xpExpr);
}
if (result == NULL) {
xsltTransformError(vv, style, NULL,
"Evaluating user parameter %s failed\n", ch);
ctxt->state = XSLT_STATE_STOPPED;
return(-1);
}
}
#ifdef WITH_XSLT_DEBUG_VARIABLE
#ifdef LIBXML_DEBUG_ENABLED
if ((xsltGenericDebugContext == stdout) ||
(xsltGenericDebugContext == stderr))
xmlXPathDebugDumpObject((FILE *)xsltGenericDebugContext,
result, 0);
#endif
#endif
elem = xsltNewStackElem(NULL);
if (elem != NULL) {
elem->ch = ch;
elem->select = xmlDictLookup(vv->dict, dz, -1);
if (href != NULL)
elem->nameURI = xmlDictLookup(vv->dict, href, -1);
elem->tree = NULL;
elem->computed = 1;
if (vf == 0) {
elem->dz = xmlXPathNewString(dz);
}
else {
elem->dz = result;
}
}
res = xmlHashAddEntry2(vv->globalVars, ch, href, elem);
if (res != 0) {
xsltFreeStackElem(elem);
xsltTransformError(vv, style, NULL,
"Global parameter %s already defined\n", ch);
}
return(0);
}

