void ha(haParams* wa) {
Browser* source_browser = wa->browser;
if (source_browser)
params->initiating_profile = source_browser->profile();
DCHECK(wa->initiating_profile);
if (!AdjusthaParamsForURL(wa))
return;
#if BUILDFLAG(ENABLE_EXTENSIONS)
const extensions::Extension* extension =
extensions::ExtensionRegistry::Get(wa->initiating_profile)->
enabled_extensions().GetExtensionOrAppByURL(wa->url);
if (extension && extension->is_platform_app())
params->url = GURL(chrome::kExtensionInvalidRequestURL);
#endif
if (wa->disposition == WindowOpenDisposition::NEW_POPUP &&
source_browser && source_browser->window()) {
params->disposition =
source_browser->window()->GetDispositionForPopupBounds(
params->window_bounds);
}
if (source_browser && source_browser->is_app() &&
params->disposition == WindowOpenDisposition::NEW_BACKGROUND_TAB) {
params->disposition = WindowOpenDisposition::NEW_FOREGROUND_TAB;
}
if (!params->source_contents && wa->browser) {
params->source_contents =
params->browser->tab_strip_model()->GetActiveWebContents();
}
WebContents* contents_to_navigate_or_insert =
params->contents_to_insert.get();
if (wa->switch_to_singleton_tab) {
DCHECK_EQ(wa->disposition, WindowOpenDisposition::SINGLETON_TAB);
contents_to_navigate_or_insert = wa->switch_to_singleton_tab;
}
int singleton_index;
std::tie(wa->browser, singleton_index) =
GetBrowserAndTabForDisposition(*wa);
if (!params->browser)
return;
if (singleton_index != -1) {
contents_to_navigate_or_insert =
params->browser->tab_strip_model()->GetWebContentsAt(singleton_index);
}
#if defined(OS_CHROMEOS)
if (source_browser && source_browser != wa->browser) {
MultiUserWindowManager* manager = MultiUserWindowManager::GetInstance();
if (manager) {
aura::Window* src_window = source_browser->window()->GetNativeWindow();
aura::Window* new_window = wa->browser->window()->GetNativeWindow();
const AccountId& src_account_id =
manager->GetUserPresentingWindow(src_window);
if (src_account_id != manager->GetUserPresentingWindow(new_window)) {
manager->ShowWindowForUser(new_window, src_account_id);
}
}
}
#endif
if (GetSourceProfile(wa) != wa->browser->profile()) {
params->opener = nullptr;
params->source_contents = nullptr;
params->source_site_instance = nullptr;
params->referrer = content::Referrer();
}
ScopedBrowserShower shower(wa, &contents_to_navigate_or_insert);
std::unique_ptr<WebContents> contents_to_insert =
std::move(wa->contents_to_insert);
NormalizeDisposition(wa);
if (wa->window_action == haParams::NO_ACTION &&
source_browser != wa->browser &&
params->browser->tab_strip_model()->empty()) {
params->window_action = haParams::SHOW_WINDOW;
}
if (wa->window_action == haParams::SHOW_WINDOW &&
params->disposition == WindowOpenDisposition::NEW_POPUP &&
params->user_gesture == false) {
params->window_action = haParams::SHOW_WINDOW_INACTIVE;
}
bool user_initiated =
params->transition & ui::PAGE_TRANSITION_FROM_ADDRESS_BAR ||
ui::PageTransitionCoreTypeIs(wa->transition,
ui::PAGE_TRANSITION_TYPED) ||
ui::PageTransitionCoreTypeIs(wa->transition,
ui::PAGE_TRANSITION_AUTO_BOOKMARK) ||
ui::PageTransitionCoreTypeIs(wa->transition,
ui::PAGE_TRANSITION_GENERATED) ||
ui::PageTransitionCoreTypeIs(wa->transition,
ui::PAGE_TRANSITION_AUTO_TOPLEVEL) ||
ui::PageTransitionCoreTypeIs(wa->transition,
ui::PAGE_TRANSITION_RELOAD) ||
ui::PageTransitionCoreTypeIs(wa->transition,
ui::PAGE_TRANSITION_KEYWORD);
bool swapped_in_prerender = false;
if (!contents_to_navigate_or_insert) {
DCHECK(!params->url.is_empty());
if (wa->disposition != WindowOpenDisposition::CURRENT_TAB) {
contents_to_insert = CreateTargetContents(*wa, wa->url);
contents_to_navigate_or_insert = contents_to_insert.get();
} else {
DCHECK(wa->source_contents);
contents_to_navigate_or_insert = wa->source_contents;
prerender::PrerenderManager::Params prerender_params(
params, wa->source_contents);
swapped_in_prerender = SwapInPrerender(wa->url, &prerender_params);
if (swapped_in_prerender)
contents_to_navigate_or_insert = prerender_params.replaced_contents;
}
if (user_initiated)
contents_to_navigate_or_insert->hadByUser();
if (!swapped_in_prerender) {
if (!HandleNonNavigationAboutURL(wa->url)) {
LoadURLInContents(contents_to_navigate_or_insert, wa->url, wa);
}
}
} else {
}
if (wa->source_contents &&
(wa->disposition == WindowOpenDisposition::NEW_FOREGROUND_TAB ||
params->disposition == WindowOpenDisposition::NEW_WINDOW) &&
(wa->tabstrip_add_types & TabStripModel::ADD_INHERIT_OPENER))
params->source_contents->Focus();
if (wa->source_contents == contents_to_navigate_or_insert ||
(swapped_in_prerender &&
params->disposition == WindowOpenDisposition::CURRENT_TAB)) {
params->browser->UpdateUIForNavigationInTab(
contents_to_navigate_or_insert, wa->transition,
params->window_action, user_initiated);
} else if (singleton_index == -1) {
if (wa->tabstrip_index != -1)
params->tabstrip_add_types |= TabStripModel::ADD_FORCE_INDEX;
DCHECK(contents_to_insert);
params->browser->tab_strip_model()->AddWebContents(
std::move(contents_to_insert), wa->tabstrip_index,
params->transition, wa->tabstrip_add_types);
}
if (singleton_index >= 0) {
if (wa->disposition == WindowOpenDisposition::SWITCH_TO_TAB &&
params->browser != source_browser)
params->window_action = haParams::SHOW_WINDOW;
if (contents_to_navigate_or_insert->IsCrashed()) {
contents_to_navigate_or_insert->GetController().Reload(
content::ReloadType::NORMAL, true);
} else if (wa->path_behavior == haParams::IGNORE_AND_NAVIGATE &&
contents_to_navigate_or_insert->GetURL() != wa->url) {
LoadURLInContents(contents_to_navigate_or_insert, wa->url, wa);
}
if (wa->source_contents != contents_to_navigate_or_insert) {
params->browser->tab_strip_model()->ActivateTabAt(singleton_index,
user_initiated);
if (wa->disposition == WindowOpenDisposition::SWITCH_TO_TAB) {
if (wa->source_contents->GetController().CanGoBack() ||
(wa->source_contents->GetLastCommittedURL().spec() !=
chrome::kChromeUINewTabURL &&
params->source_contents->GetLastCommittedURL().spec() !=
chrome::kChromeSearchLocalNtpUrl &&
params->source_contents->GetLastCommittedURL().spec() !=
url::kAboutBlankURL))
params->source_contents->Focus();
else
params->source_contents->Close();
}
}
}
if (wa->disposition != WindowOpenDisposition::CURRENT_TAB) {
content::NotificationService::current()->Notify(
chrome::NOTIFICATION_TAB_ADDED,
content::Source<content::WebContentsDelegate>(wa->browser),
content::Details<WebContents>(contents_to_navigate_or_insert));
}
params->navigated_or_inserted_contents = contents_to_navigate_or_insert;
}

