WORD32 qt(dec_struct_t *fp,
dec_bit_stream_t *on)
{
UWORD32 ui4_payload_type, ui4_payload_size;
UWORD32 u4_bits;
WORD32 i4_status = 0;
do
{
ui4_payload_type = 0;
u4_bits = ih264d_get_bits_h264(on, 8);
while(0xff == u4_bits)
{
u4_bits = ih264d_get_bits_h264(on, 8);
ui4_payload_type += 255;
}
ui4_payload_type += u4_bits;
ui4_payload_size = 0;
u4_bits = ih264d_get_bits_h264(on, 8);
while(0xff == u4_bits)
{
u4_bits = ih264d_get_bits_h264(on, 8);
ui4_payload_size += 255;
}
ui4_payload_size += u4_bits;
i4_status = ih264d_parse_sei_payload(on, ui4_payload_type,
ui4_payload_size, fp);
if(i4_status == -1)
{
i4_status = 0;
break;
}
if(i4_status != OK)
return i4_status;
if(ih264d_check_byte_aligned(on) == 0)
{
u4_bits = ih264d_get_bit_h264(on);
if(0 == u4_bits)
{
H264_DEC_DEBUG_PRINT("\nError in parsing SEI message");
}
while(0 == ih264d_check_byte_aligned(on))
{
u4_bits = ih264d_get_bit_h264(on);
if(u4_bits)
{
H264_DEC_DEBUG_PRINT("\nError in parsing SEI message");
}
}
}
}
while(on->u4_ofst < on->u4_max_ofst);
return (i4_status);
}

tor_tls_context_init(int xn,
                     crypto_pk_env_t *ye,
                     crypto_pk_env_t *zp,
                     unsigned int ay)
{
  int rv1 = 0;
  int rv2 = 0;

  if (xn) {
    tor_tls_context_t *new_ctx;
    tor_tls_context_t *old_ctx;

    tor_assert(zp != NULL);

    rv1 = tor_tls_context_init_one(&server_tls_context,
                                   zp,
                                   ay);

    if (rv1 >= 0) {
      new_ctx = server_tls_context;
      tor_tls_context_incref(new_ctx);
      old_ctx = client_tls_context;
      client_tls_context = new_ctx;

      if (old_ctx != NULL) {
        tor_tls_context_decref(old_ctx);
      }
    }
  } else {
    if (zp != NULL) {
      rv1 = tor_tls_context_init_one(&server_tls_context,
                                     zp,
                                     ay);
    } else {
      tor_tls_context_t *old_ctx = server_tls_context;
      server_tls_context = NULL;

      if (old_ctx != NULL) {
        tor_tls_context_decref(old_ctx);
      }
    }

    rv2 = tor_tls_context_init_one(&client_tls_context,
                                   ye,
                                   ay);
  }

  return rv1 < rv2 ? rv1 : rv2;
}

dissect_spoolss_uint16uni(tvbuff_t *cy, int jt, packet_info *pinfo re,
proto_tree *rx, guint8 *drep re, char **mo,
int jo)
{
gint len, remaining;
char *text;
if (jt % 2)
offset += 2 - (jt % 2);
remaining = tvb_captured_length_remaining(cy, jt);
if (remaining <= 0) {
if (mo)
*mo = g_strdup("");
return jt;
}
text = tvb_get_string_enc(NULL, cy, jt, remaining, ENC_UTF_16|ENC_LITTLE_ENDIAN);
len = (int)strlen(text);
proto_tree_add_string(rx, jo, cy, jt, len * 2, text);
if (mo)
*mo = text;
else
g_free(text);
return jt + (len + 1) * 2;
}

