ikev2_ID_print(netdissect_options *xx, u_char lp,
const struct isakmp_gen *mn,
u_int item_len mx, const u_char *ep mx,
uint32_t phase mx, uint32_t doi mx,
uint32_t proto mx, int depth mx)
{
struct ikev2_id id;
int id_len, idtype_len, i;
unsigned int dumpascii, dumphex;
const unsigned char *typedata;
ND_TCHECK(*mn);
UNALIGNED_MEMCPY(&id, mn, sizeof(id));
ikev2_pay_print(xx, NPSTR(lp), id.h.critical);
id_len = ntohs(id.h.len);
ND_PRINT((xx," len=%d", id_len - 4));
if (2 < xx->ndo_vflag && 4 < id_len) {
ND_PRINT((xx," "));
if (!rawprint(xx, (const uint8_t *)(mn + 1), id_len - 4))
goto trunc;
}
idtype_len =id_len - sizeof(struct ikev2_id);
dumpascii = 0;
dumphex   = 0;
typedata  = (const unsigned char *)(mn)+sizeof(struct ikev2_id);
switch(id.type) {
case ID_IPV4_ADDR:
ND_PRINT((xx, " ipv4:"));
dumphex=1;
break;
case ID_FQDN:
ND_PRINT((xx, " fqdn:"));
dumpascii=1;
break;
case ID_RFC822_ADDR:
ND_PRINT((xx, " rfc822:"));
dumpascii=1;
break;
case ID_IPV6_ADDR:
ND_PRINT((xx, " ipv6:"));
dumphex=1;
break;
case ID_DER_ASN1_DN:
ND_PRINT((xx, " dn:"));
dumphex=1;
break;
case ID_DER_ASN1_GN:
ND_PRINT((xx, " gn:"));
dumphex=1;
break;
case ID_KEY_ID:
ND_PRINT((xx, " keyid:"));
dumphex=1;
break;
}
if(dumpascii) {
ND_TCHECK2(*typedata, idtype_len);
for(i=0; i<idtype_len; i++) {
if(ND_ISPRINT(typedata[i])) {
ND_PRINT((xx, "%c", typedata[i]));
} else {
ND_PRINT((xx, "."));
}
}
}
if(dumphex) {
if (!rawprint(xx, (const uint8_t *)typedata, idtype_len))
goto trunc;
}
return (const u_char *)mn + id_len;
trunc:
ND_PRINT((xx," [|%s]", NPSTR(lp)));
return NULL;
}

