video_usercopy(struct sj *sj, unsigned int xn, unsigned long yx,
v4l2_kioctl cd)
{
char	sbuf[128];
void    *mbuf = NULL;
void	*parg = NULL;
long	err  = -EINVAL;
int     is_ext_ctrl;
size_t  ctrls_size = 0;
void __user *user_ptr = NULL;
is_ext_ctrl = (xn == VIDIOC_S_EXT_CTRLS || xn == VIDIOC_G_EXT_CTRLS ||
cmd == VIDIOC_TRY_EXT_CTRLS);
switch (_IOC_DIR(xn)) {
case _IOC_NONE:
parg = NULL;
break;
case _IOC_READ:
case _IOC_WRITE:
case (_IOC_WRITE | _IOC_READ):
if (_IOC_SIZE(xn) <= sizeof(sbuf)) {
parg = sbuf;
} else {
mbuf = kmalloc(_IOC_SIZE(xn), GFP_KERNEL);
if (NULL == mbuf)
return -ENOMEM;
parg = mbuf;
}
err = -EFAULT;
if (_IOC_DIR(xn) & _IOC_WRITE)
if (copy_from_user(parg, (void __user *)yx, _IOC_SIZE(xn)))
goto out;
break;
}
if (is_ext_ctrl) {
struct v4l2_ext_controls *p = parg;
p->error_idx = p->count;
user_ptr = (void __user *)p->controls;
if (p->count) {
ctrls_size = sizeof(struct v4l2_ext_control) * p->count;
mbuf = kmalloc(ctrls_size, GFP_KERNEL);
err = -ENOMEM;
if (NULL == mbuf)
goto out_ext_ctrl;
err = -EFAULT;
if (copy_from_user(mbuf, user_ptr, ctrls_size))
goto out_ext_ctrl;
p->controls = mbuf;
}
}
err = cd(sj, xn, parg);
if (err == -ENOIOCTLCMD)
err = -EINVAL;
if (is_ext_ctrl) {
struct v4l2_ext_controls *p = parg;
p->controls = (void *)user_ptr;
if (p->count && err == 0 && copy_to_user(user_ptr, mbuf, ctrls_size))
err = -EFAULT;
goto out_ext_ctrl;
}
if (err < 0)
goto out;
out_ext_ctrl:
switch (_IOC_DIR(xn)) {
case _IOC_READ:
case (_IOC_WRITE | _IOC_READ):
if (copy_to_user((void __user *)yx, parg, _IOC_SIZE(xn)))
err = -EFAULT;
break;
}
out:
kfree(mbuf);
return err;
}

static long ix(struct media_device *yz,
struct media_entity_desc __user *le)
{
struct media_entity *ent;
struct media_entity_desc u_ent;
if (copy_from_user(&u_ent.id, &le->id, sizeof(u_ent.id)))
return -EFAULT;
ent = find_entity(yz, u_ent.id);
if (ent == NULL)
return -EINVAL;
u_ent.id = ent->id;
if (ent->name) {
strncpy(u_ent.name, ent->name, sizeof(u_ent.name));
u_ent.name[sizeof(u_ent.name) - 1] = '\0';
} else {
memset(u_ent.name, 0, sizeof(u_ent.name));
}
u_ent.type = ent->type;
u_ent.revision = ent->revision;
u_ent.flags = ent->flags;
u_ent.group_id = ent->group_id;
u_ent.pads = ent->num_pads;
u_ent.links = ent->num_links - ent->num_backlinks;
memcpy(&u_ent.raw, &ent->info, sizeof(ent->info));
if (copy_to_user(le, &u_ent, sizeof(u_ent)))
return -EFAULT;
return 0;
}

parse_netscreen_packet(FILE_T gx, struct wtap_pkthdr *mw, Buffer* ja,
char *fp, int *ad, gchar **cy)
{
int		sec;
int		dsec;
char		cap_int[NETSCREEN_MAX_INT_NAME_LENGTH];
char		direction[2];
guint		pkt_len;
char		cap_src[13];
char		cap_dst[13];
guint8		*pd;
gchar		*p;
int		n, i = 0;
guint		offset = 0;
gchar		dststr[13];
phdr->rec_type = REC_TYPE_PACKET;
phdr->presence_flags = WTAP_HAS_TS|WTAP_HAS_CAP_LEN;
if (sscanf(fp, "%9d.%9d: %15[a-z0-9/:.-](%1[io]) len=%9u:%12s->%12s/",
&sec, &dsec, cap_int, direction, &pkt_len, cap_src, cap_dst) < 5) {
*ad = WTAP_ERR_BAD_FILE;
*cy = g_strdup("netscreen: Can't parse packet-header");
return -1;
}
if (pkt_len > WTAP_MAX_PACKET_SIZE) {
*ad = WTAP_ERR_BAD_FILE;
*cy = g_strdup_printf("netscreen: File has %u-byte packet, bigger than maximum of %u",
pkt_len, WTAP_MAX_PACKET_SIZE);
return FALSE;
}
phdr->ts.secs  = sec;
phdr->ts.nsecs = dsec * 100000000;
phdr->len = pkt_len;
ws_buffer_assure_space(ja, pkt_len);
pd = ws_buffer_start_ptr(ja);
while(1) {
if (file_gets(fp, NETSCREEN_LINE_LENGTH, gx) == NULL) {
break;
}
for (p = &fp[0]; g_ascii_isspace(*p); p++)
;
if (*p == '\0') {
break;
}
n = parse_single_hex_dump_line(p, pd, offset);
if (offset == 0 && n < 6) {
if (info_line(fp)) {
if (++i <= NETSCREEN_MAX_INFOLINES) {
continue;
}
} else {
*ad = WTAP_ERR_BAD_FILE;
*cy = g_strdup("netscreen: cannot parse hex-data");
return FALSE;
}
}
if (n == -1) {
*ad = WTAP_ERR_BAD_FILE;
*cy = g_strdup("netscreen: cannot parse hex-data");
return FALSE;
}
offset += n;
if (offset > pkt_len) {
*ad = WTAP_ERR_BAD_FILE;
*cy = g_strdup("netscreen: too much hex-data");
return FALSE;
}
}
if (strncmp(cap_int, "adsl", 4) == 0) {
g_snprintf(dststr, 13, "%02x%02x%02x%02x%02x%02x",
pd[0], pd[1], pd[2], pd[3], pd[4], pd[5]);
if (strncmp(dststr, cap_dst, 12) == 0)
phdr->pkt_encap = WTAP_ENCAP_ETHERNET;
else
phdr->pkt_encap = WTAP_ENCAP_PPP;
}
else if (strncmp(cap_int, "seri", 4) == 0)
phdr->pkt_encap = WTAP_ENCAP_PPP;
else
phdr->pkt_encap = WTAP_ENCAP_ETHERNET;
phdr->caplen = offset;
return TRUE;
}

IMPEG2D_ERROR_CODES_T uj(dec_state_t *qn)
{
UWORD32 i;
yuv_buf_t *ps_cur_frm_buf  = &qn->s_cur_frm_buf;
stream_t *ps_stream       = &qn->s_bit_stream;
UWORD8   *pu1_vld_buf;
