InvalidationSet* tz(const CSSSelector& tp, InvalidationType mx)
{
if (selector.match() == CSSSelector::Class)
return &ensureClassInvalidationSet(selector.value(), mx);
if (selector.isAttributeSelector())
return &ensureAttributeInvalidationSet(selector.attribute().localName(), mx);
if (selector.match() == CSSSelector::Id)
return &ensureIdInvalidationSet(selector.value(), mx);
if (selector.match() == CSSSelector::PseudoClass) {
switch (selector.pseudoType()) {
case CSSSelector::PseudoEmpty:
case CSSSelector::PseudoLink:
case CSSSelector::PseudoVisited:
case CSSSelector::PseudoAnyLink:
case CSSSelector::PseudoAutofill:
case CSSSelector::PseudoHover:
case CSSSelector::PseudoFocus:
case CSSSelector::PseudoActive:
case CSSSelector::PseudoChecked:
case CSSSelector::PseudoEnabled:
case CSSSelector::PseudoDisabled:
case CSSSelector::PseudoOptional:
case CSSSelector::PseudoPlaceholderShown:
case CSSSelector::PseudoRequired:
case CSSSelector::PseudoValid:
case CSSSelector::PseudoInvalid:
case CSSSelector::PseudoIndeterminate:
case CSSSelector::PseudoTarget:
