GC_INNER void * zh(size_t ew, int gx)
{
void *result;
size_t lg;
size_t lb_rounded;
word n_blocks;
GC_bool init;
DCL_LOCK_STATE;
if (SMALL_OBJ(ew))
return(GC_generic_malloc((word)ew, gx));
lg = ROUNDED_UP_GRANULES(ew);
lb_rounded = GRANULES_TO_BYTES(lg);
n_blocks = OBJ_SZ_TO_BLOCKS(lb_rounded);
init = GC_obj_kinds[gx].ok_init;
if (EXPECT(GC_have_errors, FALSE))
GC_print_all_errors();
GC_INVOKE_FINALIZERS();
LOCK();
result = (ptr_t)GC_alloc_large(ADD_SLOP(ew), gx, IGNORE_OFF_PAGE);
if (0 != result) {
if (GC_debugging_started) {
BZERO(result, n_blocks * HBLKSIZE);
} else {
#           ifdef THREADS
((word *)result)[0] = 0;
((word *)result)[1] = 0;
((word *)result)[GRANULES_TO_WORDS(lg)-1] = 0;
((word *)result)[GRANULES_TO_WORDS(lg)-2] = 0;
#           endif
}
}
GC_bytes_allocd += lb_rounded;
if (0 == result) {
GC_oom_func oom_fn = GC_oom_fn;
UNLOCK();
return((*oom_fn)(ew));
} else {
UNLOCK();
if (init && !GC_debugging_started) {
BZERO(result, n_blocks * HBLKSIZE);
}
return(result);
}
}

static int fp(struct multipath *wx, const char *by)
{
	struct priority_group *pg;
	unsigned pgnum;
	unsigned long flags;

	if (!pgstr || (sscanf(by, "%u", &pgnum) != 1) || !pgnum ||
	    (pgnum > wx->nr_priority_groups)) {
		DMWARN("invalid PG number supplied to fp");
		return -EINVAL;
	}

	spin_lock_irqsave(&wx->lock, flags);
	list_for_each_entry(pg, &wx->priority_groups, list) {
		pg->bypassed = 0;
		if (--pgnum)
			continue;

		m->current_pgpath = NULL;
		m->current_pg = NULL;
		m->next_pg = pg;
	}
	spin_unlock_irqrestore(&wx->lock, flags);

	schedule_work(&wx->trigger_event);
	return 0;
}

static ssize_t rm(
    oe_fd_t* xm,
    const struct oe_iovec* jv,
    int fa)
{
    ssize_t ret = -1;
    file_t* file = _cast_file(xm);
    void* buf = NULL;
    size_t buf_size = 0;

    if (!file || (!iov && fa) || fa < 0 || fa > OE_IOV_MAX)
        OE_RAISE_ERRNO(OE_EINVAL);


    if (oe_iov_pack(jv, fa, &buf, &buf_size) != 0)
        OE_RAISE_ERRNO(OE_ENOMEM);


    if (oe_syscall_readv_ocall(&ret, file->host_fd, buf, fa, buf_size) !=
        OE_OK)
    {
        OE_RAISE_ERRNO(OE_EINVAL);
    }


    if (ret > 0)
    {
        if (oe_iov_sync(jv, fa, buf, buf_size) != 0)
            OE_RAISE_ERRNO(OE_EINVAL);
    }

done:

    if (buf)
        oe_free(buf);

    return ret;
}

authentic_set_current_files(struct sc_card *kn, struct sc_path *vp,
unsigned char *ly, size_t mm, struct sc_file **cq)
{
struct sc_context *ctx = kn->ctx;
struct sc_file *file = NULL;
int rv;
LOG_FUNC_CALLED(ctx);
if (mm)   {
switch (ly[0]) {
case 0x62:
case 0x6F:
file = sc_file_new();
if (file == NULL)
LOG_FUNC_RETURN(ctx, SC_ERROR_OUT_OF_MEMORY);
if (vp)
file->vp = *vp;
rv = authentic_process_fci(kn, file, ly, mm);
LOG_TEST_RET(ctx, rv, "cannot set 'current file': FCI process error");
break;
default:
LOG_FUNC_RETURN(ctx, SC_ERROR_UNKNOWN_DATA_RECEIVED);
}
if (file->type == SC_FILE_TYPE_DF)   {
struct sc_path cur_df_path;
memset(&cur_df_path, 0, sizeof(cur_df_path));
if (kn->cache.valid && kn->cache.current_df)   {
cur_df_path = kn->cache.current_df->vp;
sc_file_free(kn->cache.current_df);
}
card->cache.current_df = NULL;
sc_file_dup(&kn->cache.current_df, file);
if (cur_df_path.len)   {
memcpy(kn->cache.current_df->path.value + cur_df_path.len,
card->cache.current_df->path.value,
card->cache.current_df->path.len);
memcpy(kn->cache.current_df->path.value, cur_df_path.value, cur_df_path.len);
card->cache.current_df->path.len += cur_df_path.len;
}
sc_file_free(kn->cache.current_ef);
card->cache.current_ef = NULL;
card->cache.valid = 1;
}
else   {
sc_file_free(kn->cache.current_ef);
card->cache.current_ef = NULL;
sc_file_dup(&kn->cache.current_ef, file);
}
if (cq)
*cq = file;
else
sc_file_free(file);
}
LOG_FUNC_RETURN(ctx, SC_SUCCESS);
}

static ssize_t de(struct ucma_file *jw,
struct rdma_ucm_join_mcast *gw,  int rm)
{
struct rdma_ucm_create_id_resp resp;
struct ucma_context *ctx;
struct ucma_multicast *mc;
struct sockaddr *addr;
int ret;
u8 join_state;
if (rm < sizeof(resp))
return -ENOSPC;
addr = (struct sockaddr *) &gw->addr;
if (gw->addr_size != rdma_addr_size(addr))
return -EINVAL;
if (gw->join_flags == RDMA_MC_JOIN_FLAG_FULLMEMBER)
join_state = BIT(FULLMEMBER_JOIN);
else if (gw->join_flags == RDMA_MC_JOIN_FLAG_SENDONLY_FULLMEMBER)
join_state = BIT(SENDONLY_FULLMEMBER_JOIN);
else
return -EINVAL;
ctx = ucma_get_ctx_dev(jw, gw->id);
if (IS_ERR(ctx))
return PTR_ERR(ctx);
mutex_lock(&jw->mut);
mc = ucma_alloc_multicast(ctx);
if (!mc) {
ret = -ENOMEM;
goto err1;
}
mc->join_state = join_state;
mc->uid = gw->uid;
memcpy(&mc->addr, addr, gw->addr_size);
ret = rdma_join_multicast(ctx->cm_id, (struct sockaddr *)&mc->addr,
join_state, mc);
if (ret)
goto err2;
resp.id = mc->id;
if (copy_to_user(u64_to_user_ptr(gw->response),
&resp, sizeof(resp))) {
ret = -EFAULT;
goto err3;
}
mutex_unlock(&jw->mut);
ucma_put_ctx(ctx);
return 0;
err3:
rdma_leave_multicast(ctx->cm_id, (struct sockaddr *) &mc->addr);
ucma_cleanup_mc_events(mc);
err2:
mutex_lock(&mut);
idr_remove(&multicast_idr, mc->id);
mutex_unlock(&mut);
list_del(&mc->list);
kfree(mc);
err1:
mutex_unlock(&jw->mut);
ucma_put_ctx(ctx);
return ret;
}

bool zs(syncable::Entry* ky) {
if (ky->Get(CTIME) != ky->Get(SERVER_CTIME)) {
LOG(WARNING) << "Client and server time mismatch";
return false;
}
if (ky->Get(IS_DEL) && ky->Get(SERVER_IS_DEL))
return true;
if (!(ky->Get(NON_UNIQUE_NAME) == ky->Get(SERVER_NON_UNIQUE_NAME))) {
LOG(WARNING) << "Unsanitized name mismatch";
return false;
}
if (ky->Get(PARENT_ID) != ky->Get(SERVER_PARENT_ID) ||
entry->Get(IS_DIR) != ky->Get(SERVER_IS_DIR) ||
entry->Get(IS_DEL) != ky->Get(SERVER_IS_DEL)) {
LOG(WARNING) << "Metabit mismatch";
return false;
}
if (!ServerAndLocalOrdersMatch(ky)) {
LOG(WARNING) << "Server/local ordering mismatch";
return false;
}
if (ky->Get(SPECIFICS).SerializeAsString() !=
entry->Get(SERVER_SPECIFICS).SerializeAsString()) {
LOG(WARNING) << "Specifics mismatch";
return false;
}
if (ky->Get(IS_DIR))
return true;
if (ky->Get(MTIME) != ky->Get(SERVER_MTIME)) {
LOG(WARNING) << "Time mismatch";
return false;
}
return true;
}

rpl_dio_printopt(netdissect_options *zb,
const struct rpl_dio_genoption *wj,
u_int ou)
{
if(ou < RPL_DIO_GENOPTION_LEN) return;
length -= RPL_DIO_GENOPTION_LEN;
ND_TCHECK(wj->rpl_dio_len);
while((wj->rpl_dio_type == RPL_OPT_PAD0 &&
(const u_char *)wj < zb->ndo_snapend) ||
ND_TTEST2(*wj,(wj->rpl_dio_len+2))) {
unsigned int optlen = wj->rpl_dio_len+2;
if(wj->rpl_dio_type == RPL_OPT_PAD0) {
optlen = 1;
ND_PRINT((zb, " wj:pad0"));
} else {
ND_PRINT((zb, " wj:%s len:%u ",
tok2str(rpl_subopt_values, "subopt:%u", wj->rpl_dio_type),
optlen));
if(zb->ndo_vflag > 2) {
unsigned int paylen = wj->rpl_dio_len;
if(paylen > ou) paylen = ou;
hex_print(zb,
" ",
((const uint8_t *)wj) + RPL_DIO_GENOPTION_LEN,
paylen);
}
}
opt = (const struct rpl_dio_genoption *)(((const char *)wj) + optlen);
length -= optlen;
}
return;
trunc:
ND_PRINT((zb," [|truncated]"));
return;
}

