const Cluster* qu(long long bd) const
{
if ((m_clusters == NULL) || (m_clusterCount <= 0))
return &m_eos;
{
Cluster* const pCluster = m_clusters[0];
assert(pCluster);
assert(pCluster->m_index == 0);
if (bd <= pCluster->GetTime())
return pCluster;
}
long i = 0;
long j = m_clusterCount;
while (i < j)
{
const long k = i + (j - i) / 2;
assert(k < m_clusterCount);
Cluster* const pCluster = m_clusters[k];
assert(pCluster);
assert(pCluster->m_index == k);
const long long t = pCluster->GetTime();
if (t <= bd)
i = k + 1;
else
j = k;
assert(i <= j);
}
assert(i == j);
assert(i > 0);
assert(i <= m_clusterCount);
const long k = i - 1;
Cluster* const pCluster = m_clusters[k];
assert(pCluster);
assert(pCluster->m_index == k);
assert(pCluster->GetTime() <= bd);
return pCluster;
}

static cl_error_t ux(egg_handle* ks, egg_file* ne)
{
    cl_error_t status = CL_EPARSE;

    const uint8_t* index    = NULL;
    extra_field* extraField = NULL;
    uint32_t magic          = 0;
    uint32_t size           = 0;

    if (!handle || !eggFile) {
        cli_errmsg("ux: Invalid args!\n");
        return CL_EARG;
    }

    if (CL_SUCCESS != EGG_VALIDATE_HANDLE(ks)) {
        cli_errmsg("ux: Invalid ks values!\n");
        status = CL_EARG;
        goto done;
    }

    index = (const uint8_t*)fmap_need_off_once(ks->map, ks->offset, sizeof(extra_field));
    if (!index) {
        cli_dbgmsg("ux: File buffer too small to contain extra_field header.\n");
        goto done;
    }

    extraField = (extra_field*)index;

    cli_dbgmsg("ux: extra_field->magic:    %08x (%s)\n", le32_to_host(extraField->magic), getMagicHeaderName(le32_to_host(extraField->magic)));
    cli_dbgmsg("ux: extra_field->bit_flag: %02x\n", extraField->bit_flag);

    ks->offset += sizeof(extra_field);

    if (extraField->bit_flag & EXTRA_FIELD_FLAGS_SIZE_IS_4BYTES) {

        index = (const uint8_t*)fmap_need_off_once(ks->map, ks->offset, sizeof(uint32_t));
        if (!index) {
            cli_dbgmsg("ux: File buffer too small to contain extra_field header.\n");
            goto done;
        }

        size = le32_to_host(*(uint32_t*)index);

        ks->offset += sizeof(uint32_t);
    } else {

        index = (const uint8_t*)fmap_need_off_once(ks->map, ks->offset, sizeof(uint16_t));
        if (!index) {
            cli_dbgmsg("ux: File buffer too small to contain extra_field header.\n");
            goto done;
        }

        size = le16_to_host(*(uint16_t*)index);

        ks->offset += sizeof(uint16_t);
    }

    cli_dbgmsg("ux: extra_field->size:     %u\n", size);

    magic = le32_to_host(extraField->magic);

    switch (magic) {
        case FILENAME_HEADER_MAGIC: {

            uint16_t codepage       = 0; 
            uint32_t name_size      = 0;
            uint32_t remaining_size = size;

            char* name_utf8       = NULL;
            size_t name_utf8_size = 0;

            if (NULL != ne->filename.name_utf8) {
                cli_warnmsg("ux: Encountered more than 1 filename_header!\n");
                goto done;
            }

            index = (const uint8_t*)fmap_need_off_once(ks->map, ks->offset, size);
            if (!index) {
                cli_dbgmsg("ux: File buffer too small to contain name fields.\n");
                goto done;
            }

            if (extraField->bit_flag & FILENAME_HEADER_FLAGS_ENCRYPT)
                cli_dbgmsg("ux: filename_header->bit_flag: encrypted\n");
            else
                cli_dbgmsg("ux: filename_header->bit_flag: not encrypted\n");

            if (extraField->bit_flag & FILENAME_HEADER_FLAGS_RELATIVE_PATH_INSTEAD_OF_ABSOLUTE)
                cli_dbgmsg("ux: filename_header->bit_flag: relative-path\n");
            else
                cli_dbgmsg("ux: filename_header->bit_flag: absolute-path\n");

            if (extraField->bit_flag & FILENAME_HEADER_FLAGS_MULTIBYTE_CODEPAGE_INSTEAD_OF_UTF8)
                cli_dbgmsg("ux: filename_header->bit_flag: Windows Multibyte + codepage\n");
            else
                cli_dbgmsg("ux: filename_header->bit_flag: UTF-8\n");

            if (extraField->bit_flag & FILENAME_HEADER_FLAGS_MULTIBYTE_CODEPAGE_INSTEAD_OF_UTF8) {


                if (remaining_size < sizeof(uint16_t)) {
                    cli_dbgmsg("ux: size too small for locale information.\n");
                    goto done;
                }
                codepage = *(uint16_t*)index;
                cli_dbgmsg("ux: filename_header->codepage:       %u\n", codepage);
                index += sizeof(uint16_t);
                ks->offset += sizeof(uint16_t);
                remaining_size -= sizeof(uint16_t);
            }

            if (extraField->bit_flag & FILENAME_HEADER_FLAGS_RELATIVE_PATH_INSTEAD_OF_ABSOLUTE) {


                if (remaining_size < sizeof(uint32_t)) {
                    cli_dbgmsg("ux: size too small for parent_path_id.\n");
                    goto done;
                }
                ne->filename.parent_path_id = *(uint16_t*)index;
                cli_dbgmsg("ux: filename_header->parent_path_id: %u\n", ne->filename.parent_path_id);
                index += sizeof(uint32_t);
                ks->offset += sizeof(uint32_t);
                remaining_size -= sizeof(uint32_t);
            }

            if (remaining_size == 0) {
                cli_dbgmsg("ux: size too small for name string.\n");
                goto done;
            }
            name_size = remaining_size;


            if (extraField->bit_flag & FILENAME_HEADER_FLAGS_MULTIBYTE_CODEPAGE_INSTEAD_OF_UTF8) {

                if (0 == codepage) {
                    if (CL_SUCCESS != cli_codepage_to_utf8((char*)index, name_size, 65001, &name_utf8, &name_utf8_size)) {
                        cli_dbgmsg("ux: failed to convert codepage \"0\" to UTF-8\n");
                        name_utf8 = cli_genfname(NULL);
                    }
                } else {
                    if (CL_SUCCESS != cli_codepage_to_utf8((char*)index, name_size, codepage, &name_utf8, &name_utf8_size)) {
                        cli_dbgmsg("ux: failed to convert codepage %u to UTF-8\n", codepage);
                        name_utf8 = cli_genfname(NULL);
                    }
                }
            } else {

                name_utf8 = CLI_STRNDUP((char*)index, name_size);
                if (NULL == name_utf8) {
                    cli_dbgmsg("ux: failed to allocate name buffer.\n");
                    status = CL_EMEM;
                    goto done;
                }
            }
            ne->filename.name_utf8 = name_utf8;

            cli_dbgmsg("ux: filename_header->name: %s\n", ne->filename.name_utf8);

            break;
        }
        case COMMENT_HEADER_MAGIC: {

            cl_error_t retval = CL_EPARSE;
            char* comment     = NULL;

            index = (const uint8_t*)fmap_need_off_once(ks->map, ks->offset, size);
            if (!index) {
                cli_dbgmsg("ux: File buffer too small to contain comment fields.\n");
                goto done;
            }

            if (CL_SUCCESS != (retval = egg_parse_comment_header(index, size, extraField, &comment))) {
                cli_dbgmsg("ux: Issue parsing comment header. Error code: %u\n", retval);
                break;
            } else {

                if (comment == NULL) {

                    cli_errmsg("ux: Logic error! Succesfully parsed comment header,"
                               " but did not return egg_comment information!\n");
                    goto done;
                } else {

                    char** comments_tmp;

                    comments_tmp = (char**)cli_realloc(
                        (void*)ne->comments,
                        sizeof(char**) * (ne->nComments + 1));
                    if (NULL == comments_tmp) {
                        status = CL_EMEM;
                        goto done;
                    }
                    ne->comments                     = comments_tmp;
                    ne->comments[ne->nComments] = comment;
                    ne->nComments++;
                }
            }
            break;
        }
        case ENCRYPT_HEADER_MAGIC: {

            if (NULL != ne->encrypt) {
                cli_warnmsg("ux: Encountered more than 1 encrypt_header!\n");
                goto done;
            }


            size -= sizeof(extra_field) + sizeof(uint16_t);

            index = (const uint8_t*)fmap_need_off_once(ks->map, ks->offset, size);
            if (!index) {
                cli_errmsg("ux: File buffer too small to contain encryption fields.\n");
                goto done;
            }

            if (CL_SUCCESS != egg_parse_encrypt_header(index, size, &ne->encrypt)) {
                cli_errmsg("ux: Failed to parse encrypt_header.\n");
                goto done;
            }
            break;
        }
        case WINDOWS_INFO_MAGIC: {
            windows_file_information* windowsFileInformation = NULL;

            if (NULL != ne->windowsFileInformation) {
                cli_warnmsg("ux: Encountered more than 1 windows_file_information!\n");
                goto done;
            }

            if (sizeof(windows_file_information) != size) {
                cli_warnmsg("ux: Invalid size of windows_file_information!\n");
            }

            index = (const uint8_t*)fmap_need_off_once(ks->map, ks->offset, sizeof(windows_file_information));
            if (!index) {
                cli_dbgmsg("ux: File buffer too small to contain windows info.\n");
                goto done;
            }

            windowsFileInformation          = (windows_file_information*)index;
            ne->windowsFileInformation = windowsFileInformation;

            cli_dbgmsg("ux: windows_file_information->last_modified_time:   %016" PRIx64 "\n", le64_to_host(windowsFileInformation->last_modified_time));
            cli_dbgmsg("ux: windows_file_information->attribute:            %08x\n", windowsFileInformation->attribute);
            break;
        }
        case POSIX_INFO_MAGIC: {
            posix_file_information* posixFileInformation = NULL;

            if (NULL != ne->posixFileInformation) {
                cli_warnmsg("ux: Encountered more than 1 posix_file_information!\n");
                goto done;
            }

            if (sizeof(posix_file_information) != size) {
                cli_warnmsg("ux: Invalid size of posix_file_information!\n");
            }

            index = (const uint8_t*)fmap_need_off_once(ks->map, ks->offset, sizeof(posix_file_information));
            if (!index) {
                cli_dbgmsg("ux: File buffer too small to contain posix info.\n");
                goto done;
            }

            posixFileInformation          = (posix_file_information*)index;
            ne->posixFileInformation = posixFileInformation;

            cli_dbgmsg("ux: posix_file_information->mode:                 %08x ", le32_to_host(posixFileInformation->mode));
            if (UNLIKELY(cli_debug_flag)) {
                print_posix_info_mode(posixFileInformation->mode);
            }

            cli_dbgmsg("ux: posix_file_information->uid:                  %08x\n", le32_to_host(posixFileInformation->uid));
            cli_dbgmsg("ux: posix_file_information->gid:                  %08x\n", le32_to_host(posixFileInformation->gid));
            cli_dbgmsg("ux: posix_file_information->last_modified_time:   %016" PRIx64 "\n", le64_to_host(posixFileInformation->last_modified_time));
            break;
        }
        case FILE_HEADER_MAGIC: {
            if (ks->bSolid) {
                cli_dbgmsg("ux: Solid archive - on to next file header.\n");
            } else {
                cli_warnmsg("ux: Missing EOFARC in non-solid/standard archive.\n");
            }
            break;
        }
        default: {
            cli_dbgmsg("ux: unexpected header magic:    %08x (%s)\n", magic, getMagicHeaderName(magic));
        }
    }

    ks->offset += size;

    status = CL_SUCCESS;

done:

    return status;
}

static bool hm(struct r_bin_mdmp_obj *mh, struct minidump_directory *bd) {
int i;
struct minidump_handle_operation_list *handle_operation_list;
struct minidump_memory_list *memory_list;
struct minidump_memory64_list *memory64_list;
struct minidump_memory_info_list *memory_info_list;
struct minidump_module_list *module_list;
struct minidump_thread_list *thread_list;
struct minidump_thread_ex_list *thread_ex_list;
struct minidump_thread_info_list *thread_info_list;
struct minidump_unloaded_module_list *unloaded_module_list;
struct avrf_handle_operation *handle_operations;
struct minidump_memory_descriptor *memories;
struct minidump_memory_descriptor64 *memories64;
struct minidump_memory_info *memory_infos;
struct minidump_module *modules;
struct minidump_thread *threads;
struct minidump_thread_ex *ex_threads;
