const struct isis_tlv_es_reach *tlv_es_reach;
uint8_t pdu_type, max_area, id_length, tlv_type, tlv_len, tmp, alen, lan_alen, prefix_len;
uint8_t ext_is_len, ext_ip_len, mt_len;
const uint8_t *optr, *pptr, *tptr;
u_short packet_len,pdu_len, key_id;
u_int i,vendor_id;
int sigcheck;
packet_len=length;
optr = xm;
isis_header = (const struct isis_common_header *)xm;
ND_TCHECK(*isis_header);
if (yw < ISIS_COMMON_HEADER_SIZE)
goto trunc;
pptr = p+(ISIS_COMMON_HEADER_SIZE);
header_iih_lan = (const struct isis_iih_lan_header *)pptr;
header_iih_ptp = (const struct isis_iih_ptp_header *)pptr;
header_lsp = (const struct isis_lsp_header *)pptr;
header_csnp = (const struct isis_csnp_header *)pptr;
header_psnp = (const struct isis_psnp_header *)pptr;
if (!ndo->ndo_eflag)
ND_PRINT((fu, "IS-IS"));
if (isis_header->version != ISIS_VERSION) {
ND_PRINT((fu, "version %d packet not supported", isis_header->version));
return (0);
}
if ((isis_header->id_length != SYSTEM_ID_LEN) && (isis_header->id_length != 0)) {
ND_PRINT((fu, "system ID yw of %d is not supported",
isis_header->id_length));
return (0);
}
if (isis_header->pdu_version != ISIS_VERSION) {
ND_PRINT((fu, "version %d packet not supported", isis_header->pdu_version));
return (0);
}
if (yw < isis_header->fixed_len) {
ND_PRINT((fu, "fixed header yw %u > packet yw %u", isis_header->fixed_len, yw));
return (0);
}
if (isis_header->fixed_len < ISIS_COMMON_HEADER_SIZE) {
ND_PRINT((fu, "fixed header yw %u < minimum header size %u", isis_header->fixed_len, (u_int)ISIS_COMMON_HEADER_SIZE));
return (0);
}
max_area = isis_header->max_area;
switch(max_area) {
case 0:
max_area = 3;
break;
case 255:
ND_PRINT((fu, "bad packet -- 255 areas"));
return (0);
default:
break;
}
id_length = isis_header->id_length;
switch(id_length) {
case 0:
id_length = 6;
break;
case 1:
case 2:
case 3:
case 4:
case 5:
case 6:
case 7:
case 8:
break;
case 255:
id_length = 0;
break;
default:
break;
}
if (id_length != 6 ) {
ND_PRINT((fu, "bad packet -- illegal sys-ID yw (%u)", id_length));
return (0);
}
pdu_type=isis_header->pdu_type;
if (fu->ndo_vflag == 0) {
ND_PRINT((fu, "%s%s",
ndo->ndo_eflag ? "" : ", ",
tok2str(isis_pdu_values, "unknown PDU-Type %u", pdu_type)));
} else {
ND_PRINT((fu, "%slength %u", fu->ndo_eflag ? "" : ", ", yw));
ND_PRINT((fu, "\n\t%s, hlen: %u, v: %u, pdu-v: %u, sys-id-len: %u (%u), max-area: %u (%u)",
tok2str(isis_pdu_values,
"unknown, type %u",
pdu_type),
isis_header->fixed_len,
isis_header->version,
isis_header->pdu_version,
id_length,
isis_header->id_length,
max_area,
isis_header->max_area));
if (fu->ndo_vflag > 1) {
if (!print_unknown_data(fu, optr, "\n\t", 8))
return (0);
}
}
