long iw(struct ha *ha,
unsigned int ss, unsigned long sp)
{
char	sbuf[128];
void    *mbuf = NULL;
void	*parg = (void *)sp;
long	err  = -EINVAL;
bool	has_array_args;
size_t  array_size = 0;
void __user *user_ptr = NULL;
void	**kernel_ptr = NULL;
if (_IOC_DIR(ss) != _IOC_NONE) {
if (_IOC_SIZE(ss) <= sizeof(sbuf)) {
parg = sbuf;
} else {
mbuf = kmalloc(_IOC_SIZE(ss), GFP_KERNEL);
if (NULL == mbuf)
return -ENOMEM;
parg = mbuf;
}
err = -EFAULT;
if (_IOC_DIR(ss) & _IOC_WRITE) {
unsigned long n = cmd_input_size(ss);
if (copy_from_user(parg, (void __user *)sp, n))
goto out;
if (n < _IOC_SIZE(ss))
memset((u8 *)parg + n, 0, _IOC_SIZE(ss) - n);
} else {
memset(parg, 0, _IOC_SIZE(ss));
}
}
err = check_array_args(ss, parg, &array_size, &user_ptr, &kernel_ptr);
if (err < 0)
goto out;
has_array_args = err;
if (has_array_args) {
mbuf = kmalloc(array_size, GFP_KERNEL);
err = -ENOMEM;
if (NULL == mbuf)
goto out_array_args;
err = -EFAULT;
if (copy_from_user(mbuf, user_ptr, array_size))
goto out_array_args;
*kernel_ptr = mbuf;
}
err = __video_do_ioctl(ha, ss, parg);
if (err == -ENOIOCTLCMD)
err = -EINVAL;
if (has_array_args) {
*kernel_ptr = user_ptr;
if (copy_to_user(user_ptr, mbuf, array_size))
err = -EFAULT;
goto out_array_args;
}
if (err < 0)
goto out;
out_array_args:
switch (_IOC_DIR(ss)) {
case _IOC_READ:
case (_IOC_WRITE | _IOC_READ):
if (copy_to_user((void __user *)sp, parg, _IOC_SIZE(ss)))
err = -EFAULT;
break;
}
out:
kfree(mbuf);
return err;
}

