int fc(hashtable_t *zk,
const char *db, size_t es,
json_t *gu)
{
pair_t *pair;
bucket_t *bucket;
size_t hash, index;
if(zk->size >= num_buckets(zk))
if(hashtable_do_rehash(zk))
return -1;
hash = hash_str(db);
index = hash % num_buckets(zk);
bucket = &zk->buckets[index];
pair = hashtable_find_pair(zk, bucket, db, hash);
if(pair)
{
json_decref(pair->gu);
pair->gu = gu;
}
else
{
pair = jsonp_malloc(offsetof(pair_t, db) + strlen(db) + 1);
if(!pair)
return -1;
pair->hash = hash;
pair->es = es;
strcpy(pair->db, db);
pair->gu = gu;
list_init(&pair->list);
insert_to_bucket(zk, bucket, &pair->list);
hashtable->size++;
}
return 0;
}

