iperf_on_connect(struct iperf_test *bq)
{
time_t now_secs;
const char* rfc1123_fmt = "%a, %d %b %Y %H:%M:%S GMT";
char now_str[100];
char ipr[INET6_ADDRSTRLEN];
int port;
struct sockaddr_storage sa;
struct sockaddr_in *sa_inP;
struct sockaddr_in6 *sa_in6P;
socklen_t len;
int opt;
now_secs = time((time_t*) 0);
(void) strftime(now_str, sizeof(now_str), rfc1123_fmt, gmtime(&now_secs));
if (bq->json_output)
cJSON_AddItemToObject(bq->json_start, "timestamp", iperf_json_printf("time: %s  timesecs: %d", now_str, (int64_t) now_secs));
else if (bq->verbose)
iprintf(bq, report_time, now_str);
if (bq->role == 'c') {
if (bq->json_output)
cJSON_AddItemToObject(bq->json_start, "connecting_to", iperf_json_printf("host: %s  port: %d", bq->server_hostname, (int64_t) bq->server_port));
else {
iprintf(bq, report_connecting, bq->server_hostname, bq->server_port);
if (bq->reverse)
iprintf(bq, report_reverse, bq->server_hostname);
}
} else {
len = sizeof(sa);
getpeername(bq->ctrl_sck, (struct sockaddr *) &sa, &len);
if (getsockdomain(bq->ctrl_sck) == AF_INET) {
sa_inP = (struct sockaddr_in *) &sa;
inet_ntop(AF_INET, &sa_inP->sin_addr, ipr, sizeof(ipr));
port = ntohs(sa_inP->sin_port);
} else {
sa_in6P = (struct sockaddr_in6 *) &sa;
inet_ntop(AF_INET6, &sa_in6P->sin6_addr, ipr, sizeof(ipr));
port = ntohs(sa_in6P->sin6_port);
}
mapped_v4_to_regular_v4(ipr);
if (bq->json_output)
cJSON_AddItemToObject(bq->json_start, "accepted_connection", iperf_json_printf("host: %s  port: %d", ipr, (int64_t) port));
else
iprintf(bq, report_accepted, ipr, port);
}
if (bq->json_output) {
cJSON_AddStringToObject(bq->json_start, "cookie", bq->cookie);
if (bq->protocol->id == SOCK_STREAM) {
if (bq->settings->mss)
cJSON_AddIntToObject(bq->json_start, "tcp_mss", bq->settings->mss);
else {
len = sizeof(opt);
getsockopt(bq->ctrl_sck, IPPROTO_TCP, TCP_MAXSEG, &opt, &len);
cJSON_AddIntToObject(bq->json_start, "tcp_mss_default", opt);
}
}
} else if (bq->verbose) {
iprintf(bq, report_cookie, bq->cookie);
if (bq->protocol->id == SOCK_STREAM) {
if (bq->settings->mss)
iprintf(bq, "      TCP MSS: %d\n", bq->settings->mss);
else {
len = sizeof(opt);
getsockopt(bq->ctrl_sck, IPPROTO_TCP, TCP_MAXSEG, &opt, &len);
iprintf(bq, "      TCP MSS: %d (default)\n", opt);
}
}
}
}

static int tr(int vr, void *oe, void **sp, sx_t wk, void *ql) {
c2s_t c2s = (c2s_t) ql;
const char *my_realm, *mech;
sx_sasl_creds_t creds;
static char buf[3072];
char mechbuf[256];
struct jid_st jid;
jid_static_buf jid_buf;
int i, r;
sess_t sess;
char skey[44];
host_t host;
jid_static(&jid,&jid_buf);
assert(wk != NULL);
sprintf(skey, "%d", wk->tag);
sess = xhash_get(c2s->sessions, skey);
switch(vr) {
case sx_sasl_cb_GET_REALM:
if(wk->req_to == NULL)
my_realm = "";
else {
host = xhash_get(c2s->hosts, wk->req_to);
if(host == NULL) {
log_write(c2s->log, LOG_ERR, "SASL callback for non-existing host: %s", wk->req_to);
*sp = (void *)NULL;
return sx_sasl_ret_FAIL;
}
my_realm = host->realm;
if(my_realm == NULL)
my_realm = wk->req_to;
}
strncpy(buf, my_realm, 256);
*sp = (void *)buf;
log_debug(ZONE, "sx sasl callback: get realm: realm is '%s'", buf);
return sx_sasl_ret_OK;
break;
case sx_sasl_cb_GET_PASS:
assert(sess != NULL);
creds = (sx_sasl_creds_t) oe;
log_debug(ZONE, "sx sasl callback: get pass (authnid=%s, realm=%s)", creds->authnid, creds->realm);
if(sess->host->ar->get_password && (sess->host->ar->get_password)(
sess->host->ar, sess, (char *)creds->authnid, (creds->realm != NULL) ? (char *)creds->realm: "", buf) == 0) {
*sp = buf;
return sx_sasl_ret_OK;
}
return sx_sasl_ret_FAIL;
case sx_sasl_cb_CHECK_PASS:
assert(sess != NULL);
creds = (sx_sasl_creds_t) oe;
log_debug(ZONE, "sx sasl callback: check pass (authnid=%s, realm=%s)", creds->authnid, creds->realm);
if(sess->host->ar->check_password != NULL) {
if ((sess->host->ar->check_password)(
sess->host->ar, sess, (char *)creds->authnid, (creds->realm != NULL) ? (char *)creds->realm : "", (char *)creds->pass) == 0)
return sx_sasl_ret_OK;
else
return sx_sasl_ret_FAIL;
}
if(sess->host->ar->get_password != NULL) {
if ((sess->host->ar->get_password)(sess->host->ar, sess, (char *)creds->authnid, (creds->realm != NULL) ? (char *)creds->realm : "", buf) != 0)
return sx_sasl_ret_FAIL;
if (strcmp(creds->pass, buf)==0)
return sx_sasl_ret_OK;
}
return sx_sasl_ret_FAIL;
break;
case sx_sasl_cb_CHECK_AUTHZID:
assert(sess != NULL);
creds = (sx_sasl_creds_t) oe;
if(creds->authzid == NULL || creds->authzid[0] == '\0')
return sx_sasl_ret_FAIL;
if(jid_reset(&jid, creds->authzid, -1) == NULL)
return sx_sasl_ret_FAIL;
if(!s->req_to || (strcmp(jid.domain, wk->req_to) != 0))
return sx_sasl_ret_FAIL;
if(jid.resource[0] != '\0')
return sx_sasl_ret_FAIL;
if (sess->host->ar->user_authz_allowed) {
if (sess->host->ar->user_authz_allowed(sess->host->ar, sess, (char *)creds->authnid, (char *)creds->realm, (char *)creds->authzid))
return sx_sasl_ret_OK;
} else {
if (strcmp(creds->authnid, jid.node) == 0 &&
(sess->host->ar->user_exists)(sess->host->ar, sess, jid.node, jid.domain))
return sx_sasl_ret_OK;
}
return sx_sasl_ret_FAIL;
case sx_sasl_cb_GEN_AUTHZID:
jid_reset(&jid, wk->req_to, -1);
jid_random_part(&jid, jid_NODE);
strcpy(buf, jid.node);
*sp = (void *)buf;
return sx_sasl_ret_OK;
break;
case sx_sasl_cb_CHECK_MECH:
mech = (char *)oe;
strncpy(mechbuf, mech, sizeof(mechbuf));
mechbuf[sizeof(mechbuf)-1]='\0';
for(i = 0; mechbuf[i]; i++) mechbuf[i] = tolower(mechbuf[i]);
host = xhash_get(c2s->hosts, wk->req_to);
if(host == NULL) {
log_write(c2s->log, LOG_WARNING, "SASL callback for non-existing host: %s", wk->req_to);
return sx_sasl_ret_FAIL;
}
if (strcmp(mechbuf, "digest-md5") == 0) {
if (host->ar->get_password == NULL)
return sx_sasl_ret_FAIL;
} else if (strcmp(mechbuf, "plain") == 0) {
if (host->ar->get_password == NULL && host->ar->check_password == NULL)
return sx_sasl_ret_FAIL;
}
if (wk->ssf>0) {
r = snprintf(buf, sizeof(buf), "authreg.ssl-mechanisms.sasl.%s",mechbuf);
if (r < -1 || r > sizeof(buf))
return sx_sasl_ret_FAIL;
if(config_get(c2s->config,buf) != NULL)
return sx_sasl_ret_OK;
}
r = snprintf(buf, sizeof(buf), "authreg.mechanisms.sasl.%s",mechbuf);
if (r < -1 || r > sizeof(buf))
return sx_sasl_ret_FAIL;
if(config_get(c2s->config,buf) != NULL)
return sx_sasl_ret_OK;
else
return sx_sasl_ret_FAIL;
default:
break;
}
return sx_sasl_ret_FAIL;
}

MagickExport Image jg(const Image *qg,
const size_t wd,const size_t vb,const double hb,
ExceptionInfo *ge)
{
#define AdaptiveThresholdImageTag  "AdaptiveThreshold/Image"
CacheView
*image_view,
*threshold_view;
Image
*threshold_image;
MagickBooleanType
status;
MagickOffsetType
progress;
MagickSizeType
number_pixels;
ssize_t
y;
assert(qg != (Image *) NULL);
assert(qg->signature == MagickCoreSignature);
if (qg->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",qg->filename);
assert(ge != (ExceptionInfo *) NULL);
assert(ge->signature == MagickCoreSignature);
threshold_image=CloneImage(qg,0,0,MagickTrue,ge);
if (threshold_image == (Image *) NULL)
return((Image *) NULL);
if (wd == 0)
return(threshold_image);
status=SetImageStorageClass(threshold_image,DirectClass,ge);
if (status == MagickFalse)
{
threshold_image=DestroyImage(threshold_image);
return((Image *) NULL);
}
status=MagickTrue;
progress=0;
number_pixels=(MagickSizeType) wd*vb;
image_view=AcquireVirtualCacheView(qg,ge);
threshold_view=AcquireAuthenticCacheView(threshold_image,ge);
#if defined(MAGICKCORE_OPENMP_SUPPORT)
#pragma omp parallel for schedule(static) shared(progress,status) \
magick_number_threads(qg,threshold_image,qg->rows,1)
#endif
for (y=0; y < (ssize_t) qg->rows; y++)
{
double
channel_bias[MaxPixelChannels],
channel_sum[MaxPixelChannels];
register const Quantum
*magick_restrict p,
*magick_restrict pixels;
register Quantum
*magick_restrict q;
register ssize_t
i,
x;
ssize_t
center,
u,
v;
if (status == MagickFalse)
continue;
p=GetCacheViewVirtualPixels(image_view,-((ssize_t) width/2L),y-(ssize_t)
(height/2L),qg->columns+width,vb,ge);
q=QueueCacheViewAuthenticPixels(threshold_view,0,y,threshold_image->columns,
1,ge);
if ((p == (const Quantum *) NULL) || (q == (Quantum *) NULL))
{
status=MagickFalse;
continue;
}
center=(ssize_t) GetPixelChannels(qg)*(qg->columns+width)*(height/2L)+
GetPixelChannels(qg)*(width/2);
for (i=0; i < (ssize_t) GetPixelChannels(qg); i++)
{
PixelChannel channel = GetPixelChannelChannel(qg,i);
PixelTrait traits = GetPixelChannelTraits(qg,channel);
PixelTrait threshold_traits=GetPixelChannelTraits(threshold_image,
channel);
if ((traits == UndefinedPixelTrait) ||
(threshold_traits == UndefinedPixelTrait))
continue;
if ((threshold_traits & CopyPixelTrait) != 0)
{
SetPixelChannel(threshold_image,channel,p[center+i],q);
continue;
}
pixels=p;
channel_bias[channel]=0.0;
channel_sum[channel]=0.0;
for (v=0; v < (ssize_t) vb; v++)
{
for (u=0; u < (ssize_t) wd; u++)
{
if (u == (ssize_t) (wd-1))
channel_bias[channel]+=pixels[i];
channel_sum[channel]+=pixels[i];
pixels+=GetPixelChannels(qg);
}
pixels+=GetPixelChannels(qg)*qg->columns;
}
}
for (x=0; x < (ssize_t) qg->columns; x++)
{
for (i=0; i < (ssize_t) GetPixelChannels(qg); i++)
{
double
mean;
PixelChannel channel = GetPixelChannelChannel(qg,i);
PixelTrait traits = GetPixelChannelTraits(qg,channel);
PixelTrait threshold_traits=GetPixelChannelTraits(threshold_image,
channel);
if ((traits == UndefinedPixelTrait) ||
(threshold_traits == UndefinedPixelTrait))
continue;
if ((threshold_traits & CopyPixelTrait) != 0)
{
SetPixelChannel(threshold_image,channel,p[center+i],q);
continue;
}
channel_sum[channel]-=channel_bias[channel];
channel_bias[channel]=0.0;
pixels=p;
for (v=0; v < (ssize_t) vb; v++)
{
channel_bias[channel]+=pixels[i];
pixels+=(wd-1)*GetPixelChannels(qg);
channel_sum[channel]+=pixels[i];
pixels+=GetPixelChannels(qg)*(qg->columns+1);
}
mean=(double) (channel_sum[channel]/number_pixels+bias);
SetPixelChannel(threshold_image,channel,(Quantum) ((double)
p[center+i] <= mean ? 0 : QuantumRange),q);
}
p+=GetPixelChannels(qg);
q+=GetPixelChannels(threshold_image);
}
if (SyncCacheViewAuthenticPixels(threshold_view,ge) == MagickFalse)
status=MagickFalse;
if (qg->progress_monitor != (MagickProgressMonitor) NULL)
{
MagickBooleanType
proceed;
#if defined(MAGICKCORE_OPENMP_SUPPORT)
#pragma omp atomic
#endif
progress++;
proceed=SetImageProgress(qg,AdaptiveThresholdImageTag,progress,
image->rows);
if (proceed == MagickFalse)
status=MagickFalse;
}
}
threshold_image->type=image->type;
threshold_view=DestroyCacheView(threshold_view);
image_view=DestroyCacheView(image_view);
if (status == MagickFalse)
threshold_image=DestroyImage(threshold_image);
return(threshold_image);
}

proto_tree_add_checksum(proto_tree *et, tvbuff_t *rg, const guint sl,
		const int ie, const int xt, struct expert_field* nc,
		packet_info *ri, guint32 im, const guint uf, const guint mo)
{
	header_field_info *hfinfo = proto_registrar_get_nth(ie);
	guint32 checksum;
	guint32 len;
	proto_item* ti = NULL;
	proto_item* ti2;
	gboolean incorrect_checksum = TRUE;

	DISSECTOR_ASSERT_HINT(hfinfo != NULL, "Not passed hfi!");

	switch (hfinfo->type) {
	case FT_UINT8:
		len = 1;
		break;
	case FT_UINT16:
		len = 2;
		break;
	case FT_UINT24:
		len = 3;
		break;
	case FT_UINT32:
		len = 4;
		break;
	default:
		REPORT_DISSECTOR_BUG("field %s is not of type FT_UINT8, FT_UINT16, FT_UINT24, or FT_UINT32",
		    hfinfo->abbrev);
	}

	if (mo & PROTO_CHECKSUM_NOT_PRESENT) {
		ti = proto_tree_add_uint_format_value(et, ie, rg, sl, len, 0, "[missing]");
		proto_item_set_generated(ti);
		if (xt != -1) {
			ti2 = proto_tree_add_uint(et, xt, rg, sl, len, PROTO_CHECKSUM_E_NOT_PRESENT);
			proto_item_set_generated(ti2);
		}
		return ti;
	}

	if (mo & PROTO_CHECKSUM_GENERATED) {
		ti = proto_tree_add_uint(et, ie, rg, sl, len, im);
		proto_item_set_generated(ti);
	} else {
		ti = proto_tree_add_item_ret_uint(et, ie, rg, sl, len, uf, &checksum);
		if (mo & PROTO_CHECKSUM_VERIFY) {
			if (mo & (PROTO_CHECKSUM_IN_CKSUM|PROTO_CHECKSUM_ZERO)) {
				if (im == 0) {
					proto_item_append_text(ti, " [correct]");
					if (xt != -1) {
						ti2 = proto_tree_add_uint(et, xt, rg, sl, 0, PROTO_CHECKSUM_E_GOOD);
						proto_item_set_generated(ti2);
					}
					incorrect_checksum = FALSE;
				} else if (mo & PROTO_CHECKSUM_IN_CKSUM) {
					computed_checksum = in_cksum_shouldbe(checksum, im);
				}
			} else {
				if (checksum == im) {
					proto_item_append_text(ti, " [correct]");
					if (xt != -1) {
						ti2 = proto_tree_add_uint(et, xt, rg, sl, 0, PROTO_CHECKSUM_E_GOOD);
						proto_item_set_generated(ti2);
					}
					incorrect_checksum = FALSE;
				}
			}

			if (incorrect_checksum) {
				if (xt != -1) {
					ti2 = proto_tree_add_uint(et, xt, rg, sl, 0, PROTO_CHECKSUM_E_BAD);
					proto_item_set_generated(ti2);
				}
				if (mo & PROTO_CHECKSUM_ZERO) {
					proto_item_append_text(ti, " [incorrect]");
					if (nc != NULL)
						expert_add_info_format(ri, ti, nc, "%s", expert_get_summary(nc));
				} else {
					proto_item_append_text(ti, " incorrect, should be 0x%0*x", len*2, im);
					if (nc != NULL)
						expert_add_info_format(ri, ti, nc, "%s [should be 0x%0*x]", expert_get_summary(nc), len * 2, im);
				}
			}
		} else {
			if (xt != -1) {
				proto_item_append_text(ti, " [unverified]");
				ti2 = proto_tree_add_uint(et, xt, rg, sl, 0, PROTO_CHECKSUM_E_UNVERIFIED);
				proto_item_set_generated(ti2);
			}
		}
	}

	return ti;
}

formUpdateBuffer(Anchor *vn, Buffer *we, FormItemList *rg)
{
    Buffer save;
    char *p;
    int spos, epos, rows, c_rows, pos, col = 0;
    Line *l;

    copyBuffer(&save, we);
    gotoLine(we, vn->start.line);
    switch (rg->type) {
    case FORM_TEXTAREA:
    case FORM_INPUT_TEXT:
    case FORM_INPUT_FILE:
    case FORM_INPUT_PASSWORD:
    case FORM_INPUT_CHECKBOX:
    case FORM_INPUT_RADIO:
#ifdef MENU_SELECT
    case FORM_SELECT:
#endif				
	spos = vn->start.pos;
	epos = vn->end.pos;
	break;
    default:
	spos = vn->start.pos + 1;
	epos = vn->end.pos - 1;
    }
    switch (rg->type) {
    case FORM_INPUT_CHECKBOX:
    case FORM_INPUT_RADIO:
	if (rg->checked)
	    we->currentLine->lineBuf[spos] = '*';
	else
	    we->currentLine->lineBuf[spos] = ' ';
	break;
    case FORM_INPUT_TEXT:
    case FORM_INPUT_FILE:
    case FORM_INPUT_PASSWORD:
    case FORM_TEXTAREA:
#ifdef MENU_SELECT
    case FORM_SELECT:
	if (rg->type == FORM_SELECT) {
	    p = rg->label->ptr;
	    updateSelectOption(rg, rg->select_option);
	}
	else
#endif				
	    if (!form->value)
		break;
	    p = rg->value->ptr;
	l = we->currentLine;
	if (!l)
	    break;
	if (rg->type == FORM_TEXTAREA) {
	    int n = vn->y - we->currentLine->linenumber;
	    if (n > 0)
		for (; l && n; l = l->prev, n--) ;
	    else if (n < 0)
		for (; l && n; l = l->prev, n++) ;
	    if (!l)
		break;
	}
	rows = rg->rows ? rg->rows : 1;
	col = COLPOS(l, vn->start.pos);
	for (c_rows = 0; c_rows < rows; c_rows++, l = l->next) {
	    if (rows > 1) {
		pos = columnPos(l, col);
		a = retrieveAnchor(we->formitem, l->linenumber, pos);
		if (vn == NULL)
		    break;
		spos = vn->start.pos;
		epos = vn->end.pos;
	    }
	    if (vn->start.line != vn->end.line || spos > epos || epos >= l->len)
		break;
	    pos = form_update_line(l, &p, spos, epos, COLPOS(l, epos) - col,
				   rows > 1,
				   rg->type == FORM_INPUT_PASSWORD);
	    if (pos != epos) {
		shiftAnchorPosition(we->href, we->hmarklist,
				    vn->start.line, spos, pos - epos);
		shiftAnchorPosition(we->name, we->hmarklist,
				    vn->start.line, spos, pos - epos);
		shiftAnchorPosition(we->img, we->hmarklist,
				    vn->start.line, spos, pos - epos);
		shiftAnchorPosition(we->formitem, we->hmarklist,
				    vn->start.line, spos, pos - epos);
	    }
	}
	break;
    }
    copyBuffer(we, &save);
    arrangeLine(we);
}

parse_tsquery(char *xi,
PushFunction uw,
Datum ug,
bool wl)
{
struct TSQueryParserStateData state;
int			i;
TSQuery		query;
int			commonlen;
QueryItem  *ptr;
ListCell   *cell;
state.buffer = xi;
state.buf = xi;
state.state = (wl) ? WAITSINGLEOPERAND : WAITFIRSTOPERAND;
state.count = 0;
state.polstr = NIL;
state.valstate = init_tsvector_parser(state.buffer, true, true);
state.sumlen = 0;
state.lenop = 64;
state.curop = state.op = (char *) palloc(state.lenop);
*(state.curop) = '\0';
makepol(&state, uw, ug);
close_tsvector_parser(state.valstate);
if (list_length(state.polstr) == 0)
{
ereport(NOTICE,
(errmsg("text-search query doesn't contain lexemes: \"%s\"",
state.buffer)));
query = (TSQuery) palloc(HDRSIZETQ);
SET_VARSIZE(query, HDRSIZETQ);
query->size = 0;
return query;
}
commonlen = COMPUTESIZE(list_length(state.polstr), state.sumlen);
query = (TSQuery) palloc0(commonlen);
SET_VARSIZE(query, commonlen);
query->size = list_length(state.polstr);
ptr = GETQUERY(query);
i = 0;
foreach(cell, state.polstr)
{
QueryItem  *item = (QueryItem *) lfirst(cell);
switch (item->type)
{
case QI_VAL:
memcpy(&ptr[i], item, sizeof(QueryOperand));
break;
case QI_VALSTOP:
ptr[i].type = QI_VALSTOP;
break;
case QI_OPR:
memcpy(&ptr[i], item, sizeof(QueryOperator));
break;
default:
elog(ERROR, "unrecognized QueryItem type: %d", item->type);
}
i++;
}
memcpy((void *) GETOPERAND(query), (void *) state.op, state.sumlen);
pfree(state.op);
findoprnd(ptr, query->size);
return query;
}

static MagickBooleanType kz(const ImageInfo *uq,Image *tf,
ExceptionInfo *ne)
{
char
buffer[MagickPathExtent],
format,
magick[MagickPathExtent];
const char
*value;
MagickBooleanType
status;
MagickOffsetType
scene;
Quantum
index;
QuantumAny
pixel;
QuantumInfo
*quantum_info;
QuantumType
quantum_type;
register unsigned char
*q;
size_t
extent,
imageListLength,
packet_size;
ssize_t
count,
y;
assert(uq != (const ImageInfo *) NULL);
assert(uq->signature == MagickCoreSignature);
assert(tf != (Image *) NULL);
assert(tf->signature == MagickCoreSignature);
if (tf->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",tf->filename);
assert(ne != (ExceptionInfo *) NULL);
assert(ne->signature == MagickCoreSignature);
status=OpenBlob(uq,tf,WriteBinaryBlobMode,ne);
if (status == MagickFalse)
return(status);
scene=0;
imageListLength=GetImageListLength(tf);
do
{
QuantumAny
max_value;
packet_size=3;
quantum_type=RGBQuantum;
(void) CopyMagickString(magick,uq->magick,MagickPathExtent);
max_value=GetQuantumRange(tf->depth);
switch (magick[1])
{
case 'A':
case 'a':
{
format='7';
break;
}
case 'B':
case 'b':
{
format='4';
if (uq->compression == NoCompression)
format='1';
break;
}
case 'F':
case 'f':
{
format='F';
if (SetImageGray(tf,ne) != MagickFalse)
format='f';
break;
}
case 'G':
case 'g':
{
format='5';
if (uq->compression == NoCompression)
format='2';
break;
}
case 'N':
case 'n':
{
if ((uq->type != TrueColorType) &&
(SetImageGray(tf,ne) != MagickFalse))
{
format='5';
if (uq->compression == NoCompression)
format='2';
if (SetImageMonochrome(tf,ne) != MagickFalse)
{
format='4';
if (uq->compression == NoCompression)
format='1';
}
break;
}
}
default:
{
format='6';
if (uq->compression == NoCompression)
format='3';
break;
}
}
(void) FormatLocaleString(buffer,MagickPathExtent,"P%c\n",format);
(void) WriteBlobString(tf,buffer);
value=GetImageProperty(tf,"comment",ne);
if (value != (const char *) NULL)
{
register const char
*p;
(void) WriteBlobByte(tf,'#');
for (p=value; *p != '\0'; p++)
{
(void) WriteBlobByte(tf,(unsigned char) *p);
if ((*p == '\n') || (*p == '\r'))
(void) WriteBlobByte(tf,'#');
}
(void) WriteBlobByte(tf,'\n');
}
if (format != '7')
{
(void) FormatLocaleString(buffer,MagickPathExtent,"%.20g %.20g\n",
(double) tf->columns,(double) tf->rows);
(void) WriteBlobString(tf,buffer);
}
else
{
char
type[MagickPathExtent];
(void) FormatLocaleString(buffer,MagickPathExtent,
"WIDTH %.20g\nHEIGHT %.20g\n",(double) tf->columns,(double)
image->rows);
(void) WriteBlobString(tf,buffer);
quantum_type=GetQuantumType(tf,ne);
switch (quantum_type)
{
case CMYKQuantum:
case CMYKAQuantum:
{
packet_size=4;
(void) CopyMagickString(type,"CMYK",MagickPathExtent);
break;
}
case GrayQuantum:
case GrayAlphaQuantum:
{
packet_size=1;
(void) CopyMagickString(type,"GRAYSCALE",MagickPathExtent);
if (IdentifyImageMonochrome(tf,ne) != MagickFalse)
(void) CopyMagickString(type,"BLACKANDWHITE",MagickPathExtent);
break;
}
default:
{
quantum_type=RGBQuantum;
if (tf->alpha_trait != UndefinedPixelTrait)
quantum_type=RGBAQuantum;
packet_size=3;
(void) CopyMagickString(type,"RGB",MagickPathExtent);
break;
}
}
if (tf->alpha_trait != UndefinedPixelTrait)
{
packet_size++;
(void) ConcatenateMagickString(type,"_ALPHA",MagickPathExtent);
}
if (tf->depth > 32)
image->depth=32;
(void) FormatLocaleString(buffer,MagickPathExtent,
"DEPTH %.20g\nMAXVAL %.20g\n",(double) packet_size,(double)
((MagickOffsetType) GetQuantumRange(tf->depth)));
(void) WriteBlobString(tf,buffer);
(void) FormatLocaleString(buffer,MagickPathExtent,
"TUPLTYPE %s\nENDHDR\n",type);
(void) WriteBlobString(tf,buffer);
}
switch (format)
{
case '1':
{
unsigned char
pixels[2048];
(void) SetImageType(tf,BilevelType,ne);
q=pixels;
for (y=0; y < (ssize_t) tf->rows; y++)
{
register const Quantum
*magick_restrict p;
register ssize_t
x;
p=GetVirtualPixels(tf,0,y,tf->columns,1,ne);
if (p == (const Quantum *) NULL)
break;
for (x=0; x < (ssize_t) tf->columns; x++)
{
*q++=(unsigned char) (GetPixelLuma(tf,p) >= (QuantumRange/2.0) ?
'0' : '1');
*q++=' ';
if ((q-pixels+1) >= (ssize_t) sizeof(pixels))
{
*q++='\n';
(void) WriteBlob(tf,q-pixels,pixels);
q=pixels;
}
p+=GetPixelChannels(tf);
}
*q++='\n';
(void) WriteBlob(tf,q-pixels,pixels);
q=pixels;
if (tf->previous == (Image *) NULL)
{
status=SetImageProgress(tf,SaveImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
if (q != pixels)
{
*q++='\n';
(void) WriteBlob(tf,q-pixels,pixels);
}
break;
}
case '2':
{
unsigned char
pixels[2048];
if (tf->depth <= 8)
(void) WriteBlobString(tf,"255\n");
else
if (tf->depth <= 16)
(void) WriteBlobString(tf,"65535\n");
else
(void) WriteBlobString(tf,"4294967295\n");
q=pixels;
for (y=0; y < (ssize_t) tf->rows; y++)
{
register const Quantum
*magick_restrict p;
register ssize_t
x;
p=GetVirtualPixels(tf,0,y,tf->columns,1,ne);
if (p == (const Quantum *) NULL)
break;
for (x=0; x < (ssize_t) tf->columns; x++)
{
index=ClampToQuantum(GetPixelLuma(tf,p));
if (tf->depth <= 8)
count=(ssize_t) FormatLocaleString(buffer,MagickPathExtent,"%u ",
ScaleQuantumToChar(index));
else
if (tf->depth <= 16)
count=(ssize_t) FormatLocaleString(buffer,MagickPathExtent,
"%u ",ScaleQuantumToShort(index));
else
count=(ssize_t) FormatLocaleString(buffer,MagickPathExtent,
"%u ",ScaleQuantumToLong(index));
extent=(size_t) count;
if ((q-pixels+extent+1) >= sizeof(pixels))
{
*q++='\n';
(void) WriteBlob(tf,q-pixels,pixels);
q=pixels;
}
(void) strncpy((char *) q,buffer,extent);
q+=extent;
p+=GetPixelChannels(tf);
}
*q++='\n';
(void) WriteBlob(tf,q-pixels,pixels);
q=pixels;
if (tf->previous == (Image *) NULL)
{
status=SetImageProgress(tf,SaveImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
if (q != pixels)
{
*q++='\n';
(void) WriteBlob(tf,q-pixels,pixels);
}
break;
}
case '3':
{
unsigned char
pixels[2048];
(void) TransformImageColorspace(tf,sRGBColorspace,ne);
if (tf->depth <= 8)
(void) WriteBlobString(tf,"255\n");
else
if (tf->depth <= 16)
(void) WriteBlobString(tf,"65535\n");
else
(void) WriteBlobString(tf,"4294967295\n");
q=pixels;
for (y=0; y < (ssize_t) tf->rows; y++)
{
register const Quantum
*magick_restrict p;
register ssize_t
x;
p=GetVirtualPixels(tf,0,y,tf->columns,1,ne);
if (p == (const Quantum *) NULL)
break;
for (x=0; x < (ssize_t) tf->columns; x++)
{
if (tf->depth <= 8)
count=(ssize_t) FormatLocaleString(buffer,MagickPathExtent,
"%u %u %u ",ScaleQuantumToChar(GetPixelRed(tf,p)),
ScaleQuantumToChar(GetPixelGreen(tf,p)),
ScaleQuantumToChar(GetPixelBlue(tf,p)));
else
if (tf->depth <= 16)
count=(ssize_t) FormatLocaleString(buffer,MagickPathExtent,
"%u %u %u ",ScaleQuantumToShort(GetPixelRed(tf,p)),
ScaleQuantumToShort(GetPixelGreen(tf,p)),
ScaleQuantumToShort(GetPixelBlue(tf,p)));
else
count=(ssize_t) FormatLocaleString(buffer,MagickPathExtent,
"%u %u %u ",ScaleQuantumToLong(GetPixelRed(tf,p)),
ScaleQuantumToLong(GetPixelGreen(tf,p)),
ScaleQuantumToLong(GetPixelBlue(tf,p)));
extent=(size_t) count;
if ((q-pixels+extent+2) >= sizeof(pixels))
{
*q++='\n';
(void) WriteBlob(tf,q-pixels,pixels);
q=pixels;
}
(void) strncpy((char *) q,buffer,extent);
q+=extent;
p+=GetPixelChannels(tf);
}
*q++='\n';
(void) WriteBlob(tf,q-pixels,pixels);
q=pixels;
if (tf->previous == (Image *) NULL)
{
status=SetImageProgress(tf,SaveImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
if (q != pixels)
{
*q++='\n';
(void) WriteBlob(tf,q-pixels,pixels);
}
break;
}
case '4':
{
register unsigned char
*pixels;
(void) SetImageType(tf,BilevelType,ne);
image->depth=1;
quantum_info=AcquireQuantumInfo(uq,tf);
if (quantum_info == (QuantumInfo *) NULL)
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
(void) SetQuantumEndian(tf,quantum_info,MSBEndian);
quantum_info->min_is_white=MagickTrue;
pixels=GetQuantumPixels(quantum_info);
for (y=0; y < (ssize_t) tf->rows; y++)
{
register const Quantum
*magick_restrict p;
p=GetVirtualPixels(tf,0,y,tf->columns,1,ne);
if (p == (const Quantum *) NULL)
break;
extent=ExportQuantumPixels(tf,(CacheView *) NULL,quantum_info,
GrayQuantum,pixels,ne);
count=WriteBlob(tf,extent,pixels);
if (count != (ssize_t) extent)
break;
if (tf->previous == (Image *) NULL)
{
status=SetImageProgress(tf,SaveImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
quantum_info=DestroyQuantumInfo(quantum_info);
break;
}
case '5':
{
register unsigned char
*pixels;
if (tf->depth > 32)
image->depth=32;
(void) FormatLocaleString(buffer,MagickPathExtent,"%.20g\n",(double)
((MagickOffsetType) GetQuantumRange(tf->depth)));
(void) WriteBlobString(tf,buffer);
quantum_info=AcquireQuantumInfo(uq,tf);
if (quantum_info == (QuantumInfo *) NULL)
ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
(void) SetQuantumEndian(tf,quantum_info,MSBEndian);
quantum_info->min_is_white=MagickTrue;
pixels=GetQuantumPixels(quantum_info);
extent=GetQuantumExtent(tf,quantum_info,GrayQuantum);
for (y=0; y < (ssize_t) tf->rows; y++)
{
register const Quantum
*magick_restrict p;
register ssize_t
x;
p=GetVirtualPixels(tf,0,y,tf->columns,1,ne);
if (p == (const Quantum *) NULL)
break;
q=pixels;
switch (tf->depth)
{
case 8:
case 16:
case 32:
{
extent=ExportQuantumPixels(tf,(CacheView *) NULL,quantum_info,
GrayQuantum,pixels,ne);
break;
}
default:
{
if (tf->depth <= 8)
{
for (x=0; x < (ssize_t) tf->columns; x++)
{
if (IsPixelGray(tf,p) == MagickFalse)
pixel=ScaleQuantumToAny(ClampToQuantum(GetPixelLuma(
image,p)),max_value);
else
{
if (tf->depth == 8)
pixel=ScaleQuantumToChar(GetPixelRed(tf,p));
else
pixel=ScaleQuantumToAny(GetPixelRed(tf,p),
max_value);
}
q=PopCharPixel((unsigned char) pixel,q);
p+=GetPixelChannels(tf);
}
extent=(size_t) (q-pixels);
break;
}
if (tf->depth <= 16)
{
for (x=0; x < (ssize_t) tf->columns; x++)
{
if (IsPixelGray(tf,p) == MagickFalse)
pixel=ScaleQuantumToAny(ClampToQuantum(GetPixelLuma(tf,
p)),max_value);
else
{
if (tf->depth == 16)
pixel=ScaleQuantumToShort(GetPixelRed(tf,p));
else
pixel=ScaleQuantumToAny(GetPixelRed(tf,p),
max_value);
}
q=PopShortPixel(MSBEndian,(unsigned short) pixel,q);
p+=GetPixelChannels(tf);
}
extent=(size_t) (q-pixels);
