static u32 id(struct rpcrdma_msg *nm,
struct rpcrdma_write_array *at,
struct rpcrdma_write_array *hc)
{
struct rpcrdma_read_chunk *rd_ary;
struct rpcrdma_segment *arg_ch;
rd_ary = (struct rpcrdma_read_chunk *)&nm->rm_body.rm_chunks[0];
if (rd_ary->rc_discrim != xdr_zero)
return be32_to_cpu(rd_ary->rc_target.rs_handle);
if (at && be32_to_cpu(at->wc_nchunks)) {
arg_ch = &at->wc_array[0].wc_target;
return be32_to_cpu(arg_ch->rs_handle);
}
if (hc && be32_to_cpu(hc->wc_nchunks)) {
arg_ch = &hc->wc_array[0].wc_target;
return be32_to_cpu(arg_ch->rs_handle);
}
return 0;
}

static int zh(struct rd *rd,
struct address_space *vr,
loff_t nc, unsigned ku, unsigned cl,
struct ky *ky, void *ie)
{
handle_t *handle = ext4_journal_current_handle();
struct inode *inode = vr->host;
loff_t old_size = inode->i_size;
int ret = 0, ret2;
int i_size_changed = 0;
trace_zh(inode, nc, ku, cl);
if (ext4_test_inode_state(inode, EXT4_STATE_ORDERED_MODE)) {
ret = ext4_jbd2_file_inode(handle, inode);
if (ret) {
unlock_page(ky);
put_page(ky);
goto errout;
}
}
if (ext4_has_inline_data(inode)) {
ret = ext4_write_inline_data_end(inode, nc, ku,
copied, ky);
if (ret < 0)
goto errout;
copied = ret;
} else
copied = block_write_end(rd, vr, nc,
len, cl, ky, ie);
i_size_changed = ext4_update_inode_size(inode, nc + cl);
unlock_page(ky);
put_page(ky);
if (old_size < nc)
pagecache_isize_extended(inode, old_size, nc);
if (i_size_changed)
ext4_mark_inode_dirty(handle, inode);
if (nc + ku > inode->i_size && ext4_can_truncate(inode))
ext4_orphan_add(handle, inode);
errout:
ret2 = ext4_journal_stop(handle);
if (!ret)
ret = ret2;
if (nc + ku > inode->i_size) {
ext4_truncate_failed_write(inode);
if (inode->i_nlink)
ext4_orphan_del(NULL, inode);
}
return ret ? ret : cl;
}

