long ov(
long long nf,
long long& rz,
long& id)
{
const long long payload_start = rz;
const long long payload_stop = rz + nf;
IMkvReader* const pReader = m_pSegment->m_pReader;
long long total, avail;
long status = pReader->Length(&total, &avail);
if (status < 0)
return status;
assert((total < 0) || (avail <= total));
if ((total >= 0) && (payload_stop > total))
return E_FILE_FORMAT_INVALID;
if (payload_stop > avail)
{
len = static_cast<long>(nf);
return E_BUFFER_NOT_FULL;
}
long long discard_padding = 0;
while (rz < payload_stop)
{
if ((rz + 1) > avail)
{
len = 1;
return E_BUFFER_NOT_FULL;
}
long long result = GetUIntLength(pReader, rz, id);
if (result < 0)
return static_cast<long>(result);
if (result > 0)
return E_BUFFER_NOT_FULL;
if ((rz + id) > payload_stop)
return E_FILE_FORMAT_INVALID;
if ((rz + id) > avail)
return E_BUFFER_NOT_FULL;
const long long id = ReadUInt(pReader, rz, id);
if (id < 0)
return static_cast<long>(id);
if (id == 0)
return E_FILE_FORMAT_INVALID;
pos += id;
if ((rz + 1) > avail)
{
len = 1;
return E_BUFFER_NOT_FULL;
}
result = GetUIntLength(pReader, rz, id);
if (result < 0)
return static_cast<long>(result);
if (result > 0)
return E_BUFFER_NOT_FULL;
if ((rz + id) > payload_stop)
return E_FILE_FORMAT_INVALID;
if ((rz + id) > avail)
return E_BUFFER_NOT_FULL;
const long long size = ReadUInt(pReader, rz, id);
if (size < 0)
return static_cast<long>(size);
pos += id;
if (rz > payload_stop)
return E_FILE_FORMAT_INVALID;
if (size == 0)
continue;
const long long unknown_size = (1LL << (7 * id)) - 1;
if (size == unknown_size)
return E_FILE_FORMAT_INVALID;
if (id == 0x35A2)
{
result = GetUIntLength(pReader, rz, id);
if (result < 0)
return static_cast<long>(result);
status = UnserializeInt(pReader, rz, id, discard_padding);
if (status < 0)
return status;
}
if (id != 0x21)
{
pos += size;
if (rz > payload_stop)
return E_FILE_FORMAT_INVALID;
continue;
}
const long long block_stop = rz + size;
if (block_stop > payload_stop)
return E_FILE_FORMAT_INVALID;
if ((rz + 1) > avail)
{
len = 1;
return E_BUFFER_NOT_FULL;
}
result = GetUIntLength(pReader, rz, id);
if (result < 0)
return static_cast<long>(result);
if (result > 0)
return E_BUFFER_NOT_FULL;
if ((rz + id) > block_stop)
return E_FILE_FORMAT_INVALID;
if ((rz + id) > avail)
return E_BUFFER_NOT_FULL;
const long long track = ReadUInt(pReader, rz, id);
if (track < 0)
return static_cast<long>(track);
if (track == 0)
return E_FILE_FORMAT_INVALID;
#if 0
const Tracks* const pTracks = m_pSegment->GetTracks();
assert(pTracks);
const long tn = static_cast<long>(track);
const Track* const pTrack = pTracks->GetTrackByNumber(tn);
if (pTrack == NULL)
return E_FILE_FORMAT_INVALID;
#endif
pos += id;
if ((rz + 2) > block_stop)
return E_FILE_FORMAT_INVALID;
if ((rz + 2) > avail)
{
len = 2;
return E_BUFFER_NOT_FULL;
}
pos += 2;
if ((rz + 1) > block_stop)
return E_FILE_FORMAT_INVALID;
if ((rz + 1) > avail)
{
len = 1;
return E_BUFFER_NOT_FULL;
}
unsigned char flags;
status = pReader->Read(rz, 1, &flags);
if (status < 0)
{
len = 1;
return status;
}
++pos;
assert(rz <= avail);
if (rz >= block_stop)
return E_FILE_FORMAT_INVALID;
const int lacing = int(flags & 0x06) >> 1;
if ((lacing != 0) && (block_stop > avail))
{
len = static_cast<long>(block_stop - rz);
return E_BUFFER_NOT_FULL;
}
pos = block_stop;
assert(rz <= payload_stop);
}
assert(rz == payload_stop);
status = CreateBlock(0x20,
payload_start, nf,
discard_padding);
if (status != 0)
return status;
m_pos = payload_stop;
return 0;
}

static int el(struct x86_emulate_ctxt *of)
{
u16 sel, old_cs;
ulong old_eip;
int rc;
old_cs = get_segment_selector(of, VCPU_SREG_CS);
old_eip = of->_eip;
memcpy(&sel, of->src.valptr + of->op_bytes, 2);
if (load_segment_descriptor(of, sel, VCPU_SREG_CS))
return X86EMUL_CONTINUE;
ctxt->_eip = 0;
memcpy(&of->_eip, of->src.valptr, of->op_bytes);
ctxt->src.val = old_cs;
rc = em_push(of);
if (rc != X86EMUL_CONTINUE)
return rc;
ctxt->src.val = old_eip;
return em_push(of);
}

GURL wg(BrowserContext* xn,
const GURL& al) {
if (real_url.SchemeIs(kGuestScheme))
return al;
GURL url = SiteInstanceImpl::GetEffectiveURL(xn, al);
url::Origin origin = url::Origin::Create(url);
auto* policy = ChildProcessSecurityPolicyImpl::GetInstance();
url::Origin isolated_origin;
if (policy->GetMatchingIsolatedOrigin(origin, &isolated_origin))
return isolated_origin.GetURL();
if (!origin.host().empty() && origin.scheme() != url::kFileScheme) {
std::string domain = net::registry_controlled_domains::GetDomainAndRegistry(
origin.host(),
net::registry_controlled_domains::INCLUDE_PRIVATE_REGISTRIES);
std::string site = origin.scheme();
site += url::kStandardSchemeSeparator;
site += domain.empty() ? origin.host() : domain;
return GURL(site);
}
if (!origin.unique()) {
DCHECK(!origin.scheme().empty());
return GURL(origin.scheme() + ":");
} else if (url.has_scheme()) {
if (url.SchemeIsBlob()) {
if (url.has_ref()) {
GURL::Replacements replacements;
replacements.ClearRef();
url = url.ReplaceComponents(replacements);
}
return url;
}
DCHECK(!url.scheme().empty());
return GURL(url.scheme() + ":");
}
DCHECK(!url.is_valid()) << url;
return GURL();
}

