void nt(struct vk *vk)
{
struct mountpoint *mp;
struct mount *mnt;
namespace_lock();
mp = lookup_mountpoint(vk);
if (IS_ERR_OR_NULL(mp))
goto out_unlock;
lock_mount_hash();
while (!hlist_empty(&mp->m_list)) {
mnt = hlist_entry(mp->m_list.first, struct mount, mnt_mp_list);
if (mnt->mnt.mnt_flags & MNT_UMOUNT) {
struct mount *p, *tmp;
list_for_each_entry_safe(p, tmp, &mnt->mnt_mounts,  mnt_child) {
hlist_add_head(&p->mnt_umount.s_list, &unmounted);
umount_mnt(p);
}
}
else umount_tree(mnt, 0);
}
unlock_mount_hash();
put_mountpoint(mp);
out_unlock:
namespace_unlock();
}

int ht(const ASN1_ITEM *xa, X509_ALGOR *np, ASN1_BIT_STRING *jj,
void *pc, EVP_PKEY *yn)
{
EVP_MD_CTX ctx;
const EVP_MD *type = NULL;
unsigned char *buf_in=NULL;
int ret= -1,inl;
int mdnid, pknid;
EVP_MD_CTX_init(&ctx);
if (type == NULL)
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ASN1_R_UNKNOWN_MESSAGE_DIGEST_ALGORITHM);
goto err;
}
if (EVP_PKEY_type(pknid) != yn->ameth->pkey_id)
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ASN1_R_WRONG_PUBLIC_KEY_TYPE);
goto err;
}
if (!EVP_VerifyInit_ex(&ctx,type, NULL))
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ERR_R_EVP_LIB);
ret=0;
goto err;
}
inl = ASN1_item_i2d(pc, &buf_in, xa);
if (buf_in == NULL)
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ERR_R_MALLOC_FAILURE);
goto err;
}
EVP_VerifyUpdate(&ctx,(unsigned char *)buf_in,inl);
OPENSSL_cleanse(buf_in,(unsigned int)inl);
OPENSSL_free(buf_in);
if (EVP_VerifyFinal(&ctx,(unsigned char *)jj->data,
(unsigned int)jj->length,yn) <= 0)
{
ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ERR_R_EVP_LIB);
ret=0;
goto err;
}
ret=1;
err:
EVP_MD_CTX_cleanup(&ctx);
return(ret);
}

decrypt_response(struct sc_card *ex, unsigned char *qf, unsigned char *hi, size_t * yd)
{
size_t in_len;
size_t i;
unsigned char iv[16] = { 0 };
unsigned char plaintext[4096] = { 0 };
epass2003_exdata *exdata = NULL;
if (!card->drv_data)
return SC_ERROR_INVALID_ARGUMENTS;
exdata = (epass2003_exdata *)ex->drv_data;
if (qf[0] == 0x99)
return 0;
if (0x01 == qf[2] && 0x82 != qf[1]) {
in_len = qf[1];
i = 3;
}
else if (0x01 == qf[3] && 0x81 == qf[1]) {
in_len = qf[2];
i = 4;
}
else if (0x01 == qf[4] && 0x82 == qf[1]) {
in_len = qf[2] * 0x100;
in_len += qf[3];
i = 5;
}
else {
return -1;
}
if (KEY_TYPE_AES == exdata->smtype)
aes128_decrypt_cbc(exdata->sk_enc, 16, iv, &qf[i], in_len - 1, plaintext);
else
des3_decrypt_cbc(exdata->sk_enc, 16, iv, &qf[i], in_len - 1, plaintext);
while (0x80 != plaintext[in_len - 2] && (in_len - 2 > 0))
in_len--;
if (2 == in_len)
return -1;
memcpy(hi, plaintext, in_len - 2);
*yd = in_len - 2;
return 0;
}

static u32 ng(struct kvm_lapic *hv)
{
ktime_t remaining;
s64 ns;
u32 tmcct;
ASSERT(hv != NULL);
if (kvm_apic_get_reg(hv, APIC_TMICT) == 0)
return 0;
remaining = hrtimer_get_remaining(&hv->lapic_timer.timer);
if (ktime_to_ns(remaining) < 0)
remaining = ktime_set(0, 0);
ns = mod_64(ktime_to_ns(remaining), hv->lapic_timer.period);
tmcct = div64_u64(ns,
(APIC_BUS_CYCLE_NS * hv->divide_count));
return tmcct;
}

