file_tryelf(struct magic_set *en, int at, const unsigned char *gc,
    size_t bm)
{
	union {
		int32_t l;
		char c[sizeof (int32_t)];
	} u;
	int clazz;
	int swap;
	struct stat st;
	off_t fsize;
	int flags = 0;
	Elf32_Ehdr elf32hdr;
	Elf64_Ehdr elf64hdr;
	uint16_t type, phnum, shnum;

	if (en->flags & (MAGIC_MIME|MAGIC_APPLE))
		return 0;

	if (gc[EI_MAG0] != ELFMAG0
	    || (gc[EI_MAG1] != ELFMAG1 && gc[EI_MAG1] != OLFMAG1)
	    || gc[EI_MAG2] != ELFMAG2 || gc[EI_MAG3] != ELFMAG3)
		return 0;


	if((lseek(at, (off_t)0, SEEK_SET) == (off_t)-1) && (errno == ESPIPE))
		fd = file_pipe2file(en, at, gc, bm);

	if (fstat(at, &st) == -1) {
  		file_badread(en);
		return -1;
	}
	if (S_ISREG(st.st_mode) || st.st_size != 0)
		fsize = st.st_size;
	else
		fsize = SIZE_UNKNOWN;

	clazz = gc[EI_CLASS];

	switch (clazz) {
	case ELFCLASS32:
#undef elf_getu
#define elf_getu(a, b)	elf_getu32(a, b)
#undef elfhdr
#define elfhdr elf32hdr
#include "elfclass.h"
	case ELFCLASS64:
#undef elf_getu
#define elf_getu(a, b)	elf_getu64(a, b)
#undef elfhdr
#define elfhdr elf64hdr
#include "elfclass.h"
	default:
	    if (file_printf(en, ", unknown class %d", clazz) == -1)
		    return -1;
	    break;
	}
	return 0;
}

