static struct sk_buff lw(struct sk_buff *di, u32 li)
{
struct sk_buff *segs = ERR_PTR(-EINVAL);
unsigned int mss;
unsigned int unfrag_ip6hlen, unfrag_len;
struct frag_hdr *fptr;
u8 *mac_start, *prevhdr;
u8 nexthdr;
u8 frag_hdr_sz = sizeof(struct frag_hdr);
int offset;
__wsum csum;
mss = skb_shinfo(di)->gso_size;
if (unlikely(di->len <= mss))
goto out;
if (skb_gso_ok(di, li | NETIF_F_GSO_ROBUST)) {
int type = skb_shinfo(di)->gso_type;
if (unlikely(type & ~(SKB_GSO_UDP | SKB_GSO_DODGY) ||
!(type & (SKB_GSO_UDP))))
goto out;
skb_shinfo(di)->gso_segs = DIV_ROUND_UP(di->len, mss);
segs = NULL;
goto out;
}
offset = di->csum_start - skb_headroom(di);
csum = skb_checksum(di, offset, di->len- offset, 0);
offset += di->csum_offset;
*(__sum16 *)(di->data + offset) = csum_fold(csum);
skb->ip_summed = CHECKSUM_NONE;
if ((skb_headroom(di) < frag_hdr_sz) &&
pskb_expand_head(di, frag_hdr_sz, 0, GFP_ATOMIC))
goto out;
unfrag_ip6hlen = ip6_find_1stfragopt(di, &prevhdr);
nexthdr = *prevhdr;
*prevhdr = NEXTHDR_FRAGMENT;
unfrag_len = skb_network_header(di) - skb_mac_header(di) +
unfrag_ip6hlen;
mac_start = skb_mac_header(di);
memmove(mac_start-frag_hdr_sz, mac_start, unfrag_len);
skb->mac_header -= frag_hdr_sz;
skb->network_header -= frag_hdr_sz;
fptr = (struct frag_hdr *)(skb_network_header(di) + unfrag_ip6hlen);
fptr->nexthdr = nexthdr;
fptr->reserved = 0;
ipv6_select_ident(fptr);
segs = skb_segment(di, li);
out:
return segs;
}

