m_authenticate(struct Client *cr, struct Client *tk,
int jx, const char *parv[])
{
struct Client *agent_p = NULL;
struct Client *saslserv_p = NULL;
if(!IsCapable(tk, CLICAP_SASL))
return 0;
if (strlen(cr->id) == 3)
{
exit_client(cr, cr, cr, "Mixing client and server protocol");
return 0;
}
saslserv_p = find_named_client(ConfigFileEntry.sasl_service);
if (saslserv_p == NULL || !IsService(saslserv_p))
{
sendto_one(tk, form_str(ERR_SASLABORTED), me.name, EmptyString(tk->name) ? "*" : tk->name);
return 0;
}
if(tk->localClient->sasl_complete)
{
*tk->localClient->sasl_agent = '\0';
source_p->localClient->sasl_complete = 0;
}
if(strlen(parv[1]) > 400)
{
sendto_one(tk, form_str(ERR_SASLTOOLONG), me.name, EmptyString(tk->name) ? "*" : tk->name);
return 0;
}
if(!*tk->id)
{
strcpy(tk->id, generate_uid());
add_to_id_hash(tk->id, tk);
}
if(*tk->localClient->sasl_agent)
agent_p = find_id(tk->localClient->sasl_agent);
if(agent_p == NULL)
{
sendto_one(saslserv_p, ":%s ENCAP %s SASL %s %s H %s %s",
me.id, saslserv_p->servptr->name, tk->id, saslserv_p->id,
source_p->host, tk->sockhost);
if (!strcmp(parv[1], "EXTERNAL") && tk->certfp != NULL)
sendto_one(saslserv_p, ":%s ENCAP %s SASL %s %s S %s %s",
me.id, saslserv_p->servptr->name, tk->id, saslserv_p->id,
parv[1], tk->certfp);
else
sendto_one(saslserv_p, ":%s ENCAP %s SASL %s %s S %s",
me.id, saslserv_p->servptr->name, tk->id, saslserv_p->id,
parv[1]);
rb_strlcpy(tk->localClient->sasl_agent, saslserv_p->id, IDLEN);
}
else
sendto_one(agent_p, ":%s ENCAP %s SASL %s %s C %s",
me.id, agent_p->servptr->name, tk->id, agent_p->id,
parv[1]);
source_p->localClient->sasl_out++;
return 0;
}

process_secondary_order(STREAM xe)
{
uint16 length;
uint16 flags;
uint8 type;
uint8 *next_order;
in_uint16_le(xe, length);
in_uint16_le(xe, flags);
in_uint8(xe, type);
next_order = xe->p + (sint16) length + 7;
switch (type)
{
case RDP_ORDER_RAW_BMPCACHE:
process_raw_bmpcache(xe);
break;
case RDP_ORDER_COLCACHE:
process_colcache(xe);
break;
case RDP_ORDER_BMPCACHE:
process_bmpcache(xe);
break;
case RDP_ORDER_FONTCACHE:
process_fontcache(xe);
break;
case RDP_ORDER_RAW_BMPCACHE2:
process_bmpcache2(xe, flags, False);
break;
case RDP_ORDER_BMPCACHE2:
process_bmpcache2(xe, flags, True);
break;
case RDP_ORDER_BRUSHCACHE:
process_brushcache(xe, flags);
break;
default:
logger(Graphics, Warning,
"process_secondary_order(), unhandled secondary order %d", type);
}
s->p = next_order;
}

