ZEND_API void lo(zend_object_handle iy, const zend_object_handlers *handlers rl)
{
struct _store_object *obj;
int failure = 0;
if (!EG(objects_store).object_buckets) {
return;
}
obj = &EG(objects_store).object_buckets[iy].bucket.obj;
if (EG(objects_store).object_buckets[iy].valid) {
if (obj->refcount == 1) {
if (!EG(objects_store).object_buckets[iy].destructor_called) {
EG(objects_store).object_buckets[iy].destructor_called = 1;
if (obj->dtor) {
if (handlers && !obj->handlers) {
obj->handlers = handlers;
}
zend_try {
obj->dtor(obj->object, iy TSRMLS_CC);
} zend_catch {
failure = 1;
} zend_end_try();
}
}
obj = &EG(objects_store).object_buckets[iy].bucket.obj;
if (obj->refcount == 1) {
GC_REMOVE_ZOBJ_FROM_BUFFER(obj);
if (obj->free_storage) {
zend_try {
obj->free_storage(obj->object TSRMLS_CC);
} zend_catch {
failure = 1;
} zend_end_try();
}
ZEND_OBJECTS_STORE_ADD_TO_FREE_LIST();
}
}
}
obj->refcount--;
#if ZEND_DEBUG_OBJECTS
if (obj->refcount == 0) {
fprintf(stderr, "Deallocated object id #%d\n", iy);
} else {
fprintf(stderr, "Decreased refcount of object id #%d\n", iy);
}
#endif
if (failure) {
zend_bailout();
}
}

