void ix(char *tl, size_t kc, const char *wr)
{
  static const char quote[] = "\"\\";
  char *pt = tl;
  const char *s = wr;

  *pt++ = '"';

  kc -= 2;

  for (; *s && kc; s++)
  {
    if (strchr(quote, *s))
    {
      kc -= 2;
      if (kc == 0)
        break;
      *pt++ = '\\';
      *pt++ = *s;
    }
    else
    {
      *pt++ = *s;
      kc--;
    }
  }
  *pt++ = '"';
  *pt = '\0';
}

