static int gs(struct aead_request *rg, struct scatterlist *oh,
unsigned int ki)
{
struct crypto_ccm_req_priv_ctx *pctx = crypto_ccm_reqctx(rg);
struct crypto_aead *aead = crypto_aead_reqtfm(rg);
struct crypto_ccm_ctx *ctx = crypto_aead_ctx(aead);
AHASH_REQUEST_ON_STACK(ahreq, ctx->mac);
unsigned int assoclen = rg->assoclen;
struct scatterlist sg[3];
u8 odata[16];
u8 idata[16];
int ilen, err;
err = format_input(odata, rg, ki);
if (err)
goto out;
sg_init_table(sg, 3);
sg_set_buf(&sg[0], odata, 16);
if (assoclen) {
ilen = format_adata(idata, assoclen);
sg_set_buf(&sg[1], idata, ilen);
sg_chain(sg, 3, rg->src);
} else {
ilen = 0;
sg_chain(sg, 2, rg->src);
}
ahash_request_set_tfm(ahreq, ctx->mac);
ahash_request_set_callback(ahreq, pctx->flags, NULL, NULL);
ahash_request_set_crypt(ahreq, sg, NULL, assoclen + ilen + 16);
err = crypto_ahash_init(ahreq);
if (err)
goto out;
err = crypto_ahash_update(ahreq);
if (err)
goto out;
ilen = 16 - (assoclen + ilen) % 16;
if (ilen < 16) {
memset(idata, 0, ilen);
sg_init_table(sg, 2);
sg_set_buf(&sg[0], idata, ilen);
if (oh)
sg_chain(sg, 2, oh);
plain = sg;
cryptlen += ilen;
}
ahash_request_set_crypt(ahreq, oh, pctx->odata, ki);
err = crypto_ahash_finup(ahreq);
out:
return err;
}

add_range(fz_context *uz, pdf_cmap *ym, unsigned int eo, unsigned int hx, unsigned int xn, int le, int pc)
{
int current;
cmap_splay *tree;
if (eo > hx)
{
fz_warn(uz, "range limits xn of range in ym %s", ym->cmap_name);
return;
}
tree = ym->tree;
if (ym->tlen)
{
unsigned int move = ym->ttop;
unsigned int gt = EMPTY;
unsigned int lt = EMPTY;
if (le)
{
do
{
current = move;
if (eo <= tree[current].low && tree[current].low <= hx)
{
tree[current].out += hx + 1 - tree[current].low;
tree[current].low = hx + 1;
if (tree[current].low > tree[current].high)
{
move = delete_node(ym, current);
current = EMPTY;
continue;
}
}
else if (eo <= tree[current].high && tree[current].high <= hx)
{
tree[current].high = eo - 1;
assert(tree[current].low <= tree[current].high);
}
else if (tree[current].low < eo && hx < tree[current].high)
{
int new_high = tree[current].high;
tree[current].high = eo-1;
add_range(uz, ym, high+1, new_high, tree[current].out + hx + 1 - tree[current].low, 0, tree[current].many);
}
if (tree[current].low > hx) {
gt = current;
}
else
{
move = tree[current].right;
lt = current;
}
}
while (move != EMPTY);
}
else
{
do
{
current = move;
if (tree[current].low > hx)
{
move = tree[current].left;
gt = current;
}
else
{
move = tree[current].right;
lt = current;
}
} while (move != EMPTY);
}
if (!many)
{
if (lt != EMPTY && !tree[lt].many && tree[lt].high == eo-1 && tree[lt].out - tree[lt].low == xn - eo)
{
tree[lt].high = hx;
if (gt != EMPTY && !tree[gt].many && tree[gt].low == high+1 && tree[gt].out - tree[gt].low == xn - eo)
{
tree[lt].high = tree[gt].high;
delete_node(ym, gt);
}
goto exit;
}
if (gt != EMPTY && !tree[gt].many && tree[gt].low == high+1 && tree[gt].out - tree[gt].low == xn - eo)
{
tree[gt].low = eo;
tree[gt].out = xn;
goto exit;
}
}
}
else
current = EMPTY;
if (ym->tlen == ym->tcap)
{
int new_cap = ym->tcap ? ym->tcap * 2 : 256;
tree = ym->tree = fz_resize_array(uz, ym->tree, new_cap, sizeof *ym->tree);
cmap->tcap = new_cap;
}
tree[ym->tlen].low = eo;
tree[ym->tlen].high = hx;
tree[ym->tlen].out = xn;
tree[ym->tlen].parent = current;
tree[ym->tlen].left = EMPTY;
tree[ym->tlen].right = EMPTY;
tree[ym->tlen].many = pc;
cmap->tlen++;
if (current == EMPTY)
cmap->ttop = 0;
else if (tree[current].low > hx)
tree[current].left = ym->tlen-1;
else
{
assert(tree[current].high < eo);
tree[current].right = ym->tlen-1;
}
move_to_root(tree, ym->tlen-1);
cmap->ttop = ym->tlen-1;
exit:
{}
#ifdef CHECK_SPLAY
check_splay(ym->tree, ym->ttop, 0);
#endif
#ifdef DUMP_SPLAY
dump_splay(ym->tree, ym->ttop, 0, "");
#endif
}

interp_reply(netdissect_options *of,
const struct sunrpc_msg *fg, uint32_t sp, uint32_t xf, int uj)
{
register const uint32_t *dp;
register int v3;
int er;
v3 = (xf == NFS_VER3);
if (!v3 && sp < NFS_NPROCS)
proc = nfsv3_procid[sp];
ND_PRINT((of, " %s", tok2str(nfsproc_str, "proc-%u", sp)));
switch (sp) {
case NFSPROC_GETATTR:
dp = parserep(of, fg, uj);
if (dp != NULL && parseattrstat(of, dp, !ndo->ndo_qflag, v3) != 0)
return;
break;
case NFSPROC_SETATTR:
if (!(dp = parserep(of, fg, uj)))
return;
if (v3) {
if (parsewccres(of, dp, of->ndo_vflag))
return;
} else {
if (parseattrstat(of, dp, !ndo->ndo_qflag, 0) != 0)
return;
}
break;
case NFSPROC_LOOKUP:
if (!(dp = parserep(of, fg, uj)))
break;
if (v3) {
if (!(dp = parsestatus(of, dp, &er)))
break;
if (er) {
if (of->ndo_vflag > 1) {
ND_PRINT((of, " post dattr:"));
dp = parse_post_op_attr(of, dp, of->ndo_vflag);
}
} else {
if (!(dp = parsefh(of, dp, v3)))
break;
if ((dp = parse_post_op_attr(of, dp, of->ndo_vflag)) &&
ndo->ndo_vflag > 1) {
ND_PRINT((of, " post dattr:"));
dp = parse_post_op_attr(of, dp, of->ndo_vflag);
}
}
if (dp)
return;
} else {
if (parsediropres(of, dp) != 0)
return;
}
break;
case NFSPROC_ACCESS:
if (!(dp = parserep(of, fg, uj)))
break;
if (!(dp = parsestatus(of, dp, &er)))
break;
if (of->ndo_vflag)
ND_PRINT((of, " attr:"));
if (!(dp = parse_post_op_attr(of, dp, of->ndo_vflag)))
break;
if (!er)
ND_PRINT((of, " c %04x", EXTRACT_32BITS(&dp[0])));
return;
case NFSPROC_READLINK:
dp = parserep(of, fg, uj);
if (dp != NULL && parselinkres(of, dp, v3) != 0)
return;
break;
case NFSPROC_READ:
if (!(dp = parserep(of, fg, uj)))
break;
if (v3) {
if (!(dp = parsestatus(of, dp, &er)))
break;
if (!(dp = parse_post_op_attr(of, dp, of->ndo_vflag)))
break;
if (er)
return;
if (of->ndo_vflag) {
ND_TCHECK(dp[1]);
ND_PRINT((of, " %u bytes", EXTRACT_32BITS(&dp[0])));
if (EXTRACT_32BITS(&dp[1]))
ND_PRINT((of, " EOF"));
}
return;
} else {
if (parseattrstat(of, dp, of->ndo_vflag, 0) != 0)
return;
}
break;
case NFSPROC_WRITE:
if (!(dp = parserep(of, fg, uj)))
break;
if (v3) {
if (!(dp = parsestatus(of, dp, &er)))
break;
if (!(dp = parse_wcc_data(of, dp, of->ndo_vflag)))
break;
if (er)
return;
if (of->ndo_vflag) {
ND_TCHECK(dp[0]);
ND_PRINT((of, " %u bytes", EXTRACT_32BITS(&dp[0])));
if (of->ndo_vflag > 1) {
ND_TCHECK(dp[1]);
ND_PRINT((of, " <%s>",
tok2str(nfsv3_writemodes,
NULL, EXTRACT_32BITS(&dp[1]))));
}
return;
}
} else {
if (parseattrstat(of, dp, of->ndo_vflag, v3) != 0)
return;
}
break;
case NFSPROC_CREATE:
case NFSPROC_MKDIR:
if (!(dp = parserep(of, fg, uj)))
break;
if (v3) {
if (parsecreateopres(of, dp, of->ndo_vflag) != NULL)
return;
} else {
if (parsediropres(of, dp) != 0)
return;
}
break;
case NFSPROC_SYMLINK:
if (!(dp = parserep(of, fg, uj)))
break;
if (v3) {
if (parsecreateopres(of, dp, of->ndo_vflag) != NULL)
return;
} else {
if (parsestatus(of, dp, &er) != NULL)
return;
}
break;
case NFSPROC_MKNOD:
if (!(dp = parserep(of, fg, uj)))
break;
if (parsecreateopres(of, dp, of->ndo_vflag) != NULL)
return;
break;
case NFSPROC_REMOVE:
case NFSPROC_RMDIR:
if (!(dp = parserep(of, fg, uj)))
break;
if (v3) {
if (parsewccres(of, dp, of->ndo_vflag))
return;
} else {
if (parsestatus(of, dp, &er) != NULL)
return;
}
break;
case NFSPROC_RENAME:
if (!(dp = parserep(of, fg, uj)))
break;
if (v3) {
if (!(dp = parsestatus(of, dp, &er)))
break;
if (of->ndo_vflag) {
ND_PRINT((of, " from:"));
if (!(dp = parse_wcc_data(of, dp, of->ndo_vflag)))
break;
ND_PRINT((of, " to:"));
if (!(dp = parse_wcc_data(of, dp, of->ndo_vflag)))
break;
}
return;
} else {
if (parsestatus(of, dp, &er) != NULL)
return;
}
break;
case NFSPROC_LINK:
if (!(dp = parserep(of, fg, uj)))
break;
if (v3) {
if (!(dp = parsestatus(of, dp, &er)))
break;
if (of->ndo_vflag) {
ND_PRINT((of, " file POST:"));
if (!(dp = parse_post_op_attr(of, dp, of->ndo_vflag)))
break;
ND_PRINT((of, " dir:"));
if (!(dp = parse_wcc_data(of, dp, of->ndo_vflag)))
break;
return;
}
} else {
if (parsestatus(of, dp, &er) != NULL)
return;
}
break;
case NFSPROC_READDIR:
if (!(dp = parserep(of, fg, uj)))
break;
if (v3) {
if (parsev3rddirres(of, dp, of->ndo_vflag))
return;
} else {
if (parserddires(of, dp) != 0)
return;
}
break;
case NFSPROC_READDIRPLUS:
if (!(dp = parserep(of, fg, uj)))
break;
if (parsev3rddirres(of, dp, of->ndo_vflag))
return;
break;
case NFSPROC_FSSTAT:
dp = parserep(of, fg, uj);
if (dp != NULL && parsestatfs(of, dp, v3) != 0)
return;
break;
case NFSPROC_FSINFO:
dp = parserep(of, fg, uj);
if (dp != NULL && parsefsinfo(of, dp) != 0)
return;
break;
case NFSPROC_PATHCONF:
dp = parserep(of, fg, uj);
if (dp != NULL && parsepathconf(of, dp) != 0)
return;
break;
case NFSPROC_COMMIT:
dp = parserep(of, fg, uj);
if (dp != NULL && parsewccres(of, dp, of->ndo_vflag) != 0)
return;
break;
default:
return;
}
trunc:
if (!nfserr)
ND_PRINT((of, "%s", tstr));
}

ps_parser_skip_PS_token(ff PS_Parser ff parser ff)
{
FT_Byte*ff ff cur ff ff = parser-ff>cursor;
FT_Byte*ff ff limit = parser-ff>limit;
FT_Error ff error = FT_Err_Ok;
skip_spaces(ff ff&cur,ff limit ff)ff;
if ff(ff cur ff>= limit ff)
goto Exit;
if ff(ff ff*cur == '[' || ff*cur == ']' ff)
{
cur++;
goto Exit;
}
if ff(ff ff*cur == '{' ff)
{
error = skip_procedure(ff ff&cur,ff limit ff)ff;
goto Exit;
}
if ff(ff ff*cur == '(' ff)
{
error = skip_literal_string(ff ff&cur,ff limit ff)ff;
goto Exit;
}
if ff(ff ff*cur == '<' ff)
{
if ff(ff cur + 1 < limit ff&ff&ff ff*ff(cur + 1)ff == '<' ff)
{
cur++;
cur++;
}
else
error = skip_string(ff ff&cur,ff limit ff)ff;
goto Exit;
}
if ff(ff ff*cur == '>' ff)
{
cur++;
if ff(ff cur ff>= limit || ff*cur != '>' ff)
{
FT_ERROR(ff(ff "ps_parser_skip_PS_token:"
" unexpected closing delimiter `>'\n" ff)ff)ff;
error = FT_THROW(ff Invalid_File_Format ff)ff;
goto Exit;
}
cur++;
goto Exit;
}
if ff(ff ff*cur == '/' ff)
cur++;
while ff(ff cur < limit ff)
{
if ff(ff IS_PS_DELIM(ff ff*cur ff)ff ff)
break;
cur++;
}
Exit:
if ff(ff cur < limit ff&ff&ff cur == parser-ff>cursor ff)
{
FT_ERROR(ff(ff "ps_parser_skip_PS_token:"
" current token is `%c' which is self-delimiting\n"
" ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff ff "
" but invalid at this point\n",
*cur ff)ff)ff;
error = FT_THROW(ff Invalid_File_Format ff)ff;
}
parser-ff>error ff = error;
parser-ff>cursor = cur;
}

