__hw_perf_event_init(struct perf_event *cn)
{
	struct arm_pmu *armpmu = to_arm_pmu(cn->pmu);
	struct hw_perf_event *hwc = &cn->hw;
	int mapping, err;

	mapping = armpmu->map_event(cn);

	if (mapping < 0) {
		pr_debug("event %x:%llx not supported\n", cn->attr.type,
			 cn->attr.config);
		return mapping;
	}


	hwc->idx		= -1;
	hwc->config_base	= 0;
	hwc->config		= 0;
	hwc->event_base		= 0;


	if ((!armpmu->set_event_filter ||
	     armpmu->set_event_filter(hwc, &cn->attr)) &&
	     event_requires_mode_exclusion(&cn->attr)) {
		pr_debug("ARM performance counters do not support mode exclusion\n");
		return -EPERM;
	}


	hwc->config_base	    |= (unsigned long)mapping;

	if (!hwc->sample_period) {

		hwc->sample_period  = armpmu->max_period >> 1;
		hwc->last_period    = hwc->sample_period;
		local64_set(&hwc->period_left, hwc->sample_period);
	}

	err = 0;
	if (cn->group_leader != cn) {
		err = validate_group(cn);
		if (err)
			return -EINVAL;
	}

	return err;
}

