for (p = ef; (c = *p); p++) {
if (!((c >= 'a' && c <= 'z')
|| (c >= 'A' && c <= 'Z')
|| (c >= '0' && c <= '9')
|| c == ','
|| c == '-')) {
ret = 0;
break;
}
}
len = p - ef;
if (len == 0 || len > 128) {
ret = 0;
}
return ret;
}

