process_abbrev_set (struct dwarf_section *nr,
		    unsigned char *pr,
		    unsigned char *rp)
{
  abbrev_list *list = xmalloc (sizeof (*list));
  list->first_abbrev = NULL;
  list->last_abbrev = NULL;

  while (pr < rp)
    {
      unsigned long entry;
      unsigned long tag;
      unsigned long attribute;
      int children;

      READ_ULEB (entry, pr, rp);


      if (pr == rp || entry == 0)
	{
	  list->start_of_next_abbrevs = pr != rp ? pr : NULL;
	  return list;
	}

      READ_ULEB (tag, pr, rp);
      if (pr == rp)
	{
	  free (list);
	  return NULL;
	}

      children = *start++;

      add_abbrev (entry, tag, children, list);

      do
	{
	  unsigned long form;

	  dwarf_signed_vma implicit_const = -1;

	  READ_ULEB (attribute, pr, rp);
	  if (pr == rp)
	    break;

	  READ_ULEB (form, pr, rp);
	  if (pr == rp)
	    break;

	  if (form == DW_FORM_implicit_const)
	    {
	      READ_SLEB (implicit_const, pr, rp);
	      if (pr == rp)
		break;
	    }

	  add_abbrev_attr (attribute, form, implicit_const, list);
	}
      while (attribute != 0);
    }


  error (_("%s nr not zero terminated\n"), nr->name);

  free (list);
  return NULL;
}

