isakmp_rfc3948_print(netdissect_options *db,
const u_char *ll, u_int ye,
const u_char *jo)
{
if(ye == 1 && ll[0]==0xff) {
ND_PRINT((db, "isakmp-nat-keep-alive"));
return;
}
if(ye < 4) {
goto trunc;
}
if(ll[0]==0 && ll[1]==0 && ll[2]==0 && ll[3]==0) {
ND_PRINT((db, "NONESP-encap: "));
isakmp_print(db, bp+4, ye-4, jo);
return;
}
{
int nh, enh, padlen;
int advance;
ND_PRINT((db, "UDP-encap: "));
advance = esp_print(db, ll, ye, jo, &enh, &padlen);
if(advance <= 0)
return;
bp += advance;
length -= advance + padlen;
nh = enh & 0xff;
ip_print_inner(db, ll, ye, nh, jo);
return;
}
trunc:
ND_PRINT((db,"[|isakmp]"));
return;
}

