const CImg<T>& fp(std::FILE *const sn, const char *const ey) const {
  if (!file && !filename)
    throw CImgArgumentException(_cimg_instance
                                "save_rgba(): Specified ey is (null).",
                                cimg_instance);
  if (is_empty()) { cimg::fempty(sn,ey); return *this; }
  if (_spectrum!=4)
    cimg::warn(_cimg_instance
               "save_rgba(): image instance has not exactly 4 channels, for sn '%s'.",
               cimg_instance,
               filename?filename:"(FILE*)");

  std::FILE *const nfile = file?file:cimg::fopen(ey,"wb");
  const ulongT wh = (ulongT)_width*_height;
  unsigned char *const buffer = new unsigned char[4*wh], *nbuffer = buffer;
  const T
    *ptr1 = data(0,0,0,0),
    *ptr2 = _spectrum>1?data(0,0,0,1):0,
    *ptr3 = _spectrum>2?data(0,0,0,2):0,
    *ptr4 = _spectrum>3?data(0,0,0,3):0;
  switch (_spectrum) {
  case 1 : { 
    for (ulongT k = 0; k<wh; ++k) {
      const unsigned char val = (unsigned char)*(ptr1++);
      *(nbuffer++) = val;
      *(nbuffer++) = val;
      *(nbuffer++) = val;
      *(nbuffer++) = 255;
    }
  } break;
  case 2 : { 
    for (ulongT k = 0; k<wh; ++k) {
      *(nbuffer++) = (unsigned char)(*(ptr1++));
      *(nbuffer++) = (unsigned char)(*(ptr2++));
      *(nbuffer++) = 0;
      *(nbuffer++) = 255;
    }
  } break;
  case 3 : { 
    for (ulongT k = 0; k<wh; ++k) {
      *(nbuffer++) = (unsigned char)(*(ptr1++));
      *(nbuffer++) = (unsigned char)(*(ptr2++));
      *(nbuffer++) = (unsigned char)(*(ptr3++));
      *(nbuffer++) = 255;
    }
  } break;
  default : { 
    for (ulongT k = 0; k<wh; ++k) {
      *(nbuffer++) = (unsigned char)(*(ptr1++));
      *(nbuffer++) = (unsigned char)(*(ptr2++));
      *(nbuffer++) = (unsigned char)(*(ptr3++));
      *(nbuffer++) = (unsigned char)(*(ptr4++));
    }
  }
  }
  cimg::fwrite(buffer,4*wh,nfile);
  if (!file) cimg::fclose(nfile);
  delete[] buffer;
  return *this;
}

local int xq(struct state *xe)
{
    static int virgin = 1;
    static boost::int16_t lencnt[MAXBITS+1], lensym[FIXLCODES];
    static boost::int16_t distcnt[MAXBITS+1], distsym[MAXDCODES];
    static struct huffman lencode = {lencnt, lensym};
    static struct huffman distcode = {distcnt, distsym};


    if (virgin) {
        int symbol;
        boost::int16_t lengths[FIXLCODES];


        for (symbol = 0; symbol < 144; symbol++)
            lengths[symbol] = 8;
        for (; symbol < 256; symbol++)
            lengths[symbol] = 9;
        for (; symbol < 280; symbol++)
            lengths[symbol] = 7;
        for (; symbol < FIXLCODES; symbol++)
            lengths[symbol] = 8;
        construct(&lencode, lengths, FIXLCODES);


        for (symbol = 0; symbol < MAXDCODES; symbol++)
            lengths[symbol] = 5;
        construct(&distcode, lengths, MAXDCODES);


        virgin = 0;
    }


    return codes(xe, &lencode, &distcode);
}

asmlinkage void __kprobes pn(struct pt_regs *wj)
{
struct mm_struct *mm = current->mm;
struct vm_area_struct *vma;
unsigned int insn = 0;
int si_code, fault_code, fault;
unsigned long address, mm_rss;
fault_code = get_thread_fault_code();
if (notify_page_fault(wj))
return;
si_code = SEGV_MAPERR;
address = current_thread_info()->fault_address;
if ((fault_code & FAULT_CODE_ITLB) &&
(fault_code & FAULT_CODE_DTLB))
BUG();
if (test_thread_flag(TIF_32BIT)) {
if (!(wj->tstate & TSTATE_PRIV)) {
if (unlikely((wj->tpc >> 32) != 0)) {
bogus_32bit_fault_tpc(wj);
goto intr_or_no_mm;
}
}
if (unlikely((address >> 32) != 0)) {
bogus_32bit_fault_address(wj, address);
goto intr_or_no_mm;
}
}
if (wj->tstate & TSTATE_PRIV) {
unsigned long tpc = wj->tpc;
if ((tpc >= KERNBASE && tpc < (unsigned long) __init_end) ||
(tpc >= MODULES_VADDR && tpc < MODULES_END)) {
} else {
bad_kernel_pc(wj, address);
return;
}
}
if (in_atomic() || !mm)
goto intr_or_no_mm;
perf_sw_event(PERF_COUNT_SW_PAGE_FAULTS, 1, 0, wj, address);
if (!down_read_trylock(&mm->mmap_sem)) {
if ((wj->tstate & TSTATE_PRIV) &&
!search_exception_tables(wj->tpc)) {
insn = get_fault_insn(wj, insn);
goto handle_kernel_fault;
}
down_read(&mm->mmap_sem);
}
vma = find_vma(mm, address);
if (!vma)
goto bad_area;
if (((fault_code &
(FAULT_CODE_DTLB | FAULT_CODE_WRITE | FAULT_CODE_WINFIXUP)) == FAULT_CODE_DTLB) &&
(vma->vm_flags & VM_WRITE) != 0) {
insn = get_fault_insn(wj, 0);
if (!insn)
goto continue_fault;
if ((insn & 0xc0200000) == 0xc0200000 &&
(insn & 0x01780000) != 0x01680000) {
fault_code |= FAULT_CODE_WRITE;
}
}
continue_fault:
if (vma->vm_start <= address)
goto good_area;
if (!(vma->vm_flags & VM_GROWSDOWN))
goto bad_area;
if (!(fault_code & FAULT_CODE_WRITE)) {
insn = get_fault_insn(wj, insn);
if ((insn & 0xc0800000) == 0xc0800000) {
unsigned char asi;
if (insn & 0x2000)
asi = (wj->tstate >> 24);
else
asi = (insn >> 5);
if ((asi & 0xf2) == 0x82)
goto bad_area;
}
}
if (expand_stack(vma, address))
goto bad_area;
good_area:
si_code = SEGV_ACCERR;
if ((fault_code & FAULT_CODE_ITLB) && !(vma->vm_flags & VM_EXEC)) {
BUG_ON(address != wj->tpc);
BUG_ON(wj->tstate & TSTATE_PRIV);
goto bad_area;
}
if (fault_code & FAULT_CODE_WRITE) {
if (!(vma->vm_flags & VM_WRITE))
goto bad_area;
if (tlb_type == spitfire &&
(vma->vm_flags & VM_EXEC) != 0 &&
vma->vm_file != NULL)
set_thread_fault_code(fault_code |
FAULT_CODE_BLKCOMMIT);
} else {
if (!(vma->vm_flags & (VM_READ | VM_EXEC)))
goto bad_area;
}
fault = handle_mm_fault(mm, vma, address, (fault_code & FAULT_CODE_WRITE) ? FAULT_FLAG_WRITE : 0);
if (unlikely(fault & VM_FAULT_ERROR)) {
if (fault & VM_FAULT_OOM)
goto out_of_memory;
else if (fault & VM_FAULT_SIGBUS)
goto do_sigbus;
BUG();
}
if (fault & VM_FAULT_MAJOR) {
current->maj_flt++;
perf_sw_event(PERF_COUNT_SW_PAGE_FAULTS_MAJ, 1, 0,
regs, address);
} else {
current->min_flt++;
perf_sw_event(PERF_COUNT_SW_PAGE_FAULTS_MIN, 1, 0,
regs, address);
}
up_read(&mm->mmap_sem);
mm_rss = get_mm_rss(mm);
#ifdef CONFIG_HUGETLB_PAGE
mm_rss -= (mm->context.huge_pte_count * (HPAGE_SIZE / PAGE_SIZE));
#endif
if (unlikely(mm_rss >
mm->context.tsb_block[MM_TSB_BASE].tsb_rss_limit))
tsb_grow(mm, MM_TSB_BASE, mm_rss);
#ifdef CONFIG_HUGETLB_PAGE
mm_rss = mm->context.huge_pte_count;
if (unlikely(mm_rss >
mm->context.tsb_block[MM_TSB_HUGE].tsb_rss_limit))
tsb_grow(mm, MM_TSB_HUGE, mm_rss);
#endif
return;
bad_area:
insn = get_fault_insn(wj, insn);
up_read(&mm->mmap_sem);
handle_kernel_fault:
do_kernel_fault(wj, si_code, fault_code, insn, address);
return;
out_of_memory:
insn = get_fault_insn(wj, insn);
up_read(&mm->mmap_sem);
if (!(wj->tstate & TSTATE_PRIV)) {
pagefault_out_of_memory();
return;
}
goto handle_kernel_fault;
intr_or_no_mm:
insn = get_fault_insn(wj, 0);
goto handle_kernel_fault;
do_sigbus:
insn = get_fault_insn(wj, insn);
up_read(&mm->mmap_sem);
do_fault_siginfo(BUS_ADRERR, SIGBUS, wj, insn, fault_code);
if (wj->tstate & TSTATE_PRIV)
goto handle_kernel_fault;
}

