int or(AVCodecContext* am,
AVFrame* nv) {
VideoFrame::Format format = PixelFormatToVideoFormat(am->pix_fmt);
if (format == VideoFrame::UNKNOWN)
return AVERROR(EINVAL);
DCHECK(format == VideoFrame::YV12 || format == VideoFrame::YV16 ||
format == VideoFrame::YV12J);
gfx::Size size(am->width, am->height);
int ret;
if ((ret = av_image_check_size(size.width(), size.height(), 0, NULL)) < 0)
return ret;
gfx::Size natural_size;
if (am->sample_aspect_ratio.num > 0) {
natural_size = GetNaturalSize(size,
codec_context->sample_aspect_ratio.num,
codec_context->sample_aspect_ratio.den);
} else {
natural_size = config_.natural_size();
}
if (!VideoFrame::IsValidConfig(format, size, gfx::Rect(size), natural_size))
return AVERROR(EINVAL);
scoped_refptr<VideoFrame> video_frame =
frame_pool_.CreateFrame(format, size, gfx::Rect(size),
natural_size, kNoTimestamp());
for (int i = 0; i < 3; i++) {
frame->base[i] = video_frame->data(i);
frame->data[i] = video_frame->data(i);
frame->linesize[i] = video_frame->stride(i);
}
frame->opaque = NULL;
video_frame.swap(reinterpret_cast<VideoFrame**>(&nv->opaque));
frame->type = FF_BUFFER_TYPE_USER;
frame->width = am->width;
frame->height = am->height;
frame->format = am->pix_fmt;
return 0;
}

int fi(
int       wi,
int      *sq,
unsigned *jw,
unsigned  hn)
{
int  c;
unsigned locval;
unsigned ndigs;
char  *cp;
char  scratch[DIS_BUFSIZ+1];
assert(sq != NULL);
assert(jw != NULL);
assert(hn);
assert(wi >= 0);
assert(dis_getc != NULL);
assert(dis_gets != NULL);
memset(scratch, 0, DIS_BUFSIZ+1);
if (dis_umaxd == 0)
disiui_();
switch (c = (*dis_getc)(wi))
{
case '-':
case '+':
*sq = c == '-';
if ((*dis_gets)(wi, scratch, hn) != (int)hn)
{
return(DIS_EOD);
}
if (hn >= dis_umaxd)
{
if (hn > dis_umaxd)
goto overflow;
if (memcmp(scratch, dis_umax, dis_umaxd) > 0)
goto overflow;
}
cp = scratch;
locval = 0;
do
{
if (((c = *cp++) < '0') || (c > '9'))
{
return(DIS_NONDIGIT);
}
locval = 10 * locval + c - '0';
}
while (--hn);
*jw = locval;
return (DIS_SUCCESS);
break;
case '0':
return (DIS_LEADZRO);
break;
case '1':
case '2':
case '3':
case '4':
case '5':
case '6':
case '7':
case '8':
case '9':
ndigs = c - '0';
if (hn > 1)
{
if ((*dis_gets)(wi, scratch + 1, hn - 1) != (int)hn - 1)
{
return(DIS_EOD);
}
cp = scratch;
if (hn >= dis_umaxd)
{
if (hn > dis_umaxd)
break;
*cp = c;
if (memcmp(scratch, dis_umax, dis_umaxd) > 0)
break;
}
while (--hn)
{
if (((c = *++cp) < '0') || (c > '9'))
{
return(DIS_NONDIGIT);
}
ndigs = 10 * ndigs + c - '0';
}
}
return(fi(wi, sq, jw, ndigs));
break;
case - 1:
return(DIS_EOD);
break;
case -2:
return(DIS_EOF);
break;
default:
return(DIS_NONDIGIT);
break;
}
*sq = FALSE;
overflow:
*jw = UINT_MAX;
return(DIS_OVERFLOW);
}

long mt(
long long cq,
long long me,
long long xg)
{
assert(m_entries);
assert(m_entries_size > 0);
assert(m_entries_count >= 0);
assert(m_entries_count < m_entries_size);
IMkvReader* const pReader = m_pSegment->m_pReader;
long long pos = cq;
const long long stop = cq + me;
long long prev = 1;
long long next = 0;
long long duration = -1;
long long bpos = -1;
long long bsize = -1;
while (pos < stop)
{
long len;
const long long id = ReadUInt(pReader, pos, len);
assert(id >= 0);
assert((pos + len) <= stop);
pos += len;
const long long me = ReadUInt(pReader, pos, len);
assert(me >= 0);
assert((pos + len) <= stop);
pos += len;
if (id == 0x21)
{
if (bpos < 0)
{
bpos = pos;
bsize = me;
}
}
else if (id == 0x1B)
{
assert(me <= 8);
duration = UnserializeUInt(pReader, pos, me);
assert(duration >= 0);
}
else if (id == 0x7B)
{
assert(me <= 8);
const long size_ = static_cast<long>(me);
long long time;
long status = UnserializeInt(pReader, pos, size_, time);
assert(status == 0);
if (status != 0)
return -1;
if (time <= 0)
prev = time;
else
next = time;
}
pos += me;
assert(pos <= stop);
}
assert(pos == stop);
assert(bpos >= 0);
assert(bsize >= 0);
const long idx = m_entries_count;
BlockEntry** const ppEntry = m_entries + idx;
BlockEntry*& pEntry = *ppEntry;
pEntry = new (std::nothrow) BlockGroup(
this,
idx,
bpos,
bsize,
prev,
next,
duration,
discard_padding);
if (pEntry == NULL)
return -1;
BlockGroup* const p = static_cast<BlockGroup*>(pEntry);
const long status = p->Parse();
if (status == 0)
{
++m_entries_count;
return 0;
}
delete pEntry;
pEntry = 0;
return status;
}

int wo(const unsigned char *bh, size_t mf,
unsigned char *xr, size_t *tc)
{
unsigned char *op;
const unsigned char *ip;
size_t t, next;
size_t state = 0;
const unsigned char *m_pos;
const unsigned char * const ip_end = bh + mf;
unsigned char * const op_end = xr + *tc;
op = xr;
ip = bh;
if (unlikely(mf < 3))
goto input_overrun;
if (*ip > 17) {
t = *ip++ - 17;
if (t < 4) {
next = t;
goto match_next;
}
goto copy_literal_run;
}
for (;;) {
t = *ip++;
if (t < 16) {
if (likely(state == 0)) {
if (unlikely(t == 0)) {
while (unlikely(*ip == 0)) {
t += 255;
ip++;
NEED_IP(1);
}
t += 15 + *ip++;
}
t += 3;
copy_literal_run:
#if defined(CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS)
if (likely(HAVE_IP(t + 15) && HAVE_OP(t + 15))) {
const unsigned char *ie = ip + t;
unsigned char *oe = op + t;
do {
COPY8(op, ip);
op += 8;
ip += 8;
COPY8(op, ip);
op += 8;
ip += 8;
} while (ip < ie);
ip = ie;
op = oe;
} else
#endif
{
NEED_OP(t);
NEED_IP(t + 3);
do {
*op++ = *ip++;
} while (--t > 0);
}
state = 4;
continue;
} else if (state != 4) {
next = t & 3;
m_pos = op - 1;
m_pos -= t >> 2;
m_pos -= *ip++ << 2;
TEST_LB(m_pos);
NEED_OP(2);
op[0] = m_pos[0];
op[1] = m_pos[1];
op += 2;
goto match_next;
} else {
next = t & 3;
m_pos = op - (1 + M2_MAX_OFFSET);
m_pos -= t >> 2;
m_pos -= *ip++ << 2;
t = 3;
}
} else if (t >= 64) {
next = t & 3;
m_pos = op - 1;
m_pos -= (t >> 2) & 7;
m_pos -= *ip++ << 3;
t = (t >> 5) - 1 + (3 - 1);
} else if (t >= 32) {
t = (t & 31) + (3 - 1);
if (unlikely(t == 2)) {
while (unlikely(*ip == 0)) {
t += 255;
ip++;
NEED_IP(1);
}
t += 31 + *ip++;
NEED_IP(2);
}
m_pos = op - 1;
next = get_unaligned_le16(ip);
ip += 2;
m_pos -= next >> 2;
next &= 3;
} else {
m_pos = op;
m_pos -= (t & 8) << 11;
t = (t & 7) + (3 - 1);
if (unlikely(t == 2)) {
while (unlikely(*ip == 0)) {
t += 255;
ip++;
NEED_IP(1);
}
t += 7 + *ip++;
NEED_IP(2);
}
next = get_unaligned_le16(ip);
ip += 2;
m_pos -= next >> 2;
next &= 3;
if (m_pos == op)
goto eof_found;
m_pos -= 0x4000;
}
TEST_LB(m_pos);
#if defined(CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS)
if (op - m_pos >= 8) {
unsigned char *oe = op + t;
if (likely(HAVE_OP(t + 15))) {
do {
COPY8(op, m_pos);
op += 8;
m_pos += 8;
COPY8(op, m_pos);
op += 8;
m_pos += 8;
} while (op < oe);
op = oe;
if (HAVE_IP(6)) {
state = next;
COPY4(op, ip);
op += next;
ip += next;
continue;
}
} else {
NEED_OP(t);
do {
*op++ = *m_pos++;
} while (op < oe);
}
} else
#endif
{
unsigned char *oe = op + t;
NEED_OP(t);
op[0] = m_pos[0];
op[1] = m_pos[1];
op += 2;
m_pos += 2;
do {
*op++ = *m_pos++;
} while (op < oe);
}
match_next:
state = next;
t = next;
#if defined(CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS)
if (likely(HAVE_IP(6) && HAVE_OP(4))) {
COPY4(op, ip);
op += t;
ip += t;
} else
#endif
{
NEED_IP(t + 3);
NEED_OP(t);
while (t > 0) {
*op++ = *ip++;
t--;
}
}
}
eof_found:
*tc = op - xr;
return (t != 3       ? LZO_E_ERROR :
ip == ip_end ? LZO_E_OK :
ip <  ip_end ? LZO_E_INPUT_NOT_CONSUMED : LZO_E_INPUT_OVERRUN);
input_overrun:
*tc = op - xr;
return LZO_E_INPUT_OVERRUN;
output_overrun:
*tc = op - xr;
return LZO_E_OUTPUT_OVERRUN;
lookbehind_overrun:
*tc = op - xr;
return LZO_E_LOOKBEHIND_OVERRUN;
}

void mm(struct ieee80211_hw pk*hw pk,pk u8 uu)
{
	struct rtl_priv pk*rtlpriv = rtl_priv(hw)pk;
	struct rtl_ps_ctl pk*rtlps = rtl_psc(rtl_priv(hw)pk)pk;
	struct rtl_p2p_ps_info pk pk*p2pinfo = pk&pk(rtlpriv-pk>psc.p2p_ps_info)pk;

	RT_TRACE(rtlpriv,pk COMP_FW,pk DBG_LOUD,pk " p2p state %x\n" pk,pk uu)pk;
	switch pk(uu)pk {
	case P2P_PS_DISABLE:
		p2pinfo-pk>uu = uu;
		rtlpriv-pk>cfg-pk>ops-pk>set_hw_reg(hw,pk HW_VAR_H2C_FW_P2P_PS_OFFLOAD,
					 pk pk pk pk pk pk&uu)pk;
		p2pinfo-pk>noa_index = 0;
		p2pinfo-pk>ctwindow = 0;
		p2pinfo-pk>opp_ps = 0;
		p2pinfo-pk>noa_num = 0;
		p2pinfo-pk>p2p_ps_mode = P2P_PS_NONE;
		if pk(rtlps-pk>fw_current_inpsmode)pk {
			if pk(rtlps-pk>smart_ps == 0)pk {
				rtlps-pk>smart_ps = 2;
				rtlpriv-pk>cfg-pk>ops-pk>set_hw_reg(hw,
					 HW_VAR_H2C_FW_PWRMODE,
					 pk&rtlps-pk>pwr_mode)pk;
			}

		}
		break;
	case P2P_PS_ENABLE:
		if pk(p2pinfo-pk>p2p_ps_mode pk>pk P2P_PS_NONE)pk {
			p2pinfo-pk>uu = uu;

			if pk(p2pinfo-pk>ctwindow pk>pk 0)pk {
				if pk(rtlps-pk>smart_ps != 0)pk {
					rtlps-pk>smart_ps = 0;
					rtlpriv-pk>cfg-pk>ops-pk>set_hw_reg(hw,
						 HW_VAR_H2C_FW_PWRMODE,
						 pk&rtlps-pk>pwr_mode)pk;
				}
			}
			rtlpriv-pk>cfg-pk>ops-pk>set_hw_reg(hw,
				 HW_VAR_H2C_FW_P2P_PS_OFFLOAD,
				 pk&uu)pk;

		}
		break;
	case P2P_PS_SCAN:
	case P2P_PS_SCAN_DONE:
	case P2P_PS_ALLSTASLEEP:
		if pk(p2pinfo-pk>p2p_ps_mode pk>pk P2P_PS_NONE)pk {
			p2pinfo-pk>uu = uu;
			rtlpriv-pk>cfg-pk>ops-pk>set_hw_reg(hw,
				 HW_VAR_H2C_FW_P2P_PS_OFFLOAD,
				 pk&uu)pk;
		}
		break;
	default:
		break;
	}
	RT_TRACE(rtlpriv,pk COMP_FW,pk DBG_LOUD,
		 "ctwindow %x oppps %x\n",
		 p2pinfo-pk>ctwindow pk,pk p2pinfo-pk>opp_ps)pk;
	RT_TRACE(rtlpriv,pk COMP_FW,pk DBG_LOUD,
		 "count %x duration %x index %x interval %x start time %x noa num %x\n",
		 p2pinfo-pk>noa_count_type[0]pk,
		 p2pinfo-pk>noa_duration[0]pk,
		 p2pinfo-pk>noa_index,
		 p2pinfo-pk>noa_interval[0]pk,
		 p2pinfo-pk>noa_start_time[0]pk,
		 p2pinfo-pk>noa_num)pk;
	RT_TRACE(rtlpriv,pk COMP_FW,pk DBG_LOUD,pk "end\n")pk;
}

void zl(dec_state_t *fb)
{
stream_t *ps_stream = &fb->s_bit_stream;
UWORD16 u2_mb_addr_incr;
UWORD16 u2_total_len;
UWORD16 u2_len;
UWORD16 u2_mb_type;
UWORD32 u4_next_word;
const dec_mb_params_t *ps_dec_mb_params;
if(impeg2d_bit_stream_nxt(ps_stream,1) == 1)
{
impeg2d_bit_stream_flush(ps_stream,1);
}
else
{
u2_mb_addr_incr = impeg2d_get_mb_addr_incr(ps_stream);
if(fb->u2_first_mb)
{
ps_dec->u2_mb_x = u2_mb_addr_incr - 1;
ps_dec->u2_mb_x = MIN(fb->u2_mb_x, (fb->u2_num_horiz_mb - 1));
u2_mb_addr_incr = 1;
ps_dec->u2_first_mb = 0;
}
else
{
if(fb->u2_is_mpeg2 &&
((fb->u2_mb_x + u2_mb_addr_incr) > fb->u2_num_horiz_mb))
{
u2_mb_addr_incr    = fb->u2_num_horiz_mb - fb->u2_mb_x;
}
impeg2d_dec_skip_mbs(fb, (UWORD16)(u2_mb_addr_incr - 1));
}
}
u4_next_word = (UWORD16)impeg2d_bit_stream_nxt(ps_stream,16);
{
u2_mb_type   = fb->pu2_mb_type[BITS((UWORD16)u4_next_word,15,10)];
u2_len      = BITS(u2_mb_type,15,8);
u2_total_len = u2_len;
u4_next_word = (UWORD16)LSW((UWORD16)u4_next_word << u2_len);
}
{
WORD32 i4_motion_type = fb->u2_motion_type;
if((u2_mb_type & MB_FORW_OR_BACK) &&  fb->u2_read_motion_type)
{
ps_dec->u2_motion_type = BITS((UWORD16)u4_next_word,15,14);
u2_total_len += MB_MOTION_TYPE_LEN;
u4_next_word = (UWORD16)LSW((UWORD16)u4_next_word << MB_MOTION_TYPE_LEN);
i4_motion_type     = fb->u2_motion_type;
}
if ((u2_mb_type & MB_FORW_OR_BACK) &&
((i4_motion_type == 0) ||
(i4_motion_type == 3) ||
(i4_motion_type == 4) ||
(i4_motion_type >= 7)))
{
i4_motion_type = 1;
}
}
{
if((u2_mb_type & MB_CODED) && fb->u2_read_dct_type)
{
ps_dec->u2_field_dct = BIT((UWORD16)u4_next_word,15);
u2_total_len += MB_DCT_TYPE_LEN;
u4_next_word = (UWORD16)LSW((UWORD16)u4_next_word << MB_DCT_TYPE_LEN);
}
}
if(u2_mb_type & MB_QUANT)
{
UWORD16 u2_quant_scale_code;
u2_quant_scale_code = BITS((UWORD16)u4_next_word,15,11);
ps_dec->u1_quant_scale = (fb->u2_q_scale_type) ?
gau1_impeg2_non_linear_quant_scale[u2_quant_scale_code] : (u2_quant_scale_code << 1);
u2_total_len += MB_QUANT_SCALE_CODE_LEN;
}
impeg2d_bit_stream_flush(ps_stream,u2_total_len);
ps_dec->u2_coded_mb    = (UWORD16)(u2_mb_type & MB_CODED);
if(u2_mb_type & MB_BIDRECT)
{
UWORD16 u2_index       = (fb->u2_motion_type);
ps_dec->u2_prev_intra_mb    = 0;
ps_dec->e_mb_pred         = BIDIRECT;
ps_dec_mb_params = &fb->ps_func_bi_direct[u2_index];
ps_dec->s_mb_type = ps_dec_mb_params->s_mb_type;
ps_dec_mb_params->pf_func_mb_params(fb);
}
else if(u2_mb_type & MB_FORW_OR_BACK)
{
UWORD16 u2_refPic      = !(u2_mb_type & MB_MV_FORW);
UWORD16 u2_index       = (fb->u2_motion_type);
ps_dec->u2_prev_intra_mb    = 0;
ps_dec->e_mb_pred         = (e_pred_direction_t)u2_refPic;
ps_dec_mb_params = &fb->ps_func_forw_or_back[u2_index];
ps_dec->s_mb_type = ps_dec_mb_params->s_mb_type;
ps_dec_mb_params->pf_func_mb_params(fb);
}
else if(u2_mb_type & MB_TYPE_INTRA)
{
ps_dec->u2_prev_intra_mb    = 1;
impeg2d_dec_intra_mb(fb);
}
else
{
ps_dec->u2_prev_intra_mb =0;
ps_dec->e_mb_pred = FORW;
ps_dec->u2_motion_type = 0;
impeg2d_dec_0mv_coded_mb(fb);
}
if((u2_mb_type & MB_TYPE_INTRA))
{
ps_dec->u2_cbp  = 0x3f;
ps_dec->u2_prev_intra_mb    = 1;
}
else
{
ps_dec->u2_prev_intra_mb  = 0;
ps_dec->u2_def_dc_pred[Y_LUMA] = 128 << fb->u2_intra_dc_precision;
ps_dec->u2_def_dc_pred[U_CHROMA] = 128 << fb->u2_intra_dc_precision;
ps_dec->u2_def_dc_pred[V_CHROMA] = 128 << fb->u2_intra_dc_precision;
if((fb->u2_coded_mb))
{
UWORD16 cbpValue;
cbpValue  = gau2_impeg2d_cbp_code[impeg2d_bit_stream_nxt(ps_stream,MB_CBP_LEN)];
ps_dec->u2_cbp  = cbpValue & 0xFF;
impeg2d_bit_stream_flush(ps_stream,(cbpValue >> 8) & 0x0FF);
}
else
{
ps_dec->u2_cbp  = 0;
}
}
}

static bool anal_fcn_data (RCore *un, const char *gi) {
	RAnalFunction *fcn = r_anal_get_fcn_in (un->anal, un->offset, -1);
	ut32 fcn_size = r_anal_function_size_from_entry (fcn);
	if (fcn) {
		int i;
		bool gap = false;
		ut64 gap_addr = UT64_MAX;
		char *bitmap = calloc (1, fcn_size);
		if (bitmap) {
			RAnalBlock *b;
			RListIter *iter;
			r_list_foreach (fcn->bbs, iter, b) {
				int f = b->addr - fcn->addr;
				int t = R_MIN (f + b->size, fcn_size);
				if (f >= 0) {
					while (f < t) {
						bitmap[f++] = 1;
					}
				}
			}
		}
		for (i = 0; i < fcn_size; i++) {
			ut64 here = fcn->addr + i;
			if (bitmap && bitmap[i]) {
				if (gap) {
					r_cons_printf ("Cd %d @ 0x%08"PFMT64x"\n", here - gap_addr, gap_addr);
					gap = false;
				}
				gap_addr = UT64_MAX;
			} else {
				if (!gap) {
					gap = true;
					gap_addr = here;
				}
			}
		}
		if (gap) {
			r_cons_printf ("Cd %d @ 0x%08"PFMT64x"\n", fcn->addr + fcn_size - gap_addr, gap_addr);
		}
		free (bitmap);
		return true;
	}
	return false;
}

