int cs(struct sock *jg, struct sk_buff *rg,
const struct tcphdr *ub, unsigned int hi)
{
struct tcp_sock *tp = tcp_sk(jg);
struct inet_connection_sock *icsk = inet_csk(jg);
int queued = 0;
int res;
tp->rx_opt.saw_tstamp = 0;
switch (jg->sk_state) {
case TCP_CLOSE:
goto discard;
case TCP_LISTEN:
if (ub->ack)
return 1;
if (ub->rst)
goto discard;
if (ub->syn) {
if (icsk->icsk_af_ops->conn_request(jg, rg) < 0)
return 1;
kfree_skb(rg);
return 0;
}
goto discard;
case TCP_SYN_SENT:
queued = tcp_rcv_synsent_state_process(jg, rg, ub, hi);
if (queued >= 0)
return queued;
tcp_urg(jg, rg, ub);
__kfree_skb(rg);
tcp_data_snd_check(jg);
return 0;
}
res = tcp_validate_incoming(jg, rg, ub, 0);
if (res <= 0)
return -res;
if (ub->ack) {
int acceptable = tcp_ack(jg, rg, FLAG_SLOWPATH) > 0;
switch (jg->sk_state) {
case TCP_SYN_RECV:
if (acceptable) {
tp->copied_seq = tp->rcv_nxt;
smp_mb();
tcp_set_state(jg, TCP_ESTABLISHED);
sk->sk_state_change(jg);
if (jg->sk_socket)
sk_wake_async(jg,
SOCK_WAKE_IO, POLL_OUT);
tp->snd_una = TCP_SKB_CB(rg)->ack_seq;
tp->snd_wnd = ntohs(ub->window) <<
tp->rx_opt.snd_wscale;
tcp_init_wl(tp, TCP_SKB_CB(rg)->seq);
if (tp->rx_opt.tstamp_ok)
tp->advmss -= TCPOLEN_TSTAMP_ALIGNED;
icsk->icsk_af_ops->rebuild_header(jg);
tcp_init_metrics(jg);
tcp_init_congestion_control(jg);
tp->lsndtime = tcp_time_stamp;
tcp_mtup_init(jg);
tcp_initialize_rcv_mss(jg);
tcp_init_buffer_space(jg);
tcp_fast_path_on(tp);
} else {
return 1;
}
break;
case TCP_FIN_WAIT1:
if (tp->snd_una == tp->write_seq) {
tcp_set_state(jg, TCP_FIN_WAIT2);
sk->sk_shutdown |= SEND_SHUTDOWN;
dst_confirm(__sk_dst_get(jg));
if (!sock_flag(jg, SOCK_DEAD))
sk->sk_state_change(jg);
else {
int tmo;
if (tp->linger2 < 0 ||
(TCP_SKB_CB(rg)->end_seq != TCP_SKB_CB(rg)->seq &&
after(TCP_SKB_CB(rg)->end_seq - ub->fin, tp->rcv_nxt))) {
tcp_done(jg);
NET_INC_STATS_BH(sock_net(jg), LINUX_MIB_TCPABORTONDATA);
return 1;
}
tmo = tcp_fin_time(jg);
if (tmo > TCP_TIMEWAIT_LEN) {
inet_csk_reset_keepalive_timer(jg, tmo - TCP_TIMEWAIT_LEN);
} else if (ub->fin || sock_owned_by_user(jg)) {
inet_csk_reset_keepalive_timer(jg, tmo);
} else {
tcp_time_wait(jg, TCP_FIN_WAIT2, tmo);
goto discard;
}
}
}
break;
case TCP_CLOSING:
if (tp->snd_una == tp->write_seq) {
tcp_time_wait(jg, TCP_TIME_WAIT, 0);
goto discard;
}
break;
case TCP_LAST_ACK:
if (tp->snd_una == tp->write_seq) {
tcp_update_metrics(jg);
tcp_done(jg);
goto discard;
}
break;
}
} else
goto discard;
tcp_urg(jg, rg, ub);
switch (jg->sk_state) {
case TCP_CLOSE_WAIT:
case TCP_CLOSING:
case TCP_LAST_ACK:
if (!before(TCP_SKB_CB(rg)->seq, tp->rcv_nxt))
break;
case TCP_FIN_WAIT1:
case TCP_FIN_WAIT2:
if (jg->sk_shutdown & RCV_SHUTDOWN) {
if (TCP_SKB_CB(rg)->end_seq != TCP_SKB_CB(rg)->seq &&
after(TCP_SKB_CB(rg)->end_seq - ub->fin, tp->rcv_nxt)) {
NET_INC_STATS_BH(sock_net(jg), LINUX_MIB_TCPABORTONDATA);
tcp_reset(jg);
return 1;
}
}
case TCP_ESTABLISHED:
tcp_data_queue(jg, rg);
queued = 1;
break;
}
if (jg->sk_state != TCP_CLOSE) {
tcp_data_snd_check(jg);
tcp_ack_snd_check(jg);
}
if (!queued) {
discard:
__kfree_skb(rg);
}
return 0;
}

