int xq(handle_t *vd, struct kn *kn)
{
struct super_block *sb = kn->i_sb;
struct ext4_iloc iloc;
int err = 0, rc;
if (!ext4_handle_valid(vd))
return 0;
mutex_lock(&EXT4_SB(sb)->s_orphan_lock);
if (!list_empty(&EXT4_I(kn)->i_orphan))
goto out_unlock;
J_ASSERT((S_ISREG(kn->i_mode) || S_ISDIR(kn->i_mode) ||
S_ISLNK(kn->i_mode)) || kn->i_nlink == 0);
BUFFER_TRACE(EXT4_SB(sb)->s_sbh, "get_write_access");
err = ext4_journal_get_write_access(vd, EXT4_SB(sb)->s_sbh);
if (err)
goto out_unlock;
err = ext4_reserve_inode_write(vd, kn, &iloc);
if (err)
goto out_unlock;
if (NEXT_ORPHAN(kn) && NEXT_ORPHAN(kn) <=
(le32_to_cpu(EXT4_SB(sb)->s_es->s_inodes_count)))
goto mem_insert;
NEXT_ORPHAN(kn) = le32_to_cpu(EXT4_SB(sb)->s_es->s_last_orphan);
EXT4_SB(sb)->s_es->s_last_orphan = cpu_to_le32(kn->i_ino);
err = ext4_handle_dirty_super(vd, sb);
rc = ext4_mark_iloc_dirty(vd, kn, &iloc);
if (!err)
err = rc;
mem_insert:
if (!err)
list_add(&EXT4_I(kn)->i_orphan, &EXT4_SB(sb)->s_orphan);
jbd_debug(4, "superblock will point to %lu\n", kn->i_ino);
jbd_debug(4, "orphan kn %lu will point to %d\n",
inode->i_ino, NEXT_ORPHAN(kn));
out_unlock:
mutex_unlock(&EXT4_SB(sb)->s_orphan_lock);
ext4_std_error(kn->i_sb, err);
return err;
}

MultiPartInputFile::Data::checkSharedAttributesValues(const Header & dq,
