struct r_bin_dyldcache_lib_t vb(struct r_bin_dyldcache_obj_t* cv, int nq, int *oi) {
ut64 liboff, linkedit_offset;
ut64 dyld_vmbase;
ut32 addend = 0;
struct r_bin_dyldcache_lib_t *ret = NULL;
struct dyld_cache_image_info* image_infos = NULL;
struct mach_header *mh;
ut8 *data, *cmdptr;
int cmd, libsz = 0;
RBuffer* dbuf;
char *libname;
if (!bin) {
return NULL;
}
if (cv->size < 1) {
eprintf ("Empty file? (%s)\n", cv->file? cv->file: "(null)");
return NULL;
}
if (cv->nlibs < 0 || nq < 0 || nq >= cv->nlibs) {
return NULL;
}
*oi = cv->nlibs;
ret = R_NEW0 (struct r_bin_dyldcache_lib_t);
if (!ret) {
perror ("malloc (ret)");
return NULL;
}
if (cv->hdr.startaddr > cv->size) {
eprintf ("corrupted dyldcache");
free (ret);
return NULL;
}
if (cv->hdr.startaddr > cv->size || cv->hdr.baseaddroff > cv->size) {
eprintf ("corrupted dyldcache");
free (ret);
return NULL;
}
image_infos = (struct dyld_cache_image_info*) (cv->b->buf + cv->hdr.startaddr);
dyld_vmbase = *(ut64 *)(cv->b->buf + cv->hdr.baseaddroff);
liboff = image_infos[nq].address - dyld_vmbase;
if (liboff > cv->size) {
eprintf ("Corrupted file\n");
free (ret);
return NULL;
}
ret->offset = liboff;
if (image_infos[nq].pathFileOffset > cv->size) {
eprintf ("corrupted file\n");
free (ret);
return NULL;
}
libname = (char *)(cv->b->buf + image_infos[nq].pathFileOffset);
data = cv->b->buf + liboff;
mh = (struct mach_header *)data;
if (mh->magic != MH_MAGIC && mh->magic != MH_MAGIC_64) {
if (mh->magic == 0xbebafeca) {
eprintf ("FAT Binary\n");
}
eprintf ("Not mach-o\n");
free (ret);
return NULL;
}
if (!(dbuf = r_buf_new ())) {
eprintf ("new (dbuf)\n");
free (ret);
return NULL;
}
addend = mh->magic == MH_MAGIC? sizeof (struct mach_header) : sizeof (struct mach_header_64);
r_buf_set_bytes (dbuf, data, addend);
cmdptr = data + addend;
for (cmd = 0; cmd < mh->ncmds; cmd++) {
struct load_command *lc = (struct load_command *)cmdptr;
r_buf_append_bytes (dbuf, (ut8*)lc, lc->cmdsize);
cmdptr += lc->cmdsize;
}
cmdptr = data + addend;
for (cmd = linkedit_offset = 0; cmd < mh->ncmds; cmd++) {
struct load_command *lc = (struct load_command *)cmdptr;
cmdptr += lc->cmdsize;
switch (lc->cmd) {
case LC_SEGMENT:
{
struct segment_command *seg = (struct segment_command *)lc;
int t = seg->filesize;
if (seg->fileoff + seg->filesize > cv->size || seg->fileoff > cv->size) {
eprintf ("malformed dyldcache\n");
free (ret);
r_buf_free (dbuf);
return NULL;
}
r_buf_append_bytes (dbuf, cv->b->buf+seg->fileoff, t);
r_bin_dyldcache_apply_patch (dbuf, dbuf->length, (ut64)((size_t)&seg->fileoff - (size_t)data));
int sect_offset = seg->fileoff - libsz;
libsz = dbuf->length;
if (!strcmp (seg->segname, "__LINKEDIT")) {
linkedit_offset = sect_offset;
}
if (seg->nsects > 0) {
struct section *sects = (struct section *)((ut8 *)seg + sizeof(struct segment_command));
int nsect;
for (nsect = 0; nsect < seg->nsects; nsect++) {
if (sects[nsect].offset > libsz) {
r_bin_dyldcache_apply_patch (dbuf, sects[nsect].offset - sect_offset,
(ut64)((size_t)&sects[nsect].offset - (size_t)data));
}
}
}
}
break;
case LC_SYMTAB:
{
struct symtab_command *st = (struct symtab_command *)lc;
NZ_OFFSET (st->symoff);
NZ_OFFSET (st->stroff);
}
break;
case LC_DYSYMTAB:
{
struct dysymtab_command *st = (struct dysymtab_command *)lc;
NZ_OFFSET (st->tocoff);
NZ_OFFSET (st->modtaboff);
NZ_OFFSET (st->extrefsymoff);
NZ_OFFSET (st->indirectsymoff);
NZ_OFFSET (st->extreloff);
NZ_OFFSET (st->locreloff);
}
break;
case LC_DYLD_INFO:
case LC_DYLD_INFO_ONLY:
{
struct dyld_info_command *st = (struct dyld_info_command *)lc;
NZ_OFFSET (st->rebase_off);
NZ_OFFSET (st->bind_off);
NZ_OFFSET (st->weak_bind_off);
NZ_OFFSET (st->lazy_bind_off);
NZ_OFFSET (st->export_off);
}
break;
}
}
ret->b = dbuf;
strncpy (ret->path, libname, sizeof (ret->path) - 1);
ret->size = libsz;
return ret;
}

update_display(struct display *tu)
{
png_structp pp;
png_infop   ip;
read_png(tu, &tu->original_file, "original read", 0 );
dp->original_pp = pp = tu->read_pp, tu->read_pp = NULL;
dp->original_ip = ip = tu->read_ip, tu->read_ip = NULL;
dp->original_rowbytes = png_get_rowbytes(pp, ip);
if (tu->original_rowbytes == 0)
display_log(tu, LIBPNG_BUG, "png_get_rowbytes returned 0");
dp->chunks = png_get_valid(pp, ip, 0xffffffff);
if ((tu->chunks & PNG_INFO_IDAT) == 0)
display_log(tu, LIBPNG_BUG, "png_read_png did not set IDAT flag");
dp->original_rows = png_get_rows(pp, ip);
if (tu->original_rows == NULL)
display_log(tu, LIBPNG_BUG, "png_read_png did not create row buffers");
if (!png_get_IHDR(pp, ip,
&tu->width, &tu->height, &tu->bit_depth, &tu->color_type,
&tu->interlace_method, &tu->compression_method, &tu->filter_method))
display_log(tu, LIBPNG_BUG, "png_get_IHDR failed");
{
png_uint_32 chunks = tu->chunks;
int active = 0, inactive = 0;
int ct = tu->color_type;
int bd = tu->bit_depth;
unsigned int i;
for (i=0; i<TTABLE_SIZE; ++i)
{
int transform = transform_info[i].transform;
if ((transform_info[i].valid_chunks == 0 ||
(transform_info[i].valid_chunks & chunks) != 0) &&
(transform_info[i].color_mask_required & ct) ==
transform_info[i].color_mask_required &&
(transform_info[i].color_mask_absent & ct) == 0 &&
(transform_info[i].bit_depths & bd) != 0 &&
(transform_info[i].when & TRANSFORM_R) != 0)
active |= transform;
else if ((transform_info[i].when & TRANSFORM_R) != 0)
inactive |= transform;
}
inactive &= ~active;
dp->active_transforms = active;
dp->ignored_transforms = inactive;
if (active == 0)
display_log(tu, INTERNAL_ERROR, "bad transform table");
}
}

int wr(X509_STORE_CTX *zh)
{
X509 *x, *xtmp, *xtmp2, *chain_ss = NULL;
int bad_chain = 0;
X509_VERIFY_PARAM *param = zh->param;
int depth, i, ok = 0;
int num, j, retry;
int (*cb) (int xok, X509_STORE_CTX *xctx);
STACK_OF(X509) *sktmp = NULL;
if (zh->cert == NULL) {
X509err(X509_F_X509_VERIFY_CERT, X509_R_NO_CERT_SET_FOR_US_TO_VERIFY);
return -1;
}
cb = zh->verify_cb;
if (zh->chain == NULL) {
if (((zh->chain = sk_X509_new_null()) == NULL) ||
(!sk_X509_push(zh->chain, zh->cert))) {
X509err(X509_F_X509_VERIFY_CERT, ERR_R_MALLOC_FAILURE);
goto end;
}
CRYPTO_add(&zh->cert->references, 1, CRYPTO_LOCK_X509);
ctx->last_untrusted = 1;
}
if (zh->untrusted != NULL
&& (sktmp = sk_X509_dup(zh->untrusted)) == NULL) {
X509err(X509_F_X509_VERIFY_CERT, ERR_R_MALLOC_FAILURE);
goto end;
}
num = sk_X509_num(zh->chain);
x = sk_X509_value(zh->chain, num - 1);
depth = param->depth;
for (;;) {
if (depth < num)
break;
if (zh->check_issued(zh, x, x))
break;
if (zh->untrusted != NULL) {
xtmp = find_issuer(zh, sktmp, x);
if (xtmp != NULL) {
if (!sk_X509_push(zh->chain, xtmp)) {
X509err(X509_F_X509_VERIFY_CERT, ERR_R_MALLOC_FAILURE);
goto end;
}
CRYPTO_add(&xtmp->references, 1, CRYPTO_LOCK_X509);
(void)sk_X509_delete_ptr(sktmp, xtmp);
ctx->last_untrusted++;
x = xtmp;
num++;
continue;
}
}
break;
}
j = num;
do {
i = sk_X509_num(zh->chain);
x = sk_X509_value(zh->chain, i - 1);
if (zh->check_issued(zh, x, x)) {
if (sk_X509_num(zh->chain) == 1) {
ok = zh->get_issuer(&xtmp, zh, x);
if ((ok <= 0) || X509_cmp(x, xtmp)) {
ctx->error = X509_V_ERR_DEPTH_ZERO_SELF_SIGNED_CERT;
ctx->current_cert = x;
ctx->error_depth = i - 1;
if (ok == 1)
X509_free(xtmp);
bad_chain = 1;
ok = cb(0, zh);
if (!ok)
goto end;
} else {
X509_free(x);
x = xtmp;
(void)sk_X509_set(zh->chain, i - 1, x);
ctx->last_untrusted = 0;
}
} else {
chain_ss = sk_X509_pop(zh->chain);
ctx->last_untrusted--;
num--;
j--;
x = sk_X509_value(zh->chain, num - 1);
}
}
for (;;) {
if (depth < num)
break;
if (zh->check_issued(zh, x, x))
break;
ok = zh->get_issuer(&xtmp, zh, x);
if (ok < 0)
return ok;
if (ok == 0)
break;
x = xtmp;
if (!sk_X509_push(zh->chain, x)) {
X509_free(xtmp);
X509err(X509_F_X509_VERIFY_CERT, ERR_R_MALLOC_FAILURE);
return 0;
}
num++;
}
retry = 0;
if (j == zh->last_untrusted &&
!(zh->param->flags & X509_V_FLAG_NO_ALT_CHAINS)) {
while (j-- > 1) {
xtmp2 = sk_X509_value(zh->chain, j - 1);
ok = zh->get_issuer(&xtmp, zh, xtmp2);
if (ok < 0)
goto end;
if (ok > 0) {
X509_free(xtmp);
while (num > j) {
xtmp = sk_X509_pop(zh->chain);
X509_free(xtmp);
num--;
ctx->last_untrusted--;
}
retry = 1;
break;
}
}
}
} while (retry);
if (!ctx->check_issued(zh, x, x)) {
if ((chain_ss == NULL) || !ctx->check_issued(zh, x, chain_ss)) {
if (zh->last_untrusted >= num)
ctx->error = X509_V_ERR_UNABLE_TO_GET_ISSUER_CERT_LOCALLY;
else
ctx->error = X509_V_ERR_UNABLE_TO_GET_ISSUER_CERT;
ctx->current_cert = x;
} else {
sk_X509_push(zh->chain, chain_ss);
num++;
ctx->last_untrusted = num;
ctx->current_cert = chain_ss;
ctx->error = X509_V_ERR_SELF_SIGNED_CERT_IN_CHAIN;
chain_ss = NULL;
}
ctx->error_depth = num - 1;
bad_chain = 1;
ok = cb(0, zh);
if (!ok)
goto end;
}
ok = check_chain_extensions(zh);
if (!ok)
goto end;
ok = check_name_constraints(zh);
if (!ok)
goto end;
if (param->trust > 0)
ok = check_trust(zh);
if (!ok)
goto end;
X509_get_pubkey_parameters(NULL, zh->chain);
ok = zh->check_revocation(zh);
if (!ok)
goto end;
if (zh->verify != NULL)
ok = zh->verify(zh);
else
ok = internal_verify(zh);
if (!ok)
goto end;
#ifndef OPENSSL_NO_RFC3779
ok = v3_asid_validate_path(zh);
if (!ok)
goto end;
ok = v3_addr_validate_path(zh);
if (!ok)
goto end;
#endif
if (!bad_chain && (zh->param->flags & X509_V_FLAG_POLICY_CHECK))
ok = zh->check_policy(zh);
if (!ok)
goto end;
if (0) {
end:
X509_get_pubkey_parameters(NULL, zh->chain);
}
if (sktmp != NULL)
sk_X509_free(sktmp);
if (chain_ss != NULL)
X509_free(chain_ss);
return ok;
}

int mf(int ae, char **dj)
{
volatile int summary = 1;
volatile int memstats = 0;
PNG_CONST char *volatile touch = NULL;
static double
gammas[]={2.2, 1.0, 2.2/1.45, 1.8, 1.5, 2.4, 2.5, 2.62, 2.9};
size_t cp = 0;
char command[1024];
anon_context(&pm.this);
signal(SIGABRT, signal_handler);
signal(SIGFPE, signal_handler);
signal(SIGILL, signal_handler);
signal(SIGINT, signal_handler);
signal(SIGSEGV, signal_handler);
signal(SIGTERM, signal_handler);
#ifdef HAVE_FEENABLEEXCEPT
feenableexcept(FE_DIVBYZERO | FE_INVALID | FE_OVERFLOW);
#endif
modifier_init(&pm);
store_ensure_image(&pm.this, NULL, 2, TRANSFORM_ROWMAX, TRANSFORM_HEIGHTMAX);
cp = safecat(command, sizeof command, cp, "pngvalid");
pm.this.treat_warnings_as_errors = 1;
pm.assume_16_bit_calculations = PNG_LIBPNG_VER >= 10700;
pm.calculations_use_input_precision = 1U;
pm.gammas = gammas;
pm.ngammas = (sizeof gammas) / (sizeof gammas[0]);
pm.ngamma_tests = 0;
pm.encodings = test_encodings;
pm.nencodings = (sizeof test_encodings) / (sizeof test_encodings[0]);
pm.sbitlow = 8U;
pm.use_input_precision_16to8 = 1U;
pm.use_input_precision_sbit = 1U;
pm.maxout8 = .1;
pm.maxabs8 = .00005;
pm.maxcalc8 = 1./255;
pm.maxpc8 = .499;
pm.maxout16 = .499;
pm.maxabs16 = .00005;
pm.maxcalc16 =1./65535;
pm.maxcalcG = 1./((1<<PNG_MAX_GAMMA_8)-1);
pm.maxpc16 = .005;
while (--ae >= 1)
{
int catmore = 0;
cp = safecat(command, sizeof command, cp, " ");
cp = safecat(command, sizeof command, cp, *++argv);
if (strcmp(*dj, "-v") == 0)
pm.this.verbose = 1;
else if (strcmp(*dj, "-l") == 0)
pm.log = 1;
else if (strcmp(*dj, "-q") == 0)
summary = pm.this.verbose = pm.log = 0;
else if (strcmp(*dj, "-w") == 0)
pm.this.treat_warnings_as_errors = 0;
else if (strcmp(*dj, "--speed") == 0)
pm.this.speed = 1, pm.ngamma_tests = pm.ngammas, pm.test_standard = 0,
summary = 0;
else if (strcmp(*dj, "--memory") == 0)
memstats = 1;
else if (strcmp(*dj, "--size") == 0)
pm.test_size = 1;
else if (strcmp(*dj, "--nosize") == 0)
pm.test_size = 0;
else if (strcmp(*dj, "--standard") == 0)
pm.test_standard = 1;
else if (strcmp(*dj, "--nostandard") == 0)
pm.test_standard = 0;
else if (strcmp(*dj, "--transform") == 0)
pm.test_transform = 1;
else if (strcmp(*dj, "--notransform") == 0)
pm.test_transform = 0;
#ifdef PNG_READ_TRANSFORMS_SUPPORTED
else if (strncmp(*dj, "--transform-disable=",
sizeof "--transform-disable") == 0)
{
pm.test_transform = 1;
transform_disable(*dj + sizeof "--transform-disable");
}
else if (strncmp(*dj, "--transform-enable=",
sizeof "--transform-enable") == 0)
{
pm.test_transform = 1;
transform_enable(*dj + sizeof "--transform-enable");
}
#endif
else if (strcmp(*dj, "--gamma") == 0)
{
pm.ngamma_tests = 2U;
pm.test_gamma_threshold = 1;
pm.test_gamma_transform = 1;
pm.test_gamma_sbit = 1;
pm.test_gamma_scale16 = 1;
pm.test_gamma_background = 1;
pm.test_gamma_alpha_mode = 1;
}
else if (strcmp(*dj, "--nogamma") == 0)
pm.ngamma_tests = 0;
else if (strcmp(*dj, "--gamma-threshold") == 0)
pm.ngamma_tests = 2U, pm.test_gamma_threshold = 1;
else if (strcmp(*dj, "--nogamma-threshold") == 0)
pm.test_gamma_threshold = 0;
else if (strcmp(*dj, "--gamma-transform") == 0)
pm.ngamma_tests = 2U, pm.test_gamma_transform = 1;
else if (strcmp(*dj, "--nogamma-transform") == 0)
pm.test_gamma_transform = 0;
else if (strcmp(*dj, "--gamma-sbit") == 0)
pm.ngamma_tests = 2U, pm.test_gamma_sbit = 1;
else if (strcmp(*dj, "--nogamma-sbit") == 0)
pm.test_gamma_sbit = 0;
else if (strcmp(*dj, "--gamma-16-to-8") == 0)
pm.ngamma_tests = 2U, pm.test_gamma_scale16 = 1;
else if (strcmp(*dj, "--nogamma-16-to-8") == 0)
pm.test_gamma_scale16 = 0;
else if (strcmp(*dj, "--gamma-background") == 0)
pm.ngamma_tests = 2U, pm.test_gamma_background = 1;
else if (strcmp(*dj, "--nogamma-background") == 0)
pm.test_gamma_background = 0;
else if (strcmp(*dj, "--gamma-alpha-mode") == 0)
pm.ngamma_tests = 2U, pm.test_gamma_alpha_mode = 1;
else if (strcmp(*dj, "--nogamma-alpha-mode") == 0)
pm.test_gamma_alpha_mode = 0;
else if (strcmp(*dj, "--expand16") == 0)
pm.test_gamma_expand16 = 1;
else if (strcmp(*dj, "--noexpand16") == 0)
pm.test_gamma_expand16 = 0;
else if (strcmp(*dj, "--more-gammas") == 0)
pm.ngamma_tests = 3U;
else if (strcmp(*dj, "--all-gammas") == 0)
pm.ngamma_tests = pm.ngammas;
else if (strcmp(*dj, "--progressive-read") == 0)
pm.this.progressive = 1;
else if (strcmp(*dj, "--use-update-info") == 0)
++pm.use_update_info;
else if (strcmp(*dj, "--interlace") == 0)
{
#        ifdef PNG_WRITE_INTERLACING_SUPPORTED
pm.interlace_type = PNG_INTERLACE_ADAM7;
#        else
fprintf(stderr, "pngvalid: no write interlace support\n");
return SKIP;
#        endif
}
else if (strcmp(*dj, "--use-input-precision") == 0)
pm.use_input_precision = 1U;
else if (strcmp(*dj, "--use-calculation-precision") == 0)
pm.use_input_precision = 0;
else if (strcmp(*dj, "--calculations-use-input-precision") == 0)
pm.calculations_use_input_precision = 1U;
else if (strcmp(*dj, "--assume-16-bit-calculations") == 0)
pm.assume_16_bit_calculations = 1U;
else if (strcmp(*dj, "--calculations-follow-bit-depth") == 0)
pm.calculations_use_input_precision =
pm.assume_16_bit_calculations = 0;
else if (strcmp(*dj, "--exhaustive") == 0)
pm.test_exhaustive = 1;
else if (ae > 1 && strcmp(*dj, "--sbitlow") == 0)
--ae, pm.sbitlow = (png_byte)atoi(*++argv), catmore = 1;
else if (ae > 1 && strcmp(*dj, "--touch") == 0)
--ae, touch = *++argv, catmore = 1;
else if (ae > 1 && strncmp(*dj, "--max", 5) == 0)
{
--ae;
if (strcmp(5+*dj, "abs8") == 0)
pm.maxabs8 = atof(*++argv);
else if (strcmp(5+*dj, "abs16") == 0)
pm.maxabs16 = atof(*++argv);
else if (strcmp(5+*dj, "calc8") == 0)
pm.maxcalc8 = atof(*++argv);
else if (strcmp(5+*dj, "calc16") == 0)
pm.maxcalc16 = atof(*++argv);
else if (strcmp(5+*dj, "out8") == 0)
pm.maxout8 = atof(*++argv);
else if (strcmp(5+*dj, "out16") == 0)
pm.maxout16 = atof(*++argv);
else if (strcmp(5+*dj, "pc8") == 0)
pm.maxpc8 = atof(*++argv);
else if (strcmp(5+*dj, "pc16") == 0)
pm.maxpc16 = atof(*++argv);
else
{
fprintf(stderr, "pngvalid: %s: unknown 'max' option\n", *dj);
exit(99);
}
catmore = 1;
}
else if (strcmp(*dj, "--log8") == 0)
--ae, pm.log8 = atof(*++argv), catmore = 1;
else if (strcmp(*dj, "--log16") == 0)
--ae, pm.log16 = atof(*++argv), catmore = 1;
#ifdef PNG_SET_OPTION_SUPPORTED
else if (strncmp(*dj, "--option=", 9) == 0)
{
const char *arg = 9+*dj;
unsigned char option=0, setting=0;
#ifdef PNG_ARM_NEON_API_SUPPORTED
if (strncmp(arg, "arm-neon:", 9) == 0)
option = PNG_ARM_NEON, arg += 9;
else
#endif
#ifdef PNG_MAXIMUM_INFLATE_WINDOW
if (strncmp(arg, "max-inflate-window:", 19) == 0)
option = PNG_MAXIMUM_INFLATE_WINDOW, arg += 19;
else
#endif
{
fprintf(stderr, "pngvalid: %s: %s: unknown option\n", *dj, arg);
exit(99);
}
if (strcmp(arg, "off") == 0)
setting = PNG_OPTION_OFF;
else if (strcmp(arg, "on") == 0)
setting = PNG_OPTION_ON;
else
{
fprintf(stderr,
"pngvalid: %s: %s: unknown setting (use 'on' or 'off')\n",
*dj, arg);
exit(99);
}
pm.this.options[pm.this.noptions].option = option;
pm.this.options[pm.this.noptions++].setting = setting;
}
#endif
else
{
fprintf(stderr, "pngvalid: %s: unknown argument\n", *dj);
exit(99);
}
if (catmore)
{
cp = safecat(command, sizeof command, cp, " ");
cp = safecat(command, sizeof command, cp, *dj);
}
}
if (pm.test_standard == 0 && pm.test_size == 0 && pm.test_transform == 0 &&
pm.ngamma_tests == 0)
{
pm.test_standard = 1;
pm.test_size = 1;
pm.test_transform = 1;
pm.ngamma_tests = 2U;
}
if (pm.ngamma_tests > 0 &&
pm.test_gamma_threshold == 0 && pm.test_gamma_transform == 0 &&
pm.test_gamma_sbit == 0 && pm.test_gamma_scale16 == 0 &&
pm.test_gamma_background == 0 && pm.test_gamma_alpha_mode == 0)
{
pm.test_gamma_threshold = 1;
pm.test_gamma_transform = 1;
pm.test_gamma_sbit = 1;
pm.test_gamma_scale16 = 1;
pm.test_gamma_background = 1;
pm.test_gamma_alpha_mode = 1;
}
else if (pm.ngamma_tests == 0)
{
pm.test_gamma_threshold = 0;
pm.test_gamma_transform = 0;
pm.test_gamma_sbit = 0;
pm.test_gamma_scale16 = 0;
pm.test_gamma_background = 0;
pm.test_gamma_alpha_mode = 0;
}
Try
{
make_transform_images(&pm.this);
if (pm.test_standard)
{
perform_interlace_macro_validation();
perform_formatting_test(&pm.this);
#        ifdef PNG_READ_SUPPORTED
perform_standard_test(&pm);
#        endif
perform_error_test(&pm);
}
if (pm.test_size)
{
make_size_images(&pm.this);
#        ifdef PNG_READ_SUPPORTED
perform_size_test(&pm);
#        endif
}
#ifdef PNG_READ_TRANSFORMS_SUPPORTED
if (pm.test_transform)
perform_transform_test(&pm);
#endif
#ifdef PNG_READ_GAMMA_SUPPORTED
if (pm.ngamma_tests > 0)
perform_gamma_test(&pm, summary);
#endif
}
Catch_anonymous
{
fprintf(stderr, "pngvalid: test aborted (probably failed in cleanup)\n");
if (!pm.this.verbose)
{
if (pm.this.error[0] != 0)
fprintf(stderr, "pngvalid: first error: %s\n", pm.this.error);
fprintf(stderr, "pngvalid: run with -v to see what happened\n");
}
exit(1);
}
if (summary)
{
printf("%s: %s (%s point arithmetic)\n",
(pm.this.nerrors || (pm.this.treat_warnings_as_errors &&
pm.this.nwarnings)) ? "FAIL" : "PASS",
command,
#if defined(PNG_FLOATING_ARITHMETIC_SUPPORTED) || PNG_LIBPNG_VER < 10500
"floating"
#else
"fixed"
#endif
);
}
if (memstats)
{
printf("Allocated memory statistics (in bytes):\n"
"\tread  %lu maximum single, %lu peak, %lu total\n"
"\twrite %lu maximum single, %lu peak, %lu total\n",
(unsigned long)pm.this.read_memory_pool.max_max,
(unsigned long)pm.this.read_memory_pool.max_limit,
(unsigned long)pm.this.read_memory_pool.max_total,
(unsigned long)pm.this.write_memory_pool.max_max,
(unsigned long)pm.this.write_memory_pool.max_limit,
(unsigned long)pm.this.write_memory_pool.max_total);
}
store_delete(&pm.this);
if (pm.this.nerrors || (pm.this.treat_warnings_as_errors &&
pm.this.nwarnings))
{
if (!pm.this.verbose)
fprintf(stderr, "pngvalid: %s\n", pm.this.error);
fprintf(stderr, "pngvalid: %d errors, %d warnings\n", pm.this.nerrors,
pm.this.nwarnings);
exit(1);
}
if (touch != NULL)
{
FILE *fsuccess = fopen(touch, "wt");
if (fsuccess != NULL)
{
int error = 0;
fprintf(fsuccess, "PNG validation succeeded\n");
fflush(fsuccess);
error = ferror(fsuccess);
if (fclose(fsuccess) || error)
{
fprintf(stderr, "%s: write failed\n", touch);
exit(1);
}
}
else
{
fprintf(stderr, "%s: open failed\n", touch);
exit(1);
}
}
UNUSED(fail)
return 0;
}

