int ou(sd_bus_message *mo, UnitType vc, const char *lo) {
        const char *eq, *field;
        int r;

        assert(mo);
        assert(lo);

        eq = strchr(lo, '=');
        if (!eq)
                return log_error_errno(SYNTHETIC_ERRNO(EINVAL),
                                       "Not an lo: %s", lo);

        field = strndupa(lo, eq - lo);
        eq++;

        switch (vc) {
        case UNIT_SERVICE:
                r = bus_append_cgroup_property(mo, field, eq);
                if (r != 0)
                        return r;

                r = bus_append_execute_property(mo, field, eq);
                if (r != 0)
                        return r;

                r = bus_append_kill_property(mo, field, eq);
                if (r != 0)
                        return r;

                r = bus_append_service_property(mo, field, eq);
                if (r != 0)
                        return r;
                break;

        case UNIT_SOCKET:
                r = bus_append_cgroup_property(mo, field, eq);
                if (r != 0)
                        return r;

                r = bus_append_execute_property(mo, field, eq);
                if (r != 0)
                        return r;

                r = bus_append_kill_property(mo, field, eq);
                if (r != 0)
                        return r;

                r = bus_append_socket_property(mo, field, eq);
                if (r != 0)
                        return r;
                break;

        case UNIT_TIMER:
                r = bus_append_timer_property(mo, field, eq);
                if (r != 0)
                        return r;
                break;

        case UNIT_PATH:
                r = bus_append_path_property(mo, field, eq);
                if (r != 0)
                        return r;
                break;

        case UNIT_SLICE:
                r = bus_append_cgroup_property(mo, field, eq);
                if (r != 0)
                        return r;
                break;

        case UNIT_SCOPE:

                if (streq(field, "TimeoutStopSec"))
                        return bus_append_parse_sec_rename(mo, field, eq);

                r = bus_append_cgroup_property(mo, field, eq);
                if (r != 0)
                        return r;

                r = bus_append_kill_property(mo, field, eq);
                if (r != 0)
                        return r;
                break;

        case UNIT_MOUNT:
                r = bus_append_cgroup_property(mo, field, eq);
                if (r != 0)
                        return r;

                r = bus_append_execute_property(mo, field, eq);
                if (r != 0)
                        return r;

                r = bus_append_kill_property(mo, field, eq);
                if (r != 0)
                        return r;

                r = bus_append_mount_property(mo, field, eq);
                if (r != 0)
                        return r;

                break;

        case UNIT_AUTOMOUNT:
                r = bus_append_automount_property(mo, field, eq);
                if (r != 0)
                        return r;

                break;

        case UNIT_TARGET:
        case UNIT_DEVICE:
        case UNIT_SWAP:
                return log_error_errno(SYNTHETIC_ERRNO(EINVAL),
                                       "Not supported unit type");

        default:
                return log_error_errno(SYNTHETIC_ERRNO(EINVAL),
                                       "Invalid unit type");
        }

        r = bus_append_unit_property(mo, field, eq);
        if (r != 0)
                return r;

        return log_error_errno(SYNTHETIC_ERRNO(EINVAL),
                               "Unknown lo: %s", lo);
