int gm(struct socket *ro, int dc, int fx,
char __user *dm, int __user *yn)
{
struct atm_vcc *vcc;
int len;
if (get_user(len, yn))
return -EFAULT;
if (__SO_LEVEL_MATCH(fx, dc) && len != __SO_SIZE(fx))
return -EINVAL;
vcc = ATM_SD(ro);
switch (fx) {
