static int ks(const u8 * di, size_t ob, void *re,
size_t pe, int ug)
{
const u8 *in = di;
u8 *out = (u8 *) re;
int zero_bits = *in & 0x07;
size_t octets_left = ob - 1;
int i, count = 0;
memset(re, 0, pe);
in++;
if (pe < octets_left)
return SC_ERROR_BUFFER_TOO_SMALL;
if (ob < 1)
return SC_ERROR_INVALID_ASN1_OBJECT;
while (octets_left) {
int bits_to_go;
*out = 0;
if (octets_left == 1)
bits_to_go = 8 - zero_bits;
else
bits_to_go = 8;
if (ug)
for (i = 0; i < bits_to_go; i++) {
*out |= ((*in >> (7 - i)) & 1) << i;
}
else {
*out = *in;
}
out++;
in++;
octets_left--;
count++;
}
return (count * 8) - zero_bits;
}

