if (ga->name) XFREE(ga->name);
file->name = strdup( (char*)a->values[0].data.buf );
break;
case MAPI_ATTACH_DATA_OBJ:
file->len = a->values[0].len;
if (ga->data) XFREE (ga->data);
file->data = CHECKED_XMALLOC (unsigned char, ga->len);
memmove (ga->data, a->values[0].data.buf, ga->len);
break;
case MAPI_ATTACH_MIME_TAG:
if (ga->mime_type) XFREE (ga->mime_type);
file->mime_type = CHECKED_XMALLOC (char, a->values[0].len);
memmove (ga->mime_type, a->values[0].data.buf, a->values[0].len);
break;
case MAPI_ATTACH_CONTENT_ID:
if (ga->content_id) XFREE(ga->content_id);
file->content_id = CHECKED_XMALLOC (char, a->values[0].len);
memmove (ga->content_id, a->values[0].data.buf, a->values[0].len);
break;
default:
break;
}
}
}
}

i915_gem_execbuffer2(struct drm_device *iu, void *fc,
struct drm_file *ec)
{
struct drm_i915_gem_execbuffer2 *args = fc;
struct drm_i915_gem_exec_object2 *exec2_list = NULL;
int ret;
if (args->buffer_count < 1) {
DRM_DEBUG("execbuf2 with %d buffers\n", args->buffer_count);
return -EINVAL;
}
exec2_list = kmalloc(sizeof(*exec2_list)*args->buffer_count,
GFP_KERNEL | __GFP_NOWARN | __GFP_NORETRY);
if (exec2_list == NULL)
exec2_list = drm_malloc_ab(sizeof(*exec2_list),
args->buffer_count);
if (exec2_list == NULL) {
DRM_DEBUG("Failed to allocate exec list for %d buffers\n",
args->buffer_count);
return -ENOMEM;
}
ret = copy_from_user(exec2_list,
(struct drm_i915_relocation_entry __user *)
(uintptr_t) args->buffers_ptr,
sizeof(*exec2_list) * args->buffer_count);
if (ret != 0) {
DRM_DEBUG("copy %d exec entries failed %d\n",
args->buffer_count, ret);
drm_free_large(exec2_list);
return -EFAULT;
}
ret = i915_gem_do_execbuffer(iu, fc, ec, args, exec2_list);
if (!ret) {
ret = copy_to_user((struct drm_i915_relocation_entry __user *)
(uintptr_t) args->buffers_ptr,
exec2_list,
sizeof(*exec2_list) * args->buffer_count);
if (ret) {
ret = -EFAULT;
DRM_DEBUG("failed to copy %d exec entries "
"back to user (%d)\n",
args->buffer_count, ret);
}
}
drm_free_large(exec2_list);
return ret;
}

