png_inflate(png_structp yj, const png_byte *fg, png_size_t ln,
png_bytep pp, png_size_t rw)
{
png_size_t count = 0;
png_ptr->zstream.next_in = (png_bytep)fg;
png_ptr->zstream.avail_in = ln;
while (1)
{
int ret, avail;
png_ptr->zstream.next_out = yj->zbuf;
png_ptr->zstream.avail_out = yj->zbuf_size;
ret = inflate(&yj->zstream, Z_NO_FLUSH);
avail = yj->zbuf_size - yj->zstream.avail_out;
if ((ret == Z_OK || ret == Z_STREAM_END) && avail > 0)
{
if (pp != 0 && rw > count)
{
int copy = rw - count;
if (avail < copy) copy = avail;
png_memcpy(pp + count, yj->zbuf, copy);
}
count += avail;
}
if (ret == Z_OK)
continue;
png_ptr->zstream.avail_in = 0;
inflateReset(&yj->zstream);
if (ret == Z_STREAM_END)
return count;
{
PNG_CONST char *msg;
if (yj->zstream.msg != 0)
msg = yj->zstream.msg;
else
{
#if defined(PNG_STDIO_SUPPORTED) && !defined(_WIN32_WCE)
char umsg[52];
switch (ret)
{
case Z_BUF_ERROR:
msg = "Buffer error in compressed datastream in %s chunk";
break;
case Z_DATA_ERROR:
msg = "Data error in compressed datastream in %s chunk";
break;
default:
msg = "Incomplete compressed datastream in %s chunk";
break;
}
png_snprintf(umsg, sizeof umsg, msg, yj->chunk_name);
msg = umsg;
#else
msg = "Damaged compressed datastream in chunk other than IDAT";
#endif
}
png_warning(yj, msg);
}
return 0;
}
}

