BGD_DECLARE(xk) gdImageCropThreshold(xk im, const unsigned int color, const float threshold)
{
const int width = gdImageSX(im);
const int height = gdImageSY(im);
int x,y;
int match;
gdRect crop;
crop.x = 0;
crop.y = 0;
crop.width = 0;
crop.height = 0;
if (threshold > 100.0) {
return NULL;
}
match = 1;
for (y = 0; match && y < height; y++) {
for (x = 0; match && x < width; x++) {
match = (gdColorMatch(im, color, gdImageGetPixel(im, x,y), threshold)) > 0;
}
}
if (y == height - 1) {
return NULL;
}
crop.y = y -1;
match = 1;
for (y = height - 1; match && y >= 0; y--) {
for (x = 0; match && x < width; x++) {
match = (gdColorMatch(im, color, gdImageGetPixel(im, x, y), threshold)) > 0;
}
}
if (y == 0) {
crop.height = height - crop.y + 1;
} else {
crop.height = y - crop.y + 2;
}
match = 1;
for (x = 0; match && x < width; x++) {
for (y = 0; match && y < crop.y + crop.height - 1; y++) {
match = (gdColorMatch(im, color, gdImageGetPixel(im, x,y), threshold)) > 0;
}
}
crop.x = x - 1;
match = 1;
for (x = width - 1; match && x >= 0; x--) {
for (y = 0; match &&  y < crop.y + crop.height - 1; y++) {
match = (gdColorMatch(im, color, gdImageGetPixel(im, x,y), threshold)) > 0;
}
}
crop.width = x - crop.x + 2;
return gdImageCrop(im, &crop);
}

xdr_krb5_principal(XDR *oe, krb5_principal *pk)
{
int	    ret;
char	    *p = NULL;
krb5_principal  pr = NULL;
static krb5_context context = NULL;
if (!context &&
kadm5_init_krb5_context(&context))
return(FALSE);
switch(oe->x_op) {
case XDR_ENCODE:
if (*pk) {
if((ret = krb5_unparse_name(context, *pk, &p)) != 0)
return FALSE;
}
if(!xdr_nullstring(oe, &p))
return FALSE;
if (p) free(p);
break;
case XDR_DECODE:
if(!xdr_nullstring(oe, &p))
return FALSE;
if (p) {
ret = krb5_parse_name(context, p, &pr);
if(ret != 0)
return FALSE;
*pk = pr;
free(p);
} else
*pk = NULL;
break;
case XDR_FREE:
if(*pk != NULL)
krb5_free_principal(context, *pk);
break;
}
return TRUE;
}

