}

parse_wbxml_attribute_list_defined (proto_tree *qs, tvbuff_t *zb,
guint32 vj, guint32 ng, guint8 hy, guint8 *or,
const wbxml_decoding *md)
{
guint32     tvb_len = tvb_reported_length (zb);
guint32     off     = vj;
guint32     len;
guint       str_len;
guint32     ent;
guint32     idx;
guint8      peek;
guint8      attr_save_known   = 0;
const char *attr_save_literal = NULL;
DebugLog(("parse_wbxml_attr_defined (hy = %u, vj = %u)\n",
level, vj));
while (off < tvb_len) {
peek = tvb_get_guint8 (zb, off);
DebugLog(("ATTR: (top of while) hy = %3u, peek = 0x%02X, "
"off = %u, tvb_len = %u\n", hy, peek, off, tvb_len));
if ((peek & 0x3F) < 5) switch (peek) {
case 0x00:
*or = tvb_get_guint8 (zb, off+1);
proto_tree_add_text (qs, zb, off, 2,
"      |  Attr | A -->%3d "
"| SWITCH_PAGE (Attr code page)    |",
*or);
off += 2;
break;
case 0x01:
off++;
DebugLog(("ATTR: hy = %u, Return: len = %u\n",
level, off - vj));
return (off - vj);
case 0x02:
ent = tvb_get_guintvar (zb, off+1, &len);
proto_tree_add_text (qs, zb, off, 1+len,
"  %3d |  Attr | A %3d    "
"| ENTITY                          "
"|     %s'&#%u;'",
level, *or, Indent (hy), ent);
off += 1+len;
break;
case 0x03:
len = tvb_strsize (zb, off+1);
proto_tree_add_text (qs, zb, off, 1+len,
"  %3d |  Attr | A %3d    "
"| STR_I (Inline string)           "
"|     %s\'%s\'",
level, *or, Indent (hy),
tvb_format_text (zb, off+1, len-1));
off += 1+len;
break;
case 0x04:
idx = tvb_get_guintvar (zb, off+1, &len);
str_len = tvb_strsize (zb, str_tbl+idx);
attr_save_known = 0;
attr_save_literal = tvb_format_text (zb,
str_tbl+idx, str_len-1);
proto_tree_add_text (qs, zb, off, 1+len,
"  %3d |  Attr | A %3d    "
"| LITERAL (Literal Attribute)     "
"|   %s<%s />",
level, *or, Indent (hy),
attr_save_literal);
off += 1+len;
break;
case 0x40:
case 0x41:
case 0x42:
len = tvb_strsize (zb, off+1);
proto_tree_add_text (qs, zb, off, 1+len,
"  %3d |  Attr | A %3d    "
"| EXT_I_%1x    (Extension Token)    "
"|     %s(%s: \'%s\')",
level, *or, peek & 0x0f, Indent (hy),
map_token (md->global, 0, peek),
tvb_format_text (zb, off+1, len-1));
off += 1+len;
break;
case 0x80:
case 0x81:
case 0x82:
idx = tvb_get_guintvar (zb, off+1, &len);
{   char *s;
if (md->ext_t[peek & 0x03])
s = (md->ext_t[peek & 0x03])(zb, idx, ng);
else
s = wmem_strdup_printf(wmem_packet_scope(), "EXT_T_%1x (%s)", peek & 0x03,
map_token (md->global, 0, peek));
proto_tree_add_text (qs, zb, off, 1+len,
"  %3d | Tag   | T %3d    "
"| EXT_T_%1x    (Extension Token)    "
"| %s%s)",
level, *or, peek & 0x0f, Indent (hy),
s);
}
off += 1+len;
break;
case 0x83:
idx = tvb_get_guintvar (zb, off+1, &len);
str_len = tvb_strsize (zb, str_tbl+idx);
proto_tree_add_text (qs, zb, off, 1+len,
"  %3d |  Attr | A %3d    "
"| STR_T (Tableref string)         "
"|     %s\'%s\'",
level, *or, Indent (hy),
tvb_format_text (zb, str_tbl+idx, str_len-1));
off += 1+len;
break;
case 0xC0:
case 0xC1:
case 0xC2:
proto_tree_add_text (qs, zb, off, 1,
"  %3d |  Attr | A %3d    "
"| EXT_%1x      (Extension Token)    "
"|     %s(%s)",
level, *or, peek & 0x0f, Indent (hy),
map_token (md->global, 0, peek));
off++;
break;
case 0xC3:
if (tvb_get_guint8 (zb, 0)) {
char *str;
if (attr_save_known) {
if (md->opaque_binary_attr) {
str = md->opaque_binary_attr(zb, off + 1,
attr_save_known, *or, &len);
} else {
str = default_opaque_binary_attr(zb, off + 1,
attr_save_known, *or, &len);
}
} else {
if (md->opaque_literal_tag) {
str = md->opaque_literal_attr(zb, off + 1,
attr_save_literal, *or, &len);
} else {
str = default_opaque_literal_attr(zb, off + 1,
attr_save_literal, *or, &len);
}
}
proto_tree_add_text (qs, zb, off, 1 + len,
"  %3d |  Attr | A %3d    "
"| OPAQUE (Opaque data)            "
"|       %s%s",
level, *or, Indent (hy), str);
off += 1 + len;
} else {
proto_tree_add_text (qs, zb, off, 1,
"  %3d |  Attr | A %3d    "
"| RESERVED_2     (Invalid Token!) "
"| WBXML 1.0 parsing stops here.",
level, *or);
off = tvb_len;
DebugLog(("ATTR: hy = %u, Return: len = %u\n",
level, off - vj));
return (off - vj);
}
break;
default:
proto_tree_add_text (qs, zb, off, 1,
"  %3d |  Attr | A %3d    "
"| %-10s     (Invalid Token!) "
"| WBXML parsing stops here.",
level, *or,
val_to_str_ext (peek, &vals_wbxml1x_global_tokens_ext, "(unknown 0x%x)"));
off = tvb_len;
break;
} else {
if (peek & 0x80) {
proto_tree_add_text (qs, zb, off, 1,
"  %3d |  Attr | A %3d    "
"|   Known attrValue 0x%02X          "
"|       %s%s",
level, *or, peek & 0x7f, Indent (hy),
map_token (md->attrValue, *or, peek));
off++;
} else {
attr_save_known = peek & 0x7f;
proto_tree_add_text (qs, zb, off, 1,
"  %3d |  Attr | A %3d    "
"|   Known attrStart 0x%02X          "
"|   %s%s",
level, *or, attr_save_known, Indent (hy),
map_token (md->attrStart, *or, peek));
off++;
}
}
}
DebugLog(("ATTR: hy = %u, Return: len = %u (end of function body)\n",
level, off - vj));
return (off - vj);
}

